#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    float noise_factor;  // Simulated noise factor for each UE
} UE_NOISE_CONTEXT;

// Function to initialize and populate the UEs array
void initialize_and_populate_ue(NFAPI_MESSAGE_PDU_T *ue_array, int num_ues) {
    if (ue_array == NULL || num_ues <= 0) return;

    UE_NOISE_CONTEXT *noise_context = malloc(num_ues * sizeof(UE_NOISE_CONTEXT));
    if (!noise_context) return;  // Handle memory allocation failure

    for (int i = 0; i < num_ues; ++i) {
        ue_array[i].RX_UE_INFORMATION_TAG = i + 1;  // Example: Unique tag
        ue_array[i].RNTI = rand() % 10000;  // Random RNTI

        noise_context[i].noise_factor = (float)(rand() % 100) / 10.0f;  // Simulated noise factor
    }

    for (int i = 0; i < num_ues; ++i) {
        int CRC_INDICATION_REL8_TAG = rand() % 2;
        float SNR_INDICATION_REL8_TAG = (rand() % 100) - noise_context[i].noise_factor;

        // Populate additional data based on simulated conditions
        printf("UE %d: RNTI=%d, RX_TAG=%d, CRC=%d, SNR=%.2f\n",
               i + 1,
               ue_array[i].RNTI,
               ue_array[i].RX_UE_INFORMATION_TAG,
               CRC_INDICATION_REL8_TAG,
               SNR_INDICATION_REL8_TAG);
    }

    free(noise_context);  // Release the noise context memory
}

int main() {
    const int num_ues = 1000;  // Example number of UEs
    NFAPI_MESSAGE_PDU_T *ue_array = malloc(num_ues * sizeof(NFAPI_MESSAGE_PDU_T));

    if (ue_array) {
        initialize_and_populate_ue(ue_array, num_ues);
        free(ue_array);  // Clean up allocated memory for UE array
    }

    return 0;
}
