#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct Node {
    long offset;
    struct Node* next;
} OffsetNode;

record* initialize_records(int num_records, double min_value, double max_value) {
    if (num_records <= 0) return NULL;

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Estimate initial size for hash table to store offsets
    int hash_table_size = num_records * 2;
    OffsetNode** hash_table = calloc(hash_table_size, sizeof(OffsetNode*));
    if (!hash_table) return NULL;

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        free(hash_table);
        return NULL;
    }

    int count = 0;
    while (count < num_records) {
        long new_offset = rand() % (1000000 - 1) + 1; // Offset greater than zero
        int hash_index = new_offset % hash_table_size;

        // Check for uniqueness of offset
        OffsetNode* current = hash_table[hash_index];
        while (current) {
            if (current->offset == new_offset) break;
            current = current->next;
        }

        // If unique, add to records and hash table
        if (!current) {
            records[count].offset = new_offset;
            records[count].key = count;  // or any other logic for key assignment
            records[count].value = (double)(rand() % ((int)(max_value * 1000) - (int)(min_value * 1000))) / 1000.0 + min_value;

            OffsetNode* new_node = malloc(sizeof(OffsetNode));
            if (!new_node) {
                for (int i = 0; i < count; ++i) free(records[i].offset); // Clean up
                free(hash_table);
                free(records);
                return NULL;
            }
            new_node->offset = new_offset;
            new_node->next = hash_table[hash_index];
            hash_table[hash_index] = new_node;

            count++;
        }
    }

    // Free the hash table
    for (int i = 0; i < hash_table_size; ++i) {
        OffsetNode* current = hash_table[i];
        while (current) {
            OffsetNode* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(hash_table);

    return records;
}

void free_records(record* records, int num_records) {
    if (!records) return;
    // No need to free individual offsets as they are part of the structure
    free(records);
}
