#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024

void print_usage(const char *program_name) {
    printf("Usage: %s [options] file1 [file2 ...]\n", program_name);
    printf("Options:\n");
    printf("  -h, --help        Display this help and exit\n");
    printf("  -p, --pattern     Specify the regex pattern to match (default: email)\n");
    printf("  -o, --output      Specify an output file for results\n");
    printf("  -t, --text        Process files as text (default)\n");
    printf("  -b, --binary      Process files as binary\n");
    printf("  -m, --manpage     Produce manpage output\n");
    printf("  -q, --quiet       Suppress all output except errors\n");
}

void process_files(const char *pattern, FILE **input_files, int num_files,
                   const char *output_file, bool text_mode, bool quiet) {
    regex_t regex;
    regmatch_t match[1];
    if (regcomp(&regex, pattern, REG_EXTENDED | REG_NOSUB)) {
        fprintf(stderr, "Could not compile regex\n");
        exit(1);
    }

    FILE *output = output_file ? fopen(output_file, "w") : stdout;

    for (int i = 0; i < num_files; ++i) {
        char buffer[MAX_LINE_LENGTH];
        while (fgets(buffer, sizeof(buffer), input_files[i])) {
            if (!text_mode && regexec(&regex, buffer, 1, match, 0)) continue;
            fprintf(output, "%s", buffer);
        }
    }

    fclose(output);
    regfree(&regex);
}

int main(int argc, char *argv[]) {
    bool text_mode = true;
    bool quiet = false;
    const char *pattern = "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}";
    const char *output_file = NULL;

    int opt;
    while ((opt = getopt(argc, argv, "hp:o:tbmq")) != -1) {
        switch (opt) {
            case 'h':
                print_usage(argv[0]);
                return 0;
            case 'p':
                pattern = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 't':
                text_mode = true;
                break;
            case 'b':
                text_mode = false;
                break;
            case 'q':
                quiet = true;
                break;
            default:
                print_usage(argv[0]);
                return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "No input files specified.\n");
        print_usage(argv[0]);
        return 1;
    }

    FILE **input_files = malloc((argc - optind) * sizeof(FILE *));
    for (int i = optind; i < argc; ++i) {
        if (!text_mode && !(input_files[i - optind] = fopen(argv[i], "rb"))) {
            fprintf(stderr, "Error opening file: %s\n", argv[i]);
            return 1;
        } else if (text_mode && !(input_files[i - optind] = fopen(argv[i], "r"))) {
            fprintf(stderr, "Error opening file: %s\n", argv[i]);
            return 1;
        }
    }

    process_files(pattern, input_files, argc - optind, output_file, text_mode, quiet);

    for (int i = 0; i < argc - optind; ++i) {
        fclose(input_files[i]);
    }
    free(input_files);

    return 0;
}
