#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_IP_LENGTH 16
#define DNS_TIMEOUT 5
#define MAX_CONCURRENT_REQUESTS 10

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        printf("Not enough memory\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

int resolve_dns(const char *hostname, u_char ip_address[MAX_IP_LENGTH]) {
    struct addrinfo hints, *res, *p;
    int err;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS resolution error: %s\n", gai_strerror(err));
        return err;
    }

    for(p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), (char *)ip_address, MAX_IP_LENGTH);
        break;
    }

    freeaddrinfo(res);

    return 0;
}

void process_log_data(const char *data) {
    char *line = strtok((char *)data, "\n");

    while(line != NULL) {
        char *fields[10];
        int field_count = 0;

        char *token = strtok(line, ",");
        while(token != NULL && field_count < 10) {
            fields[field_count++] = token;
            token = strtok(NULL, ",");
        }

        if(field_count >= 2) {
            double last1 = atof(fields[field_count - 1]);
            double last2 = atof(fields[field_count - 2]);
            double average = (last1 + last2) / 2.0;

            for(int i = 0; i < field_count; ++i) {
                printf("%s", fields[i]);
                if(i < field_count - 1 || i == field_count - 2)
                    printf(",");
            }
            printf("%f\n", average);
        }

        line = strtok(NULL, "\n");
    }
}

void fetch_log_file(const char *url) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if(curl) {
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, DNS_TIMEOUT);

        res = curl_easy_perform(curl);

        if(res == CURLE_OK) {
            process_log_data(chunk.memory);
        } else {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        free(chunk.memory);
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if(argc != 2) {
        printf("Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    u_char ip_address[MAX_IP_LENGTH];
    int dns_result = resolve_dns(argv[1], ip_address);

    if(dns_result == 0) {
        printf("Resolved IP address: %s\n", (char *)ip_address);

        const char *log_file_url = "http://external-server.com/logfile.log";
        fetch_log_file(log_file_url);
    } else {
        fprintf(stderr, "Failed to resolve DNS for hostname: %s\n", argv[1]);
    }

    return EXIT_SUCCESS;
}
```

### Key Points:
- **DNS Resolution:** The `resolve_dns` function resolves the given hostname and returns its IPv4 address.
- **REST API Call:** Uses libcurl to fetch a log file from an external server. Handles memory allocation dynamically as the data is received.
- **Log Processing:** Parses each line of the log, calculates the average of the last two fields, and prints it in CSV format.
- **Error Handling:** Provides meaningful error messages for DNS resolution failures and network errors.
- **Resource Management:** Manages memory allocation and cleanup to handle varying line lengths and large files efficiently.']

