#include <stdio.h>
#include <stdlib.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB
#define DEFAULT_MIN_VALUE -1000
#define DEFAULT_MAX_VALUE 1000

typedef struct {
    int *array;
    size_t size;
    size_t capacity;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->size = 0;
    da->capacity = initial_capacity;
    da->array = (int *)malloc(initial_capacity * sizeof(int));
}

void free_dynamic_array(DynamicArray *da) {
    if (da->array != NULL) {
        free(da->array);
        da->array = NULL;
    }
    da->size = 0;
    da->capacity = 0;
}

int expand_dynamic_array(DynamicArray *da, size_t new_capacity) {
    int *new_array = (int *)realloc(da->array, new_capacity * sizeof(int));
    if (!new_array) {
        return -1; // Memory allocation failed
    }
    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

void process_input(DynamicArray *da, int min_value, int max_value) {
    int number;
    long memory_used = 0;
    size_t initial_capacity = 1024;

    init_dynamic_array(da, initial_capacity);
    size_t index = 0;

    while (scanf("%d", &number) == 1) {
        if (index >= da->capacity) {
            size_t new_capacity = da->capacity * 2;
            if ((long)new_capacity * sizeof(int) > MAX_MEMORY_USAGE - memory_used) {
                fprintf(stderr, "Memory limit exceeded.\n");
                break;
            }
            if (expand_dynamic_array(da, new_capacity) == -1) {
                fprintf(stderr, "Failed to allocate more memory.\n");
                break;
            }
        }

        if (number >= min_value && number <= max_value) {
            da->array[index++] = number;
            memory_used += sizeof(int);
        }
    }

    free_dynamic_array(da); // Free any extra allocated space

    if (da->size == 0) {
        printf("No valid integers found.\n");
        return;
    }

    int max_value_in_list = da->array[0];
    size_t indices_of_max = index ? sizeof(size_t) * da->size : 0;
    size_t *indices_array = (size_t *)malloc(indices_of_max);

    if (!indices_array) {
        fprintf(stderr, "Failed to allocate memory for indices.\n");
        return;
    }

    size_t count_indices = 0;

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i] > max_value_in_list) {
            max_value_in_list = da->array[i];
            count_indices = 1;
            indices_array[0] = i;
        } else if (da->array[i] == max_value_in_list) {
            if (count_indices * sizeof(size_t) < indices_of_max) {
                indices_array[count_indices++] = i;
            }
        }
    }

    printf("Largest integer(s): %d\n", max_value_in_list);
    for (size_t j = 0; j < count_indices; ++j) {
        printf("Index: %zu\n", indices_array[j]);
    }

    free(indices_array);
}

int main() {
    DynamicArray da;
    int min_value = DEFAULT_MIN_VALUE, max_value = DEFAULT_MAX_VALUE;

    // Optionally, configure the range from user input or another source
    printf("Enter minimum value for filtering (default %d): ", DEFAULT_MIN_VALUE);
    if (scanf("%d", &min_value) != 1) {
        fprintf(stderr, "Invalid input format.\n");
        return EXIT_FAILURE;
    }

    printf("Enter maximum value for filtering (default %d): ", DEFAULT_MAX_VALUE);
    if (scanf("%d", &max_value) != 1) {
        fprintf(stderr, "Invalid input format.\n");
        return EXIT_FAILURE;
    }

    process_input(&da, min_value, max_value);

    return EXIT_SUCCESS;
}
