#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define LOG_BUFFER_SIZE 1024
#define MAX_LOG_FILE_SIZE (10 * 1024 * 1024) // 10 MB
#define NUM_BACKUP_FILES 5

typedef enum {
    INFO,
    WARNING,
    ERROR
} LogLevel;

typedef struct LogBuffer {
    char buffer[LOG_BUFFER_SIZE];
    size_t length;
    pthread_mutex_t mutex;
} LogBuffer;

thread_local LogBuffer logBuffer = { .length = 0 };

pthread_once_t init_done = PTHREAD_ONCE_INIT;
pthread_rwlock_t file_lock = PTHREAD_RWLOCK_INITIALIZER;
FILE *logFile = NULL;
size_t currentFileSize = 0;
char logFileName[256] = "server.log";

static void initializeLogFile() {
    pthread_mutex_lock(&fileLock);
    if (!logFile) {
        snprintf(logFileName, sizeof(logFileName), "server_%ld.log", time(NULL));
        logFile = fopen(logFileName, "a");
        currentFileSize = 0;
    }
    pthread_mutex_unlock(&fileLock);
}

static void rotateLogFile() {
    pthread_mutex_lock(&fileLock);
    if (currentFileSize >= MAX_LOG_FILE_SIZE) {
        fclose(logFile);
        for (int i = NUM_BACKUP_FILES - 1; i > 0; --i) {
            char src[256], dst[256];
            snprintf(src, sizeof(src), "%s.%d", logFileName, i - 1);
            snprintf(dst, sizeof(dst), "%s.%d", logFileName, i);
            rename(src, dst);
        }
        snprintf(logFileName, sizeof(logFileName), "server_%ld.log.0", time(NULL));
        logFile = fopen(logFileName, "w");
        currentFileSize = 0;
    }
    pthread_mutex_unlock(&fileLock);
}

static void flushBufferToFile() {
    pthread_mutex_lock(&logBuffer.mutex);
    if (logBuffer.length > 0) {
        initializeLogFile();
        rotateLogFile();
        fwrite(logBuffer.buffer, 1, logBuffer.length, logFile);
        currentFileSize += logBuffer.length;
        logBuffer.length = 0;
        fflush(logFile);
    }
    pthread_mutex_unlock(&logBuffer.mutex);
}

static void appendLog(LogLevel level, const char *message) {
    const char *levelStr[] = { "INFO", "WARNING", "ERROR" };
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    size_t messageLength = snprintf(NULL, 0, "[%s] [%s] %s\n", levelStr[level], timestamp, message);
    if (messageLength >= LOG_BUFFER_SIZE - logBuffer.length) {
        flushBufferToFile();
    }

    pthread_mutex_lock(&logBuffer.mutex);
    strncat(logBuffer.buffer, "[INFO] [", LOG_BUFFER_SIZE - logBuffer.length);
    strncat(logBuffer.buffer, levelStr[level], LOG_BUFFER_SIZE - logBuffer.length);
    strncat(logBuffer.buffer, "] ", LOG_BUFFER_SIZE - logBuffer.length);
    strncat(logBuffer.buffer, timestamp, LOG_BUFFER_SIZE - logBuffer.length);
    strncat(logBuffer.buffer, " ", LOG_BUFFER_SIZE - logBuffer.length);
    strncat(logBuffer.buffer, message, LOG_BUFFER_SIZE - logBuffer.length);
    strncat(logBuffer.buffer, "\n", LOG_BUFFER_SIZE - logBuffer.length);

    logBuffer.length += messageLength;
    pthread_mutex_unlock(&logBuffer.mutex);
}

void logMessage(LogLevel level, const char *message) {
    appendLog(level, message);
}

void flushAllBuffers() {
    initializeLogFile();
    pthread_rwlock_wrlock(&fileLock);
    if (logFile) {
        flushBufferToFile();
        for (int i = 0; i < NUM_THREADS; ++i) { // Assume NUM_THREADS is defined
            // Simulate flushing thread-local buffers
            LogBuffer *threadLocalBuffer = getThreadLocalLogBuffer(i); // Hypothetical function
            pthread_mutex_lock(&threadLocalBuffer->mutex);
            if (threadLocalBuffer->length > 0) {
                fwrite(threadLocalBuffer->buffer, 1, threadLocalBuffer->length, logFile);
                currentFileSize += threadLocalBuffer->length;
                threadLocalBuffer->length = 0;
            }
            pthread_mutex_unlock(&threadLocalBuffer->mutex);
        }
        fflush(logFile);
    }
    pthread_rwlock_unlock(&fileLock);
}

void cleanup() {
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }
}
