```python
import hashlib
from concurrent.futures import ThreadPoolExecutor

def calculate_hashes(file_path, hash_types=['md5', 'sha256'], chunk_size=4096):
    def compute_hash(hash_algorithm, file_handle):
        hasher = hashlib.new(hash_algorithm)
        while True:
            data = file_handle.read(chunk_size)
            if not data:
                break
            hasher.update(data)
        return hasher.hexdigest()

    hash_algorithms = {
        'md5': hashlib.md5,
        'sha256': hashlib.sha256,
        'sha1': hashlib.sha1
    }

    results = {}

    with open(file_path, 'rb') as f:
        with ThreadPoolExecutor(max_workers=len(hash_types)) as executor:
            future_to_hash = {executor.submit(compute_hash, hash_algorithms[ht], f): ht for ht in hash_types if ht in hash_algorithms}
            for future in future_to_hash:
                ht = future_to_hash[future]
                try:
                    results[ht] = future.result()
                except Exception as e:
                    results[ht] = None

    return results
```

This function uses a `ThreadPoolExecutor` to concurrently calculate the checksums specified by the user. It reads the file in chunks, which helps manage memory usage effectively, especially for large files. The function returns a dictionary containing the computed checksum values for each requested hash type."]

['Below is an outline of a modular encryption framework in C that meets your requirements. Note that this example assumes access to libraries like OpenSSL for AES and ChaCha20, and potentially libsodium for additional functions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Include necessary cryptographic libraries
#ifdef USE_OPENSSL
#include <openssl/evp.h>
#include <openssl/rand.h>
#endif

#ifdef USE_LIBSODIUM
#include <sodium.h>
#endif

// Define a common interface for encryption algorithms
typedef struct {
    void (*init)(void *context, const unsigned char *key, size_t key_len);
    int (*encrypt)(void *context, const unsigned char *plaintext, size_t plaintext_len,
                   unsigned char *ciphertext, size_t *ciphertext_len);
    int (*decrypt)(void *context, const unsigned char *ciphertext, size_t ciphertext_len,
                   unsigned char *plaintext, size_t *plaintext_len);
} Cipher;

// Example implementations for AES and ChaCha20
typedef struct {
#ifdef USE_OPENSSL
    EVP_CIPHER_CTX *ctx;
#endif
} AESContext;

typedef struct {
#ifdef USE_LIBSODIUM
    unsigned char nonce[crypto_aead_chacha20poly1305_IETF_NPUBBYTES];
#endif
} ChaCha20Context;

// Key derivation functions using PBKDF2 and scrypt
void derive_key_pbkdf2(const char *password, size_t password_len,
                       const unsigned char *salt, size_t salt_len,
                       int iter_count, size_t key_len,
                       unsigned char *key) {
#ifdef USE_OPENSSL
    PKCS5_PBKDF2_HMAC_SHA1(password, password_len, salt, salt_len, iter_count, key_len, key);
#endif
}

void derive_key_scrypt(const char *password, size_t password_len,
                       const unsigned char *salt, size_t salt_len,
                       int N, int r, int p, size_t key_len,
                       unsigned char *key) {
#ifdef USE_LIBSODIUM
    if (sodium_init() == -1) {
        // Initialization failed
        exit(1);
    }
    if (crypto_pwhash(key, key_len, password, password_len, salt, salt_len, N, r, p,
                      crypto_pwhash_ALG_ARGON2ID13) != 0) {
        // Derivation failed
        exit(1);
    }
#endif
}

// Implementations for AES and ChaCha20 initialization, encryption, decryption
void aes_init(AESContext *ctx, const unsigned char *key, size_t key_len) {
#ifdef USE_OPENSSL
    ctx->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, key, NULL);
#endif
}

int aes_encrypt(AESContext *ctx, const unsigned char *plaintext, size_t plaintext_len,
                unsigned char *ciphertext, size_t *ciphertext_len) {
#ifdef USE_OPENSSL
    int len;
    EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len);
    *ciphertext_len = len;
    return 1; // Success
#endif
}

int aes_decrypt(AESContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len,
                unsigned char *plaintext, size_t *plaintext_len) {
#ifdef USE_OPENSSL
    int len;
    EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len);
    *plaintext_len = len;
    return 1; // Success
#endif
}

void chacha20_init(ChaCha20Context *ctx, const unsigned char *key, size_t key_len) {
#ifdef USE_LIBSODIUM
    randombytes_buf(ctx->nonce, sizeof(ctx->nonce));
#endif
}

int chacha20_encrypt(ChaCha20Context *ctx, const unsigned char *plaintext, size_t plaintext_len,
                     unsigned char *ciphertext, size_t *ciphertext_len) {
#ifdef USE_LIBSODIUM
    crypto_aead_chacha20poly1305_ietf_encrypt(ciphertext, NULL, plaintext, plaintext_len, NULL, 0,
                                              ctx->nonce, key);
    *ciphertext_len = plaintext_len + crypto_aead_chacha20poly1305_IETF_ABYTES;
    return 1; // Success
#endif
}

int chacha20_decrypt(ChaCha20Context *ctx, const unsigned char *ciphertext, size_t ciphertext_len,
                     unsigned char *plaintext, size_t *plaintext_len) {
#ifdef USE_LIBSODIUM
    if (crypto_aead_chacha20poly1305_ietf_decrypt(plaintext, NULL, NULL, ciphertext, ciphertext_len,
                                                  NULL, 0, ctx->nonce, key) != 0) {
        return 0; // Failure
    }
    *plaintext_len = ciphertext_len - crypto_aead_chacha20poly1305_IETF_ABYTES;
    return 1; // Success
#endif
}

// Example of dynamic loading and instantiation
Cipher *create_cipher(const char *algorithm, const unsigned char *key, size_t key_len) {
    if (strcmp(algorithm, "AES") == 0) {
        AESContext *aes_ctx = malloc(sizeof(AESContext));
        aes_init(aes_ctx, key, key_len);
        static Cipher aes_cipher = { .init = (void (*)(void *, const unsigned char *, size_t))aes_init,
                                    .encrypt = aes_encrypt,
                                    .decrypt = aes_decrypt };
        return &aes_cipher;
    } else if (strcmp(algorithm, "ChaCha20") == 0) {
        ChaCha20Context *chacha_ctx = malloc(sizeof(ChaCha20Context));
        chacha20_init(chacha_ctx, key, key_len);
        static Cipher chacha_cipher = { .init = (void (*)(void *, const unsigned char *, size_t))chacha20_init,
                                        .encrypt = chacha20_encrypt,
                                        .decrypt = chacha20_decrypt };
        return &chacha_cipher;
    }
    return NULL; // Unsupported algorithm
}

// Securely destroy keys and contexts
void secure_destroy(Cipher *cipher, void *context) {
    if (cipher == NULL || context == NULL) return;
#ifdef USE_OPENSSL
    if (strcmp(cipher->init.__func__, "aes_init") == 0) {
        AESContext *aes_ctx = (AESContext *)context;
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        free(aes_ctx);
    }
#endif
#ifdef USE_LIBSODIUM
    if (strcmp(cipher->init.__func__, "chacha20_init") == 0) {
        ChaCha20Context *chacha_ctx = (ChaCha20Context *)context;
        memset(chacha_ctx, 0, sizeof(ChaCha20Context));
        free(chacha_ctx);
    }
#endif
}

// Main function for testing
int main() {
#ifdef USE_LIBSODIUM
    if (sodium_init() == -1) {
        // Initialization failed
        return 1;
    }
#endif

    const char *algorithm = "AES";
    unsigned char key[32]; // Example key size for AES-256
    derive_key_pbkdf2("password", strlen("password"), (unsigned char *)"salt", 4, 100000, sizeof(key), key);

    Cipher *cipher = create_cipher(algorithm, key, sizeof(key));
    if (!cipher) {
        fprintf(stderr, "Unsupported algorithm\n");
        return 1;
    }

    unsigned char plaintext[] = "This is a test message.";
    size_t ciphertext_len, plaintext_len;
    unsigned char *ciphertext = malloc(strlen((char *)plaintext) + EVP_MAX_BLOCK_LENGTH);
    unsigned char *decryptedtext = malloc(strlen((char *)plaintext) + EVP_MAX_BLOCK_LENGTH);

    void *context = malloc(sizeof(AESContext)); // Allocate context based on cipher type
    cipher->init(context, key, sizeof(key));
    cipher->encrypt(context, plaintext, strlen((char *)plaintext), ciphertext, &ciphertext_len);
    cipher->decrypt(context, ciphertext, ciphertext_len, decryptedtext, &plaintext_len);

    printf("Decrypted text: %.*s\n", (int)plaintext_len, decryptedtext);

    secure_destroy(cipher, context);
    free(ciphertext);
    free(decryptedtext);

    return 0;
}
```

### Key Points:
- **Modular Design**: The framework uses function pointers to abstract the operations of different ciphers.
- **Dynamic Loading**: Cipher objects are created dynamically based on user input.
- **Key Derivation**: Supports both PBKDF2 and scrypt for key derivation.
- **Secure Key Management**: Includes secure destruction of keys and contexts.
- **External Dependencies**: Uses OpenSSL and libsodium for cryptographic operations.

This code provides a starting point and can be extended to support additional algorithms and features as needed.']

['Below is an implementation of the described task in Java. The solution uses polymorphism, dependency injection, thread-safe practices, caching, abstraction, logging, and configurable report formats.

```java
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Function;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

interface PokemonTypeRetriever {
    List<String> getTypes(String pokemonId) throws Exception;
}

interface PokemonNameRetriever {
    String getName(String pokemonId) throws Exception;
}

class SimplePokemonTypeRetriever implements PokemonTypeRetriever {
    @Override
    public List<String> getTypes(String pokemonId) throws Exception {
        // Mock implementation
        return Arrays.asList("Fire", "Flying");
    }
}

class SimplePokemonNameRetriever implements PokemonNameRetriever {
    @Override
    public String getName(String pokemonId) throws Exception {
        // Mock implementation
        return "Pikachu";
    }
}

class CachingPokemonTypeRetriever implements PokemonTypeRetriever {
    private final PokemonTypeRetriever delegate;
    private final Map<String, List<String>> cache = new ConcurrentHashMap<>();

    public CachingPokemonTypeRetriever(PokemonTypeRetriever delegate) {
        this.delegate = delegate;
    }

    @Override
    public List<String> getTypes(String pokemonId) throws Exception {
        return cache.computeIfAbsent(pokemonId, id -> {
            try {
                return new ArrayList<>(delegate.getTypes(id));
            } catch (Exception e) {
                throw new RuntimeException("Failed to retrieve types", e);
            }
        });
    }
}

class LoggerPokemonTypeRetriever implements PokemonTypeRetriever {
    private static final Logger logger = LoggerFactory.getLogger(LoggerPokemonTypeRetriever.class);
    private final PokemonTypeRetriever delegate;

    public LoggerPokemonTypeRetriever(PokemonTypeRetriever delegate) {
        this.delegate = delegate;
    }

    @Override
    public List<String> getTypes(String pokemonId) throws Exception {
        try {
            return delegate.getTypes(pokemonId);
        } catch (Exception e) {
            logger.error("Failed to retrieve types for Pokemon ID: {}", pokemonId, e);
            throw e;
        }
    }
}

class LoggerPokemonNameRetriever implements PokemonNameRetriever {
    private static final Logger logger = LoggerFactory.getLogger(LoggerPokemonNameRetriever.class);
    private final PokemonNameRetriever delegate;

    public LoggerPokemonNameRetriever(PokemonNameRetriever delegate) {
        this.delegate = delegate;
    }

    @Override
    public String getName(String pokemonId) throws Exception {
        try {
            return delegate.getName(pokemonId);
        } catch (Exception e) {
            logger.error("Failed to retrieve name for Pokemon ID: {}", pokemonId, e);
            throw e;
        }
    }
}

interface ReportFormatter {
    String formatReport(PokemonData data);
}

class DefaultReportFormatter implements ReportFormatter {
    @Override
    public String formatReport(PokemonData data) {
        return "Pokemon Name: " + data.getName() +
                "\nTypes: " + String.join(", ", data.getTypes()) +
                (data.getWeaknesses().isEmpty() ? "" : 
                    "\nWeaknesses: " + String.join(", ", data.getWeaknesses()));
    }
}

class PokemonData {
    private final String name;
    private final List<String> types;
    private final List<String> weaknesses;

    public PokemonData(String name, List<String> types, List<String> weaknesses) {
        this.name = name;
        this.types = types;
        this.weaknesses = weaknesses;
    }

    public String getName() {
        return name;
    }

    public List<String> getTypes() {
        return types;
    }

    public List<String> getWeaknesses() {
        return weaknesses;
    }
}

public class PokemonReportGenerator {

    private final PokemonTypeRetriever typeRetriever;
    private final PokemonNameRetriever nameRetriever;

    public PokemonReportGenerator(PokemonTypeRetriever typeRetriever, PokemonNameRetriever nameRetriever) {
        this.typeRetriever = typeRetriever;
        this.nameRetriever = nameRetriever;
    }

    public String generateReport(String pokemonId, ReportFormatter formatter, List<String> specialWeaknesses) throws Exception {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        try {
            List<Callable<?>> tasks = new ArrayList<>();
            Callable<String> nameTask = () -> nameRetriever.getName(pokemonId);
            Callable<List<String>> typesTask = () -> typeRetriever.getTypes(pokemonId);

            tasks.add(nameTask);
            tasks.add(typesTask);

            List<Object> results = executor.invokeAll(tasks).stream()
                    .map(future -> {
                        try {
                            return future.get();
                        } catch (Exception e) {
                            throw new RuntimeException("Failed to execute task", e);
                        }
                    })
                    .collect(Collectors.toList());

            String name = (String) results.get(0);
            List<String> types = (List<String>) results.get(1);

            // Mock weaknesses based on type
            List<String> weaknesses = calculateWeaknesses(types);

            if (specialWeaknesses != null) {
                weaknesses.addAll(specialWeaknesses);
            }

            PokemonData data = new PokemonData(name, types, weaknesses);

            return formatter.formatReport(data);
        } finally {
            executor.shutdown();
        }
    }

    private List<String> calculateWeaknesses(List<String> types) {
        // Mock weakness calculation
        Set<String> weaknessesSet = new HashSet<>();
        for (String type : types) {
            if ("Fire".equals(type)) {
                weaknessesSet.add("Water");
            } else if ("Flying".equals(type)) {
                weaknessesSet.add("Electric");
            }
        }
        return new ArrayList<>(weaknessesSet);
    }

    public static void main(String[] args) throws Exception {
        PokemonTypeRetriever typeRetriever = new LoggerPokemonTypeRetriever(
                new CachingPokemonTypeRetriever(new SimplePokemonTypeRetriever()));

        PokemonNameRetriever nameRetriever = new LoggerPokemonNameRetriever(new SimplePokemonNameRetriever());

        PokemonReportGenerator generator = new PokemonReportGenerator(typeRetriever, nameRetriever);

        String report = generator.generateReport("001", new DefaultReportFormatter(), Arrays.asList("Psychic"));
        System.out.println(report);
    }
}
```

This code provides a scalable and extensible solution for generating detailed reports on Pokémon objects, incorporating the requested features such as polymorphism, dependency injection, thread safety, caching, logging, and customizable report formats.']

['Below is a C code implementation that addresses your requirements for dynamically checking cryptographic hash functions and block ciphers while considering performance, memory usage, and thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ALGORITHMS 10

typedef struct {
    char** algorithms;
    size_t count;
} AlgorithmList;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static AlgorithmList hashFunctions = {NULL, 0};
static AlgorithmList blockCiphers = {NULL, 0};

// Mock function to simulate checking availability of cryptographic algorithms
int is_algorithm_available(const char* algorithm) {
    // Simulate a system call or check
    return 1; // Assume all are available for demonstration purposes
}

void update_algorithms(AlgorithmList* list, const char** possibleAlgorithms) {
    size_t capacity = MAX_ALGORITHMS;
    list->algorithms = (char**)malloc(capacity * sizeof(char*));
    if (!list->algorithms) return;

    for (size_t i = 0; possibleAlgorithms[i] != NULL; ++i) {
        if (is_algorithm_available(possibleAlgorithms[i])) {
            if (list->count >= capacity) {
                capacity *= 2;
                char** new_algorithms = (char**)realloc(list->algorithms, capacity * sizeof(char*));
                if (!new_algorithms) break;
                list->algorithms = new_algorithms;
            }
            list->algorithms[list->count++] = strdup(possibleAlgorithms[i]);
        } else {
            printf("Algorithm unavailable: %s\n", possibleAlgorithms[i]);
        }
    }
}

void* periodic_check(void* arg) {
    struct timespec interval = {0, 100000000}; // 100 ms interval
    while (1) {
        pthread_mutex_lock(&mutex);

        const char* hashCandidates[] = {"SHA256", "SHA512", NULL};
        const char* cipherCandidates[] = {"AES", "DES", NULL};

        update_algorithms(&hashFunctions, hashCandidates);
        update_algorithms(&blockCiphers, cipherCandidates);

        pthread_mutex_unlock(&mutex);

        nanosleep(&interval, NULL); // Sleep for the specified interval
    }
}

AlgorithmList get_available_algorithms(const char* type, size_t max_count) {
    AlgorithmList result = {NULL, 0};
    pthread_mutex_lock(&mutex);

    if (strcmp(type, "hash") == 0) {
        result.algorithms = hashFunctions.algorithms;
        result.count = (hashFunctions.count < max_count) ? hashFunctions.count : max_count;
    } else if (strcmp(type, "cipher") == 0) {
        result.algorithms = blockCiphers.algorithms;
        result.count = (blockCiphers.count < max_count) ? blockCiphers.count : max_count;
    }

    pthread_mutex_unlock(&mutex);
    return result;
}

void free_algorithm_list(AlgorithmList* list) {
    if (list->algorithms) {
        for (size_t i = 0; i < list->count; ++i) {
            free(list->algorithms[i]);
        }
        free(list->algorithms);
        list->algorithms = NULL;
        list->count = 0;
    }
}

int main() {
    pthread_t checker_thread;
    if (pthread_create(&checker_thread, NULL, periodic_check, NULL)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    AlgorithmList availableHashes = get_available_algorithms("hash", 5);
    printf("Available Hash Functions:\n");
    for (size_t i = 0; i < availableHashes.count; ++i) {
        printf("%s\n", availableHashes.algorithms[i]);
    }
    free_algorithm_list(&availableHashes);

    AlgorithmList availableCiphers = get_available_algorithms("cipher", 5);
    printf("\nAvailable Block Ciphers:\n");
    for (size_t i = 0; i < availableCiphers.count; ++i) {
        printf("%s\n", availableCiphers.algorithms[i]);
    }
    free_algorithm_list(&availableCiphers);

    pthread_cancel(checker_thread);
    pthread_join(checker_thread, NULL);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe access to the algorithm lists.
- **Dynamic Updates**: Periodically checks for available algorithms in a separate thread and updates the list.
- **Memory Management**: Efficiently allocates memory using dynamic arrays, reallocating only when necessary.
- **Error Handling**: Gracefully handles unavailable algorithms by logging messages.
- **Resource Limitation**: Supports an optional parameter to limit the number of returned algorithms.

This code provides a template for managing cryptographic algorithm availability dynamically and safely in a multi-threaded environment.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <openssl/evp.h>
#include <jansson.h>

#define MAX_OPERATIONS_PER_SECOND 100

typedef struct {
    EVP_CIPHER_CTX *ctx;
    char *key;
    char *iv;
    char *cipher_type;
} OpenSSLParams;

typedef enum { ENCRYPTION, DECRYPTION } OperationType;

void handleError(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int checkDependencies() {
    // Check for OpenSSL
    if (!EVP_CIPHER_CTX_new)
        return 0;
    return 1;
}

JSON_Value* loadConfig(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) handleError("Could not open configuration file.");

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *data = malloc(length + 1);
    fread(data, 1, length, file);
    fclose(file);
    data[length] = '\0';

    JSON_Value *root_value = json_loads(data, 0, NULL);
    free(data);
    return root_value;
}

OpenSSLParams parseConfig(JSON_Value *config) {
    OpenSSLParams params = {NULL, NULL, NULL, NULL};

    JSON_Object *config_obj = json_value_get_object(config);

    const char *key = json_object_dotget_string(config_obj, "encryption.key");
    if (!key) handleError("Missing encryption key in configuration.");

    const char *iv = json_object_dotget_string(config_obj, "encryption.iv");
    if (!iv) handleError("Missing initialization vector in configuration.");

    const char *cipher_type = json_object_dotget_string(config_obj, "encryption.type");
    if (!cipher_type) handleError("Missing cipher type in configuration.");

    params.key = strdup(key);
    params.iv = strdup(iv);
    params.cipher_type = strdup(cipher_type);

    return params;
}

int initOpenSSL(OpenSSLParams *params, OperationType op_type) {
    params->ctx = EVP_CIPHER_CTX_new();
    if (!params->ctx) handleError("Failed to create OpenSSL context.");

    const EVP_CIPHER *cipher = NULL;
    if (strcmp(params->cipher_type, "AES-256-CBC") == 0)
        cipher = EVP_aes_256_cbc();

    if (!cipher || EVP_EncryptInit_ex(params->ctx, cipher, NULL, params->key, params->iv) <= 0 ||
        (op_type == DECRYPTION && EVP_DecryptInit_ex(params->ctx, cipher, NULL, params->key, params->iv) <= 0))
        handleError("Failed to initialize OpenSSL operation.");

    return 1;
}

void cleanup(OpenSSLParams *params) {
    if (params->ctx) EVP_CIPHER_CTX_free(params->ctx);
    free(params->key);
    free(params->iv);
    free(params->cipher_type);
}

void processOperation(const char *input, size_t input_len, OperationType op_type) {
    OpenSSLParams params = {NULL, NULL, NULL, NULL};
    if (!checkDependencies()) handleError("Missing or outdated dependencies.");

    JSON_Value *config = loadConfig("config.json");
    params = parseConfig(config);
    json_value_free(config);

    initOpenSSL(&params, op_type);

    // Simulate operation (e.g., encryption/decryption)
    printf("Processing %s with cipher type: %s\n", op_type == ENCRYPTION ? "encryption" : "decryption", params.cipher_type);

    cleanup(&params);
}

void rateLimit() {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;
    static int ops_count = 0;
    static time_t last_reset = time(NULL);

    pthread_mutex_lock(&mutex);

    if (time(NULL) != last_reset) {
        ops_count = 0;
        last_reset = time(NULL);
    }

    while (ops_count >= MAX_OPERATIONS_PER_SECOND) {
        pthread_cond_wait(&cond_var, &mutex);
    }

    ops_count++;
    pthread_cond_signal(&cond_var);
    pthread_mutex_unlock(&mutex);

    usleep(1000000 / MAX_OPERATIONS_PER_SECOND); // Sleep to maintain rate limit
}

void *operationThread(void *arg) {
    OperationType op_type = *(OperationType *)arg;
    char input[] = "data"; // Example data
    processOperation(input, sizeof(input), op_type);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 2 || strcmp(argv[1], "encrypt") != 0 && strcmp(argv[1], "decrypt") != 0)
        handleError("Usage: program [encrypt|decrypt]");

    OperationType op_type = strcmp(argv[1], "encrypt") == 0 ? ENCRYPTION : DECRYPTION;

    pthread_t threads[MAX_OPERATIONS_PER_SECOND];
    for (int i = 0; i < MAX_OPERATIONS_PER_SECOND; ++i) {
        rateLimit();
        pthread_create(&threads[i], NULL, operationThread, &op_type);
    }

    for (int i = 0; i < MAX_OPERATIONS_PER_SECOND; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
