#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define SEM_NAME_MAX 255
#define LOG_BUFFER_SIZE 256

// Utility function for logging messages with minimal overhead.
void log_message(const char *message) {
    static char buffer[LOG_BUFFER_SIZE];
    snprintf(buffer, sizeof(buffer), "%s\n", message);
    write(STDERR_FILENO, buffer, strlen(buffer));
}

// Validate semaphore name according to the naming convention.
int validate_semaphore_name(const char *name) {
    if (strlen(name) == 0 || strlen(name) > SEM_NAME_MAX) return -1;
    for (size_t i = 0; i < strlen(name); ++i) {
        if (!isalnum(name[i]) && name[i] != '_') return -1;
    }
    return 0;
}

// Function to manage semaphore
int manage_semaphore(const char *sem_name, unsigned int initial_value, unsigned int timeout_ms) {
    if (validate_semaphore_name(sem_name) == -1) {
        log_message("Invalid semaphore name.");
        return -1;
    }

    sem_t *sem = sem_open(sem_name, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        if (errno == EEXIST) {
            sem_unlink(sem_name); // Ensure cleanup on existing names
        }
        log_message("Failed to create semaphore.");
        return -1;
    }

    int ret = 0;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }

    // Retry mechanism for acquiring semaphore
    while (1) {
        ret = sem_timedwait(sem, &ts);
        if (ret == 0) break; // Successfully acquired the semaphore

        if (errno == ETIMEDOUT) {
            log_message("Semaphore wait timed out.");
            break;
        }

        // Retry logic for transient errors
        if (errno == EINTR || errno == EAGAIN) {
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += timeout_ms / 1000;
            ts.tv_nsec += (timeout_ms % 1000) * 1000000;
            if (ts.tv_nsec >= 1000000000) {
                ts.tv_sec++;
                ts.tv_nsec -= 1000000000;
            }
        } else {
            log_message("Failed to acquire semaphore.");
            break;
        }
    }

    // Reporting current state of the semaphore
    int sem_value = 0;
    if (sem_getvalue(sem, &sem_value) == 0) {
        printf("Semaphore value: %d\n", sem_value);
    } else {
        log_message("Failed to get semaphore value.");
    }

    // Clean up and delete semaphore
    if (sem_close(sem) != 0 || sem_unlink(sem_name) != 0) {
        log_message("Failed to clean up semaphore.");
    }

    return ret == 0 ? 0 : -1;
}

int main() {
    const char *sem_name = "my_semaphore_01";
    unsigned int initial_value = 1;
    unsigned int timeout_ms = 5000;

    if (manage_semaphore(sem_name, initial_value, timeout_ms) != 0) {
        log_message("Semaphore management failed.");
    } else {
        log_message("Semaphore managed successfully.");
    }

    return 0;
}
```

### Key Points:
- **Semaphore Creation and Naming:** Validates the semaphore name and ensures it does not conflict with existing resources.
- **Logging:** Uses a simple logging mechanism to minimize overhead during high-concurrency scenarios.
- **Timeout Handling:** Implements a retry mechanism using `sem_timedwait`.
- **Resource Cleanup:** Ensures semaphores are deleted on successful completion or early termination.
- **State Reporting:** Reports the current state of the semaphore without blocking other operations.']

