async fn fetch_and_generate_bytecode() -> Result<(), ReqError> {
    // Configure environment variables
    let api_base_url = env::var("API_BASE_URL").expect("API_BASE_URL not set");
    let operation_endpoint = env::var("OPERATION_ENDPOINT").expect("OPERATION_ENDPOINT not set");

    // Construct the full endpoint URL
    let url = format!("{}/{}", api_base_url, operation_endpoint);

    // Create an HTTP client with retry logic and rate limiting handling
    let client = Client::builder()
        .user_agent("MyApp/1.0")
        .build()?;

    let mut attempts = 3;
    while attempts > 0 {
        match fetch_data(&client, &url).await {
            Ok(data) => {
                if let Some(bytecode) = generate_optimized_bytecode(&data) {
                    info!("Generated bytecode: {:?}", bytecode);
                } else {
                    error!("Failed to generate bytecode from data");
                }
                return Ok(());
            },
            Err(e) => {
                attempts -= 1;
                if attempts == 0 {
                    error!("Request failed after retries: {}", e);
                    return Err(e);
                }
                info!("Retrying due to network error: {}, attempts left: {}", e, attempts);
                sleep(Duration::from_secs(2)).await;
            },
        }
    }

    Ok(())
}

async fn fetch_data(client: &Client, url: &str) -> Result<String, ReqError> {
