    let response = client.get(url)
        .send()
        .await?;

    log_request(&response);

    if !response.status().is_success() {
        return Err(ReqError::new(reqwest::StatusCode::from_u16(response.status().as_u16()).unwrap(), true));
    }

    let elapsed = start.elapsed();
    info!("Request to {} completed in {:?}", url, elapsed);

    response.text().await
}

fn log_request(response: &reqwest::Response) {
    info!(
        "Response Status: {}, Headers: {:?}, Duration: {:?}",
        response.status(),
        response.headers(),
        response.elapsed()
    );
}

