['```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;

public class BulkInserter<T>
{
    private static readonly object LockObject = new object();

    public (int TotalInserted, int FailedInsertions, List<Exception> Errors) InsertRecords(
        List<T> records,
        SqlConnection connection,
        string tableName,
        int batchSize)
    {
        if (records == null || !records.Any() || connection == null || string.IsNullOrEmpty(tableName))
            throw new ArgumentException("Invalid input parameters.");

        var totalInserted = 0;
        var failedInsertions = 0;
        var errors = new List<Exception>();

        using (var transaction = connection.BeginTransaction())
        {
            try
            {
                int recordsCount = records.Count;

                for (int i = 0; i < recordsCount; i += batchSize)
                {
                    var batchRecords = records.Skip(i).Take(batchSize).ToList();

                    if (!batchRecords.Any()) continue;

                    lock (LockObject) // Ensure thread safety
                    {
                        using (var bulkCopy = new SqlBulkCopy(connection, SqlBulkCopyOptions.Default, transaction))
                        {
                            bulkCopy.DestinationTableName = tableName;

                            var stopwatch = Stopwatch.StartNew();

                            try
                            {
                                bulkCopy.WriteToServer(batchRecords);
                                totalInserted += batchRecords.Count;
                            }
                            catch (Exception ex)
                            {
                                failedInsertions += batchRecords.Count;
                                errors.Add(new Exception($"Failed to insert batch starting at index {i}. Error: {ex.Message}", ex));

                                // Optional: Log detailed information about the failure
                            }

                            stopwatch.Stop();
                            Console.WriteLine($"Batch inserted in {stopwatch.ElapsedMilliseconds} ms.");
                        }
                    }
                }

                transaction.Commit();
            }
            catch (Exception ex)
            {
                try
                {
                    transaction.Rollback();
                }
                catch
                {
                    // Log rollback failure if needed
                }

                errors.Add(ex);
            }
        }

        return (totalInserted, failedInsertions, errors);
    }
}
```

### Notes:
- **Concurrency**: The `lock` ensures serialized access to the database.
- **Error Tolerance**: Exceptions are caught and logged. Insertion can be retried if needed based on business logic.
- **Performance Optimization**: Uses `SqlBulkCopy` for efficient bulk insertions within transactions.
- **Resource Management**: Processes records in manageable batches, reducing memory load.
- **Integration Flexibility & Scalability**: Designed generically to handle different data types and structures.']

