using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

namespace GeospatialApp
{
    public class GeoSpatialService
    {
        private readonly string _apiKey;
        private readonly HttpClient _httpClient;
        private const int MaxRetries = 3;
        private double _currentZoomLevel;
        private double _preferredNetworkLatencyThreshold; // in milliseconds

        public GeoSpatialService(string apiKey, double preferredNetworkLatencyThreshold)
        {
            _apiKey = apiKey;
            _httpClient = new HttpClient();
            _preferredNetworkLatencyThreshold = preferredNetworkLatencyThreshold;
        }

        public async Task AdjustGeoTilesAsync(double userZoomLevel, double networkLatency)
        {
            _currentZoomLevel = userZoomLevel;

            if (networkLatency > _preferredNetworkLatencyThreshold)
            {
                await AdjustForHighLatencyAsync();
            }
            else
            {
                await FetchAndAdjustTilesAsync();
            }
        }

        private async Task AdjustForHighLatencyAsync()
        {
            // Reduce resolution to decrease load times
            double adjustedZoomLevel = _currentZoomLevel - 1;
            await FetchAndAdjustTilesAsync(adjustedZoomLevel);
        }

        private async Task FetchAndAdjustTilesAsync(double? zoomLevelOverride = null)
        {
            var zoomLevel = zoomLevelOverride ?? _currentZoomLevel;

            for (int attempt = 0; attempt < MaxRetries; attempt++)
            {
                try
                {
                    var response = await _httpClient.GetAsync(
                        $"https://api.example.com/tiles?zoom={zoomLevel}&key={_apiKey}");

                    if (!response.IsSuccessStatusCode)
                    {
                        HandleApiError(response);
                        continue;
                    }

                    string content = await response.Content.ReadAsStringAsync();
                    JObject tileData = JObject.Parse(content);

                    // Process and display tiles based on fetched data
                    DisplayTiles(tileData);

                    break; // Exit loop if successful
                }
                catch (HttpRequestException ex)
                {
                    Console.WriteLine($"Request failed: {ex.Message}");
                    await Task.Delay(1000); // Wait before retrying
                }
            }
        }

        private void HandleApiError(HttpResponseMessage response)
        {
            int statusCode = (int)response.StatusCode;

            if (statusCode == 429) // Too Many Requests
            {
                Console.WriteLine("Rate limit exceeded. Retrying...");
                Task.Delay(2000).Wait(); // Wait before retrying
            }
            else if (statusCode >= 500 && statusCode < 600)
            {
                Console.WriteLine("Server error encountered.");
            }
            else
            {
                Console.WriteLine($"API error: {response.ReasonPhrase}");
            }
        }

        private void DisplayTiles(JObject tileData)
        {
            // Logic to display tiles based on the data received
            Console.WriteLine("Displaying tiles...");
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            string apiKey = "your_api_key_here";
            double preferredNetworkLatencyThreshold = 200; // milliseconds

            GeoSpatialService geoService = new GeoSpatialService(apiKey, preferredNetworkLatencyThreshold);

            double userZoomLevel = 5.0;
            double currentNetworkLatency = 150; // Example latency in ms

            await geoService.AdjustGeoTilesAsync(userZoomLevel, currentNetworkLatency);
        }
    }
}
```

