### C# Function: ProcessConfigFiles

```csharp
using System;
using System.IO;
using System.Xml.Linq;

public class ConfigProcessor
{
    public void ProcessConfigFiles(string xmlConfig, string directoryPath, string fileMask)
    {
        try
        {
            XDocument configDoc = XDocument.Parse(xmlConfig);
            var filesToProcess = Directory.EnumerateFiles(directoryPath, fileMask, SearchOption.AllDirectories);

            foreach (var filePath in filesToProcess)
            {
                try
                {
                    ProcessFile(configDoc, filePath);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to process configuration: {ex.Message}");
        }
    }

    private void ProcessFile(XDocument configDoc, string filePath)
    {
        if (!File.Exists(filePath))
        {
            Console.WriteLine($"File does not exist: {filePath}");
            return;
        }

        try
        {
            var fileElement = configDoc.Root.Element("File");
            if (fileElement == null) throw new InvalidOperationException("Invalid XML configuration.");

            string operation = fileElement.Attribute("Operation")?.Value;
            string targetPath = fileElement.Attribute("TargetPath")?.Value;

            switch (operation)
            {
                case "Rename":
                    RenameFile(filePath, targetPath);
                    break;
                case "Copy":
                    CopyFile(filePath, targetPath);
                    break;
                case "Archive":
                    ArchiveFile(filePath, targetPath);
                    break;
                default:
                    Console.WriteLine($"Unsupported operation: {operation}");
                    break;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
        }
    }

    private void RenameFile(string sourceFilePath, string targetFileName)
    {
        if (string.IsNullOrEmpty(targetFileName))
            throw new ArgumentNullException(nameof(targetFileName));

        var directory = Path.GetDirectoryName(sourceFilePath);
        var newFilePath = Path.Combine(directory, targetFileName);

        File.Move(sourceFilePath, newFilePath);
        Console.WriteLine($"Renamed {sourceFilePath} to {newFilePath}");
    }

    private void CopyFile(string sourceFilePath, string targetPath)
    {
        if (string.IsNullOrEmpty(targetPath))
            throw new ArgumentNullException(nameof(targetPath));

        var directory = Path.GetDirectoryName(targetPath);
        var fileName = Path.GetFileName(sourceFilePath);

        var newFilePath = Path.Combine(directory, fileName);
        File.Copy(sourceFilePath, newFilePath, true);
        Console.WriteLine($"Copied {sourceFilePath} to {newFilePath}");
    }

    private void ArchiveFile(string filePath, string archivePath)
    {
        if (string.IsNullOrEmpty(archivePath))
            throw new ArgumentNullException(nameof(archivePath));

        var directory = Path.GetDirectoryName(archivePath) ?? throw new DirectoryNotFoundException();
        var fileName = Path.GetFileName(filePath);

        var archiveFileName = $"{fileName}.zip";
        var zipFilePath = Path.Combine(directory, archiveFileName);

        System.IO.Compression.ZipFile.CreateFromDirectory(Path.GetDirectoryName(filePath), zipFilePath, CompressionLevel.Fastest, false);
        Console.WriteLine($"Archived {filePath} to {zipFilePath}");
    }
}
```

### Rust Function: EnvironmentAwareFileOperation

```rust
use std::env;
use std::fs::{self, File};
use std::io::{self, ErrorKind};
use std::path::Path;
use std::result;

#[derive(Debug)]
enum OperationType {
    Copy,
    Move,
    Rename,
}

type Result<T> = result::Result<T, String>;

fn environment_aware_file_operation(
    directory_name: &str,
    env_var_name: &str,
    operation_type: OperationType,
    target_path: &str,
) -> Result<String> {
    let current_value = env::var(env_var_name).ok();

    let source_dir = Path::new(directory_name);
    if !source_dir.exists() || !source_dir.is_dir() {
        return Err(format!("Directory does not exist or is not a directory: {}", directory_name));
    }

    let target_path = match current_value.as_deref() {
        Some(value) => value,
        None => target_path,
    };

    let source_file = Path::new(directory_name).join("file.txt"); // Example file
    if !source_file.exists() || !source_file.is_file() {
        return Err(format!("Source file does not exist: {:?}", source_file));
    }

    match operation_type {
        OperationType::Copy => copy_operation(&source_file, target_path),
        OperationType::Move => move_operation(&source_file, target_path),
        OperationType::Rename => rename_operation(&source_file, target_path),
    }
}

fn copy_operation(source: &Path, target_dir: &str) -> Result<String> {
    let destination = Path::new(target_dir).join(source.file_name().unwrap());

    fs::copy(source, &destination)
        .map_err(|e| format!("Failed to copy file: {}", e))?;

    Ok(format!("Copied {} to {:?}", source.display(), destination.display()))
}

fn move_operation(source: &Path, target_dir: &str) -> Result<String> {
    let destination = Path::new(target_dir).join(source.file_name().unwrap());

    fs::rename(source, &destination)
        .map_err(|e| format!("Failed to move file: {}", e))?;

    Ok(format!("Moved {} to {:?}", source.display(), destination.display()))
}

fn rename_operation(source: &Path, new_name: &str) -> Result<String> {
    let parent_dir = source.parent().ok_or("Source path is not valid")?;
    let new_path = parent_dir.join(new_name);

    fs::rename(source, &new_path)
        .map_err(|e| format!("Failed to rename file: {}", e))?;

    Ok(format!("Renamed {} to {:?}", source.display(), new_path.display()))
}

fn main() {
    match environment_aware_file_operation("example_dir", "EXAMPLE_ENV_VAR", OperationType::Copy, "/target/dir") {
        Ok(message) => println!("{}", message),
        Err(e) => eprintln!("Error: {}", e),
    }
}
```

These implementations handle the specified requirements and potential issues such as file existence, permissions, and error logging.']

['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StringProcessor {

    private static final Logger logger = Logger.getLogger(StringProcessor.class.getName());
    private final BlockingQueue<String> queue = new LinkedBlockingQueue<>(1000);
    private final ConcurrentHashMap<String, String> cache;
    private final ExecutorService executor;
    private final int maxCacheSize;

    public StringProcessor(int threadCount, int maxCacheSize) {
        this.cache = new ConcurrentHashMap<>();
        this.maxCacheSize = maxCacheSize;
        this.executor = Executors.newFixedThreadPool(threadCount);
        initializeCacheEvictionPolicy();
    }

    private void initializeCacheEvictionPolicy() {
        ScheduledExecutorService cacheManager = Executors.newScheduledThreadPool(1);
        cacheManager.scheduleAtFixedRate(() -> {
            if (cache.size() > maxCacheSize) {
                int entriesToRemove = cache.size() - maxCacheSize;
                for (int i = 0; i < entriesToRemove && !cache.isEmpty(); i++) {
                    String keyToEvict = cache.keySet().iterator().next();
                    cache.remove(keyToEvict);
                }
            }
        }, 0, 1, TimeUnit.SECONDS);
    }

    public void processBatch(String[] batch) {
        long startTime = System.currentTimeMillis();
        int processedCount = 0;

        for (String input : batch) {
            try {
                queue.put(sanitizeInput(input));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }
        }

        while (!queue.isEmpty()) {
            String sanitizedString = queue.poll();
            if (sanitizedString != null) {
                executor.submit(() -> cache.computeIfAbsent(sanitizedString, this::generateMD5Hash));
                processedCount++;
            }
        }

        long endTime = System.currentTimeMillis();
        logger.log(Level.INFO, "Processed {0} strings in {1} ms", new Object[]{processedCount, (endTime - startTime)});
    }

    private String sanitizeInput(String input) {
        return input.replaceAll("[^\\w\\s]", "").trim(); // Basic sanitization example
    }

    private String generateMD5Hash(String data) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(data.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        StringProcessor processor = new StringProcessor(Runtime.getRuntime().availableProcessors(), 10000);

        // Simulate receiving a batch of strings
        String[] sampleBatch = {"string1", "string2", "string3"};
        processor.processBatch(sampleBatch);

        processor.shutdown();
    }
}
```

This Java code defines a `StringProcessor` class that processes batches of strings, generates MD5 hashes for each sanitized string, and stores them in a high-performance cache with an eviction policy. It uses a thread-safe queue to buffer incoming strings and optimizes resource management to handle up to 1,000 strings per second. The method logs the number of processed strings and time taken for each batch.']

