            case 'create':
                $response = createUserAccount($id, $name, $email, $password);
                break;

            case 'update':
                if (!$id) return jsonResponse(['message' => 'error', 'status_code' => 400]);
                $response = updateUserAccount($id, $name, $email, $password);
