using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

public class ContentController : Controller
{
    private readonly IContentManagementService _contentService;
    private readonly IMemoryCache _cache;

    public ContentController(IContentManagementService contentService, IMemoryCache cache)
    {
        _contentService = contentService ?? throw new ArgumentNullException(nameof(contentService));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    [HttpPost("update-content")]
    public async Task<IActionResult> UpdateContent(string pageSectionId, string elementId, string newHtmlContent)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(pageSectionId) || string.IsNullOrWhiteSpace(elementId) || string.IsNullOrWhiteSpace(newHtmlContent))
                return BadRequest("Invalid input parameters.");

            // Generate cache key based on section and element ID
            var cacheKey = $"content_{pageSectionId}_{elementId}";

            // Check the cache first to avoid unnecessary database access
            if (_cache.TryGetValue(cacheKey, out string cachedContent) && cachedContent == newHtmlContent)
                return Ok("No update required. Content is already up-to-date.");

            using (await _contentService.AcquireLockAsync(elementId))
            {
                var updated = await _contentService.UpdateElementAsync(pageSectionId, elementId, newHtmlContent);

                if (updated)
                {
                    // Update the cache with new content
                    _cache.Set(cacheKey, newHtmlContent, TimeSpan.FromMinutes(5)); // Adjust expiration as needed

                    LogUpdateAction(pageSectionId, elementId, newHtmlContent);
                    return Ok("Content updated successfully. Please refresh the page.");
                }

                return StatusCode(500, "Failed to update content due to an internal error.");
            }
        }
        catch (Exception ex)
        {
            // Handle and log exception details
            LogError(ex, pageSectionId, elementId);
            return StatusCode(500, "An unexpected error occurred while updating content.");
        }
    }

    private void LogUpdateAction(string pageSectionId, string elementId, string newHtmlContent)
    {
        // Implement detailed logging for update actions
        Console.WriteLine($"Updated section {pageSectionId}, element {elementId} at {DateTime.UtcNow}");
    }

    private void LogError(Exception ex, string pageSectionId, string elementId)
    {
        // Implement comprehensive error logging
        Console.Error.WriteLine($"Error updating section {pageSectionId}, element {elementId}: {ex.Message}");
    }
}

public interface IContentManagementService
{
    Task<IDisposable> AcquireLockAsync(string elementId);
    Task<bool> UpdateElementAsync(string pageSectionId, string elementId, string newHtmlContent);
}
