### C++ Function

```cpp
#include <forward_list>
#include <string>

void modifyForwardList(std::forward_list<std::string>& list, const std::string& first, const std::string& second) {
    auto it = list.begin();
    bool inserted = false;

    for (auto next_it = std::next(it); it != list.end(); it = next_it) {
        next_it = std::next(it);
        if (*it == first) {
            list.insert_after(it, second);
            inserted = true;
            break;
        }
    }

    if (!inserted) {
        list.push_back(second);
    }
}

// Example usage:
// std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
// modifyForwardList(myList, "banana", "date");
```

