from collections import OrderedDict
import requests

class ThemeCacheManager:
    def __init__(self, config_service_url):
        self.config_service_url = config_service_url
        self.default_theme_dir = None
        self.theme_cache = OrderedDict()
        self.cache_lock = threading.RLock()  # Reentrant lock for thread safety
        self.setup_logging()

        if not os.path.exists(self.get_default_theme_directory()):
            self.retrieve_default_theme_directory_from_service()

    def setup_logging(self):
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    def get_default_theme_directory(self):
        if self.default_theme_dir is None:
            raise ValueError("Default theme directory not set.")
        return self.default_theme_dir

    def retrieve_default_theme_directory_from_service(self):
        try:
            response = requests.get(self.config_service_url, timeout=5)
            if response.status_code == 200:
                self.default_theme_dir = response.json().get('default_theme_dir', None)
                if not self.default_theme_dir or not os.path.exists(self.default_theme_dir):
                    raise FileNotFoundError("Theme directory retrieved is invalid.")
        except (requests.RequestException, ValueError, KeyError) as e:
            logging.error(f"Failed to retrieve default theme directory: {e}")
            # Implement fallback logic, e.g., use a hardcoded path
            self.default_theme_dir = "/fallback/theme/directory"

    def add_theme_to_cache(self, theme_name, theme_data):
        with self.cache_lock:
            if len(self.theme_cache) >= 10:  # Limit cache size to prevent memory bloat
                self.theme_cache.popitem(last=False)

            try:
                # Simulate bitmap recycling strategy to handle memory issues
                self.theme_cache[theme_name] = theme_data  # Store theme data (bitmaps)
            except MemoryError as e:
                logging.warning(f"Memory error while caching theme {theme_name}: {e}")

    def get_theme_from_cache(self, theme_name):
        with self.cache_lock:
            return self.theme_cache.get(theme_name)

    def validate_theme(self, theme_data):
        # Implement basic integrity and format checks
        try:
            if not isinstance(theme_data, (str, bytes)):  # Simulating file type check
                raise ValueError("Invalid theme format.")

            # Additional validation logic can be added here for actual content checking
            return True
        except Exception as e:
            logging.error(f"Theme validation failed: {e}")
            return False

    def periodic_cleanup(self):
        while True:
            with self.cache_lock:
                if self.theme_cache:
                    oldest_theme = next(iter(self.theme_cache))
                    del self.theme_cache[oldest_theme]

            logging.info("Performed theme cache cleanup.")
            threading.Event().wait(60)  # Run every minute

    def start_periodic_maintenance(self):
        maintenance_thread = threading.Thread(target=self.periodic_cleanup, daemon=True)
        maintenance_thread.start()

# Example usage
if __name__ == "__main__":
    manager = ThemeCacheManager("http://config-service.local/config")
    manager.start_periodic_maintenance()

    # Add some themes to cache for testing
    sample_theme_data = b"sample_theme_data"
    manager.add_theme_to_cache("light", sample_theme_data)
    manager.add_theme_to_cache("dark", sample_theme_data)

    # Retrieve a theme from the cache
    print(manager.get_theme_from_cache("light"))
