```java
import java.util.*;
import java.util.concurrent.*;
import java.io.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

class Service implements Runnable {
    private final String id;
    private static final Logger logger = LoggerFactory.getLogger(Service.class);

    public Service(String id) {
        this.id = id;
    }

    @Override
    public void run() {
        try {
            simulateWorkload();
            reportState("running");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            reportState("stopped");
        }
    }

    private void simulateWorkload() throws InterruptedException {
        logger.info("Service {} is executing a CPU-intensive task.", id);
        long startTime = System.currentTimeMillis();
        // Simulate intensive computation
        while (!Thread.currentThread().isInterrupted()) {
            performTask();
        }
        long endTime = System.currentTimeMillis();
        reportMetrics(startTime, endTime);
    }

    private void performTask() {
        double result = 0;
        for (int i = 1; i <= 1000000; i++) {
            result += Math.sqrt(i) * Math.sin(i);
        }
    }

    private void reportState(String state) {
        logger.info("Service {} is now {}", id, state);
        // Mock message broker communication
        System.out.println("MessageBroker: Service " + id + " State: " + state);
    }

    private void reportMetrics(long startTime, long endTime) {
        long duration = endTime - startTime;
        logger.info("Service {} completed task in {} ms", id, duration);
        // Mock message broker communication
        System.out.println("MessageBroker: Service " + id + " Metrics: Duration=" + duration + "ms");
    }
}

class ServiceManager {
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final Map<String, Future<?>> serviceFutures = new ConcurrentHashMap<>();
    private int instanceCount;
    private static final Logger logger = LoggerFactory.getLogger(ServiceManager.class);

    public void startServices(int initialCount) {
        instanceCount = initialCount;
        for (int i = 0; i < instanceCount; i++) {
            startNewService();
        }
    }

    private void startNewService() {
        String id = "service-" + serviceFutures.size();
        Future<?> future = scheduler.submit(new Service(id));
        serviceFutures.put(id, future);
        logger.info("Started {}", id);
    }

    public void adjustServiceCount(int newCount) {
        int currentCount = serviceFutures.size();
        if (newCount > currentCount) {
            for (int i = 0; i < newCount - currentCount; i++) {
                startNewService();
            }
        } else if (newCount < currentCount) {
            List<String> toStop = new ArrayList<>(serviceFutures.keySet());
            for (int i = 0; i < currentCount - newCount; i++) {
                String id = toStop.get(i);
                stopService(id);
            }
        }
    }

    private void stopService(String id) {
        Future<?> future = serviceFutures.remove(id);
        if (future != null && !future.isDone()) {
            future.cancel(true);
            logger.info("Stopped {}", id);
        }
    }

    public void shutdown() throws InterruptedException {
        scheduler.shutdown();
        for (Future<?> future : serviceFutures.values()) {
            if (!future.isDone()) {
                future.cancel(true);
            }
        }
        if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
            logger.error("Forced shutdown due to timeout");
        }
    }

    public static void main(String[] args) throws IOException {
        ServiceManager manager = new ServiceManager();
        manager.startServices(5);

        // Dynamic adjustment simulation
        ScheduledExecutorService adjuster = Executors.newSingleThreadScheduledExecutor();
        adjuster.scheduleAtFixedRate(() -> {
            int randomAdjustment = (int) (Math.random() * 3 - 1); 
            int currentCount = /* logic to determine based on performance */;
            manager.adjustServiceCount(currentCount + randomAdjustment);
            logger.info("Adjusted service count to {}", currentCount + randomAdjustment);
        }, 0, 10, TimeUnit.SECONDS);

        Runtime.getRuntime().addShutdownHook(new Thread(manager::shutdown));
    }
}
```

### Key Points:
- **Concurrency**: Uses `ScheduledExecutorService` for managing lifecycle and dynamic adjustment of services.
- **Resource Management**: Services simulate CPU-intensive tasks using loops with intensive computation.
- **Message Broker Simulation**: Outputs state and metrics to the console, simulating external communication.
- **Dynamic Scaling**: Adjusts service instance count based on a simulated performance metric (e.g., random for this example).
- **Logging**: Uses SLF4J for logging lifecycle events and performance metrics.']

