<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp) {
    // Predefined set of allowed statuses
    $allowedStatuses = ['active', 'inactive', 'under_maintenance'];

    // Validate the new status
    if (!in_array($newStatus, $allowedStatuses)) {
        logError("Invalid status", $clinicId, $newStatus);
        return "Error: Invalid status provided.";
    }

    try {
        // Verify clinic existence and permissions via external service
        $clinicExists = verifyClinicExistence($clinicId);

        if (!$clinicExists) {
            throw new Exception('Clinic does not exist or access is denied.');
        }

        // Begin database transaction
        $db = getDatabaseConnection();
        $db->beginTransaction();

        // Update the clinic status, last modified IP, and date in the database
        $stmt = $db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
        $success = $stmt->execute([$newStatus, $lastModifiedIp, $clinicId]);

        if (!$success) {
            throw new Exception('Database update failed.');
        }

        // Commit the transaction
        $db->commit();

        return "Success: Clinic status updated.";
    } catch (Exception $e) {
        // Rollback in case of an error
        if ($db && $db->inTransaction()) {
            $db->rollBack();
        }

        logError($e->getMessage(), $clinicId, $newStatus);
        return "Error: " . $e->getMessage();
    }
}

function verifyClinicExistence($clinicId) {
    // Simulate third-party API call to check clinic existence
    try {
        $response = file_get_contents("https://api.example.com/verifyClinic?clinic_id=" . urlencode($clinicId));

        if ($response === false) {
            throw new Exception('Failed to connect to the verification service.');
        }

        $data = json_decode($response, true);
        return isset($data['exists']) && $data['exists'];
    } catch (Exception $e) {
        logError("API Error: " . $e->getMessage(), $clinicId, null);
        return false;
    }
}

function getDatabaseConnection() {
    // Database connection logic
    try {
        $dsn = 'mysql:host=localhost;dbname=your_database_name;charset=utf8mb4';
        $username = 'your_username';
        $password = 'your_password';

        return new PDO($dsn, $username, $password);
    } catch (PDOException $e) {
        logError("Database Connection Error: " . $e->getMessage(), null, null);
        throw $e;
    }
}

function logError($message, $clinicId, $statusAttempted) {
    // Log error details with timestamp
    $timestamp = date('Y-m-d H:i:s');
    error_log("[$timestamp] Error for Clinic ID: $clinicId | Status Attempted: $statusAttempted | Message: $message" . PHP_EOL);
}
