        try:
            # Validate the format and structure of the command
            parsed_command = json.loads(command)
            required_keys = {"action", "criteria"}
            if not all(key in parsed_command for key in required_keys):
                raise ValueError("Command missing required keys")
            return True
        except (json.JSONDecodeError, ValueError) as e:
            print(f"Invalid command format: {e}")
            return False

    def process_commands(self, commands: List[str]):
        for command in commands:
            if self.validate_command(command):
                try:
                    parsed_command = json.loads(command)
                    action = parsed_command.get("action")
                    criteria = parsed_command.get("criteria")

                    if action == "filter":
                        self.filtered_sorted_reviews = self.filter_reviews(criteria)
                    elif action == "sort":
                        self.filtered_sorted_reviews = self.sort_reviews(self.filtered_sorted_reviews, criteria)
                    else:
                        print(f"Unknown action: {action}")

                except Exception as e:
                    print(f"Error processing command {command}: {e}")
            else:
                print("Skipping invalid command")

    def filter_reviews(self, criteria: Dict[str, Any]) -> List[Dict[str, Any]]:
        # Example filtering logic
        return [
            review for review in self.dataset
            if all(review.get(key) == value for key, value in criteria.items())
        ]

    def sort_reviews(self, reviews: List[Dict[str, Any]], criteria: Dict[str, str]) -> List[Dict[str, Any]]:
        # Example sorting logic
        try:
            return sorted(
                reviews,
                key=lambda review: tuple(review.get(key) for key in criteria.keys()),
                reverse=criteria.get('order', 'asc') == 'desc'
            )
        except Exception as e:
            print(f"Error sorting reviews: {e}")
            return reviews

    def update_dataset(self, new_reviews: List[Dict[str, Any]]):
        # Efficiently update the dataset with new reviews
        self.dataset.extend(new_reviews)

    def get_user_friendly_output(self) -> str:
        # Format output for easy navigation
        return json.dumps(self.filtered_sorted_reviews, indent=2)


