// JavaScript File Reader Module (fileReader.js)
const fs = require('fs');
const path = require('path');

class FileReader {
  constructor(directory) {
    this.directory = directory;
  }

  readFile(filePath, callback) {
    const fullPath = path.join(this.directory, filePath);

    fs.readFile(fullPath, { encoding: 'utf8' }, (err, data) => {
      if (err) {
        return callback(err);
      }
      callback(null, data);
    });
  }

  readFiles(filePaths, callback) {
    const promises = filePaths.map(filePath =>
      new Promise((resolve, reject) => {
        this.readFile(filePath, (err, data) => {
          if (err) return reject(err);
          resolve(data);
        });
      })
    );

    Promise.all(promises)
      .then(results => callback(null, results))
      .catch(error => callback(error));
  }
}

module.exports = FileReader;

// JavaScript Unit Tests for File Reader
const assert = require('assert');
const FileReader = require('./fileReader.js');

describe("FileReader", function() {
  let fileReader;

  beforeEach(function() {
    fileReader = new FileReader(__dirname);
  });

  it("should read a single file successfully", function(done) {
    fileReader.readFile('test.txt', (err, data) => {
      assert.ifError(err);
      assert.strictEqual(data.includes('Test Content'), true);
      done();
    });
  });

  it("should handle invalid file paths gracefully", function(done) {
    fileReader.readFile('invalid.txt', (err, _) => {
      assert.ok(err);
      done();
    });
  });

  it("should read multiple files concurrently", function(done) {
    fileReader.readFiles(['test1.txt', 'test2.txt'], (err, results) => {
      assert.ifError(err);
      assert.strictEqual(results.length, 2);
      done();
    });
  });
});
