<?php
// PHP Password Manager Module (PasswordManager.php)
class PasswordManager {
    private $hashAlgorithm;

    public function __construct($algorithm = PASSWORD_BCRYPT) {
        if (!in_array($algorithm, [PASSWORD_DEFAULT, PASSWORD_BCRYPT])) {
            throw new InvalidArgumentException("Unsupported hashing algorithm");
        }
        $this->hashAlgorithm = $algorithm;
    }

    public function generateSalt() {
        return bin2hex(random_bytes(16));
    }

    public function hashPassword($password) {
        return password_hash($password . $this->generateSalt(), $this->hashAlgorithm);
    }

    public function verifyPassword($password, $hash) {
        return password_verify($password, $hash);
    }
}

// PHP Unit Tests for Password Manager
class PasswordManagerTest extends PHPUnit\Framework\TestCase {

    private $passwordManager;

    protected function setUp(): void {
        $this->passwordManager = new PasswordManager();
    }

    public function testGenerateSalt() {
        $salt = $this->passwordManager->generateSalt();
        $this->assertIsString($salt);
        $this->assertEquals(32, strlen($salt));
    }

    public function testHashPassword() {
        $hash = $this->passwordManager->hashPassword('test');
        $this->assertTrue(password_verify('test' . substr($hash, 0, 32), $hash));
    }

    public function testVerifyPassword() {
        $password = 'securepassword';
        $hash = $this->passwordManager->hashPassword($password);

        $this->assertTrue($this->passwordManager->verifyPassword($password, $hash));
        $this->assertFalse($this->passwordManager->verifyPassword('wrongpassword', $hash));
    }
}
