const crypto = require('crypto');
const axios = require('axios');
const NodeCache = require('node-cache');
const { PassThrough } = require('stream');

// Cache setup with TTL and maximum size settings
const certificateCache = new NodeCache({ stdTTL: 300, checkperiod: 120, maxKeys: 100 });

async function fetchCertificate(uri) {
    try {
        const response = await axios.get(uri);
        return response.data;
    } catch (error) {
        throw new Error('Failed to fetch certificate from URI');
    }
}

function getCachedCertificate(key) {
    return certificateCache.get(key);
}

function setCachedCertificate(key, value) {
    certificateCache.set(key, value);
}

async function generatePEMCertificate(oauthRequest) {
    const { primaryURI, fallbackURI, requestId } = oauthRequest;

    if (!primaryURI || !requestId) {
        throw new Error('Invalid OAuth request: missing required parameters');
    }

    let certificate;
    try {
        // Attempt to fetch from primary URI
        certificate = await fetchCertificate(primaryURI);
    } catch (error) {
        console.warn(`Primary URI failed, attempting fallback: ${error.message}`);
        if (fallbackURI) {
            certificate = await fetchCertificate(fallbackURI);
        } else {
            throw new Error('Both primary and fallback URIs failed');
        }
    }

    // Cache the fetched certificate
    const cacheKey = `cert-${requestId}`;
    setCachedCertificate(cacheKey, certificate);

    return certificate;
}

class StreamHandler extends PassThrough {
    constructor(options) {
        super(options);
        this.paused = false;
        this.dataArray = [];
        this.pauseTimeout = null;

        this.on('data', (chunk) => {
            if (!this.paused) {
                this.dataArray.push(chunk);
            }
        });

        this.on('pause', () => {
            this.paused = true;
            clearTimeout(this.pauseTimeout);

            // Implement backpressure strategy
            this.pauseTimeout = setTimeout(() => {
                if (this.paused) {
                    console.log('Stream paused for too long, resuming...');
                    this.resume();
                }
            }, 10000); // Resume after 10 seconds of pause
        });

        this.on('resume', () => {
            this.paused = false;
            clearTimeout(this.pauseTimeout);
        });
    }

    saveData() {
        return this.dataArray.join('');
    }
}

module.exports = { generatePEMCertificate, StreamHandler };
```"]

