class CharacterAttackManager {
public:
    CharacterAttackManager() 
        : lastAttackTime(0), nextAnalyticsSendTime(std::chrono::steady_clock::now()) {
        attacks = { {"Slash", 7}, {"Punch", 9}, {"Kick", 11} };
        attackStats = {{"Slash", 0}, {"Punch", 0}, {"Kick", 0}};
    }

    void manageAttackSequence(GameState& gameState) {
        auto currentTime = std::chrono::steady_clock::now();

        if (isTimeToSendAnalytics(currentTime)) {
            sendAnalyticsData(attackStats);
            scheduleNextAnalyticsSend(currentTime);
        }

        if (gameState.isCritical() || canPerformAttack()) {
            performAttack(gameState, currentTime);
        }
    }

private:
    std::vector<Attack> attacks;
    std::unordered_map<std::string, int> attackStats;
    std::mutex mtx;
    std::chrono::steady_clock::time_point lastAttackTime;
    std::chrono::steady_clock::time_point nextAnalyticsSendTime;

    bool isTimeToSendAnalytics(const std::chrono::steady_clock::time_point& currentTime) {
        return currentTime >= nextAnalyticsSendTime;
    }

    void scheduleNextAnalyticsSend(const std::chrono::steady_clock::time_point& currentTime) {
        nextAnalyticsSendTime = currentTime + std::chrono::minutes(30);
    }

    bool canPerformAttack() const {
        auto now = std::chrono::steady_clock::now();
        return lastAttackTime == std::chrono::steady_clock::time_point{} || 
               std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime).count() >= cooldown;
    }

    void performAttack(GameState& gameState, const std::chrono::steady_clock::time_point& currentTime) {
        std::lock_guard<std::mutex> lock(mtx);

        Attack selectedAttack = selectAttack(gameState);
        lastAttackTime = currentTime;
        cooldown = selectedAttack.cooldownDuration;

        attackStats[selectedAttack.name]++;

        // Log or print the selected attack (for debugging)
        std::cout << "Performed attack: " << selectedAttack.name << std::endl;
    }

    Attack selectAttack(GameState& gameState) {
        static std::mt19937 rng(std::random_device{}());
        std::uniform_int_distribution<int> dist(0, 2);

        if (gameState.isCritical()) {
            return attacks[1]; // Prioritize "Punch" in critical state
        }

        int attackIndex = dist(rng);
        return attacks[attackIndex];
    }
};

// Example usage:
int main() {
    CharacterAttackManager manager;
    GameState gameState;

    while (true) {
        manager.manageAttackSequence(gameState);

        // Simulate time passing
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
```

### Key Points:
- **Cooldown Management**: Each attack has a cooldown period, and the last attack time is tracked to prevent rapid repeated attacks.
- **Random Attack Selection**: Attacks are chosen randomly unless in a critical state, where a specific attack ("Punch") is prioritized.
- **Analytics Integration**: Data on attack usage is sent every 30 minutes using a mockup function.
- **Concurrency and Performance**: A mutex ensures thread safety when updating shared resources like `lastAttackTime` and `attackStats`. The implementation uses efficient time management to minimize computational overhead.']

