using System;
using System.Threading;

public class DynamicRandom : IDisposable
{
    private readonly Random _random;
    private object _lock = new object();
    private int? _minInt, _maxInt;
    private double? _minDouble, _maxDouble;
    private bool _inclusiveIntegerBounds;

    public DynamicRandom()
    {
        _random = new Random();
    }

    public void SetSeed(int seed)
    {
        lock (_lock)
        {
            var newRandom = new Random(seed);
            // Copy internal state if possible for simplicity, actual implementation might differ
            Interlocked.Exchange(ref _random, newRandom);
        }
    }

    public bool ValidateRange(int? minInt, int? maxInt, double? minDouble, double? maxDouble)
    {
        lock (_lock)
        {
            if (minInt.HasValue && maxInt.HasValue && minInt >= maxInt) return false;
            if (minDouble.HasValue && maxDouble.HasValue && (minDouble >= maxDouble)) return false;
            _minInt = minInt;
            _maxInt = AdjustRangeIfNeeded(minInt, maxInt);
            _minDouble = minDouble;
            _maxDouble = AdjustRangeIfNeeded(minDouble, maxDouble);
        }

        return true;
    }

    private T? AdjustRangeIfNeeded<T>(T? minValue, T? maxValue) where T : struct
    {
        if (minValue.HasValue && maxValue.HasValue)
        {
            Type type = typeof(T);

            if (type == typeof(int))
            {
                if (minValue > maxValue)
                    return new T?(Convert.ToInt32(minValue) + 1);
            }
            else if (type == typeof(double))
            {
                if (minValue >= maxValue)
                    return new T?(Convert.ToDouble(minValue) + Double.Epsilon);
            }
        }

        return maxValue;
    }

    public int? GenerateRandomInt(bool inclusive = false)
    {
        lock (_lock)
        {
            _inclusiveIntegerBounds = inclusive;

            if (!_minInt.HasValue || !_maxInt.HasValue) throw new InvalidOperationException("Invalid integer range");

            var minVal = _minInt.Value;
            var maxVal = _maxInt.Value + (inclusive ? 0 : 1);

            return _random.Next(minVal, maxVal);
        }
    }

    public double? GenerateRandomDouble()
    {
        lock (_lock)
        {
            if (!_minDouble.HasValue || !_maxDouble.HasValue) throw new InvalidOperationException("Invalid double range");

            var rnd = (double)_random.NextDouble();
            return _minDouble.Value + rnd * (_maxDouble.Value - _minDouble.Value);
        }
    }

    public string ToString()
    {
        lock (_lock)
        {
            return $"Integer Range: {_minInt} to {_maxInt}, Inclusive: {_inclusiveIntegerBounds}. " +
                   $"Double Range: {_minDouble} to {_maxDouble}.";
        }
    }

    // For integration with external data sources
    public bool UpdateRangeFromExternalSource(Func<int?, int?, double?, double?> fetchRange)
    {
        try
        {
            var range = fetchRange(_minInt, _maxInt, _minDouble, _maxDouble);
            return ValidateRange(range.Item1, range.Item2, range.Item3, range.Item4);
        }
        catch (Exception ex) when (ex is TimeoutException || ex is InvalidOperationException)
        {
            // Handle or log error as necessary
            return false;
        }
    }

    public void Dispose()
    {
        lock (_lock)
        {
            if (_random != null)
            {
                _random.Dispose();
                _random = null;
            }
        }
    }
}
