#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* processStringWithConstraints(const char *input, size_t sizeLimit, size_t maxMemoryThreshold) {
    if (input == NULL || sizeLimit == 0 || maxMemoryThreshold <= sizeof(char)) {
        return NULL;
    }

    size_t inputLength = strlen(input);

    if (inputLength > sizeLimit) {
        return NULL;
    }

    size_t newLength = inputLength + 2; // for null terminator and hyphen
    if (newLength > maxMemoryThreshold) {
        return NULL;
    }

    char *result = malloc(newLength);
    if (result == NULL) {
        return NULL;
    }

    strcpy(result, input);
    result[inputLength] = '-';
    result[newLength - 1] = '\0';

    return result;
}
