function extractMatchingElements(rootNode, selector, callback) {
    if (!rootNode || typeof selector !== 'string' || typeof callback !== 'function') {
        return [];
    }

    const matchedElements = [];

    function traverse(node) {
        if (!node) return;

        if (callback(node)) {
            if (node.matches(selector)) {
                matchedElements.push(node);
            }
        }

        node.childNodes.forEach(child => traverse(child));
    }

    traverse(rootNode);

    return matchedElements;
}
