#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <jansson.h> // For JSON handling

#define MAX_EVENTS 1000
#define CACHE_SIZE 1024 * 1024 * 10 // 10 MB cache size limit
#define EVENT_EXPIRY_DAYS 30
#define JSON_EXPORT_INTERVAL 60 // seconds

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int packet_size;
    char event_type[32];
    int cumulative_packet_size;
} NetworkEvent;

typedef struct CacheNode {
    NetworkEvent event;
    time_t last_accessed;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode** buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
    size_t current_memory_usage;
    void (*purge_callback)(void);
} EventCache;

NetworkEvent parse_log_entry(const char* line) {
    NetworkEvent event = {0};
    sscanf(line, "%ld %15s %15s %d %31s",
           &event.timestamp,
           event.source_ip,
           event.destination_ip,
           &event.packet_size,
           event.event_type);
    return event;
}

int is_event_recent(NetworkEvent* event) {
    time_t now = time(NULL);
    double seconds_in_day = 86400.0;
    time_t cutoff = now - (EVENT_EXPIRY_DAYS * seconds_in_day);
    return event->timestamp >= cutoff;
}

unsigned long hash_ip(const char* ip) {
    unsigned long hash = 5381;
    int c;
    while ((c = *ip++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

void cache_init(EventCache* cache, size_t bucket_count, void (*purge_callback)(void)) {
    cache->buckets = calloc(bucket_count, sizeof(CacheNode*));
    cache->bucket_count = bucket_count;
    pthread_mutex_init(&cache->lock, NULL);
    cache->current_memory_usage = 0;
    cache->purge_callback = purge_callback;
}

CacheNode* create_cache_node(NetworkEvent event) {
    CacheNode* node = malloc(sizeof(CacheNode));
    node->event = event;
    node->last_accessed = time(NULL);
    node->next = NULL;
    return node;
}

void insert_event(EventCache* cache, NetworkEvent event) {
    unsigned long hash = hash_ip(event.source_ip) ^ hash_ip(event.destination_ip);
    unsigned int bucket_index = hash % cache->bucket_count;

    pthread_mutex_lock(&cache->lock);

    CacheNode** head = &cache->buckets[bucket_index];
    while (*head) {
        if ((*head)->event.timestamp == event.timestamp &&
            strcmp((*head)->event.source_ip, event.source_ip) == 0 &&
            strcmp((*head)->event.destination_ip, event.destination_ip) == 0) {
            // Update existing node
            (*head)->event.packet_size = event.packet_size;
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        head = &(*head)->next;
    }

    CacheNode* new_node = create_cache_node(event);

    if (new_node) {
        *head = new_node;
        cache->current_memory_usage += sizeof(CacheNode) + sizeof(NetworkEvent);
    }

    pthread_mutex_unlock(&cache->lock);
}

void purge_least_accessed(EventCache* cache) {
    pthread_mutex_lock(&cache->lock);

    time_t now = time(NULL);

    for (size_t i = 0; i < cache->bucket_count; ++i) {
        CacheNode** node = &cache->buckets[i];
        CacheNode* prev = NULL;

        while (*node) {
            if ((*node)->last_accessed < now - EVENT_EXPIRY_DAYS * 86400 ||
                (cache->current_memory_usage > CACHE_SIZE && !prev)) {

                CacheNode* to_delete = *node;
                *node = (*node)->next;
                free(to_delete);

                cache->current_memory_usage -= sizeof(CacheNode) + sizeof(NetworkEvent);
            } else {
                prev = *node;
                node = &(*node)->next;
            }
        }
    }

    pthread_mutex_unlock(&cache->lock);
}

void export_to_json(EventCache* cache, const char* filename) {
    json_t* root = json_array();
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->bucket_count; ++i) {
        CacheNode* node = cache->buckets[i];
        while (node) {
            json_t* event_json = json_object();

            json_object_set_new(event_json, "timestamp", json_integer(node->event.timestamp));
            json_object_set_new(event_json, "source_ip", json_string(node->event.source_ip));
            json_object_set_new(event_json, "destination_ip", json_string(node->event.destination_ip));
            json_object_set_new(event_json, "packet_size", json_integer(node->event.packet_size));
            json_object_set_new(event_json, "event_type", json_string(node->event.event_type));

            json_array_append_new(root, event_json);

            if (json_array_size(root) >= MAX_EVENTS) {
                break;
            }

            node = node->next;
        }
    }

    pthread_mutex_unlock(&cache->lock);

    FILE* fp = fopen(filename, "w");
    if (!fp) return;

    char* json_dump = json_dumps(root, JSON_INDENT(2));
    fprintf(fp, "%s", json_dump);
    fclose(fp);
    free(json_dump);

    json_decref(root);
}

void* cache_maintenance(void* arg) {
    EventCache* cache = (EventCache*)arg;

    while (1) {
        sleep(JSON_EXPORT_INTERVAL);

        purge_least_accessed(cache);
        export_to_json(cache, "recent_events.json");
    }

    return NULL;
}

int main() {
    EventCache cache;
    cache_init(&cache, 128, NULL);

    pthread_t maintenance_thread;
    pthread_create(&maintenance_thread, NULL, cache_maintenance, &cache);

    FILE* log_file = fopen("network_log.txt", "r");
    if (!log_file) return 1;

    char line[256];
    while (fgets(line, sizeof(line), log_file)) {
        NetworkEvent event = parse_log_entry(line);
        if (is_event_recent(&event)) {
            insert_event(&cache, event);
        }
    }

    fclose(log_file);

    pthread_join(maintenance_thread, NULL);
    return 0;
}
```']

