#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#define THEME_CACHE_PATH "theme_cache"
#define DEFAULT_THEME_DIR "default_theme"

typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AESCipherContext;

int create_directory_if_not_exists(const char* path) {
    struct stat st = {0};

    if (stat(path, &st) == -1) {
        return mkdir(path, 0700);
    }
    return 0;
}

EACS_CIPHER_CTX init_aes_256_cbc_cipher(const char *passphrase) {
    AESCipherContext ctx;
    memset(&ctx, 0, sizeof(ctx));

    unsigned char key[EVP_MAX_KEY_LENGTH];
    if (SHA256((unsigned char*)passphrase, strlen(passphrase), key) != SHA256_DIGEST_LENGTH) {
        fprintf(stderr, "Error deriving key from passphrase\n");
        return NULL;
    }

    if (!RAND_bytes(ctx.iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc()))) {
        fprintf(stderr, "Error generating random IV\n");
        return NULL;
    }

    ctx.cipher_ctx = EVP_CIPHER_CTX_new();
    if (ctx.cipher_ctx == NULL) {
        fprintf(stderr, "Error creating cipher context\n");
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx.cipher_ctx, EVP_aes_256_cbc(), NULL, key, ctx.iv)) {
        fprintf(stderr, "Error initializing cipher\n");
        EVP_CIPHER_CTX_free(ctx.cipher_ctx);
        return NULL;
    }

    int dir_check = create_directory_if_not_exists(THEME_CACHE_PATH);
    if (dir_check != 0) {
        fprintf(stderr, "Failed to ensure theme cache directory exists\n");
        EVP_CIPHER_CTX_free(ctx.cipher_ctx);
        return NULL;
    }

    char default_theme_path[256];
    snprintf(default_theme_path, sizeof(default_theme_path), "%s/%s", THEME_CACHE_PATH, DEFAULT_THEME_DIR);

    dir_check = create_directory_if_not_exists(default_theme_path);
    if (dir_check != 0) {
        fprintf(stderr, "Failed to ensure default theme directory exists\n");
        EVP_CIPHER_CTX_free(ctx.cipher_ctx);
        return NULL;
    }

    // Logic to parse and cache PNG files can be added here

    return &ctx;
}

void cleanup_aes_cipher(AESCipherContext *cipher_context) {
    if (cipher_context && cipher_context->cipher_ctx) {
        EVP_CIPHER_CTX_free(cipher_context->cipher_ctx);
    }
    memset(cipher_context, 0, sizeof(*cipher_context));
}
```

This C code initializes an AES-256-CBC cipher using a given passphrase, manages theme directories and caches, and includes cleanup logic for the cipher context.']

