int is_valid_timestamp(time_t expiration_time) {
    time_t now = time(NULL);
    return expiration_time > now;  // Check if the timestamp is in the future
}

int validate_session(const char *json_payload) {
    json_error_t error;
    json_t *root = json_loads(json_payload, 0, &error);

    if (!root) {
        log_error("Malformed JSON");
        return 0; // Invalid session due to malformed JSON
    }

    json_t *user_id = json_object_get(root, "user_id");
    json_t *expiration_time = json_object_get(root, "expiration_time");
    json_t *session_token = json_object_get(root, "session_token");

    if (!json_is_string(user_id) || !json_is_integer(expiration_time) ||
        !json_is_string(session_token)) {
        log_error("Missing or invalid required fields");
        json_decref(root);
        return 0;
    }

    const char *token_str = json_string_value(session_token);
    if (!is_session_token_unique(token_str)) {
        log_error("Duplicate session token");
        json_decref(root);
        return 0;
    }

    time_t exp_time = (time_t)json_integer_value(expiration_time);
    if (!is_valid_timestamp(exp_time)) {
        log_error("Invalid expiration time");
        json_decref(root);
        return 0;
    }

    // Optional: validate refresh_token, etc.

    json_decref(root);
    return 1; // Valid session
}
