using System;
using System.Data;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicRandom : IDisposable
{
    private static readonly object lockObject = new object();
    private Random _random;
    private double _minDouble;
    private double _maxDouble;
    private long _minLong;
    private long _maxLong;
    private bool _disposed = false;

    public DynamicRandom()
    {
        _random = new Random();
    }

    public void SetSeed(long seed)
    {
        lock (lockObject)
        {
            _random = new Random((int)seed);
        }
    }

    public void SetRange(double min, double max)
    {
        ValidateRange(min, max);
        _minDouble = Math.Min(min, max);
        _maxDouble = Math.Max(min, max);
    }

    public void SetRange(long min, long max)
    {
        ValidateRange(min, max);
        _minLong = Math.Min(min, max);
        _maxLong = Math.Max(min, max);
    }

    public double NextDouble()
    {
        lock (lockObject)
        {
            return _random.NextDouble() * (_maxDouble - _minDouble) + _minDouble;
        }
    }

    public long NextInt64()
    {
        lock (lockObject)
        {
            if (_minLong == _maxLong)
                return _minLong;

            var range = (long)(_maxLong - _minLong);
            if (range < 0)
                throw new InvalidOperationException("Range overflow.");

            var diff = unchecked((long)_random.Next() << 32) | _random.Next();
            return (_minLong + (diff % (range + 1)));
        }
    }

    public override string ToString()
    {
        lock (lockObject)
        {
            return $"DynamicRandom: Int64 Range [{_minLong}, {_maxLong}], Double Range [{_minDouble}, {_maxDouble}]";
        }
    }

    private void ValidateRange(double min, double max)
    {
        if (double.IsInfinity(min) || double.IsInfinity(max) ||
            double.IsNaN(min) || double.IsNaN(max))
            throw new ArgumentOutOfRangeException(nameof(min), "Invalid range values.");

        if (_minDouble > _maxDouble && _minLong > _maxLong)
            throw new ArgumentOutOfRangeException("Minimum value cannot be greater than maximum value.");
    }

    private void ValidateRange(long min, long max)
    {
        if (long.IsNegativeInfinity(min) || long.IsPositiveInfinity(max))
            throw new ArgumentOutOfRangeException(nameof(min), "Invalid range values.");

        if (_minLong > _maxLong && _minDouble > _maxDouble)
            throw new ArgumentOutOfRangeException("Minimum value cannot be greater than maximum value.");
    }

