using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Base64MessageProcessor
{
    private const int MaxRetries = 3;

    public Dictionary<int, string> ProcessMessages(string input, string delimiter, byte[] key, byte[] iv)
    {
        var result = new Dictionary<int, string>();

        // Split the input into base64 messages
        var messages = input.Split(new[] { delimiter }, StringSplitOptions.RemoveEmptyEntries);

        for (int i = 0; i < messages.Length; i++)
        {
            string messageIdStr = $"Message_{i}";
            string encodedMessage = messages[i];

            if (!IsValidBase64String(encodedMessage))
            {
                LogError($"Invalid Base64 format: {messageIdStr}");
                result[Convert.ToInt32(messageIdStr.Replace("Message_", ""))] = "Corrupted";
                continue;
            }

            int retryCount = 0;
            bool success = false;

            while (retryCount < MaxRetries && !success)
            {
                try
                {
                    string decryptedMessage = DecryptTripleDes(encodedMessage, key, iv);
                    result[i] = decryptedMessage;
                    success = true;
                }
                catch (CryptographicException ex)
                {
                    LogError($"Decryption failed for {messageIdStr} on attempt {retryCount + 1}: {ex.Message}");
                    retryCount++;
                    if (retryCount == MaxRetries)
                    {
                        result[i] = "Corrupted";
                    }
                }
            }
        }

        return result;
    }

    private bool IsValidBase64String(string base64)
    {
        // Validate that the string is a valid Base64 format and within limits
        try
        {
            Convert.FromBase64String(base64);
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
        catch (ArgumentException)
        {
            return false;
        }
    }

    private string DecryptTripleDes(string base64EncodedData, byte[] key, byte[] iv)
    {
        // Triple DES decryption
        byte[] buffer = Convert.FromBase64String(base64EncodedData);

        using (var tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;

            ICryptoTransform decryptor = tripleDES.CreateDecryptor(tripleDES.Key, tripleDES.IV);

            using (var ms = new MemoryStream(buffer))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (var sr = new StreamReader(cs))
            {
                return sr.ReadToEnd();
            }
        }
    }

    private void LogError(string message)
    {
        // Placeholder for logging mechanism
        Console.WriteLine(message);
    }
}
