using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class TextFileProcessor
{
    public ConcurrentDictionary<string, string> ProcessTextFile(string filePath, Func<string, bool> filterCriteria = null)
    {
        var results = new ConcurrentDictionary<string, string>();

        try
        {
            using (var reader = new StreamReader(filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    // Apply filtering criteria if provided
                    if (filterCriteria == null || filterCriteria(line))
                    {
                        var hash = ComputeSha256Hash(line);

                        // Store the original line and its hash in a thread-safe dictionary
                        results.TryAdd(hash, line);
                    }
                }
            }
        }
        catch (IOException ex)
        {
            Console.WriteLine($"I/O error occurred: {ex.Message}");
            // Implement retry logic or other recovery strategies if needed.
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An unexpected error occurred: {ex.Message}");
        }

        return results;
    }

    private string ComputeSha256Hash(string input)
    {
        using (var sha256 = SHA256.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            var hashBytes = sha256.ComputeHash(bytes);

            // Convert byte array to a hexadecimal string
            var stringBuilder = new StringBuilder();
            foreach (var b in hashBytes)
            {
                stringBuilder.Append(b.ToString("x2"));
            }

            return stringBuilder.ToString();
        }
    }
}

// Usage example:
// TextFileProcessor processor = new TextFileProcessor();
// var resultDictionary = processor.ProcessTextFile("path/to/largefile.txt", line => line.Length > 10);
