['```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    private readonly ILogger _logger; // Assume this is injected through dependency injection

    public AesCbcDecryptor(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public byte[] Decrypt(
        byte[] ciphertext,
        byte[] key,
        byte[] iv,
        byte[] hmacKey,
        byte[] expectedHmac)
    {
        if (ciphertext == null || key == null || iv == null ||
            hmacKey == null || expectedHmac == null)
        {
            _logger.LogError("Null input parameters provided.");
            return null;
        }

        if (key.Length != 16 && key.Length != 24 && key.Length != 32) // AES-128, AES-192, AES-256
        {
            _logger.LogError("Invalid encryption key length.");
            return null;
        }

        if (iv.Length != 16)
        {
            _logger.LogError("Invalid IV length.");
            return null;
        }

        try
        {
            using (_logger.LogOperationStart())
            {
                byte[] decryptedData = DecryptAesCbc(ciphertext, key, iv);

                // Verify HMAC
                if (!VerifyHmac(decryptedData, hmacKey, expectedHmac))
                {
                    _logger.LogError("Integrity check failed.");
                    return null;
                }

                return decryptedData;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption error occurred.");
            return null;
        }
    }

    private byte[] DecryptAesCbc(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        using (var memoryStream = new MemoryStream(ciphertext))
        using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
        {
            const int bufferSize = 1024 * 64; // 64KB buffer
            var decryptedData = new List<byte>();

            while (memoryStream.Position < memoryStream.Length)
            {
                byte[] buffer = new byte[bufferSize];
                int bytesRead = cryptoStream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0) 
                    decryptedData.AddRange(buffer[..bytesRead]);
            }

            return decryptedData.ToArray();
        }
    }

    private bool VerifyHmac(byte[] data, byte[] hmacKey, byte[] expectedHmac)
    {
        using var hmac = new HMACSHA256(hmacKey);
        byte[] computedHmac = hmac.ComputeHash(data);

        return StructuralComparisons.StructuralEqualityComparer.Equals(computedHmac, expectedHmac);
    }
}

