        _currentOperation = new OperationScope(this);
        return _currentOperation;
    }

    public void Dispose() => Console.WriteLine("Logger disposed.");

    private class OperationScope : IDisposable
    {
        private readonly SimpleLogger _logger;

        public OperationScope(SimpleLogger logger)
        {
            _logger = logger;
            Console.WriteLine($"[{DateTime.Now}] Starting operation.");
        }

        public void Dispose()
        {
            Console.WriteLine($"[{DateTime.Now}] Ending operation.");
        }
    }
}
