['```rust
use tokio::time::{sleep, Duration};
use reqwest::Client;
use log::{info, warn, error};
use simplelog::*;
use std::env;

const MAX_RETRIES: u32 = 5;

struct Logger {
    client: Client,
}

impl Logger {
    fn new() -> Self {
        Self { client: Client::new() }
    }

    async fn fetch_data(&self, url: &str) -> Result<String, reqwest::Error> {
        let mut retries = 0;
        loop {
            match self.client.get(url).send().await {
                Ok(response) => return response.text().await,
                Err(e) if retries < MAX_RETRIES => {
                    warn!("Network error: {}. Retrying in {}ms...", e, (2_u32.pow(retries as u32)) * 100);
                    sleep(Duration::from_millis((2_u32.pow(retries as u32)) * 100)).await;
                    retries += 1;
                }
                Err(e) => {
                    error!("Failed to fetch data after {} attempts: {}", MAX_RETRIES, e);
                    return Err(e);
                }
            }
        }
    }

    async fn execute(&self, command: &str) -> Result<(), Box<dyn std::error::Error>> {
        match command {
            "fetch" => {
                let url = "https://api.example.com/data";
                if let Ok(data) = self.fetch_data(url).await {
                    info!("Fetched data: {}", data);
                }
            }
            _ => error!("Unknown command: {}", command),
        }
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    CombinedLogger::init(vec![
        TermLogger::new(LevelFilter::Info, Config::default(), TerminalMode::Mixed).unwrap(),
        WriteLogger::new(LevelFilter::Info, Config::default(), File::create("app.log")?),
    ]).unwrap();

    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        error!("No command provided");
        return Ok(());
    }

    let logger = Logger::new();
    let command = &args[1];

    tokio::runtime::Runtime::new()?.block_on(async {
        if let Err(e) = logger.execute(command).await {
            error!("Error executing command: {}", e);
        }
    });

    Ok(())
}
```']

