        }
    }

    fn create_directory(&self, name: &str) -> Result<(), String> {
        let path = if let Ok(existing_path) = env::var(&self.env_var) {
            info!("Environment variable already set. Using existing directory: {}", existing_path);
            Some(existing_path)
        } else {
