            self.enforce_creation_limit()?;

            let new_dir = format!("{}/{}", env::current_dir()?.display(), name);
            DirBuilder::new().recursive(true).create(&new_dir)?;
            info!("Created new directory: {}", new_dir);

            Some(new_dir)
        };

        if let Some(dir_path) = path {
