        Ok(())
    }

    fn enforce_creation_limit(&self) -> Result<(), String> {
        let mut times = self.directory_creation_times.lock().unwrap();
        let now = SystemTime::now();

        times.retain(|&t| t.elapsed().unwrap() < Duration::new(60, 0));

        if times.len() as u32 >= self.max_directories_per_minute {
            error!("Reached maximum directory creation limit per minute.");
            return Err("Max directory creation rate exceeded".into());
        }

        times.push(now);
        Ok(())
    }
}

