import json
from typing import Any, Dict, Type, Callable
from abc import ABC, abstractmethod
import threading
import logging

# Setup logging
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)

class ValidationError(Exception):
    pass

class BaseConfig(ABC):
    _registry_lock = threading.Lock()

    def __init__(self, **kwargs):
        self.fields = {}
        for field_name in self._fields:
            if field_name in kwargs:
                value = kwargs[field_name]
                expected_type = self._field_types[field_name]
                self._validate_field(field_name, value, expected_type)
                self.fields[field_name] = value
            elif self._field_defaults.get(field_name) is not None:
                self.fields[field_name] = self._field_defaults[field_name]

    @classmethod
    def _validate_field(cls, field: str, value: Any, expected_type: Type):
        if not isinstance(value, expected_type):
            raise ValidationError(f"Field '{field}' must be of type {expected_type.__name__}")
        # Add more validation logic if needed

    @classmethod
    @abstractmethod
    def _create_subclass(cls, config_id: str, fields: Dict[str, Type], defaults: Dict[str, Any] = None):
        """Create subclass dynamically with provided fields and default values."""
        name = f"Config_{config_id}"
        attrs = {
            '_fields': fields.keys(),
            '_field_types': fields,
            '_field_defaults': defaults or {}
        }
        return type(name, (cls,), attrs)

    @classmethod
    def register(cls, config_id: str, subclass: Type['BaseConfig']):
        """Register a new subclass."""
        with cls._registry_lock:
            if config_id in cls._registry:
                raise ValueError(f"Configuration ID '{config_id}' is already registered.")
            cls._registry[config_id] = subclass

    @classmethod
    def get_class(cls, config_id: str) -> Type['BaseConfig']:
        """Get the class for a given configuration ID."""
        with cls._registry_lock:
            if config_id not in cls._registry:
                raise KeyError(f"Configuration ID '{config_id}' is not registered.")
            return cls._registry[config_id]

    _registry = {}

class ConfigManager(BaseConfig):
    @classmethod
    def load_config(cls, config_json: str) -> BaseConfig:
        try:
            config_dict = json.loads(config_json)
            config_type = config_dict.get("type")
            if not config_type:
                raise ValueError("Configuration type is missing.")

            subclass = cls.get_class(config_type)
            return subclass(**config_dict)

        except (json.JSONDecodeError, KeyError) as e:
            logger.error(f"Failed to load configuration: {e}")
            raise

    @classmethod
    def create_dynamic_config(cls, config_id: str, fields: Dict[str, Type], defaults: Dict[str, Any] = None):
        """Create and register a dynamic subclass."""
        new_class = cls._create_subclass(config_id, fields, defaults)
        cls.register(config_id, new_class)

# Example usage:

# Define a new configuration dynamically
ConfigManager.create_dynamic_config(
    "ExampleConfig",
    {
        "name": str,
        "value": int,
        "active": bool
    },
    {
        "active": True
    }
)

# Create an instance of the dynamic config
config_json = json.dumps({
    "type": "ExampleConfig",
    "name": "Sample",
    "value": 42
})
config_instance = ConfigManager.load_config(config_json)
print(config_instance.fields)
```

This code snippet provides a framework for managing JSON-based configurations with support for dynamic subclass creation and registration. It includes validation, logging, and a centralized registry mechanism for handling different configuration types.']

