['Below is a C function that fulfills your requirements. It initializes an array of `NFAPI_MESSAGE_PDU_T` structures with appropriate values, simulates channel conditions to calculate SNR, and uses threading mechanisms for concurrent access.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_UES 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int SNR_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    NFAPI_MESSAGE_PDU_T *ue_array;
    size_t num_ues;
    pthread_mutex_t lock;
    double avg_snr;
    double min_snr;
    double max_snr;
} ChannelContext;

void calculate_snr(int *snr) {
    // Simulate radio channel model with random noise
    static const int noise_range = 10; 
    *snr = rand() % (2 * noise_range + 1) - noise_range;
}

void update_statistics(ChannelContext *context) {
    double sum = 0;
    double min = context->ue_array[0].SNR_INDICATION_REL8_TAG;
    double max = context->ue_array[0].SNR_INDICATION_REL8_TAG;

    for (size_t i = 0; i < context->num_ues; ++i) {
        int snr = context->ue_array[i].SNR_INDICATION_REL8_TAG;
        sum += snr;
        if (snr < min) min = snr;
        if (snr > max) max = snr;
    }

    pthread_mutex_lock(&context->lock);
    context->avg_snr = sum / context->num_ues;
    context->min_snr = min;
    context->max_snr = max;
    pthread_mutex_unlock(&context->lock);
}

void *update_ue_snr(void *arg) {
    ChannelContext *ctx = (ChannelContext *)arg;

    while (1) { // Simulate periodic updates
        for (size_t i = 0; i < ctx->num_ues; ++i) {
            calculate_snr(&ctx->ue_array[i].SNR_INDICATION_REL8_TAG);
        }

        update_statistics(ctx);

        sleep(5); // Update every 5 seconds
    }

    return NULL;
}

ChannelContext* initialize_channel(size_t max_ues) {
    ChannelContext *context = malloc(sizeof(ChannelContext));
    if (!context) {
        perror("Failed to allocate memory for channel context");
        exit(EXIT_FAILURE);
    }

    context->ue_array = calloc(max_ues, sizeof(NFAPI_MESSAGE_PDU_T));
    if (!context->ue_array) {
        free(context);
        perror("Failed to allocate memory for UE array");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&context->lock, NULL);

    // Initialize UEs with random values
    srand(time(NULL));
    for (size_t i = 0; i < max_ues; ++i) {
        context->ue_array[i].RX_UE_INFORMATION_TAG = rand();
        context->ue_array[i].RNTI = rand() & 0xFFFF;
        context->ue_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        calculate_snr(&context->ue_array[i].SNR_INDICATION_REL8_TAG);
    }

    context->num_ues = max_ues;

    return context;
}

void cleanup_channel(ChannelContext *ctx) {
    free(ctx->ue_array);
    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}

int main() {
    size_t max_ues = MAX_UES;
    ChannelContext *channel = initialize_channel(max_ues);

    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, update_ue_snr, channel)) {
        perror("Failed to create SNR update thread");
        cleanup_channel(channel);
        exit(EXIT_FAILURE);
    }

    // Simulate running for a while
    sleep(30);

    pthread_cancel(update_thread);  // Clean up the update thread (simplification)
    pthread_join(update_thread, NULL);

    printf("Avg SNR: %.2f\n", channel->avg_snr);
    printf("Min SNR: %.2f\n", channel->min_snr);
    printf("Max SNR: %.2f\n", channel->max_snr);

    cleanup_channel(channel);

    return 0;
}
```

### Key Points:
- **Thread Safety:** The use of a `pthread_mutex_t` ensures that statistics updates are thread-safe.
- **Dynamic Memory Allocation:** Allocates memory for UE structures dynamically to support configurable number of UEs (`max_ues`).
- **SNR Calculation and Update:** SNR values are periodically updated in a separate thread simulating real-world channel conditions using random noise.
- **Statistics Reporting:** Calculates average, minimum, and maximum SNR values across all UEs and reports them.
- **Concurrency Handling:** Uses a mutex to handle concurrent access to shared data (SNR statistics).

This solution assumes a single-threaded main process with a separate thread for periodic updates. In practice, you might need more sophisticated concurrency handling if multiple threads modify the UE array concurrently beyond just reading statistics.']

