    // Static Mersenne Twister instance to generate random numbers.
    static std::mt19937 mt_engine;

    // Constructor to initialize the records with given parameters.
    DataProcessingFramework(size_t num_records, double min_value, double max_value)
        : records_(num_records), min_value_(min_value), max_value_(max_value) {

        validateAndInitializeRecords();
