['Here's a C function that manages LTE UE contexts with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UE_ID 1000

typedef struct {
    int message_id;
} RRC_CONNECTION_RECONFIGURATION_COMPLETE;

typedef struct {
    int ue_id;
    char rrc_connection_state[20];
    RRC_CONNECTION_RECONFIGURATION_COMPLETE *reconfig_messages;
    size_t num_reconfig_messages;
} UEContext;

typedef struct {
    UEContext *contexts[MAX_UE_ID];
    pthread_mutex_t lock;
} UEManager;

// Initialize the UE manager
void init_ue_manager(UEManager *manager) {
    for (int i = 0; i < MAX_UE_ID; ++i) {
        manager->contexts[i] = NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

// Add or update a UE context
void add_or_update_ue_context(UEManager *manager, int ue_id, const char *new_state, RRC_CONNECTION_RECONFIGURATION_COMPLETE new_message) {
    pthread_mutex_lock(&manager->lock);

    UEContext **context = &manager->contexts[ue_id];

    if (*context == NULL) {
        // Allocate a new context
        *context = (UEContext *)malloc(sizeof(UEContext));
        if (*context == NULL) {
            fprintf(stderr, "Memory allocation failed for UE context\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        (*context)->ue_id = ue_id;
        strncpy((*context)->rrc_connection_state, new_state, sizeof((*context)->rrc_connection_state));
        (*context)->num_reconfig_messages = 0;
    }

    // Update RRC state
    strncpy((*context)->rrc_connection_state, new_state, sizeof((*context)->rrc_connection_state));

    // Add the new reconfiguration message
    *context = (UEContext *)realloc(*context, sizeof(UEContext) + (*context)->num_reconfig_messages * sizeof(RRC_CONNECTION_RECONFIGURATION_COMPLETE) + sizeof(RRC_CONNECTION_RECONFIGURATION_COMPLETE));
    if (*context == NULL) {
        fprintf(stderr, "Memory reallocation failed for UE context\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    (*context)->reconfig_messages[(*context)->num_reconfig_messages] = new_message;
    ++((*context)->num_reconfig_messages);

    pthread_mutex_unlock(&manager->lock);
}

// Clean up the UE manager
void cleanup_ue_manager(UEManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_UE_ID; ++i) {
        if (manager->contexts[i] != NULL) {
            free(manager->contexts[i]);
            manager->contexts[i] = NULL;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    UEManager manager;
    init_ue_manager(&manager);

    RRC_CONNECTION_RECONFIGURATION_COMPLETE message1 = { .message_id = 1 };
    add_or_update_ue_context(&manager, 1, "CONNECTED", message1);

    RRC_CONNECTION_RECONFIGURATION_COMPLETE message2 = { .message_id = 2 };
    add_or_update_ue_context(&manager, 1, "RECONFIGURED", message2);

    cleanup_ue_manager(&manager);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that the function can handle concurrent access safely.
- **Memory Management**: Dynamic allocation and reallocation are used to manage memory efficiently, with checks for allocation failures.
- **Scalability**: The design allows for scaling by using a fixed-size array indexed by UE-ID, which can be adjusted based on expected load.
- **Error Handling**: Basic error handling is implemented for memory operations.']

['```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.time.Instant;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Logger;
import java.util.logging.Level;

class InvalidInputException extends RuntimeException {
    public InvalidInputException(String message) {
        super(message);
    }
}

public class UniqueIdentifierGenerator {

    private static final Logger logger = Logger.getLogger(UniqueIdentifierGenerator.class.getName());
    private static final AtomicLong sequenceNumber = new AtomicLong();
    private static final ConcurrentHashMap<String, String> identifierMap = new ConcurrentHashMap<>();

    public static synchronized String generateUniqueId(String input) {
        if (input == null || input.trim().isEmpty()) {
            throw new InvalidInputException("Input cannot be null or empty.");
        }

        String uniqueId;
        do {
            uniqueId = createIdentifier(input);
        } while (!identifierMap.putIfAbsent(uniqueId, Instant.now().toString()).isEmpty());

        logger.log(Level.INFO, "Generated Unique ID: {0} at {1}", new Object[]{uniqueId, Instant.now()});

        return uniqueId;
    }

    private static String createIdentifier(String input) {
        long seqNum = sequenceNumber.incrementAndGet();
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest((input + seqNum).getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to generate hash", e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        try {
            String id = generateUniqueId("exampleUserInput");
            System.out.println("Generated ID: " + id);
        } catch (InvalidInputException e) {
            System.err.println(e.getMessage());
        }
    }
}
