['```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <chrono>

struct Transaction {
    int id;
    long long timestamp;  // Using long long for precise timestamps.
    double weightedValue;
};

// Union-Find Data Structure with Path Compression and Union by Rank.
class UnionFind {
private:
    std::vector<int> parent, rank;

public:
    UnionFind(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV])
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

    bool connected(int u, int v) {
        return find(u) == find(v);
    }
};

struct Result {
    double maxWeightedSum;
    int transactionID;
    int disjointPairsCount;
    double averageProcessingTimePerDisjointCheck; // in milliseconds
};

Result processTransactions(const std::vector<Transaction>& transactions) {
    const long long timeWindow = 3000000LL; // 3 seconds in microseconds.
    std::priority_queue<std::pair<long long, Transaction>> transactionQueue;
    std::unordered_map<int, bool> activeTransactions;
    double maxWeightedSum = -1.0;
    int transactionIDWithMaxWeight = -1;

    std::vector<std::chrono::milliseconds> disjointCheckTimes; // To record processing times for checks.
    int totalDisjointPairs = 0;

    auto currentTime = std::chrono::steady_clock::now().time_since_epoch().count();
    UnionFind uf(transactions.size());

    for (const auto& transaction : transactions) {
        long long age = currentTime - transaction.timestamp;

        // Filter transactions based on age and add to priority queue.
        if (age <= timeWindow) {
            transactionQueue.emplace(transaction.timestamp, transaction);

            while (!transactionQueue.empty() && currentTime - transactionQueue.top().first > timeWindow) {
                transactionQueue.pop();
            }

            int numTransactionsInLastThreeSeconds = transactionQueue.size();

            // Process each transaction only if it meets the condition for the number of transactions in the last 3 seconds.
            if (numTransactionsInLastThreeSeconds <= 10000) {
                activeTransactions[transaction.id] = true;

                double currentWeightedSum = 0.0;

                // Check disjoint pairs and calculate processing time.
                auto start = std::chrono::steady_clock::now();
                for (const auto& [activeID, _] : activeTransactions) {
                    if (!uf.connected(transaction.id, activeID)) {
                        uf.unite(transaction.id, activeID);
                        ++totalDisjointPairs;

                        auto end = std::chrono::steady_clock::now();
                        disjointCheckTimes.push_back(std::chrono::duration_cast<std::chrono::milliseconds>(end - start));
                    }
                }

                // Update the max weighted sum.
                currentWeightedSum += transaction.weightedValue;
                if (currentWeightedSum > maxWeightedSum) {
                    maxWeightedSum = currentWeightedSum;
                    transactionIDWithMaxWeight = transaction.id;
                }
            } else {
                activeTransactions.erase(transaction.id);
            }
        }
    }

    double totalProcessingTime = 0.0;
    for (const auto& t : disjointCheckTimes)
        totalProcessingTime += t.count();

    double averageProcessingTime = totalDisjointPairs > 0 ? totalProcessingTime / totalDisjointPairs : 0.0;

    return {maxWeightedSum, transactionIDWithMaxWeight, totalDisjointPairs, averageProcessingTime};
}

int main() {
    // Example usage of processTransactions function.
    std::vector<Transaction> transactions = {
        {1, 1633036800000000000LL, 10.5},
        {2, 1633036803000000000LL, 20.0},
        // Add more transactions as needed for testing.
    };

    Result result = processTransactions(transactions);

    std::cout << "Max Weighted Sum: " << result.maxWeightedSum << ", Transaction ID: " 
              << result.transactionID << "\n";
    std::cout << "Disjoint Pairs Count: " << result.disjointPairsCount << "\n";
    std::cout << "Average Processing Time per Disjoint Check (ms): " 
              << result.averageProcessingTimePerDisjointCheck << "\n";

    return 0;
}
```']

['Below is an implementation in C for managing a dynamic list of user sessions efficiently under high load conditions, ensuring scalability, low latency, and handling concurrent access:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Constants
#define SESSION_TIMEOUT 300 // Session timeout duration in seconds

typedef struct {
    char *session_id;
    time_t last_access_time; // For session expiration check
} Session;

typedef struct {
    Session **sessions;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} SessionManager;

// Function to remove expired sessions
void remove_expired_sessions(SessionManager *manager) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (current_time - manager->sessions[i]->last_access_time > SESSION_TIMEOUT) {
            free(manager->sessions[i]->session_id);
            free(manager->sessions[i]);
            manager->sessions[i] = NULL;
        }
    }
}

// Function to expand session list
SessionManager* manage_sessions(Session **session_ids, int active_sessions, SessionManager *manager, int current_capacity) {
    if (!session_ids || !manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    remove_expired_sessions(manager);

    // Check if expansion is needed
    if (active_sessions >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Session **new_sessions = realloc(manager->sessions, new_capacity * sizeof(Session*));

        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return NULL; // Insufficient memory
        }

        for (size_t i = manager->capacity; i < new_capacity; ++i) {
            new_sessions[i] = NULL;
        }

        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    // Update sessions with current active session IDs
    for (int i = 0; i < active_sessions; ++i) {
        size_t index = hash(session_ids[i]) % manager->capacity; // Assuming a hash function is defined

        while (manager->sessions[index] != NULL && strcmp(manager->sessions[index]->session_id, session_ids[i]) != 0) {
            index = (index + 1) % manager->capacity;
        }

        if (manager->sessions[index] == NULL || 
            strcmp(manager->sessions[index]->session_id, session_ids[i]) != 0) {

            Session *new_session = malloc(sizeof(Session));
            if (!new_session) {
                pthread_mutex_unlock(&manager->lock);
                return NULL; // Insufficient memory
            }

            new_session->session_id = strdup(session_ids[i]);
            if (!new_session->session_id) {
                free(new_session);
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }

            new_session->last_access_time = time(NULL);
            manager->sessions[index] = new_session;
        } else {
            manager->sessions[index]->last_access_time = time(NULL); // Update access time
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return manager;
}

// Simple hash function for session ID (replace with a more robust one if needed)
unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash;
}
```

### Key Points:
- **Concurrency Handling**: A mutex (`pthread_mutex_t`) is used to ensure thread-safe operations on the session manager.
- **Session Expiry Management**: Expired sessions are removed based on a timeout threshold, improving memory efficiency.
- **Dynamic Expansion**: The session list automatically expands when needed, ensuring scalability.
- **Handling Network Failures**: This implementation assumes that external authentication is handled elsewhere with retry logic; focus here remains on session management and data structure integrity.

### Data Structure Choice:
A hash table (open addressing) is chosen for efficient O(1) average time complexity for insertions, deletions, and lookups. The choice balances between speed and memory efficiency, which is critical under high load conditions.']

['```csharp
using System;
using System.Collections.Generic;

public class DynamicValueGenerator : ICloneable
{
    private Random _random;
    private Dictionary<string, object> _cache = new();

    public int Seed { get; set; } = Environment.TickCount;

    public DynamicValueGenerator(int seed = 0)
    {
        Seed = seed;
        _random = new Random(Seed);
    }

    // Generate a random integer within the specified range
    public int NextInt(int min, int max, bool inclusiveUpperBound = false)
    {
        if (max <= min) throw new ArgumentException("Max must be greater than Min.");

        string cacheKey = $"nextInt_{min}_{max}_{inclusiveUpperBound}";
        if (_cache.TryGetValue(cacheKey, out var cachedValue))
            return (int)cachedValue;

        int range = inclusiveUpperBound ? max - min + 1 : max - min;
        int result = _random.Next(min, min + range);

        _cache[cacheKey] = result;
        return result;
    }

    // Generate a random double within the specified range
    public double NextDouble(double min, double max, bool inclusiveUpperBound = false)
    {
        if (max <= min) throw new ArgumentException("Max must be greater than Min.");

        string cacheKey = $"nextDouble_{min}_{max}_{inclusiveUpperBound}";
        if (_cache.TryGetValue(cacheKey, out var cachedValue))
            return (double)cachedValue;

        double range = inclusiveUpperBound ? max - min + 1 : max - min;
        double result = _random.NextDouble() * range + min;

        _cache[cacheKey] = result;
        return result;
    }

    // Generate a vector of random values
    public T[] NextVector<T>(int length, Func<int> valueGenerator) where T : IConvertible
    {
        if (length <= 0) throw new ArgumentException("Length must be greater than zero.");

        string cacheKey = $"nextVector_{typeof(T).Name}_{length}";
        if (_cache.TryGetValue(cacheKey, out var cachedValue))
            return (T[])cachedValue;

        T[] vector = new T[length];
        for (int i = 0; i < length; i++)
        {
            object value;
            if (valueGenerator == null) // Default to int generator
                value = NextInt(1, 100);
            else
                value = valueGenerator();

            vector[i] = (T)value;
        }

        _cache[cacheKey] = vector;
        return vector;
    }

    // Generate a matrix of random values
    public T[,] NextMatrix<T>(int rows, int cols, Func<int> valueGenerator) where T : IConvertible
    {
        if (rows <= 0 || cols <= 0) throw new ArgumentException("Rows and Cols must be greater than zero.");

        string cacheKey = $"nextMatrix_{typeof(T).Name}_{rows}_{cols}";
        if (_cache.TryGetValue(cacheKey, out var cachedValue))
            return (T[,])cachedValue;

        T[,] matrix = new T[rows, cols];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                object value;
                if (valueGenerator == null) // Default to int generator
                    value = NextInt(1, 100);
                else
                    value = valueGenerator();

                matrix[i, j] = (T)value;
            }
        }

        _cache[cacheKey] = matrix;
        return matrix;
    }

    // Shuffle an array of integers in place using Fisher-Yates shuffle algorithm
    public void Shuffle(int[] array)
    {
        if (array == null || array.Length <= 1) return;

        for (int i = array.Length - 1; i > 0; i--)
        {
            int j = _random.Next(i + 1);
            Swap(ref array[i], ref array[j]);
        }
    }

    private void Swap<T>(ref T lhs, ref T rhs)
    {
        T temp = lhs;
        lhs = rhs;
        rhs = temp;
    }

    // Overload the ToString method to provide a clear representation of the current state
    public override string ToString()
    {
        return $"DynamicValueGenerator(Seed: {Seed})";
    }

    public object Clone()
    {
        var clone = (DynamicValueGenerator)MemberwiseClone();
        clone._random = new Random(clone.Seed);
        clone._cache = new Dictionary<string, object>(_cache);
        return clone;
    }
}
