typedef struct {
    void* result;
    int status;
} CommandResult;

void* asyncCommandExecution(void* arg) {
    CommandResult* result = (CommandResult*)arg;

    // Simulate network performance metric retrieval
    sleep(1); // Mock delay for network command execution

    // Simulating success or failure of the network command
    if (rand() % 2 == 0) { // Randomly simulate success or failure
        result->status = 1; // Success
        result->result = malloc(sizeof(int));
        *((int*)result->result) = 42; // Mock performance indicator value
    } else {
        result->status = 0; // Failure
        result->result = NULL;
    }

    return arg;
}

int generateNfareport(NFAPI_CRC_INDICATION_PDU_T* reportArray, size_t arraySize) {
    pthread_mutex_lock(&lock);

    CommandResult commandResult = { .result = NULL, .status = 0 };
    pthread_t threadId;

    if (pthread_create(&threadId, NULL, asyncCommandExecution, &commandResult)) {
        perror("Failed to create thread");
        pthread_mutex_unlock(&lock);
        return 0;
    }

    void* resultStatus;
    pthread_join(threadId, &resultStatus);

    int commandSuccess = ((CommandResult*)resultStatus)->status;

    if (commandSuccess) {
        for (size_t i = 0; i < arraySize; ++i) {
            reportArray[i].RX_UE_INFORMATION_TAG = rand(); // Mock tag
            reportArray[i].RNTI = rand() % 10000; // Mock RNTI
            reportArray[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Mock CRC indication tag

            int* performanceIndicator = (int*)((CommandResult*)resultStatus)->result;
            if (performanceIndicator) {
                reportArray[i].CRCFLAG = *performanceIndicator;
                free(performanceIndicator);
            }
        }

        pthread_mutex_unlock(&lock);
        return 1;
    } else {
        // Log failure for debugging
        fprintf(stderr, "Failed to execute network command\n");

        for (size_t i = 0; i < arraySize; ++i) {
            reportArray[i].RX_UE_INFORMATION_TAG = 0;
            reportArray[i].RNTI = 0;
            reportArray[i].CRC_INDICATION_REL8_TAG = 0;
            reportArray[i].CRCFLAG = -1; // Indicate failure
        }

        pthread_mutex_unlock(&lock);
        return 0;
    }

    free(resultStatus);
}
