#include <map>
#include <memory>
#include <string>
import <thread>
#include <unordered_map>

namespace beast = boost::beast;  // from <boost/beast.hpp>
namespace http = beast::http;    // from <boost/beast/http.hpp>
namespace net = boost::asio;     // from <boost/asio.hpp>
using tcp = net::ip::tcp;        // from <boost/asio/ip/tcp.hpp>

class NetworkInterfaceManagerMock {
public:
    struct DeviceStatus {
        std::string deviceId;
        int signalStrength;
        std::chrono::system_clock::time_point lastConnectionTimestamp;

        bool operator==(const DeviceStatus& other) const {
            return deviceId == other.deviceId && 
                   signalStrength == other.signalStrength &&
                   lastConnectionTimestamp.time_since_epoch() == 
                   other.lastConnectionTimestamp.time_since_epoch();
        }
    };

    // Mock method to simulate fetching device status
    std::map<std::string, DeviceStatus> getDeviceStatuses(const std::vector<std::string>& deviceIds) {
        std::map<std::string, DeviceStatus> statuses;
        for (const auto& id : deviceIds) {
            statuses[id] = {id, rand() % 100, std::chrono::system_clock::now()};
        }
        return statuses;
    }
};

class Cache {
public:
    void put(const NetworkInterfaceManagerMock::DeviceStatus& status) {
        cache_[status.deviceId] = {status, std::chrono::steady_clock::now()};
    }

    bool get(const std::string& deviceId, 
             NetworkInterfaceManagerMock::DeviceStatus& outStatus,
             bool& isStale) {
        auto it = cache_.find(deviceId);
        if (it != cache_.end()) {
            const auto& cachedData = it->second;
            isStale = (std::chrono::steady_clock::now() - 
                       cachedData.timestamp > std::chrono::hours(1));
            outStatus = cachedData.status;
            return true;
        }
        return false;
    }

private:
    struct CachedItem {
        NetworkInterfaceManagerMock::DeviceStatus status;
        std::chrono::steady_clock::time_point timestamp;
    };

    std::unordered_map<std::string, CachedItem> cache_;
};

class Application {
public:
    Application(net::io_context& ioc, const std::vector<std::string>& deviceIds)
        : resolver_(ioc), deviceIds_(deviceIds) {}

    void run(const std::string& host, const std::string& port) {
        for (const auto& deviceId : deviceIds_) {
            if (!cache_.get(deviceId, status_, isStale)) {
                fetchStatus(host, port, deviceId);
            } else if (!isStale) {
                printStatus(status_);
            }
        }

        net::signal_handler::instance().run(ioc_.stop());
    }

private:
    void fetchStatus(const std::string& host, const std::string& port, 
                     const std::string& deviceId) {
        auto self = shared_from_this();

        resolver_.async_resolve(host, port,
            [self, deviceId](const boost::system::error_code& ec,
                             tcp::resolver::results_type results) {
                if (!ec) {
                    beast::tcp_stream stream(self->ioc_);
                    http::request<http::string_body> req{http::verb::get, "/", 11};

                    req.set(http::field::host, host);
                    req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

                    self->doResolve(req, std::move(results), deviceId);
                } else {
                    logError(ec.message(), "DNS resolution failed for device: " + deviceId);
                }
            });
    }

    void doResolve(const http::request<http::string_body>& req,
                   tcp::resolver::results_type results, const std::string& deviceId) {

        beast::get_lowest_layer(stream_).expires_after(std::chrono::seconds(30));

        beast::get_lowest_layer(stream_)
            .async_connect(results.begin(), results.end(),
                [self = shared_from_this(), req = req](const boost::system::error_code& ec,
                                                       tcp::resolver::iterator) {
                    if (!ec) {
                        self->doRequest(req);
                    } else {
                        logError(ec.message(), "Connection failed for device: " + deviceId);
                    }
                });
    }

    void doRequest(http::request<http::string_body>& req) {
        http::async_write(stream_, req,
            [self = shared_from_this()](boost::system::error_code ec, std::size_t bytesTransferred) {
                boost::ignore_unused(bytesTransferred);
                if (!ec) {
                    self->doReadResponse();
                } else {
                    logError(ec.message(), "Write failed");
                }
            });
    }

    void doReadResponse() {
        http::response<http::dynamic_body> res;

        beast::flat_buffer buffer;
        stream_.async_read(buffer, [self = shared_from_this()](boost::system::error_code ec, std::size_t bytesTransferred) {
            boost::ignore_unused(bytesTransferred);
            if (!ec) {
                http::response_parser<http::dynamic_body> parser;
                parser.parse(res, buffer.data());

                auto status = parseDeviceStatus(res.body());
                cache_.put(status);
                printStatus(status);

            } else {
                logError(ec.message(), "Read failed");
            }
        });
    }

    NetworkInterfaceManagerMock::DeviceStatus parseDeviceStatus(const std::string& body) {
        // Parsing logic for the response, assuming JSON format
        NetworkInterfaceManagerMock::DeviceStatus status;
        // Example parsing (in reality, use a proper JSON library)
        // Pseudo code: parse deviceId, signalStrength, lastConnectionTimestamp from `body`

        return status;
    }

    void printStatus(const NetworkInterfaceManagerMock::DeviceStatus& status) {
        std::cout << "Device ID: " << status.deviceId
                  << ", Signal Strength: " << status.signalStrength
                  << ", Last Connection Timestamp: "
                  << std::chrono::duration_cast<std::chrono::seconds>(
                         status.lastConnectionTimestamp.time_since_epoch()).count()
                  << "\n";
    }

    void logError(const std::string& message, const std::string& context) {
        std::cerr << "Error: " << message << " - Context: " << context << '\n';
    }

private:
    net::io_context ioc_;
    tcp::resolver resolver_{ioc_};
    beast::tcp_stream stream_;
    std::vector<std::string> deviceIds_;
    Cache cache_;
    NetworkInterfaceManagerMock::DeviceStatus status_;
    bool isStale{true};

    using allocator_type = boost::asio::associated_allocator_t<beast::tcp_stream>;
};

int main(int argc, char* argv[]) {
    try {
        if (argc != 4) {
            std::cerr << "Usage: <executable> <host> <port> <device_ids...>\n";
            return EXIT_FAILURE;
        }

        net::io_context ioc{1};
        auto app = std::make_shared<Application>(ioc, {argv[3]});

        app->run(argv[1], argv[2]);

        ioc.run();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

