NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_list(unsigned int num_pdus) {
    if (num_pdus == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pduList = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (unsigned int i = 0; i < num_pdus; ++i) {
        pduList[i].RNTI = rand() % 10000; // Example RNTI value
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example RX_UE_INFORMATION_TAG value
        pduList[i].crcTag.CRCFLAG = rand() % 2; // Random CRC flag (0 or 1)

        // Validation of the structure's integrity
        if (pduList[i].RNTI == 0 || pduList[i].RX_UE_INFORMATION_TAG == 0) {
            free(pduList);
            perror("Invalid structure data");
            return NULL;
        }
    }

    return pduList;
}

void free_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pduList) {
    if (pduList) {
        free(pduList);
        pduList = NULL; // Avoid dangling pointer
    }
}

// Usage Example
int main() {
    unsigned int num_pdus = 10;
    NFAPI_CRC_INDICATION_PDU_T *pduList = allocate_and_populate_list(num_pdus);

    if (pduList) {
        for (unsigned int i = 0; i < num_pdus; ++i) {
            printf("PDU %u: RNTI = %u, RX_UE_INFORMATION_TAG = %u, CRCFLAG = %u\n",
                   i,
                   pduList[i].RNTI,
                   pduList[i].RX_UE_INFORMATION_TAG,
                   pduList[i].crcTag.CRCFLAG);
        }

        free_pdu_list(pduList);
    } else {
        fprintf(stderr, "Failed to allocate or populate PDUs.\n");
    }

    return 0;
}
