['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <time.h>

#define MAX_QUERIES_PER_MINUTE 100
#define CACHE_TTL_SECONDS 300 // 5 minutes

typedef struct {
    char hostname[256];
    u_char ip_address[16]; // Supports both IPv4 and IPv6
    time_t timestamp;
} dns_cache_entry;

typedef struct {
    dns_cache_entry *entries;
    size_t count;
    pthread_mutex_t lock;
} dns_cache;

typedef struct {
    unsigned int query_count;
    time_t reset_time;
    pthread_mutex_t lock;
} rate_limit_info;

dns_cache global_dns_cache = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
rate_limit_info rate_limits[256] = {{0, time(NULL), PTHREAD_MUTEX_INITIALIZER}}; // One entry per possible IP

int resolve_hostname(const char *hostname, u_char *ip_buffer) {
    struct addrinfo hints, *res;
    int status, family, ip_length;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Support both IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        perror("getaddrinfo");
        return -1;
    }

    for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
        family = p->ai_family;
        ip_length = family == AF_INET ? sizeof(struct in_addr) : sizeof(struct in6_addr);

        if (family == AF_INET || family == AF_INET6) {
            memcpy(ip_buffer, &((struct sockaddr_storage *)p->ai_addr)->ss_addr, ip_length);
            freeaddrinfo(res);
            return 0;
        }
    }

    freeaddrinfo(res);
    return -1;
}

int rate_limit(const char *client_ip) {
    struct in_addr addr;
    if (inet_pton(AF_INET, client_ip, &addr.s_addr)) {
        size_t index = addr.s_addr % 256; // Simple hash for IP to an index
        pthread_mutex_lock(&rate_limits[index].lock);

        time_t now = time(NULL);
        if (now >= rate_limits[index].reset_time) {
            rate_limits[index].query_count = 0;
            rate_limits[index].reset_time = now + 60; // Reset every minute
        }

        if (rate_limits[index].query_count < MAX_QUERIES_PER_MINUTE) {
            rate_limits[index].query_count++;
            pthread_mutex_unlock(&rate_limits[index].lock);
            return 0;
        } else {
            pthread_mutex_unlock(&rate_limits[index].lock);
            return -1; // Rate limit exceeded
        }
    }
    return -1; // Invalid IP format
}

void cache_cleanup(dns_cache *cache) {
    time_t now = time(NULL);

    for (size_t i = 0; i < cache->count; ++i) {
        if (now - cache->entries[i].timestamp > CACHE_TTL_SECONDS) {
            memmove(&cache->entries[i], &cache->entries[i + 1],
                    (cache->count - i - 1) * sizeof(dns_cache_entry));
            --cache->count;
            --i; // Check same index again
        }
    }
}

int check_cache(const char *hostname, u_char *ip_buffer) {
    pthread_mutex_lock(&global_dns_cache.lock);
    for (size_t i = 0; i < global_dns_cache.count; ++i) {
        if (strcmp(global_dns_cache.entries[i].hostname, hostname) == 0 &&
            time(NULL) - global_dns_cache.entries[i].timestamp <= CACHE_TTL_SECONDS) {

            memcpy(ip_buffer, global_dns_cache.entries[i].ip_address,
                   sizeof(u_char[16])); // Supports both IPv4 and IPv6
            pthread_mutex_unlock(&global_dns_cache.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&global_dns_cache.lock);
    return -1; // Not found in cache
}

int add_to_cache(const char *hostname, const u_char *ip_address) {
    dns_cache_entry new_entry;
    strncpy(new_entry.hostname, hostname, sizeof(new_entry.hostname));
    memcpy(new_entry.ip_address, ip_address, 16); // Supports both IPv4 and IPv6
    new_entry.timestamp = time(NULL);

    pthread_mutex_lock(&global_dns_cache.lock);
    global_dns_cache.entries = realloc(global_dns_cache.entries,
                                       (global_dns_cache.count + 1) * sizeof(dns_cache_entry));
    if (!global_dns_cache.entries) {
        perror("realloc");
        pthread_mutex_unlock(&global_dns_cache.lock);
        return -1;
    }
    global_dns_cache.entries[global_dns_cache.count++] = new_entry;
    pthread_mutex_unlock(&global_dns_cache.lock);

    cache_cleanup(&global_dns_cache); // Cleanup expired entries
    return 0;
}

int dns_resolver(const char *client_ip, const char *hostname, u_char *ip_buffer) {
    if (rate_limit(client_ip)) {
        fprintf(stderr, "Rate limit exceeded for %s\n", client_ip);
        return -1; // Rate limited
    }

    if (check_cache(hostname, ip_buffer) == 0) {
        printf("Cache hit for %s\n", hostname);
        return 0;
    }

    if (resolve_hostname(hostname, ip_buffer) != 0) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return -1; // Resolution error
    }

    add_to_cache(hostname, ip_buffer);

    printf("Resolved %s to %s\n", hostname,
           inet_ntop(AF_INET6, ip_buffer, buffer, sizeof(buffer)) ? buffer : inet_ntoa(*((struct in_addr *)ip_buffer)));

    return 0;
}

int main() {
    u_char ip_address[16];
    dns_resolver("192.168.1.10", "example.com", ip_address);
    // Additional logic for handling client IPs, configuration service, logging, etc.
    return 0;
}
```

### Notes:
- This code provides a basic implementation of DNS resolution with rate limiting and caching mechanisms. 
- The cache cleanup function ensures that stale entries are removed efficiently.
- Rate-limiting is implemented per client IP using a simple modulo operation to map IPs to indices in an array, which holds query counts and reset times.
- Thread safety is ensured by using mutexes for both the DNS cache and rate limit data structures.
- IPv4 and IPv6 support is handled with `getaddrinfo`.
- The code can be extended to include configuration service integration, logging, and handling consecutive failed queries.

This implementation provides a foundation but may need further refinement based on specific requirements or constraints in a production environment.']

