#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

// Function prototypes
record* allocate_records(int num_records, double min_value, double max_value, size_t max_memory_usage);
int is_unique_offset(record *records, int num_records, long offset);

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* allocate_records(int num_records, double min_value, double max_value, size_t max_memory_usage) {
    if (num_records <= 0 || max_memory_usage == 0) return NULL;

    // Calculate memory required per record and total needed memory
    size_t record_size = sizeof(record);
    size_t total_memory_needed = num_records * record_size;

    // Check against the maximum allowed memory usage
    if (total_memory_needed > max_memory_usage) {
        fprintf(stderr, "Requested memory exceeds maximum allowed.\n");
        return NULL;
    }

    record* records = malloc(total_memory_needed);
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_records; ++i) {
        long unique_offset;
        do {
            unique_offset = rand() % (1000000000 - 1) + 1;
        } while (!is_unique_offset(records, i, unique_offset));

        pthread_mutex_lock(&lock);
        records[i].offset = unique_offset;
        records[i].key = i; // or any other logic for key
        records[i].value = min_value + (double)rand() / RAND_MAX * (max_value - min_value);
        pthread_mutex_unlock(&lock);
    }

    return records;
}

int is_unique_offset(record *records, int num_records, long offset) {
    if (!records) return 0;

    for (int i = 0; i < num_records; ++i) {
        if (records[i].offset == offset)
            return 0;
    }
    return 1;
}

void free_records(record* records) {
    free(records);
}
```

This C code provides a function `allocate_records` which dynamically allocates memory for an array of `record` structures, initializes them with unique offsets and random floating-point values within specified bounds, while also ensuring that the total memory usage does not exceed a given limit. The use of a mutex ensures thread safety when accessing or modifying records concurrently.']

