class NetworkStatusCache {
private:
    std::map<std::string, nlohmann::json> cache;
    mutable std::mutex cacheMutex;

public:
    void update(const std::string& deviceId, const nlohmann::json& status) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cache[deviceId] = status;
    }

    bool get(const std::string& deviceId, nlohmann::json& status) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = cache.find(deviceId);
        if (it != cache.end()) {
            status = it->second;
            return true;
        }
        return false;
    }

    void clear() {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cache.clear();
    }
};

