    unsigned int rx_ue_information_tag;
    unsigned int rnti;
    unsigned char crcflag;
} CRC_INDICATION_PDU_T;

// Function to validate network parameters
int is_valid_network_entity(const NetworkEntity *entity) {
    if (inet_pton(AF_INET, entity->ip_address)) {
        return 0; // Invalid IP address
    }
    return 1; // Valid IP address
}

// Main function to process configuration files and generate PDU structures
void process_config_files_and_generate_pdu(const char *directory_path) {
    DIR *dir;
    struct dirent *entry;
    NetworkEntity entities[1000]; // Adjust size as needed for expected number of entities
    CRC_INDICATION_PDU_T pdu_list[1000];
    int entity_count = 0, max_port = 0;

    if ((dir = opendir(directory_path)) == NULL) {
        perror("Error opening directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        // Skip the current and parent directories
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory_path, entry->d_name);

        FILE *file = fopen(filepath, "r");
        if (!file) {
            perror("Error opening file");
            continue;
        }

        // Read and validate each network entity
        NetworkEntity entity;
        while (fscanf(file, "%15[^,],%u,%9[^\n]\n", entity.ip_address, &entity.port, entity.protocol_type) == 3) {
            if (is_valid_network_entity(&entity)) {
                entities[entity_count++] = entity;
                if (entity.port > max_port) {
                    max_port = entity.port;
                }

                // Generate CRC_INDICATION_PDU_T with random values
                pdu_list[entity_count - 1].rx_ue_information_tag = rand(); 
                pdu_list[entity_count - 1].rnti = rand();
                pdu_list[entity_count - 1].crcflag = rand() % 2; // 0 or 1 for realistic CRC flag
            } else {
                fprintf(stderr, "Invalid network entity in file: %s\n", filepath);
            }
        }

        fclose(file);
    }
    closedir(dir);

    // Print maximum port number found
    printf("Maximum Port Number: %u\n", max_port);
    printf("Valid Network Entities Processed: %d\n", entity_count);

    // Optionally, print or process the generated PDU list as needed
    for (int i = 0; i < entity_count; ++i) {
        printf("PDU List[%d] - RX UE Information Tag: %u, RNTI: %u, CRCFLAG: %u\n", 
               i, pdu_list[i].rx_ue_information_tag, pdu_list[i].rnti, pdu_list[i].crcflag);
    }
}

int main() {
    const char *config_directory = "./config_files";
    process_config_files_and_generate_pdu(config_directory);
    return 0;
}
