    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generateNfaapiPdus(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t N) {
    if (pthread_mutex_lock(&mutex)) {
        fprintf(stderr, "Failed to lock mutex\n");
        return;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % UINT_MAX;
        pdus[i].RNTI = rand() % UINT_MAX;

        for (int j = 0; j < 4; ++j) {
            pdus[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }

        pdus[i].CRCFLAG = rand() & 1;
    }

    if (pthread_mutex_unlock(&mutex)) {
        fprintf(stderr, "Failed to unlock mutex\n");
    }
}
