    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    free(node);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->ue_info_tag = ue_info_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    return new_node;
}

int add_entry(CRCList *list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    if (!list || !ue_info_tag) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;

    while (current && current->rnti == rnti) {
        prev = current;
        current = current->next;
    }

    if (current && current->rnti == rnti) { // Consecutive RNTI check
        pthread_mutex_unlock(&list->lock);
        return -1; // Prevent same consecutive RNTI values
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(ue_info_tag, rnti);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (prev) {
        prev->next = new_node;
    } else {
        list->head = new_node;
    }

    // Integrate with external database here for persistent storage of RNTI values
    // Example: db_insert_rnti(rnti);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_list(CRCList *list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = current->next;
        free_node(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *node;
} CRCListIterator;

CRCListIterator* create_iterator(CRCList *list) {
    if (!list) return NULL;

    CRCListIterator *iter = (CRCListIterator*)malloc(sizeof(CRCListIterator));
    if (!iter) return NULL;

    pthread_mutex_lock(&list->lock);
    iter->node = list->head;
    pthread_mutex_unlock(&list->lock);

    return iter;
}

NFAPI_CRC_INDICATION_PDU_T* next(CRCListIterator *iter) {
    if (!iter || !iter->node) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *current_node = iter->node;
    iter->node = current_node->next;

    return current_node;
}

void free_iterator(CRCListIterator *iter) {
    if (iter) free(iter);
}
