#include <pthread.h>

// Define constants
#define MAX_ENTRIES 50000

typedef struct {
    // Example structure members
    int id;
    char data[256];
} PHY_STATS;

typedef struct {
    // Example structure members
    int config_id;
} UL_SRS_CONFIG;

typedef struct {
    // Example structure members
    int tx_info;
    void* TX_DATA;
} SRS_TX_INFO;

typedef struct {
    PHY_STATS phy_stats;
    UL_SRS_CONFIG ul_srs_config;
    SRS_TX_INFO srs_tx_info;
} NFAPI_LTE_UL_SRS_PDU_T;

// Node for dynamic array
typedef struct Node {
    NFAPI_LTE_UL_SRS_PDU_T pdu;
    struct Node* next;
    struct Node* prev;
} Node;

// Dynamic array structure
typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->head = arr->tail = NULL;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void destroy_dynamic_array(DynamicArray* arr) {
    Node* current = arr->head;
    while (current) {
        Node* next = current->next;
        free(current->pdu.srs_tx_info.TX_DATA);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

int insert_at_front(DynamicArray* arr, NFAPI_LTE_UL_SRS_PDU_T pdu) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->count > 0 && arr->head->pdu.ul_srs_config.config_id == pdu.ul_srs_config.config_id) {
        pthread_mutex_unlock(&arr->mutex);
        return -1; // Conflict with unique SRS configuration
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }

    new_node->pdu = pdu;
    new_node->next = arr->head;
    new_node->prev = NULL;

    if (arr->head) arr->head->prev = new_node;
    else arr->tail = new_node;

    arr->head = new_node;
    arr->count++;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int insert_at_back(DynamicArray* arr, NFAPI_LTE_UL_SRS_PDU_T pdu) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->count > 0 && arr->tail->pdu.ul_srs_config.config_id == pdu.ul_srs_config.config_id) {
        pthread_mutex_unlock(&arr->mutex);
        return -1; // Conflict with unique SRS configuration
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }

    new_node->pdu = pdu;
    new_node->next = NULL;
    new_node->prev = arr->tail;

    if (arr->tail) arr->tail->next = new_node;
    else arr->head = new_node;

    arr->tail = new_node;
    arr->count++;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int delete_from_front(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);

    if (!arr->head) {
        pthread_mutex_unlock(&arr->mutex);
        return -1; // Empty array
    }

    Node* temp = arr->head;
    arr->head = arr->head->next;

    if (arr->head) arr->head->prev = NULL;
    else arr->tail = NULL;

    free(temp->pdu.srs_tx_info.TX_DATA);
    free(temp);

    arr->count--;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int delete_from_back(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);

    if (!arr->tail) {
        pthread_mutex_unlock(&arr->mutex);
        return -1; // Empty array
    }

    Node* temp = arr->tail;
    arr->tail = arr->tail->prev;

    if (arr->tail) arr->tail->next = NULL;
    else arr->head = NULL;

    free(temp->pdu.srs_tx_info.TX_DATA);
    free(temp);

    arr->count--;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Iterator for forward and backward traversal
typedef struct {
    Node* current;
} DynamicArrayIterator;

DynamicArrayIterator* create_iterator(DynamicArray* arr, int direction) {
    DynamicArrayIterator* iter = (DynamicArrayIterator*)malloc(sizeof(DynamicArrayIterator));
    if (!iter) return NULL;

    pthread_mutex_lock(&arr->mutex);
    iter->current = (direction == 0) ? arr->head : arr->tail;
    pthread_mutex_unlock(&arr->mutex);

    return iter;
}

NFAPI_LTE_UL_SRS_PDU_T* iterator_next(DynamicArrayIterator* iter, int forward) {
    if (!iter->current) return NULL;

    pthread_mutex_lock(iter->current); // Ensure current node is accessed safely

    NFAPI_LTE_UL_SRS_PDU_T* pdu = &(iter->current->pdu);

    iter->current = (forward ? iter->current->next : iter->current->prev);
    pthread_mutex_unlock(iter->current); // Unlock after access

    return pdu;
}

void destroy_iterator(DynamicArrayIterator* iter) {
    free(iter);
}
```

This code defines a thread-safe dynamic array of `NFAPI_LTE_UL_SRS_PDU_T` structures with operations for insertion and deletion at both ends, ensuring unique SRS configuration IDs. It also includes an iterator to traverse the array forward or backward while maintaining data integrity in concurrent environments.']

