    static CryptoAlgorithm algorithms[] = {
        {"hash", .hash = { "SHA256", sha256_init, sha256_update, sha256_final, sha256_cleanup }, .performance_metric = 1.23 },
        {"cipher", .cipher = { "AES", aes_init, aes_encrypt, aes_decrypt, aes_cleanup }, .performance_metric = 0.98 }
    };

