    CryptoAlgorithm **list = malloc(*count * sizeof(CryptoAlgorithm *));
    for (size_t i = 0; i < *count; ++i) {
        list[i] = &algorithms[i];
    }

    pthread_mutex_unlock(&crypto_mutex);

    return list;
}

// Function to load and unload algorithms dynamically
void *load_algorithm(const char *lib_name, const char *func_name) {
    void *handle = dlopen(lib_name, RTLD_LAZY);
    if (!handle) return NULL;

    dlerror();  // Clear any existing errors

    void *(*init_func)(void) = (void *(*)())dlsym(handle, func_name);
    char *error = dlerror();
    if (error) {
        dlclose(handle);
        return NULL;
    }

    return init_func ? handle : NULL; // Return handle or NULL
}

// Function to unload algorithm dynamically
void unload_algorithm(void *handle) {
    if (handle) {
        dlclose(handle);
    }
}

// Mock function for logging performance discrepancies
void log_performance_discrepancy(double expected, double actual) {
    if (fabs(expected - actual) > 0.1) { // Threshold for discrepancy
        printf("Performance discrepancy detected: Expected %f, Actual %f\n", expected, actual);
    }
}

