#define OFFSET_ARRAY_SIZE 10000

typedef struct Record {
    long *offset;
    int key;
    struct Record *next;
} Record;

long offsetArray[OFFSET_ARRAY_SIZE] = {0};
int maxKeyGlobal = -1; // Global variable to track the maximum key value
Record *head = NULL;   // Head of the linked list for record management

void freeResources() {
    Record *current = head;
    while (current != NULL) {
        Record *next = current->next;
        free(current);
        current = next;
    }
}

int validateKey(int key, int keys[], int size) {
    if (key < 0 || key > 65535) return -1; // Invalid range
    for (int i = 0; i < size; ++i) {
        if (keys[i] == key) return -2; // Duplicate key
    }
    return 0;
}

void updateMaxKey(Record *record) {
    if (maxKeyGlobal < record->key) {
        maxKeyGlobal = record->key;
    }
}

void populateRecords(int keys[], int size) {
    for (int i = 0; i < size; ++i) {
        Record *newRecord = (Record *)malloc(sizeof(Record));
        if (!newRecord) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        newRecord->offset = &offsetArray[i]; // Link to the offset array
        newRecord->key = keys[i];
        newRecord->next = head;
        head = newRecord;

        updateMaxKey(newRecord);
    }
}

int main() {
    int keyCount = 0, inputKey;

    // Read integers from standard input until a negative number is encountered
    while (scanf("%d", &inputKey) && inputKey >= 0) {
        keyCount++;
    }

    if (keyCount == 0) {
        fprintf(stderr, "No valid keys provided.\n");
        return EXIT_FAILURE;
    }

    int *keys = (int *)malloc(keyCount * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys array\n");
        return EXIT_FAILURE;
    }

    // Rewind standard input to read the same keys again
    rewind(stdin);

    int validKeyCount = 0;
    while (scanf("%d", &inputKey) && inputKey >= 0) {
        if (validateKey(inputKey, keys, validKeyCount) == 0) {
            keys[validKeyCount++] = inputKey;
        } else {
            fprintf(stderr, "Invalid or duplicate key encountered: %d\n", inputKey);
            free(keys);
            freeResources();
            return EXIT_FAILURE;
        }
    }

    if (validKeyCount != keyCount) {
        fprintf(stderr, "Mismatch in the number of valid keys.\n");
        free(keys);
        freeResources();
        return EXIT_FAILURE;
    }

    populateRecords(keys, validKeyCount);

    printf("Max Key Value: %d\n", maxKeyGlobal);

    // Free allocated resources
    free(keys);
    freeResources();

    return 0;
}
