using System;
using System.Data;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class DynamicRandom : IDisposable
{
    private readonly object _lock = new();
    private Random _random;
    private double _minDouble;
    private double _maxDouble;
    private int _minInt;
    private int _maxInt;
    private bool _disposed = false;

    public void SetSeed(long seed)
    {
        lock (_lock)
        {
            _random = new Random((int)seed);
        }
    }

    public bool ValidateRange(double min, double max, out double validatedMin, out double validatedMax)
    {
        lock (_lock)
        {
            if (min > max)
            {
                validatedMin = max;
                validatedMax = min;
                return true; // Adjusted range
            }

            validatedMin = min;
            validatedMax = max;
            return min <= max;
        }
    }

    public double NextDouble()
    {
        lock (_lock)
        {
            return _random.NextDouble() * (_maxDouble - _minDouble) + _minDouble;
        }
    }

    public int NextInt()
    {
        lock (_lock)
        {
            return (int)(_random.NextDouble() * (_maxInt - _minInt) + _minInt);
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            return $"Range: [{_minInt}, {_maxInt}] for Int, [{_minDouble}, {_maxDouble}] for Double";
        }
    }

    public async Task<DataTableReader> SendToDatabaseAsync(byte[] data)
    {
        using var client = new HttpClient();
        var content = new ByteArrayContent(data);
        var response = await client.PostAsync("https://your-database-server/api", content);

        if (response.IsSuccessStatusCode)
        {
            var dataTable = await DataTable.LoadFromJson(await response.Content.ReadAsStringAsync());
            return dataTable.CreateDataReader();
        }
        else
        {
            throw new Exception("Failed to retrieve data from database.");
        }
    }

    public void Dispose()
    {
        lock (_lock)
        {
            if (!_disposed)
            {
                _random?.Dispose();
                _disposed = true;
            }
        }
    }
}

