#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    unsigned long UTRAN_CELL_ID;
    unsigned long TMSI;
    unsigned short PREAMBLE_SEQ_NOM;
    int corruption_flag;
} NFAPI_RACH_REQ_PDU_T;

#define RANDOM_INT_RANGE(low, high) (rand() % ((high) - (low) + 1) + (low))
#define MAX_UINT32 ((unsigned long)-1)
#define MAX_USHORT ((unsigned short)-1)

int populate_network_simulation(record **records, NFAPI_RACH_REQ_PDU_T **pdu_array, int N, const char *label) {
    if (!records || !pdu_array) return -1;

    srand(time(NULL));  // Seed the random number generator

    record *recs = (record *)malloc(N * sizeof(record));
    NFAPI_RACH_REQ_PDU_T *pdus = (NFAPI_RACH_REQ_PDU_T *)malloc(N * sizeof(NFAPI_RACH_REQ_PDU_T));

    if (!recs || !pdus) {
        free(recs);
        free(pdus);
        return -2;
    }

    for (int i = 0; i < N; ++i) {
        recs[i].value = RANDOM_INT_RANGE(1, 100);  // Random int in range [1, 100]
        pdus[i].UTRAN_CELL_ID = RANDOM_INT_RANGE(1, MAX_UINT32);
        pdus[i].TMSI = RANDOM_INT_RANGE(1, MAX_UINT32);
        pdus[i].PREAMBLE_SEQ_NOM = RANDOM_INT_RANGE(0, MAX_USHORT);
        pdus[i].corruption_flag = RANDOM_INT_RANGE(0, 1);  // Random flag (0 or 1)
    }

    *records = recs;
    *pdu_array = pdus;

    printf("Simulation '%s' initialized with %d records and PDUs.\n", label, N);

    return 0;  // Success
}

void free_simulation_memory(record *records, NFAPI_RACH_REQ_PDU_T *pdus) {
    if (records) free(records);
    if (pdus) free(pdus);
}
