def execute_simulation(label, callback):
    # Define argument and return types for C functions
    lib.populate_network_simulation.argtypes = [ctypes.POINTER(ctypes.POINTER(ctypes.c_int)),
                                                ctypes.POINTER(ctypes.POINTER(ctypes.c_uint64)),
                                                ctypes.c_int,
                                                ctypes.c_char_p]
    lib.populate_network_simulation.restype = ctypes.c_int

    lib.free_simulation_memory.argtypes = [ctypes.POINTER(ctypes.c_int),
                                           ctypes.POINTER(ctypes.c_uint64)]

    N = 1000
    records_array_type = ctypes.POINTER(ctypes.c_int) * N
    pdu_array_type = ctypes.POINTER(ctypes.c_uint64) * N

    # Create pointers for arrays to pass by reference
    records_pointer = records_array_type()
    pdus_pointer = pdu_array_type()

    result = lib.populate_network_simulation(records_pointer, pdus_pointer, N, label.encode('utf-8'))

    if result != 0:
        print(f"Error initializing simulation '{label}': Error code {result}")
        return

    try:
        # Execute the callback with the records and PDUs
        callback(records_pointer.contents, pdus_pointer.contents)
    finally:
        # Ensure memory is freed
        lib.free_simulation_memory(ctypes.byref(records_pointer), ctypes.byref(pdus_pointer))
