['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_IDENTITY;
    char RECONFIGURATION_COMMAND[256];
} LTE_RRC_RECONFIGURATION_MESSAGE;

typedef struct Node {
    LTE_RRC_RECONFIGURATION_MESSAGE data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_unique_UE_IDENTITY(DoublyLinkedList* list, int UE_IDENTITY) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.UE_IDENTITY == UE_IDENTITY)
            return 0;
        current = current->next;
    }
    return 1;
}

void add_message(DoublyLinkedList* list, LTE_RRC_RECONFIGURATION_MESSAGE message) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique_UE_IDENTITY(list, message.UE_IDENTITY)) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: UE_IDENTITY already exists consecutively\n");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->data = message;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail != NULL)
        list->tail->next = new_node;
    else
        list->head = new_node;
    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
}

void remove_message(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* temp = list->head;
    list->head = list->head->next;

    if (list->head != NULL)
        list->head->prev = NULL;
    else
        list->tail = NULL;

    free(temp->data.RECONFIGURATION_COMMAND);
    free(temp);

    pthread_mutex_unlock(&list->lock);
}

void traverse_list(DoublyLinkedList* list, void (*process)(LTE_RRC_RECONFIGURATION_MESSAGE)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        process(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current->data.RECONFIGURATION_COMMAND);
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void process_message(LTE_RRC_RECONFIGURATION_MESSAGE message) {
    // Example processing function
    printf("Processing UE_IDENTITY: %d, Command: %s\n", message.UE_IDENTITY, message.RECONFIGURATION_COMMAND);
}

int main() {
    DoublyLinkedList* list = create_list();

    LTE_RRC_RECONFIGURATION_MESSAGE msg1 = { .UE_IDENTITY = 1, .RECONFIGURATION_COMMAND = "Command1" };
    LTE_RRC_RECONFIGURATION_MESSAGE msg2 = { .UE_IDENTITY = 2, .RECONFIGURATION_COMMAND = "Command2" };

    add_message(list, msg1);
    add_message(list, msg2);

    traverse_list(list, process_message);

    remove_message(list);
    free_list(list);

    return 0;
}
```

This C code manages a doubly linked list of `LTE_RRC_RECONFIGURATION_MESSAGE` structures. It ensures unique consecutive `UE_IDENTITY`s using mutex locks for thread safety and supports efficient traversal, addition, and removal of nodes with robust memory management. The design allows integration with external message queue services for asynchronous processing.']

