Edge* createEdge(Vertex* from, Vertex* to, const char* properties);
void addVertexToDatabase(Vertex* vertex);
void addEdgeToDatabase(Edge* edge);
void handleDatabaseFailure(void);
bool retryGraphOperation(void (*operation)(void), int retries);

// Function implementations
UMTS_TURBODEC_PDU_T* generatePduList(int count) {
    UMTS_TURBODEC_PDU_T* pduList = (UMTS_TURBODEC_PDU_T*)malloc(count * sizeof(UMTS_TURBODEC_PDU_T));
    if (!pduList) return NULL;

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        pduList[i].umtsTurboCodeTag = rand() % 100;
        pduList[i].megaCellId = rand() % 1000;
        pduList[i].turboDecodingStatusTag = rand() % 100;

        Vertex* vertex = createVertex(i, "PDU Properties");
        if (!vertex) {
            free(pduList);
            return NULL;
        }

        retryGraphOperation(() => addVertexToDatabase(vertex), 3);

        // Simulating adding edges (self-loop for simplicity)
        Edge* edge = createEdge(vertex, vertex, "Self-loop");
        if (!edge) {
            free(pduList);
            return NULL;
        }
        retryGraphOperation(() => addEdgeToDatabase(edge), 3);
    }

    return pduList;
}

Vertex* createVertex(int id, const char* properties) {
    Vertex* vertex = (Vertex*)malloc(sizeof(Vertex));
    if (!vertex) return NULL;

    vertex->id = id;
    snprintf(vertex->properties, sizeof(vertex->properties), "%s", properties);
    vertex->edges = NULL;
    vertex->next = NULL;

    return vertex;
}

Edge* createEdge(Vertex* from, Vertex* to, const char* properties) {
    Edge* edge = (Edge*)malloc(sizeof(Edge));
    if (!edge) return NULL;

    edge->from = from;
    edge->to = to;
    snprintf(edge->properties, sizeof(edge->properties), "%s", properties);
    edge->next = NULL;

    // Link the edge to the vertex
    Edge** current = &from->edges;
    while (*current) {
        current = &(*current)->next;
    }
    *current = edge;

    return edge;
}

void addVertexToDatabase(Vertex* vertex) {
    // Simulate database operation with a chance of failure
    if (rand() % 10 < 2) {  // 20% chance to fail
        handleDatabaseFailure();
        free(vertex);
        exit(EXIT_FAILURE);  // For demonstration, normally you'd retry or log the error
    }
    printf("Vertex %d added to database\n", vertex->id);
}

void addEdgeToDatabase(Edge* edge) {
    if (rand() % 10 < 2) {  // 20% chance to fail
