#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset_ptr;
    int *key_ptr;
} record;

record* initialize_arrays(int offset_size, int key_size, int min_value, int max_value) {
    if (offset_size <= 0 || key_size <= 0 || min_value >= max_value) {
        return NULL;
    }

    // Allocate memory for arrays
    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    record *records = malloc(key_size * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize offsets and keys with default values
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = i * 10L; // Default offset value
    }
    for (int i = 0; i < key_size; ++i) {
        keys[i] = -1; // Default invalid key value
    }

    srand(time(NULL));

    int unique_keys_count = 0;
    while (unique_keys_count < key_size) {
        int new_key = rand() % (max_value - min_value + 1) + min_value;

        // Check for duplicate keys
        int is_duplicate = 0;
        for (int i = 0; i < unique_keys_count; ++i) {
            if (keys[i] == new_key) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate && new_key != -1) {
            keys[unique_keys_count++] = new_key;
        }
    }

    // Initialize records
    for (int i = 0; i < key_size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        // Assign pointers to the corresponding offset and key
        int assigned_offset = i % offset_size;
        records[i].offset_ptr = &offsets[assigned_offset];
        records[i].key_ptr = &keys[i];
    }

    free(offsets); // Free offsets as they are no longer needed after initialization

    return records; // Caller is responsible for freeing this memory
}

void free_records(record *records, int key_size) {
    if (records) {
        free(records);
    }
}
```

This code defines a function `initialize_arrays` that allocates and initializes three arrays: one for long offsets, one for integer keys, and one for record structures. It ensures unique keys by checking for duplicates before adding new ones. The function also sets the value of each record's integer field to a random number within a specified range. Memory allocation is handled carefully to prevent leaks, and memory for the offset array is freed after use since it's no longer needed once records are initialized. A helper function `free_records` is provided to free the allocated memory for records when they are no longer needed by the caller."]

