    UdpSessionStats *sessionStatsArray = (UdpSessionStats *)malloc(initialSize * sizeof(UdpSessionStats));

    if (!sessionStatsArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&statsMutex);
    for (int i = 0; i < initialSize; ++i) {
        sessionStatsArray[i].sessionID = i + 1; // Unique ID
        sessionStatsArray[i].timestamp = time(NULL); // Current timestamp
        sessionStatsArray[i].connectionStatus = 0; // Initially disconnected
        sessionStatsArray[i].averageLatency = 0.0f; // Initialize latency to zero
    }
    pthread_mutex_unlock(&statsMutex);

    return sessionStatsArray;
}

// Function to update average latency for a given session ID
void updateLatency(UdpSessionStats *sessionStatsArray, int size, int sessionId, float newLatency) {
    if (!sessionStatsArray || sessionId <= 0 || sessionId > size)
        return;

    pthread_mutex_lock(&statsMutex);
    // Simple moving average calculation: Assuming we want to keep the last N measurements
    static const int N = 10;
    static float latencyMeasurements[100][10] = {0}; // Placeholder for up to 100 sessions
    static int measurementCount[100] = {0};

    int index = sessionId - 1; // Convert to zero-based indexing

    if (measurementCount[index] < N) {
        latencyMeasurements[index][measurementCount[index]] = newLatency;
        measurementCount[index]++;
    } else {
        for (int i = 1; i < N; ++i) {
            latencyMeasurements[index][i - 1] = latencyMeasurements[index][i];
        }
        latencyMeasurements[index][N - 1] = newLatency;
    }

    float sum = 0.0f;
    for (int i = 0; i < measurementCount[index]; ++i) {
        sum += latencyMeasurements[index][i];
    }

    sessionStatsArray[index].averageLatency = sum / measurementCount[index];
    pthread_mutex_unlock(&statsMutex);
}

// Function to free allocated memory
void freeUdpSessionStatsArray(UdpSessionStats *sessionStatsArray) {
    if (sessionStatsArray) {
        free(sessionStatsArray);
    }
}
