#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

#define MAX_LOG_LEVEL 3 // e.g., 0: None, 1: Error, 2: Info, 3: Debug

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t node_count;
    int log_level;
    // Memory pool specific fields
    void** free_list;  // Linked list of free memory blocks
    size_t block_size;
    size_t max_blocks;
    size_t allocated_blocks;
} ThreadSafeLinkedList;

// Function prototypes
void init_linked_list(ThreadSafeLinkedList* list, size_t block_size, size_t max_blocks);
void destroy_linked_list(ThreadSafeLinkedList* list);
Node* create_node(ThreadSafeLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data);
void add_to_list(ThreadSafeLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data);
int remove_duplicates(ThreadSafeLinkedList* list);
void log_message(ThreadSafeLinkedList* list, int level, const char* message);
void export_statistics(const ThreadSafeLinkedList* list);
void garbage_collect(ThreadSafeLinkedList* list);

// Initialize the linked list and memory pool
void init_linked_list(ThreadSafeLinkedList* list, size_t block_size, size_t max_blocks) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->node_count = 0;
    list->log_level = MAX_LOG_LEVEL; // Default to debug level

    // Initialize memory pool
    list->free_list = (void**)malloc(max_blocks * sizeof(void*));
    list->block_size = block_size;
    list->max_blocks = max_blocks;
    list->allocated_blocks = 0;

    for (size_t i = 0; i < max_blocks; ++i) {
        void* block = malloc(block_size);
        if (!block) break; // Stop on allocation failure
        ((char**)list->free_list)[i] = block;
        list->allocated_blocks++;
    }
}

// Destroy the linked list and free memory pool
void destroy_linked_list(ThreadSafeLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    // Free memory pool
    for (size_t i = 0; i < list->allocated_blocks; ++i) {
        free(list->free_list[i]);
    }
    free(list->free_list);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Create a new node using memory pool
Node* create_node(ThreadSafeLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = NULL;
    if (list->free_list && list->allocated_blocks > 0) {
        // Reuse from free list
        void** last_free_block = &list->free_list[list->allocated_blocks - 1];
        while (*last_free_block) {
            last_free_block = (void**)((char*)*last_free_block + sizeof(void*));
        }
        *last_free_block = list->free_list[--list->allocated_blocks];

        node = *(Node**)last_free_block;
    } else {
        // Allocate new block
        node = malloc(list->block_size);
        if (!node) return NULL;  // Handle allocation failure gracefully
    }

    memcpy(&node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->next = NULL;
    return node;
}

// Add a new entry to the list
void add_to_list(ThreadSafeLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    Node* existing = list->head;
    while (existing) {
        if (existing->data.RNTI == data->RNTI) break; // Duplicate found
        existing = existing->next;
    }

    if (!existing) { // No duplicate, add new node
        Node* new_node = create_node(list, data);
        if (!new_node) {
            log_message(list, 0, "Memory allocation failed for new node.");
            pthread_mutex_unlock(&list->lock);
            return;
        }

        new_node->next = list->head;
        list->head = new_node;
        list->node_count++;
    }

    pthread_mutex_unlock(&list->lock);
}

// Remove duplicate entries based on RNTI
int remove_duplicates(ThreadSafeLinkedList* list) {
    int removed_count = 0;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && current->next) {
        Node* temp = current;
        Node* prev = NULL;

        while (temp->next) {
            if (temp->data.RNTI == current->next->data.RNTI) {
                // Duplicate found
                Node* to_remove = current->next;
                current->next = to_remove->next;

                free(to_remove);
                list->node_count--;
                removed_count++;
            } else {
                prev = temp;
                temp = temp->next;
            }
        }

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return removed_count;
}

// Log messages based on log level
void log_message(ThreadSafeLinkedList* list, int level, const char* message) {
    if (level <= list->log_level) {
        printf("Log [%d]: %s\n", level, message);
    }
}

// Export CRC error statistics in a standardized format
void export_statistics(const ThreadSafeLinkedList* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    size_t crc_error_count = 0;
    Node* current = list->head;

    while (current) {
        if (current->data.CRCFLAG != 0) { // Assume non-zero CRCFLAG indicates an error
            crc_error_count++;
        }
        current = current->next;
    }

    printf("Total entries: %zu\nCRC errors: %zu\n", list->node_count, crc_error_count);

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

// Garbage collect obsolete structures
void garbage_collect(ThreadSafeLinkedList* list) {
    // Implement garbage collection logic here.
    // This is a placeholder for the actual GC implementation, which might depend on additional context or criteria.
}

int main() {
    ThreadSafeLinkedList list;
    init_linked_list(&list, sizeof(Node), 1000); // Initialize with block size and pool capacity

    NFAPI_CRC_INDICATION_PDU_T data = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1001, .CRC_INDICATION_REL8_TAG = 2, .CRCFLAG = rand() % 2 };

    add_to_list(&list, &data);
    remove_duplicates(&list);

    export_statistics(&list);

    garbage_collect(&list);
    destroy_linked_list(&list);

    return 0;
}
