void manage_dynamic_memory(const char *config_file, NodeCallback callback) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Error opening configuration file");
        return;
    }

    int num_nodes, min_value, max_value;
    fscanf(file, "%d %d %d", &num_nodes, &min_value, &max_value);
    fclose(file);

    if (num_nodes <= 0 || min_value > max_value) {
        fprintf(stderr, "Invalid configuration\n");
        return;
    }

    // Allocate memory for nodes
    Node *head = NULL, *current = NULL;
    for (int i = 0; i < num_nodes; ++i) {
        Node *new_node = (Node *)malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation failed");
            while (head) { // Free allocated nodes in case of failure
                Node *temp = head;
                head = head->next;
                free(temp);
            }
            return;
        }

        new_node->value = min_value + rand() % (max_value - min_value + 1);
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }

        current = new_node;
    }

    // Apply callback to each node
    Node *node_iter = head;
    while (node_iter) {
        if (callback) {
            callback(node_iter);
        }
        node_iter = node_iter->next;
    }

    // Free memory for nodes
    Node *free_node;
    while (head) {
        free_node = head;
        head = head->next;
        free(free_node);
    }
}

// Example usage of the callback function
