    system("sudo apt-get install openssl");
    #endif
}

int parse_json_config(const char* config_content, ConfigParams* params) {
    json_error_t error;
    json_t *root = json_loads(config_content, 0, &error);
    if (!root) {
        log_message("JSON parsing error: ", LOG_LEVEL_PROD);
        return 0;
    }

    json_t *key = json_object_get(root, "encryption_key");
    json_t *iv = json_object_get(root, "initialization_vector");
    json_t *cipher_type = json_object_get(root, "cipher_type");

    if (!json_is_string(key) || !json_is_string(iv) || !json_is_string(cipher_type)) {
        log_message("Malformed JSON configuration.", LOG_LEVEL_PROD);
        json_decref(root);
        return 0;
    }

    params->encryption_key = strdup(json_string_value(key));
    params->initialization_vector = strdup(json_string_value(iv));
    params->cipher_type = strdup(json_string_value(cipher_type));

    json_decref(root);
    return 1;
}

void initialize_openssl(ConfigParams* params) {
#ifdef __linux__
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();
#endif
}

void perform_operation(int encrypt_flag) {
#ifdef __linux__
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message("Failed to create cipher context.", LOG_LEVEL_PROD);
        return;
    }

    int result;
    if (encrypt_flag) {
        result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)params->encryption_key, (unsigned char*)params->initialization_vector);
    } else {
        result = EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)params->encryption_key, (unsigned char*)params->initialization_vector);
    }

    if (!result) {
        log_message("Failed to initialize cipher.", LOG_LEVEL_PROD);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Example: Perform encryption/decryption here

    EVP_CIPHER_CTX_free(ctx);
#endif
}

void rate_limiter() {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int count = 0;
    static time_t start_time;

    pthread_mutex_lock(&mutex);

    if (count == 0) {
        start_time = time(NULL);
    }

    if ((time(NULL) - start_time) * MAX_OPERATIONS_PER_SECOND <= count) {
        sleep(1);
        count = 0;
        start_time = time(NULL);
    }

    count++;
    pthread_mutex_unlock(&mutex);
}

void handle_error(const char* error_message) {
    log_message(error_message, LOG_LEVEL_PROD);
}

void log_message(const char* message, int level) {
#ifdef __linux__
    FILE *log_file = fopen("app.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
#endif
}
```

