#define MAX_RECORDS 10000
#define LATENCY_UPDATE_INTERVAL 5 // seconds

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    pthread_mutex_t lock;
    double average_latency;
} RecordManager;

// Simulate an external latency measurement service
void* update_latency_service(void *arg) {
    RecordManager *manager = (RecordManager *)arg;
    while (1) {
        // Simulating retrieval of updated latency
        double new_latency = ((double)(rand() % 100)) / 10.0; 
        pthread_mutex_lock(&manager->lock);
        manager->average_latency = new_latency;
        printf("Updated average latency: %.2f\n", new_latency);
        pthread_mutex_unlock(&manager->lock);
        sleep(LATENCY_UPDATE_INTERVAL);
    }
}

void initialize_manager(RecordManager *manager, size_t count) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Exceeded maximum record limit.\n");
        exit(EXIT_FAILURE);
    }

    manager->offsets = malloc(count * sizeof(long));
    manager->keys = malloc(count * sizeof(int));
    manager->records = malloc(count * sizeof(record *));
    manager->count = count;

    if (!manager->offsets || !manager->keys || !manager->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->average_latency = 0.0;

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        manager->offsets[i] = rand();
        manager->keys[i] = rand();

        record *rec = malloc(sizeof(record));
        if (!rec) {
            fprintf(stderr, "Memory allocation failed for a record.\n");
            exit(EXIT_FAILURE);
        }
        rec->value = (rand() % 100); // Random number between 0 and 99
        manager->records[i] = rec;
    }

    pthread_t latency_thread;
    if (pthread_create(&latency_thread, NULL, update_latency_service, manager)) {
        fprintf(stderr, "Failed to create latency update thread.\n");
        exit(EXIT_FAILURE);
    }
}

void free_manager(RecordManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    RecordManager manager;
    initialize_manager(&manager, 5000); // Initialize with 5000 records

    sleep(20); // Let the latency service run for a while
    free_manager(&manager);

    return 0;
}
