#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_OFFSETS 10000
#define RNTI_MAX 65535

typedef struct {
    int tag;
    unsigned int rnti;
    int crcIndicationRel8;
    float snr;
} NFAPI_MESSAGE_PDU_T;

typedef struct ListNode {
    long offset;
    int key;
    struct ListNode* prev;
    struct ListNode* next;
} ListNode;

long resourceOffsets[MAX_OFFSETS] = {0};
int globalMaxKey = -1;
pthread_mutex_t maxKeyMutex = PTHREAD_MUTEX_INITIALIZER;

ListNode* createNode(long offset, int key) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return NULL;
    newNode->offset = offset;
    newNode->key = key;
    newNode->prev = newNode->next = NULL;
    return newNode;
}

void insertSorted(ListNode** head, long offset, int key) {
    ListNode* newNode = createNode(offset, key);
    if (!newNode) return;

    pthread_mutex_lock(&maxKeyMutex);

    if (*head == NULL || (*head)->key < key) {
        newNode->next = *head;
        if (*head != NULL) (*head)->prev = newNode;
        *head = newNode;
    } else {
        ListNode* current = *head;
        while (current->next && current->next->key >= key) {
            current = current->next;
        }
        newNode->next = current->next;
        if (current->next != NULL) current->next->prev = newNode;
        current->next = newNode;
        newNode->prev = current;
    }

    if (newNode->key > globalMaxKey) {
        globalMaxKey = newNode->key;
    }
    pthread_mutex_unlock(&maxKeyMutex);
}

void freeList(ListNode* head) {
    while (head) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int isValidKey(int key, int* keys, size_t count) {
    if (key < 0 || key > RNTI_MAX) return 0;
    for (size_t i = 0; i < count; ++i) {
        if (keys[i] == key) return 0;
    }
    return 1;
}

void initializeNFAPI_MESSAGE_PDU(int numUes) {
    NFAPI_MESSAGE_PDU_T* messages = malloc(numUes * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!messages) return;

    for (int i = 0; i < numUes; ++i) {
        messages[i].tag = i + 1;
        messages[i].rnti = rand() % RNTI_MAX + 1;
        messages[i].crcIndicationRel8 = rand() % 2;
        float noiseFactor = ((float)(rand() % 100)) / 100.0f;
        messages[i].snr = 10.0f - noiseFactor; // Simulated SNR
    }

    for (int i = 0; i < numUes; ++i) {
        printf("Message[%d]: Tag=%d, RNTI=%u, CRC=%d, SNR=%.2f\n",
               i, messages[i].tag, messages[i].rnti,
               messages[i].crcIndicationRel8, messages[i].snr);
    }

    free(messages);
}

void handleUserInput(int expectedNumRecords) {
    int* keys = NULL;
    size_t keyCount = 0;
    ListNode* head = NULL;

    printf("Enter keys (0 to %d). Enter a negative number to finish:\n", RNTI_MAX);

    while (keyCount < expectedNumRecords) {
        int key;
        scanf("%d", &key);
        if (key < 0 || !isValidKey(key, keys, keyCount)) break;

        size_t newSize = (keyCount + 1) * sizeof(int);
        int* newKeys = realloc(keys, newSize);
        if (!newKeys) {
            freeList(head);
            free(keys);
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        keys = newKeys;
        keys[keyCount++] = key;

        long offsetIndex = rand() % MAX_OFFSETS; // Simulate offset assignment
        insertSorted(&head, resourceOffsets[offsetIndex], key);

        if (keyCount == expectedNumRecords) {
            printf("Max Key: %d\n", globalMaxKey);
        }
    }

    freeList(head);
    free(keys);
}

int main() {
    srand(time(NULL));

    initializeNFAPI_MESSAGE_PDU(10); // Example for 10 UEs

    int expectedNumRecords;
    printf("Enter the number of records to process: ");
    scanf("%d", &expectedNumRecords);

    handleUserInput(expectedNumRecords);

    pthread_mutex_destroy(&maxKeyMutex);
    return 0;
}
