['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU* head;
    NFAPI_CRC_INDICATION_PDU* tail;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} DynamicLinkedList;

void init_list(DynamicLinkedList* list, size_t max_size) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void destroy_list(DynamicLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

void randomize_crcflag(NFAPI_CRC_INDICATION_PDU* pdu) {
    srand(time(NULL));
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

int add_element(DynamicLinkedList* list, int rx_ue_info_tag, int rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Indicate overflow
    }

    NFAPI_CRC_INDICATION_PDU* new_pdu = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_pdu) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_pdu->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_pdu->RNTI = rnti;
    randomize_crcflag(new_pdu);
    new_pdu->next = NULL;

    if (list->tail) {
        list->tail->next = new_pdu;
    } else {
        list->head = new_pdu;
    }
    list->tail = new_pdu;
    list->count++;

    pthread_cond_broadcast(&list->cond);
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_element(DynamicLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is empty
    }

    NFAPI_CRC_INDICATION_PDU* temp = list->head;
    list->head = list->head->next;

    if (list->head == NULL) {
        list->tail = NULL;
    }
    list->count--;

    free(temp);
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void* consumer_thread(void* arg) {
    DynamicLinkedList* list = (DynamicLinkedList*)arg;

    while (1) {
        pthread_mutex_lock(&list->lock);

        while (list->count == 0) {
            pthread_cond_wait(&list->cond, &list->lock);
        }

        remove_element(list);

        pthread_mutex_unlock(&list->lock);

        // Simulate processing
        printf("Processed an element\n");
    }
    return NULL;
}

int main() {
    DynamicLinkedList list;
    init_list(&list, 10);

    pthread_t consumer;
    pthread_create(&consumer, NULL, consumer_thread, &list);

    for (int i = 0; i < 15; ++i) {
        int result = add_element(&list, i, i * 2);
        if (result == -1) {
            printf("List is full\n");
        } else if (result == -2) {
            printf("Memory allocation failed\n");
        }
    }

    pthread_join(consumer, NULL);

    destroy_list(&list);
    return 0;
}
```

This code implements a dynamic linked list with thread-safe operations for adding and removing elements. It uses mutexes and condition variables to manage concurrency, ensuring that multiple threads can safely interact with the list. The `add_element` function handles memory allocation failures and checks for overflow conditions. A consumer thread is provided to simulate processing of elements from the list.']

