#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_STRUCTURES 10000
#define DEFAULT_STRUCTURES 1000

typedef struct {
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Simulated external logging framework function
void log_rnti(int rnti) {
    printf("RNTI logged: %d\n", rnti);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    size_t count;
} PopulationResult;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int is_unique(int *rnti_set, int rnti, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (rnti_set[i] == rnti) return 0;
    }
    return 1;
}

PopulationResult* populate_nfa_structures(size_t num_structures) {
    PopulationResult *result = NULL;

    if (num_structures > MAX_STRUCTURES) {
        fprintf(stderr, "Requested number exceeds maximum allowed structures.\n");
        return result;
    }

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int *rnti_set = malloc(sizeof(int) * num_structures);

    if (!structures || !rnti_set) {
        perror("Memory allocation failed");
        free(structures);
        free(rnti_set);
        return result;
    }

    srand(time(NULL));

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    size_t generated = 0;
    while (generated < num_structures) {
        pthread_mutex_lock(&mutex);

        int rnti = rand() % 65536; // Simulate RNTI generation
        uint8_t crc_flag = rand() & 1;

        if (!is_unique(rnti_set, rnti, generated)) {
            pthread_mutex_unlock(&mutex);
            continue;
        }

        structures[generated].RNTI = rnti;
        structures[generated].CRCFLAG = crc_flag;
        rnti_set[generated] = rnti;

        log_rnti(rnti);

        ++generated;

        pthread_mutex_unlock(&mutex);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed_time = (end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1e9;
    printf("Total time taken: %.6f seconds\n", elapsed_time);

    result = malloc(sizeof(PopulationResult));
    if (!result) {
        perror("Failed to allocate PopulationResult");
        free(structures);
        free(rnti_set);
        return NULL;
    }

    result->structures = structures;
    result->count = generated;

    free(rnti_set);
    return result;
}

void free_population_result(PopulationResult *result) {
    if (result) {
        free(result->structures);
        free(result);
    }
}

int main(int argc, char **argv) {
    size_t num_structures = DEFAULT_STRUCTURES;

    if (argc > 1) {
        sscanf(argv[1], "%zu", &num_structures);
    }

    PopulationResult *result = populate_nfa_structures(num_structures);

    if (!result) {
        fprintf(stderr, "Failed to generate structures.\n");
        return EXIT_FAILURE;
    }

    // Simulate asynchronous processing
    printf("Asynchronous processing simulated...\n");

    free_population_result(result);
    return EXIT_SUCCESS;
}
```

### Key Points:
