```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define CACHE_SIZE 100

typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    char dns_server[64];
} NetworkConfig;

typedef struct CacheEntry {
    NetworkConfig config;
    time_t last_access_time;
    struct CacheEntry* next;
} CacheEntry;

typedef struct {
    CacheEntry* entries[CACHE_SIZE];
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConfigCache;

static inline uint32_t hash(const char* str) {
    uint32_t hash = 0;
    while (*str) {
        hash = (hash << 5) + *str++;
    }
    return hash % CACHE_SIZE;
}

void cache_init(ConfigCache* cache) {
    memset(cache, 0, sizeof(ConfigCache));
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->cond, NULL);
}

int cache_put(ConfigCache* cache, const NetworkConfig* config) {
    pthread_mutex_lock(&cache->lock);

    uint32_t index = hash(config->ip_address);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        int pos = (index + i) % CACHE_SIZE;
        if (!cache->entries[pos]) {
            CacheEntry* entry = malloc(sizeof(CacheEntry));
            if (!entry) {
                pthread_mutex_unlock(&cache->lock);
                return -1; // Memory allocation failure
            }
            memcpy(&entry->config, config, sizeof(NetworkConfig));
            entry->last_access_time = time(NULL);
            entry->next = NULL;
            cache->entries[pos] = entry;
            if (cache->size < CACHE_SIZE) {
                cache->size++;
            } else {
                // Implement LRU eviction here
                // For simplicity, evict the oldest entry
                CacheEntry* prev = NULL;
                CacheEntry* oldest = NULL;
                time_t oldest_time = time(NULL);

                for (int j = 0; j < CACHE_SIZE; ++j) {
                    if (cache->entries[j]) {
                        if (!oldest || cache->entries[j]->last_access_time < oldest_time) {
                            oldest = cache->entries[j];
                            oldest_time = oldest->last_access_time;
                        }
                        prev = cache->entries[j];
                    }
                }

                if (prev && prev->next == oldest) {
                    prev->next = NULL;
                } else {
                    for (int j = 0; j < CACHE_SIZE; ++j) {
                        CacheEntry* entry = cache->entries[j];
                        while (entry && entry->next != oldest) {
                            entry = entry->next;
                        }
                        if (entry) {
                            entry->next = oldest->next;
                        }
                    }
                }

                free(oldest);
            }
            pthread_mutex_unlock(&cache->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return -2; // Cache full, unable to add
}

NetworkConfig* cache_get(ConfigCache* cache, const char* ip_address) {
    pthread_mutex_lock(&cache->lock);

    uint32_t index = hash(ip_address);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        int pos = (index + i) % CACHE_SIZE;
        CacheEntry* entry = cache->entries[pos];
        while (entry) {
            if (strcmp(entry->config.ip_address, ip_address) == 0) {
                entry->last_access_time = time(NULL);
                pthread_mutex_unlock(&cache->lock);
                return &entry->config;
            }
            entry = entry->next;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL; // Cache miss
}

void cache_destroy(ConfigCache* cache) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        CacheEntry* entry = cache->entries[i];
        while (entry) {
            CacheEntry* next = entry->next;
            free(entry);
            entry = next;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->cond);
}

void log_operation(const char* operation, const NetworkConfig* config) {
    printf("[%s] %s: IP=%s, Subnet=%s, Gateway=%s, DNS=%s\n",
           __func__, operation,
           config ? config->ip_address : "NULL",
           config ? config->subnet_mask : "NULL",
           config ? config->gateway : "NULL",
           config ? config->dns_server : "NULL");
}

// Example usage
int main() {
    ConfigCache cache;
    cache_init(&cache);

    NetworkConfig config1 = {"192.168.1.1", "255.255.255.0", "192.168.1.254", "8.8.8.8"};
    cache_put(&cache, &config1);
    log_operation("PUT", &config1);

    NetworkConfig* retrieved_config = cache_get(&cache, "192.168.1.1");
    if (retrieved_config) {
        log_operation("GET", retrieved_config);
    } else {
        printf("Cache miss\n");
    }

    cache_destroy(&cache);
    return 0;
}
```

This code provides a basic implementation of a dynamic network configuration cache with concurrency support, memory management, and error handling. It includes logging for operations and uses an LRU eviction policy when the cache is full.']

