        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(ConcurrentLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_node(ConcurrentLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || list->size >= MAX_LIST_SIZE) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return -1;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int delete_node(ConcurrentLinkedList* list, unsigned int RNTI) {
    if (!list || !list->head) return -1;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }
    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

