// Logger function for memory operations
void log_memory_operation(const char *operation, size_t size) {
    printf("Memory %s: %zu bytes\n", operation, size);
}

// Error handling function
void handle_allocation_error(void *ptr) {
    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

// Custom pseudo-random number generator seeded by the caller
unsigned int custom_random(unsigned int *seedp) {
    unsigned int seed = *seedp;
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    *seedp = seed;
    return seed;
}

// Function to initialize NFAPI_CRC_INDICATION_PDU_T array
NFAPI_CRC_INDICATION_PDU_T* init_nfa_crc_indication_pdu(size_t num_elements, unsigned int seed) {
    if (num_elements > MAX_ELEMENTS) num_elements = MAX_ELEMENTS;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    handle_allocation_error(pdu_array);

    log_memory_operation("allocated", num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < num_elements; ++i) {
        pdu_array[i].CRCFLAG = custom_random(&seed);
        pdu_array[i].RX_UE_INFORMATION_TAG = custom_random(&seed);
        pdu_array[i].RNTI = custom_random(&seed);
        for (int j = 0; j < 4; ++j) {
            pdu_array[i].CRC_INDICATION_REL8_TAG[j] = custom_random(&seed) & 0xFF;
        }
    }

    return pdu_array;
}

// Function to check if a key exists in the record array
int key_exists(record_t *records, int num_elements, int key) {
