}

// Function to initialize record array
record_t* init_records(size_t num_elements, unsigned int seed) {
    if (num_elements > MAX_ELEMENTS) num_elements = MAX_ELEMENTS;

    record_t *records = malloc(num_elements * sizeof(record_t));
    handle_allocation_error(records);

    log_memory_operation("allocated", num_elements * sizeof(record_t));

    for (size_t i = 0; i < num_elements; ++i) {
        records[i].value = custom_random(&seed);
        records[i].offset = malloc(sizeof(long));
        handle_allocation_error(records[i].offset);

        records[i].key = NULL;
        if (!key_exists(records, i, (int)custom_random(&seed))) {
            records[i].key = malloc(sizeof(int));
            handle_allocation_error(records[i].key);
            *records[i].key = custom_random(&seed);
        }
    }

    return records;
}

// Function to free allocated memory
void free_memory(NFAPI_CRC_INDICATION_PDU_T *pdu_array, record_t *records, size_t num_records) {
    if (pdu_array) {
        log_memory_operation("freed", num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(pdu_array);
    }

    if (records) {
        for (size_t i = 0; i < num_records; ++i) {
            if (records[i].offset) {
                log_memory_operation("freed", sizeof(long));
                free(records[i].offset);
            }
            if (records[i].key) {
                log_memory_operation("freed", sizeof(int));
                free(records[i].key);
            }
        }
        log_memory_operation("freed", num_records * sizeof(record_t));
        free(records);
    }
}
