#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_CONNECTIONS 100

typedef struct {
    int connection_id;
    char remote_address[INET6_ADDRSTRLEN];
    char local_address[INET6_ADDRSTRLEN];
    double current_bandwidth; // in Mbps
    double latency;           // in ms
} TCP_CONNECTION_INFO_T;

typedef struct {
    TCP_CONNECTION_INFO_T *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double total_bandwidth;
    double min_latency;
    double max_throughput;
} ConnectionPool;

ConnectionPool* create_connection_pool(size_t initial_capacity) {
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    pool->connections = malloc(initial_capacity * sizeof(TCP_CONNECTION_INFO_T));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->total_bandwidth = 0.0;
    pool->min_latency = INFINITY;
    pool->max_throughput = 0.0;

    return pool;
}

void destroy_connection_pool(ConnectionPool *pool) {
    if (pool) {
        free(pool->connections);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int add_connection(ConnectionPool *pool, const TCP_CONNECTION_INFO_T *info) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        TCP_CONNECTION_INFO_T *new_connections = realloc(pool->connections, new_capacity * sizeof(TCP_CONNECTION_INFO_T));
        if (!new_connections) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }

    memcpy(&pool->connections[pool->count], info, sizeof(TCP_CONNECTION_INFO_T));
    pool->count++;
    pool->total_bandwidth += info->current_bandwidth;
    if (info->latency < pool->min_latency) {
        pool->min_latency = info->latency;
    }
    if (info->current_bandwidth > pool->max_throughput) {
        pool->max_throughput = info->current_bandwidth;
    }

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

int remove_connection(ConnectionPool *pool, int connection_id) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->connections[i].connection_id == connection_id) {
            size_t index = i;
            pool->total_bandwidth -= pool->connections[index].current_bandwidth;
            pool->count--;

            // Move the last element to fill the gap
            if (index < pool->count) {
                memcpy(&pool->connections[index], &pool->connections[pool->count], sizeof(TCP_CONNECTION_INFO_T));
            }

            pthread_mutex_unlock(&pool->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // Connection not found
}

void update_metrics(ConnectionPool *pool, double (*callback)(int connection_id)) {
    pthread_mutex_lock(&pool->lock);

    pool->total_bandwidth = 0.0;
    pool->min_latency = INFINITY;
    pool->max_throughput = 0.0;

    for (size_t i = 0; i < pool->count; ++i) {
        double bandwidth = callback(pool->connections[i].connection_id);
        pool->connections[i].current_bandwidth = bandwidth;
        pool->total_bandwidth += bandwidth;

        // Simulate latency update
        pool->connections[i].latency = (rand() % 100) + 10; // Example: Random latency between 10ms and 110ms

        if (pool->connections[i].latency < pool->min_latency) {
            pool->min_latency = pool->connections[i].latency;
        }
        if (bandwidth > pool->max_throughput) {
            pool->max_throughput = bandwidth;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void log_connection_stats(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    printf("Total Bandwidth: %.2f Mbps\n", pool->total_bandwidth);
    printf("Minimum Latency: %.2f ms\n", pool->min_latency);
    printf("Maximum Throughput: %.2f Mbps\n", pool->max_throughput);

    pthread_mutex_unlock(&pool->lock);
}

// Example usage
double example_callback(int connection_id) {
    // Simulate bandwidth measurement
    return (rand() % 1000) + 50; // Example: Random bandwidth between 50 and 1050 Mbps
}

int main() {
    ConnectionPool *pool = create_connection_pool(MAX_CONNECTIONS);

    TCP_CONNECTION_INFO_T conn1 = {1, "192.168.1.2", "192.168.1.1", 100.0, 20.0};
    add_connection(pool, &conn1);

    update_metrics(pool, example_callback);
    log_connection_stats(pool);

    destroy_connection_pool(pool);
    return 0;
}
```

This code provides a basic implementation of a dynamic connection pool for managing TCP connections in a high-performance streaming media distribution application. It supports concurrent access with thread safety, dynamic scaling, and real-time metric updates using a callback function. The code includes functions to add and remove connections, update metrics, and log statistics.']

