#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

// Thread-safe memory allocation
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Thread-safe memory mapping
void* safe_mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset) {
    void *mapped = mmap(addr, length, prot, flags, fd, offset);
    if (mapped == MAP_FAILED) {
        perror("Failed to map file");
        exit(EXIT_FAILURE);
    }
    return mapped;
}

// Read CSV and populate records
int read_csv(const char *filename, Record **records, size_t *record_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    char line[1024];
    int count = 0;

    // Count valid records
    while (fgets(line, sizeof(line), file)) {
        long offset;
        int key;
        double timestamp;

        if (sscanf(line, "%ld,%d,%lf", &offset, &key, &timestamp) == 3) {
            count++;
        }
    }

    rewind(file);

    *records = safe_malloc(count * sizeof(Record));
    *record_count = count;

    // Read and validate records
    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        long offset;
        int key;
        double timestamp;

        if (sscanf(line, "%ld,%d,%lf", &offset, &key, &timestamp) == 3) {
            (*records)[i].offset = offset;
            (*records)[i].key = key;
            (*records)[i].timestamp = timestamp;
            i++;
        }
    }

    fclose(file);
    return 0;
}

// Serialize records to a memory-mapped file
int serialize_records(const char *filename, const Record *records, size_t record_count) {
    int fd = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("Failed to open file for writing");
        return -1;
    }

    size_t data_size = record_count * sizeof(Record);
    if (ftruncate(fd, data_size) == -1) {
        perror("Failed to set file size");
        close(fd);
        return -1;
    }

    Record *mapped_data = safe_mmap(NULL, data_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

    memcpy(mapped_data, records, data_size);

    if (msync(mapped_data, data_size, MS_SYNC) == -1) {
        perror("Failed to synchronize file with memory");
        munmap(mapped_data, data_size);
        close(fd);
        return -1;
    }

    munmap(mapped_data, data_size);
    close(fd);

    return 0;
}

// Deserialize records from a memory-mapped file
int deserialize_records(const char *filename, Record **records, size_t *record_count) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file for reading");
        return -1;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Failed to get file size");
        close(fd);
        return -1;
    }

    *record_count = sb.st_size / sizeof(Record);

    Record *mapped_data = safe_mmap(NULL, sb.st_size, PROT_READ, MAP_SHARED, fd, 0);

    *records = malloc(sb.st_size);
    memcpy(*records, mapped_data, sb.st_size);

    munmap(mapped_data, sb.st_size);
    close(fd);

    return 0;
}

// Clean up memory
void cleanup(Record *records) {
    free(records);
}
```

### Explanation:
- **Dynamic Memory Allocation**: `safe_malloc` ensures safe allocation and exits if it fails.
- **CSV Reading**: Records are validated while reading from the CSV file. Valid records are counted first, then read again into dynamically allocated memory.
- **Memory Mapping for Serialization**: Uses `mmap` to map files directly into process address space, which is efficient for large datasets.
- **Thread Safety and Synchronization**: The use of `msync()` ensures changes in memory-mapped regions are synchronized with the file system.
- **Error Handling**: Comprehensive error handling using `perror` for I/O operations.

This approach balances memory efficiency, read performance, and thread safety suitable for high-concurrency environments.']

