#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INPUT_SIZE 1000
#define VALUE_RANGE_MIN 1
#define VALUE_RANGE_MAX 10000
#define CRC_FLAG_PROBABILITY 0.3

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int validate_input(int *input, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if (input[i] < VALUE_RANGE_MIN || input[i] > VALUE_RANGE_MAX) return 0;
        for (size_t j = 0; j < i; j++) {
            if (input[i] == input[j]) return 0;
        }
    }
    return 1;
}

int find_largest(int *input, size_t size) {
    int largest = input[0];
    for (size_t i = 1; i < size; i++) {
        if (input[i] > largest) largest = input[i];
    }
    printf("Largest integer: %d\n", largest);
    return largest;
}

int generate_crc_flags(NFAPI_CRC_INDICATION_PDU_T *pdu_array, size_t pdu_count) {
    srand(time(NULL));
    for (size_t i = 0; i < pdu_count; i++) {
        pdu_array[i].CRCFLAG = (rand() / (float)RAND_MAX) < CRC_FLAG_PROBABILITY ? 1 : 0;
    }
    return 1;
}

int populate_pdu_array(int *input, size_t input_size, NFAPI_CRC_INDICATION_PDU_T **pdu_array_out) {
    if (!validate_input(input, input_size)) {
        fprintf(stderr, "Invalid input data.\n");
        return -1;
    }

    *pdu_array_out = (NFAPI_CRC_INDICATION_PDU_T *)malloc(input_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu_array_out == NULL) {
        perror("Memory allocation failed");
        return -2;
    }

    for (size_t i = 0; i < input_size; i++) {
        (*pdu_array_out)[i].RX_UE_INFORMATION_TAG = input[i] % VALUE_RANGE_MAX;
        (*pdu_array_out)[i].RNTI = (input[i] * 31) % VALUE_RANGE_MAX;
        (*pdu_array_out)[i].CRC_INDICATION_REL8_TAG = (input[i] * 17) % VALUE_RANGE_MAX;
    }

    if (!generate_crc_flags(*pdu_array_out, input_size)) {
        fprintf(stderr, "Failed to generate CRC flags.\n");
        free(*pdu_array_out);
        return -3;
    }

    return 0;
}

int write_to_file(NFAPI_CRC_INDICATION_PDU_T *pdu_array, size_t pdu_count) {
    FILE *file = fopen("crc_indications.bin", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    if (fwrite(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T), pdu_count, file) != pdu_count) {
        perror("Failed to write data to file");
        fclose(file);
        return -2;
    }

    fclose(file);
    return 0;
}

int main() {
    int input[MAX_INPUT_SIZE];
    size_t input_size = 0;

    printf("Enter integers (end with non-integer): ");
    while (scanf("%d", &input[input_size]) == 1 && input_size < MAX_INPUT_SIZE) {
        input_size++;
    }

    if (!validate_input(input, input_size)) {
        fprintf(stderr, "Input contains duplicates or out-of-range values.\n");
        return -1;
    }

    find_largest(input, input_size);

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int result = populate_pdu_array(input, input_size, &pdu_array);
    if (result != 0) {
        return result;
    }

    result = write_to_file(pdu_array, input_size);
    if (result != 0) {
        free(pdu_array);
        return result;
    }

    free(pdu_array);
    printf("Data written successfully.\n");
    return 0;
}
