// Function to allocate memory for an array of Records
Record* allocate_records(size_t num_records, double min_value, double max_value) {
    if (num_records <= 0 || num_records > 10000000) return NULL;

    // Allocate memory for records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));

    long current_offset = 1;
    int unique_check[num_records] = {0}; // Simplified check within reasonable range

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = current_offset++;
        records[i].key = rand() % 10000; // Example key generation
        records[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);

        // Ensure uniqueness of offsets
        if (!unique_check[(int)(records[i].offset % num_records)]) {
            unique_check[(int)(records[i].offset % num_records)] = 1;
        } else {
            i--; // Retry this iteration with a new offset
        }
    }

    return records;
}

