    record_t* records = malloc(max_offsets_limit * sizeof(record_t));
    if (!records) {
        logger.log("Failed to allocate memory for records", LOG_ERROR);
        free(keys);
        free(offsets);
        json_decref(root);
        return -1;
    }

    // Initialize records with random values
    pthread_mutex_lock(&lock);  // Ensure thread safety
    for (int i = 0; i < max_offsets_limit; ++i) {
        int range_size = random_range_max - random_range_min + 1;
        int rand_value = RAND_priv_bytes(NULL, sizeof(int));
        records[i].value = random_range_min + (rand_value % range_size);
    }
    pthread_mutex_unlock(&lock);

    // Log success
    logger.log("Crypto configuration completed successfully", LOG_WARNING);

    // Clean up JSON object and free memory if needed later
    json_decref(root);

    return 0; // Success
}
