typedef struct {
    int value;
} Record;

// Function prototypes
int initializeMemory(long *offsets, size_t offset_size, int *keys, size_t key_size, Record **records, size_t record_size, const char* log_file_path, int logging_frequency);
void cleanup(long *offsets, int *keys, Record *records);
void *logRecords(void *args);

// Thread-safe mutex
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initializeMemory(long *offsets, size_t offset_size, int *keys, size_t key_size, Record **records, size_t record_size, const char* log_file_path, int logging_frequency) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for arrays and check for allocation failures
    offsets = (long *)malloc(offset_size * sizeof(long));
    if (!offsets) return -1;

    keys = (int *)malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return -2;
    }

    *records = (Record *)malloc(record_size * sizeof(Record));
    if (!*records) {
        free(keys);
        free(offsets);
        return -3;
    }

    // Initialize arrays
    for (size_t i = 0; i < offset_size; ++i) offsets[i] = i;
    for (size_t i = 0; i < key_size; ++i) keys[i] = rand() % 100;

    for (size_t i = 0; i < record_size; ++i) {
        (*records)[i].value = rand() % 50 + 1; // Random value between 1 and 50
    }

    // Set up logging thread
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, logRecords, (void *)(size_t)record_size)) {
        cleanup(offsets, keys, *records);
        return -4;
    }
    pthread_detach(log_thread);

    return 0; // Successful initialization
}

void cleanup(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}

void *logRecords(void *args) {
    size_t record_size = (size_t)args;
    FILE *file = fopen("audit_log.txt", "w");
    if (!file) return NULL;

    while (1) {
        pthread_mutex_lock(&lock);

        fprintf(file, "Current records:\n");
        for (size_t i = 0; i < record_size; ++i) {
            fprintf(file, "Record %zu: Value = %d\n", i, ((Record *)records[i].value));
        }

        pthread_mutex_unlock(&lock);
        sleep(logging_frequency);

        // For demonstration purposes only
    }
    fclose(file);
    return NULL;
}
