#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/time.h>
#include <curl/curl.h>

#define TIMEOUT 5

// Function to resolve DNS with timeout and error handling
int resolve_dns(const char *hostname, u_char **ip_address) {
    struct addrinfo hints, *res;
    int status, retval = -1;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    struct timeval start_time, current_time;
    gettimeofday(&start_time, NULL);

    while (res) {
        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &((struct sockaddr_in *)res->ai_addr)->sin_addr, ipstr, sizeof(ipstr));

        u_char *addr = malloc(sizeof(struct in_addr));
        if (!addr) return -1;

        memcpy(addr, &((struct sockaddr_in *)res->ai_addr)->sin_addr, sizeof(struct in_addr));

        gettimeofday(&current_time, NULL);
        long elapsed = (current_time.tv_sec - start_time.tv_sec) * 1000 + 
                       (current_time.tv_usec - start_time.tv_usec) / 1000;

        if (elapsed >= TIMEOUT * 1000) {
            free(addr);
            res = res->ai_next;
            continue;
        }

        *ip_address = addr;
        retval = 0;
        break;
    }

    freeaddrinfo(res);
    return retval;
}

// Function to process a line and calculate the average of the last two numerical fields
void process_line(const char *line, double *average) {
    char *token, *last_token = NULL;
    int count = 0;

    for (token = strtok((char *)line, " \t"); token; token = strtok(NULL, " \t")) {
        if (++count >= strlen(line) - strlen(token)) {
            last_token = token;
        }
    }

    if (last_token && last_token[1]) { // Check if there's at least one more field
        double num1 = atof(last_token);
        char *next_token = strtok(NULL, " \t");
        if (next_token) {
            double num2 = atof(next_token);
            *average = (num1 + num2) / 2;
        }
    }
}

// Function to read a large file efficiently and process each line
void process_file(const char *filename, const char *output_filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    FILE *out_file = fopen(output_filename, "w");
    if (!out_file) {
        fclose(file);
        return;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        double average = 0.0;
        process_line(buffer, &average);
        fprintf(out_file, "%f\n", average);
    }

    fclose(file);
    fclose(out_file);
}

// Callback function for curl write data
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Function to perform HTTP PUT request
int http_put(const char *url, const char *data) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    std::string readBuffer;
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    printf("Response: %s\n", readBuffer.c_str());
    curl_easy_cleanup(curl);
    return 0;
}

// Function to perform HTTP DELETE request
int http_delete(const char *url) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    std::string readBuffer;
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "DELETE");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    printf("Response: %s\n", readBuffer.c_str());
    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <hostname> <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *hostname = argv[1];
    const char *input_file = argv[2];
    const char *output_file = argv[3];

    u_char *ip_address = NULL;
    if (resolve_dns(hostname, &ip_address) == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(*((struct in_addr *)ip_address)));
        free(ip_address);
    } else {
        fprintf(stderr, "DNS resolution failed for hostname: %s\n", hostname);
        return EXIT_FAILURE;
    }

    process_file(input_file, output_file);

    const char *put_url = "http://example.com/api/resource";
    const char *put_data = "{\"key\":\"value\"}";
    if (http_put(put_url, put_data) != 0) {
        fprintf(stderr, "HTTP PUT request failed\n");
    }

    const char *delete_url = "http://example.com/api/resource/123";
    if (http_delete(delete_url) != 0) {
        fprintf(stderr, "HTTP DELETE request failed\n");
    }

    return EXIT_SUCCESS;
}
