#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/sha.h>

#define MAX_STRING_LENGTH 64
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 100

struct element {
    float floatValue;
    int intValue;
    char charValue[MAX_STRING_LENGTH];
};

int read_and_initialize(const char *filename, double **doublesArray, size_t *numDoubles,
                        char ***stringsArray, size_t *numStrings, struct element ***elementsArray, 
                        size_t *numElements) {

    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    // Seed for reproducibility
    srand(42);

    double *doubles = NULL;
    char **strings = NULL;
    struct element **elements = NULL;

    size_t doublesCapacity = 0, stringsCapacity = 0, elementsCapacity = 0;

    while (!feof(file)) {
        // Allocate and resize arrays if needed
        if (doublesCapacity == *numDoubles) {
            doublesCapacity = (*numDoubles ? *numDoubles : 1) * 2;
            double *temp = realloc(doubles, doublesCapacity * sizeof(double));
            if (!temp) {
                perror("Failed to allocate memory for doubles");
                fclose(file);
                return -1;
            }
            doubles = temp;
        }

        // Read a floating point number
        if (fscanf(file, "%lf", &doubles[*numDoubles]) == 1) {
            (*numDoubles)++;
        } else {
            break; // Invalid data or EOF reached
        }

        if (stringsCapacity == *numStrings) {
            stringsCapacity = (*numStrings ? *numStrings : 1) * 2;
            char **temp = realloc(strings, stringsCapacity * sizeof(char *));
            if (!temp) {
                perror("Failed to allocate memory for string pointers");
                fclose(file);
                return -1;
            }
            strings = temp;
        }

        // Read a string
        strings[*numStrings] = malloc(MAX_STRING_LENGTH);
        if (!strings[*numStrings]) {
            perror("Failed to allocate memory for string buffer");
            fclose(file);
            return -1;
        }
        if (fgets(strings[*numStrings], MAX_STRING_LENGTH, file)) {
            (*numStrings)++;
        } else {
            free(strings[*numStrings]);
            break; // Invalid data or EOF reached
        }

        if (elementsCapacity == *numElements) {
            elementsCapacity = (*numElements ? *numElements : 1) * 2;
            struct element **temp = realloc(elements, elementsCapacity * sizeof(struct element *));
            if (!temp) {
                perror("Failed to allocate memory for element pointers");
                fclose(file);
                return -1;
            }
            elements = temp;
        }

        // Allocate and populate a new element
        struct element *newElement = malloc(sizeof(struct element));
        if (!newElement) {
            perror("Failed to allocate memory for element structure");
            fclose(file);
            return -1;
        }

        newElement->floatValue = (float)(rand() % 100.0 + 0.5); // Example: random float
        newElement->intValue = rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1) + INT_RANGE_MIN;

        for (int i = 0; i < MAX_STRING_LENGTH - 1; ++i) {
            newElement->charValue[i] = 'A' + (rand() % 26);
        }
        newElement->charValue[MAX_STRING_LENGTH - 1] = '\0';

        elements[*numElements] = newElement;
        (*numElements)++;
    }

    fclose(file);

    // Cryptographic operation: Compute SHA-256 of all strings for integrity
    pthread_t threads[3];

    int result = pthread_create(&threads[0], NULL, compute_sha256_for_doubles, (void *)doubles);
    if (result != 0) {
        perror("Failed to create thread for doubles");
        return -1;
    }

    result = pthread_create(&threads[1], NULL, compute_sha256_for_strings, (void *)strings);
    if (result != 0) {
        perror("Failed to create thread for strings");
        return -1;
    }

    result = pthread_create(&threads[2], NULL, compute_sha256_for_elements, (void *)elements);
    if (result != 0) {
        perror("Failed to create thread for elements");
        return -1;
    }

    // Wait for threads to complete
    for (int i = 0; i < 3; ++i) {
        pthread_join(threads[i], NULL);
    }

    *doublesArray = doubles;
    *stringsArray = strings;
    *elementsArray = elements;

    return 0;
}

void* compute_sha256_for_doubles(void *data) {
    double *array = (double *)data;
    for (size_t i = 0; array[i] != '\0'; ++i) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, &array[i], sizeof(double));
        SHA256_Final(hash, &sha256);

        // Example: Print the hash
        printf("SHA-256 for double[%zu]: ", i);
        for (int j = 0; j < SHA256_DIGEST_LENGTH; ++j) {
            printf("%02x", hash[j]);
        }
        printf("\n");
    }
    return NULL;
}

void* compute_sha256_for_strings(void *data) {
    char **array = (char **)data;
    for (size_t i = 0; array[i] != '\0'; ++i) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, array[i], strlen(array[i]));
        SHA256_Final(hash, &sha256);

        // Example: Print the hash
        printf("SHA-256 for string[%zu]: ", i);
        for (int j = 0; j < SHA256_DIGEST_LENGTH; ++j) {
            printf("%02x", hash[j]);
        }
        printf("\n");
    }
    return NULL;
}

void* compute_sha256_for_elements(void *data) {
    struct element **array = (struct element **)data;
    for (size_t i = 0; array[i] != '\0'; ++i) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, &(*array[i]), sizeof(struct element));
        SHA256_Final(hash, &sha256);

        // Example: Print the hash
        printf("SHA-256 for element[%zu]: ", i);
        for (int j = 0; j < SHA256_DIGEST_LENGTH; ++j) {
            printf("%02x", hash[j]);
        }
        printf("\n");
    }
    return NULL;
}
