#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Helper function to find the largest integer in an array
int findLargest(int* arr, size_t count) {
    if (count == 0) return INT_MIN; // No valid numbers found

    int max = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to read integers from a file and process them
int* processFile(const char* filename, size_t maxCount, size_t* processedCount) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        return NULL;
    }

    int* validNumbers = (int*)malloc(sizeof(int));
    if (!validNumbers) {
        fclose(file);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    size_t capacity = 1; // Start with a capacity of 1 and grow as needed
    *processedCount = 0;

    int number;
    while (fscanf(file, "%d", &number) == 1 && *processedCount < maxCount) {
        if (number >= -1000 && number <= 1000) {
            if (*processedCount >= capacity) {
                // Double the capacity
                int* newNumbers = realloc(validNumbers, sizeof(int) * (capacity *= 2));
                if (!newNumbers) {
                    free(validNumbers);
                    fclose(file);
                    fprintf(stderr, "Memory allocation failed\n");
                    return NULL;
                }
                validNumbers = newNumbers;
            }
            validNumbers[(*processedCount)++] = number;
        }
    }

    fclose(file);

    // Shrink the array to fit the exact number of processed numbers
    int* finalArray = realloc(validNumbers, sizeof(int) * (*processedCount));
    if (!finalArray && *processedCount > 0) {
        free(validNumbers);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    return finalArray ? validNumbers : NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <filename> <maxCount>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* filename = argv[1];
    size_t maxCount = strtoul(argv[2], NULL, 10);

    size_t processedCount = 0;
    int* numbers = processFile(filename, maxCount, &processedCount);

    if (!numbers) {
        return EXIT_FAILURE;
    }

    if (processedCount == 0) {
        printf("No valid integers found within the specified range.\n");
        free(numbers);
        return EXIT_SUCCESS;
    }

    int largestNumber = findLargest(numbers, processedCount);
    printf("The largest integer is: %d\n", largestNumber);

    free(numbers);
    return EXIT_SUCCESS;
}
