// Simulated radio channel model function
fn simulate_radio_channel_model() -> f32 {
    let mut rng = rand::thread_rng();
    0.0..10.0 // Random SNR value between 0 and 10 dB for simulation purposes
        .map(|x| x + rng.gen_range(-1.0..1.0)) // Add some noise
        .next()
        .unwrap_or(0.0)
}

// Function to initialize and log NFAPI messages
fn initialize_and_log_nfaapi_messages(
    ue_list: &mut Vec<String>,  // Dynamic UE list
    directory_name: &str,
) {
    let dir_path = PathBuf::from(directory_name);

    // Set the environment variable if not already set
    match env::var("NFAPI_LOG_DIR") {
        Ok(_) => {}, // Use existing value
        Err(_) => {
            fs::create_dir_all(&dir_path).expect("Failed to create directory");
            env::set_var("NFAPI_LOG_DIR", dir_path.to_str().unwrap());
        }
    }

    // Initialize logging
    let log_level = LevelFilter::Info; // Set the desired level, e.g., Info or Debug
    simple_logger::SimpleLogger::new()
        .with_level(log_level)
        .init()
        .unwrap();

    let mut messages: Vec<NFAPI_MESSAGE_PDU_T> = vec![];

    for ue in ue_list.iter() {
        // Simulate radio channel model to get SNR value
        let raw_snr = simulate_radio_channel_model();

        // Filter SNR using external library
        let filtered_snr = signal_processing_lib::filter_snr(raw_snr);

        let message = NFAPI_MESSAGE_PDU_T {
            rx_ue_information_tag: format!("RX_TAG_{}", ue),
            rnti: rand::thread_rng().gen(),  // Simulated RNTI value
            crc_indication_rel8_tag: "CRC_REL8".to_string(),
            snr_indication_rel8_tag: filtered_snr,
        };

        messages.push(message);

        debug!("Processed UE: {}, SNR: {}", ue, message.snr_indication_rel8_tag);
    }

    info!("Initialized {} NFAPI messages", messages.len());

    // Efficiently manage memory and updates
    *ue_list = messages.iter().map(|msg| msg.rx_ue_information_tag.clone()).collect();
}

fn main() {
    let mut ue_list = vec!["UE1".to_string(), "UE2".to_string()];
    initialize_and_log_nfaapi_messages(&mut ue_list, "nfaapi_logs");
}
