import java.util.ArrayList;
import java.util.List;
import java.util.Random;

class NFAPICRCIndicationPDU_T {
    private final int rxUEInformationTag;
    private final int rnti;
    private final int crcIndicationRel8Tag;
    private final boolean crcFlag;

    public NFAPICRCIndicationPDU_T(int rxUEInformationTag, int rnti, int crcIndicationRel8Tag, boolean crcFlag) {
        this.rxUEInformationTag = rxUEInformationTag;
        this.rnti = rnti;
        this.crcIndicationRel8Tag = crcIndicationRel8Tag;
        this.crcFlag = crcFlag;
    }

    @Override
    public String toString() {
        return "NFAPICRCIndicationPDU_T{" +
                "rxUEInformationTag=" + rxUEInformationTag +
                ", rnti=" + rnti +
                ", crcIndicationRel8Tag=" + crcIndicationRel8Tag +
                ", crcFlag=" + crcFlag +
                '}';
    }
}

class NetworkServiceManager {
    private boolean isRunning = false;
    private List<Integer> dataStore = new ArrayList<>();
    private final Random random = new Random();

    public void startService() {
        if (!isRunning) {
            isRunning = true;
            System.out.println("Service started");
            // Simulate fetching and processing data
            fetchData();
        }
    }

    public void stopService() {
        if (isRunning) {
            isRunning = false;
            System.out.println("Service stopped");
            int maxNumber = findMaxInteger(dataStore);
            List<NFAPICRCIndicationPDU_T> pduList = createPDUList(maxNumber);
            pduList.forEach(System.out::println);
        }
    }

    private void fetchData() {
        // Simulate fetching integers from a remote data source
        for (int i = 0; i < 10; i++) {
            int number = random.nextInt(100); // Random integer between 0 and 99
            System.out.println("Fetched: " + number);
            synchronized (dataStore) {
                dataStore.add(number);
            }
        }
    }

    private int findMaxInteger(List<Integer> integers) {
        synchronized (integers) {
            return integers.stream().max(Integer::compare).orElse(0);
        }
    }

    private List<NFAPICRCIndicationPDU_T> createPDUList(int maxNumber) {
        List<NFAPICRCIndicationPDU_T> pduList = new ArrayList<>();
        for (int i = 0; i < 5; i++) { // Create 5 PDUs as an example
            int rxUEInformationTag = random.nextInt(1000);
            int rnti = random.nextInt(65536); // Random RNTI
            int crcIndicationRel8Tag = maxNumber + random.nextInt(10); // Example CRC tag logic
            boolean crcFlag = random.nextBoolean(); // Random CRC flag

            pduList.add(new NFAPICRCIndicationPDU_T(rxUEInformationTag, rnti, crcIndicationRel8Tag, crcFlag));
        }
        return pduList;
    }

    public static void main(String[] args) {
        NetworkServiceManager manager = new NetworkServiceManager();

        // Simulate random intervals for start/stop
        manager.startService();

        try {
            Thread.sleep(2000); // Simulating processing time
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        manager.stopService();
    }
}
```

