// Define the structure as per NFAPI_CRC_INDICATION_PDU_T specification.
typedef struct {
    // Add appropriate fields here.
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    atomic_size_t count;
    pthread_mutex_t lock;
} NFAPIDynamicList;

// Function declarations
NFAPIDynamicList* create_list();
void destroy_list(NFAPIDynamicList *list);
int add_element(NFAPIDynamicList *list, NFAPI_CRC_INDICATION_PDU_T element);
NFAPI_CRC_INDICATION_PDU_T get_element(NFAPIDynamicList *list, size_t index);
void async_processing(NFAPIDynamicList *list);

// Function definitions
NFAPIDynamicList* create_list() {
    NFAPIDynamicList *list = (NFAPIDynamicList*)malloc(sizeof(NFAPIDynamicList));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    atomic_store(&list->count, 0);
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(NFAPIDynamicList *list) {
    if (list) {
        free(list->elements);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_element(NFAPIDynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    size_t index = atomic_fetch_add(&list->count, 1);

    if (index >= MAX_ELEMENTS) return -1; // Buffer overflow

    pthread_mutex_lock(&list->lock);
    list->elements[index] = element;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_element(NFAPIDynamicList *list, size_t index) {
    if (index >= MAX_ELEMENTS) {
        // Handle out-of-bounds access
        NFAPI_CRC_INDICATION_PDU_T empty = {0};
        return empty;
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T element = list->elements[index];
    pthread_mutex_unlock(&list->lock);

    return element;
}

void* async_task(void *arg) {
    NFAPIDynamicList *list = (NFAPIDynamicList*)arg;

    while (1) { // Replace with a proper termination condition
        size_t current_count = atomic_load(&list->count);

        for (size_t i = 0; i < current_count; ++i) {
            NFAPI_CRC_INDICATION_PDU_T element = get_element(list, i);
            // Process the element here asynchronously.
        }
    }

    return NULL;
}

void async_processing(NFAPIDynamicList *list) {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, async_task, list) != 0) {
        fprintf(stderr, "Error creating async processing thread.\n");
        exit(1);
    }

    // Detach the thread to allow it to run independently.
    pthread_detach(thread_id);
}

int main() {
    NFAPIDynamicList *list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return 1;
    }

    async_processing(list);

    // Add elements and process them as needed...

    destroy_list(list);

    return 0;
}
