import stdlib.h
#include <stdint.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

#define HASH_TABLE_SIZE 1000003

typedef struct HashTableEntry {
    long offset;
    struct HashTableEntry *next;
} HashTableEntry;

HashTableEntry *hash_table[HASH_TABLE_SIZE];

// Simple hash function for 'long' values
unsigned long hash(long x) {
    return (x * 2654435761u) % HASH_TABLE_SIZE;
}

// Initialize the hash table
void init_hash_table() {
    for(int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

// Insert into hash table and check uniqueness
int insert_into_hash(long offset) {
    unsigned long index = hash(offset);
    HashTableEntry *entry = hash_table[index];

    while (entry != NULL) {
        if (entry->offset == offset) return 0; // Not unique
        entry = entry->next;
    }

    HashTableEntry *new_entry = malloc(sizeof(HashTableEntry));
    if (!new_entry) return 0;

    new_entry->offset = offset;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
    return 1; // Unique
}

// Free the hash table
void free_hash_table() {
    for(int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = hash_table[i];
        while (entry != NULL) {
            HashTableEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
}

// Pool allocator implementation
typedef struct PoolAllocator {
    size_t unit_size;
    size_t count;
    void* pool;
} PoolAllocator;

void init_pool_allocator(PoolAllocator *pool, size_t unit_size, size_t count) {
    pool->unit_size = unit_size;
    pool->count = count;
    pool->pool = malloc(unit_size * count);
}

void free_pool_allocator(PoolAllocator *pool) {
    if (pool->pool) {
        free(pool->pool);
        pool->pool = NULL;
    }
}

// Function to dynamically allocate and initialize arrays
int* allocate_arrays(long num_records, long double_range_min, long double_range_max, record **records_out, PoolAllocator *allocator) {
    // Allocate memory using the pool allocator for records
    if (!allocator || !allocator->pool) return NULL;

    init_hash_table();
    *records_out = malloc(sizeof(record) * num_records);
    if (*records_out == NULL) goto error;

    long* offsets = (long*)allocator->pool; // Reuse pool memory for offsets
    int* keys = (int*)((char*)allocator->pool + allocator->unit_size * allocator->count); // Use remaining space for keys

    srand(time(NULL));  // Seed random number generator

    for(long i = 0; i < num_records; ++i) {
        long offset;
        do {
            offset = rand() % (long double_range_max - double_range_min + 1) + double_range_min;
        } while(offset <= 0 || !insert_into_hash(offset));

        (*records_out)[i].offset = offset;
        keys[i] = i; // Assign key
        (*records_out)[i].value = ((double)rand() / RAND_MAX) * (double_range_max - double_range_min + 1) + double_range_min;
    }

    free_hash_table();
    return keys;

error:
    if(*records_out) {
        free(*records_out);
        *records_out = NULL;
    }
    return NULL;
}

