#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define CACHE_SIZE 100 // Adjust cache size as needed

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} RecordArray;

// Cache structure
typedef struct {
    Record *cache[CACHE_SIZE];
    int available[CACHE_SIZE]; // 0 for free, 1 for occupied
    pthread_mutex_t cache_lock;
} RecordCache;

// Function prototypes
RecordArray* initialize_records(size_t num_records);
void update_value(RecordArray *record_array, long offset, double new_value);
void cleanup(RecordArray *record_array, RecordCache *cache);
int is_offset_unique(RecordArray *record_array, long offset);
void load_to_cache(RecordCache *cache, RecordArray *record_array);
Record* get_from_cache(RecordCache *cache, long offset);

// Initialize the array of records
RecordArray* initialize_records(size_t num_records) {
    if (num_records == 0) return NULL;

    RecordArray *record_array = malloc(sizeof(RecordArray));
    if (!record_array) {
        perror("Failed to allocate memory for RecordArray");
        exit(EXIT_FAILURE);
    }

    record_array->records = malloc(num_records * sizeof(Record));
    if (!record_array->records) {
        free(record_array);
        perror("Failed to allocate memory for records array");
        exit(EXIT_FAILURE);
    }

    record_array->capacity = num_records;
    pthread_mutex_init(&record_array->lock, NULL);

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records;) {
        long new_offset = rand() % (LONG_MAX / 2) + 1; // Ensure positive offset
        if (!is_offset_unique(record_array, new_offset)) continue;

        Record *record = &record_array->records[i++];
        record->offset = new_offset;
        record->key = rand(); // Random key for demonstration
        record->value = (double)rand() / RAND_MAX; // Random double between 0 and 1
    }

    return record_array;
}

// Check if offset is unique in the array
int is_offset_unique(RecordArray *record_array, long offset) {
    for (size_t i = 0; i < record_array->capacity; ++i) {
        if (record_array->records[i].offset == offset)
            return 0;
    }
    return 1;
}

// Update the value of a specific record by its unique offset
void update_value(RecordArray *record_array, long offset, double new_value) {
    pthread_mutex_lock(&record_array->lock);
    for (size_t i = 0; i < record_array->capacity; ++i) {
        if (record_array->records[i].offset == offset) {
            record_array->records[i].value = new_value;
            break;
        }
    }
    pthread_mutex_unlock(&record_array->lock);
}

// Clean up allocated resources
void cleanup(RecordArray *record_array, RecordCache *cache) {
    free(record_array->records);
    pthread_mutex_destroy(&record_array->lock);
    free(record_array);

    for (int i = 0; i < CACHE_SIZE; ++i)
        if (cache->available[i])
            free(cache->cache[i]);

    pthread_mutex_destroy(&cache->cache_lock);
    free(cache);
}

// Load a subset of records to the cache
void load_to_cache(RecordCache *cache, RecordArray *record_array) {
    pthread_mutex_lock(&cache->cache_lock);

    for (int i = 0; i < CACHE_SIZE && i < record_array->capacity; ++i) {
        int j;
        for (j = 0; j < CACHE_SIZE; ++j)
            if (!cache->available[j]) break;

        cache->cache[j] = malloc(sizeof(Record));
        if (!cache->cache[j]) {
            perror("Failed to allocate memory for cache entry");
            exit(EXIT_FAILURE);
        }

        *cache->cache[j] = record_array->records[i];
        cache->available[j] = 1;
    }

    pthread_mutex_unlock(&cache->cache_lock);
}

// Get a record from the cache by its offset
Record* get_from_cache(RecordCache *cache, long offset) {
    pthread_mutex_lock(&cache->cache_lock);

    for (int i = 0; i < CACHE_SIZE; ++i)
        if (cache->available[i] && cache->cache[i]->offset == offset) {
            pthread_mutex_unlock(&cache->cache_lock);
            return cache->cache[i];
        }

    pthread_mutex_unlock(&cache->cache_lock);
    return NULL;
}

int main() {
    size_t num_records = 1000; // Example number of records
    RecordArray *record_array = initialize_records(num_records);

    RecordCache cache = { .available = {0}, };
    pthread_mutex_init(&cache.cache_lock, NULL);

    load_to_cache(&cache, record_array); // Preload some records to the cache

    long test_offset = 12345; // Example offset
    double new_value = 3.14159;

    update_value(record_array, test_offset, new_value);

    Record *cached_record = get_from_cache(&cache, test_offset);
    if (cached_record)
        printf("Cached Value: %.5f\n", cached_record->value);

    cleanup(record_array, &cache);

    return 0;
}
```

This code initializes a dynamic array of records with unique long offsets and random values. It includes basic memory management strategies such as using mutex locks for thread safety. A simple cache mechanism is implemented to enhance access performance by storing frequently accessed records. The implementation ensures that updates maintain the uniqueness constraint and gracefully handles potential errors, providing feedback when issues arise.']

