#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char* str;
} DataEntry;

#define INITIAL_SIZE 10
#define BUFFER_POOL_SIZE 5

typedef struct {
    size_t count;
    size_t capacity;
    DataEntry** entries;
    size_t* indices;
    size_t index_count;
    size_t index_capacity;
    char* buffer_pool[BUFFER_POOL_SIZE];
    size_t buffer_sizes[BUFFER_POOL_SIZE];
} DataEntryManager;

void init_buffer_pool(DataEntryManager* manager) {
    for (size_t i = 0; i < BUFFER_POOL_SIZE; ++i) {
        manager->buffer_pool[i] = malloc(256); // Example fixed size
        manager->buffer_sizes[i] = 256;
    }
}

char* allocate_string_from_pool(DataEntryManager* manager, const char* str) {
    for (size_t i = 0; i < BUFFER_POOL_SIZE; ++i) {
        if (strlen(str) + 1 <= manager->buffer_sizes[i]) {
            strcpy(manager->buffer_pool[i], str);
            return manager->buffer_pool[i];
        }
    }
    // If no buffer available, allocate a new one
    char* new_str = malloc(strlen(str) + 1);
    strcpy(new_str, str);
    return new_str;
}

void resize_data_entry_array(DataEntryManager* manager, size_t new_capacity) {
    manager->entries = realloc(manager->entries, new_capacity * sizeof(DataEntry*));
    if (manager->entries == NULL) {
        perror("Failed to resize DataEntry array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = manager->count; i < new_capacity; ++i) {
        manager->entries[i] = malloc(sizeof(DataEntry));
    }
    manager->capacity = new_capacity;
}

void resize_index_array(DataEntryManager* manager, size_t new_capacity) {
    manager->indices = realloc(manager->indices, new_capacity * sizeof(size_t));
    if (manager->indices == NULL) {
        perror("Failed to resize index array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = manager->index_count; i < new_capacity; ++i) {
        manager->indices[i] = 0;
    }
    manager->index_capacity = new_capacity;
}

DataEntryManager* create_data_entry_manager() {
    DataEntryManager* manager = malloc(sizeof(DataEntryManager));
    manager->count = 0;
    manager->capacity = INITIAL_SIZE;
    manager->entries = calloc(INITIAL_SIZE, sizeof(DataEntry*));
    if (manager->entries == NULL) {
        perror("Failed to allocate DataEntry array");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < INITIAL_SIZE; ++i) {
        manager->entries[i] = malloc(sizeof(DataEntry));
    }

    manager->index_count = 0;
    manager->index_capacity = INITIAL_SIZE;
    manager->indices = calloc(INITIAL_SIZE, sizeof(size_t));

    init_buffer_pool(manager);

    return manager;
}

void add_data_entry(DataEntryManager* manager, double value, const char* str) {
    if (manager->count >= manager->capacity) {
        resize_data_entry_array(manager, manager->capacity * 2);
    }
    DataEntry* entry = manager->entries[manager->count++];
    entry->value = value;
    entry->str = allocate_string_from_pool(manager, str);
}

void add_index(DataEntryManager* manager, size_t index) {
    if (index >= manager->count) return; // Ignore invalid indices
    if (manager->index_count >= manager->index_capacity) {
        resize_index_array(manager, manager->index_capacity * 2);
    }
    manager->indices[manager->index_count++] = index;
}

DataEntry* get_data_entry(DataEntryManager* manager, size_t index) {
    if (index < manager->count) {
        return manager->entries[index];
    }
    return NULL;
}

void free_data_entry_manager(DataEntryManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->str);
        free(manager->entries[i]);
    }
    free(manager->entries);

    for (size_t i = 0; i < BUFFER_POOL_SIZE; ++i) {
        free(manager->buffer_pool[i]);
    }

    free(manager->indices);
    free(manager);
}

// Example usage
int main() {
    DataEntryManager* manager = create_data_entry_manager();
    add_data_entry(manager, 3.14, "Hello");
    add_data_entry(manager, 2.71, "World");

    add_index(manager, 0);
    add_index(manager, 1);

    DataEntry* entry = get_data_entry(manager, 0);
    if (entry) {
        printf("Value: %f, String: %s\n", entry->value, entry->str);
    }

    free_data_entry_manager(manager);
    return 0;
}
```

### Key Features:
- **Dynamic Allocation**: The `DataEntryManager` handles dynamic resizing of both the data entries and indices.
- **Buffer Pool Optimization**: A pool of pre-allocated buffers is used to minimize frequent memory allocations for strings.
- **Memory Management**: Proper allocation and deallocation ensure no memory leaks.
- **Scalability**: Arrays are resized as needed, supporting growth in dataset size.
- **Usability**: Functions allow adding entries, indices, and querying specific entries efficiently.']

