    VALID_TYPE_2,
    VALID_TYPE_3,
    VALID_TYPE_4,
    INVALID_TYPE
} EVENT_TYPE;

typedef struct {
    time_t timestamp;
    EVENT_TYPE event_type;
} CELLULAR_EVENT_REL8_TAG;

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
    CELLULAR_EVENT_REL8_TAG cell_event_tag;
} NFAPI_CELLULAR_EVENT_PDU_T;

typedef struct Node {
    NFAPI_CELLULAR_EVENT_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} EventList;

EventList* create_list() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_valid_event_type(EVENT_TYPE event_type) {
    switch (event_type) {
        case VALID_TYPE_1:
        case VALID_TYPE_2:
        case VALID_TYPE_3:
        case VALID_TYPE_4:
            return 1;
        default:
            return 0;
    }
}

void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int add_event(EventList* list, NFAPI_CELLULAR_EVENT_PDU_T event) {
    pthread_mutex_lock(&list->lock);

    if (!is_valid_event_type(event.cell_event_tag.event_type)) {
        log_message("Invalid event type encountered.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for new node.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = event;
    new_node->next = list->head;
    list->head = new_node;

    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "Added event: RX_UE_TAG=%d, RNTI=%d, Timestamp=%ld, Event_Type=%d",
             event.valid_RX_UE_INFORMATION_TAG, event.RNTI, event.cell_event_tag.timestamp, event.cell_event_tag.event_type);
    log_message(log_buffer);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(EventList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

EventList* manage_dynamic_list(int M) {
    EventList* list = create_list();
    if (!list) return NULL;

    for (int i = 0; i < M; ++i) {
        NFAPI_CELLULAR_EVENT_PDU_T event;
        event.valid_RX_UE_INFORMATION_TAG = rand() % 1000; // Example data
        event.RNTI = rand() % 1000;
        event.cell_event_tag.timestamp = time(NULL);
        event.cell_event_tag.event_type = rand() % (MAX_EVENT_TYPES + 1); // Random event type

        add_event(list, event);
    }

    return list;
}

int main() {
    int M = 10; // Example number of structures
    EventList* event_list = manage_dynamic_list(M);

    if (event_list) {
        free_list(event_list);
    }

    return 0;
}
```

### Key Points:

- **Thread Safety**: The list uses a mutex (`pthread_mutex_t`) to ensure thread-safe operations during node additions.
- **Validation**: Event types are validated before being added to the list, with logging for invalid events.
- **Logging**: Detailed logs are generated for each operation, including errors and successful event additions.
- **Memory Management**: Dynamic memory allocation is used for nodes, with cleanup functions provided.
- **Scalability**: The design allows for easy expansion by adding more structures or integrating additional data sources.']

