typedef struct {
    int *parent;
    size_t count;
} UnionFind;

UnionFind* create_union_find(size_t n) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->count = n;
    uf->parent = calloc(n, sizeof(int));
    for (size_t i = 0; i < n; ++i) {
        uf->parent[i] = -1;
    }
    return uf;
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] < 0)
        return x;
    else
        return uf->parent[x] = find(uf, uf->parent[x]);
}

void union_sets(UnionFind *uf, int x, int y) {
    x = find(uf, x);
    y = find(uf, y);

    if (x != y) {
        if (uf->parent[y] < uf->parent[x]) {
            int temp = x;
            x = y;
            y = temp;
        }
        uf->parent[x] += uf->parent[y];
        uf->parent[y] = x;
    }
}

