#define MAX_CIPHER_CONTEXTS 10

typedef struct {
    int valid;
    unsigned int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    EVP_CIPHER_CTX *contexts[MAX_CIPHER_CONTEXTS];
    int active_count;
} CipherManager;

CipherManager cipher_manager = {.active_count = 0};

void load_yaml_config(const char* file_path);
int init_cipher_context(EVP_CIPHER_CTX **ctx, const unsigned char *key, const unsigned char *iv);
void destroy_cipher_context(EVP_CIPHER_CTX **ctx);

NFAPI_CRC_INDICATION_PDU_T* manage_nfa_list(int size);
void update_aes_key(EVP_CIPHER_CTX *ctx, const unsigned char *new_key, int key_len);

int main() {
    load_yaml_config("config.yaml");

    NFAPI_CRC_INDICATION_PDU_T* nfa_list = manage_nfa_list(10);
    // Further operations...

    return 0;
}

void load_yaml_config(const char* file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open config file: %s\n", file_path);
        exit(EXIT_FAILURE);
    }

    yaml_document_t doc;
    yaml_parser_t parser;

    yaml_parser_initialize(&parser);
    yaml_parser_set_input_file(&parser, file);

    while (yaml_parser_parse(&parser, &doc) == 1) {
        // Parse and handle config settings
    }

    yaml_document_delete(&doc);
    yaml_parser_delete(&parser);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* manage_nfa_list(int size) {
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        nfa_list[i].valid = 1;
        nfa_list[i].RNTI = rand() % 10000;
        snprintf(nfa_list[i].CRC_INDICATION_REL8_TAG, sizeof(nfa_list[i].CRC_INDICATION_REL8_TAG), "Tag_%d", i);
    }

    return nfa_list;
}

int init_cipher_context(EVP_CIPHER_CTX **ctx, const unsigned char *key, const unsigned char *iv) {
    pthread_mutex_lock(&cipher_manager.lock);

    if (cipher_manager.active_count >= MAX_CIPHER_CONTEXTS) {
        fprintf(stderr, "Maximum cipher contexts reached\n");
        pthread_mutex_unlock(&cipher_manager.lock);
        return -1;
    }

    *ctx = EVP_CIPHER_CTX_new();
    if (!*ctx || EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Cipher context initialization failed\n");
        pthread_mutex_unlock(&cipher_manager.lock);
        return -1;
    }

    cipher_manager.contexts[cipher_manager.active_count++] = *ctx;
    pthread_mutex_unlock(&cipher_manager.lock);

    return 0;
}

void destroy_cipher_context(EVP_CIPHER_CTX **ctx) {
    if (*ctx) {
        EVP_CIPHER_CTX_free(*ctx);
        *ctx = NULL;

        pthread_mutex_lock(&cipher_manager.lock);
        for (int i = 0; i < cipher_manager.active_count; ++i) {
            if (cipher_manager.contexts[i] == *ctx) {
                for (int j = i; j < cipher_manager.active_count - 1; ++j) {
                    cipher_manager.contexts[j] = cipher_manager.contexts[j + 1];
                }
                cipher_manager.contexts[--cipher_manager.active_count] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&cipher_manager.lock);
    }
}

void update_aes_key(EVP_CIPHER_CTX *ctx, const unsigned char *new_key, int key_len) {
    EVP_CIPHER_CTX_rekey(ctx, new_key, key_len);
}

// Further functions for PNG parsing and caching
