#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_GROUP_ID 1000

typedef struct {
    int payloadType;
    time_t timestamp;
    char *content;
    size_t contentSize;
} Message;

typedef struct Node {
    int messageId;
    Message message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int capacity;
    unsigned int size;
} DynamicArray;

DynamicArray* createDynamicArray(unsigned int initialCapacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = initialCapacity;
    array->size = 0;
    return array;
}

void destroyMessage(Message* message) {
    free(message->content);
    free(message);
}

void deleteDynamicArray(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        destroyMessage(&current->message);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int addMessage(DynamicArray* array, int messageId, int payloadType, const char* content) {
    pthread_mutex_lock(&array->lock);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    newNode->message.payloadType = payloadType;
    newNode->message.timestamp = time(NULL);
    newNode->message.contentSize = strlen(content) + 1;
    newNode->message.content = malloc(newNode->message.contentSize);

    if (!newNode->message.content) {
        free(newNode);
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    strcpy(newNode->message.content, content);
    newNode->messageId = messageId;

    // Insert at head for simplicity
    newNode->next = array->head;
    array->head = newNode;
    array->size++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int updateMessage(DynamicArray* array, int messageId, const char* newContent) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        if (current->messageId == messageId) {
            free(current->message.content);
            current->message.contentSize = strlen(newContent) + 1;
            current->message.content = malloc(current->message.contentSize);
            if (!current->message.content) {
                pthread_mutex_unlock(&array->lock);
                return -1;
            }
            strcpy(current->message.content, newContent);
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Message not found
}

void retrieveMessages(DynamicArray* array, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&array->lock);

    Node* current = array->head;
    while (current != NULL) {
        if (current->message.timestamp >= startTime && current->message.timestamp <= endTime) {
            printf("Message ID: %d, Payload Type: %d, Content: %s\n",
                   current->messageId,
                   current->message.payloadType,
                   current->message.content);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void archiveOldMessages(DynamicArray* array) {
    time_t currentTime = time(NULL);
    time_t thresholdTime = currentTime - (30 * 24 * 60 * 60);

    pthread_mutex_lock(&array->lock);

    Node *current = array->head, *prev = NULL;
    while (current != NULL) {
        if (current->message.timestamp < thresholdTime) {
            if (prev == NULL) { // Head node
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            Node* toDelete = current;
            current = current->next;
            destroyMessage(&toDelete->message);
            free(toDelete);
            continue; // Move to next without advancing `current`
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void* messageValidationService(void* args) {
    // Dummy implementation for validation service
    return NULL;
}

int main() {
    DynamicArray* array = createDynamicArray(100);

    addMessage(array, 1, 101, "Hello World");
    updateMessage(array, 1, "Updated Content");

    time_t currentTime = time(NULL);
    retrieveMessages(array, currentTime - (7 * 24 * 60 * 60), currentTime); // Last week

    archiveOldMessages(array);

    deleteDynamicArray(array);
    return 0;
}
```

