    struct TileConfig {
        int key;
        long offset;
        double size;

        TileConfig(int k, long o, double s) : key(k), offset(o), size(s) {}
    };

    std::vector<TileConfig> tiles;
    std::unordered_map<long, bool> offsets; // To ensure uniqueness of offsets
    std::mt19937 rng;
    std::mutex mtx;
