    ~DynamicWorldManager() {
        tiles.clear();
        offsets.clear();
    }

    bool initializeTiles(int numTiles) {
        std::lock_guard<std::mutex> lock(mtx);
        tiles.reserve(numTiles);

        std::uniform_int_distribution<> keyDist(0, 10000);
        std::uniform_real_distribution<> sizeDist(0.1, 10.0);

        for (int i = 0; i < numTiles; ++i) {
            int key = keyDist(rng);
            double size = sizeDist(rng);
            long offset;

            do {
                offset = static_cast<long>(rng()) % 100000000 + 1;
            } while (!offsets.insert({offset, true}).second);

            tiles.emplace_back(key, offset, size);
        }
        return true;
    }

