#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 100
#define INITIAL_CAPACITY 10
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_DEBUG 2

typedef struct {
    int value;
} record;

typedef struct {
    int capacity;
    int count;
    record *records;
    pthread_mutex_t lock;
    long average_latency; // External latency measurement service integration
} session;

typedef struct {
    session sessions[MAX_SESSIONS];
    pthread_mutex_t global_lock;
} session_manager;

void log_message(int level, const char *message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}

session* create_session() {
    session *new_session = malloc(sizeof(session));
    if (!new_session) return NULL;

    new_session->capacity = INITIAL_CAPACITY;
    new_session->count = 0;
    new_session->records = malloc(new_session->capacity * sizeof(record));
    if (!new_session->records) {
        free(new_session);
        log_message(LOG_LEVEL_INFO, "Failed to allocate memory for session records.");
        return NULL;
    }

    pthread_mutex_init(&new_session->lock, NULL);
    new_session->average_latency = 0;

    return new_session;
}

void destroy_session(session *sess) {
    if (sess) {
        free(sess->records);
        pthread_mutex_destroy(&sess->lock);
        free(sess);
    }
}

int add_record(session *sess, int key) {
    pthread_mutex_lock(&sess->lock);

    if (sess->count == sess->capacity) {
        int new_capacity = sess->capacity * 2;
        record *new_records = realloc(sess->records, new_capacity * sizeof(record));
        if (!new_records) {
            log_message(LOG_LEVEL_INFO, "Reallocation failed, continuing with existing capacity.");
            pthread_mutex_unlock(&sess->lock);
            return -1; // Memory allocation failure
        }
        sess->records = new_records;
        sess->capacity = new_capacity;
    }

    record *new_record = &sess->records[sess->count++];
    new_record->value = rand() % 100; // Initialize with random value within range

    pthread_mutex_unlock(&sess->lock);
    return 0;
}

void update_latency(session *sess, long latency) {
    pthread_mutex_lock(&sess->lock);

    sess->average_latency = ((sess->average_latency * (sess->count - 1)) + latency) / sess->count;

    pthread_mutex_unlock(&sess->lock);
}

void session_manager_init(session_manager *manager) {
    pthread_mutex_init(&manager->global_lock, NULL);
}

void session_manager_destroy(session_manager *manager) {
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        destroy_session(&manager->sessions[i]);
    }
    pthread_mutex_destroy(&manager->global_lock);
}

session* get_session(session_manager *manager, int index) {
    if (index < 0 || index >= MAX_SESSIONS) return NULL;

    pthread_mutex_lock(&manager->global_lock);
    session *sess = &manager->sessions[index];
    pthread_mutex_unlock(&manager->global_lock);

    return sess;
}

void log_latency(session_manager *manager, int index, long latency) {
    session *sess = get_session(manager, index);
    if (sess) {
        update_latency(sess, latency);
        char msg[100];
        snprintf(msg, sizeof(msg), "Session %d: Average Latency = %ld", index, sess->average_latency);
        log_message(LOG_LEVEL_INFO, msg);
    }
}
