#include <stdio.h>
#include <stdlib.h>

#define OFFSET_SIZE 10000

typedef struct Record {
    long *offsetPtr;
    int key;
    struct Record *next;
} Record;

long offsets[OFFSET_SIZE] = {0};
unsigned long global_max_key = 0;

// Hash table size
#define TABLE_SIZE 65536

int hash_table[TABLE_SIZE];

void initialize_hash_table() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        hash_table[i] = -1;
    }
}

int is_unique(int key) {
    int index = key % TABLE_SIZE;
    return hash_table[index] == -1;
}

void add_key_to_hash_table(int key) {
    int index = key % TABLE_SIZE;
    hash_table[index] = key;
}

Record *create_record(long *offset, int key) {
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for record\n");
        exit(EXIT_FAILURE);
    }
    new_record->offsetPtr = offset;
    new_record->key = key;
    new_record->next = NULL;
    return new_record;
}

void free_records(Record *head) {
    Record *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void find_max_key(Record *head, unsigned long *max_key) {
    *max_key = 0;
    Record *current = head;
    while (current) {
        if (current->key > *max_key) {
            *max_key = current->key;
        }
        current = current->next;
    }
}

void manage_memory(int num_keys, long *input_data) {
    initialize_hash_table();

    Record *head = NULL, *tail = NULL;

    for (int i = 0; i < num_keys; ++i) {
        int key;
        if (scanf("%d", &key) != 1 || key < 0) break;

        // Check if key is within range and unique
        if (key < 0 || key > 65535 || !is_unique(key)) {
            printf("Invalid or duplicate key: %d\n", key);
            continue;
        }

        add_key_to_hash_table(key);

        long *offset = &offsets[i];
        Record *new_record = create_record(offset, key);

        if (!head) {
            head = new_record;
            tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }
    }

    find_max_key(head, &global_max_key);

    // Validate input size
    int count = 0;
    Record *current = head;
    while (current) {
        current = current->next;
        ++count;
    }

    if (count != num_keys) {
        printf("Error: Number of inputs does not match number of records\n");
    }

    // Free all allocated memory
    free_records(head);
}

int main() {
    int num_keys;
    while (1) {
        if (scanf("%d", &num_keys) != 1 || num_keys <= 0) break;

        long input_data[num_keys];

        for (int i = 0; i < num_keys; ++i) {
            scanf("%ld", &input_data[i]);
        }

        manage_memory(num_keys, input_data);
    }

    return 0;
}
```

This code provides a memory management solution for interconnected data structures under constrained resources. It initializes an array of offsets, uses a hash table to ensure unique keys, manages records in a linked list, and handles edge cases such as invalid inputs or memory allocation failures. The program also includes functions to find the maximum key value and free all allocated memory after processing.']

