#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define the structure for CRC indication.
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Log entry structure
typedef struct {
    time_t timestamp;
    const char* message;
} OperationLogEntry;

#define MAX_CONNECTIONS 10000

static pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

static NFAPI_CRC_INDICATION_PDU_T *crc_array = NULL;
static size_t current_size = 0, max_size = 0;

static OperationLogEntry *log_array = NULL;
static size_t log_count = 0, log_capacity = 100; // Initial capacity for logs

void log_operation(const char* message) {
    pthread_mutex_lock(&log_lock);
    if (log_count >= log_capacity) {
        log_capacity *= 2;
        OperationLogEntry *new_log_array = realloc(log_array, log_capacity * sizeof(OperationLogEntry));
        if (!new_log_array) {
            fprintf(stderr, "Error: Log array reallocation failed\n");
            pthread_mutex_unlock(&log_lock);
            return;
        }
        log_array = new_log_array;
    }

    OperationLogEntry entry = { .timestamp = time(NULL), .message = strdup(message) };
    if (!entry.message) {
        fprintf(stderr, "Error: Failed to duplicate log message\n");
    } else {
        log_array[log_count++] = entry;
    }
    pthread_mutex_unlock(&log_lock);
}

void free_logs() {
    pthread_mutex_lock(&log_lock);
    for (size_t i = 0; i < log_count; ++i) {
        free((char*) log_array[i].message); // Free the duplicated string
    }
    free(log_array);
    pthread_mutex_unlock(&log_lock);
}

void manage_crc_array(NFAPI_CRC_INDICATION_PDU_T new_pdu, size_t index) {
    if (index >= MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return;
    }

    pthread_mutex_lock(&array_lock);

    // Initialize array on first use
    if (!crc_array) {
        max_size = MAX_CONNECTIONS;
        crc_array = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_array) {
            fprintf(stderr, "Error: Initial allocation failed\n");
            pthread_mutex_unlock(&array_lock);
            return;
        }
    }

    // Set new CRC indication
    crc_array[index] = new_pdu;

    // Randomly set CRCFLAG
    crc_array[index].CRC_INDICATION_REL8_TAG ^= (rand() % 256);

    current_size = MAX(current_size, index + 1);

    log_operation("Updated CRC indication at index");

    pthread_mutex_unlock(&array_lock);
}

size_t get_current_size(void) {
    size_t size;
    pthread_mutex_lock(&array_lock);
    size = current_size;
    pthread_mutex_unlock(&array_lock);
    return size;
}

void cleanup_crc_array(void) {
    pthread_mutex_lock(&array_lock);
    if (crc_array) {
        free(crc_array);
        crc_array = NULL;
        current_size = 0;
        max_size = 0;
    }
    pthread_mutex_unlock(&array_lock);

    free_logs();
}

int main() {
    srand(time(NULL)); // Seed random number generator
    NFAPI_CRC_INDICATION_PDU_T pdu_example = { .RX_UE_INFORMATION_TAG = 1234, .RNTI = 5678, .CRC_INDICATION_REL8_TAG = 0 };

    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        manage_crc_array(pdu_example, i);
    }

    printf("Current size: %zu\n", get_current_size());

    cleanup_crc_array();
    return 0;
}
```

This C code manages a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures with thread safety and logging functionalities. It includes error handling for memory allocation failures, uses mutexes to ensure safe concurrent access, and implements a resizing log buffer strategy that balances performance and reliability.']

