typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

typedef struct {
    FILE *file;
    LogLevel level;
    pthread_mutex_t mutex;
} Logger;

Logger logger = { stdout, INFO, PTHREAD_MUTEX_INITIALIZER };

void log_message(LogLevel level, const char* message) {
    if (level < logger.level) return;

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    pthread_mutex_lock(&logger.mutex);
    fprintf(logger.file, "[%s] [%s] %s\n", timestamp,
            (level == DEBUG) ? "DEBUG" :
            (level == INFO) ? "INFO" :
            (level == WARNING) ? "WARNING" : "ERROR",
            message);
    if (logger.file != stdout) fflush(logger.file);
    pthread_mutex_unlock(&logger.mutex);
}

typedef struct {
    NFAPI_MESSAGE_PDU_T *messages;
    size_t count;
    pthread_rwlock_t lock;
} UEArray;

void init_logger(Logger* logger, const char* filename, LogLevel level) {
    logger->level = level;
    if (filename && strcmp(filename, "stdout") != 0) {
        logger->file = fopen(filename, "a");
        if (!logger->file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    } else {
        logger->file = stdout;
    }
}

void free_logger(Logger* logger) {
    if (logger->file != stdout && logger->file) {
        fclose(logger->file);
    }
}

int init_and_populate_ues(UEArray *ue_array, size_t num_ues) {
    pthread_rwlock_init(&ue_array->lock, NULL);

    if (num_ues > MAX_UE_COUNT) {
        log_message(ERROR, "Number of UEs exceeds the maximum limit.");
        return -1;
    }

    ue_array->messages = (NFAPI_MESSAGE_PDU_T *)malloc(num_ues * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!ue_array->messages) {
        log_message(ERROR, "Memory allocation for UEs failed.");
        pthread_rwlock_destroy(&ue_array->lock);
        return -1;
    }

    ue_array->count = num_ues;

    for (size_t i = 0; i < num_ues; ++i) {
        pthread_rwlock_wrlock(&ue_array->lock);

        ue_array->messages[i].rx_ue_info.RNTI = rand() % 10000 + 1;

        // Simulate radio channel model
        double noise_factor = (double)(rand() % 10) / 10.0;
        ue_array->messages[i].snr_indication.SNR_INDICATION_REL8_TAG = (int)((30.0 - noise_factor * 5.0));

        log_message(INFO, "Initialized UE with RNTI and calculated SNR.");

        pthread_rwlock_unlock(&ue_array->lock);
    }

    return 0;
}

void cleanup_ues(UEArray *ue_array) {
    pthread_rwlock_wrlock(&ue_array->lock);

    free(ue_array->messages);
    ue_array->messages = NULL;
    ue_array->count = 0;

    pthread_rwlock_unlock(&ue_array->lock);
    pthread_rwlock_destroy(&ue_array->lock);
}

int main() {
    init_logger(&logger, "log.txt", DEBUG);

    UEArray ue_array = { .messages = NULL, .count = 0 };
    if (init_and_populate_ues(&ue_array, 10) == 0) {
        log_message(INFO, "UEs initialized successfully.");
    } else {
        log_message(ERROR, "Failed to initialize UEs.");
    }

    cleanup_ues(&ue_array);
    free_logger(&logger);

    return 0;
}
