            fprintf(stderr, "Memory allocation failed for record buffer\n");
            return -1;
        }

        // Generate a random string
        int result = RAND_bytes((unsigned char *)records[i].buffer, buffer_size - 1);
        if (result != 1) {
            fprintf(stderr, "Random byte generation failed\n");
            return -1;
        }
        records[i].buffer[string_length] = '\0';
    }

    // Placeholder for processing or returning the data
    printf("Data generated successfully\n");

    for (int i = 0; i < RECORD_COUNT; ++i) {
        free(records[i].buffer);
    }
    free(records);

