}

typedef struct {
    unsigned int seed;
    size_t string_length;
    void (*hash_function)(const record *, const char *);
} task_args;

void *process_task(void *arg) {
    task_args *task = (task_args *)arg;

    if (generate_records_and_strings(task->seed, task->string_length) != 0) {
        fprintf(stderr, "Task failed\n");
