    // Verify data integrity with the provided hash function
    if (task->hash_function) {
        task->hash_function((record *)(void *)arg, "Data verification");
    }

    return NULL;
}

int process_tasks_concurrently(unsigned int seed, size_t string_length, void (*hash_function)(const record *, const char *)) {
    initialize_crypto_primitives();

    pthread_t threads[MAX_THREADS];
    task_args tasks[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        tasks[i].seed = seed + i;
        tasks[i].string_length = string_length;
        tasks[i].hash_function = hash_function;

        int result = pthread_create(&threads[i], NULL, process_task, &tasks[i]);
        if (result != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return -1;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

