['Below is an example C code implementing a thread-safe dynamic in-memory cache with custom memory allocation, ensuring unique values within specified limits:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1024

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} CacheRecord;

typedef struct MemoryPool {
    void *pool;
    size_t pool_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t initial_size, size_t max_size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->pool = malloc(initial_size);
    mp->pool_size = initial_size;
    mp->used_size = 0;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void free_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

int validate_and_allocate(MemoryPool *mp, size_t size, size_t max_size) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used_size + size > mp->pool_size && mp->pool_size + size <= max_size) {
        mp->pool = realloc(mp->pool, mp->pool_size + size);
        mp->pool_size += size;
    } else if (mp->used_size + size > mp->pool_size || mp->pool_size >= max_size) {
        pthread_mutex_unlock(&mp->lock);
        return 0; // Not enough memory
    }

    void *mem = ((char *)mp->pool) + mp->used_size;
    mp->used_size += size;

    pthread_mutex_unlock(&mp->lock);
    return (int)(uintptr_t)mem;
}

typedef struct {
    MemoryPool *memory_pool;
    size_t max_memory_size;
    _Atomic int next_random_value;
    _Atomic int used_keys[10000]; // Assuming keys range within 0-9999
} CacheManager;

CacheManager *create_cache_manager(size_t initial_size, size_t max_memory_size) {
    CacheManager *manager = (CacheManager *)malloc(sizeof(CacheManager));
    manager->memory_pool = create_memory_pool(initial_size, max_memory_size);
    manager->max_memory_size = max_memory_size;
    atomic_store(&manager->next_random_value, 0);

    for (int i = 0; i < 10000; ++i) {
        atomic_store(&manager->used_keys[i], 0);
    }

    return manager;
}

void free_cache_manager(CacheManager *manager) {
    if (manager) {
        free_memory_pool(manager->memory_pool);
        free(manager);
    }
}

int get_unique_random_value(CacheManager *manager, int min_val, int max_val) {
    int unique = atomic_fetch_add(&manager->next_random_value, 1);

    while (unique < min_val || unique > max_val || atomic_load(&manager->used_keys[unique % 10000])) {
        unique = atomic_fetch_add(&manager->next_random_value, 1);
    }

    atomic_store(&manager->used_keys[unique % 10000], 1);
    return unique;
}

CacheRecord *add_record(CacheManager *manager, long offset, int key) {
    size_t record_size = sizeof(CacheRecord);

    if (!validate_and_allocate(manager->memory_pool, record_size, manager->max_memory_size)) {
        return NULL; // Memory limit reached
    }

    CacheRecord *new_record = (CacheRecord *)validate_and_allocate(manager->memory_pool, record_size, manager->max_memory_size);
    new_record->offset = offset;
    new_record->key = key;

    int unique_value = get_unique_random_value(manager, 1, 10000); // Example range
    new_record->record.value = unique_value;

    return new_record;
}

int main() {
    srand(time(NULL));

    CacheManager *manager = create_cache_manager(INITIAL_POOL_SIZE, 10 * 1024 * 1024);

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))add_record, manager);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_cache_manager(manager);

    return 0;
}
```

**Notes:**
- This implementation uses a custom memory pool to manage allocations.
- A mutex lock ensures thread-safe access when modifying the memory pool size and usage.
- An atomic integer tracks unique random values, ensuring no two records have the same value within a specified range.
- Memory pool management is designed for dynamic growth while respecting a maximum limit.
- The example initializes a `CacheManager`, which can manage cache operations across multiple threads.']

