    int status;

    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        exit(EXIT_FAILURE); // If execl fails
    } else if (pid > 0) {
        wait(&status);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }

    return 0; // Fork failed or command execution error
}

