                printf("Duplicate key detected: %d. Please enter a unique key.\n", key);
                --i;
                break;
            }
        }
        keys[i] = key;
    }
    return keys;
}

// Function to insert a record into the linked list
void insert_record(long offset, int key) {
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    if (!new_node) return;

    new_node->data.offset = &resources[offset];
    new_node->data.key = key;
    new_node->next = NULL;

    pthread_mutex_lock(&lock);
    new_node->next = head;
    head = new_node;

    // Update max_key_value
    if (key > max_key_value) {
        max_key_value = key;
    }
    pthread_mutex_unlock(&lock);
}

// Function to free the linked list
void free_list() {
    node_t *current = head;
    while (current != NULL) {
        node_t *next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
}

// Main function
int main() {
    memset(resources, 0, sizeof(resources));

    int num_keys;
    printf("Enter the number of keys: ");
    scanf("%d", &num_keys);

    int *keys = allocate_keys(num_keys);
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return EXIT_FAILURE;
    }

    // Populate linked list with records
    for (int i = 0; i < num_keys; ++i) {
        insert_record(i, keys[i]);
    }

    free(keys);

    // Traverse the list to find max key value
    pthread_mutex_lock(&lock);
    printf("Maximum key value: %d\n", max_key_value);
    pthread_mutex_unlock(&lock);

    // Free allocated resources
    free_list();

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: The code uses a mutex lock to ensure thread-safe operations on shared data.
- **Memory Management**: Dynamic memory allocation is used for keys and linked list nodes, with checks for allocation failures.
- **Error Handling**: Validates key inputs and handles duplicates gracefully.
- **Data Structures**: Uses a singly linked list for efficient insertions and deletions.
- **Resource Management**: Fixed-size array for resource offsets to minimize dynamic allocations.

### Scalability Considerations:
- The design can be extended with distributed computing frameworks like MPI or OpenMP for parallel execution across nodes, ensuring load balancing and fault tolerance.']

