#include <time.h>

typedef struct {
    int value;
    int *key_ref;
    long offset;
} record;

void initialize_records(record **records, long num_records, int key_min, int key_max, int value_min, int value_max) {
    if (num_records <= 0) return;

    // Allocate memory for keys and offsets
    int *keys = malloc(num_records * sizeof(int));
    long *offsets = malloc(num_records * sizeof(long));

    if (!keys || !offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        free(keys);
        free(offsets);
        return;
    }

    // Allocate memory for records
    *records = malloc(num_records * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(keys);
        free(offsets);
        return;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Initialize keys ensuring uniqueness
    for (long i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (key_max - key_min + 1) + key_min;
        } while (contains_key(keys, i, key));
        keys[i] = key;
    }

    // Initialize records with random values and offsets
    for (long i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (value_max - value_min + 1) + value_min;
        (*records)[i].key_ref = &keys[i];
        (*records)[i].offset = offsets[i] = rand(); // Assign a random offset
    }

    // Free the allocated memory for keys and offsets
    free(keys);
    free(offsets);
}

// Helper function to check if a key already exists in the array
int contains_key(int *keys, long size, int key) {
    for (long i = 0; i < size; ++i) {
        if (keys[i] == key) return 1;
    }
    return 0;
}

// Example usage of initialize_records function
int main() {
    record *records;
    long num_records = 1000; // Number of records to be created
    int key_min = 1, key_max = 2000; // Range for keys
    int value_min = -100, value_max = 100; // Range for values

    initialize_records(&records, num_records, key_min, key_max, value_min, value_max);

    // Example: Print the first record's details
    if (records) {
        printf("First Record: Value=%d, Key=%d, Offset=%ld\n",
               records[0].value, *records[0].key_ref, records[0].offset);
    }

    // Free allocated memory for records
    free(records);

    return 0;
}
