int initialize_data_structures(long* offsets, int* keys, record** records, metadata** metas,
                               size_t num_records, size_t max_memory, int max_unique_values) {

    if (num_records == 0 || max_memory < sizeof(long) * num_records + 
        sizeof(int) * num_records + sizeof(record) * num_records +
        sizeof(metadata) * num_records) {
        fprintf(stderr, "Invalid parameters or memory limit too low\n");
        return -1;
    }

    if (max_unique_values > MAX_UNIQUE_VALUES) {
        fprintf(stderr, "Maximum unique values exceeded\n");
        return -1;
    }

    size_t total_memory = sizeof(long) * num_records + 
                          sizeof(int) * num_records + 
                          sizeof(record) * num_records +
                          sizeof(metadata) * num_records;

    if (total_memory > max_memory) {
        fprintf(stderr, "Memory limit exceeded\n");
        return -1;
    }

    offsets = custom_alloc(sizeof(long) * num_records);
    keys = custom_alloc(sizeof(int) * num_records);
    *records = custom_alloc(sizeof(record) * num_records);
    *metas = custom_alloc(sizeof(metadata) * num_records);

    srand(time(NULL));
    int unique_values[MAX_UNIQUE_VALUES] = {0};
    int count_unique = 0;

    for (size_t i = 0; i < num_records; ++i) {
        if (count_unique >= max_unique_values) {
            fprintf(stderr, "Unable to generate unique values\n");
            return -1;
        }

        int value;
        do {
            value = rand() % max_unique_values;
        } while (unique_values[value]);

        unique_values[value] = 1;
        count_unique++;

        offsets[i] = i; // Example offset
        keys[i] = value; 
        (*records)[i].value = value;
        (*records)[i].key_ptr = &keys[i];
        (*records)[i].last_accessed = time(NULL);
        snprintf((*metas)[i].info, sizeof((*metas)[i].info), "Metadata for record %zu", i);
    }

    return 0; // Success
}

void free_data_structures(long* offsets, int* keys, record* records, metadata* metas, size_t num_records) {
    if (offsets) custom_free(offsets);
    if (keys) custom_free(keys);
    if (records) custom_free(records);
    if (metas) custom_free(metas);
}

// Simulate periodic cleanup for infrequently accessed records
void perform_cleanup(record* records, size_t num_records, time_t threshold) {
    time_t now = time(NULL);

    for (size_t i = 0; i < num_records; ++i) {
        if ((now - records[i].last_accessed) > threshold) {
