                                   num_records, max_memory, MAX_UNIQUE_VALUES) == 0) {
        perform_cleanup(records, num_records, 60); // Example threshold in seconds

        free_data_structures(offsets, keys, records, metas, num_records);
    }

    pthread_mutex_destroy(&memory_pool_lock);

    return 0;
}
