#define MAX_OFFSETS 10000
#define MEMORY_LIMIT 1048576 // Example limit in bytes

typedef struct record {
    long *offset_ptr;
    int key;
} record_t;

typedef struct node {
    record_t data;
    struct node *next;
} node_t;

// Global variables for distributed computing simulation
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
node_t *head = NULL;
int global_max_key = INT_MIN;

long offsets[MAX_OFFSETS];
int allocated_values[65536] = {0}; // To track unique values within range

void initialize_offsets() {
    for (int i = 0; i < MAX_OFFSETS; ++i) {
        offsets[i] = i;
    }
}

int allocate_unique_value(int min, int max) {
    int value;
    do {
        value = rand() % (max - min + 1) + min;
    } while (allocated_values[value]);

    allocated_values[value] = 1;
    return value;
}

void *memory_pool = NULL; // Custom memory pool
size_t memory_used = 0;

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&cache_lock);

    if (memory_used + size > MEMORY_LIMIT) {
        pthread_mutex_unlock(&cache_lock);
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    void *ptr = malloc(size);
    if (!ptr) {
        pthread_mutex_unlock(&cache_lock);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    memory_used += size;
    pthread_mutex_unlock(&cache_lock);
    return ptr;
}

void custom_free(void *ptr) {
    pthread_mutex_lock(&cache_lock);

    if (ptr) {
        free(ptr);
        // Note: Not reducing `memory_used` here; real implementation may track individual allocations
    }

    pthread_mutex_unlock(&cache_lock);
}

node_t* insert_record(long offset, int key) {
    pthread_mutex_lock(&cache_lock);

    if (allocated_values[key]) {
        pthread_mutex_unlock(&cache_lock);
        fprintf(stderr, "Duplicate or invalid key\n");
        return NULL;
    }

    node_t *new_node = custom_alloc(sizeof(node_t));
    if (!new_node) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    new_node->data.offset_ptr = &offsets[offset];
    new_node->data.key = allocate_unique_value(1, 100); // Example range

    new_node->next = head;
    head = new_node;

    if (new_node->data.key > global_max_key) {
        global_max_key = new_node->data.key;
    }

    pthread_mutex_unlock(&cache_lock);
    return new_node;
}

void clear_cache() {
    pthread_mutex_lock(&cache_lock);

    node_t *current = head;
    while (current) {
        node_t *temp = current;
        current = current->next;
        custom_free(temp);
    }

    memory_used = 0;
    for (int i = 0; i < 65536; ++i) {
        allocated_values[i] = 0;
    }

    pthread_mutex_unlock(&cache_lock);
}

void simulate_snr() {
    srand(time(NULL));
    float noise_factor = ((float)rand() / RAND_MAX) * 10.0; // Example noise range
    printf("Simulated SNR with noise factor: %.2f\n", noise_factor);
}

int main() {
    initialize_offsets();

    int num_keys;
    printf("Enter number of keys to allocate (max 65536): ");
    scanf("%d", &num_keys);

    if (num_keys > 65536) {
        fprintf(stderr, "Too many keys requested\n");
