#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_CONTENT_SIZE 1024

typedef struct {
    char *metadata;
    size_t metadata_len;
    char *payload;
    size_t payload_len;
} message;

typedef struct {
    pthread_mutex_t lock;
    message **queue;
    int max_size;
    int current_size;
} messaging_context;

messaging_context* init_messaging_context(int max_size) {
    messaging_context *ctx = malloc(sizeof(messaging_context));
    if (!ctx) return NULL;

    pthread_mutex_init(&ctx->lock, NULL);
    ctx->max_size = max_size;
    ctx->current_size = 0;
    ctx->queue = calloc(max_size, sizeof(message*));
    if (!ctx->queue) {
        free(ctx);
        return NULL;
    }
    return ctx;
}

void destroy_messaging_context(messaging_context *ctx) {
    if (!ctx) return;

    pthread_mutex_lock(&ctx->lock);
    for (int i = 0; i < ctx->current_size; ++i) {
        free(ctx->queue[i]->metadata);
        free(ctx->queue[i]->payload);
        free(ctx->queue[i]);
    }
    free(ctx->queue);
    pthread_mutex_unlock(&ctx->lock);

    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}

void add_message_to_queue(messaging_context *ctx, char *payload, int num_messages, int perf_threshold) {
    if (!ctx || !payload) return;

    srand(time(NULL));

    for (int i = 0; i < num_messages; ++i) {
        pthread_mutex_lock(&ctx->lock);

        if (ctx->current_size >= ctx->max_size) {
            printf("Queue is full. Message dropped.\n");
            pthread_mutex_unlock(&ctx->lock);
            continue;
        }

        size_t payload_len = rand() % MAX_CONTENT_SIZE + 1; // Random length between 1 and MAX_CONTENT_SIZE
        if (payload_len > strlen(payload)) {
            payload_len = strlen(payload); // Ensure we don't exceed actual payload length
        }

        message *msg = malloc(sizeof(message));
        if (!msg) {
            pthread_mutex_unlock(&ctx->lock);
            printf("Failed to allocate memory for message.\n");
            continue;
        }

        msg->metadata = malloc(20); // Example fixed size for metadata
        if (!msg->metadata) {
            free(msg);
            pthread_mutex_unlock(&ctx->lock);
            printf("Failed to allocate memory for metadata.\n");
            continue;
        }

        snprintf(msg->metadata, 20, "Msg%d", i);
        msg->metadata_len = strlen(msg->metadata);

        msg->payload = malloc(payload_len);
        if (!msg->payload) {
            free(msg->metadata);
            free(msg);
            pthread_mutex_unlock(&ctx->lock);
            printf("Failed to allocate memory for payload.\n");
            continue;
        }

        strncpy(msg->payload, payload, payload_len);
        msg->payload_len = payload_len;

        ctx->queue[ctx->current_size++] = msg;

        // Check performance threshold
        size_t used_memory = 0;
        for (int j = 0; j < ctx->current_size; ++j) {
            used_memory += sizeof(message) + strlen(ctx->queue[j]->metadata) + 1 + ctx->queue[j]->payload_len;
        }

        if (used_memory > perf_threshold) {
            printf("Performance threshold exceeded. Consider optimizing.\n");
        }

        pthread_mutex_unlock(&ctx->lock);
    }
}

int main() {
    int max_queue_size = 10000; // Example size
    int perf_threshold = 10 * 1024 * 1024; // 10 MB example performance threshold

    messaging_context *ctx = init_messaging_context(max_queue_size);
    if (!ctx) {
        printf("Failed to initialize context.\n");
        return 1;
    }

    char *payloads[] = {"Message 1", "Message 2", "Message 3"};
    int num_payloads = sizeof(payloads) / sizeof(payloads[0]);

    add_message_to_queue(ctx, payloads[0], 10000, perf_threshold); // Example call

    destroy_messaging_context(ctx);
    return 0;
}
