double process_snr(double snr_value, void *context) {
    double factor = *(double *) context;
    return snr_value + (factor * ((rand() / (double) RAND_MAX) - 0.5));
}

void initialize_ue_manager(UE_Manager *ue_mgr, size_t initial_size) {
    ue_mgr->message_array = malloc(initial_size * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!ue_mgr->message_array) {
        log_message("ERROR", "Failed to allocate memory for UE manager.");
        exit(EXIT_FAILURE);
    }
    ue_mgr->count = 0;
    pthread_mutex_init(&ue_mgr->lock, NULL);
}

void add_ue(UE_Manager *ue_mgr) {
    if (ue_mgr->count >= MAX_UE_COUNT) {
        log_message("WARNING", "Max UE count reached. Cannot add more UEs.");
        return;
    }

    pthread_mutex_lock(&ue_mgr->lock);

    NFAPI_MESSAGE_PDU_T new_pdu = {0};

    // Simulating RX_UE_INFORMATION_TAG and RNTI values
    new_pdu.rx_ue_information_tag = rand() % 10000; 
    new_pdu.rnti = rand() % 1000;

    // Calculating SNR with random noise factor.
    double base_snr = rand() % 30;
    double noise_factor = ((rand() / (double) RAND_MAX) * SNR_NOISE_FACTOR) - (SNR_NOISE_FACTOR / 2);
    double processed_snr = process_snr(base_snr + noise_factor, &noise_factor);

    new_pdu.crc_indication_rel8_tag = rand();
    new_pdu.snr_indication_rel8_tag = (uint16_t)processed_snr;

    ue_mgr->message_array[ue_mgr->count++] = new_pdu;

    pthread_mutex_unlock(&ue_mgr->lock);
}

void remove_ue(UE_Manager *ue_mgr, size_t index) {
    if (index >= ue_mgr->count) {
        log_message("WARNING", "Invalid UE index for removal.");
        return;
    }

    pthread_mutex_lock(&ue_mgr->lock);

    // Shift elements to fill the gap
    memmove(&ue_mgr->message_array[index], &ue_mgr->message_array[index + 1],
            (ue_mgr->count - index - 1) * sizeof(NFAPI_MESSAGE_PDU_T));
    ue_mgr->count--;

    pthread_mutex_unlock(&ue_mgr->lock);
}

void shutdown_ue_manager(UE_Manager *ue_mgr) {
    free(ue_mgr->message_array);
    pthread_mutex_destroy(&ue_mgr->lock);
    log_message("INFO", "UE Manager shut down successfully.");
}

int main() {
    UE_Manager ue_mgr;

    initialize_ue_manager(&ue_mgr, 10);

    // Simulate dynamic addition of UEs
    for (size_t i = 0; i < 15; ++i) { 
        add_ue(&ue_mgr);
        time_sleep(1); // Simulating real-time processing delay
    }

    // Dynamic removal of a UE for demonstration purposes.
    remove_ue(&ue_mgr, 5);

    shutdown_ue_manager(&ue_mgr);

    return 0;
}
