// Function to check for duplicate keys
bool has_duplicate(int* array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            if (array[i] == array[j]) return true;
        }
    }
    return false;
}

// Function to allocate and initialize arrays
record* init_structs(size_t num_offsets, long offsets[], size_t num_keys, int keys[], size_t range_size, int seeds[]) {
    // Check for duplicate keys
    if (has_duplicate(keys, num_keys)) {
        printf("Error: Duplicate key found in the keys array.\n");
        return NULL;
    }

    // Calculate total memory needed
    size_t total_memory = sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(record) * num_keys;

    // Allocate a single block of memory for all three arrays
    void* mem_block = malloc(total_memory);
    if (!mem_block) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Assign pointers to each array within the memory block
    long* allocated_offsets = (long*)mem_block;
    int* allocated_keys = (int*)(allocated_offsets + num_offsets);
    record* allocated_data = (record*)(allocated_keys + num_keys);

    // Initialize offsets and keys arrays
