    const std::string& targetStr, 
    const std::string& insertStr,
    int maxInsertions) {

    if (maxInsertions <= 0) {
        return {};
    }

    int allowedInsertions = getMaxInsertionsBasedOnLoad(maxInsertions);

    auto it = flist.begin();
    bool found = false;
    for (; it != flist.end(); ++it) {
        if (*it == targetStr) {
            found = true;
            break;
        }
    }

    if (found && allowedInsertions > 0) {
        flist.insert_after(it, insertStr);
        --allowedInsertions;
    } else if (!found && allowedInsertions > 0) {
        flist.push_front(insertStr); // This ensures it's inserted at the end.
        --allowedInsertions;
    }

    return (allowedInsertions <= 0) ? std::forward_list<std::string>() : flist;
}
