#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint64_t rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    time_t timestamp; // Timestamp for when the CRC indication was received
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random CRCFLAG value (0 or 1)
uint32_t random_crcflag() {
    return rand() % 2;
}

// Comparator function for sorting by timestamp
int compare_by_timestamp(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return (int)(pduA->timestamp - pduB->timestamp);
}

// Function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T
int init_and_populate_pdu_array(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t count) {
    if (!pdus) return -1;

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&lock);

        (*pdus)[i].timestamp = time(NULL); // Capture the current timestamp
        (*pdus)[i].ue_info_tag.rnti = rand(); // Simulate an RNTI value
        (*pdus)[i].rnti = (uint16_t)(rand() % 65536);
        (*pdus)[i].crc_rel8_tag.crcflag = random_crcflag();

        pthread_mutex_unlock(&lock);
    }

    // Sort the array by timestamp in ascending order
    qsort(*pdus, count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_by_timestamp);

    pthread_mutex_destroy(&lock);
    return 0;
}

// Function to free allocated memory for pdus array
void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus != NULL) {
        free(pdus);
    }
}
