#define CRCFLAG_MAX_VALUE 1

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool[MAX_POOL_SIZE];
    size_t available_count;
    pthread_mutex_t lock;
    int crc_error_count;
} BufferPool;

BufferPool buffer_pool = {.available_count = MAX_POOL_SIZE, .crc_error_count = 0};

pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
uint16_t allocated_rtnis[MAX_POOL_SIZE] = {0};
int is_allocated[65536] = {0}; // Assuming a max RNTI value of 65535

// Helper function to initialize the buffer pool
void init_buffer_pool() {
    pthread_mutex_init(&buffer_pool.lock, NULL);
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        buffer_pool.pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!buffer_pool.pool[i]) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Helper function to release the buffer pool
void destroy_buffer_pool() {
    pthread_mutex_lock(&buffer_pool.lock);
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        free(buffer_pool.pool[i]);
    }
    pthread_mutex_unlock(&buffer_pool.lock);
    pthread_mutex_destroy(&buffer_pool.lock);
}

// Function to get a unique RNTI
int get_unique_rnti(uint16_t* rnti) {
    pthread_mutex_lock(&rnti_lock);
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        if (!is_allocated[allocated_rtnis[i]]) {
            *rnti = allocated_rtnis[i];
            is_allocated[*rnti] = 1;
            pthread_mutex_unlock(&rnti_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&rnti_lock);
    return 0; // No unique RNTI available
}

// Function to release an allocated RNTI
void release_rnti(uint16_t rnti) {
    pthread_mutex_lock(&rnti_lock);
    is_allocated[rnti] = 0;
    pthread_mutex_unlock(&rnti_lock);
}

// Function to manage CRC indications
int manage_crc_indications(size_t max_structures, int* crc_errors_out) {
    if (max_structures > MAX_POOL_SIZE) max_structures = MAX_POOL_SIZE;

    size_t count = 0;
    while (count < max_structures) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;

        pthread_mutex_lock(&buffer_pool.lock);
        if (buffer_pool.available_count > 0) {
            pdu = buffer_pool.pool[--buffer_pool.available_count];
        }
        pthread_mutex_unlock(&buffer_pool.lock);

        if (!pdu) break; // No more available structures

        uint16_t rnti;
        if (!get_unique_rnti(&rnti)) {
            continue; // Unable to get a unique RNTI
        }

        pdu->RX_UE_INFORMATION_TAG = rand(); // Example initialization
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Example initialization
        pdu->CRCFLAG = rand() % CRCFLAG_MAX_VALUE;

        pthread_mutex_lock(&buffer_pool.lock);
        buffer_pool.crc_error_count += pdu->CRCFLAG;
        pthread_mutex_unlock(&buffer_pool.lock);

        release_rnti(rnti); 
        count++;
    }

    if (crc_errors_out) {
        *crc_errors_out = buffer_pool.crc_error_count;
    }
    return 0;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    init_buffer_pool();

    int crc_errors_detected;
    manage_crc_indications(500, &crc_errors_detected);

    printf("CRC errors detected: %d\n", crc_errors_detected);

    destroy_buffer_pool();
    return 0;
}
```']

