#include <signal.h>

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} ReportEntry;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int signal_received = 0;

void handle_signal(int sig) {
    signal_received = 1;
}

int execute_background_command(const char *command) {
    pid_t pid = fork();
    if (pid == -1) return 0; // Fork failed
    if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }
    execlp("/bin/sh", "sh", "-c", command, NULL);
    return 0; // Exec failed
}

void* generate_reports(void *arg) {
    int num_reports = *(int*)arg;
    ReportEntry *reports = malloc(num_reports * sizeof(ReportEntry));

    if (!reports) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit((void *)0);
    }

    for (int i = 0; i < num_reports && !signal_received; ++i) {
        pthread_mutex_lock(&lock);

        snprintf(reports[i].RX_UE_INFORMATION_TAG, sizeof(reports[i].RX_UE_INFORMATION_TAG), "TAG_%d", i);
        reports[i].RNTI = rand() % 65536;

        int success = execute_background_command("echo 'Dummy command'");

        if (success) {
            reports[i].pdu.crc_tag.CRCFLAG = rand() % 2;
        }

        pthread_mutex_unlock(&lock);
    }

    free(reports);
    return (void *)1;
}

int generateNfaReports(int num_reports, const char *background_command) {
    signal(SIGINT, handle_signal);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, generate_reports, &num_reports)) {
        fprintf(stderr, "Thread creation failed\n");
        return 0;
    }

    int result;
    if (pthread_join(thread_id, (void**)&result)) {
        fprintf(stderr, "Thread join failed\n");
        return 0;
    }

    return signal_received ? 0 : * (int*)result;
}
