#include <stdio.h>
#include <stdlib.h>
import time
import threading

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

#define MAX_ELEMENTS 10000

// Function to initialize memory pool
void init_memory_pool(MemoryPool *mp, size_t initial_capacity) {
    mp->capacity = initial_capacity;
    mp->used = 0;
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&mp->lock, NULL);
}

// Function to allocate an element from the memory pool
int allocate_from_pool(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T **element) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used < mp->capacity) {
        *element = &mp->pool[mp->used++];
        pthread_mutex_unlock(&mp->lock);
        return 1;
    }
    pthread_mutex_unlock(&mp->lock);
    return 0;
}

// Function to deallocate an element from the memory pool (for trimming purposes)
void deallocate_from_pool(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (element != NULL) {
        pthread_mutex_lock(&mp->lock);
        memmove(element, element + 1, (--mp->used) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&mp->lock);
    }
}

// Function to manage dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfa_api_crc_array(MemoryPool *mp, size_t num_elements, unsigned int seed) {
    srand(seed); // Seed the pseudo-random generator for reproducibility
    pthread_mutex_lock(&mp->lock);

    if (num_elements > mp->capacity) {
        // Resize memory pool if necessary
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(mp->pool, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&mp->lock);
            return;
        }
        mp->pool = new_pool;
        mp->capacity = num_elements;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &mp->pool[i];

        pdu->RX_UE_INFORMATION_TAG = rand() % MAX_ELEMENTS;
        pdu->RNTI = rand() % MAX_ELEMENTS;

        // Set CRCFLAG randomly
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    pthread_mutex_unlock(&mp->lock);

    log_allocation(num_elements); // Logging allocation details
}

// Function to trim the dynamic array, removing unused elements
void trim_nfa_api_crc_array(MemoryPool *mp, size_t new_size) {
    if (new_size < mp->used) {
        pthread_mutex_lock(&mp->lock);
        for (size_t i = new_size; i < mp->used; ++i) {
            deallocate_from_pool(mp, &mp->pool[i]);
        }
        log_deallocation(mp->used - new_size); // Logging deallocation details
        pthread_mutex_unlock(&mp->lock);
    }
}

// Function to log allocation details with metadata
void log_allocation(size_t num_elements) {
    printf("Timestamp: %ld, Thread ID: %lu, Allocated Elements: %zu\n",
           time.time(), threading.get_ident(), num_elements);
}

// Function to log deallocation details with metadata
void log_deallocation(size_t num_elements_freed) {
    printf("Timestamp: %ld, Thread ID: %lu, Deallocated Elements: %zu\n",
           time.time(), threading.get_ident(), num_elements_freed);
}
```

### Explanation:
- **Memory Pool Management**: The code uses a memory pool to manage `NFAPI_CRC_INDICATION_PDU_T` structures efficiently. This reduces allocation overhead and improves cache locality.

- **Thread Safety**: Mutex locks (`pthread_mutex_lock`/`unlock`) ensure that concurrent access is handled safely, minimizing the risk of race conditions.

- **Dynamic Resizing**: The function resizes the memory pool if needed, ensuring it can handle up to `MAX_ELEMENTS`.

- **Logging and Monitoring**: Metadata such as timestamps and thread IDs are logged during allocation and deallocation for better monitoring.

- **Performance Optimization**: Lock granularity is kept minimal by locking only necessary sections of code. Memory operations are optimized with functions like `memmove` for trimming.

This approach balances efficiency, scalability, and maintainability while ensuring high performance in a concurrent environment.']

['Below are implementations for the `createNfadWithConstraints` function in C and the `processStringWithConstraints` function in JavaScript:

### C Function: `createNfadWithConstraints`

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Assuming structures are defined as follows:
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* createNfadWithConstraints(size_t maxMemory, size_t structureSize) {
    if (maxMemory == 0 || structureSize == 0) return NULL;

    Node *head = NULL, *tail = NULL;
    size_t totalAllocated = 0;
    srand(time(NULL));

    while ((totalAllocated + structureSize) <= maxMemory) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) break; // Memory allocation failed

        newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000000;
        newNode->data.RNTI = rand() % 1000000;
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 256;
        newNode->data.CRCFLAG = rand() % 2;

        newNode->next = NULL;
        newNode->prev = tail;

        if (tail) {
            tail->next = newNode;
        } else {
            head = newNode;
        }
        tail = newNode;

        totalAllocated += sizeof(Node);
    }

    return head; // Caller is responsible for freeing the list
}

void freeNfadList(Node* head) {
    Node *current = head, *nextNode = NULL;
    while (current != NULL) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }
}
```

