typedef struct {
    NFAPI_RX_FRAME_T *frames[MAX_FRAMES];
    size_t count;
    pthread_mutex_t lock;
} FrameList;

void init_frame_list(FrameList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_frame(FrameList *list, NFAPI_RX_FRAME_T *frame) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_FRAMES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    list->frames[list->count++] = frame;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_frame_list(FrameList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->frames[i]);
    }
    pthread_mutex_destroy(&list->lock);
}

NFAPI_RX_FRAME_T* deserialize_frame(const char *data, size_t len) {
    if (len != sizeof(NFAPI_RX_FRAME_T)) {
        return NULL;
    }

    NFAPI_RX_FRAME_T *frame = malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!frame) {
        return NULL;
    }

    memcpy(frame, data, sizeof(NFAPI_RX_FRAME_T));
    frame->timestamp = time(NULL);

    return frame;
