        size_t len = strlen(data);

        NFAPI_RX_FRAME_T *frame = deserialize_frame(data, len);
        if (frame) {
            add_frame(list, frame);
        } else {
            printf("Failed to deserialize or allocate memory for frame from source %zu\n", i);
        }
    }

    // Log deserialization metrics
    printf("Processed %zu frames\n", list->count);
}

int main() {
