    size_t current_size;
} FSA;

static uint32_t seed = 12345; // Seed for random number generation

// Function to initialize a random number generator
void init_random() {
    srand(seed);
}

// Function to generate a unique random integer within range [min, max)
int generate_unique_int(int min, int max, int *existing, size_t count) {
    int new_val;
    do {
        new_val = rand() % (max - min) + min;
    } while (bsearch(&new_val, existing, count, sizeof(int), (int (*)(const void *, const void *)) strcmp) != NULL);
    return new_val;
}

// Thread-safe function to manage dynamic state list
void manage_state_list(record **states, size_t num_states, FSA *fsa, int last_state,
                       int performance_threshold, int concurrency_level) {
    pthread_mutex_lock(&fsa->lock);

    if (fsa->current_size >= fsa->allocated_size || fsa->state_list == NULL) {
        size_t new_size = fsa->current_size + num_states;
        if ((size_t)new_size > performance_threshold) {
            fprintf(stderr, "Performance threshold exceeded.\n");
            pthread_mutex_unlock(&fsa->lock);
            return;
        }

        record *new_state_list = realloc(fsa->state_list, new_size * sizeof(record));
        if (!new_state_list) {
            // Handle memory allocation failure
            perror("Failed to allocate memory for state list");
            pthread_mutex_unlock(&fsa->lock);
            return;
        }

        fsa->state_list = new_state_list;
        fsa->allocated_size = new_size;
    }

    int existing_states[fsa->current_size];
    memcpy(existing_states, fsa->state_list, fsa->current_size * sizeof(int));

    for (size_t i = 0; i < num_states; ++i) {
        (*states)[i].state = generate_unique_int(1, last_state + 1, existing_states, fsa->current_size);
        fsa->state_list[fsa->current_size++] = (*states)[i];
    }

    pthread_mutex_unlock(&fsa->lock);

    // Simulate integration with external data sources
    if (rand() % 10 == 0) { // Randomly simulate a delay or failure scenario
        fprintf(stderr, "Simulated delay/failure in accessing external source.\n");
    }
}

// Function to initialize FSA and its mutex lock
void init_fsa(FSA *fsa) {
    pthread_mutex_init(&fsa->lock, NULL);
    fsa->state_list = NULL;
    fsa->allocated_size = 0;
    fsa->current_size = 0;
}

// Function to clean up FSA resources
void cleanup_fsa(FSA *fsa) {
    free(fsa->state_list);
    pthread_mutex_destroy(&fsa->lock);
}
