void* allocate_and_initialize(long max_offsets, double scale_factor, const char* filename) {
    // Allocate memory for offsets, keys, and data arrays
    long *offsets = (long *)malloc(max_offsets * sizeof(long));
    int *keys = (int *)malloc(max_offsets * sizeof(int));
    record *data = (record *)malloc(max_offsets * sizeof(record));

    if (!offsets || !keys || !data) {
        // Free allocated memory in case of allocation failure
        free(offsets);
        free(keys);
        free(data);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    FILE *file = fopen(filename, "r");
    if (!file) {
        free(offsets);
        free(keys);
        free(data);
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return NULL;
    }

    long offset;
    int key;

    for (long i = 0; i < max_offsets; ++i) {
        if (fscanf(file, "%ld %d", &offset, &key) != 2) {
            // Handle file format error
            fclose(file);
            free(offsets);
            free(keys);
            free(data);
            fprintf(stderr, "Invalid file format\n");
            return NULL;
        }
        offsets[i] = offset;
        keys[i] = key;
        data[i].value = (offset * scale_factor + key) % 1000; // Apply transformation
    }

    fclose(file);

    // Free the offsets and keys as they are no longer needed
    free(offsets);
    free(keys);

    return (void *)data; // Return pointer to the data array
}

// Example usage
int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <max_offsets> <scale_factor> <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    long max_offsets = atol(argv[1]);
    double scale_factor = atof(argv[2]);
    const char *filename = argv[3];

    record *data = (record *)allocate_and_initialize(max_offsets, scale_factor, filename);

    if (!data) {
        return EXIT_FAILURE;
    }

    // Use data...
    // Remember to free the allocated memory when done
    free(data);

    return EXIT_SUCCESS;
}
