// Record structure to hold individual data records.
struct Record {
    long offset;
    int key;
    double value;

    bool operator==(const Record& other) const {
        return offset == other.offset && key == other.key && value == other.value;
    }

    // Hash function for unordered_map
    struct Hasher {
        std::size_t operator()(const Record& record) const {
            return std::hash<long>()(record.offset) ^ 
                   std::hash<int>()(record.key) ^ 
                   std::hash<double>()(record.value);
        }
    };
};

// Class to manage data records with random generation and distributed updates.
class DataRecordManager {
private:
    std::vector<std::shared_ptr<Record>> records;
    std::unordered_map<long, Record> uniqueOffsets;
    mutable std::mutex mtx; // Mutex for thread-safe operations
    std::mt19937 mtGenerator;

public:
    DataRecordManager() : mtGenerator(std::random_device{}()) {}

    ~DataRecordManager() {
        records.clear();
    }

    void generateRecords(size_t numRecords, double minValue, double maxValue) {
        std::uniform_real_distribution<double> dist(minValue, maxValue);

        for (size_t i = 0; i < numRecords; ++i) {
            long offset;
            do {
                offset = static_cast<long>(mtGenerator() % 1000000); // Ensure unique offsets
            } while(uniqueOffsets.count(offset));

            Record record{offset, mtGenerator() % 1000, dist(mtGenerator)};

            std::lock_guard<std::mutex> lock(mtx);
            uniqueOffsets[offset] = record;
        }

        for (const auto& [_, rec] : uniqueOffsets) {
            records.push_back(std::make_shared<Record>(rec));
        }
    }

    void updateRecords(DataAccessObject& dao) {
        std::lock_guard<std::mutex> lock(mtx);

        for (const auto& recordPtr : records) {
            dao.updateRecord(recordPtr->offset, *recordPtr);
        }
    }

    void batchProcessUpdates(DataAccessObject& dao, size_t batchSize) {
        std::lock_guard<std::mutex> lock(mtx);

        const size_t totalRecords = records.size();
        for (size_t i = 0; i < totalRecords; i += batchSize) {
            size_t endIdx = std::min(i + batchSize, totalRecords);

            for (size_t j = i; j < endIdx; ++j) {
                dao.updateRecord(records[j]->offset, *records[j]);
            }
        }
    }
};

// Usage example
int main() {
    DataRecordManager manager;
    DataAccessObject dao;

    manager.generateRecords(1000, 0.0, 1.0);

    manager.batchProcessUpdates(dao, 100);

    return 0;
}
