// Define the structure for a PUCCH measurement result
typedef struct {
    uint32_t ue_id;
    int transmission_power_level;
    time_t timestamp;
} Measurement;

// Define the list node and list head structure
typedef struct Node {
    Measurement data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_capacity;
    void (*callback)(Measurement);
    FILE* log_file;
} MeasurementList;

// Function prototypes
void initialize_list(MeasurementList* list, size_t max_capacity, void (*callback)(Measurement), const char* log_filename);
int add_measurement(MeasurementList* list, Measurement measurement);
int validate_and_filter_stale_data(MeasurementList* list);
void cleanup_old_measurements(MeasurementList* list);
void process_current_memory_usage(MeasurementList* list);

// Callback function example
void sample_callback(Measurement measurement) {
    printf("Processing UE ID: %u\n", measurement.ue_id);
}

// Initialize the list with a given capacity and optional callback
void initialize_list(MeasurementList* list, size_t max_capacity, void (*callback)(Measurement), const char* log_filename) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->max_capacity = max_capacity;
    list->callback = callback;
    list->log_file = fopen(log_filename, "a");
}

// Add a measurement to the list
int add_measurement(MeasurementList* list, Measurement measurement) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_capacity || validate_and_filter_stale_data(list)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory capacity exceeded or stale data filtering failed
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    new_node->data = measurement;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    if (list->callback) {
        list->callback(measurement);
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Validate and filter out stale data
int validate_and_filter_stale_data(MeasurementList* list) {
    time_t current_time = time(NULL);
    Node** node_ptr = &list->head;

    while (*node_ptr != NULL) {
        if (difftime(current_time, (*node_ptr)->data.timestamp) > 5.0) {
            Node* temp = *node_ptr;
            *node_ptr = (*node_ptr)->next;
            free(temp);
            list->count--;
        } else {
            node_ptr = &(*node_ptr)->next;
        }
    }

    return (list->count >= list->max_capacity);
}

// Cleanup old measurements
void cleanup_old_measurements(MeasurementList* list) {
    pthread_mutex_lock(&list->lock);

    Node** node_ptr = &list->head;
    while (*node_ptr != NULL && list->count > (0.7 * list->max_capacity)) {
        Node* temp = *node_ptr;
        *node_ptr = (*node_ptr)->next;
        free(temp);
        list->count--;
    }

    pthread_mutex_unlock(&list->lock);
}

// Process current memory usage
void process_current_memory_usage(MeasurementList* list) {
    // This is a placeholder for system-specific memory checking code.
    size_t available_ram = 1000000; // Example value in bytes
    if (sizeof(Measurement) * list->count > 0.7 * available_ram) {
        cleanup_old_measurements(list);
    }
}

// Logging function example
void log_message(MeasurementList* list, const char* message) {
    if (list->log_file) {
        fprintf(list->log_file, "%s\n", message);
    }
}

int main() {
    MeasurementList measurement_list;
    initialize_list(&measurement_list, 50000, sample_callback, "measurements.log");

    // Example usage
    srand(42); // Seed for deterministic behavior
    for (int i = 0; i < 100; ++i) {
        Measurement measurement = { .ue_id = rand() % 1000, 
                                    .transmission_power_level = rand() % 30 - 10,
                                    .timestamp = time(NULL) };
        add_measurement(&measurement_list, measurement);
    }

    process_current_memory_usage(&measurement_list);

    // Cleanup
    Node* node;
    while (measurement_list.head != NULL) {
        node = measurement_list.head;
        measurement_list.head = measurement_list.head->next;
        free(node);
    }

    pthread_mutex_destroy(&measurement_list.lock);
    fclose(measurement_list.log_file);

    return 0;
}
