typedef struct {
    long offset;
    int key;
} Record;

void log_error(char *buffer, const char *message) {
    snprintf(buffer, BUFFER_SIZE, "%s", message);
}

Record* manage_memory(void (*data_source)(int*, long*, size_t, size_t)) {
    static char buffer[BUFFER_SIZE] = {0};
    int keys[MAX_KEYS];
    long offsets[MAX_OFFSETS];

    // Determine the number of key-offset pairs provided by the data source
    size_t num_keys = 0;
    size_t num_offsets = 0;

    data_source(keys, offsets, &num_keys, &num_offsets);

    if (num_keys > MAX_KEYS) {
        log_error(buffer, "Number of keys exceeds maximum limit");
        return NULL;
    }
    if (num_offsets > MAX_OFFSETS) {
        log_error(buffer, "Number of offsets exceeds maximum limit");
        return NULL;
    }

    // Initialize arrays with default values
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = (i < num_keys) ? keys[i] : -1; // Default key value
    }
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = (i < num_offsets) ? offsets[i] : -1L; // Default offset value
    }

    size_t num_records = (num_keys < num_offsets) ? num_keys : num_offsets;
    if (num_records > MAX_RECORDS) {
        log_error(buffer, "Number of records exceeds maximum limit");
        return NULL;
    }

    // Allocate memory for the record array
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        log_error(buffer, "Memory allocation for records failed");
        return NULL;
    }

    // Populate the record array
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    return records;
}

