#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <memory>

// Constants
const int MIN_VALUE = 1;
const int MAX_VALUE = 1000;

class Record {
public:
    int value;
    explicit Record(int val) : value(val) {}
};

class Monitor {
public:
    void notify(const std::string& message) {
        // Simulate asynchronous communication to a monitoring system
        std::cout << "Monitor Notification: " << message << std::endl;
    }
};

class Service {
private:
    bool is_running = false;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void start() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            if (is_running) return;
            is_running = true;
        }
        cv.notify_all();
        runServiceLoop();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mtx);
            if (!is_running) return;
            is_running = false;
        }
        cv.notify_all();
    }

private:
    void runServiceLoop() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !is_running; });

            if (!is_running) break;

            // Simulate service work
            simulateWork();

            // Random delay to simulate real-world usage
            int delay = rand() % 5 + 1;
            std::this_thread::sleep_for(std::chrono::seconds(delay));
        }
    }

    void simulateWork() {
        std::cout << "Service is running..." << std::endl;
    }
};

class RecordManager {
private:
    std::vector<std::shared_ptr<Record>> records;
    int capacity;

public:
    explicit RecordManager(int cap) : capacity(cap) {}

    void addRecord(int value) {
        if (records.size() >= capacity) {
            records.erase(records.begin()); // Remove oldest record to maintain capacity
        }
        records.push_back(std::make_shared<Record>(value));
    }

    void logPerformanceMetrics() const {
        std::cout << "Current number of records: " << records.size() << std::endl;
    }
};

int generateRandomValue(int min, int max) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    std::uniform_int_distribution<> distrib(min, max);
    return distrib(gen);
}

int main() {
    srand(static_cast<unsigned>(time(0)));

    RecordManager record_manager(100); // Capacity of 100 records
    Service service;
    Monitor monitor;

    std::thread([&]() {
        for (int i = 0; i < 50; ++i) { // Simulate adding records over time
            int value = generateRandomValue(MIN_VALUE, MAX_VALUE);
            record_manager.addRecord(value);

            // Randomly start/stop service to simulate behavior
            if (rand() % 2 == 0) {
                service.start();
                std::this_thread::sleep_for(std::chrono::milliseconds(500));
                service.stop();
            }

            record_manager.logPerformanceMetrics();

            std::this_thread::sleep_for(std::chrono::milliseconds(200));
        }
    }).join();

    monitor.notify("Service has completed.");

    return 0;
}
```

### Key Points:
- **Record Management**: Uses a `std::vector` with a fixed capacity to manage records, removing the oldest when full.
- **Service Control**: Simulates starting and stopping services at random intervals using threads and condition variables for synchronization.
- **Memory Management**: Utilizes smart pointers (`std::shared_ptr`) to manage dynamic memory automatically, reducing the risk of leaks.
- **Logging & Monitoring**: Logs performance metrics and uses a simple `Monitor` class to simulate asynchronous notifications.

This code provides a basic framework that can be extended with additional record types or service configurations as needed.']

