```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int UTRAN_CELL_ID;
    int TMSI;
    int PREAMBLE_SEQ_NOM;
    int corruption_flag;
} NFAPI_RACH_REQ_PDU_T;

#define SUCCESS 0
#define MEMORY_ALLOCATION_FAILED -1

int initialize_nfaapi_crc_indication_and_rach_requests(
        size_t N, 
        unsigned int seed,
        NFAPI_CRC_INDICATION_PDU_T **crc_array, 
        NFAPI_RACH_REQ_PDU_T **rach_array) {

    // Seed the random number generator
    srand(seed);

    *crc_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_array == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }

    *rach_array = malloc(N * sizeof(NFAPI_RACH_REQ_PDU_T));
    if (*rach_array == NULL) {
        free(*crc_array);
        return MEMORY_ALLOCATION_FAILED;
    }

    for (size_t i = 0; i < N; ++i) {
        (*crc_array)[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        (*crc_array)[i].RNTI = rand() % 1000000;
        (*crc_array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        (*rach_array)[i].UTRAN_CELL_ID = rand() % 1000;
        (*rach_array)[i].TMSI = rand() % 10000;
        (*rach_array)[i].PREAMBLE_SEQ_NOM = rand() % 50;
        (*rach_array)[i].corruption_flag = rand() & 1;
    }

    return SUCCESS;
}
