['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define the structure as per the task description.
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t N, int *error_code) {
    if (N <= 0) {
        *error_code = -1; // Invalid input size
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = -2; // Memory allocation failed
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Example of setting a valid tag
        array[i].RNTI = rand() % 65536; // Example of setting a valid RNTI
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        if (array[i].RX_UE_INFORMATION_TAG == 0 || array[i].RNTI == 0) {
            for (size_t j = 0; j <= i; ++j) {
                free(array[j]);
            }
            free(array);
            *error_code = -3; // Invalid tag detected
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    *error_code = 0; // Success

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
