- **Thread Safety**: A global mutex is used to ensure thread safety during allocation and population.
- **Modularity**: The design allows easy integration with other parts of the system, with clear separation between allocation and cleanup functions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_PACKET_ID 10000

typedef enum {
    VALID,
    EXPIRED,
    INVALID
} PacketStatus;

typedef struct {
    int packet_id;
    time_t timestamp;
    PacketStatus status;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void initialize_array(DynamicArray *array) {
    array->packets = malloc(INITIAL_CAPACITY * sizeof(DataPacket));
    if (!array->packets) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void resize_array_if_needed(DynamicArray *array) {
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        DataPacket *new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
}

int generate_random_packet_id() {
