#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 10000000
#define TIMESTAMP_THRESHOLD 1609459200 // Example threshold (e.g., Jan 1, 2021)
#define STATUS_EXPIRED "EXPIRED"
#define RANDOM_KEY_MAX 1000
#define RANDOM_VALUE_MIN -10.0
#define RANDOM_VALUE_MAX 10.0

typedef struct {
    int packet_id;
    time_t timestamp;
    char status[20];
    unsigned int offset;
    int key;
    double value;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketArray;

void init_random() {
    srand((unsigned)time(NULL));
}

int generate_unique_offset(PacketArray *array, unsigned int *offset) {
    for (size_t i = 0; i < array->capacity; ++i) {
        if (!array->packets[i].offset || array->packets[i].offset == UINT_MAX) {
            *offset = i + 1;
            return 1;
        }
    }
    return 0;
}

void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->count = 0;
    array->packets = malloc(array->capacity * sizeof(DataPacket));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void expand_packet_array(PacketArray *array) {
    size_t new_capacity = array->capacity * 2;
    DataPacket *new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket));
    if (!new_packets) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(array->packets);
        exit(EXIT_FAILURE);
    }
    array->packets = new_packets;
    array->capacity = new_capacity;
}

void add_packet(PacketArray *array) {
    if (array->count == array->capacity) {
        expand_packet_array(array);
    }

    unsigned int offset;
    if (!generate_unique_offset(array, &offset)) {
        fprintf(stderr, "Failed to generate unique offset\n");
        exit(EXIT_FAILURE);
    }

    DataPacket packet;
    packet.packet_id = array->count + 1;
    packet.timestamp = time(NULL);
    strcpy(packet.status, TIMESTAMP_THRESHOLD > packet.timestamp ? "ACTIVE" : STATUS_EXPIRED);
    packet.offset = offset;
    packet.key = rand() % RANDOM_KEY_MAX;
    packet.value = (double)rand() / RAND_MAX * (RANDOM_VALUE_MAX - RANDOM_VALUE_MIN) + RANDOM_VALUE_MIN;

    array->packets[array->count++] = packet;
}

void update_packet(PacketArray *array, int index, time_t new_timestamp) {
    if (index < 0 || index >= array->count) {
        fprintf(stderr, "Invalid packet index\n");
        return;
    }

    DataPacket *packet = &array->packets[index];
    packet->timestamp = new_timestamp;
    strcpy(packet->status, TIMESTAMP_THRESHOLD > new_timestamp ? "ACTIVE" : STATUS_EXPIRED);
}

void free_packet_array(PacketArray *array) {
    free(array->packets);
    array->packets = NULL;
    array->count = 0;
    array->capacity = 0;
}

int main() {
    init_random();

    PacketArray packetArray;
    init_packet_array(&packetArray, 1024);

    for (size_t i = 0; i < 10000; ++i) { // Example usage
        add_packet(&packetArray);
    }

    update_packet(&packetArray, 5, time(NULL) + 3600); // Update example

    free_packet_array(&packetArray);
    return 0;
}
```

