#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import sys/socket
import struct
import time
import random

#define MAX_DNS_RESPONSE_SIZE 512
#define TIMEOUT_MS 2000 // Timeout for DNS query in milliseconds

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char *message) {
    printf("LOG: %s\n", message);
}

int resolve_dns(const char *hostname, u_char *ip_address_array) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(53); // DNS port
    inet_aton("8.8.8.8", &server_addr.sin_addr); // Google's public DNS

    u_char dns_query[MAX_DNS_RESPONSE_SIZE];
    memset(dns_query, 0, sizeof(dns_query));

    struct {
        uint16_t id; /* identification number */
        uint16_t flags; /* RFC 1035 flags */
        uint16_t q_count; /* number of question entries */
        uint16_t ans_count; /* number of answer resource records */
        uint16_t auth_count; /* number of authority resource records */
        uint16_t add_count; /* number of resource records in additional section */
    } dns_header;

    dns_header.id = (random.getrandbits(2) << 14);
    dns_header.flags = 0x0100; // Standard query
    dns_header.q_count = htons(1); // We have one question

    u_char *qname;
    uint8_t label_length = strlen(hostname);

    qname = &dns_query[sizeof(dns_header)];
    *(uint8_t *)qname = (uint8_t)label_length; 
    memcpy(qname + 1, hostname, label_length);
    qname += 1 + label_length;

    struct {
        uint16_t qtype;
        uint16_t qclass;
    } qinfo;

    qinfo.qtype = htons(1); // Type A
    qinfo.qclass = htons(1); // Class IN

    memcpy(qname, &qinfo, sizeof(struct {
        uint16_t qtype;
        uint16_t qclass;
    }));

    struct timeval tv;
    tv.tv_sec = TIMEOUT_MS / 1000; 
    tv.tv_usec = (TIMEOUT_MS % 1000) * 1000;

    if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, (char *)&tv, sizeof(tv)) < 0) {
        perror("setsockopt failed");
        close(sockfd);
        return -1;
    }

    ssize_t n = sendto(sockfd, (const char *)dns_query, qname - dns_query + sizeof(qinfo), 0, 
                       (struct sockaddr*)&server_addr, sizeof(server_addr));

    if (n < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    u_char response[MAX_DNS_RESPONSE_SIZE];
    memset(response, 0, MAX_DNS_RESPONSE_SIZE);

    socklen_t len = sizeof(server_addr);
    n = recvfrom(sockfd, (char *)response, MAX_DNS_RESPONSE_SIZE, 0, 
                 (struct sockaddr*)&server_addr, &len);

    if (n < 0) {
        perror("recvfrom failed");
        close(sockfd);
        return -1;
    }

    if (ntohs(dns_header.ans_count) > 0) {
        u_char *answer = response + sizeof(struct {
            uint16_t id; 
            uint16_t flags; 
            uint16_t q_count; 
            uint16_t ans_count; 
            uint16_t auth_count; 
            uint16_t add_count;
        });

        answer += 4; // Skip the name field
        struct {
            uint32_t ip_address;
            uint8_t type;
            uint8_t _class;
            uint16_t ttl;
            uint16_t data_len;
        } *record = (struct {
            uint32_t ip_address;
            uint8_t type;
            uint8_t _class;
            uint16_t ttl;
            uint16_t data_len;
        } *)answer;

        if (ntohs(record->type) == 1 && ntohs(record->data_len) == 4) {
            struct in_addr *ip = (struct in_addr *)&record->ip_address;
            memcpy(ip_address_array, &ip->s_addr, sizeof(struct in_addr));
            close(sockfd);
            return 0;
        }
    }

    close(sockfd);
    return -1;
}

void initialize_nfaPI_CRC_INDICATION_PDU(int n, NFAPI_CRC_INDICATION_PDU_T *pdu_array) {
    for (int i = 0; i < n; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = (uint8_t)i;
        pdu_array[i].RNTI = htons((uint16_t)(i + 1));
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = random.getrandbits(1);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu_array[10]; // Example size
    initialize_nfaPI_CRC_INDICATION_PDU(10, pdu_array);

    u_char ip_address_array[sizeof(struct in_addr)];
    int result = resolve_dns(argv[1], ip_address_array);

    if (result == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr *)ip_address_array));
    } else {
        fprintf(stderr, "Failed to resolve DNS for hostname: %s\n", argv[1]);
    }

    return result;
}
