    time_t timestamp;
    Status status;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->packets = malloc(initial_capacity * sizeof(DataPacket));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

bool add_packet(DynamicArray *array, time_t timestamp) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        DataPacket *new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return false;
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    int packet_id = rand(); // Simulate random generation
    DataPacket packet = {packet_id, timestamp, ACTIVE};
    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock);
    return true;
}

