    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} FSA;

FSA* initialize_fsa(size_t initial_capacity) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    if (!fsa) return NULL;

    fsa->states = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!fsa->states) {
        free(fsa);
        return NULL;
    }

    fsa->capacity = initial_capacity;
    fsa->count = 0;
    pthread_mutex_init(&fsa->lock, NULL);

    return fsa;
}

void free_fsa(FSA* fsa) {
    if (fsa) {
        pthread_mutex_destroy(&fsa->lock);
        free(fsa->states);
        free(fsa);
    }
}

FSA* manage_state_list(int* states_array, size_t num_states, FSA* existing_fsa, int last_state, double performance_threshold) {
    if (!existing_fsa || !states_array) return NULL;

    pthread_mutex_lock(&existing_fsa->lock);

    // Check memory and capacity constraints
    if (existing_fsa->count >= existing_fsa->capacity) {
        size_t new_capacity = existing_fsa->capacity * 2; // Example strategy for resizing
        NFAPI_CRC_INDICATION_PDU_T* new_states = realloc(existing_fsa->states, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_states || (double)new_capacity / num_states < performance_threshold) {
            pthread_mutex_unlock(&existing_fsa->lock);
            return NULL;
        }

        existing_fsa->states = new_states;
        existing_fsa->capacity = new_capacity;
    }

    // Simulate state transition handling with external data source considerations
    for (size_t i = 0; i < num_states; ++i) {
        if (states_array[i] > last_state) { // Simplified condition to handle transitions
            existing_fsa->states[existing_fsa->count].valid_RX_UE_INFORMATION_TAG = states_array[i];
            existing_fsa->states[existing_fsa->count].RNTI = rand() % 100; // Example assignment
            existing_fsa->states[existing_fsa->count++].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }
    }

    pthread_mutex_unlock(&existing_fsa->lock);

    return existing_fsa;
}

int main() {
    size_t initial_capacity = 10;
    FSA* fsa = initialize_fsa(initial_capacity);
    if (!fsa) {
        fprintf(stderr, "Failed to initialize FSA\n");
        return EXIT_FAILURE;
    }

    int states_array[] = {0, 1, 2, 3, 4, 5};
    size_t num_states = sizeof(states_array) / sizeof(states_array[0]);
    double performance_threshold = 0.5;

    fsa = manage_state_list(states_array, num_states, fsa, 3, performance_threshold);

    if (!fsa) {
        fprintf(stderr, "Failed to manage state list\n");
    } else {
        printf("FSA managed successfully with %zu states.\n", fsa->count);
    }

    free_fsa(fsa);

    return EXIT_SUCCESS;
}
