    int CRCFLAG; // Assume 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for statistics
int successful_allocations = 0;
int allocation_failures = 0;
pthread_mutex_t stats_mutex = PTHREAD_MUTEX_INITIALIZER;

// Predefined algorithm to set CRCFLAG
static int calculate_crcflag(uint32_t crc_value) {
    // Simple example: CRCFLAG is 1 if the number of set bits in crc_value is even, otherwise 0
    return (__builtin_popcount(crc_value) % 2 == 0);
}

// Thread-safe function to initialize and populate NFAPIS
NFAPI_CRC_INDICATION_PDU_T* init_nfa_pi_list(size_t n_count) {
    if (n_count <= 0) {
        allocation_failures++;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        allocation_failures++;
        return NULL;
    }

    pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < n_count; ++i) {
        // Simulated data population
        memset(&list[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list[i].RX_UE_INFORMATION_TAG[0] = rand() % 256;
        list[i].RX_UE_INFORMATION_TAG[1] = rand() % 256;
        list[i].RX_UE_INFORMATION_TAG[2] = rand() % 256;

        // Simulated RNTI
        list[i].RNTI = (rand() % 0xFFFF) + 1; // Ensure non-zero

        // Simulated CRC_INDICATION_REL8_TAG and setting CRCFLAG
        list[i].CRC_INDICATION_REL8_TAG = rand();
        list[i].CRCFLAG = calculate_crcflag(list[i].CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_lock(&stats_mutex);
    successful_allocations += n_count;
    pthread_mutex_unlock(&stats_mutex);

    return list;
}

// Function to validate CRCFLAG consistency
int validate_crcflags(const NFAPI_CRC_INDICATION_PDU_T *list, size_t count) {
    int consistent = 1;

    for (size_t i = 0; i < count && consistent; ++i) {
        if (calculate_crcflag(list[i].CRC_INDICATION_REL8_TAG) != list[i].CRCFLAG) {
            consistent = 0;
            break;
        }
    }

    return consistent;
}

// Function to free allocated memory and print statistics
void cleanup_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t n_count) {
    if (list) {
        free(list);
    }

    pthread_mutex_lock(&stats_mutex);
    printf("Successful allocations: %d\n", successful_allocations);
    printf("Allocation failures: %d\n", allocation_failures);
    pthread_mutex_unlock(&stats_mutex);

    // Destroy mutex
    pthread_mutex_destroy(&stats_mutex);
}

int main() {
    size_t n_count = 1000;
    NFAPI_CRC_INDICATION_PDU_T *nfa_pi_list = init_nfa_pi_list(n_count);

    if (nfa_pi_list) {
        int consistent = validate_crcflags(nfa_pi_list, n_count);
        printf("CRCFLAG consistency: %s\n", consistent ? "Consistent" : "Inconsistent");

        cleanup_nfa_pi_list(nfa_pi_list, n_count);
    } else {
        printf("Failed to allocate memory for NFAPIS.\n");
    }

    return 0;
}
