#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_SIZE 1024 // Example maximum size

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} List;

// Initialize the list
bool init_list(List *list, size_t max_capacity) {
    if (max_capacity == 0 || max_capacity > MAX_SIZE) return false;

    list->data = malloc(max_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) return false;

    list->size = 0;
    list->capacity = max_capacity;
    return true;
}

// Add an element to the list
bool add_pdu(List *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    if (list->size >= list->capacity) return false;

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[list->size++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    srand(time(NULL)); // Seed the random number generator
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)

    return true;
}

// Retrieve an element by index
bool get_pdu(List *list, size_t index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (index >= list->size) return false;
    *pdu = list->data[index];
    return true;
}

// Free the allocated memory for the list
void free_list(List *list) {
    free(list->data);
    list->size = 0;
    list->capacity = 0;
}

// Example usage
int main() {
    List list;
    if (!init_list(&list, MAX_SIZE)) {
        fprintf(stderr, "Failed to initialize the list.\n");
        return EXIT_FAILURE;
    }

    add_pdu(&list, 1234, 5678);
    NFAPI_CRC_INDICATION_PDU_T pdu;
