    pthread_mutex_lock(&lock);

    srand(seed);
    FrameStatistics* frameStats = malloc(sizeof(FrameStatistics));
    if (!frameStats) {
        log_message("Memory allocation failed for FrameStatistics structure.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    frameStats->frameNumber = frameNumber;
    frameStats->timestamp = time(NULL);
    frameStats->activeChannels = activeColumns;
    frameStats->successfulInitializations = 0;
    frameStats->failedInitializations = 0;

    frameStats->channelQualities = malloc(activeColumns * sizeof(ChannelQuality));
