        log_message("Memory allocation failed for ChannelQuality array.");
        free(frameStats);
        frameStats->failedInitializations++;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int retryCount = 0, maxRetries = 3, backoffTime = 1; // Backoff logic parameters
    while (retryCount < maxRetries) {
        for (int i = 0; i < activeChannels; ++i) {
            frameStats->channelQualities[i].signalStrength = -150 + rand() % 101;
        }

        if (/* condition to check successful initialization */) { // Implement actual success check
