            break;
        } else {
            log_message("Initialization failed, retrying...");
            sleep(backoffTime);
            backoffTime *= 2; // Exponential backoff
            retryCount++;
        }
    }

    if (retryCount == maxRetries) {
        log_message("Max retries reached. Initialization failed.");
        free(frameStats->channelQualities);
        free(frameStats);
        frameStats = NULL;
    }

    pthread_mutex_unlock(&lock);

    // Optionally, write logs to a file
    FILE *logFile = fopen(logFilePath, "a");
    if (logFile) {
