                frameStats ? frameStats->frameNumber : -1,
                frameStats ? frameStats->timestamp : time(NULL),
                frameStats ? frameStats->successfulInitializations : 0,
                frameStats ? frameStats->failedInitializations : 1);
        fclose(logFile);
    }

    return frameStats;
}

