#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    // Other fields can be added here
} NFAPI_CRC_INDICATION_PDU_T;

