    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} CRC_List;

CRC_List* create_list() {
    CRC_List* list = (CRC_List*)malloc(sizeof(CRC_List));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node* node) {
    free(node);
}

bool is_rnti_registered(CRC_List* list, unsigned short rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.crc_tag.RNTI == rnti) return true;
        current = current->next;
    }
    return false;
}

bool add_to_list(CRC_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->size >= MAX_LIST_SIZE) return false;

    pthread_mutex_lock(&list->lock);

    if (is_rnti_registered(list, pdu.crc_tag.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    // Randomly set CRCFLAG
    srand((unsigned int)time(NULL));
    new_node->data.crc_tag.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void clear_list(CRC_List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free_node(temp);
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(CRC_List* list) {
    if (!list) return;

    clear_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

