// Function to insert after the first occurrence of a string in a forward list
void insertAfterFirstOccurrence(std::forward_list<std::string>& flist, const std::string& target, const std::string& value) {
    auto it = flist.before_begin();
    bool found = false;

    for (auto next_it = flist.begin(); next_it != flist.end() && !found; ++next_it) {
        if (*next_it == target) {
            flist.insert_after(next_it, value);
            found = true;
        }
        it = next_it;
    }

    if (!found) {
        flist.push_back(value);
    }
}

