#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 1000

typedef struct {
    unsigned int RNTI;
    unsigned long RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    int crc_count[MAX_ENTRIES]; // Simple hash for tracking CRC counts per RNTI
} CRCList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; 
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

CRCList* init_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    memset(list->crc_count, 0, sizeof(list->crc_count));
    return list;
}

int add_crc_indication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size >= MAX_ENTRIES) {
        // Remove the oldest entry
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        --list->size;

        // Adjust CRC count
        int rnti_index = data.RNTI % MAX_ENTRIES; // Simple hash function for demonstration
        if (list->crc_count[rnti_index] > 0) {
            --list->crc_count[rnti_index];
        }
    }

    Node* new_node = create_node(data);
    if (!new_node) return -1;

    // Insert at the head to maintain insertion order
    new_node->next = list->head;
    list->head = new_node;
    ++list->size;

    int rnti_index = data.RNTI % MAX_ENTRIES; // Simple hash function for demonstration
    ++list->crc_count[rnti_index];

    return 0;
}

int remove_crc_indication(CRCList* list, unsigned int RNTI) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            // Remove node
            if (prev == NULL) { 
                list->head = current->next; 
            } else {
                prev->next = current->next;
            }
            free(current);

            --list->size;

            int rnti_index = RNTI % MAX_ENTRIES;
            if (list->crc_count[rnti_index] > 0) {
                --list->crc_count[rnti_index];
            }

            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    return -1; // Not found
}

void iterate_and_print(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %lu\n", current->data.RTX_UE_INFORMATION_TAG);
        current = current->next;
    }
}

int get_crc_count(CRCList* list, unsigned int RNTI) {
    if (list == NULL || list->size <= 0) return -1;

    int rnti_index = RNTI % MAX_ENTRIES;
    return list->crc_count[rnti_index];
}

void cleanup_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}
