#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define RANGE_MIN 0
#define RANGE_MAX 100

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t count;
    pthread_mutex_t lock;
} RecordSet;

typedef struct {
    record* buffer_pool;
    size_t pool_size;
    size_t free_index;
    pthread_mutex_t lock;
} BufferPool;

BufferPool* create_buffer_pool(size_t pool_size) {
    BufferPool* bp = malloc(sizeof(BufferPool));
    if (!bp) return NULL;

    bp->buffer_pool = calloc(pool_size, sizeof(record));
    if (!bp->buffer_pool) {
        free(bp);
        return NULL;
    }

    bp->pool_size = pool_size;
    bp->free_index = 0;
    pthread_mutex_init(&bp->lock, NULL);

    return bp;
}

record* allocate_record(BufferPool* bp) {
    pthread_mutex_lock(&bp->lock);
    if (bp->free_index < bp->pool_size) {
        record* rec = &bp->buffer_pool[bp->free_index++];
        pthread_mutex_unlock(&bp->lock);
        return rec;
    }
    pthread_mutex_unlock(&bp->lock);
    return NULL; // Buffer pool exhausted
}

void free_buffer_pool(BufferPool* bp) {
    free(bp->buffer_pool);
    pthread_mutex_destroy(&bp->lock);
    free(bp);
}

RecordSet* create_record_set(size_t count, BufferPool* bp) {
    RecordSet* rs = malloc(sizeof(RecordSet));
    if (!rs) return NULL;

    rs->offsets = malloc(count * sizeof(long));
    rs->keys = malloc(count * sizeof(int));
    rs->records = malloc(count * sizeof(record*));

    if (!rs->offsets || !rs->keys || !rs->records) {
        free(rs->offsets);
        free(rs->keys);
        free(rs->records);
        free(rs);
        return NULL;
    }

    rs->count = count;
    pthread_mutex_init(&rs->lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        record* rec = allocate_record(bp);
        if (!rec) {
            fprintf(stderr, "Error: Buffer pool exhausted\n");
            free(rs->offsets);
            free(rs->keys);
            free(rs->records);
            free(rs);
            return NULL;
        }
        rs->records[i] = rec;
        rs->keys[i] = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;
        rs->offsets[i] = i; // Example offset
    }

    return rs;
}

void free_record_set(RecordSet* rs) {
    pthread_mutex_destroy(&rs->lock);
    free(rs->offsets);
    free(rs->keys);
    free(rs->records);
    free(rs);
}

void* process_records(void* arg) {
    RecordSet* rs = (RecordSet*)arg;
    pthread_mutex_lock(&rs->lock);

    for (size_t i = 0; i < rs->count; ++i) {
        rs->records[i]->value = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;
    }

    pthread_mutex_unlock(&rs->lock);
    return NULL;
}

void batch_process(RecordSet* record_sets[], size_t num_sets, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        int idx = i % num_sets;
        pthread_create(&threads[i], NULL, process_records, (void*)record_sets[idx]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));

    size_t pool_size = MAX_RECORDS;
    BufferPool* bp = create_buffer_pool(pool_size);
    if (!bp) return EXIT_FAILURE;

    RecordSet* record_sets[10];
    for (size_t i = 0; i < 10; ++i) {
        record_sets[i] = create_record_set(MAX_RECORDS, bp);
        if (!record_sets[i]) {
            fprintf(stderr, "Error: Failed to create record set\n");
            free_buffer_pool(bp);
            return EXIT_FAILURE;
        }
    }

    batch_process(record_sets, 10, 4);

    for (size_t i = 0; i < 10; ++i) {
        free_record_set(record_sets[i]);
    }

    free_buffer_pool(bp);
    return EXIT_SUCCESS;
}
