        ues[i].snr_indication_rel8_tag = snr;
        ues[i].ber_indication_tag = ber;

        update_global_stats(snr, ber);
    }

    pthread_mutex_unlock(&array_lock);

    free(ues); // Reclaim memory for this channel

    return NULL;
}

// Function to convert SNR to BER (example conversion)
float snr_to_ber(float snr) {
    return 1.0f / (snr + 1.0f);
}

// Update global statistics
void update_global_stats(float snr, float ber) {
    pthread_mutex_lock(&array_lock);

    global_stats.snr += snr;
    if(snr < global_stats.min_snr) global_stats.min_snr = snr;
    if(snr > global_stats.max_snr) global_stats.max_snr = snr;

    global_stats.ber += ber;
    if(ber < global_stats.min_ber) global_stats.min_ber = ber;
    if(ber > global_stats.max_ber) global_stats.max_ber = ber;

    pthread_mutex_unlock(&array_lock);
}

// Main function
