void log_metrics();

// Implementation of functions

void add_ue_context(int ue_id) {
    if (!data_warehouse_available && current_ue_count >= max_ues_allowed) return;

    pthread_mutex_lock(&ue_ctx_lock);

    UE_Context *new_context = (UE_Context *)malloc(sizeof(UE_Context));
    new_context->ue_id = ue_id;
    new_context->rrc_state = IDLE;
    new_context->reconfig_complete_msgs = NULL;
    new_context->msg_count = 0;
    new_context->next = ue_contexts;
    ue_contexts = new_context;

    current_ue_count++;

    pthread_mutex_unlock(&ue_ctx_lock);
}

void update_rrc_state(int ue_id, const char *message) {
    pthread_mutex_lock(&ue_ctx_lock);

    UE_Context *current = ue_contexts;
    while (current != NULL && current->ue_id != ue_id) {
        current = current->next;
    }

    if (current == NULL) return;

    // Update RRC state
    current->rrc_state = CONNECTED; // Example logic

    // Add the message to the list
    size_t new_count = current->msg_count + 1;
    current->reconfig_complete_msgs = realloc(current->reconfig_complete_msgs, new_count * sizeof(RRC_MSG));

    if (current->reconfig_complete_msgs) {
        RRC_MSG *new_message = &current->reconfig_complete_msgs[current->msg_count];
        new_message->ue_id = ue_id;
        new_message->message = strdup(message);

        current->msg_count = new_count;
    }

    pthread_mutex_unlock(&ue_ctx_lock);

    // Persist update to data warehouse with retry logic
    handle_network_failure(
        []() {
            // Functionality to persist changes in the warehouse
        },
        0
    );
}

void handle_network_failure(void (*retry_func)(), int retries) {
    int backoff = INITIAL_BACKOFF_MS;

    while (!data_warehouse_available && retries < 5) {
        retry_func();

        sleep(backoff / 1000);
        backoff *= BACKOFF_MULTIPLIER;
        retries++;
    }
}

void adjust_max_ues_allowed() {
    // Example logic to adjust based on load and usage patterns
    max_ues_allowed = (current_ue_count < MAX_UE_CONTEXTS) ? current_ue_count * 2 : MAX_UE_CONTEXTS;
}

void log_metrics() {
    pthread_mutex_lock(&ue_ctx_lock);

    printf("Current UE Count: %zu\n", current_ue_count);
    printf("Max UEs Allowed: %d\n", max_ues_allowed);

    // Additional logging for performance metrics

    pthread_mutex_unlock(&ue_ctx_lock);
}

// Entry point for testing

int main() {
    add_ue_context(1);
    update_rrc_state(1, "Reconfig Complete");

    adjust_max_ues_allowed();
    log_metrics();

    return 0;
}
