    manager->capacity = initial_capacity;
    manager->count = 0;

    // Allocate array of pointers to LTE_RRC_SRB1_MESSAGE
    manager->message_array = (LTE_RRC_SRB1_MESSAGE **)malloc(manager->capacity * sizeof(LTE_RRC_SRB1_MESSAGE *));
    if (!manager->message_array) {
        fprintf(stderr, "Failed to allocate memory for message array\n");
        return;
