        LTE_RRC_SRB1_MESSAGE *msg = (LTE_RRC_SRB1_MESSAGE *)malloc(sizeof(LTE_RRC_SRB1_MESSAGE));
        if (!msg) {
            fprintf(stderr, "Failed to allocate memory for message structure\n");
            // Free previously allocated messages before returning
