#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    MESSAGE_TYPE_A,
    MESSAGE_TYPE_B,
    // Add other message types as needed
} LTE_RRC_SRB1_MESSAGE_TYPE;

#define MAX_PAYLOAD_SIZE 1024
#define AVERAGE_PAYLOAD_SIZE 256

typedef struct LTE_RRC_SRB1_MESSAGE {
    LTE_RRC_SRB1_MESSAGE_TYPE type;
    uint8_t *buffer;
    size_t buffer_size;
} LTE_RRC_SRB1_MESSAGE;

typedef struct Node {
    LTE_RRC_SRB1_MESSAGE message;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    size_t max_payload_size;
    size_t avg_payload_size;
} MessageList;

// Initialize the dynamic list
int init_message_list(MessageList *list, size_t max_payload_size, size_t avg_payload_size) {
    if (pthread_mutex_init(&list->lock, NULL)) return -1;
    list->head = NULL;
    list->max_payload_size = max_payload_size > 0 ? max_payload_size : MAX_PAYLOAD_SIZE;
    list->avg_payload_size = avg_payload_size > 0 ? avg_payload_size : AVERAGE_PAYLOAD_SIZE;
    return 0;
}

// Insert a new message into the list
int insert_message(MessageList *list, LTE_RRC_SRB1_MESSAGE_TYPE type) {
    pthread_mutex_lock(&list->lock);

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->message.type = type;
    new_node->message.buffer_size = list->avg_payload_size; // Start with average size
    new_node->message.buffer = (uint8_t *)malloc(new_node->message.buffer_size);
    if (!new_node->message.buffer) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove a message from the list
int remove_message(MessageList *list) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node *temp = list->head;
    list->head = list->head->next;

    free(temp->message.buffer);
    free(temp);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Traverse and print all messages
void traverse_messages(MessageList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        printf("Message Type: %d, Buffer Size: %zu\n", current->message.type, current->message.buffer_size);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup and release all resources
void cleanup_message_list(MessageList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;

        free(temp->message.buffer);
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example testing function
void test_message_list() {
    MessageList list;
    init_message_list(&list, MAX_PAYLOAD_SIZE, AVERAGE_PAYLOAD_SIZE);

    insert_message(&list, MESSAGE_TYPE_A);
    insert_message(&list, MESSAGE_TYPE_B);

    traverse_messages(&list);

    remove_message(&list);
    remove_message(&list);

    cleanup_message_list(&list);
}

int main() {
    test_message_list();
    return 0;
}
