    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} FULL_NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CELLULAR_EVENT_PDU_T;

typedef struct {
    time_t timestamp;
    int event_type;
} CELLULAR_EVENT_REL8_TAG;

#define VALID_EVENT_TYPES {0, 1, 2, 3, 4}

typedef struct {
    NFAPI_CELLULAR_EVENT_PDU_T cellular_pdu;
    CELLULAR_EVENT_REL8_TAG cell_event_rel8_tag;
} FULL_NFAPI_CELLULAR_EVENT_PDU_T;

typedef enum { CRC_INDICATION = 0, CELLULAR_EVENT } PDU_TYPE;

typedef union {
    FULL_NFAPI_CRC_INDICATION_PDU_T crc_indication;
    FULL_NFAPI_CELLULAR_EVENT_PDU_T cellular_event;
} PDU_UNION;

typedef struct {
    PDU_UNION pdu_data;
    PDU_TYPE type;
} PDU_LIST_NODE_T;

typedef struct {
    PDU_LIST_NODE_T *head;
    pthread_mutex_t lock;
} PDU_LIST_T;

PDU_LIST_T* create_pdu_list() {
    PDU_LIST_T *list = (PDU_LIST_T *)malloc(sizeof(PDU_LIST_T));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_valid_event_type(int event_type) {
    int valid_types[] = VALID_EVENT_TYPES;
    for (int i = 0; i < MAX_EVENT_TYPES; ++i) {
        if (valid_types[i] == event_type)
            return 1;
    }
    return 0;
}

void log_message(const char *message) {
    printf("%s\n", message);
}

PDU_LIST_NODE_T* create_crc_pdu() {
    PDU_LIST_NODE_T *node = (PDU_LIST_NODE_T *)malloc(sizeof(PDU_LIST_NODE_T));

    node->pdu_data.crc_indication.crc_pdu.valid_RX_UE_INFORMATION_TAG = 1;
    node->pdu_data.crc_indication.crc_pdu.RNTI = rand() % 1000;

    node->pdu_data.crc_indication.crc_ind_rel8_tag.CRCFLAG = rand() % 2;

    node->type = CRC_INDICATION;

    log_message("Created CRC Indication PDU");
    return node;
}

PDU_LIST_NODE_T* create_cellular_event_pdu(int event_type) {
    if (!is_valid_event_type(event_type)) {
        log_message("Invalid Cellular Event Type. Using default type 0.");
        event_type = 0; // Fallback to default valid type
    }

    PDU_LIST_NODE_T *node = (PDU_LIST_NODE_T *)malloc(sizeof(PDU_LIST_NODE_T));

    node->pdu_data.cellular_event.cellular_pdu.valid_RX_UE_INFORMATION_TAG = 1;
    node->pdu_data.cellular_event.cellular_pdu.RNTI = rand() % 1000;

    node->pdu_data.cellular_event.cell_event_rel8_tag.timestamp = time(NULL);
    node->pdu_data.cellular_event.cell_event_rel8_tag.event_type = event_type;

    node->type = CELLULAR_EVENT;

    log_message("Created Cellular Event PDU");
    return node;
}

void append_to_list(PDU_LIST_T *list, PDU_LIST_NODE_T *node) {
    pthread_mutex_lock(&list->lock);
    node->pdu_data.crc_indication.crc_pdu.RNTI = rand() % 1000; // Example update
    node->next = list->head;
    list->head = node;
    pthread_mutex_unlock(&list->lock);
}

void initialize_pdu_list(PDU_LIST_T *list, int N, int M) {
    for (int i = 0; i < N; ++i) {
        PDU_LIST_NODE_T *crc_node = create_crc_pdu();
        append_to_list(list, crc_node);
    }

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < M; ++i) {
        int event_type = rand() % (MAX_EVENT_TYPES + 1); // Randomly choose an event type
        PDU_LIST_NODE_T *cellular_node = create_cellular_event_pdu(event_type);
        append_to_list(list, cellular_node);
    }
}

void free_pdu_list(PDU_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    PDU_LIST_NODE_T *current = list->head;
    while (current != NULL) {
        PDU_LIST_NODE_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    int N = 5; // Example number of CRC structures
    int M = 3; // Example number of Cellular Event structures

    PDU_LIST_T *pdu_list = create_pdu_list();
    initialize_pdu_list(pdu_list, N, M);

    free_pdu_list(pdu_list);
    return 0;
}
```

### Key Points:

- The code uses a linked list to dynamically manage the PDUs.
- It employs mutexes (`pthread_mutex_t`) to ensure thread-safe operations when accessing or modifying the shared data structure.
- A random number generator is seeded for CRCFLAG and event types, providing variability in PDU contents.
- Validation checks are included for cellular events to handle invalid inputs gracefully, logging any discrepancies.
- A simple logging function captures essential information without significantly impacting performance.
- Memory management functions (`malloc` and `free`) ensure efficient use of resources while preventing leaks.']

