#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define structures for User Equipment (UE) information
typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    double SNR_INDICATION_REL8_TAG;
} UE_Info;

typedef struct {
    uint64_t offset;
    int key;
    double snr_value;
    UE_Info ue_info;
} UERecord;

// Define a dynamic array structure with locking mechanism for thread-safety
typedef struct {
    UERecord *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} DynamicArray;

// Function to initialize the dynamic array
void initDynamicArray(DynamicArray *da, size_t initial_capacity) {
    da->size = 0;
    da->capacity = initial_capacity;
    da->array = (UERecord *)malloc(sizeof(UERecord) * initial_capacity);
    pthread_mutex_init(&da->lock, NULL);
}

// Function to double the capacity of the dynamic array
void resizeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    size_t new_capacity = da->capacity * 2;
    UERecord *new_array = (UERecord *)realloc(da->array, sizeof(UERecord) * new_capacity);

    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    da->array = new_array;
    da->capacity = new_capacity;
    pthread_mutex_unlock(&da->lock);
}

// Function to add a UERecord into the dynamic array
void addUERecord(DynamicArray *da, uint64_t offset, int key, double snr_value,
                 UE_Info ue_info) {
    if (offset == 0) {
        fprintf(stderr, "Offset must be greater than zero\n");
        return;
    }

    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].offset == offset) {
            fprintf(stderr, "Duplicate offset detected: %llu\n", offset);
            pthread_mutex_unlock(&da->lock);
            return;
        }
    }

    if (da->size >= da->capacity) {
        resizeDynamicArray(da);
    }

    UERecord new_record = {offset, key, snr_value, ue_info};
    da->array[da->size++] = new_record;
    pthread_mutex_unlock(&da->lock);
}

// Function to simulate SNR values using a simple random noise model
double calculateSNR() {
    double signal_strength = 50.0; // Base signal strength
    double noise_level = (double)rand() / RAND_MAX * 10.0; // Random noise between 0 and 10
    return signal_strength - noise_level;
}

// Function to populate the dynamic array with simulated UE information
void simulateUEInformation(DynamicArray *da, size_t ue_count) {
    srand(time(NULL));
    for (size_t i = 0; i < ue_count; ++i) {
        uint64_t offset = rand() % UINT64_MAX + 1;
        int key = rand();
        double snr_value = calculateSNR();

        UE_Info ue_info = {offset, rand(), rand(), snr_value};

        addUERecord(da, offset, key, snr_value, ue_info);
    }
}

// Function to clean up resources
void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int main() {
    DynamicArray ueArray;
    initDynamicArray(&ueArray, 10); // Initial capacity of 10
    simulateUEInformation(&ueArray, 20); // Simulate information for 20 UEs

    for (size_t i = 0; i < ueArray.size; ++i) {
        printf("Offset: %llu, Key: %d, SNR: %.2f\n", ueArray.array[i].offset,
               ueArray.array[i].key, ueArray.array[i].snr_value);
    }

    freeDynamicArray(&ueArray);
    return 0;
}
