#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define LOG_INTERVAL_DEFAULT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t log_interval;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity, size_t log_interval);
void free_dynamic_array(DynamicArray *da);
int resize_array_if_needed(DynamicArray *da);
int add_element_to_array(DynamicArray *da, int seed);
int remove_least_recently_used(DynamicArray *da);
void serialize_to_file(const DynamicArray *da, const char *filename);
int deserialize_from_file(DynamicArray *da, const char *filename);

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *da, size_t initial_capacity, size_t log_interval) {
    pthread_mutex_init(&da->lock, NULL);
    da->capacity = initial_capacity;
    da->count = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->log_interval = log_interval;
}

// Free the dynamic array
void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->count = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

// Resize array if needed, remove least recently used elements
int resize_array_if_needed(DynamicArray *da) {
    size_t available_memory = /* Function to get available system memory */;
    size_t required_memory = da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    while (required_memory > available_memory && da->count > 0) {
        remove_least_recently_used(da);
        required_memory = da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    return 0;
}

// Add an element to the dynamic array
int add_element_to_array(DynamicArray *da, int seed) {
    pthread_mutex_lock(&da->lock);

    if (resize_array_if_needed(da)) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity == 0 ? 10 : da->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1;
        }

        da->array = new_array;
        da->capacity = new_capacity;
    }

    srand(seed + time(NULL)); // Initialize random seed
    NFAPI_CRC_INDICATION_PDU_T new_element;
    new_element.RX_UE_INFORMATION_TAG = rand();
    new_element.RNTI = rand();
    new_element.CRC_INDICATION_REL8_TAG = rand();
    new_element.CRCFLAG = rand() % 2; // Random CRC flag
    new_element.timestamp = time(NULL);

    da->array[da->count++] = new_element;

    if (0 == (da->count % da->log_interval)) {
        printf("Added element at index %zu\n", da->count - 1);
    }

    pthread_mutex_unlock(&da->lock);
    return 0;
}

// Remove the least recently used element
int remove_least_recently_used(DynamicArray *da) {
    if (da->count == 0) {
        return -1;
    }
    // Simple LRU logic: remove from start of array
    memmove(da->array, da->array + 1, (--da->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (0 == (da->count % da->log_interval)) {
        printf("Removed least recently used element\n");
    }
    return 0;
}

// Serialize array to file
void serialize_to_file(const DynamicArray *da, const char *filename) {
    pthread_mutex_lock((pthread_mutex_t *)&da->lock);
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&da->count, sizeof(size_t), 1, file);
        fwrite(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->count, file);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for serialization\n");
    }
    pthread_mutex_unlock((pthread_mutex_t *)&da->lock);
}

// Deserialize array from file
int deserialize_from_file(DynamicArray *da, const char *filename) {
    pthread_mutex_lock(&da->lock);

    FILE *file = fopen(filename, "rb");
    if (file) {
        size_t new_count;
        fread(&new_count, sizeof(size_t), 1, file);

        if (resize_array_if_needed(da)) {
            fclose(file);
            return -1;
        }

        da->count = new_count;
        fread(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->count, file);
        fclose(file);

    } else {
        fprintf(stderr, "Failed to open file for deserialization\n");
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    pthread_mutex_unlock(&da->lock);
    return 0;
}
```

