['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct record {
    int value;
};

long* generate_offsets(int seed, size_t num_offsets);

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <num_offsets> <num_records>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_offsets = strtoul(argv[1], NULL, 10);
    size_t num_records = strtoul(argv[2], NULL, 10);

    srand(time(NULL));

    // Allocate and initialize offsets
    long* offsets = generate_offsets(rand(), num_offsets);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return EXIT_FAILURE;
    }

    // Allocate and populate keys with unique random values between 1 and 1000
    int *keys = (int *)malloc(num_offsets * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        return EXIT_FAILURE;
    }

    int range = 1000;
    int max_size = (range < num_offsets) ? -1 : num_offsets; // To handle limited range
    while (max_size != -1 && max_size > 0) {
        memset(keys, 0, num_offsets * sizeof(int));
        for (size_t i = 0; i < num_offsets; ++i) {
            int key;
            do {
                key = rand() % range + 1;
            } while (keys[key - 1]);
            keys[i] = key;
        }

        // Check uniqueness
        int unique_count = 0;
        for (size_t i = 0; i < num_offsets; ++i) {
            if (keys[i]) {
                unique_count++;
                keys[i] = 0; // Mark as used
            }
        }

        max_size = range - unique_count; // Adjust remaining slots
    }

    if (max_size == -1) {
        fprintf(stderr, "Unable to generate unique keys within the specified range.\n");
        free(offsets);
        free(keys);
        return EXIT_FAILURE;
    }

    // Allocate and initialize records
    struct record *records = (struct record *)malloc(num_records * sizeof(struct record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return EXIT_FAILURE;
    }
    memset(records, 0, num_records * sizeof(struct record));

    // Sort keys using a stable sorting algorithm (merge sort)
    void merge(int arr[], int l, int m, int r) {
        int i, j, k;
        int n1 = m - l + 1;
        int n2 = r - m;

        int *L = malloc(n1 * sizeof(int));
        int *R = malloc(n2 * sizeof(int));

        for (i = 0; i < n1; i++)
            L[i] = arr[l + i];
        for (j = 0; j < n2; j++)
            R[j] = arr[m + 1 + j];

        i = 0;
        j = 0;
        k = l;

        while (i < n1 && j < n2) {
            if (L[i] <= R[j]) {
                arr[k] = L[i];
                i++;
            } else {
                arr[k] = R[j];
                j++;
            }
            k++;
        }

        while (i < n1) {
            arr[k] = L[i];
            i++;
            k++;
        }

        while (j < n2) {
            arr[k] = R[j];
            j++;
            k++;
        }

        free(L);
        free(R);
    }

    void mergeSort(int arr[], int l, int r) {
        if (l < r) {
            int m = l + (r - l) / 2;

            mergeSort(arr, l, m);
            mergeSort(arr, m + 1, r);

            merge(arr, l, m, r);
        }
    }

    // Perform the sort
    mergeSort(keys, 0, num_offsets - 1);

    // Update records array based on keys
    for (size_t i = 0; i < num_offsets; ++i) {
        int index = keys[i] - 1;
        if (index >= 0 && index < num_records) { 
            records[index].value += rand() % 10 + 1;
        }
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}

long* generate_offsets(int seed, size_t num_offsets) {
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) return NULL;

    srand(seed);
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % 10000;
    }

    return offsets;
}
