#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int rssi;
} RX_UE_SIGNAL_STRENGTH_REPORT;

typedef struct {
    float cqi;
} RX_UE_CHANNEL_QUALITY_INDICATOR;

typedef struct {
    int tx_power_level;
} TX_POWER_COMMAND;

typedef struct {
    int ue_id;
    RX_UE_SIGNAL_STRENGTH_REPORT signal_strength_report;
    RX_UE_CHANNEL_QUALITY_INDICATOR channel_quality_indicator;
    TX_POWER_COMMAND *tx_power_command; // Optional
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T* initialize_nfa_messages(int num_ue, int include_tx_commands) {
    if (num_ue <= 0) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    NFAPI_MESSAGE_T *messages = malloc(num_ue * sizeof(NFAPI_MESSAGE_T));
    if (!messages) {
        pthread_mutex_unlock(&lock);
        return NULL; // Handle out-of-memory gracefully
    }

    for (int i = 0; i < num_ue; ++i) {
        messages[i].ue_id = i;
        // Simulate signal strength and channel quality initialization
        messages[i].signal_strength_report.rssi = rand() % 100 - 50; // Example values
        messages[i].channel_quality_indicator.cqi = (float)(rand() % 20000) / 100.0;

        if (include_tx_commands) {
            messages[i].tx_power_command = malloc(sizeof(TX_POWER_COMMAND));
            if (!messages[i].tx_power_command) {
                // Clean up previously allocated memory in case of failure
                for (int j = 0; j < i; ++j) {
                    free(messages[j].tx_power_command);
                }
                free(messages);
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            messages[i].tx_power_command->tx_power_level = rand() % 31; // Example power levels
        } else {
            messages[i].tx_power_command = NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    return messages;
}

void cleanup_nfa_messages(NFAPI_MESSAGE_T *messages, int num_ue, int include_tx_commands) {
    if (!messages) return;

    for (int i = 0; i < num_ue; ++i) {
        if (include_tx_commands && messages[i].tx_power_command) {
            free(messages[i].tx_power_command);
        }
    }

    free(messages);
}
