#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

// Define a structure for NFAPI_CRC_INDICATION_PDU_T with necessary fields
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[16];
    uint8_t CRCFLAG; // Assume this is a single byte flag for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

// Define an error code structure or constants
#define MEMORY_ALLOCATION_ERROR -1
#define SUCCESS 0

// Node in the linked list
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

// Function to generate a random RNTI value
uint16_t generate_random_rnti() {
    return rand() % (1 << 15); // Assuming RNTI is a 15-bit value for this example
}

// Helper function to check if the RNTI already exists in the list
int rnti_exists(ListNode *head, uint16_t rnti) {
    ListNode *current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return 1;
        current = current->next;
    }
    return 0;
}

// Function to create a new list node
ListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode *newNode = (ListNode *)malloc(sizeof(ListNode));
    if (!newNode) {
        return NULL; // Memory allocation failure
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to dynamically generate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
int generate_nfa_list(int n, int max_unique_rnti_values, ListNode **head) {
    *head = NULL;
    if (n <= 0 || max_unique_rnti_values <= 0)
        return MEMORY_ALLOCATION_ERROR;

    srand(time(NULL)); // Seed the random number generator

    uint16_t rntis[max_unique_rnti_values];
    int unique_count = 0;

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate a new RNTI
        do {
            pdu.RNTI = generate_random_rnti();
        } while ((unique_count > 0 && rnti_exists(*head, pdu.RNTI)) || (unique_count < max_unique_rnti_values && !rnti_exists(*head, pdu.RNTI) && rnti_exists(rntis, pdu.RNTI)));

        // Record the unique RNTI
        if (unique_count < max_unique_rnti_values) {
            rntis[unique_count++] = pdu.RNTI;
        }

        // Fill other fields with random data for demonstration purposes
        pdu.RX_UE_INFORMATION_TAG = rand();
        for (int j = 0; j < sizeof(pdu.CRC_INDICATION_REL8_TAG); ++j) {
            pdu.CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
        pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        ListNode *newNode = create_node(pdu);
        if (!newNode)
            return MEMORY_ALLOCATION_ERROR;

        newNode->next = *head;
        *head = newNode;
    }

    return SUCCESS;
}

// Example usage
int main() {
    ListNode *list_head = NULL;
    int n = 10; // Number of elements in the list
    int max_unique_rnti_values = 5; // Maximum unique RNTI values

    int result = generate_nfa_list(n, max_unique_rnti_values, &list_head);
    if (result == MEMORY_ALLOCATION_ERROR) {
        printf("Memory allocation failed.\n");
    } else {
        printf("List generated successfully with %d elements.\n", n);
    }

    // Free allocated memory
    ListNode *current = list_head;
    while (current != NULL) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
