typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef enum {
    DES_ECB,
    DES_EDE,
    DES_EDE3,
    DES_CFB,
    NULL_ENCRYPTION
} CipherMode;

EVP_CIPHER* initialize_records(int num_records, double min_value, double max_value, CipherMode mode) {
    if (num_records <= 0) return NULL;

    // Allocate memory for records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Validation set for unique offsets
    long *offsets = (long *)calloc(num_records, sizeof(long));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int key_gen_attempts = 0;

    // Populate records with random data and ensure unique offsets
    for (int i = 0; i < num_records; ++i) {
        do {
            records[i].offset = rand() % (num_records * 10) + 1;
            if (++key_gen_attempts > num_records * 10) break;
        } while (offsets[records[i].offset - 1] != 0);

        // Unique offset validation
        if (offsets[records[i].offset - 1]) {
            free(records);
            free(offsets);
            fprintf(stderr, "Unique offset generation failed\n");
            return NULL;
        }

        offsets[records[i].offset - 1] = 1;

        records[i].key = rand() % 100; // Arbitrary key generation
        records[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }

    free(offsets);

    // Select and initialize cipher based on mode
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher_type;

    switch (mode) {
        case DES_ECB:
            cipher_type = EVP_des_ecb();
            break;
        case DES_EDE:
            cipher_type = EVP_des_ede();
            break;
        case DES_EDE3:
            cipher_type = EVP_des_ede3();
            break;
        case DES_CFB:
            cipher_type = EVP_des_cfb64();
            break;
        default: // NULL_ENCRYPTION
            return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        free(records);
        fprintf(stderr, "Cipher context initialization failed\n");
        return NULL;
    }

    // Init cipher with a random key and IV (for demonstration)
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_length];
    RAND_bytes(key, EVP_des_key_len());
    RAND_bytes(iv, EVP_CIPHER_iv_length(cipher_type));

    if (!EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv)) {
        free(records);
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Cipher initialization failed\n");
        return NULL;
    }

    // Return the initialized cipher
    EVP_CIPHER *cipher = EVP_CIPHER_CTX_cipher(ctx);
    EVP_CIPHER_CTX_free(ctx);

    return cipher;
}

int main() {
    int num_records = 1000;
    double min_value = 0.0, max_value = 10.0;
    CipherMode mode = DES_ECB;

    EVP_CIPHER *cipher = initialize_records(num_records, min_value, max_value, mode);
    if (cipher) {
        printf("Cipher initialized successfully\n");
    } else {
        printf("Cipher initialization failed\n");
    }

    // Clean up and close OpenSSL
    EVP_cleanup();

    return 0;
}
