```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_TAGS 10000

typedef struct {
    int rnti;
} NFAPI_RX_UE_INFORMATION_TAG;

typedef struct {
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    NFAPI_RX_UE_INFORMATION_TAG ue_tag;
    int assigned_rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Assume this function interfaces with an external RNTI pool
int get_next_available_rnti() {
    static pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;
    static int last_rnti = 0x0001; // Starting RNTI value

    pthread_mutex_lock(&rnti_mutex);
    int new_rnti = ++last_rnti & 0xFFFFF; // Simulate a 20-bit RNTI space
    pthread_mutex_unlock(&rnti_mutex);

    if (new_rnti == last_rnti) {
        fprintf(stderr, "RNTI pool exhausted\n");
        return -1;
    }

    return new_rnti;
}

void handle_crc_indications(NFAPI_RX_UE_INFORMATION_TAG *ue_tags[], size_t count) {
    if (count > MAX_UE_TAGS) {
        fprintf(stderr, "Exceeded maximum number of UE tags\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T **indication_pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!indication_pdus) {
        perror("Memory allocation failed for indication PDUs");
        return;
    }

    int rnti_pool[MAX_UE_TAGS] = {0};
    pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < count; ++i) {
        indication_pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!indication_pdus[i]) {
            perror("Memory allocation failed for individual PDU");
            // Cleanup and exit
            while (--i >= 0) free(indication_pdus[i]);
            free(indication_pdus);
            return;
        }

        indication_pdus[i]->ue_tag = ue_tags[i][0];

        pthread_mutex_lock(&pool_mutex);
        int assigned_rnti = get_next_available_rnti();
        if (assigned_rnti == -1) {
            fprintf(stderr, "Failed to assign RNTI\n");
            // Cleanup and exit
            while (--i >= 0) free(indication_pdus[i]);
            free(indication_pdus);
            pthread_mutex_unlock(&pool_mutex);
            return;
        }

        if (rnti_pool[assigned_rnti]) {
            fprintf(stderr, "Duplicate RNTI detected: %d\n", assigned_rnti);
        } else {
            rnti_pool[assigned_rnti] = 1;
        }

        indication_pdus[i]->assigned_rnti = assigned_rnti;
        pthread_mutex_unlock(&pool_mutex);

        indication_pdus[i]->crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRC flag
    }

    // Process the populated PDUs (e.g., send to another system)
    for (size_t i = 0; i < count; ++i) {
        printf("UE Tag: RNTI %d, CRC Flag: %d\n", indication_pdus[i]->assigned_rnti, indication_pdus[i]->crc_indication_rel8_tag.crcflag);
        free(indication_pdus[i]);
    }

    free(indication_pdus);
}

int main() {
    // Example usage
    NFAPI_RX_UE_INFORMATION_TAG ue_tags1[] = {{.rnti = 1}};
    NFAPI_RX_UE_INFORMATION_TAG *ue_tags[MAX_UE_TAGS] = {ue_tags1};

    handle_crc_indications(ue_tags, 1);

    return 0;
}
