```csharp
using System;
using System.Collections.Concurrent;
using Microsoft.Extensions.Caching.Distributed;

public class PageElementUpdater
{
    private readonly IDistributedCache _cache;
    private static readonly ConcurrentDictionary<string, object> LockTable = new();

    public PageElementUpdater(IDistributedCache cache)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public void UpdatePageElement(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrWhiteSpace(pageSectionId) || string.IsNullOrWhiteSpace(elementId))
        {
            Console.WriteLine("Invalid Page Section ID or Element ID.");
            return;
        }

        // Create a unique key for caching based on section and element IDs
        string cacheKey = $"{pageSectionId}:{elementId}";

        object lockObj;
        if (!LockTable.TryGetValue(cacheKey, out lockObj))
        {
            lockObj = new object();
            LockTable[cacheKey] = lockObj;
        }

        lock (lockObj)
        {
            try
            {
                // Serialize the HTML content to a byte array for caching.
                var serializedContent = System.Text.Encoding.UTF8.GetBytes(htmlContent);

                // Set cache options with an absolute expiration time, adjust as needed
                var cacheEntryOptions = new DistributedCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromMinutes(5))
                    .SetAbsoluteExpiration(TimeSpan.FromHours(1));

                _cache.Set(cacheKey, serializedContent, cacheEntryOptions);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating page element: {ex.Message}");
            }
        }
    }
}

// Usage example:
// var updater = new PageElementUpdater(yourCacheInstance);
// updater.UpdatePageElement("header", "title", "<h1>New Title</h1>");
