```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_BANDWIDTH 10000 // Example maximum bandwidth
#define LATENCY_THRESHOLD 200 // Example latency threshold in ms

typedef struct {
    int value;
} RECORD_T;

typedef struct {
    int CONNECTION_ID;
    char REMOTE_ADDRESS[50];
    char LOCAL_ADDRESS[50];
    int CURRENT_BANDWIDTH;
    int LATENCY;
    RECORD_T record;
} TCP_CONNECTION_INFO_T;

typedef struct {
    TCP_CONNECTION_INFO_T* connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CONNECTION_POOL_T;

CONNECTION_POOL_T connection_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_random() {
    srand((unsigned)time(NULL));
}

int random_within_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void* create_connection(void* arg) {
    int connection_id = *(int*)arg;

    pthread_mutex_lock(&connection_pool.lock);

    if (connection_pool.count >= connection_pool.capacity) {
        // Double the capacity
        size_t new_capacity = connection_pool.capacity * 2 ? connection_pool.capacity * 2 : 1;
        TCP_CONNECTION_INFO_T* new_connections = realloc(connection_pool.connections, new_capacity * sizeof(TCP_CONNECTION_INFO_T));

        if (new_connections == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&connection_pool.lock);
            return NULL;
        }

        connection_pool.connections = new_connections;
        connection_pool.capacity = new_capacity;
    }

    TCP_CONNECTION_INFO_T* conn_info = &connection_pool.connections[connection_pool.count++];
    conn_info->CONNECTION_ID = connection_id;
    snprintf(conn_info->REMOTE_ADDRESS, sizeof(conn_info->REMOTE_ADDRESS), "192.168.1.%d", random_within_range(1, 255));
    snprintf(conn_info->LOCAL_ADDRESS, sizeof(conn_info->LOCAL_ADDRESS), "10.0.0.%d", random_within_range(1, 255));
    conn_info->CURRENT_BANDWIDTH = random_within_range(100, MAX_BANDWIDTH);
    conn_info->LATENCY = random_within_range(50, LATENCY_THRESHOLD);
    conn_info->record.value = random_within_range(1, 10);

    pthread_mutex_unlock(&connection_pool.lock);

    // Simulate handling network anomalies
    if (conn_info->CURRENT_BANDWIDTH < 500 || conn_info->LATENCY > LATENCY_THRESHOLD) {
        printf("Anomaly detected on connection %d: BW=%d, Latency=%d\n", conn_info->CONNECTION_ID,
               conn_info->CURRENT_BANDWIDTH, conn_info->LATENCY);
        // Handle anomaly (e.g., re-establish connection)
    }

    return NULL;
}

void initialize_connection_pool(size_t max_connections) {
    pthread_mutex_lock(&connection_pool.lock);

    if (connection_pool.connections != NULL) {
        free(connection_pool.connections);
        connection_pool.connections = NULL;
    }

    connection_pool.capacity = max_connections;
    connection_pool.count = 0;

    if (max_connections > 0) {
        connection_pool.connections = malloc(max_connections * sizeof(TCP_CONNECTION_INFO_T));
        if (connection_pool.connections == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&connection_pool.lock);
            return;
        }
    }

    pthread_mutex_unlock(&connection_pool.lock);

    for (size_t i = 0; i < connection_pool.capacity; ++i) {
        int* conn_id = malloc(sizeof(int));
        if (conn_id == NULL) {
            perror("Failed to allocate memory");
            continue;
        }
        *conn_id = i + 1;

        pthread_t thread;
        pthread_create(&thread, NULL, create_connection, conn_id);
        pthread_detach(thread);
    }
}

void cleanup_connection_pool() {
    pthread_mutex_lock(&connection_pool.lock);

    if (connection_pool.connections != NULL) {
        free(connection_pool.connections);
        connection_pool.connections = NULL;
    }

    connection_pool.capacity = 0;
    connection_pool.count = 0;

    pthread_mutex_unlock(&connection_pool.lock);
}

int main(int argc, char* argv[]) {
    size_t max_connections = 10; // Example configuration

    initialize_random();
    initialize_connection_pool(max_connections);

    // Simulate running for a while
    sleep(5);

    cleanup_connection_pool();

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutex locks are used to ensure thread safety when accessing and modifying the connection pool.
- **Dynamic Scaling**: The pool can grow dynamically by reallocating memory as needed.
- **Random Initialization**: Each `RECORD_T` value is initialized with a random number within a specified range.
- **Anomaly Detection**: Basic anomaly detection based on bandwidth and latency thresholds is implemented.
- **Resource Management**: Memory allocation and deallocation are carefully handled to prevent leaks.

This code provides a basic framework for managing TCP connections in a high-performance streaming application, considering thread safety and dynamic scaling. Adjustments can be made based on specific requirements or constraints of the larger network management framework.']

