#include <string.h>

#define MAX_MEMORY_THRESHOLD 1024 * 1024 // Example threshold

typedef struct RX_UE_SIGNAL_STRENGTH_REPORT {
    int signalStrength;
} RX_UE_SIGNAL_STRENGTH_REPORT;

typedef struct RX_UE_CHANNEL_QUALITY_INDICATOR {
