    RX_UE_SIGNAL_STRENGTH_REPORT signalReport;
    RX_UE_CHANNEL_QUALITY_INDICATOR channelQualityIndicator;
    TX_POWER_COMMAND *txPowerCommand; // Optional
    struct NFAPI_MESSAGE_T *next;
} NFAPI_MESSAGE_T;

// Memory pool for efficient memory management
#define POOL_SIZE 100
NFAPI_MESSAGE_T memoryPool[POOL_SIZE];
int freeIndex = 0;

void* allocateMemory(size_t size) {
    if (freeIndex < POOL_SIZE) {
        return &memoryPool[freeIndex++];
    }
    // Handle out-of-memory situation
    fprintf(stderr, "Out of memory\n");
    return NULL;
}

NFAPI_MESSAGE_T* initializeNFADWithConstraints(int numUEs, int includePowerCommands) {
    if (numUEs <= 0) {
        fprintf(stderr, "Invalid number of UEs\n");
        return NULL;
    }

    NFAPI_MESSAGE_T *head = NULL, *tail = NULL;

    for (int i = 0; i < numUEs; ++i) {
        NFAPI_MESSAGE_T *newNode = (NFAPI_MESSAGE_T*)allocateMemory(sizeof(NFAPI_MESSAGE_T));
        if (!newNode) return head;

        // Populate with dummy data or fetch from external source
        newNode->signalReport.signalStrength = rand() % 100;
        newNode->channelQualityIndicator.channelQuality = (float)(rand() % 100) / 10.0f;

        if (includePowerCommands) {
            newNode->txPowerCommand = (TX_POWER_COMMAND*)allocateMemory(sizeof(TX_POWER_COMMAND));
            if (!newNode->txPowerCommand) return head;
            newNode->txPowerCommand->powerLevel = rand() % 31; // Example power level
        } else {
            newNode->txPowerCommand = NULL;
        }

        newNode->next = NULL;

        if (tail) {
            tail->next = newNode;
        } else {
            head = newNode;
        }
        tail = newNode;
    }

    return head;
}

