function processStringWithConstraints(inputString, sizeLimit, maxMemoryThreshold) {
    if (!inputString || typeof inputString !== 'string') {
        console.error("Invalid input");
        return null;
    }

    const currentMemoryUsage = process.memoryUsage().heapUsed;

    if (currentMemoryUsage > maxMemoryThreshold) {
        console.error("Memory threshold exceeded");
        return null;
    }

    if (inputString.length <= sizeLimit) {
        try {
            // Allocate a new string with a hyphen appended
            const result = inputString + '-';
            return result;
        } catch (error) {
            console.error("Error during memory allocation", error);
            return null;
        }
    }

    return null;
}
