NFAPI_CRC_INDICATION_PDU_T* createNfadWithConstraints(int N, size_t maxMemory) {
    if (N <= 0 || maxMemory == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    size_t memoryAllocated = 0;

    for (int i = 0; i < N; ++i) {
        // Calculate the required memory
        size_t structureSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (memoryAllocated + structureSize > maxMemory) break;

        NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*) malloc(structureSize);

        if (!newNode) {
            // Free previously allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
