    int macEntityID;
    DL_FRAME* dlFrameRef;
    MAC_SERVICE_DATA_UNIT** sdus;
    int sduCount;
} MAC_ECONTEXT;

MAC_ECONTEXT* macContextArray[MAX_MAC_CONTEXTS] = {NULL};
int currentContextCount = 0;

void initializeRandom() {
    srand(time(NULL));
}

int allocateMacEcontext(int macEntityID, DL_FRAME* dlFrameRef, int sduCount) {
    if (currentContextCount >= MAX_MAC_CONTEXTS || sduCount > MAX_SDUS) return -1;

    MAC_ECONTEXT* newContext = (MAC_ECONTEXT*)malloc(sizeof(MAC_ECONTEXT));
    if (!newContext) return -1;

    newContext->macEntityID = macEntityID;
    newContext->dlFrameRef = dlFrameRef;
    newContext->sdus = (MAC_SERVICE_DATA_UNIT**)malloc(sduCount * sizeof(MAC_SERVICE_DATA_UNIT*));
    if (!newContext->sdus) {
        free(newContext);
        return -1;
    }

    for (int i = 0; i < sduCount; ++i) {
        newContext->sdus[i] = (MAC_SERVICE_DATA_UNIT*)malloc(sizeof(MAC_SERVICE_DATA_UNIT));
        if (!newContext->sdus[i]) {
            while (i-- > 0) free(newContext->sdus[i]);
            free(newContext->sdus);
            free(newContext);
            return -1;
        }

        // Populate SDU with random data
        for (int j = 0; j < 10; ++j) {
            newContext->sdus[i]->data[j] = rand() % 100;
        }
    }

    newContext->sduCount = sduCount;

    macContextArray[currentContextCount++] = newContext;
    return 0;
}

void freeMacEcontext(int index) {
    if (index < 0 || index >= currentContextCount || !macContextArray[index]) return;

    MAC_ECONTEXT* context = macContextArray[index];

    for (int i = 0; i < context->sduCount; ++i) {
        free(context->sdus[i]);
    }

    free(context->sdus);
    free(context);

    macContextArray[index] = NULL;
}

void bulkDeleteMacEcontext() {
    for (int i = 0; i < currentContextCount; ++i) {
        if (macContextArray[i]) {
            freeMacEcontext(i);
        }
    }

    currentContextCount = 0;
}

int main() {
    initializeRandom();

    DL_FRAME frame = {1};

    // Example of allocating and managing MAC_ECONTEXT instances
    allocateMacEcontext(1, &frame, 5);
    allocateMacEcontext(2, &frame, 10);

    // Bulk delete all contexts
    bulkDeleteMacEcontext();

    return 0;
}
