#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS 10000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int execute_command(const char* command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return 0;
    }

    if (pid == 0) { // Child process
        execlp(command, command, NULL);
        exit(EXIT_FAILURE); // If execlp returns, it must have failed.
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);

        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }
}

int createNfareport(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t count, const char* command) {
    if (count > MAX_STRUCTS) {
        fprintf(stderr, "Exceeded maximum structure limit.\n");
        return 0;
    }

    int success = execute_command(command);

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < count; ++i) {
        pdu_list[i].ue_info_tag.RNTI = rand() % 100000; // Simulating valid RNTI generation
        if (success) {
            pdu_list[i].crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG set
        }
    }

    pthread_mutex_unlock(&lock);

    return success ? 1 : 0;
}

// Example usage: 
// NFAPI_CRC_INDICATION_PDU_T pdus[MAX_STRUCTS];
