import threading
from typing import Optional

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    float SNR_INDICATION_REL8_TAG; // Signal-to-Noise Ratio
} NFAPI_MESSAGE_PDU_T;

class DynamicArray:
    def __init__(self, initial_capacity=10):
        self.capacity = initial_capacity
        self.size = 0
        self.lock = threading.Lock()

        # Allocate memory for the array
        self.array = [None] * self.capacity

    def _resize(self):
        new_capacity = self.capacity * 2
        new_array = [None] * new_capacity

        for i in range(self.size):
            new_array[i] = self.array[i]

        self.array = new_array
        self.capacity = new_capacity

    def add_ue(self, rx_UE_INFORMATION_TAG: int, rnti: int) -> Optional[NFAPI_MESSAGE_PDU_T]:
        with self.lock:
            if self.size == self.capacity:
                # Try to resize the array
                try:
                    self._resize()
                except MemoryError:
                    print("Failed to allocate more memory.")
                    return None

            # Simulate SNR value computation using a random factor
            import random
            snr = random.uniform(-5.0, 10.0)  # Example range for SNR in dB

            ue_pdu = NFAPI_MESSAGE_PDU_T(
                RX_UE_INFORMATION_TAG=rx_UE_INFORMATION_TAG,
                RNTI=rnti,
                CRC_INDICATION_REL8_TAG=1 if random.random() > 0.1 else 0,  # Simulate CRC indication
                SNR_INDICATION_REL8_TAG=snr
            )

            self.array[self.size] = ue_pdu
            self.size += 1

            return ue_pdu

    def get_ue(self, index: int) -> Optional[NFAPI_MESSAGE_PDU_T]:
        with self.lock:
            if 0 <= index < self.size:
                return self.array[index]
            else:
                print("Index out of bounds.")
                return None

# Example usage
