// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to handle cleanup on signal interruption or error
void handle_cleanup(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

// Function to execute a background command using fork and wait
int execute_background_command(const char *command) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        execlp(command, command, (char *)NULL);
        exit(EXIT_FAILURE); // If execlp fails
    } else if (pid > 0) { // Parent process
        int status;
        wait(&status);
        return WIFEXITED(status) && !WEXITSTATUS(status);
    } else {
        return 0; // Fork failed
    }
}

// Function to generate NFA reports
int generateNfaReports(size_t N, NFAPI_CRC_INDICATION_PDU_T **reports) {
    if (N == 0) {
        *reports = NULL;
        return 1;
    }

    pthread_mutex_lock(&lock);

    // Allocate memory for N structures
    *reports = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*reports == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        handle_cleanup(*reports);
        pthread_mutex_unlock(&lock);
        return 0;
    }

    const char *background_command = "/bin/true"; // Replace with actual command

    int success = execute_background_command(background_command);

    for (size_t i = 0; i < N; ++i) {
        (*reports)[i].RX_UE_INFORMATION_TAG = VALID_RX_UE_INFORMATION_TAG;
        (*reports)[i].RNTI = VALID_RNTI;
        // Assume CRC_INDICATION_REL8_TAG is derived from index or similar
        (*reports)[i].CRC_INDICATION_REL8_TAG = i + 1;

        if (success) {
            (*reports)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        } else {
            (*reports)[i].CRCFLAG = -1; // Unset flag on failure
        }
    }

    pthread_mutex_unlock(&lock);

    return success;
}

// Example usage and signal handling setup
void sigint_handler(int signum) {
    fprintf(stderr, "Interrupt received! Cleaning up...\n");
    handle_cleanup(NULL);  // Add actual cleanup logic if needed
    exit(signum);
}

int main() {
    size_t N = 10;  // Number of reports to generate
    NFAPI_CRC_INDICATION_PDU_T *reports;

    signal(SIGINT, sigint_handler);

    int result = generateNfaReports(N, &reports);
    if (result) {
        printf("Generated %zu reports successfully.\n", N);
    } else {
        fprintf(stderr, "Failed to generate reports.\n");
    }

    handle_cleanup(reports);
    return 0;
}
