This implementation balances performance with error handling and resource management while ensuring thread safety in a multi-threaded environment.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_T;

#define MAX_LOG_LEVEL 3

typedef struct MessageNode {
    NFAPI_MESSAGE_T message;
    struct MessageNode* next;
} MessageNode;

typedef struct {
    MessageNode* head;
    size_t count;
    pthread_mutex_t lock;
    int max_size;
    FILE* log_file;
    int log_level;
} MessageArray;

// Function prototypes
MessageArray* init_message_array(size_t max_size, const char* log_filename, int log_level);
int add_or_update_message(MessageArray* array, int index, NFAPI_MESSAGE_T message);
void process_messages(MessageArray* array, void (*process_func)(NFAPI_MESSAGE_T));
void free_message_array(MessageArray* array);

// Helper functions
static void log_message(const char* format, ...) {
    if (!array->log_file || array->log_level == 0) return;

    va_list args;
    va_start(args, format);
    vfprintf(array->log_file, format, args);
    va_end(args);
}

MessageArray* init_message_array(size_t max_size, const char* log_filename, int log_level) {
    MessageArray* array = (MessageArray*)malloc(sizeof(MessageArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->head = NULL;
    array->count = 0;
    array->max_size = max_size;

    if (log_filename && log_level > 0) {
        array->log_file = fopen(log_filename, "a");
        if (!array->log_file) {
            free(array);
            return NULL;
        }
    } else {
        array->log_file = NULL;
    }

    array->log_level = log_level > MAX_LOG_LEVEL ? MAX_LOG_LEVEL : log_level;

    log_message("Initialized message array with max size %zu\n", max_size);

    return array;
}

int add_or_update_message(MessageArray* array, int index, NFAPI_MESSAGE_T message) {
    if (index < 0 || index >= (int)array->max_size) {
        log_message("Error: Index out of bounds [%d]\n", index);
        return -1;
    }

    pthread_mutex_lock(&array->lock);

    MessageNode* current = array->head;
    MessageNode* prev = NULL;

    int i = 0;
    while (current && i < index) {
        prev = current;
        current = current->next;
        i++;
    }

    if (i == index) { // Update existing
        current->message = message;
        log_message("Updated message at index %d\n", index);
    } else { // Add new
        if (array->count >= array->max_size) {
            pthread_mutex_unlock(&array->lock);
            log_message("Error: Maximum size reached [%zu]\n", array->max_size);
            return -1;
        }

        MessageNode* node = (MessageNode*)malloc(sizeof(MessageNode));
        if (!node) {
            pthread_mutex_unlock(&array->lock);
            log_message("Error: Memory allocation failed\n");
            return -1;
        }

        node->message = message;
        node->next = current;

        if (prev) {
            prev->next = node;
        } else {
            array->head = node;
        }

        array->count++;
        log_message("Added new message at index %d\n", index);
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void process_messages(MessageArray* array, void (*process_func)(NFAPI_MESSAGE_T)) {
    if (!process_func) return;

    pthread_mutex_lock(&array->lock);

    MessageNode* current = array->head;
    while (current) {
        process_func(current->message);
        current = current->next;
    }

    pthread_mutex_unlock(&array->lock);
}

void free_message_array(MessageArray* array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    MessageNode* current = array->head;
    while (current) {
        MessageNode* next = current->next;
        free(current);
        current = next;
    }

    array->head = NULL;
    array->count = 0;

    if (array->log_file) {
        fclose(array->log_file);
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);

    log_message("Freed message array\n");

    free(array);
}

// Example process function
void print_message(NFAPI_MESSAGE_T msg) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           msg.RX_UE_INFORMATION_TAG, msg.RNTI, msg.CRC_INDICATION_REL8_TAG);
}

// Example usage
int main() {
    MessageArray* array = init_message_array(10000, "log.txt", 1);

    NFAPI_MESSAGE_T msg = {1, 1234, 5678};
    add_or_update_message(array, 0, msg);

    process_messages(array, print_message);

    free_message_array(array);
    return 0;
}
```']

