// Define structure types
typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a random number for CRCFLAG
uint16_t getRandomCRCFlag() {
    return rand() % 2; // Randomly set to 0 or 1
}

// Thread-safe queue implementation
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} Queue;

void initQueue(Queue* q) {
    q->head = NULL;
    q->tail = NULL;
    pthread_mutex_init(&q->mutex, NULL);
}

int enqueue(Queue* q, NFAPI_CRC_INDICATION_PDU_T item) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Error handling for memory allocation

    newNode->data = item;
    newNode->next = NULL;

    pthread_mutex_lock(&q->mutex);
    if (!q->tail) {
        q->head = q->tail = newNode;
    } else {
        q->tail->next = newNode;
        q->tail = newNode;
    }
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int dequeue(Queue* q, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&q->mutex);
    if (!q->head) {
        pthread_mutex_unlock(&q->mutex);
        return -1; // Queue is empty
    }

    Node* temp = q->head;
    *item = q->head->data;
    q->head = q->head->next;

    if (!q->head)
        q->tail = NULL;

    free(temp);
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

// Function to generate NFAPI structures
void* structureGenerator(void* arg) {
    Queue* queue = (Queue*)arg;
    while (1) { // In a real scenario, this should check for termination condition
        struct sysinfo info;
        sysinfo(&info);

        int availableMemory = info.freeram; // Example metric

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Random example value
        pdu.RNTI = rand() % 500; // Random example value
        pdu.crcTag.CRCFLAG = getRandomCRCFlag();

        enqueue(queue, pdu);

        time_t current_time;
        time(&current_time);
        struct tm *local_time = localtime(&current_time);

        printf("Generated at %02d:%02d:%02d - RX_UE: %d RNTI: %d CRCFLAG: %u\n",
               local_time->tm_hour, local_time->tm_min, local_time->tm_sec,
               pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.crcTag.CRCFLAG);

        time_t next_run = current_time + 1; // Sleep until next second
        while (time(NULL) < next_run) {
            sched_yield(); // Allow other threads to run
        }
    }
}

// Function to serialize NFAPI structure into binary format
size_t serialize(NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t** buffer) {
    *buffer = (uint8_t*)malloc(sizeof(*pdu));
    if (!*buffer) return 0; // Error handling for memory allocation

    memcpy(*buffer, pdu, sizeof(*pdu));
    return sizeof(*pdu);
}

// Function to deserialize binary format back into NFAPI structure
void deserialize(NFAPI_CRC_INDICATION_PDU_T* pdu, const uint8_t* buffer) {
    if (buffer && pdu) {
        memcpy(pdu, buffer, sizeof(*pdu));
    }
}

// Main function integrating all components
int main() {
    Queue queue;
    initQueue(&queue);

    pthread_t generator_thread;
    pthread_create(&generator_thread, NULL, structureGenerator, &queue);

    // Example loop for processing dequeued items
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        if (dequeue(&queue, &pdu) == 0) {
            uint8_t* buffer = NULL;
            size_t size = serialize(&pdu, &buffer);

            // Simulate processing of serialized data
            deserialize(&pdu, buffer);
            printf("Processed RX_UE: %d RNTI: %d CRCFLAG: %u\n",
                   pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.crcTag.CRCFLAG);

            free(buffer); // Clean up allocated memory
        }

        sched_yield(); // Yield CPU time to other threads/processes
    }

    pthread_join(generator_thread, NULL);
    return 0;
}
