```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* createNfadWithConstraints(int max_memory, int num_elements) {
    if (max_memory <= 0 || num_elements <= 0) return NULL;

    Node* head = NULL;
    Node** current = &head;
    srand(time(NULL));

    while (*current && (sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_elements - 1)) < max_memory) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) break;

        NFAPI_CRC_INDICATION_PDU_T* pdu = &newNode->data;
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        pdu->RNTI = rand() % 5000; // Example value
        pdu->CRC_INDICATION_REL8_TAG = rand() % 10; // Example value
        pdu->CRCFLAG = rand() % 2;

        newNode->next = NULL;
        *current = newNode;
        current = &newNode->next;
        num_elements--;
    }

    return head;
}

void freeNfad(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
