int execute_background_command() {
    pid_t pid = fork();
    if (pid < 0) {
        log_error("Fork failed.");
        return -1;
    } else if (pid == 0) {
        // Background command simulation
        sleep(2); // Simulate some work being done in the background
        exit(EXIT_SUCCESS);
    }

    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status) && WEXITSTATUS(status) == EXIT_SUCCESS) {
        return 1; // Command succeeded
    } else {
        log_error("Background command failed or was interrupted.");
        return -1; // Command failed or interrupted
    }
}

void handle_sigint(int sig) {
    static volatile int exit_flag = 0;
    if (sig == SIGINT && !exit_flag) {
        exit_flag = 1;
    } else if (exit_flag) {
        raise(SIGTERM); // Trigger termination on subsequent signals
    }
}

int generateNFAResults(NFAPI_CRC_INDICATION_PDU_T **result, int N) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    if (N <= 0) {
        log_error("Invalid number of elements requested.");
        return 0;
    }

    *result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*result) {
        log_error("Memory allocation failed.");
        return 0;
    }

    for (int i = 0; i < N; ++i) {
        (*result)[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        (*result)[i].RNTI = rand() % 500 + 1;
        (*result)[i].CRC_INDICATION_REL8_TAG = rand() % 10;

        int command_result = execute_background_command();
        if (command_result > 0) {
            // Simulate probabilistic CRCFLAG assignment
            (*result)[i].CRCFLAG = rand() % 2; // 50% chance to be set or unset
        }
    }

    return 1;
}

