             (type == 0 ? "CRC_INDICATION" : "CELLULAR_EVENT"),
             node->data.crc_indication.RNTI,
             node->data.crc_indication.RX_UE_INFORMATION_TAG);
    log_message(log_buf);

    return node;
}

void add_to_list(Node** head, int type, int valid_event_type) {
    Node* new_node = create_node(type, valid_event_type);
    if (!new_node) return;

    pthread_mutex_lock(&list_mutex);

    // Append to the end of list
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void initialize_list(int N, int M, const int* event_types) {
    Node* head = NULL;

    for (int i = 0; i < N; ++i) {
        add_to_list(&head, 0, -1); // Type 0 for CRC
    }

    for (int i = 0; i < M; ++i) {
        if (event_types[i] >= EVENT_TYPE_1 && event_types[i] <= EVENT_TYPE_3) {
            add_to_list(&head, 1, event_types[i]); // Type 1 for Cellular Event
        } else {
            log_message("Skipping invalid event type.");
        }
    }

    // List cleanup would be done here if necessary (not shown)
}

