} CRC_INDICATION_REL8_TAG;

typedef struct {
    time_t timestamp;
    int eventType;
} CELLULAR_EVENT_REL8_TAG;

typedef enum { CRC_INDICATION, CELLULAR_EVENT } PDU_TYPE;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
    PDU_TYPE type;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CELLULAR_EVENT_PDU_T {
    RX_UE_INFORMATION_TAG rxInfoTag;
    RNTI rnti;
    CELLULAR_EVENT_REL8_TAG cellularEvent;
    PDU_TYPE type;
} NFAPI_CELLULAR_EVENT_PDU_T;

typedef union {
    NFAPI_CRC_INDICATION_PDU_T crcIndicationPdu;
    NFAPI_CELLULAR_EVENT_PDU_T cellularEventPdu;
} PDU_Union;

typedef struct Node {
    PDU_Union pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

typedef struct {
    Node** array;
    int size;
    int capacity;
    pthread_rwlock_t rwlock;
} PriorityQ;

const char* validEventTypes[MAX_VALID_EVENT_TYPES] = {"EVENT_TYPE_1", "EVENT_TYPE_2", "EVENT_TYPE_3", "EVENT_TYPE_4", "EVENT_TYPE_5"};
DynamicList list = {NULL, PTHREAD_MUTEX_INITIALIZER};
PriorityQ priorityQ = {NULL, 0, 10, PTHREAD_RWLOCK_INITIALIZER};

int validateEventType(const char* eventType) {
    for (int i = 0; i < MAX_VALID_EVENT_TYPES; ++i) {
        if (strcmp(eventType, validEventTypes[i]) == 0)
            return 1;
    }
    return 0;
}

void logMessage(const char* message) {
    FILE* file = fopen("log.txt", "a");
    if (file) {
        time_t now = time(NULL);
        fprintf(file, "%s: %s\n", ctime(&now), message);
        fclose(file);
    }
}

Node* createNode(PDU_TYPE type, int validRnti, int rnti, const char* eventType, int crcFlag) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    switch (type) {
        case CRC_INDICATION:
            node->pdu.crcIndicationPdu.rxInfoTag.valid = 1;
            node->pdu.crcIndicationPdu.rnti.rnti = rnti;
            node->pdu.crcIndicationPdu.timestamp = time(NULL);
            node->pdu.crcIndicationPdu.crcIndication.crcFlag = crcFlag;
            break;
        case CELLULAR_EVENT:
            if (!validateEventType(eventType)) {
                logMessage("Invalid event type encountered");
                free(node);
                return NULL;
            }
            node->pdu.cellularEventPdu.rxInfoTag.valid = 1;
            node->pdu.cellularEventPdu.rnti.rnti = rnti;
            node->pdu.cellularEventPdu.timestamp = time(NULL);
            node->pdu.cellularEventPdu.cellularEvent.eventType = atoi(eventType);
            break;
    }
    node->next = NULL;
    return node;
}

void addNodeToPriorityQ(Node* node) {
    pthread_rwlock_wrlock(&priorityQ.rwlock);

    if (priorityQ.size == priorityQ.capacity) {
        Node** tempArray = (Node**)realloc(priorityQ.array, sizeof(Node*) * (priorityQ.capacity + 10));
        if (!tempArray) return;
        priorityQ.array = tempArray;
        priorityQ.capacity += 10;
    }

    priorityQ.array[priorityQ.size++] = node;

    pthread_rwlock_unlock(&priorityQ.rwlock);
}

void manageDynamicList(int N, int M) {
    srand(time(NULL));
    Node* newNode = NULL;
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&list.lock);

        newNode = createNode(CRC_INDICATION, 1, rand() % 10000, NULL, rand() % 2);
        if (!newNode) continue;

        newNode->next = list.head;
        list.head = newNode;

        addNodeToPriorityQ(newNode);

        pthread_mutex_unlock(&list.lock);

        logMessage("Created CRC_INDICATION structure");
    }

    for (int i = 0; i < M; ++i) {
        pthread_mutex_lock(&list.lock);

        char eventType[20];
        snprintf(eventType, sizeof(eventType), "EVENT_TYPE_%d", rand() % MAX_VALID_EVENT_TYPES + 1);

        newNode = createNode(CELLULAR_EVENT, 1, rand() % 10000, eventType, -1);
        if (!newNode) continue;

        newNode->next = list.head;
        list.head = newNode;

        addNodeToPriorityQ(newNode);

        pthread_mutex_unlock(&list.lock);

        logMessage("Created CELLULAR_EVENT structure");
    }
}

void cleanup() {
    pthread_rwlock_wrlock(&priorityQ.rwlock);
    Node* current = NULL, *next = NULL;

    for (int i = 0; i < priorityQ.size; ++i) {
        current = priorityQ.array[i];
        if (!current) continue;

        next = current->next;
        free(current);

        current = next;
    }

    pthread_rwlock_unlock(&priorityQ.rwlock);

    current = list.head;
    while (current) {
        Node* toFree = current;
        current = current->next;
        free(toFree);
    }
}

int main() {
    manageDynamicList(10, 5);
    cleanup();
    return 0;
}
