// Function to safely add a record
void add_record(RecordList *list, Record record) {
    pthread_rwlock_wrlock(&list->lock);

    if (list->count == 0 || list->records[list->count - 1].offset != record.offset) {
        // Find free space or append new record
        for (size_t i = 0; i < list->count; ++i) {
            if (list->records[i].offset == record.offset) {
                list->records[i] = record;
                break;
            }
