void update_records(RecordList *list, Record new_record) {
    pthread_rwlock_wrlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i].offset == new_record.offset) {
            list->records[i] = new_record;
            break;
        }
    }

    pthread_rwlock_unlock(&list->lock);
}

// Function to clean up resources
void cleanup() {
    free(crc_list.records);
    free(cellular_event_list.records);

    pthread_rwlock_destroy(&crc_list.lock);
    pthread_rwlock_destroy(&cellular_event_list.lock);
}

// Logging function for debugging and error handling
void log_message(const char *message) {
    fprintf(stderr, "Log: %s\n", message);
}

int main() {
    size_t N = 100; // Example number of CRC indications
    size_t M = 50;  // Example number of cellular events

