    int value, seen[101] = {0}; // Assuming range is [0, 100]

    char *token = strtok(buffer, " ");
    while (token) {
        if (sscanf(token, "%d", &value) == 1 && value >= 0 && value <= 100 && !seen[value]) {
            array[(*size)++] = value;
            seen[value] = 1;
        }
        token = strtok(NULL, " ");
    }
}

int findLargestInteger(const int *array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

