#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int cell_id;
    float signal_strength;
} CellReport;

typedef struct {
    int serving_cell_id;
    CellReport* neighbor_cells;
    size_t num_neighbors;
    size_t capacity_neighbors;
    float avg_signal_strength;
} LTE_RRC_MESUREMENT_REPORT_T;

// Initialize a dynamic array of measurement reports
LTE_RRC_MESUREMENT_REPORT_T* init_measurement_reports(size_t initial_capacity) {
    if (initial_capacity == 0) {
        initial_capacity = INITIAL_CAPACITY;
    }

    LTE_RRC_MESUREMENT_REPORT_T* reports = malloc(initial_capacity * sizeof(LTE_RRC_MESUREMENT_REPORT_T));
    if (!reports) {
        perror("Failed to allocate memory for measurement reports");
        return NULL;
    }

    memset(reports, 0, initial_capacity * sizeof(LTE_RRC_MESUREMENT_REPORT_T));

    return reports;
}

// Resize the dynamic array of measurement reports
int resize_measurement_reports(LTE_RRC_MESUREMENT_REPORT_T** reports, size_t new_capacity) {
    if (!*reports || new_capacity == 0) {
        return -1;
    }

    LTE_RRC_MESUREMENT_REPORT_T* resized = realloc(*reports, new_capacity * sizeof(LTE_RRC_MESUREMENT_REPORT_T));
    if (!resized) {
        perror("Failed to reallocate memory for measurement reports");
        return -1;
    }

    *reports = resized;
    memset((*reports + (*reports)->num_neighbors), 0, (new_capacity - (*reports)->num_neighbors) * sizeof(LTE_RRC_MESUREMENT_REPORT_T));

    for (size_t i = 0; i < new_capacity; ++i) {
        if ((*reports)[i].neighbor_cells) {
            // Resize the neighbors array
            size_t current_capacity = (*reports)[i].capacity_neighbors;
            CellReport* resized_neighbors = realloc((*reports)[i].neighbor_cells, new_capacity * sizeof(CellReport));
            if (!resized_neighbors && new_capacity > current_capacity) {
                perror("Failed to reallocate memory for neighbor cells");
                return -1;
            }

            (*reports)[i].capacity_neighbors = new_capacity;
            (*reports)[i].neighbor_cells = resized_neighbors;

            // Initialize newly allocated space
            memset((*reports)[i].neighbor_cells + current_capacity, 0,
                   (new_capacity - current_capacity) * sizeof(CellReport));
        }
    }

    return 0;
}

// Add a measurement report to the dynamic array
int add_measurement_report(LTE_RRC_MESUREMENT_REPORT_T** reports, size_t* num_reports,
                           int serving_cell_id, int neighbor_cell_ids[], float signal_strengths[], size_t num_neighbors) {
    if (!reports || !num_reports || !neighbor_cell_ids || !signal_strengths) {
        return -1;
    }

    *reports = realloc(*reports, (*num_reports + 1) * sizeof(LTE_RRC_MESUREMENT_REPORT_T));
    if (!*reports) {
        perror("Failed to reallocate memory for adding a new report");
        return -1;
    }

    LTE_RRC_MESUREMENT_REPORT_T* new_report = &(*reports)[*num_reports];
    memset(new_report, 0, sizeof(LTE_RRC_MESUREMENT_REPORT_T));

    new_report->serving_cell_id = serving_cell_id;
    new_report->neighbor_cells = malloc(num_neighbors * sizeof(CellReport));
    if (!new_report->neighbor_cells) {
        perror("Failed to allocate memory for neighbor cells");
        return -1;
    }

    new_report->num_neighbors = num_neighbors;
    new_report->capacity_neighbors = num_neighbors;

    for (size_t i = 0; i < num_neighbors; ++i) {
        new_report->neighbor_cells[i].cell_id = neighbor_cell_ids[i];
        new_report->neighbor_cells[i].signal_strength = signal_strengths[i];
    }

    // Update average signal strength
    float total_signal_strength = signal_strengths[0];
    for (size_t i = 1; i < num_neighbors; ++i) {
        total_signal_strength += signal_strengths[i];
    }

    new_report->avg_signal_strength = total_signal_strength / num_neighbors;

    (*num_reports)++;
    return 0;
}

// Retrieve average signal strength for a specific cell
float get_avg_signal_strength(LTE_RRC_MESUREMENT_REPORT_T* reports, size_t num_reports, int cell_id) {
    float avg_signal_strength = -1.0f; // Indicate not found by default

    for (size_t i = 0; i < num_reports; ++i) {
        if (reports[i].serving_cell_id == cell_id) {
            return reports[i].avg_signal_strength;
        }

        for (size_t j = 0; j < reports[i].num_neighbors; ++j) {
            if (reports[i].neighbor_cells[j].cell_id == cell_id) {
                avg_signal_strength = reports[i].neighbor_cells[j].signal_strength;
                break;
            }
        }
    }

    return avg_signal_strength;
}

// Free the dynamically allocated memory
void free_measurement_reports(LTE_RRC_MESUREMENT_REPORT_T* reports, size_t num_reports) {
    for (size_t i = 0; i < num_reports; ++i) {
        if (reports[i].neighbor_cells) {
            free(reports[i].neighbor_cells);
        }
    }

    free(reports);
}

int main() {
    // Example usage
    size_t num_reports = 0;
    LTE_RRC_MESUREMENT_REPORT_T* reports = init_measurement_reports(INITIAL_CAPACITY);

    int neighbor_ids[] = {101, 102};
    float signal_strengths[] = { -50.5f, -55.2f };

    add_measurement_report(&reports, &num_reports, 1, neighbor_ids, signal_strengths, 2);

    printf("Average Signal Strength for Cell 1: %.2f\n", get_avg_signal_strength(reports, num_reports, 1));
    printf("Signal Strength for Neighbor Cell 101: %.2f\n", get_avg_signal_strength(reports, num_reports, 101));

    free_measurement_reports(reports, num_reports);

    return 0;
}
```

