#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define LOG_ALLOC(ptr) printf("Allocated at %p\n", ptr)
#define LOG_FREE(ptr)  printf("Freed at %p\n", ptr)

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct record {
    int value;
    long *offset;
    int *key;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int get_random(unsigned int min, unsigned int max) {
    return min + rand() % (max - min + 1);
}

int init_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, unsigned int seed) {
    if (!pdu) return -1;
    srand(seed);
    pdu->RX_UE_INFORMATION_TAG = get_random(0, 100000);
    pdu->RNTI = get_random(0, 50000);
    pdu->CRC_INDICATION_REL8_TAG = (unsigned short)get_random(0, 255);
    pdu->CRCFLAG = rand() % 2;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_crc_pdu_array(size_t size, unsigned int seed) {
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    if (size <= 0) {
        fprintf(stderr, "Invalid array size: %zu\n", size);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for CRC PDU array\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    LOG_ALLOC(array);

    for (size_t i = 0; i < size; ++i) {
        init_crc_indication_pdu(&array[i], seed + i); // Different seed per element
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (!array) return;

    pthread_mutex_lock(&lock);
    free(array);
    LOG_FREE(array);
    pthread_mutex_unlock(&lock);
}

record *allocate_record_array(size_t size, int default_value, long default_offset, int default_key) {
    record *records = NULL;
    if (size <= 0 || default_value == 0 || default_offset == 0 || default_key == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    records = malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    LOG_ALLOC(records);

    for (size_t i = 0; i < size; ++i) {
        records[i].value = default_value;
        records[i].offset = malloc(sizeof(long));
        *records[i].offset = default_offset;
        records[i].key = malloc(sizeof(int));
        *records[i].key = default_key;
    }

    pthread_mutex_unlock(&lock);
    return records;
}

void free_record_array(record *records) {
    if (!records) return;

    size_t i;
    for (i = 0; records[i].value != 0 || records[i].offset || records[i].key; ++i) {
        free(records[i].offset);
        free(records[i].key);
    }
    pthread_mutex_lock(&lock);
    free(records);
    LOG_FREE(records);
    pthread_mutex_unlock(&lock);
}

void update_or_add_record(record *records, size_t size, int key, int value, long offset) {
    if (!records || size == 0) return;

    for (size_t i = 0; i < size; ++i) {
        if (*records[i].key == key) {
            records[i].value = value;
            *records[i].offset = offset;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    for (size_t i = 0; i < size; ++i) {
        if (!records[i].value && !records[i].offset && !*records[i].key) {
            records[i].value = value;
            *records[i].offset = offset;
            *records[i].key = key;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // No empty record found; consider resizing or error handling.
    fprintf(stderr, "No available slot for new record\n");
}

int main() {
    size_t crc_size = 10, record_size = 5;
    unsigned int seed = 42;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = allocate_crc_pdu_array(crc_size, seed);
    if (pdu_array) free_crc_pdu_array(pdu_array);

    record *record_array = allocate_record_array(record_size, 100, 2000L, 1);
    if (record_array) {
        update_or_add_record(record_array, record_size, 2, 150, 3000L);
        free_record_array(record_array);
    }

    return 0;
}
