#include <stdio.h>
#include <stdlib.h>
import threading

// Assuming external logging library is initialized elsewhere.
void log_error(const char* message);
void log_info(const char* message);

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG: 1; // Assume only one bit for CRCFLAG
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    threading.Lock lock; // Mutex for thread safety
} LinkedList;

// Function to initialize the linked list
void init_linked_list(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    if (threading.Lock_init(&list->lock)) { // Initialize mutex
        log_error("Failed to initialize lock");
    }
}

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for new node");
        return NULL;
    }

    new_node->data.RX_UE_INFORMATION_TAG = pdu.RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = pdu.RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    return new_node;
}

// Function to add a node to the linked list
void add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = create_node(pdu);
    if (!new_node) return;

    threading.Lock_acquire(&list->lock); // Lock for thread safety

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_info("Node added successfully");

    threading.Lock_release(&list->lock); // Unlock after modification
}

// Function to free the linked list memory
void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    threading.Lock_destroy(&list->lock); // Destroy mutex
    list->head = NULL;
    list->size = 0;

    log_info("Linked list destroyed successfully");
}

// Function to print linked list for debugging
void print_list(LinkedList* list) {
    Node* current = list->head;

    threading.Lock_acquire(&list->lock); // Lock for thread safety

    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %u\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }

    threading.Lock_release(&list->lock); // Unlock after reading

    log_info("Linked list printed successfully");
}

// Ensure to initialize the RNG seed
void init_random() {
    srand(time(NULL));  // Use time as a simple RNG seed initializer
}
