        curl_easy_setopt(curl, CURLOPT_URL, url_or_file);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, response_file);

