            fclose(response_file);
            curl_easy_cleanup(curl);
            return;
        }

        fseek(response_file, 0, SEEK_SET);
        json_error_t error;
        json_t *root = json_loadf(response_file, 0, &error);
        fclose(response_file);

        if (!root) {
            fprintf(stderr, "Error parsing JSON response: %s\n", error.text);
            curl_easy_cleanup(curl);
            return;
