void parse_json_data(SensorDataStore *store, json_t *root) {
    json_error_t error;
    json_t *array = json_array_each(root, &error);

    while (array) {
        SensorRecord record;
        memset(&record, 0, sizeof(record));

        json_t *id_json = json_object_get(array, "identifier");
        if (!json_is_integer(id_json)) {
            fprintf(stderr, "Invalid identifier\n");
            array = json_array_next(root);
            continue;
