        record.identifier = (uint64_t)json_integer_value(id_json);

        json_t *reading_json = json_object_get(array, "reading");
        if (!json_is_real(reading_json)) {
            fprintf(stderr, "Invalid reading\n");
            array = json_array_next(root);
            continue;
