        record.reading = (float)json_number_value(reading_json);

        json_t *sensor_id_json = json_object_get(array, "sensor_id");
        if (!json_is_string(sensor_id_json)) {
            fprintf(stderr, "Invalid sensor ID\n");
            array = json_array_next(root);
            continue;
        }
        strncpy(record.sensor_id, json_string_value(sensor_id_json), sizeof(record.sensor_id) - 1);

        json_t *timestamp_json = json_object_get(array, "timestamp");
        if (!json_is_integer(timestamp_json)) {
            fprintf(stderr, "Invalid timestamp\n");
            array = json_array_next(root);
            continue;
        }
        record.timestamp = (time_t)json_integer_value(timestamp_json);

        json_t *confidence_json = json_object_get(array, "confidence");
        if (!json_is_real(confidence_json)) {
            fprintf(stderr, "Invalid confidence score\n");
            array = json_array_next(root);
            continue;
        }
        record.confidence = json_number_value(confidence_json);

        add_sensor_record(store, record);
        array = json_array_next(root);
    }
}

// Function to serialize records into a compressed binary format
void serialize_records(SensorDataStore *store, const char *filename) {
    pthread_rwlock_rdlock(&store->lock);
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_rwlock_unlock(&store->lock);
        return;
    }

    uLongf compressed_size = compressBound(store->size * sizeof(SensorRecord));
    unsigned char *compressed_data = malloc(compressed_size);

    if (compress(compressed_data, &compressed_size, store->records, store->size * sizeof(SensorRecord)) != Z_OK) {
        fprintf(stderr, "Compression failed\n");
        free(compressed_data);
        fclose(file);
        pthread_rwlock_unlock(&store->lock);
        return;
    }

    fwrite(&store->size, sizeof(size_t), 1, file);
    fwrite(compressed_data, compressed_size, 1, file);

    free(compressed_data);
    fclose(file);
    pthread_rwlock_unlock(&store->lock);
}

// Function to deserialize records from a compressed binary format
void deserialize_records(SensorDataStore *store, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    uLongf decompressed_size = store->size * sizeof(SensorRecord);
    unsigned char *decompressed_data = malloc(decompressed_size);

    if (uncompress(decompressed_data, &decompressed_size, NULL, 0) != Z_OK) {
        fprintf(stderr, "Decompression failed\n");
        free(decompressed_data);
        fclose(file);
        return;
    }

    pthread_rwlock_wrlock(&store->lock);
    fread(decompressed_data, decompressed_size, 1, file);
    memcpy(store->records, decompressed_data, decompressed_size);
    store->size = size;
    pthread_rwlock_unlock(&store->lock);

    free(decompressed_data);
    fclose(file);
}

// Function to free the sensor data store
void destroy_sensor_data_store(SensorDataStore *store) {
    pthread_rwlock_wrlock(&store->lock);
    free(store->records);
    pthread_rwlock_unlock(&store->lock);
    pthread_rwlock_destroy(&store->lock);
    free(store);
}
