        return NULL;
    }
    return block;
}

void free_memory_pool() {
    mempool_destroy(memory_pool);
}

void log_and_exit(const char *msg, int status) {
    logger_log_error(msg);
    exit(status);
}

// Worker function to process PDU
void* worker_function(void *arg) {
    while (1) {
        pthread_mutex_lock(&queue_mutex);
        while (work_queue.head == NULL) {
            pthread_cond_wait(&queue_cond, &queue_mutex);
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = work_queue.head;
        if (pdu) {
            work_queue.head = pdu->next;
            if (work_queue.head == NULL) work_queue.tail = NULL;

            pthread_mutex_unlock(&queue_mutex);

            // Process the PDU
            logger_log_info("Processing PDU with RNTI: %lu", pdu->rx_ue_info_tag.RNTI);

            free(pdu);  // Free after processing (assumes PDU is dynamically allocated)
        } else {
            pthread_mutex_unlock(&queue_mutex);
        }
    }
}

void start_worker_threads() {
