    if (!work_queue.head) {
        work_queue.head = pdu;
        work_queue.tail = pdu;
    } else {
        work_queue.tail->next = pdu;
        work_queue.tail = pdu;
    }
    pthread_cond_signal(&queue_cond);

    pthread_mutex_unlock(&queue_mutex);
}

void validate_linked_list() {
    // Periodically validates the integrity of the linked list
    NFAPI_CRC_INDICATION_PDU_T *current = work_queue.head, *prev = NULL;

    while (current) {
        if (current == prev || current->next && current->next == prev) {
            logger_log_error("Circular reference detected");
            break;
        }
        prev = current;
        current = current->next;
    }

