        pthread_mutex_lock(&list_lock);
        if (++pdu_count >= check_frequency) {
            validate_linked_list();
            pdu_count = 0;
        }
        pthread_mutex_unlock(&list_lock);
    }

    return NULL;
}

void main_task() {
    initialize_config();
    initialize_memory_pool();

    pthread_t async_thread;
    if (pthread_create(&async_thread, NULL, async_pdu_processing, NULL)) {
        log_and_exit("Failed to create async processing thread", EXIT_FAILURE);
    }

    start_worker_threads();
    pthread_join(async_thread, NULL);

    free_memory_pool();
