```csharp
using System;

public class DynamicRandom
{
    private static readonly object syncRoot = new Object();
    private Random random;

    public DynamicRandom(int? seed = null)
    {
        if (seed.HasValue)
        {
            lock (syncRoot) { random = new Random(seed.Value); }
        }
        else
        {
            lock (syncRoot) { random = new Random(); }
        }
    }

    public void SetSeed(int seed)
    {
        lock (syncRoot) { random = new Random(seed); }
    }

    public int NextInt(int minInclusive, int maxExclusive)
    {
        ValidateRange(minInclusive, maxExclusive);
        lock (syncRoot) { return random.Next(minInclusive, maxExclusive); }
    }

    public double NextDouble(double minInclusive, double maxExclusive)
    {
        ValidateRange(minInclusive, maxExclusive);
        lock (syncRoot) 
        {
            return minInclusive + (maxExclusive - minInclusive) * random.NextDouble();
        }
    }

    private void ValidateRange(int minInclusive, int maxExclusive)
    {
        if (maxExclusive <= minInclusive)
        {
            throw new ArgumentOutOfRangeException("Max must be greater than Min");
        }
    }

    private void ValidateRange(double minInclusive, double maxExclusive)
    {
        if (maxExclusive <= minInclusive)
        {
            throw new ArgumentOutOfRangeException("Max must be greater than Min");
        }
    }
}
