#define IDENTIFIERS_SIZE 20000
#define HASH_TABLE_SIZE 10007 // A prime number for better distribution

typedef struct {
    uint32_t identifier;
    int key;
} data_record;

typedef struct hash_table_entry {
    data_record record;
    struct hash_table_entry *next;
} hash_table_entry;

hash_table_entry *hash_table[HASH_TABLE_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int max_key = -1;
pthread_mutex_t max_key_mutex = PTHREAD_MUTEX_INITIALIZER;

uint32_t identifiers[IDENTIFIERS_SIZE];

// Simple hash function
unsigned int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

void initialize_identifiers() {
    for (int i = 0; i < IDENTIFIERS_SIZE; ++i) {
        identifiers[i] = i;
    }
}

hash_table_entry *create_hash_table_entry(data_record record) {
    hash_table_entry *entry = malloc(sizeof(hash_table_entry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    entry->record = record;
    entry->next = NULL;
    return entry;
}

void insert_into_hash_table(data_record record) {
    unsigned int index = hash(record.key);
    pthread_mutex_lock(&mutex);

    hash_table_entry *entry = create_hash_table_entry(record);
    entry->next = hash_table[index];
    hash_table[index] = entry;

    pthread_mutex_unlock(&mutex);

    update_max_key(record.key);
}

void update_max_key(int key) {
    pthread_mutex_lock(&max_key_mutex);
    if (key > max_key) {
        max_key = key;
    }
    pthread_mutex_unlock(&max_key_mutex);
}

int is_unique_key(uint16_t *keys, uint16_t new_key, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (keys[i] == new_key) {
            return 0;
        }
    }
    return 1;
}

void read_and_process_input(size_t expected_count) {
    uint16_t *keys = malloc(expected_count * sizeof(uint16_t));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    int key;
    while (scanf("%d", &key) == 1 && count < expected_count) {
        if (key >= 0 && key <= 65535) {
            if (is_unique_key(keys, key, count)) {
                keys[count++] = key;
            } else {
                fprintf(stderr, "Duplicate key encountered: %d\n", key);
                exit(EXIT_FAILURE);
            }
        } else {
            fprintf(stderr, "Invalid key range: %d\n", key);
            exit(EXIT_FAILURE);
        }
    }

    if (count != expected_count) {
        fprintf(stderr, "Input count mismatch. Expected: %zu, Got: %d\n", expected_count, count);
        free(keys);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        data_record record = { .identifier = identifiers[i], .key = keys[i] };
        insert_into_hash_table(record);
    }

    free(keys);
}

int main() {
    initialize_identifiers();

    size_t expected_count;
    printf("Enter the number of records: ");
    if (scanf("%zu", &expected_count) != 1 || expected_count == 0 || expected_count > IDENTIFIERS_SIZE) {
        fprintf(stderr, "Invalid input count\n");
        return EXIT_FAILURE;
    }

    read_and_process_input(expected_count);

    printf("Maximum key value found: %d\n", max_key);

    // Cleanup hash table
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table_entry *entry = hash_table[i];
        while (entry) {
            hash_table_entry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    return EXIT_SUCCESS;
}
```

### Key Points:

- **Thread Safety**: The code uses mutexes to ensure thread-safe operations on the hash table and `max_key`.
- **Memory Management**: Allocates memory for keys dynamically, checks for allocation failures, and ensures cleanup of resources.
- **Hash Table Implementation**: Uses a simple hash function with chaining for collision resolution.
- **Input Validation**: Checks for valid key ranges and uniqueness, ensuring input matches expected counts.
- **Error Handling**: Gracefully handles errors such as invalid inputs or memory allocation failures.']

