#define MAX_NODES 10000
#define MAX_EDGES 50000

typedef struct {
    int nodeID;
    int connectionStatus; // 0 for disconnected, 1 for connected
} NetworkNode;

typedef struct {
    int sourceID;
    int targetID;
    time_t lastVerifiedTimestamp;
} Edge;

typedef struct {
    NetworkNode *nodes;
    int nodeCount;
    Edge *edges;
    int edgeCount;
} GraphDatabase;

GraphDatabase* initializeGraph(int nodeCount, int edgeCount) {
    if (nodeCount > MAX_NODES || edgeCount > MAX_EDGES)
        return NULL;

    GraphDatabase *graph = malloc(sizeof(GraphDatabase));
    graph->nodes = calloc(nodeCount, sizeof(NetworkNode));
    graph->edges = malloc(edgeCount * sizeof(Edge));
    graph->nodeCount = nodeCount;
    graph->edgeCount = edgeCount;

    for (int i = 0; i < nodeCount; ++i) {
        graph->nodes[i].nodeID = i;
        graph->nodes[i].connectionStatus = rand() % 2;
    }

    srand(time(NULL));
    for (int i = 0; i < edgeCount; ++i) {
        graph->edges[i].sourceID = rand() % nodeCount;
        graph->edges[i].targetID = rand() % nodeCount;
        graph->edges[i].lastVerifiedTimestamp = time(NULL);
    }

    return graph;
}

void simulateNetworkTraffic(GraphDatabase *graph, int packetCount) {
    if (!graph)
        return;

    for (int i = 0; i < packetCount; ++i) {
        int sourceID = rand() % graph->nodeCount;
        int targetID = rand() % graph->nodeCount;

        while (targetID == sourceID)
            targetID = rand() % graph->nodeCount;

        NetworkNode *source = &graph->nodes[sourceID];
        if (source->connectionStatus) {
            for (int j = 0; j < graph->edgeCount; ++j) {
                Edge *edge = &graph->edges[j];
                if ((edge->sourceID == sourceID && edge->targetID == targetID) ||
                    (edge->sourceID == targetID && edge->targetID == sourceID)) {

                    edge->lastVerifiedTimestamp = time(NULL);
                    NetworkNode *target = &graph->nodes[targetID];
                    target->connectionStatus = 1; // Update to connected status
                }
            }
        }
    }
}

void cleanupGraph(GraphDatabase *graph) {
    if (!graph)
        return;

    free(graph->nodes);
    free(graph->edges);
    free(graph);
}

int main() {
    int nodeCount = 1000;
    int edgeCount = 2000;
    GraphDatabase *graph = initializeGraph(nodeCount, edgeCount);

    if (graph) {
        simulateNetworkTraffic(graph, 500);
        cleanupGraph(graph);
    }

    return 0;
}
