typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

int allocate_dynamic_array(DynamicArray *da, size_t n) {
    if (n > MAX_CAPACITY) return -1; // Exceeds max capacity

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        da->array = realloc(da->array, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (da->array != NULL) {
            da->capacity = n;
            return 0; // Success
        }
    }
    return -1; // Allocation failure after retries
}

void populate_array(DynamicArray *da, uint32_t crcThreshold) {
    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < da->capacity; ++i) {
        da->array[i].crcTag.RX_UE_INFORMATION_TAG = rand(); // Random data
        da->array[i].crcTag.RNTI = rand() % 65536;
        da->array[i].CRCFLAG = (rand() % 100) < crcThreshold ? 1 : 0; // Configurable threshold
    }
}

void remove_element(DynamicArray *da, size_t index) {
    if (index >= da->count) return;

    memmove(&da->array[index], &da->array[index + 1], 
            (da->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --da->count;
}

void iterate_and_process(DynamicArray *da, void (*operation)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        operation(&da->array[i]);
    }

    pthread_mutex_unlock(&da->lock);
}

void example_operation(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Example operation: toggle CRCFLAG
    element->CRCFLAG ^= 1;
}

int main() {
    DynamicArray da = { .count = 0, .capacity = 0 };
    pthread_mutex_init(&da.lock, NULL);

    if (allocate_dynamic_array(&da, 100) == 0) {
        populate_array(&da, 50); // Set CRC threshold to 50%
        da.count = da.capacity;

        iterate_and_process(&da, example_operation);

        remove_element(&da, 10); // Example removal
    }

    free(da.array);
    pthread_mutex_destroy(&da.lock);

    return 0;
}
