import <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_STRUCTS 10000
#define LOG_FLUSH_THRESHOLD 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        _Atomic(int) CRCFLAG; // Using atomic for lock-free access
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} BufferPool;

BufferPool pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};
_Atomic(int) crc_error_count = 0;
_Atomic(size_t) log_counter = 0;

// Logging function
void log_structure(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);

    printf("Logging RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);

    _Atomic_fetch_add(&log_counter, 1);
    if (_Atomic_load(&log_counter) >= LOG_FLUSH_THRESHOLD) {
        fflush(stdout); // Flush logs to disk
        _Atomic_store(&log_counter, 0);
    }

    pthread_mutex_unlock(&log_mutex);
}

// Function to initialize buffer pool
void init_buffer_pool(size_t initial_capacity) {
    pthread_mutex_lock(&pool.mutex);
    if (pool.capacity == 0) {
        pool.buffer = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool.capacity = initial_capacity;
    }
    pthread_mutex_unlock(&pool.mutex);
}

// Function to generate unique RNTI
int generate_unique_rnti() {
    static _Atomic(int) next_rnti = 1; // Start from a safe non-zero value
    int rnti;
    do {
        rnti = _Atomic_fetch_add(&next_rnti, 1);
    } while (rnti == 0); // Ensure RNTI is never zero

    return rnti;
}

// Function to create and populate structures with optional max limit
void create_and_populate_structures(size_t max_count) {
    size_t current_capacity = pool.capacity;
    pthread_mutex_lock(&pool.mutex);

    if (max_count > 0 && pool.count >= max_count) {
        printf("Max structure count reached. Applying backpressure.\n");
        pthread_mutex_unlock(&pool.mutex);
        return; // Apply backpressure
    }

    size_t required_capacity = pool.count + 1;
    if (required_capacity > current_capacity) {
        size_t new_capacity = required_capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_buffer = realloc(pool.buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_buffer == NULL) {
            pthread_mutex_unlock(&pool.mutex);
            printf("Failed to allocate memory. Applying backpressure.\n");
            return; // Apply backpressure
        }

        pool.buffer = new_buffer;
        current_capacity = new_capacity;
    }

    size_t index = pool.count++;
    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool.buffer[index];

    // Populate structure with random values
    srand(time(NULL) ^ pthread_self()); // Unique seed per thread

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = generate_unique_rnti();
    int crc_flag = (rand() % 2 == 0);
    atomic_store(&pdu->CRC_INDICATION_REL8_TAG.CRCFLAG, crc_flag);

    if (crc_flag) {
        atomic_fetch_add(&crc_error_count, 1); // Increment CRC error count
    }

    log_structure(pdu);

    pthread_mutex_unlock(&pool.mutex);
}

// Thread-safe function to handle dynamic scaling and backpressure logic
void* thread_function(void* arg) {
    size_t max_count = *(size_t*)arg;
    while (1) { 
        create_and_populate_structures(max_count);
        usleep(100); // Simulate processing delay
    }
    return NULL;
}

// Entry point to start threads and initialize system
int main(int argc, char* argv[]) {
    size_t max_structs = MAX_STRUCTS; 
    init_buffer_pool(1024);

    pthread_t threads[MAX_STRUCTS];
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &max_structs)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Join threads
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(pool.buffer); // Cleanup buffer pool
    return 0;
}
