void buffer_init(IndicationBuffer *buf, size_t initial_capacity) {
    buf->buffer = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buf->buffer) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
