    buf->capacity = initial_capacity;
    buf->count = 0;
    pthread_mutex_init(&buf->lock, NULL);
    pthread_cond_init(&buf->cond, NULL);
}

void buffer_destroy(IndicationBuffer *buf) {
    free(buf->buffer);
    pthread_mutex_destroy(&buf->lock);
    pthread_cond_destroy(&buf->cond);
}

int buffer_add_pdu(IndicationBuffer *buf, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&buf->lock);

    if (buf->count == buf->capacity) {
        size_t new_capacity = buf->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_buffer = realloc(buf->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&buf->lock);
            return -1;
        }
        buf->buffer = new_buffer;
        buf->capacity = new_capacity;
    }

    buf->buffer[buf->count++] = pdu;

    pthread_cond_signal(&buf->cond);
    pthread_mutex_unlock(&buf->lock);

    return 0;
}

