} NFAPI_CRC_INDICATION_PDU_T;

bool validate_network_parameters(const NetworkEntity* entity) {
    // Example validation: Check for valid IP and port range
    if (entity->port_number < 1024 || entity->port_number > 65535) return false;
    return true; 
}

int process_config_files(const char *directory, NetworkEntity network_entities[], size_t max_entities, NFAPI_CRC_INDICATION_PDU_T pdus[]) {
    DIR *dir;
    struct dirent *entry;
    int max_port = -1;
    size_t valid_entity_count = 0;

    if ((dir = opendir(directory)) == NULL) {
        fprintf(stderr, "Error opening directory: %s\n", strerror(errno));
        return -1;
    }

    while ((entry = readdir(dir)) != NULL && valid_entity_count < max_entities) {
        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory, entry->d_name);

        FILE *file = fopen(filepath, "r");
        if (!file) continue;

        NetworkEntity entity;
        int bytes_read = fscanf(file, "%15[^ \t\n],%d,%9s",
                                entity.ip_address,
                                &entity.port_number,
                                entity.protocol_type);

        fclose(file);

        if (bytes_read != 3) {
            fprintf(stderr, "Malformed data in file: %s\n", filepath);
            continue;
        }

        if (!validate_network_parameters(&entity)) {
            fprintf(stderr, "Invalid network parameters in file: %s\n", filepath);
            continue;
        }

        if (max_port < entity.port_number) max_port = entity.port_number;

        network_entities[valid_entity_count++] = entity;

        // Generate NFAPI_CRC_INDICATION_PDU_T
        pdus[valid_entity_count - 1].pdu.crc_tag.RX_UE_INFORMATION_TAG = rand();
        pdus[valid_entity_count - 1].pdu.crc_tag.RNTI = rand() & 0x7FFF; // Example RNTI range
        pdus[valid_entity_count - 1].pdu.crc_tag.CRCFLAG = rand() % 2;
    }

    closedir(dir);
    return max_port;
}

void initialize_mac_frames(MAC_FRAME* frames, size_t frame_count, const uint8_t* input_stream, size_t stream_length) {
    for (size_t i = 0; i < frame_count; ++i) {
        frames[i].header.data[0] = rand(); // Example initialization
        size_t payload_size = (stream_length > 64) ? 64 : stream_length;

        frames[i].payload.payload = malloc(payload_size);
        if (!frames[i].payload.payload) {
            fprintf(stderr, "Memory allocation failed for MAC_PAYLOAD\n");
            exit(EXIT_FAILURE);
        }
        memcpy(frames[i].payload.payload, input_stream + (i * 64), payload_size);

        // Align with IEEE 802.11 padding requirements
        frames[i].payload.length = (payload_size % 4) ? (payload_size + 4 - (payload_size % 4)) : payload_size;

        frames[i].fcs.crc = rand(); // Example CRC generation

        stream_length -= 64; // Move to next segment in input_stream
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    NetworkEntity network_entities[MAX_NETWORK_ENTITIES];
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_NETWORK_ENTITIES];
    int max_port = process_config_files(argv[1], network_entities, MAX_NETWORK_ENTITIES, pdus);

    if (max_port == -1) {
        fprintf(stderr, "Failed to process configuration files.\n");
        return EXIT_FAILURE;
    }

    printf("Maximum Port Number: %d\n", max_port);
