NFAPI_CRC_INDICATION_PDU_T* initialize_array(size_t initial_size) {
    size_t current_size = initial_size;
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) return NULL;

    for (size_t i = 0; i < current_size; ++i) {
        array[i].rnti.RX_UE_INFORMATION_TAG = i + 1;
        array[i].crc_indication_rel8_tag.CRCFLAG = (unsigned char)(i ^ 0xAB); // predefined constant
    }

    return array;
}

NFAPI_CRC_INDICATION_PDU_T* resize_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t current_size) {
    pthread_mutex_lock(&resize_mutex);

    if (!array || current_size >= MAX_SIZE) {
        pthread_mutex_unlock(&resize_mutex);
        return NULL; // Can't resize further
    }

    size_t new_size = current_size + 10;
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) {
