        return NULL; // Reallocation failed
    }

    for (size_t i = current_size; i < new_size; ++i) {
        new_array[i].rnti.RX_UE_INFORMATION_TAG = i + 1;
        new_array[i].crc_indication_rel8_tag.CRCFLAG = (unsigned char)(i ^ 0xAB);
