typedef struct {
    Sensor **sensors;
    size_t sensorCount;
    size_t capacity;
} SensorCollection;

SensorCollection* createSensorCollection(size_t initialCapacity) {
    SensorCollection *collection = (SensorCollection *)malloc(sizeof(SensorCollection));
    if (!collection) return NULL;

    collection->sensors = (Sensor **)calloc(initialCapacity, sizeof(Sensor *));
    if (!collection->sensors) {
        free(collection);
        return NULL;
    }

    collection->sensorCount = 0;
    collection->capacity = initialCapacity;
    return collection;
}

void resizeSensorCollectionIfNeeded(SensorCollection *collection) {
    if (collection->sensorCount < collection->capacity) return;

    size_t newCapacity = collection->capacity * 2;
    Sensor **newArray = (Sensor **)realloc(collection->sensors, newCapacity * sizeof(Sensor *));
    if (!newArray) return; // Handle reallocation failure gracefully

    memset(newArray + collection->capacity, 0, (newCapacity - collection->capacity) * sizeof(Sensor *));
    collection->sensors = newArray;
    collection->capacity = newCapacity;
}

void addSensor(SensorCollection *collection, const char *name, double accuracy, size_t readingsCount) {
    resizeSensorCollectionIfNeeded(collection);

    Sensor *sensor = (Sensor *)malloc(sizeof(Sensor));
    if (!sensor) return;

    strncpy(sensor->name, name, MAX_NAME_LENGTH);
    sensor->name[MAX_NAME_LENGTH] = '\0';
    sensor->accuracy = accuracy;

    sensor->temperatureReadings = (double *)malloc(readingsCount * sizeof(double));
    if (!sensor->temperatureReadings) {
        free(sensor);
        return; // Handle memory allocation failure
    }

    sensor->readingsCount = readingsCount;

    collection->sensors[collection->sensorCount++] = sensor;
}

Sensor* getSensorByName(SensorCollection *collection, const char *name) {
    for (size_t i = 0; i < collection->sensorCount; ++i) {
        if (strcmp(collection->sensors[i]->name, name) == 0) {
            return collection->sensors[i];
        }
    }
    return NULL;
}

double* getTemperatureReadings(Sensor *sensor, size_t *count) {
    if (!sensor) return NULL;

    *count = sensor->readingsCount;
    return sensor->temperatureReadings;
}

void freeSensorCollection(SensorCollection *collection) {
    for (size_t i = 0; i < collection->sensorCount; ++i) {
        free(collection->sensors[i]->temperatureReadings);
        free(collection->sensors[i]);
    }
    free(collection->sensors);
    free(collection);
}

int main() {
    SensorCollection *collection = createSensorCollection(4);

    addSensor(collection, "Thermistor1", 0.98, 5);
    addSensor(collection, "Thermocouple2", 0.99, 3);

    // Example usage: Retrieve and print temperature readings for a sensor
    const char *sensorName = "Thermistor1";
    Sensor *sensor = getSensorByName(collection, sensorName);

