#include <stdio.h>
#include <stdlib.h>
import "nfa_api_crc_indication_pdu_t.h"  // Assume this header provides NFAPI_CRC_INDICATION_PDU_T definition

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
} CRCIndicationManager;

// Function to initialize the manager
void init_crc_manager(CRCIndicationManager *manager, size_t initial_capacity) {
    if (initial_capacity == 0) return;

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) exit(EXIT_FAILURE); // Handle allocation failure
    manager->capacity = initial_capacity;
    manager->count = 0;
}

// Function to free the manager resources
void free_crc_manager(CRCIndicationManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Resize array if necessary
static void ensure_capacity(CRCIndicationManager *manager, size_t min_capacity) {
    if (min_capacity > manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        while (new_capacity < min_capacity) new_capacity *= 2;

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) exit(EXIT_FAILURE); // Handle allocation failure

        manager->array = new_array;
        manager->capacity = new_capacity;
    }
}

// Function to add a new element
void add_crc_indication(CRCIndicationManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);

    ensure_capacity(manager, manager->count + 1);

    // Fill in the structure with valid data and random CRCFLAG
    pdu.RX_UE_INFORMATION_TAG = ...;   // Assume a valid tag is provided or generated
    pdu.RNTI = ...;                     // Assume a valid RNTI is provided or generated
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    manager->array[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->lock);
}

// Function to remove an element by index
void remove_crc_indication(CRCIndicationManager *manager, size_t index) {
    if (index >= manager->count) return; // Handle invalid index gracefully

    pthread_mutex_lock(&manager->lock);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }
    manager->count--;

    pthread_mutex_unlock(&manager->lock);
}

// Function to iterate over the array in a forward direction
void iterate_forward(CRCIndicationManager *manager, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        func(manager->array[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to iterate over the array in a reverse direction
void iterate_reverse(CRCIndicationManager *manager, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&manager->lock);

    for (int i = manager->count - 1; i >= 0; --i) {
        func(manager->array[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example usage function
void print_crc(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("CRCFLAG: %d\n", pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
}
