#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct EnvironmentalMeasurement {
    long timestamp;
    float temperature;
    char location[50];
    int sensorID;
    struct EnvironmentalMeasurement* next;
} EnvironmentalMeasurement;

float calculate_average(float *arr, size_t n) {
    float sum = 0.0;
    for (size_t i = 0; i < n; ++i) {
        sum += arr[i];
    }
    return n ? (sum / n) : 0.0;
}

int compare_measurements(const EnvironmentalMeasurement* a, const EnvironmentalMeasurement* b) {
    if (a->timestamp != b->timestamp)
        return (a->timestamp < b->timestamp) ? -1 : 1;
    if (a->temperature != b->temperature || strcmp(a->location, b->location) != 0)
        return 0; // Duplicate entry
    return 1; // Not a duplicate
}

void flush_to_persistent_storage(EnvironmentalMeasurement* head) {
    FILE *file = fopen("measurements.txt", "a");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    EnvironmentalMeasurement* current = head;
    while (current != NULL) {
        fprintf(file, "%ld,%f,%s,%d\n",
                current->timestamp,
                current->temperature,
                current->location,
                current->sensorID);
        current = current->next;
    }
    fclose(file);
}

EnvironmentalMeasurement* add_measurement(EnvironmentalMeasurement** head, long timestamp, float temperature, const char* location, int sensorID) {
    EnvironmentalMeasurement* new_node = (EnvironmentalMeasurement*)malloc(sizeof(EnvironmentalMeasurement));
    if (!new_node) {
        perror("Failed to allocate memory");
        return NULL;
    }

    new_node->timestamp = timestamp;
    new_node->temperature = temperature;
    strncpy(new_node->location, location, sizeof(new_node->location) - 1);
    new_node->sensorID = sensorID;
    new_node->next = NULL;

    EnvironmentalMeasurement **tracer = head;
    while (*tracer && compare_measurements(*tracer, new_node) == -1) {
        tracer = &((*tracer)->next);
    }

    if (compare_measurements(*tracer, new_node)) {
        new_node->next = *tracer;
        *tracer = new_node;
    } else {
        free(new_node); // Duplicate entry
    }

    return *head;
}

int main() {
    float *numbers = NULL;
    size_t capacity = 0, count = 0;
    float number;

    printf("Enter floating-point numbers (non-number to end):\n");
    while (scanf("%f", &number) == 1) {
        if (count >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            numbers = realloc(numbers, capacity * sizeof(float));
            if (!numbers) {
                perror("Failed to reallocate memory");
                return EXIT_FAILURE;
            }
        }
        numbers[count++] = number;
    }

    printf("Average: %.2f\n", calculate_average(numbers, count));

    EnvironmentalMeasurement* head = NULL;

    // Example of adding measurements
    add_measurement(&head, 1625247600, 23.5, "LocationA", 1);
    add_measurement(&head, 1625247660, 24.0, "LocationB", 2);

    flush_to_persistent_storage(head);

    // Free linked list
    EnvironmentalMeasurement* current = head;
    while (current) {
        EnvironmentalMeasurement* next = current->next;
        free(current);
        current = next;
    }

    free(numbers);
    return 0;
}
