#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_CAPACITY 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_CAPACITY];
    size_t count;
    pthread_mutex_t mutex;
} CRC_Indication_List;

// Function to perform parity check
int calculate_parity(uint16_t value) {
    int parity = 0;
    while (value) {
        parity ^= (value & 1);
        value >>= 1;
    }
    return parity;
}

// Function to generate pseudo-random number based on timestamp
uint16_t generate_random_number(time_t timestamp) {
    return (uint16_t)(timestamp ^ (timestamp >> 16));
}

// Initialize the CRC indication list
void init_crc_indication_list(CRC_Indication_List *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new PDU to the list
int add_pdu_to_list(CRC_Indication_List *list, uint16_t rx_ue_tag, uint16_t rnti, uint8_t crc_rel8_tag) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_CAPACITY) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Error: Maximum capacity reached.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    new_pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_pdu->RNTI = rnti;
    new_pdu->CRC_INDICATION_REL8_TAG = crc_rel8_tag;

    time_t timestamp = time(NULL);
    uint16_t random_number = generate_random_number(timestamp);
    int parity = calculate_parity(rnti) ^ calculate_parity(random_number);

    new_pdu->CRCFLAG = (parity == 1) ? 1 : 0;

    list->data[list->count++] = new_pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Free all allocated PDUs
void free_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i]);
    }

    pthread_mutex_unlock(&list->mutex);
}

// Clean up the CRC indication list
void destroy_crc_indication_list(CRC_Indication_List *list) {
    free_crc_indication_list(list);
    pthread_mutex_destroy(&list->mutex);
}
