#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_SIZE 1024

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer[MAX_SIZE];
    size_t head;
    size_t tail;
    size_t count;
    pthread_mutex_t lock;
} RingBuffer;

void ring_buffer_init(RingBuffer *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    pthread_mutex_init(&rb->lock, NULL);
}

int is_full(RingBuffer *rb) {
    return rb->count == MAX_SIZE;
}

int is_empty(RingBuffer *rb) {
    return rb->count == 0;
}

int enqueue(RingBuffer *rb, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&rb->lock);
    if (is_full(rb)) {
        pthread_mutex_unlock(&rb->lock);
        printf("Ring buffer overflow\n");
        return -1; // Overflow
    }
    rb->buffer[rb->tail] = item;
    rb->tail = (rb->tail + 1) % MAX_SIZE;
    rb->count++;
    pthread_mutex_unlock(&rb->lock);

    if ((item->RNTI & 0x01) == (rand() % 2)) {
        notify_crc_flag_set(item);
    }
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(RingBuffer *rb) {
    pthread_mutex_lock(&rb->lock);
    if (is_empty(rb)) {
        pthread_mutex_unlock(&rb->lock);
        printf("Ring buffer underflow\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *item = rb->buffer[rb->head];
    rb->head = (rb->head + 1) % MAX_SIZE;
    rb->count--;
    pthread_mutex_unlock(&rb->lock);
    return item;
}

void notify_crc_flag_set(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Integration with external signaling system
    printf("CRC flag set for RNTI: %u\n", pdu->RNTI);
}

uint8_t calculate_parity(uint16_t rnti) {
    uint8_t parity = 0;
    while (rnti) {
        parity ^= rnti & 1;
        rnti >>= 1;
    }
    return parity;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int main() {
    srand(time(NULL));
    RingBuffer rb;
    ring_buffer_init(&rb);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = 1;
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG = rand();
    log_message("Enqueued a new PDU");

    if (enqueue(&rb, pdu) == 0) {
        NFAPI_CRC_INDICATION_PDU_T *dequeued_pdu = dequeue(&rb);
        free(dequeued_pdu);
    }

    return 0;
}
```

This code implements a ring buffer to manage `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring thread-safe access with mutexes. It includes functions for enqueuing and dequeuing elements, calculating parity, notifying when CRC flags are set, and logging operations. The ring buffer dynamically grows up to a maximum size of 1024 elements, handling overflow gracefully.']

