        log_message(log_msg);
    }
    pthread_mutex_unlock(&container->mutex);
}

double measure_processing_time(void (*func)(UEDataContainer*), UEDataContainer* container, size_t ue_count) {
    clock_t start = clock();
    func(container, ue_count);
    clock_t end = clock();

    double time_taken = (double)(end - start) / CLOCKS_PER_SEC;
    return time_taken;
}

void free_ue_data_container(UEDataContainer* container) {
    pthread_mutex_lock(&container->mutex);
    free(container->array);
    container->array = NULL;
    container->capacity = 0;
    container->count = 0;
    pthread_mutex_unlock(&container->mutex);
    pthread_mutex_destroy(&container->mutex);
}

