int execute_command(const char *cmd) {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
        exit(EXIT_FAILURE); // If exec fails
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }
    return 0; // Fork failed
}

void log_attempt(int success, const char *cmd) {
    FILE *log_file = fopen("nfa_report.log", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - Command: %s - Success: %d\n", ctime(&now), cmd, success);
        fclose(log_file);
    }
}

int createNfareport(NFAPI_CRC_INDICATION_PDU_T *report_array, size_t array_size, const char *cmd) {
    int active_processes = 0;
    for (size_t i = 0; i < array_size; ++i) {
        while (active_processes >= MAX_CONCURRENT_PROCESSES) {
            sleep(1); // Simple throttling
        }

        pid_t pid = fork();
        if (pid == 0) { // Child process
            int success = execute_command(cmd);
            report_array[i].crc_indication_rel8_tag.CRCFLAG = success ? 1 : 0;
            log_attempt(success, cmd);
            exit(0); // Exit child after setting flag and logging
        } else if (pid > 0) {
            active_processes++;
        } else {
            return 0; // Fork failed
        }
    }

    int status = 1;
    for (size_t i = 0; i < array_size; ++i) {
        int child_status;
        waitpid(-1, &child_status, WNOHANG);
        if (!WIFEXITED(child_status) || !WEXITSTATUS(child_status)) {
            status = 0;
        }
    }

    return status;
}
