    NFAPI_PDU *pdus;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_LIST;

NFAPI_LIST* create_nfa_list(size_t n, size_t m) {
    NFAPI_LIST* list = malloc(sizeof(NFAPI_LIST));
    if (!list) return NULL;

    list->size = n + m;
    list->pdus = calloc(list->size, sizeof(NFAPI_PDU));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&list->lock);

        list->pdus[i].rx_ue_info.RNTI = rand() % 65536;
        list->pdus[i].RNTI = rand() % 65536;
        list->pdus[i].tag.crc_tag.timestamp = time(NULL);
        list->pdus[i].tag.crc_tag.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&list->lock);

        printf("CRC_INDICATION structure created at index %zu\n", i);
    }

    for (size_t i = n; i < list->size; ++i) {
        int event_type;
        do {
            event_type = rand() % 20; // Randomly generate an event type.
        } while (event_type < VALID_EVENT_TYPE_MIN || event_type > VALID_EVENT_TYPE_MAX);

        pthread_mutex_lock(&list->lock);

        list->pdus[i].rx_ue_info.RNTI = rand() % 65536;
        list->pdus[i].RNTI = rand() % 65536;
        list->pdus[i].tag.cell_event_tag.timestamp = time(NULL);
        list->pdus[i].tag.cell_event_tag.event_type = event_type;

        pthread_mutex_unlock(&list->lock);

        printf("CELLULAR_EVENT structure created at index %zu\n", i);
    }

    return list;
}

void free_nfa_list(NFAPI_LIST* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdus);
        free(list);
    }
}

// Example API to update event types, demonstrating interaction.
void update_event_type(NFAPI_LIST* list, size_t index, int new_event_type) {
    if (index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    // Validate the new event type
    if (new_event_type < VALID_EVENT_TYPE_MIN || new_event_type > VALID_EVENT_TYPE_MAX) {
        printf("Invalid event type encountered at index %zu. Skipping update.\n", index);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->pdus[index].tag.cell_event_tag.event_type = new_event_type;

    pthread_mutex_unlock(&list->lock);

    printf("Event type updated for index %zu\n", index);
}

// Example of bulk update processing.
void process_bulk_updates(NFAPI_LIST* list, size_t updates[], int types[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (updates[i] < list->size && types[i] >= VALID_EVENT_TYPE_MIN &&
            types[i] <= VALID_EVENT_TYPE_MAX) {
            update_event_type(list, updates[i], types[i]);
        }
    }
}

// Logging mechanism to record detailed information.
void log_structure_creation(const char* message) {
    printf("[LOG] %s\n", message);
}

int main() {
    size_t n = 10; // Number of CRC_INDICATION_REL8_TAG structures
    size_t m = 5;  // Number of CELLULAR_EVENT_REL8_TAG structures

    NFAPI_LIST *list = create_nfa_list(n, m);

    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    log_structure_creation("List created successfully.");

    size_t updates[] = {2, 5, 7};
    int types[] = {3, 11, 6};
    process_bulk_updates(list, updates, types, sizeof(updates) / sizeof(size_t));

    free_nfa_list(list);

    return EXIT_SUCCESS;
}
