    *numbers = malloc(capacity * sizeof(int));
    if (*numbers == NULL) {
        log_message("Memory allocation failed");
        return -1;
    }

    char input[256];
    *size = 0;

    while (fgets(input, sizeof(input), stdin)) {
        if (sscanf(input, "%d", &((*numbers)[*size])) != 1) {
            free(*numbers);
            log_message("Invalid input");
            return -1;
        }
        (*size)++;

        if (*size >= capacity) {
            capacity *= 2;
            int *temp = realloc(*numbers, capacity * sizeof(int));
            if (temp == NULL) {
                free(*numbers);
                log_message("Memory reallocation failed");
                return -1;
            }
            *numbers = temp;
        }
    }

    return 0;
}

