    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int *numbers = malloc(num_elements * sizeof(int));
    if (numbers == NULL) {
        log_message("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T");
        return;
    }

    int size = num_elements;
    if (read_integers(&numbers, &size) != 0) {
        free(numbers);
        return;
    }

    pthread_create(&tid, NULL, process_integers, &numbers);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        log_message("Memory allocation failed for array of structures");
        free(numbers);
        return;
    }

    for (int i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&mutex);

        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 1000 + 1;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&mutex);
    }

    free(array);

    pthread_join(tid, NULL);
}

int main(void) {
