            } catch (e) {
                console.error("Error during traversal", e);
                return null;
            }
        }
    }

    // Example usage
    const rootNode = new Node('root');
    traverseDOM(rootNode, node => {
        console.log(node.value); // Process each node value
    });

    return result;
}
