#define MAX_STRUCTURE_SIZE 1024
#define DEFAULT_STRUCTURE_SIZE 256

typedef struct {
    // Define your structure members here
    char data[MAX_STRUCTURE_SIZE];
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int logging_enabled = 1;  // Assume this can be toggled at runtime

void log_message(const char* message) {
    if (logging_enabled) {
        time_t now;
        time(&now);
        printf("[%s] %s\n", ctime(&now), message);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_rrm_data(int n, int structure_size) {
    if (n <= 0 || structure_size <= 0 || structure_size > MAX_STRUCTURE_SIZE) {
        log_message("Invalid input parameters.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_message("Memory allocation failed for array.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        char* data_ptr = malloc(structure_size * sizeof(char));
        if (!data_ptr) {
            log_message("Memory allocation failed for structure data.");

            // Free any previously allocated structures
            while (--i >= 0) {
                free(array[i].data);
            }
            free(array);

            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        array[i].data = data_ptr;
    }

    log_message("Successfully allocated RRM data.");
    pthread_mutex_unlock(&mutex);

    return array;
}

void deallocate_rrm_data(NFAPI_CRC_INDICATION_PDU_T* array, int n) {
    if (!array) return;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < n; ++i) {
        free(array[i].data);
    }

    free(array);
    log_message("Successfully deallocated RRM data.");

    pthread_mutex_unlock(&mutex);
}

// Example usage
int main() {
    int structure_size = DEFAULT_STRUCTURE_SIZE;
    int num_structures = 10;

    NFAPI_CRC_INDICATION_PDU_T* rrm_data = allocate_rrm_data(num_structures, structure_size);
    if (rrm_data) {
        // Use the allocated structures
        deallocate_rrm_data(rrm_data, num_structures);
    }

    return 0;
}
