    log_message("Dynamic array initialized.");
    return array;
}

void cleanup_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->data);
        pthread_mutex_unlock(&array->mutex);

        pthread_mutex_destroy(&array->mutex);
        free(array);
        log_message("Dynamic array cleaned up.");
    }
}

void resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    if (new_capacity <= array->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_message("Failed to reallocate memory for dynamic array.");
        return;
    }

    pthread_mutex_lock(&array->mutex);
    for (size_t i = array->capacity; i < new_capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &new_data[i];
        pdu->RX_UE_INFORMATION_TAG = (int)i;
