        pdu->CRC_INDICATION_REL8_TAG = (int)(i * 654321); // Example assignment
        pdu->CRCFLAG = generate_pseudo_random(false);
    }
    array->data = new_data;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->mutex);

    log_message("Dynamic array resized.");
}

void add_element(DynamicArray* array) {
