            head = newNode;
        }
        tail = newNode;
    }

    return head;
}

size_t getUniqueCount(int *array, size_t size, int **uniqueArray) {
    int seen[size];
    for (size_t i = 0; i < size; ++i) {
        seen[i] = 0;
    }

    size_t uniqueCount = 0;
    for (size_t i = 0; i < size; ++i) {
        int isUnique = 1;
        for (size_t j = 0; j < size; ++j) {
            if (array[i] == array[j] && i != j) {
                isUnique = 0;
                break;
            }
        }

        if (isUnique) {
            (*uniqueArray)[uniqueCount++] = array[i];
            seen[i] = 1;
        }
    }

    for (size_t i = 0; i < size; ++i) {
        if (!seen[i]) {
            free(&array[i]);
        }
    }

    return uniqueCount;
}

