        free(inputArray);
        free(uniqueIntegers);
        return -1;
    }

    // Free dynamically allocated arrays
    free(inputArray);
    free(uniqueIntegers);

    // Assume proper usage and freeing of listHead elsewhere in codebase

    return (int)uniqueCount;  // Return the number of unique integers processed
}
