#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CrcIndicationList;

// Function to initialize the list
void init_list(NFAPI_CrcIndicationList *list, size_t initial_capacity) {
    list->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to resize the array when needed
void ensure_capacity(NFAPI_CrcIndicationList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        list->array = new_array;
        list->capacity = new_capacity;
    }
}

// Function to add a new element
void add_element(NFAPI_CrcIndicationList *list, unsigned int RNTI, unsigned char RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);
    ensure_capacity(list);

    NFAPI_CRC_INDICATION_PDU_T *element = &list->array[list->size];
    element->RNTI = RNTI;
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove an element by index
void remove_element(NFAPI_CrcIndicationList *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Invalid index\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    memmove(&list->array[index], &list->array[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the array in forward direction
void iterate_forward(NFAPI_CrcIndicationList *list, void (*func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        func(&list->array[i]);
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the array in reverse direction
void iterate_reverse(NFAPI_CrcIndicationList *list, void (*func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);
    for (int i = list->size - 1; i >= 0; --i) {
        func(&list->array[i]);
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to free the allocated memory
void destroy_list(NFAPI_CrcIndicationList *list) {
    pthread_mutex_lock(&list->lock);
