    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct CacheNode* next;
} CacheNode;

// List and cache management structures
typedef struct {
    PduNode* head;
    pthread_mutex_t lock;
    CacheNode* cacheHead; // Simple LRU-style cache for demonstration
    int cacheSizeLimit;
} PduListManager;

// Function prototypes
PduListManager* createPduListManager(int cacheSize);
void destroyPduListManager(PduListManager* manager);
int addPDUs(PduListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdus[], int count);
NFAPI_CRC_INDICATION_PDU_T* getPduById(PduListManager* manager, int id);

// Helper functions
static void addToCache(CacheNode** cacheHead, int key, NFAPI_CRC_INDICATION_PDU_T* pdu, int cacheSizeLimit);
static NFAPI_CRC_INDICATION_PDU_T* getFromCache(CacheNode** cacheHead, int key);
static void removePduNode(PduNode** head, PduNode* node);

// Implementation of the functions
PduListManager* createPduListManager(int cacheSize) {
    PduListManager* manager = (PduListManager*)malloc(sizeof(PduListManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;
    manager->cacheHead = NULL;
    manager->cacheSizeLimit = cacheSize;

    return manager;
}

void destroyPduListManager(PduListManager* manager) {
    if (manager) {
        PduNode *current = manager->head, *temp;

        while (current != NULL) {
            temp = current;
            current = current->next;
            free(temp);
        }

        CacheNode *cacheCurrent = manager->cacheHead, *cacheTemp;

        while (cacheCurrent != NULL) {
            cacheTemp = cacheCurrent;
            cacheCurrent = cacheCurrent->next;
            free(cacheTemp->pdu); // Free each PDU stored in cache
            free(cacheTemp);
        }

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int addPDUs(PduListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdus[], int count) {
    if (!manager || !pdus) return -1;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < count; ++i) {
        PduNode* newNode = (PduNode*)malloc(sizeof(PduNode));
        if (!newNode) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        newNode->pdu = pdus[i];
        newNode->next = manager->head;
        manager->head = newNode;

        addToCache(&manager->cacheHead, pdus[i].id, &pdus[i], manager->cacheSizeLimit); // Add to cache
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* getPduById(PduListManager* manager, int id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* cachedPdu = getFromCache(&manager->cacheHead, id);
    if (cachedPdu != NULL) {
        pthread_mutex_unlock(&manager->lock);
        return *cachedPdu;
    }

    PduNode* current = manager->head;
    while (current != NULL) {
        if (current->pdu.id == id) {
            // Update cache with accessed item
            addToCache(&manager->cacheHead, id, &current->pdu, manager->cacheSizeLimit);
            pthread_mutex_unlock(&manager->lock);
            return &current->pdu;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Cache helper functions
static void addToCache(CacheNode** cacheHead, int key, NFAPI_CRC_INDICATION_PDU_T* pdu, int cacheSizeLimit) {
    if (!cacheHead || !pdu) return;

    // Check for existing entry in cache
    CacheNode *current = *cacheHead, *prev = NULL;
    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // New entry
        CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
        newNode->key = key;
        newNode->pdu = pdu; // Assume deep copy is handled elsewhere

        newNode->next = *cacheHead;
        *cacheHead = newNode;

        if (newNode->next) {
            newNode->next->prev = newNode;
        }

        if (getCacheSize(*cacheHead) > cacheSizeLimit) {
            removeLeastRecentlyUsed(cacheHead); // Remove LRU item
        }
    } else { // Update existing entry
        current->pdu = pdu; // Assume deep copy is handled elsewhere
    }
}

static NFAPI_CRC_INDICATION_PDU_T* getFromCache(CacheNode** cacheHead, int key) {
    if (!cacheHead) return NULL;

    CacheNode *current = *cacheHead;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    if (current != NULL) {
        // Move to head for LRU update
        if (current->prev) {
            current->prev->next = current->next;
        } else {
            *cacheHead = current->next; // Remove from head
        }
        if (current->next) {
            current->next->prev = current->prev;
        }

        current->next = *cacheHead;
        if (*cacheHead) {
            (*cacheHead)->prev = current;
        }
        *cacheHead = current;

        return &(*current->pdu);
    }

    return NULL;
}

static void removePduNode(PduNode** head, PduNode* node) {
    if (!head || !node) return;

    if (*head == node) {
        *head = node->next;
    } else {
        PduNode* current = *head;
        while (current && current->next != node) {
            current = current->next;
        }
        if (current) {
            current->next = node->next;
        }
    }

    free(node);
}

static int getCacheSize(CacheNode* head) {
    int size = 0;
    CacheNode* current = head;
    while (current != NULL) {
        ++size;
        current = current->next;
    }
    return size;
}

static void removeLeastRecentlyUsed(CacheNode** cacheHead) {
    if (!cacheHead || !(*cacheHead)) return;

    CacheNode* lru = *cacheHead; // Assume the first is least recently used for simplicity
    if (lru && lru->next == NULL) { // Only one item in cache
        free(lru->pdu); // Free PDU memory
        free(lru);
        *cacheHead = NULL;
    } else {
        while (lru->next != NULL) {
            lru = lru->next; // Traverse to the end of list
        }
        if (lru->prev) {
            lru->prev->next = NULL;
        }

        free(lru->pdu); // Free PDU memory
        free(lru);
    }
}

