    if (dynamic_array) {
        free(dynamic_array->array);
        pthread_mutex_destroy(&dynamic_array->lock);
        free(dynamic_array);
    }
}

void populate_dynamic_array(DynamicArray *dynamic_array, const char *input_file) {
    FILE *file = fopen(input_file, "r");
    if (!file) {
        log_error("Failed to open input file.");
        return;
    }

    char line[1024];
    int line_count = 0;

    while (fgets(line, sizeof(line), file)) {
        pthread_mutex_lock(&dynamic_array->lock);

        size_t index = line_count % dynamic_array->length;
        sscanf(line, "%d %[^\n]", &dynamic_array->array[index].id, 
