#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int *value;
    size_t ref_count;
    int is_valid;
} record;

typedef struct {
    long *file_offsets;
    int *keys;
    record **records;
    pthread_mutex_t mutex;
} file_index_data;

void initialize_random_number_generator() {
    srand((unsigned int)time(NULL));
}

int generate_unique_random(int min, int max, int *used_values, size_t used_count) {
    int random_value;
    do {
        random_value = rand() % (max - min + 1) + min;
    } while (bsearch(&random_value, used_values, used_count, sizeof(int), cmpfunc));
    return random_value;
}

int cmpfunc(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

file_index_data* allocate_file_index_data(size_t num_records, int min_rand, int max_rand) {
    file_index_data *data = malloc(sizeof(file_index_data));
    if (!data) return NULL;

    pthread_mutex_init(&data->mutex, NULL);

    data->file_offsets = calloc(num_records, sizeof(long));
    if (!data->file_offsets) goto cleanup;

    data->keys = calloc(num_records, sizeof(int));
    if (!data->keys) goto cleanup;

    data->records = malloc(num_records * sizeof(record *));
    if (!data->records) goto cleanup;

    int *used_values = malloc(num_records * sizeof(int));
    if (!used_values) goto cleanup;

    initialize_random_number_generator();

    for (size_t i = 0; i < num_records; ++i) {
        data->records[i] = malloc(sizeof(record));
        if (!data->records[i]) goto cleanup;

        data->records[i]->value = malloc(sizeof(int));
        if (!data->records[i]->value) goto cleanup;

        int unique_value = generate_unique_random(min_rand, max_rand, used_values, i);
        *(data->records[i]->value) = unique_value;

        used_values[i] = unique_value;
        data->records[i]->ref_count = 1;
        data->records[i]->is_valid = 1;
    }

    free(used_values);
    return data;

cleanup:
    if (data) {
        if (data->file_offsets) free(data->file_offsets);
        if (data->keys) free(data->keys);
        for (size_t i = 0; i < num_records; ++i) {
            if (data->records && data->records[i]) {
                if (data->records[i]->value) free(data->records[i]->value);
                free(data->records[i]);
            }
        }
        if (data->records) free(data->records);
    }
    if (used_values) free(used_values);

    pthread_mutex_destroy(&data->mutex);
    free(data);
    return NULL;
}

void free_file_index_data(file_index_data *data) {
    if (!data) return;

    pthread_mutex_lock(&data->mutex);

    if (data->file_offsets) free(data->file_offsets);
    if (data->keys) free(data->keys);

    for (size_t i = 0; i < data->num_records && data->records[i]; ++i) {
        if (data->records[i]->value) {
            free(data->records[i]->value);
        }
        free(data->records[i]);
    }

    free(data->records);

    pthread_mutex_unlock(&data->mutex);
    pthread_mutex_destroy(&data->mutex);
    free(data);
}

