            usleep(backoffInterval * 1000); // Sleep with backoff
        }
    }

    pthread_mutex_unlock(&mutex);
    log_message("Failed to allocate memory after multiple attempts.");
    return NULL;
}

// Example usage
int main() {
    int N = 500; // This would be user input in a real scenario
    NFAPI_CRC_INDICATION_PDU_T *indicationArray = allocate_and_populate_crc_indications(N);

    if (indicationArray != NULL) {
        log_message("Memory allocated and populated successfully.");
        free(indicationArray); // Don't forget to free the memory when done
    } else {
        log_message("Failed to allocate memory for CRC indications.");
    }

    return 0;
}
```

### Documentation for Configuration Parameters

- **maxAllowedElements**: Defines the maximum number of `NFAPI_CRC_INDICATION_PDU_T` structures that can be allocated. This limit prevents excessive memory usage and should be set based on system resource constraints.

- **retryAttempts**: Number of times the function will attempt to allocate memory in case of failure before giving up. This helps handle temporary allocation issues.

- **backoffInterval**: Time (in milliseconds) to wait between retry attempts after a failed allocation. This interval helps reduce CPU usage during retries and can be adjusted based on system performance needs.

These parameters should be configurable through a configuration file or environment variables for easy adjustments without modifying the source code.']

