void initialize_system(int *max_offsets, long **offsets, int **keys, record ***records, int seed) {
    if (seed == -1) {
        srand(time(NULL));
    } else {
        srand(seed);
    }

    // Allocate memory for offsets and initialize with random values
    *offsets = (long *)malloc(*max_offsets * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < *max_offsets; i++) {
        (*offsets)[i] = rand() % (MAX_RANDOM_OFFSET + 1);
    }

    // Allocate memory for keys and ensure uniqueness
    *keys = (int *)malloc(*max_offsets * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    int used_keys[*max_offsets] = {0};
    for (int i = 0; i < *max_offsets; i++) {
        do {
            (*keys)[i] = rand() % *max_offsets + 1;
        } while (used_keys[(*keys)[i] - 1]);
        used_keys[(*keys)[i] - 1] = 1;
    }

    // Allocate memory for records and initialize with random values
    *records = (record **)malloc(*max_offsets * sizeof(record *));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < *max_offsets; i++) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record at index %d.\n", i);
            // Free previously allocated memory
            while (--i >= 0) {
                free((*records)[i]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            exit(EXIT_FAILURE);
        }
        (*records)[i]->value = rand() % (MAX_RANDOM_VALUE + 1);
    }
}

void free_system(long *offsets, int *keys, record **records, int max_offsets) {
    for (int i = 0; i < max_offsets; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(offsets);
    free(keys);
    free(records);
}
