#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_REQUESTS 20000

typedef struct {
    int ue_id;
    char nas_message[256];
    int gmm_state_indicator;
} SessionRequest;

typedef struct {
    SessionRequest *requests;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} RequestList;

unsigned long calculate_hash(const char *nas_message) {
    unsigned long hash = 5381;
    int c;
    while ((c = *nas_message++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

void validate_request(SessionRequest *request, const char *signature) {
    unsigned long request_hash = calculate_hash(request->nas_message);
    if (request_hash != strtoul(signature, NULL, 10)) {
        fprintf(stderr, "Invalid request: Hash mismatch\n");
        exit(EXIT_FAILURE);
    }
}

int compare_requests(const void *a, const void *b) {
    SessionRequest *reqA = (SessionRequest *)a;
    SessionRequest *reqB = (SessionRequest *)b;
    return reqA->ue_id - reqB->ue_id; // Sorting by UE ID for simplicity
}

void resize_request_list(RequestList *list) {
    size_t new_capacity = list->capacity * 2;
    if (new_capacity > MAX_REQUESTS)
        new_capacity = MAX_REQUESTS;

    SessionRequest *new_requests = realloc(list->requests, new_capacity * sizeof(SessionRequest));
    if (!new_requests) {
        perror("Failed to resize request list");
        exit(EXIT_FAILURE);
    }

    list->requests = new_requests;
    list->capacity = new_capacity;
}

void add_request(RequestList *list, SessionRequest request, const char *signature) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resize_request_list(list);
    }

    validate_request(&request, signature);
    list->requests[list->size++] = request;

    qsort(list->requests, list->size, sizeof(SessionRequest), compare_requests);

    pthread_mutex_unlock(&list->lock);
}

void process_requests(RequestList *list) {
    // Placeholder for processing logic
    printf("Processing %zu requests\n", list->size);
}

int main() {
    RequestList list = {NULL, 0, INITIAL_CAPACITY};
    pthread_mutex_init(&list.lock, NULL);

    char nas_signature[] = "123456789"; // Example signature

    SessionRequest req1 = {1, "NAS message 1", 0};
    add_request(&list, req1, nas_signature);

    process_requests(&list);

    free(list.requests);
    pthread_mutex_destroy(&list.lock);

    return 0;
}
```

