['Below is a C implementation for managing a dynamically resizable list of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified conditions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MAX_SIZE 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ResizableList;

// Logging function
void log_error(const char* message) {
    printf("ERROR: %s\n", message);
}

ResizableList* create_list() {
    ResizableList* list = (ResizableList*)malloc(sizeof(ResizableList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = INITIAL_SIZE;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_list(ResizableList* list) {
    size_t new_capacity = (list->capacity < MAX_SIZE) ? list->capacity * 2 : MAX_SIZE;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;

    list->data = new_data;
    list->capacity = new_capacity;
}

bool is_valid_rnti(uint16_t rnti) {
    return (rnti >= 0x0001 && rnti <= 0xFFFF);
}

void add_pdu(ResizableList* list, uint32_t rx_ue_tag, uint16_t rnti, uint8_t crc_rel8_tag) {
    pthread_mutex_lock(&list->lock);

    if (!is_valid_rnti(rnti)) {
        log_error("Invalid RNTI value");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->size >= list->capacity) {
        resize_list(list);
        if (list->size >= list->capacity) { // Check again after resizing
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {
        .RX_UE_INFORMATION_TAG = rx_ue_tag,
        .RNTI = rnti,
        .CRC_INDICATION_REL8_TAG = crc_rel8_tag,
        .CRCFLAG = rand() % 2
    };

    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
}

void free_list(ResizableList* list) {
    if (list) {
        if (list->data) free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Unit tests
void test_add_valid_pdu() {
    ResizableList* list = create_list();
    add_pdu(list, 12345, 0x0001, 10);
    printf("Test Add Valid PDU: %zu\n", list->size); // Expected: 1
    free_list(list);
}

void test_add_invalid_pdu() {
    ResizableList* list = create_list();
    add_pdu(list, 12345, 0x0000, 10); // Invalid RNTI
    printf("Test Add Invalid PDU: %zu\n", list->size); // Expected: 0
    free_list(list);
}

void test_resize() {
    ResizableList* list = create_list();
    for (int i = 0; i < INITIAL_SIZE + 5; ++i) {
        add_pdu(list, i, 0x0001 + i, i % 256);
    }
    printf("Test Resize: %zu\n", list->size); // Expected: INITIAL_SIZE + 5
    free_list(list);
}

int main() {
    srand(time(NULL));

    test_add_valid_pdu();
    test_add_invalid_pdu();
    test_resize();

    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex` for thread-safe access to the list.
- **Dynamic Resizing**: Doubles the capacity when needed, up to a maximum of 10,000 elements.
- **Validation and Logging**: Validates RNTI values and logs errors without stopping execution.
- **Memory Management**: Properly allocates, resizes, and frees memory to prevent leaks.
- **Unit Tests**: Includes tests for adding valid/invalid PDUs and resizing the list.']

