import stdlib.h> // For realloc()
#include <pthread.h>
#include <time.h>

typedef struct {
    double value;
} Data;

typedef struct {
    int *offsets;
    size_t offset_size;
    int *keys;
    size_t key_size;
    Data *data;
    size_t data_size;
    pthread_mutex_t lock; // For thread safety
} DataManager;

// Simulated external API function
double getRandomDoubleInRange(double min, double max) {
    return (rand() / (RAND_MAX + 1.0)) * (max - min) + min;
}

void logMemoryUsage(const char* message, size_t memoryUsed) {
    printf("%s: %zu bytes\n", message, memoryUsed);
}

void initDataManager(DataManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->offsets = malloc(sizeof(int));
    manager->keys = malloc(sizeof(int));
    manager->data = malloc(sizeof(Data));

    if (!manager->offsets || !manager->keys || !manager->data) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }

    manager->offset_size = 1;
    manager->key_size = 1;
    manager->data_size = 1;
}

void freeDataManager(DataManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->offsets) free(manager->offsets);
    if (manager->keys) free(manager->keys);
    if (manager->data) free(manager->data);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

void resizeDataManager(DataManager *manager, size_t new_data_size) {
    pthread_mutex_lock(&manager->lock);

    manager->offsets = realloc(manager->offsets, sizeof(int) * (new_data_size + 1));
    manager->keys = realloc(manager->keys, sizeof(int) * new_data_size);
    manager->data = realloc(manager->data, sizeof(Data) * new_data_size);

    if (!manager->offsets || !manager->keys || !manager->data) {
        perror("Failed to resize memory");
        exit(EXIT_FAILURE);
    }

    // Update sizes
    manager->data_size = new_data_size;
    manager->key_size = new_data_size;
    manager->offset_size = new_data_size + 1;

    logMemoryUsage("After resizing", sizeof(int) * (manager->offset_size) +
                   sizeof(int) * manager->key_size +
                   sizeof(Data) * manager->data_size);

    pthread_mutex_unlock(&manager->lock);
}

void populateDataWithRandomValues(DataManager *manager, double min, double max) {
    for (size_t i = 0; i < manager->data_size; ++i) {
        manager->data[i].value = getRandomDoubleInRange(min, max);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    DataManager manager;
    initDataManager(&manager);

    size_t newSize = 10;
    resizeDataManager(&manager, newSize);
    populateDataWithRandomValues(&manager, 0.0, 1.0);

    freeDataManager(&manager);

    return 0;
}
