    for (size_t i = 0; i < size; ++i) {
        scanf("%d", &array[i]);
    }

    // Sort the array
    qsort(array, size, sizeof(int), (__compar_fn_t)int_comparator);

    int median;
    if (size % 2 == 0) {
        median = (array[size / 2 - 1] + array[size / 2]) / 2;
    } else {
