```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the structure for CRC indication
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG : 1; // Assuming CRCFLAG is a single-bit flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for record management
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Function to manage dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int count, unsigned int seed) {
    if (count > 10000) {
        fprintf(stderr, "Error: Maximum element limit exceeded.\n");
        return NULL;
    }

    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed for CRC indications array");
        return NULL;
    }

    printf("Allocated memory for %d CRC indications.\n", count);

    for (int i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        array[i].RNTI = rand() % 10000 + 1;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return array;
}

// Helper function to check if an offset exists in the hash table
int offset_exists(unsigned long *hashTable, unsigned int size, long offset) {
    unsigned int index = offset % size;
    while (hashTable[index] != 0) {
        if (hashTable[index] == offset) {
            return 1; // Found
        }
        index = (index + 1) % size; // Linear probing
    }
    return 0; // Not found
}

// Function to manage records with unique offsets using a hash table for uniqueness check
Record* create_records(int count, double minVal, double maxVal, unsigned int seed) {
    if (count <= 0 || minVal >= maxVal) {
        fprintf(stderr, "Error: Invalid parameters for record creation.\n");
        return NULL;
    }

    srand(seed);

    // Define hash table size and initialize
    const unsigned int hashTableSize = count * 2; // Reduce collision probability
    unsigned long *hashTable = calloc(hashTableSize, sizeof(unsigned long));
    if (!hashTable) {
        perror("Memory allocation failed for hash table");
        return NULL;
    }

    printf("Allocated memory for hash table of size %u.\n", hashTableSize);

    Record *records = malloc(count * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed for records array");
        free(hashTable);
        return NULL;
    }

    printf("Allocated memory for %d records.\n", count);

    for (int i = 0; i < count; ++i) {
        long offset;

        do {
            offset = rand() % (10000000 - 1) + 1; // Ensure positive non-zero offsets
        } while (offset_exists(hashTable, hashTableSize, offset));

        records[i].offset = offset;
        records[i].key = rand() % 10000 + 1;
        records[i].value = minVal + ((double)rand() / RAND_MAX) * (maxVal - minVal);

        // Insert into hash table
        unsigned int index = offset % hashTableSize;
        while (hashTable[index] != 0) {
            if (index == (offset % hashTableSize)) {
                fprintf(stderr, "Error: Collision detected in hash table.\n");
                free(records);
                free(hashTable);
                return NULL;
            }
            index = (index + 1) % hashTableSize;
        }

        hashTable[index] = offset;
    }

    free(hashTable);

    printf("Created %d unique records with offsets.\n", count);

    return records;
}

// Function to free resources allocated for CRC indications
void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
        printf("Freed memory for CRC indications array.\n");
    }
}

// Function to free resources allocated for records
void free_records(Record *records) {
    if (records) {
        free(records);
        printf("Freed memory for records array.\n");
    }
}
```

### Explanation

- **NFAPI_CRC_INDICATION_PDU_T and Record Structures**: These structures are defined to hold the necessary fields. Each `CRCFLAG` is assumed as a single bit, which can be represented in different ways.

- **create_crc_indications Function**: Manages an array of CRC indications with robust error handling for memory allocation failures, ensuring not more than 10,000 elements and logging allocations.

- **offset_exists and create_records Functions**: Use a simple hash table (with linear probing) to ensure uniqueness of offsets. The records are dynamically allocated and initialized with random values within the specified range.

- **Memory Management**: `free_crc_indications` and `free_records` functions handle memory deallocation, ensuring no leaks occur, with logs for debugging purposes.

This code should integrate well into larger systems requiring efficient management of large datasets while maintaining performance under expected loads.']

