```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDU_COUNT 1000

typedef struct {
    int valid;
} RX_UE_INFORMATION_TAG;

typedef unsigned int RNTI;

typedef struct {
    int crc_flag; // CRC flag, randomly set
} CRC_INDICATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_TAG crc_indication_tag;
} NFAPI_LTE_PDU;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    pthread_mutex_lock(&mutex);
    printf("%s\n", message); // Simple logging to stdout
    pthread_mutex_unlock(&mutex);
}

int init_pdus(NFAPI_LTE_PDU **pdus, int count) {
    if (count <= 0 || count > MAX_PDU_COUNT) {
        log_message("Invalid PDU count requested.");
        return -1;
    }

    *pdus = malloc(count * sizeof(NFAPI_LTE_PDU));
    if (*pdus == NULL) {
        log_message("Memory allocation failed.");
        return -1;
    }

    srand(time(NULL)); // Seed for random number generation

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; ++i) {
        (*pdus)[i].rx_ue_info_tag.valid = 1;
        (*pdus)[i].rnti = rand() % UINT_MAX;
        (*pdus)[i].crc_indication_tag.crc_flag = rand() % 2; // Randomly set CRC flag
    }
    pthread_mutex_unlock(&mutex);

    log_message("PDUs initialized successfully.");
    return 0;
}

void free_pdus(NFAPI_LTE_PDU *pdus) {
    if (pdus != NULL) {
        free(pdus);
        log_message("Memory freed for PDUs.");
    }
}
