unsigned int rand_uint(unsigned int max_val) {
    return rand() % (max_val + 1);
}

// Function to dynamically create and populate the list of structures
NFAPI_CRC_INDICATION_PDU_T* create_filtered_nfa_pids(int N, unsigned int crc_threshold, unsigned int *final_count) {
    if (N <= 0 || final_count == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T **array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!array) return NULL;

    for (int i = 0; i < N; ++i) {
        array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            // Free previously allocated memory in case of failure
            while (--i >= 0) free(array[i]);
            free(array);
            return NULL;
        }

        // Populate structure with random values
        array[i]->RX_UE_INFORMATION_TAG = rand_uint(UINT_MAX);
        array[i]->RNTI = rand_uint(UINT_MAX);
        array[i]->crc_indication.CRCFLAG = rand_uint(255);  // Random CRCFLAG between 0 and 255

        printf("Created structure %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n", 
            i + 1, array[i]->RX_UE_INFORMATION_TAG, array[i]->RNTI, array[i]->crc_indication.CRCFLAG);
    }

    // Filtering based on the CRC threshold
    NFAPI_CRC_INDICATION_PDU_T **filtered = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    int filtered_count = 0;

    for (int i = 0; i < N; ++i) {
        if (array[i]->crc_indication.CRCFLAG >= crc_threshold) {
            bool duplicate_found = false;

            // Check for duplicates in the filtered list
            for (int j = 0; j < filtered_count; ++j) {
                if (filtered[j]->RNTI == array[i]->RNTI) {
                    duplicate_found = true;
