// Custom memory allocator (simple example)
#define MEMORY_POOL_SIZE 1024 * 1024 // 1MB
static char memory_pool[MEMORY_POOL_SIZE];
static size_t memory_offset = 0;
pthread_mutex_t memory_allocator_lock = PTHREAD_MUTEX_INITIALIZER;

void* custom_malloc(size_t size) {
    pthread_mutex_lock(&memory_allocator_lock);
    if (memory_offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&memory_allocator_lock);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[memory_offset];
    memory_offset += size;
    pthread_mutex_unlock(&memory_allocator_lock);
    return ptr;
}

void custom_free(void*) {
    // No-op for this simple allocator
}

// Logging mechanism with verbosity levels
typedef enum { DEBUG, INFO, WARN, ERROR } LogLevel;

typedef struct {
    char buffer[256];
    LogLevel level;
} LogEntry;

static pthread_rwlock_t log_lock = PTHREAD_RWLOCK_INITIALIZER;
static LogEntry log_buffer[1000];  // Example buffer size
static int log_index = 0;

void log_message(LogLevel level, const char* message) {
    pthread_rwlock_wrlock(&log_lock);
    if (level >= INFO && log_index < 1000) { // Adjust verbosity threshold as needed
        snprintf(log_buffer[log_index].buffer, sizeof(log_buffer[log_index].buffer), "%s", message);
        log_buffer[log_index].level = level;
        log_index++;
    }
    pthread_rwlock_unlock(&log_lock);
}

// Thread-safe dynamic array management with resizing capability
typedef struct {
    NFAPI_LTE_PDU* pdus;
    size_t capacity;
    size_t count;
    pthread_rwlock_t rwlock;
} PduArray;

PduArray* initialize_pdu_array(size_t initial_capacity) {
    PduArray* pdu_array = (PduArray*)custom_malloc(sizeof(PduArray));
    if (!pdu_array) return NULL;

    pdu_array->pdus = (NFAPI_LTE_PDU*)custom_malloc(initial_capacity * sizeof(NFAPI_LTE_PDU));
    if (!pdu_array->pdus) {
        custom_free(pdu_array);
        return NULL;
    }

    pdu_array->capacity = initial_capacity;
    pdu_array->count = 0;
    pthread_rwlock_init(&pdu_array->rwlock, NULL);

    log_message(INFO, "PDU array initialized.");
    return pdu_array;
}

int resize_pdu_array(PduArray* pdu_array, size_t new_capacity) {
    pthread_rwlock_wrlock(&pdu_array->rwlock);
    NFAPI_LTE_PDU* new_pdus = (NFAPI_LTE_PDU*)custom_malloc(new_capacity * sizeof(NFAPI_LTE_PDU));
    if (!new_pdus) {
        pthread_rwlock_unlock(&pdu_array->rwlock);
        return -1; // Out of memory
    }

    memcpy(new_pdus, pdu_array->pdus, pdu_array->count * sizeof(NFAPI_LTE_PDU));
    custom_free(pdu_array->pdus);
    pdu_array->pdus = new_pdus;
    pdu_array->capacity = new_capacity;

    log_message(INFO, "PDU array resized.");
    pthread_rwlock_unlock(&pdu_array->rwlock);
    return 0;
}

int populate_pdu(PduArray* pdu_array) {
    if (!pdu_array) return -1; // Invalid argument

    pthread_rwlock_wrlock(&pdu_array->rwlock);
    if (pdu_array->count >= pdu_array->capacity) {
        int resize_result = resize_pdu_array(pdu_array, pdu_array->capacity * 2);
        if (resize_result != 0) {
            pthread_rwlock_unlock(&pdu_array->rwlock);
            return -1; // Out of memory
        }
    }

    NFAPI_LTE_PDU* pdu = &pdu_array->pdus[pdu_array->count];
    snprintf(pdu->rx_ue_info.rx_ue_information_tag, sizeof(pdu->rx_ue_info.rx_ue_information_tag), "UE_Info_%zu", pdu_array->count);
    pdu->rnti = rand() % 0xFFFF;
    pdu->crc_indication.crc_flag = rand() % 2;

    pdu_array->count++;
    pthread_rwlock_unlock(&pdu_array->rwlock);

    log_message(DEBUG, "PDU populated.");
    return 0;
}

void cleanup_pdu_array(PduArray* pdu_array) {
    if (!pdu_array) return;

    pthread_rwlock_wrlock(&pdu_array->rwlock);
    custom_free(pdu_array->pdus);
    pthread_rwlock_unlock(&pdu_array->rwlock);

    pthread_rwlock_destroy(&pdu_array->rwlock);
    custom_free(pdu_array);
}

// Main function for demonstration
int main() {
    srand(time(NULL));  // Seed the random number generator

    PduArray* pdu_array = initialize_pdu_array(10);
    if (!pdu_array) {
        log_message(ERROR, "Failed to initialize PDU array.");
        return -1;
    }

    for (size_t i = 0; i < 20; ++i) { // Example: populate more than initial capacity
        if (populate_pdu(pdu_array) != 0) {
            log_message(WARN, "Failed to populate PDU. Possible out-of-memory.");
            break;
        }
    }

    cleanup_pdu_array(pdu_array);
    return 0;
}
