typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock; // For thread-safe operations
} RecordManager;

// Function prototypes for memory management and storage integration
int allocateRecords(RecordManager *manager, size_t num_records, size_t total_memory_budget);
void initializeRecords(RecordManager *manager);
void releaseMemory(RecordManager *manager);
void persistToStorage(const RecordManager *manager);

// Implementation of the function
int allocateRecords(RecordManager *manager, size_t num_records, size_t total_memory_budget) {
    if (num_records == 0 || total_memory_budget < sizeof(RecordManager)) {
        return -1; // Invalid input
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->records = NULL;
    manager->count = 0;
    manager->capacity = 0;

    size_t record_size = sizeof(Record);
    size_t overhead = sizeof(*manager) + num_records * sizeof(int) + num_records * sizeof(long);

    if (overhead > total_memory_budget || (num_records * record_size) + overhead > total_memory_budget) {
        return -1; // Not enough memory
    }

    manager->capacity = num_records;
    manager->records = (Record *)malloc(num_records * record_size);
    if (!manager->records) {
        releaseMemory(manager); // Fallback strategy: clean up
        pthread_mutex_destroy(&manager->lock);
        return -1; // Allocation failed
    }

    initializeRecords(manager);

    persistToStorage(manager); // Integration with external storage

    return 0;
}

void initializeRecords(RecordManager *manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->records[i].key = i + 1; // Unique key starting from 1
        manager->records[i].offset = (long)i * 100; // Example offset initialization
    }
    manager->count = manager->capacity;
}

void releaseMemory(RecordManager *manager) {
