#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define HEADER_SIZE sizeof(Header)
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    char *payload;
    size_t payload_size;
    uint32_t checksum;
} Header;

typedef struct Node {
    Header header;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} HeaderCollection;

uint32_t calculate_checksum(const void *data, size_t length) {
    const unsigned char *bytes = data;
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += bytes[i];
    }
    return checksum;
}

void verify_integrity(Header *header) {
    if (header->checksum != calculate_checksum(header->payload, header->payload_size)) {
        fprintf(stderr, "Integrity check failed for payload\n");
    }
}

void free_headers(HeaderCollection *collection) {
    Node *current = collection->head;
    while (current) {
        Node *next = current->next;
        free(current->header.payload);
        free(current);
        current = next;
    }
    collection->head = NULL;
}

HeaderCollection* create_collection() {
    HeaderCollection *collection = malloc(sizeof(HeaderCollection));
    if (!collection) {
        perror("Failed to allocate memory for header collection");
        return NULL;
    }
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(HeaderCollection *collection) {
    free_headers(collection);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_header(HeaderCollection *collection, const void *payload_data, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Payload size exceeds maximum limit\n");
        return -1;
    }

    pthread_mutex_lock(&collection->lock);

    Header header = {0};
    header.payload = malloc(payload_size);
    if (!header.payload) {
        perror("Failed to allocate memory for payload");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    memcpy(header.payload, payload_data, payload_size);
    header.payload_size = payload_size;
    header.checksum = calculate_checksum(header.payload, payload_size);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        free(header.payload);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    new_node->header = header;
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_header(HeaderCollection *collection, Node *node, const void *payload_data, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Payload size exceeds maximum limit\n");
        return -1;
    }

    pthread_mutex_lock(&collection->lock);

    free(node->header.payload);
    node->header.payload = malloc(payload_size);
    if (!node->header.payload) {
        perror("Failed to allocate memory for payload");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    memcpy(node->header.payload, payload_data, payload_size);
    node->header.payload_size = payload_size;
    node->header.checksum = calculate_checksum(node->header.payload, payload_size);

    verify_integrity(&node->header);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void recalculate_checksums(HeaderCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current) {
        current->header.checksum = calculate_checksum(current->header.payload, current->header.payload_size);
        verify_integrity(&current->header);
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

int main() {
    HeaderCollection *collection = create_collection();
    if (!collection) return EXIT_FAILURE;

    const char payload1[] = "Example payload 1";
    add_header(collection, payload1, sizeof(payload1));

    recalculate_checksums(collection);

    // Example of updating a header
    Node *node_to_update = collection->head;
    const char updated_payload[] = "Updated payload";
    update_header(collection, node_to_update, updated_payload, sizeof(updated_payload));

    destroy_collection(collection);
    return EXIT_SUCCESS;
}
```

