    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    uint8_t CRCFLAG; // Assume it's a single byte for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

uint8_t generate_differing_crc_flag(uint8_t previous_flag) {
    // Flip at least one bit to ensure difference
    return previous_flag ^ (1 << (rand() % 8));
}

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

int add_crc_pdu(DynamicArray* arr, uint16_t rx_ue_tag, uint16_t rnti) {
    if (!arr || rnti > MAX_RNTI) return -1;

    pthread_mutex_lock(&arr->lock);

    if (arr->size == 0) {
        arr->array[arr->size].crc_tag.RX_UE_INFORMATION_TAG = rx_ue_tag;
        arr->array[arr->size].crc_tag.RNTI = rnti;
        arr->array[arr->size].CRCFLAG = rand() % 256;
    } else {
        if (arr->capacity == arr->size) {
            size_t new_capacity = arr->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) {
                pthread_mutex_unlock(&arr->lock);
                return -1;
            }
            arr->array = new_array;
            arr->capacity = new_capacity;
        }

        uint8_t previous_flag = arr->array[arr->size - 1].CRCFLAG;
        arr->array[arr->size].crc_tag.RX_UE_INFORMATION_TAG = rx_ue_tag;
        arr->array[arr->size].crc_tag.RNTI = rnti;
        arr->array[arr->size].CRCFLAG = generate_differing_crc_flag(previous_flag);
    }

    ++arr->size;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int remove_crc_pdu(DynamicArray* arr, size_t index) {
    if (!arr || index >= arr->size) return -1;

    pthread_mutex_lock(&arr->lock);

    memmove(&arr->array[index], &arr->array[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --arr->size;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_pdu(DynamicArray* arr, size_t index) {
    if (!arr || index >= arr->size) return NULL;

    pthread_mutex_lock(&arr->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &arr->array[index];

    pthread_mutex_unlock(&arr->lock);
    return pdu;
}

void free_dynamic_array(DynamicArray* arr) {
    if (!arr) return;

    pthread_mutex_destroy(&arr->lock);
    free(arr->array);
    free(arr);
}
```

### Key Points:
- **Memory Management**: Uses `calloc` and `realloc` to manage dynamic memory, ensuring no leaks.
- **Concurrency**: Utilizes a mutex (`pthread_mutex_t`) for thread-safe operations.
- **CRC Flag Generation**: Ensures CRC flags differ by at least one bit using bitwise XOR.
- **Error Handling**: Returns `-1` on errors such as invalid indices or memory allocation failures.
- **Scalability**: Supports dynamic resizing of the array to accommodate more elements."]

