#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_BUFFER_SIZE 1024
#define MAX_RETRY_COUNT 3

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list_mutex);
    if (list->size >= list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list_mutex);
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list_mutex);
    free(list->data);
    free(list);
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = rand();
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    return pdu;
}

int serialize_list(DynamicList *list, unsigned char **buffer, size_t *length) {
    pthread_mutex_lock(&list_mutex);
    size_t required_size = sizeof(size_t) + list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (unsigned char*)malloc(required_size);
    if (!*buffer) {
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    *((size_t*)(*buffer)) = list->size;
    memcpy(*buffer + sizeof(size_t), list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *length = required_size;

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

void log_memory_usage(const char *message) {
    size_t used_memory = sizeof(DynamicList) + sizeof(NFAPI_CRC_INDICATION_PDU_T) * 100; // Example usage
    printf("%s: Memory Usage = %zu bytes\n", message, used_memory);
}

int main() {
    srand(time(NULL));

    DynamicList *list = create_dynamic_list(INITIAL_BUFFER_SIZE);

    for (int i = 0; i < 500; ++i) {
        add_pdu(list, generate_random_pdu(i));
    }

    unsigned char *buffer;
    size_t length;
    if (serialize_list(list, &buffer, &length) == 0) {
        printf("Serialized data length: %zu\n", length);
    } else {
        printf("Serialization failed.\n");
    }

    free(buffer);
    free_dynamic_list(list);

    log_memory_usage("Final Memory Usage");

    return 0;
}
```

