#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_ELEMENTS];
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    int head, tail;
    size_t cache_size;
    NFAPI_CRC_INDICATION_PDU_T *cache[MAX_ELEMENTS / 10]; // Cache to store recently accessed structures
} CRC_List;

CRC_List* create_crc_list(size_t initial_capacity) {
    CRC_List *list = (CRC_List *)malloc(sizeof(CRC_List));
    list->size = 0;
    list->capacity = initial_capacity;
    for (size_t i = 0; i < list->capacity; ++i) {
        list->data[i] = NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->head = 0;
    list->tail = 0;
    list->cache_size = 0;
    return list;
}

uint32_t polynomial_crc(uint32_t crc_tag) {
    uint32_t polynomial = 0xEDB88320;
    crc_tag ^= 0xFFFFFFFF;
    for (int i = 0; i < 32; ++i) {
        if (crc_tag & 1) {
            crc_tag = (crc_tag >> 1) ^ polynomial;
        } else {
            crc_tag >>= 1;
        }
    }
    return crc_tag ^ 0xFFFFFFFF;
}

void add_element(CRC_List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = (NFAPI_CRC_INDICATION_PDU_T **)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * list->capacity);
        memset(&list->data[list->size], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list->capacity - list->size));
    }

    element.CRC_INDICATION_REL8_TAG = polynomial_crc(element.CRC_INDICATION_REL8_TAG);

    list->data[list->tail] = &element;
    list->tail = (list->tail + 1) % list->capacity;
    ++list->size;

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(CRC_List *list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index < list->size) {
        NFAPI_CRC_INDICATION_PDU_T *element = list->data[(list->head + index) % list->capacity];

        // Cache the element
        if (list->cache_size < (list->capacity / 10)) {
            list->cache[list->cache_size++] = element;
        } else {
            for (size_t i = 0; i < list->cache_size - 1; ++i) {
                list->cache[i] = list->cache[i + 1];
            }
            list->cache[list->cache_size - 1] = element;
        }

        pthread_mutex_unlock(&list->mutex);
        return *element;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void remove_element(CRC_List *list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index < list->size) {
        list->data[list->head] = NULL;
        list->head = (list->head + 1) % list->capacity;
        --list->size;

        pthread_cond_signal(&list->cond_var);
    }

    pthread_mutex_unlock(&list->mutex);
}

void destroy_crc_list(CRC_List *list) {
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond_var);
    free(list->data);
    free(list);
}

