typedef struct Node {
    MACEntityStatus data;
    struct Node *next, *prev;
} Node;

typedef struct {
    Node **buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash_function(int id) {
    return (id * 2654435761u) % MAX_ENTITIES; // FNV-1a-like simple hash
}

HashTable* create_table(size_t initial_capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }
    table->capacity = initial_capacity > 0 ? initial_capacity : INITIAL_CAPACITY;
    table->buckets = calloc(table->capacity, sizeof(Node*));
    if (!table->buckets) {
        fprintf(stderr, "Memory allocation failed for buckets\n");
        free(table);
        return NULL;
    }
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_table(HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        Node *current = table->buckets[i];
        while (current) {
            Node *next = current->next;
            free(current);
            current = next;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void resize_table(HashTable *table);

int insert_entity(HashTable *table, int id, void* config_params, int status_flag) {
    if (pthread_mutex_lock(&table->lock) != 0) {
        fprintf(stderr, "Failed to lock the table\n");
        return -1;
    }

    if (table->count >= table->capacity * 0.7) {
        resize_table(table);
    }

    unsigned long index = hash_function(id);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node\n");
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    new_node->data.id = id;
    new_node->data.config_params = config_params;
    new_node->data.status_flag = status_flag;

    Node *head = table->buckets[index];
    new_node->next = head;
    if (head) {
        head->prev = new_node;
    }
    table->buckets[index] = new_node;
    ++table->count;

    pthread_mutex_unlock(&table->lock);
    return 0;
}

MACEntityStatus* find_entity(HashTable *table, int id) {
    unsigned long index = hash_function(id);

    for (Node *current = table->buckets[index]; current; current = current->next) {
        if (current->data.id == id) {
            return &(current->data);
        }
    }
    return NULL;
}

void resize_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2 > MAX_ENTITIES ? MAX_ENTITIES : table->capacity * 2;
    Node **new_buckets = calloc(new_capacity, sizeof(Node*));
    if (!new_buckets) {
        fprintf(stderr, "Memory allocation failed during resize\n");
        return;
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        Node *current = table->buckets[i];
        while (current) {
            Node *next = current->next;

            unsigned long new_index = hash_function(current->data.id) % new_capacity;
            current->next = new_buckets[new_index];
            if (new_buckets[new_index]) {
                new_buckets[new_index]->prev = current;
            }
            new_buckets[new_index] = current;
            current = next;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void synchronize_data(HashTable *table) {
    // Placeholder for integration logic with external network management system
    // This function should handle data synchronization and deal with latency/transient failures.
}

// Main entry point to test functionality (not part of the module)
int main() {
    HashTable *status_table = create_table(INITIAL_CAPACITY);

    if (!status_table) return 1;

    int config_param_example = 42;
    insert_entity(status_table, 12345, &config_param_example, 1);

    MACEntityStatus* status = find_entity(status_table, 12345);
    if (status) {
        printf("Entity ID: %d, Status Flag: %d\n", status->id, status->status_flag);
    }

    synchronize_data(status_table); // Synchronize with external system

    destroy_table(status_table);

    return 0;
}
