#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListEntry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct ListEntry *next;
} ListEntry;

typedef struct {
    ListEntry *head;
    size_t count;
    int crc_count[MAX_ENTRIES]; // Track valid CRC indications per RNTI
} DynamicList;

void init_list(DynamicList *list) {
    list->head = NULL;
    list->count = 0;
    memset(list->crc_count, 0, sizeof(list->crc_count));
}

int is_full(DynamicList *list) {
    return list->count >= MAX_ENTRIES;
}

void remove_oldest_entry(DynamicList *list) {
    if (list->head == NULL) return;

    ListEntry *temp = list->head;
    list->head = list->head->next;
    free(temp);
    --list->count;
}

void add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (is_full(list)) remove_oldest_entry(list);

    ListEntry *new_entry = malloc(sizeof(ListEntry));
    new_entry->pdu = pdu;
    new_entry->next = list->head;
    list->head = new_entry;
    ++list->count;

    // Random CRCFLAG for demonstration purposes
    pdu.CRC_INDICATION_REL8_TAG = rand() % 2;
    if (pdu.CRC_INDICATION_REL8_TAG) {
        list->crc_count[pdu.RNTI]++;
    }
}

void remove_entry_by_rnti(DynamicList *list, unsigned int rnti) {
    ListEntry **current = &list->head;

    while (*current != NULL) {
        if ((*current)->pdu.RNTI == rnti) {
            ListEntry *to_remove = *current;
            *current = to_remove->next;
            free(to_remove);

            // Update CRC count
            list->crc_count[rnti]--;
            --list->count;

            return; // Remove the first match only
        }
        current = &(*current)->next;
    }
}

void print_rx_ue_information_tags(DynamicList *list) {
    ListEntry *current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u\n", current->pdu.RX_UE_INFORMATION_TAG);
        current = current->next;
    }
}

void export_to_binary_file(const char *filename, DynamicList *list) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(size_t), 1, file);

    ListEntry *current = list->head;
    while (current != NULL) {
        fwrite(&(current->pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

void import_from_binary_file(const char *filename, DynamicList *list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    // Clear current list
    while (list->head != NULL) remove_oldest_entry(list);

    for (size_t i = 0; i < count && !is_full(list); ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        add_entry(list, pdu);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    DynamicList list;
    init_list(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 456 };
    add_entry(&list, pdu);
    print_rx_ue_information_tags(&list);

    export_to_binary_file("export.bin", &list);
    DynamicList new_list;
    init_list(&new_list);
    import_from_binary_file("export.bin", &new_list);
    print_rx_ue_information_tags(&new_list);

    remove_entry_by_rnti(&list, 456);
    print_rx_ue_information_tags(&list);

    return 0;
}
