#define LOG_LEVEL_DEV 0
#define LOG_LEVEL_TEST 1
#define LOG_LEVEL_PROD 2

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
