typedef struct {
    size_t total_allocated;
    pthread_mutex_t lock;
} MemoryPoolStats;

MemoryPoolStats pool_stats = {0, PTHREAD_MUTEX_INITIALIZER};

void log_memory_usage(int log_level) {
    if (log_level <= LOG_LEVEL_PROD) {
        pthread_mutex_lock(&pool_stats.lock);
        printf("Total memory allocated: %zu bytes\n", pool_stats.total_allocated);
        pthread_mutex_unlock(&pool_stats.lock);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_crc_array(int N, int log_level) {
    if (log_level <= LOG_LEVEL_DEV) {
        printf("Attempting to allocate memory for %d structures.\n", N);
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for %d structures.\n", N);
        return NULL;
    }

    pthread_mutex_lock(&pool_stats.lock);
    pool_stats.total_allocated += N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&pool_stats.lock);

    if (log_level <= LOG_LEVEL_TEST) {
        log_memory_usage(log_level);
    }

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); // Example assignment
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    if (log_level <= LOG_LEVEL_DEV) {
        printf("Memory allocation successful for %d structures.\n", N);
    }

    return array;
}

void free_nfa_crc_array(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    if (!array) return;

    pthread_mutex_lock(&pool_stats.lock);
    pool_stats.total_allocated -= N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&pool_stats.lock);

    free(array);
}

int main() {
    srand(time(NULL)); // Initialize random seed

    int log_level = LOG_LEVEL_DEV;  // Set appropriate log level
    int num_structures = 10;

    NFAPI_CRC_INDICATION_PDU_T *nfa_array = allocate_nfa_crc_array(num_structures, log_level);

    if (nfa_array) {
        free_nfa_crc_array(nfa_array, num_structures);
    }

    return 0;
}
