CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    memset(list->crc_count, 0, sizeof(list->crc_count));
    return list;
}

void add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->count >= MAX_ENTRIES) return;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;

    unsigned long rnti = entry.RNTI;
    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (list->crc_count[i] == rnti) {
            list->crc_count[i]++;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_entry(CRCList* list, unsigned long RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (list->crc_count[i] == RNTI) {
            list->crc_count[i]--;
            break;
        }
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

