#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_POOL_SIZE 1024

typedef struct {
    int DEVICE_ID;
    char LINK_STATUS[10];
    int ERROR_CODE;
    char METADATA[20];
} NetworkDeviceStatus;

typedef struct MemoryPool {
    size_t element_size;
    size_t pool_size;
    unsigned char* memory;
    NetworkDeviceStatus* free_list;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool
MemoryPool* init_memory_pool(size_t element_size, size_t pool_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->pool_size = pool_size;
    pool->memory = (unsigned char*)malloc(element_size * pool_size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pool->free_list = (NetworkDeviceStatus*)pool->memory;
    for (size_t i = 0; i < pool_size - 1; ++i) {
        ((NetworkDeviceStatus*)((unsigned char*)pool->free_list + i * element_size))->next =
            (NetworkDeviceStatus*)((unsigned char*)pool->free_list + (i + 1) * element_size);
    }
    ((NetworkDeviceStatus*)((unsigned char*)pool->free_list + (pool_size - 1) * element_size))->next = NULL;

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Function to free the memory pool
void destroy_memory_pool(MemoryPool* pool) {
    if (!pool) return;
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory);
    free(pool);
}

// Thread-safe allocation from the custom memory pool
NetworkDeviceStatus* allocate_status_update(MemoryPool* pool) {
    if (!pool) return NULL;

    NetworkDeviceStatus* status = NULL;

    pthread_mutex_lock(&pool->lock);

    if (pool->free_list != NULL) {
        status = pool->free_list;
        pool->free_list = ((NetworkDeviceStatus*)pool->free_list)->next;
    } else {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Memory Pool Exhausted\n");
        return NULL;
    }

    pthread_mutex_unlock(&pool->lock);

    if (status != NULL) {
        status->ERROR_CODE = 0;
        time_t now = time(NULL);
        struct tm* local_time = localtime(&now);
        strftime(status->METADATA, sizeof(status->METADATA), "%Y-%m-%d %H:%M:%S", local_time);
    }

    return status;
}

// Thread-safe deallocation to the custom memory pool
void free_status_update(MemoryPool* pool, NetworkDeviceStatus* status) {
    if (!pool || !status) return;

    pthread_mutex_lock(&pool->lock);

    ((NetworkDeviceStatus*)status)->next = pool->free_list;
    pool->free_list = (NetworkDeviceStatus*)status;

    pthread_mutex_unlock(&pool->lock);
}

// Example usage
int main() {
    MemoryPool* pool = init_memory_pool(sizeof(NetworkDeviceStatus), DEFAULT_POOL_SIZE);
    if (!pool) return 1;

    NetworkDeviceStatus* status = allocate_status_update(pool);
    if (status) {
        status->DEVICE_ID = 123;
        strcpy(status->LINK_STATUS, "UP");
        // Use the status update
        free_status_update(pool, status);
    }

    destroy_memory_pool(pool);
    return 0;
}
```']

