typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} CRCArray;

// Function to allocate and initialize the array
int allocate_crc_array(CRCArray* arr, int N) {
    if (arr == NULL) return -1;

    pthread_mutex_init(&arr->lock, NULL);

    size_t initial_capacity = INITIAL_SIZE;
    while (initial_capacity < N) {
        initial_capacity *= 2; // Exponential growth
    }

    arr->data = memory_pool_allocate(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr->data == NULL) return -1;

    arr->capacity = initial_capacity;

    pthread_mutex_lock(&arr->lock);
    for (int i = 0; i < N; ++i) {
        arr->data[i].RX_UE_INFORMATION_TAG = rand() % 100;
        arr->data[i].RNTI = rand() % 1000;
        arr->data[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        arr->data[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&arr->lock);

    return 0; // Success
}

// Function to resize the array if necessary
int resize_crc_array(CRCArray* arr, int new_size) {
    if (arr == NULL || arr->data == NULL) return -1;

    size_t new_capacity = arr->capacity;
    while (new_capacity < new_size) {
        new_capacity *= 2; // Exponential growth
    }

    pthread_mutex_lock(&arr->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_data = memory_pool_allocate(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    memcpy(new_data, arr->data, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    memory_pool_free(arr->data);
    arr->data = new_data;
    arr->capacity = new_capacity;

    pthread_mutex_unlock(&arr->lock);

    return 0; // Success
}

// Function to free the allocated array
void free_crc_array(CRCArray* arr) {
    if (arr != NULL && arr->data != NULL) {
        memory_pool_free(arr->data);
        pthread_mutex_destroy(&arr->lock);
    }
}

