            log_error("Integer value too large.");
            continue; // Skip invalid numbers
        }

        int exists = 0;
        for (size_t i = 0; i < count; ++i) {
            if (numbers[i] == number) {
                exists = 1;
                break;
            }
        }

        if (!exists && count < max_size) {
            if (count == capacity) {
                capacity *= 2;
                int *new_numbers = realloc(numbers, capacity * sizeof(int));
                if (!new_numbers) {
                    log_error("Memory reallocation failed.");
                    free(numbers);
                    fclose(log_file);
                    return -1;
