    return base_snr - (rand() % 10 / 10.0 * noise_variance);
}

void initialize_radio_environment(RadioEnvironment *env, int num_pdus) {
    pthread_mutex_init(&env->lock, NULL);
    env->num_pdus = num_pdus;
    env->pdus = malloc(sizeof(RX_MESSAGE_PDU) * num_pdus);

    for (int i = 0; i < num_pdus; ++i) {
        env->pdus[i].rx_ue_information_tag = rand();
        env->pdus[i].rnti = rand() % 65536;
