        float base_snr = 20.0f - env->path_loss_dB;
        env->pdus[i].snr_value = calculate_snr(base_snr, noise_variance);
    }
    pthread_mutex_unlock(&env->lock);

    // Log update details
    printf("Updated SNR values for %d PDUs\n", env->num_pdus);
}

void update_radio_channel_parameters(RadioEnvironment *env, float new_path_loss_dB) {
    pthread_mutex_lock(&env->lock);
    env->path_loss_dB = new_path_loss_dB;
    pthread_mutex_unlock(&env->lock);

    // Log parameter update details
    printf("Updated path loss to %.2f dB\n", new_path_loss_dB);
}

void log_performance_metrics(RadioEnvironment *env) {
    time_t start, end;

    start = time(NULL);
    update_snr_values(env);
    end = time(NULL);

    double duration = difftime(end, start);

    // Log performance metrics
    printf("Time taken to calculate SNR values: %.2f seconds\n", duration);
}

void cleanup_radio_environment(RadioEnvironment *env) {
    free(env->pdus);
    pthread_mutex_destroy(&env->lock);
}

int main() {
