#include <stdio.h>
#include <stdlib.h>
import pthread.h
import time.h

// Assuming the structure is defined as follows:
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned int CRCFLAG;  // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array management structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    unsigned long checksum;  // For error detection
    time_t lastValidationTime;
} CRCArrayManager;

// Function prototypes
CRCArrayManager* create_crc_array_manager(size_t initial_capacity);
void free_crc_array_manager(CRCArrayManager *manager);
int insert_crc_indication(CRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu);
unsigned long calculate_checksum(const CRCArrayManager *manager);
void validate_crc_from_external_source(CRCArrayManager *manager);
void log_insertion(const NFAPI_CRC_INDICATION_PDU_T *pdu);

// Function definitions
CRCArrayManager* create_crc_array_manager(size_t initial_capacity) {
    CRCArrayManager *manager = malloc(sizeof(CRCArrayManager));
    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->checksum = 0;
    manager->lastValidationTime = time(NULL);
    return manager;
}

void free_crc_array_manager(CRCArrayManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i]);
    }
    free(manager->array);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int insert_crc_indication(CRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));

        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Failed to reallocate
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array[manager->count]) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Failed to allocate
    }

    *manager->array[manager->count] = *pdu;
    manager->checksum += pdu->CRC_INDICATION_REL8_TAG.CRCFLAG;

    log_insertion(pdu);

    if (time(NULL) - manager->lastValidationTime > 60) { // Validate every minute, for example
        validate_crc_from_external_source(manager);
        manager->lastValidationTime = time(NULL);
    }

    ++manager->count;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

unsigned long calculate_checksum(const CRCArrayManager *manager) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->mutex);

    unsigned long checksum = manager->checksum;

    pthread_mutex_unlock((pthread_mutex_t *)&manager->mutex);
    return checksum;
}

void validate_crc_from_external_source(CRCArrayManager *manager) {
    // Placeholder for external validation logic
