    // Simulate delay in response and caching strategy
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < 5) { // Assume it may take up to 5 seconds
        sleep(1); // Placeholder for actual validation process
    }

    printf("CRC indications validated.\n");
}

void log_insertion(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Inserted PDU: RX_UE_INFO=%d, RNTI=%d, CRCFLAG=%u\n",
           pdu->RX_UE_INFORMATION_TAG,
           pdu->RNTI,
           pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

// Example usage
int main() {
    // Create a manager with initial capacity of 10
    CRCArrayManager *manager = create_crc_array_manager(10);

    NFAPI_CRC_INDICATION_PDU_T example_pdu = {1, 2, {rand() % 256}};

    for (int i = 0; i < 15; ++i) {
        if (insert_crc_indication(manager, &example_pdu) != 0) {
            fprintf(stderr, "Failed to insert PDU.\n");
        }
    }

    printf("Checksum: %lu\n", calculate_checksum(manager));

    // Cleanup
    free_crc_array_manager(manager);
    return 0;
}
