```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "uthash.h"

#define MAX_ENTRIES 1000

typedef struct {
    uint32_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG[10]; // Example size, adjust as necessary
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRCListEntry {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct CRCListEntry *next;
    UT_hash_handle hh; // Makes this structure hashable
} CRCListEntry;

CRCListEntry *crc_list = NULL;
int total_valid_crcs = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_crc_entry(NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list_mutex);

    CRCListEntry *entry, *tmp;
    HASH_FIND_INT(crc_list, &new_data.RNTI, entry);

    if (entry) {
        // Update existing entry
        memcpy(entry->data.RX_UE_INFORMATION_TAG, new_data.RX_UE_INFORMATION_TAG, sizeof(new_data.RX_UE_INFORMATION_TAG));
    } else {
        // Add new entry
        entry = malloc(sizeof(CRCListEntry));
        if (!entry) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        memcpy(entry->data, new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        HASH_ADD_INT(crc_list, data.RNTI, entry);

        // Maintain list order and size
        if (HASH_COUNT(crc_list) > MAX_ENTRIES) {
            tmp = crc_list;
            crc_list = crc_list->next;
            free(tmp);
        }
    }

    total_valid_crcs++;
    pthread_mutex_unlock(&list_mutex);
}

void remove_crc_entry_by_rnti(uint32_t rnti) {
    pthread_mutex_lock(&list_mutex);

    CRCListEntry *entry, *tmp;
    HASH_FIND_INT(crc_list, &rnti, entry);

    if (entry) {
        HASH_DEL(crc_list, entry);
        free(entry);
        total_valid_crcs--;
    }

    pthread_mutex_unlock(&list_mutex);
}

void print_all_rx_ue_information_tags() {
    pthread_mutex_lock(&list_mutex);

    CRCListEntry *entry;
    for (entry = crc_list; entry != NULL; entry = entry->next) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: ", entry->data.RNTI);
        for (int i = 0; i < sizeof(entry->data.RX_UE_INFORMATION_TAG); i++) {
            printf("%02x", entry->data.RX_UE_INFORMATION_TAG[i]);
        }
        printf("\n");
    }

    pthread_mutex_unlock(&list_mutex);
}

void export_list_to_file(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);

    CRCListEntry *entry;
    for (entry = crc_list; entry != NULL; entry = entry->next) {
        fprintf(file, "RNTI: %u, RX_UE_INFORMATION_TAG: ", entry->data.RNTI);
        for (int i = 0; i < sizeof(entry->data.RX_UE_INFORMATION_TAG); i++) {
            fprintf(file, "%02x", entry->data.RX_UE_INFORMATION_TAG[i]);
        }
        fputc('\n', file);
    }

    pthread_mutex_unlock(&list_mutex);

    fclose(file);
}

void log_operation(const char *message) {
    printf("[LOG] %s\n", message); // Replace with a more robust logging mechanism if needed
}
