#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define CACHE_SIZE 50

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    unsigned long s_tmsi[2]; // S-TMSI stored as two parts
    unsigned short sequence_number;
    time_t timestamp;
} NFAPI_RRC_MSG_T;

// Thread-safe cache implementation
typedef struct {
    NFAPI_RRC_MSG_T* messages[CACHE_SIZE];
    int usage[CACHE_SIZE];
    pthread_mutex_t lock;
} Cache;

Cache cache = {0};

void initialize_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache.messages[i] = NULL;
        cache.usage[i] = -1;
    }
    pthread_mutex_init(&cache.lock, NULL);
}

NFAPI_RRC_MSG_T* get_cached_message(unsigned long s_tmsi) {
    pthread_mutex_lock(&cache.lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.messages[i] && 
            cache.messages[i]->s_tmsi[0] == (s_tmsi >> 32) &&
            cache.messages[i]->s_tmsi[1] == s_tmsi & 0xFFFFFFFF) {

            // Move accessed item to the end
            int last = CACHE_SIZE - 1;
            NFAPI_RRC_MSG_T* temp = cache.messages[last];
            cache.messages[last] = cache.messages[i];
            cache.messages[i] = temp;

            int tempUsage = cache.usage[last];
            cache.usage[last] = cache.usage[i];
            cache.usage[i] = tempUsage;

            pthread_mutex_unlock(&cache.lock);
            return cache.messages[i];
        }
    }

    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

void add_to_cache(NFAPI_RRC_MSG_T* message) {
    pthread_mutex_lock(&cache.lock);

    if (message == NULL) {
        pthread_mutex_unlock(&cache.lock);
        return;
    }

    // Find the least recently used item
    int lru_index = 0;
    for (int i = 1; i < CACHE_SIZE; ++i) {
        if (cache.usage[i] < cache.usage[lru_index]) {
            lru_index = i;
        }
    }

    // Replace LRU with new message
    free(cache.messages[lru_index]);
    cache.messages[lru_index] = message;

    // Update usage index
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.usage[i] > cache.usage[lru_index]) {
            cache.usage[i]--;
        }
    }
    cache.usage[lru_index] = CACHE_SIZE - 1;

    pthread_mutex_unlock(&cache.lock);
}

void generate_random_s_tmsi(unsigned long* s_tmsi) {
    // Simulate external source integration
    *s_tmsi = rand();
    *(s_tmsi + 1) = rand();
}

NFAPI_RRC_MSG_T* create_rrc_message() {
    NFAPI_RRC_MSG_T* message = malloc(sizeof(NFAPI_RRC_MSG_T));
    if (!message) return NULL;

    generate_random_s_tmsi(message->s_tmsi);
    message->sequence_number = rand() % 10000;
    message->timestamp = time(NULL);

    return message;
}

void initialize_records_and_messages(record* records, NFAPI_RRC_MSG_T** messages, int num_records) {
    if (!records || !messages || num_records <= 0) return;

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % 100;
    }

    initialize_cache();

    for (int i = 0; i < num_records; ++i) {
        NFAPI_RRC_MSG_T* message = get_cached_message(records[i].offset);
        if (!message) {
            message = create_rrc_message();
            if (message) add_to_cache(message);
        }

        messages[i] = message;
    }

    // Comprehensive logging and metrics can be added here
}

void cleanup(NFAPI_RRC_MSG_T** messages, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(messages[i]);
    }
    pthread_mutex_destroy(&cache.lock);
}
