#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Define a structure for the pool allocator (simplified)
typedef struct PoolAllocator {
    size_t unit_size;
    void* memory_pool;
    pthread_mutex_t lock; // For thread safety
    size_t total_units;
    size_t used_units;
} PoolAllocator;

// Hash table entry for offset uniqueness check
typedef struct OffsetHashTableEntry {
    long offset;
    bool is_used;
} OffsetHashTableEntry;

PoolAllocator* create_pool_allocator(size_t unit_size, size_t num_units) {
    PoolAllocator* pool = (PoolAllocator*)malloc(sizeof(PoolAllocator));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->unit_size = unit_size;
    pool->total_units = num_units;
    pool->used_units = 0;

    size_t memory_size = unit_size * num_units;
    pool->memory_pool = malloc(memory_size);
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* pool_allocate(PoolAllocator* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_units >= pool->total_units) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }

    void* mem = ((char*)pool->memory_pool) + (pool->unit_size * pool->used_units);
    pool->used_units++;

    pthread_mutex_unlock(&pool->lock);
    return mem;
}

void destroy_pool_allocator(PoolAllocator* pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Function to find the largest integer in an array
int find_largest(int* arr, size_t size) {
    if (size == 0) return INT_MIN; // Return a minimum value if empty

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

// Main function to generate components
void* generate_components(size_t num_records, double range_min, double range_max) {
    // Determine size requirements
    size_t record_size = sizeof(Record);
    size_t offset_table_size = num_records * sizeof(OffsetHashTableEntry);

    // Create pool allocator for records and hash table entries
    PoolAllocator* record_pool = create_pool_allocator(record_size, num_records);
    PoolAllocator* offset_pool = create_pool_allocator(sizeof(long) + sizeof(int), num_records);

    if (!record_pool || !offset_pool) {
        printf("Memory allocation failed.\n");
        destroy_pool_allocator(record_pool);
        destroy_pool_allocator(offset_pool);
        return NULL;
    }

    // Allocate and initialize arrays
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    int* keys = (int*)malloc(num_records * sizeof(int));
    OffsetHashTableEntry* offset_table = (OffsetHashTableEntry*)malloc(offset_table_size);

    if (!records || !keys || !offset_table) {
        printf("Memory allocation failed.\n");
        destroy_pool_allocator(record_pool);
        destroy_pool_allocator(offset_pool);
        free(records);
        free(keys);
        free(offset_table);
        return NULL;
    }

    // Initialize hash table
    for (size_t i = 0; i < num_records; ++i) {
        offset_table[i].offset = 0;
        offset_table[i].is_used = false;
    }

    bool success = true;

    // Populate records, keys and offsets
    for (size_t i = 0; i < num_records && success; ++i) {
        long offset;
        do {
            offset = rand() % ((long)num_records * 100) + 1;
        } while (!set_offset(offset_table, num_records, offset)); // Ensure uniqueness

        keys[i] = rand() % 1000;

        double value = (double)(rand() / (RAND_MAX / (range_max - range_min))) + range_min;

        Record* record = pool_allocate(record_pool);
        if (!record) {
            success = false;
            break;
        }

        ((long*)record)[0] = offset; // Store offset in the first slot
        ((int*)record)[1] = keys[i]; // Store key in the second slot

        records[i].value = value;

        // Directly store offsets and keys into record fields for simplicity
        records[i].offset = offset;
        records[i].key = keys[i];
    }

    if (!success) {
        printf("Failed to generate unique components.\n");
        destroy_pool_allocator(record_pool);
        destroy_pool_allocator(offset_pool);
        free(records);
        free(keys);
        free(offset_table);
        return NULL;
    }

    // Read integers from standard input
    size_t array_size = 10; // Example size, adapt as needed
    int* int_array = (int*)malloc(array_size * sizeof(int));

    if (!int_array) {
        printf("Memory allocation failed for integer array.\n");
        destroy_pool_allocator(record_pool);
        destroy_pool_allocator(offset_pool);
        free(records);
        free(keys);
        free(offset_table);
        return NULL;
    }

    printf("Enter %zu integers:\n", array_size);
    for (size_t i = 0; i < array_size; ++i) {
        if (scanf("%d", &int_array[i]) != 1) {
            printf("Invalid input.\n");
            destroy_pool_allocator(record_pool);
            destroy_pool_allocator(offset_pool);
            free(records);
            free(keys);
            free(offset_table);
            free(int_array);
            return NULL;
        }
    }

    int largest = find_largest(int_array, array_size);
    printf("Largest integer: %d\n", largest);

    // Clean up
    destroy_pool_allocator(record_pool);
    destroy_pool_allocator(offset_pool);
    free(records);
    free(keys);
    free(offset_table);
    free(int_array);

    return NULL;
}

// Helper function to set an offset in the hash table ensuring uniqueness
bool set_offset(OffsetHashTableEntry* offset_table, size_t num_records, long offset) {
    for (size_t i = 0; i < num_records; ++i) {
        if (!offset_table[i].is_used && offset == offset_table[i].offset) {
            offset_table[i].is_used = true;
            return true;
        }
    }
    return false;
}

int main() {
    size_t num_records = 1000;
    double range_min = -10.0, range_max = 10.0;

    generate_components(num_records, range_min, range_max);

    return 0;
}
