# processNetworkEvents.py

import threading
import time
import logging

class NetworkStateManager:
    def __init__(self):
        self.current_state = "IDLE"
        self.lock = threading.Lock()

    def set_network_availability(self, available: bool):
        with self.lock:
            if not available and self.current_state in ["CONNECTED", "CONNECTING"]:
                self.current_state = "IDLE"
            elif available:
                if self.current_state == "IDLE":
                    self.current_state = "CONNECTING"
                elif self.current_state == "CONNECTING":
                    # Simulate connection success for simplicity
                    self.current_state = "CONNECTED"

    def get_current_state(self):
        with self.lock:
            return self.current_state

def processNetworkEvents(manager: NetworkStateManager, events: list):
    def handle_event(event):
        available = event.get("network_available", False)
        manager.set_network_availability(available)

    threads = []
    for event in events:
        thread = threading.Thread(target=handle_event, args=(event,))
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    manager = NetworkStateManager()

    # Simulated list of network events
    events = [
        {"network_available": True},
        {"network_available": False},
        {"network_available": True}
    ]

    processNetworkEvents(manager, events)
    final_state = manager.get_current_state()
    logging.info(f"Final State: {final_state}")
