void log_creation(const char* message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    static FILE* log_file = NULL;

    if (!log_file) {
        log_file = fopen("nfa_log.txt", "a");
        if (!log_file) {
            perror("Unable to open log file");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_lock(&log_mutex);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);  // Flush after writing
    pthread_mutex_unlock(&log_mutex);
}

// Function to dynamically create a list of NFAPI_CRC_INDICATION_PDU_T structures.
NFAPI_CRC_INDICATION_PDU_T* generate_nfa_indications(int N, int M) {
    if (N <= 0 || M <= 0) return NULL;

    size_t total_pdus = N * M;
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(total_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!indications) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int user_id = 0; user_id < N; ++user_id) {
        int rx_tag, rnti;
        if (fetch_ue_information(user_id, &rx_tag, &rnti) != 0) {
            log_creation("Failed to fetch UE information for user ID: " + std::to_string(user_id));
            continue; // Proceed despite failure
        }

        for (int pdu_index = 0; pdu_index < M; ++pdu_index) {
            pthread_mutex_lock(&mutex);

            int base_index = user_id * M + pdu_index;
            indications[base_index].RX_UE_INFORMATION_TAG = rx_tag;
            indications[base_index].RNTI = rnti;
            indications[base_index].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

