int calculate_checksum(RX_UE_INFORMATION_TAG* tag, uint8_t* crcflag, size_t max_size) {
    if (!tag || !crcflag) return -1;

    // Simplified checksum calculation logic.
    size_t index = 0;
    for (; index < max_size && /* some condition based on `tag` fields */; ++index) {
        crcflag[index] = (uint8_t)(/* calculate byte value from tag fields */);
    }

    return index <= max_size ? 0 : -1;
}

int populate_nfa_pi_crc_indication_pdu(Node* node, uint16_t rnti, RX_UE_INFORMATION_TAG rx_ue_info_tag) {
    if (!node || !is_valid_rnti(rnti)) return -1;

    NFAPI_CRC_INDICATION_PDU_T* pdu = &node->data;
    pdu->rx_ue_info_tag = rx_ue_info_tag;
    pdu->rnti = rnti;

    if (calculate_checksum(&pdu->rx_ue_info_tag, pdu->crc_indication_rel8_tag.crcflag, CRCFLAG_SIZE_LIMIT) != 0)
        return -1;

    return 0;
}

int append_to_list(LinkedList* list, RX_UE_INFORMATION_TAG rx_ue_info_tag, uint16_t rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (populate_nfa_pi_crc_indication_pdu(new_node, rnti, rx_ue_info_tag) != 0) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void clear_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(LinkedList* list) {
    if (!list) return;

    clear_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
