#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint8_t tagField1;
    uint16_t tagField2;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t rnti;
} RNTI_T;

typedef struct {
