    RNTI_T rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next; // For singly-linked list
    // struct Node* prev; // Uncomment for doubly-linked list
} Node;

Node* generateNFADListWithConstraints(size_t maxMemory, size_t sizeLimit) {
    if (maxMemory <= sizeof(Node)) return NULL;

    Node *head = NULL, *tail = NULL;
    size_t currentSize = 0;

    while (currentSize + sizeof(Node) <= maxMemory) {
        // Dynamically allocate a new node
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) return head; // Return partially filled list on failure

        // Example constraints validation and memory check
        RX_UE_INFORMATION_TAG tag;
        RNTI_T rnti;

        // Simulated valid assignments for demonstration purposes
        tag.tagField1 = rand() % 256;
        tag.tagField2 = rand() % 65536;
        rnti.rnti = rand() % 1000000;

        if (tag.tagField1 > 255 || tag.tagField2 > 65535 || rnti.rnti > 999999) {
            free(newNode);
            break;
        }

        newNode->data.rxUeInfoTag = tag;
        newNode->data.rnti = rnti;

        // Compute checksum and set crcFlag
        newNode->data.crcIndicationTag.crcFlag = (tag.tagField1 + (tag.tagField2 >> 8)) & 0x01; // Example calculation

        if (!head) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }

        currentSize += sizeof(Node);
    }

    return head;
}

void freeNFADList(Node* head) {
    Node *current = head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
}
