typedef struct DOMElement {
    char *tag;
    char *id;
    char **class_list;
    int class_count;
    struct DOMElement *children;
    struct DOMElement *next_sibling;
} DOMElement;

// External API function prototype (to be implemented externally)
int matches_selector(DOMElement* element, const char* selector);

// Recursive traversal function
void traverse_dom_tree(DOMElement* root, const char* selector, DOMElement** result_list, int* count) {
    if (!root || !selector) return;

    static int capacity = 10;
    *result_list = malloc(capacity * sizeof(DOMElement*));
    if (!(*result_list)) return;

    int current_count = 0;

    void traverse_recursive(DOMElement* element) {
        if (matches_selector(element, selector)) {
            if (current_count >= capacity) {
                capacity *= 2;
                *result_list = realloc(*result_list, capacity * sizeof(DOMElement*));
                if (!(*result_list)) return; // Handle memory allocation failure
            }
            (*result_list)[current_count++] = element;
        }

        for (DOMElement* child = element->children; child != NULL; child = child->next_sibling) {
            traverse_recursive(child);
        }
    }

    traverse_recursive(root);
    *count = current_count;
}

// Example usage
int main() {
    int nfa_pi_list_size = 5;
    NFAPI_CRC_INDICATION_PDU_T* nfa_pi_list = create_nfa_pi_list(nfa_pi_list_size);

