    memset(&root, 0, sizeof(DOMElement)); // Initialize to zero

    const char* selector = ".example-class";
    DOMElement* matched_elements = NULL;
    int match_count = 0;

    traverse_dom_tree(&root, selector, &matched_elements, &match_count);

    if (matched_elements) {
        for (int i = 0; i < match_count; ++i) {
            // Process matched elements...
        }
        free(matched_elements);
    }

    return 0;
}
