enum {
    LOG_LEVEL_NONE,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
};

typedef struct {
    size_t total_allocations;
    size_t current_usage;
    pthread_mutex_t lock;
} MemoryPoolStats;

static const char* log_level_strings[] = {"NONE", "ERROR", "INFO", "DEBUG"};

// Function prototypes for memory allocation and logging
void* thread_safe_malloc(size_t size, MemoryPoolStats* stats);
void log_message(enum { LOG_ERROR, LOG_INFO, LOG_DEBUG }, int level, const char* message, ...);

// Initialize the memory pool statistics structure
MemoryPoolStats mem_pool_stats = {
    .total_allocations = 0,
    .current_usage = 0,
    .lock = PTHREAD_MUTEX_INITIALIZER
};

void* thread_safe_malloc(size_t size, MemoryPoolStats* stats) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        log_message(LOG_ERROR, LOG_LEVEL_ERROR, "Memory allocation failed for size %zu", size);
        return NULL;
    }

    pthread_mutex_lock(&stats->lock);
    stats->total_allocations++;
    stats->current_usage += size;
    pthread_mutex_unlock(&stats->lock);

    return ptr;
}

void log_message(int type, int level, const char* message, ...) {
    if (level > LOG_LEVEL_DEBUG) {  // Assuming a global variable or function to fetch current log level
        return;
    }

    va_list args;
    va_start(args, message);
    vprintf(message, args);
    printf("\n");
    va_end(args);

    switch(type) {
        case LOG_ERROR:
            fprintf(stderr, "%s: ", log_level_strings[level]);
            break;
        case LOG_INFO:
            printf("%s: ", log_level_strings[level]);
            break;
        case LOG_DEBUG:
            if (level == LOG_LEVEL_DEBUG) {
                printf("%s: ", log_level_strings[level]);
            }
            break;
    }

    va_start(args, message);
    vprintf(message, args);
    fprintf(stderr, "\n");
    va_end(args);

    if (type == LOG_ERROR) {
        exit(EXIT_FAILURE);
    }
}

