['Below is a C implementation of a dynamically sized linked list managing `NFAPI_CRC_INDICATION_PDU_T` structures with thread safety and efficient memory usage:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct CRC_Indication {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_duplicate_rnti(LinkedList* list, unsigned short rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0;
}

void add_crc_indication(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    if (is_duplicate_rnti(list, new_data.RNTI)) {
        printf("Duplicate RNTI detected. Skipping insertion.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = new_data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void generate_random_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand((unsigned int)time(NULL));
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* crc_list = create_linked_list();
    if (!crc_list) {
        printf("Failed to create linked list.\n");
        return 1;
    }

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % MAX_ELEMENTS;

        generate_random_crc_flag(&pdu);

        add_crc_indication(crc_list, pdu);
    }

    free_linked_list(crc_list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutexes ensure safe concurrent modifications.
- **Duplicate Handling**: Checks for duplicate `RNTI` before insertion.
- **Memory Management**: Efficiently allocates and frees memory, with error handling for allocation failures.
- **Random CRCFLAG**: Generates a random CRC flag using `rand()`.
- **Performance Considerations**: Mutex locking is minimized to improve performance during high-frequency updates.']

