    LTE_RRC_MessageType_t* messages;
    size_t count;
    size_t capacity;
} MessageArray;

MessageArray* create_message_array() {
    MessageArray* array = (MessageArray*)malloc(sizeof(MessageArray));
    if (!array) return NULL;
    array->messages = (LTE_RRC_MessageType_t*)malloc(MAX_ENTRIES * sizeof(LTE_RRC_MessageType_t));
    if (!array->messages) {
        free(array);
        return NULL;
    }
    array->count = 0;
    array->capacity = MAX_ENTRIES;
    return array;
}

void free_message_array(MessageArray* array) {
    if (array) {
        free(array->messages);
        free(array);
    }
}

int add_or_update_entry(MessageArray* array, int ue_id, const char* message_type, long timestamp) {
    if (!array || array->count >= MAX_ENTRIES) return -1;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].ue_id == ue_id) {
            strncpy(array->messages[i].message_type, message_type, sizeof(array->messages[i].message_type) - 1);
            array->messages[i].timestamp = timestamp;
            return 0;
        }
    }

    if (array->count < MAX_ENTRIES) {
        array->messages[array->count].ue_id = ue_id;
        strncpy(array->messages[array->count].message_type, message_type, sizeof(array->messages[array->count].message_type) - 1);
        array->messages[array->count].timestamp = timestamp;
        array->count++;
    }

    return 0;
}

int remove_entry(MessageArray* array, int ue_id) {
    if (!array || array->count == 0) return -1;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].ue_id == ue_id) {
            memmove(&array->messages[i], &array->messages[i + 1], (array->count - i - 1) * sizeof(LTE_RRC_MessageType_t));
            array->count--;
            return 0;
        }
    }

    return -1;
}

void print_all_messages(MessageArray* array) {
    if (!array || array->count == 0) return;

    for (size_t i = 0; i < array->count; ++i) {
        printf("UE ID: %d, Message Type: %s, Timestamp: %ld\n", 
            array->messages[i].ue_id, array->messages[i].message_type, array->messages[i].timestamp);
    }
}

// Example usage
int main() {
    MessageArray* message_array = create_message_array();

    if (!message_array) {
        fprintf(stderr, "Failed to create message array.\n");
        return 1;
    }

    add_or_update_entry(message_array, 1001, "InitialMessage", 1622547800);
    add_or_update_entry(message_array, 1002, "SecondMessage", 1622547900);
    add_or_update_entry(message_array, 1001, "UpdatedMessage", 1622548000);

    print_all_messages(message_array);

    remove_entry(message_array, 1001);

    printf("\nAfter removal:\n");
    print_all_messages(message_array);

    free_message_array(message_array);
    return 0;
}
