ThreadSafeList* initialize_list() {
    ThreadSafeList* list = malloc(sizeof(ThreadSafeList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

int add_to_list(ThreadSafeList* list, LTE_PHY_RX_TASK_OUTPUT output) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = output;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(ThreadSafeList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

