#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;  // Ensure CRCFLAG is either 0 or 1
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t lock; // Lock for thread-safe access
} NFAPICRCList;

NFAPICRCList* create_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;
    NFAPICRCList* list = malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->capacity = initial_capacity;
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return list;
}

void free_list(NFAPICRCList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

int resize_list_if_needed(NFAPICRCList* list, size_t new_size) {
    pthread_mutex_lock(&list->lock);

    if (new_size > list->capacity) {
        size_t new_capacity = list->capacity * 2;
        while (new_capacity < new_size) new_capacity *= 2;

        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->capacity = new_capacity;
        list->data = new_data;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int populate_list(NFAPICRCList* list, size_t N) {
    if (!list || N == 0) return -1;

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&list->lock);

        int crc_flag = rand() % 2;  // Randomly assign CRCFLAG as either 0 or 1
        if (crc_flag != 0 && crc_flag != 1) {  // Ensure validity
            pthread_mutex_unlock(&list->lock);
            continue;
        }

        if (resize_list_if_needed(list, list->size + 1)) {
            pthread_mutex_unlock(&list->lock);
            return -2;  // Memory allocation failed
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), 
                                           .RNTI = rand(),
                                           .CRC_INDICATION_REL8_TAG = { .CRCFLAG = crc_flag } };

        list->data[list->size] = pdu;
        list->size++;

        printf("Created PDU: RX_UE_INFO_TAG=%d, RNTI=%d, CRCFLAG=%d\n", 
               pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);

        pthread_mutex_unlock(&list->lock);
    }

    return 0;
}

int main() {
    size_t N = 10; // Number of elements to populate
    NFAPICRCList* list = create_list(2); // Initial capacity

    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    int result = populate_list(list, N);
    if (result != 0) {
        fprintf(stderr, "Failed to populate list: error code %d\n", result);
    } else {
        printf("Successfully populated the list with %zu elements.\n", list->size);
    }

    free_list(list);

    return EXIT_SUCCESS;
}
