typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    struct {
        int CRCFLAG; // 0 or 1
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    printf("Created structure with RX_UE_INFORMATION_TAG: %d, RNTI: %lu, CRCFLAG: %d\n",
           data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG.CRCFLAG);
    pthread_mutex_unlock(&list->lock);
}

void process_packet(NFAPI_CRC_INDICATION_PDU_T* packet) {
    // Simulate asynchronous processing
    sleep(1); // Placeholder for actual processing time
    printf("Processed packet with RNTI: %lu\n", packet->RNTI);
}

void async_process_list(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_t threads[100];
    int thread_count = 0;

    Node* current = list->head;
    while (current != NULL) {
        pthread_create(&threads[thread_count++], NULL, (void*)callback, (void*)&current->data);
        current = current->next;
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

NFAPI_CRC_INDICATION_PDU_T create_packet(unsigned long rnti) {
    NFAPI_CRC_INDICATION_PDU_T packet;
    packet.RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate tag
    packet.RNTI = rnti;
    packet.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set to 0 or 1

    if (packet.CRC_INDICATION_REL8_TAG.CRCFLAG != 0 && packet.CRC_INDICATION_REL8_TAG.CRCFLAG != 1) {
        fprintf(stderr, "Invalid CRCFLAG: %d\n", packet.CRC_INDICATION_REL8_TAG.CRCFLAG);
        exit(EXIT_FAILURE);
    }
    return packet;
}

void* process_packet_async(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* packet = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    process_packet(packet);
    return NULL;
}

void manage_nfa_indications(int N) {
    srand(time(NULL));
    LinkedList* list = create_list();

    for (int i = 0; i < N; ++i) {
        add_to_list(list, create_packet(i + 1)); // Use RNTI as unique identifier
    }

    async_process_list(list, process_packet_async);
    destroy_list(list);
}

