#include <string.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[50];
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 10000

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
} HashMap;

unsigned int hash(unsigned int RNTI, size_t size) {
    return RNTI % size;
}

HashMap* create_hashmap(size_t size) {
    HashMap* map = (HashMap*)malloc(sizeof(HashMap));
    map->buckets = (Node**)calloc(size, sizeof(Node*));
    map->size = size;
    return map;
}

void free_hashmap(HashMap* map) {
    for (size_t i = 0; i < map->size; ++i) {
        Node* node = map->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(map->buckets);
    free(map);
}

void insert_hashmap(HashMap* map, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned int index = hash(pdu.RNTI, map->size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    *new_node = (Node){.data = pdu, .next = NULL};

    if (!map->buckets[index]) {
        map->buckets[index] = new_node;
    } else {
        Node* current = map->buckets[index];
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

Node* find_in_hashmap(HashMap* map, unsigned int RNTI) {
    unsigned int index = hash(RNTI, map->size);
    Node* current = map->buckets[index];
    while (current) {
        if (current->data.RNTI == RNTI) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void delete_from_hashmap(HashMap* map, unsigned int RNTI) {
    unsigned int index = hash(RNTI, map->size);
    Node* current = map->buckets[index];
    Node* prev = NULL;

    while (current) {
        if (current->data.RNTI == RNTI) {
            if (prev) {
                prev->next = current->next;
            } else {
                map->buckets[index] = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

unsigned int calculate_crcflag(const char* tag) {
    unsigned int sum = 0;
    while (*tag) {
        sum += (unsigned int)(*tag++);
    }
    return sum % 256; // Ensure it's a non-negative integer within byte range
}

void manage_structures(HashMap** map_ptr, NFAPI_CRC_INDICATION_PDU_T* pdu, int action) {
    if (!map_ptr || !pdu) return;

    switch (action) {
        case 0: // Insert or update
            pdu->CRCFLAG = calculate_crcflag(pdu->RX_UE_INFORMATION_TAG);
            HashMap* map = *map_ptr;
            Node* existing_node = find_in_hashmap(map, pdu->RNTI);

            if (!existing_node) {
                insert_hashmap(map, *pdu);
            } else {
                existing_node->data.CRCFLAG = pdu->CRCFLAG;
            }
            break;

        case 1: // Retrieve
            Node* node = find_in_hashmap(*map_ptr, pdu->RNTI);
            if (node) {
                memcpy(pdu, &(node->data), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            } else {
                printf("Structure not found.\n");
            }
            break;

        case 2: // Remove
            delete_from_hashmap(*map_ptr, pdu->RNTI);
            break;
    }
}

int main() {
    HashMap* map = create_hashmap(1000); // Example size for hash map

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {"Tag1", 1234, 5678, 0};
    manage_structures(&map, &pdu1, 0);

    NFAPI_CRC_INDICATION_PDU_T pdu2;
    pdu2.RNTI = 1234;
    manage_structures(&map, &pdu2, 1);
    printf("Retrieved CRCFLAG: %u\n", pdu2.CRCFLAG);

    manage_structures(&map, &pdu1, 2); // Remove

    free_hashmap(map);
    return 0;
}
