#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 1000

struct record {
    int value;
};

// CRC related tags (mock implementations)
#define RX_UE_INFORMATION_TAG(x) ((x) << 2 | 0b01)
#define RNTI(x) ((x) << 8 | 0b10)
#define CRC_INDICATION_REL8_TAG(crcflag, x) (((crcflag) ? 1 : 0) << 15 | (x))

// Function to manage memory allocation and initialization
struct record* manage_memory(long offsets[], int num_offsets, long max_data_size) {
    // Total memory size calculation based on inputs
    long total_keys = MAX_KEYS;
    long data_elements = max_data_size;

    // Calculate sizes for each section
    long offsets_size = sizeof(long) * num_offsets;
    long keys_size = sizeof(int) * total_keys;
    long data_size = sizeof(struct record) * data_elements;

    // Single block allocation size
    long total_memory_size = offsets_size + keys_size + data_size;

    void* memory_block = malloc(total_memory_size);
    if (!memory_block) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Pointers for each section in the allocated memory
    long* p_offsets = (long*) memory_block;
    int* p_keys = (int*)(p_offsets + num_offsets);
    struct record* p_data = (struct record*)(p_keys + total_keys);

    // Initialize offsets
    for (int i = 0; i < num_offsets; ++i) {
        p_offsets[i] = offsets[i];
    }

    // Read keys ensuring no duplicates, up to MAX_KEYS elements
    bool seen[10000] = { false }; // Adjust size as needed based on expected key range
    int unique_keys[MAX_KEYS];
    printf("Enter %d keys (unique integers):\n", total_keys);
    for (int i = 0; i < total_keys && scanf("%d", &unique_keys[i]) == 1; ++i) {
        if (!seen[abs(unique_keys[i])] && abs(unique_keys[i]) < 10000) { // Adjust bounds as needed
            seen[abs(unique_keys[i])] = true;
            p_keys[i] = unique_keys[i];
        } else {
            --i; // Retry on duplicate or out-of-bounds value
            printf("Duplicate or invalid key, try again: ");
        }
    }

    // Populate data array with mock tags and random CRCFLAG
    for (long i = 0; i < data_elements; ++i) {
        int crcflag = rand() % 2;
        p_data[i].value = RX_UE_INFORMATION_TAG(i) | RNTI(i) | CRC_INDICATION_REL8_TAG(crcflag, i);
    }

    return p_data;
}

// Helper function to find and print the largest key
void print_largest_key(int keys[], int num_keys) {
    if (num_keys <= 0) {
        printf("No valid keys to compare.\n");
        return;
    }

    int max_key = keys[0];
    for (int i = 1; i < num_keys; ++i) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }

    printf("The largest key is: %d\n", max_key);
}

// Test function
void test_manage_memory() {
    long offsets[MAX_OFFSETS] = {0, 10, 20}; // Example offsets
    int num_offsets = 3;
    long data_elements = 100;

    struct record* data = manage_memory(offsets, num_offsets, data_elements);

    if (data) {
        printf("Data memory block allocated successfully.\n");

        void* base_ptr = &((long*)data)[-MAX_KEYS - MAX_OFFSETS]; // Backtrack to the start of the block
        int* keys = (int*)((long*)base_ptr + num_offsets);

        print_largest_key(keys, MAX_KEYS);

        free(base_ptr); // Free entire allocated memory block
    }
}

int main() {
    test_manage_memory();
    return 0;
}
