#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    double value;
} node;

typedef struct {
    double metric_value;
    time_t timestamp;
    int source_id;
} event_record;

typedef struct {
    float* values;
    char** tags;
    node** nodes;
    int* indices;
    event_record* records;
    size_t count;
} event_log;

typedef struct {
    size_t total_floats;
    double min_node_value;
    double max_node_value;
    const char* static_source_id;
} config;

event_log* initialize_event_logging(config* cfg, void** error_buffer) {
    if (!cfg || !error_buffer) return NULL;

    event_log* log = (event_log*)malloc(sizeof(event_log));
    if (!log) {
        *error_buffer = "Failed to allocate memory for event_log structure.";
        return NULL;
    }

    size_t total_elements = cfg->total_floats;
    float* values = (float*)calloc(total_elements, sizeof(float));
    char** tags = (char**)malloc(total_elements * sizeof(char*));
    node** nodes = (node**)malloc(total_elements * sizeof(node*));
    int* indices = (int*)malloc(total_elements * sizeof(int));
    event_record* records = (event_record*)malloc(total_elements * sizeof(event_record));

    if (!values || !tags || !nodes || !indices || !records) {
        free(log);
        *error_buffer = "Failed to allocate memory for event components.";
        return NULL;
    }

    log->values = values;
    log->tags = tags;
    log->nodes = nodes;
    log->indices = indices;
    log->records = records;

    size_t char_count = 0, int_sum = 0;

    for (size_t i = 0; i < total_elements; ++i) {
        tags[i] = strdup("default_tag");
        if (!tags[i]) {
            *error_buffer = "Failed to allocate memory for char tag.";
            free_event_log(log);
            return NULL;
        }

        node* n = (node*)malloc(sizeof(node));
        if (!n) {
            *error_buffer = "Failed to allocate memory for node.";
            free_event_log(log);
            return NULL;
        }

        // Ensuring double value is within range
        do {
            n->value = ((double)rand() / RAND_MAX) * (cfg->max_node_value - cfg->min_node_value) + cfg->min_node_value;
        } while (n->value < cfg->min_node_value || n->value > cfg->max_node_value);

        n->id = i;  // Assuming unique id based on index for simplicity.
        nodes[i] = n;

        indices[i] = rand() % 1000; // Randomly generated, could be replaced with meaningful logic
        int_sum += indices[i];

        records[i].metric_value = (double)(rand() % 100);
        time(&records[i].timestamp);
        records[i].source_id = atoi(cfg->static_source_id); // Convert source id to integer

        char_count++;
    }

    if (total_elements != (char_count + int_sum)) {
        *error_buffer = "Validation failed: total number of 'float' values does not match the sum of 'char' tags and 'index' integers.";
        free_event_log(log);
        return NULL;
    }

    log->count = total_elements;
    return log;
}

void free_event_log(event_log* log) {
    if (!log) return;

    for (size_t i = 0; i < log->count; ++i) {
        free(log->tags[i]);
        free(log->nodes[i]);
    }

    free(log->values);
    free(log->tags);
    free(log->nodes);
    free(log->indices);
    free(log->records);

    free(log);
}
