#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_TAG ue_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10
#define PREDEFINED_CONSTANT 0xA5A5

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Memory profiler data
size_t total_memory_usage = 0;
int allocation_count = 0, deallocation_count = 0;
size_t peak_memory_usage = 0;

NFAPI_CRC_INDICATION_PDU_T* initialize_array(int N) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        array[i].ue_tag.RX_UE_INFORMATION_TAG = rand(); // Random value for demonstration
        array[i].ue_tag.RNTI = rand();
        array[i].crc_ind_rel8_tag.CRCFLAG = i ^ PREDEFINED_CONSTANT;
    }

    total_memory_usage += N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    allocation_count++;
    if (total_memory_usage > peak_memory_usage) {
        peak_memory_usage = total_memory_usage;
    }

    pthread_mutex_unlock(&lock);
    return array;
}

NFAPI_CRC_INDICATION_PDU_T* resize_array(NFAPI_CRC_INDICATION_PDU_T *array, int old_size, int new_size) {
    pthread_mutex_lock(&lock);

    if (new_size <= old_size) {
        pthread_mutex_unlock(&lock);
        return array; // No resizing needed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = old_size; i < new_size; ++i) {
        new_array[i].ue_tag.RX_UE_INFORMATION_TAG = rand();
        new_array[i].ue_tag.RNTI = rand();
        new_array[i].crc_ind_rel8_tag.CRCFLAG = i ^ PREDEFINED_CONSTANT;
    }

    total_memory_usage += (new_size - old_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&lock);

    return new_array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; ++i) {
        // Memory validation logic
        if (!array[i].ue_tag.RX_UE_INFORMATION_TAG || !array[i].ue_tag.RNTI) {
            fprintf(stderr, "Memory corruption detected at index %d\n", i);
        }
    }

    free(array);
    total_memory_usage -= size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    deallocation_count++;

    pthread_mutex_unlock(&lock);
}

void print_memory_profile() {
    printf("Peak Memory Usage: %zu bytes\n", peak_memory_usage);
    printf("Total Allocations: %d\n", allocation_count);
    printf("Total Deallocations: %d\n", deallocation_count);
    if (allocation_count > 0) {
        printf("Average Memory Usage per Structure: %.2f bytes\n",
               (float)total_memory_usage / allocation_count);
    }
}

// Placeholder for configuration service integration
int get_updated_predefined_constant() {
    // Simulate fetching from an external service
    return PREDEFINED_CONSTANT;
}

void log_structure(NFAPI_CRC_INDICATION_PDU_T *structure, const char *action) {
    printf("[%s] TXUE: %d, RNTI: %d, CRCFLAG: %d\n", action,
           structure->ue_tag.RX_UE_INFORMATION_TAG, structure->ue_tag.RNTI,
           structure->crc_ind_rel8_tag.CRCFLAG);
}

int main() {
    int N = 5;
    NFAPI_CRC_INDICATION_PDU_T *array = initialize_array(N);

    if (array) {
        log_structure(&array[0], "ALLOCATED");

        array = resize_array(array, N, N + 5);
        if (array) {
            log_structure(&array[N], "REALLOCATED");
        }

        free_array(array, N + 5);
        log_structure(&array[0], "DEALLOCATED");

        print_memory_profile();
    } else {
        printf("Memory allocation failed.\n");
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures thread-safe operations on shared resources.
- **Dynamic Resizing**: Efficiently reallocates memory and recalculates `CRCFLAG`.
- **Memory Profiling**: Tracks allocations, deallocations, and peak memory usage.
- **Configuration Service**: Placeholder function simulates dynamic updates to constants.
- **Logging**: Provides detailed logs for debugging and auditing purposes.']

