#define MAX_MEASUREMENTS 1000

typedef struct {
    time_t timestamp;
    int signal_strength;
    int frequency_band;
    int cqi; // Channel Quality Information
} LTE_Measurement;

typedef struct {
    LTE_Measurement *measurements;
    size_t count;
    pthread_mutex_t lock;
} MeasurementManager;

MeasurementManager* create_manager() {
    MeasurementManager *manager = (MeasurementManager *)malloc(sizeof(MeasurementManager));
    if (!manager) return NULL;

    manager->measurements = (LTE_Measurement *)calloc(MAX_MEASUREMENTS, sizeof(LTE_Measurement));
    if (!manager->measurements) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(MeasurementManager *manager) {
    if (manager) {
        free(manager->measurements);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_measurement(MeasurementManager *manager, LTE_Measurement measurement) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_MEASUREMENTS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory limit reached
    }

    manager->measurements[manager->count++] = measurement;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_measurement(MeasurementManager *manager, time_t timestamp, LTE_Measurement updatedMeasurement) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(manager->measurements[i].timestamp, timestamp) == 0) {
            manager->measurements[i] = updatedMeasurement;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Measurement not found
}

void retrieve_summary(MeasurementManager *manager, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&manager->lock);

    printf("Summary Report:\n");
    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(manager->measurements[i].timestamp, start_time) >= 0 &&
            difftime(manager->measurements[i].timestamp, end_time) <= 0) {
            printf("Timestamp: %ld, Signal Strength: %d, Frequency Band: %d, CQI: %d\n",
                   manager->measurements[i].timestamp,
                   manager->measurements[i].signal_strength,
                   manager->measurements[i].frequency_band,
                   manager->measurements[i].cqi);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

