    LTE_Measurement measurement = {time(NULL), -70, 700, 15};
    add_measurement(manager, measurement);
    return NULL;
}

int main() {
    MeasurementManager *manager = create_manager();
    if (!manager) {
        fprintf(stderr, "Failed to initialize measurement manager.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread1, thread2;

    // Simulate concurrent additions
    pthread_create(&thread1, NULL, add_measurement_thread, (void*)manager);
