typedef struct MemoryPool {
    size_t block_size;
    unsigned char *pool;
    size_t pool_size;
    atomic_uint offset; // Atomic for thread safety
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->offset = 0;

    mp->pool = (unsigned char *)malloc(mp->pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    size_t offset = atomic_fetch_add(&mp->offset, mp->block_size);
    if (offset >= mp->pool_size) {
        // Handle allocation failure
        return NULL;
    }

    return mp->pool + offset;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    MemoryPool *mem_pool;
} DataArrays;

DataArrays* initialize_data_arrays(size_t num_records, size_t name_length) {
    DataArrays *da = (DataArrays*)malloc(sizeof(DataArrays));
    if (!da) return NULL;

    da->offsets = (long*)malloc(num_records * sizeof(long));
    if (!da->offsets) goto fail;

    da->keys = (int*)malloc(num_records * sizeof(int));
    if (!da->keys) goto fail;

    da->mem_pool = create_memory_pool(sizeof(record) + name_length, num_records);
    if (!da->mem_pool) goto fail;

    da->records = (record**)malloc(num_records * sizeof(record*));
    if (!da->records) goto fail;

    for (size_t i = 0; i < num_records; ++i) {
        record *rec = (record*)memory_pool_alloc(da->mem_pool);
        if (!rec) goto fail;

        rec->value = 0;
        rec->name = (char*)(rec + 1); // Use the space after `record`

        da->records[i] = rec;
    }

    return da;

fail:
    destroy_data_arrays(da);
    return NULL;
}

void destroy_record(record *rec) {
    free(rec->name);
    free(rec);
}

void destroy_data_arrays(DataArrays *da) {
    if (da) {
        for (size_t i = 0; i < da->records; ++i) {
            destroy_record(da->records[i]);
        }

        free(da->offsets);
        free(da->keys);
        free(da->records);
        destroy_memory_pool(da->mem_pool);

        free(da);
    }
}

// Mock logging function
void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}
