['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

// Define the structure for NFAPI_CELLULAR_PACKET_T
typedef struct {
    char bssid[18];
    char ssid[32];
    char mac_addresses[100][18]; // Assuming a max of 100 MAC addresses per connection
} NFAPI_CELLULAR_PACKET_T;

// Define the node structure for a linked list
typedef struct ListNode {
    NFAPI_CELLULAR_PACKET_T data;
    struct ListNode* next;
} ListNode;

// Define the pool structure
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} CellularPool;

CellularPool* create_pool() {
    CellularPool* pool = (CellularPool*)malloc(sizeof(CellularPool));
    if (!pool) return NULL;
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_pool(CellularPool* pool) {
    ListNode* current = pool->head;
    while (current) {
        ListNode* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_device_to_pool(CellularPool* pool, const NFAPI_CELLULAR_PACKET_T* device) {
    if (!device) return -1;

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) return -1;

    memcpy(&new_node->data, device, sizeof(NFAPI_CELLULAR_PACKET_T));

    pthread_mutex_lock(&pool->lock);
    new_node->next = pool->head;
    pool->head = new_node;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

int load_configurations(CellularPool* pool, const char** filenames, int file_count) {
    if (!pool || !filenames) return -1;

    for (int i = 0; i < file_count; ++i) {
        FILE* file = fopen(filenames[i], "r");
        if (!file) {
            fprintf(stderr, "Error opening file: %s\n", filenames[i]);
            continue;
        }

        struct json_object *parsed_json, *bssid_obj, *ssid_obj, *mac_array_obj;
        char *json_string = NULL;
        size_t len;

        fseek(file, 0, SEEK_END);
        len = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (len > 0) {
            json_string = (char*)malloc(len + 1);
            fread(json_string, 1, len, file);
            json_string[len] = '\0';
        }

        parsed_json = json_tokener_parse(json_string);
        free(json_string);

        if (!parsed_json) {
            fprintf(stderr, "Error parsing JSON from file: %s\n", filenames[i]);
            fclose(file);
            continue;
        }

        bssid_obj = json_object_object_get(parsed_json, "bssid");
        ssid_obj = json_object_object_get(parsed_json, "ssid");
        mac_array_obj = json_object_object_get(parsed_json, "mac_addresses");

        if (!bssid_obj || !ssid_obj || !mac_array_obj) {
            fprintf(stderr, "Missing required fields in file: %s\n", filenames[i]);
            json_object_put(parsed_json);
            fclose(file);
            continue;
        }

        NFAPI_CELLULAR_PACKET_T device;
        strncpy(device.bssid, json_object_get_string(bssid_obj), sizeof(device.bssid));
        strncpy(device.ssid, json_object_get_string(ssid_obj), sizeof(device.ssid));

        size_t mac_count = json_array_length(mac_array_obj);
        for (size_t j = 0; j < mac_count && j < 100; ++j) {
            const char* mac_address = json_object_get_string(json_object_array_get_idx(mac_array_obj, j));
            strncpy(device.mac_addresses[j], mac_address, sizeof(device.mac_addresses[0]));
        }

        add_device_to_pool(pool, &device);

        json_object_put(parsed_json);
        fclose(file);
    }
    return 0;
}

NFAPI_CELLULAR_PACKET_T* query_device(CellularPool* pool, const char* bssid) {
    if (!pool || !bssid) return NULL;

    pthread_mutex_lock(&pool->lock);
    for (ListNode* current = pool->head; current != NULL; current = current->next) {
        if (strncmp(current->data.bssid, bssid, sizeof(current->data.bssid)) == 0) {
            pthread_mutex_unlock(&pool->lock);
            return &current->data;
        }
    }
    pthread_mutex_unlock(&pool->lock);

    return NULL;
}

// Example usage
int main() {
    CellularPool* pool = create_pool();
    if (!pool) {
        fprintf(stderr, "Failed to create cellular pool\n");
        return -1;
    }

    const char* filenames[] = {"config1.json", "config2.json"};
    load_configurations(pool, filenames, 2);

    NFAPI_CELLULAR_PACKET_T* device = query_device(pool, "00:11:22:33:44:55");
    if (device) {
        printf("Device found with BSSID: %s\n", device->bssid);
    } else {
        printf("Device not found\n");
    }

    destroy_pool(pool);
    return 0;
}
