    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

int main() {
    int num_keys = read_user_input();
    if (num_keys <= 0 || num_keys > MAX_RECS) {
        handle_memory_allocation_error("Invalid number of keys.");
    }

    initialize_records(num_keys);

    populate_records_with_random_values();

    // Update global max key
    int max_index = find_max_key_record_index();
    update_global_max_key(max_index);
    printf("Max key value is at index %d\n", max_index);

    // Integrate external data source asynchronously
    integrate_external_data_source(NULL);  // Pass actual callback function

    // Simulate other operations...

    deallocate_resources();

    return 0;
}

void initialize_records(int count) {
    pthread_mutex_lock(&mutex);
    records = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!records) handle_memory_allocation_error("Failed to allocate memory for records.");

    num_records = count;
    pthread_mutex_unlock(&mutex);

    // Initialize random seed
    srand(time(NULL));
}

void deallocate_resources() {
    pthread_mutex_lock(&mutex);
    free(records);
    records = NULL;
    pthread_mutex_unlock(&mutex);
}

int read_user_input() {
    int keys[MAX_RECS];
    int count = 0, key;

    printf("Enter integer keys (negative to stop):\n");
    while (scanf("%d", &key) == 1 && key >= 0) {
        if (count >= MAX_RECS) break;
        keys[count++] = key;
    }

    return count;
}

void populate_records_with_random_values() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; ++i) {
        records[i].RX_UE_INFORMATION_TAG = rand() % 100;
        records[i].RNTI = rand() % 1000;
        records[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
    pthread_mutex_unlock(&mutex);
}

int find_max_key_record_index() {
    int max_index = -1;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; ++i) {
        if (records[i].RNTI > max_key) {
            max_key = records[i].RNTI;
            max_index = i;
        }
    }
    pthread_mutex_unlock(&mutex);
    return max_index;
}

void update_global_max_key(int index) {
    if (index != -1 && index < num_records) {
        printf("Updated global max key to %d at index %d\n", records[index].RNTI, index);
    }
}

void integrate_external_data_source(void (*update_callback)(void)) {
    pthread_t thread_id;
    int err = pthread_create(&thread_id, NULL, external_update_thread, (void *)update_callback);
    if (err) {
        fprintf(stderr, "Failed to create thread for external data source integration.\n");
    }
}

void *external_update_thread(void *arg) {
