#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assume these structures are defined elsewhere in the codebase.
typedef struct {
    // Placeholder structure definition for UE context.
} UE_CONTEXT_T;

typedef struct {
    // Placeholder structure definition for Slice context.
} SLICE_CONTEXT_T;

typedef struct {
    UE_CONTEXT_T ue_context;
    SLICE_CONTEXT_T *slice_contexts;
    size_t num_slices;
} NFAPI_MESSAGE_T;

// Define a dynamic array of NFAPI_MESSAGE_T structures with thread safety.
typedef struct {
    NFAPI_MESSAGE_T **messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;  // Mutex for concurrency control.
} NFAPI_MANAGER_T;

// Initialize the NFAPI manager.
NFAPI_MANAGER_T *nfaapi_manager_init(size_t initial_capacity) {
    NFAPI_MANAGER_T *manager = (NFAPI_MANAGER_T *)malloc(sizeof(NFAPI_MANAGER_T));
    if (!manager) return NULL;

    manager->messages = (NFAPI_MESSAGE_T **)calloc(initial_capacity, sizeof(NFAPI_MESSAGE_T *));
    if (!manager->messages) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Add a new NFAPI_MESSAGE to the manager.
int nfaapi_manager_add(NFAPI_MANAGER_T *manager, size_t num_slices) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    // Resize array if necessary.
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_MESSAGE_T **new_messages = (NFAPI_MESSAGE_T **)realloc(manager->messages, new_capacity * sizeof(NFAPI_MESSAGE_T *));
        if (!new_messages) {
            pthread_mutex_unlock(&manager->lock);
            return -1;  // Out of memory.
        }
        manager->messages = new_messages;
        manager->capacity = new_capacity;
    }

    NFAPI_MESSAGE_T *message = (NFAPI_MESSAGE_T *)malloc(sizeof(NFAPI_MESSAGE_T));
    if (!message) {
        pthread_mutex_unlock(&manager->lock);
        return -1;  // Out of memory.
    }

    message->ue_context = /* Initialize UE_CONTEXT_T */;
    message->num_slices = num_slices;
    message->slice_contexts = (SLICE_CONTEXT_T *)calloc(num_slices, sizeof(SLICE_CONTEXT_T));
    if (!message->slice_contexts) {
        free(message);
        pthread_mutex_unlock(&manager->lock);
        return -1;  // Out of memory.
    }

    manager->messages[manager->count++] = message;
    pthread_mutex_unlock(&manager->lock);

    return 0;  // Success
}

// Remove an NFAPI_MESSAGE from the manager by index.
int nfaapi_manager_remove(NFAPI_MANAGER_T *manager, size_t index) {
    if (!manager || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);

    NFAPI_MESSAGE_T *message = manager->messages[index];
    if (message) {
        free(message->slice_contexts);
        free(message);

        // Shift remaining elements down.
        memmove(&manager->messages[index], &manager->messages[index + 1], 
                (manager->count - index - 1) * sizeof(NFAPI_MESSAGE_T *));
        manager->count--;
    }

    pthread_mutex_unlock(&manager->lock);

    return 0;  // Success
}

// Clean up the NFAPI manager.
void nfaapi_manager_destroy(NFAPI_MANAGER_T *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->messages[i]->slice_contexts);
        free(manager->messages[i]);
    }
    free(manager->messages);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

