#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

void init_random(int seed) {
    srand(seed);
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* shuffle_records(int *keys, long *offsets, record *records, size_t n_keys, size_t n_offsets, size_t n_records, int seed, record **shuffled_records_out) {
    if (!keys || !offsets || !records || n_records > n_keys || n_records > n_offsets || shuffled_records_out == NULL) {
        return NULL;
    }

    init_random(seed);

    *shuffled_records_out = (record*)malloc(n_records * sizeof(record));
    if (*shuffled_records_out == NULL) {
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < n_records; ++i) {
        int j = random_int(i, n_records - 1);

        record temp = records[i];
        records[i] = records[j];
        records[j] = temp;

        if (shuffled_records_out != &records) { // Prevent unnecessary copying
            (*shuffled_records_out)[i] = records[i];
        }
    }

    return *shuffled_records_out;
}

void free_memory(record *records, size_t n_records) {
    free(records);
}

int main() {
    int keys[] = {1, 2, 3, 4};
    long offsets[] = {10L, 20L, 30L, 40L};
    record records[] = {{1, 10}, {2, 20}, {3, 30}, {4, 40}};

    size_t n_keys = sizeof(keys) / sizeof(keys[0]);
    size_t n_offsets = sizeof(offsets) / sizeof(offsets[0]);
    size_t n_records = sizeof(records) / sizeof(records[0]);

    record *shuffled_records = NULL;
    int seed = 42;

    shuffled_records = shuffle_records(keys, offsets, records, n_keys, n_offsets, n_records, seed, &shuffled_records);

    if (shuffled_records != NULL) {
        for (size_t i = 0; i < n_records; ++i) {
            printf("Key: %d, Offset: %ld\n", shuffled_records[i].key, shuffled_records[i].offset);
        }

        free_memory(shuffled_records, n_records);
    } else {
        fprintf(stderr, "Memory allocation failed.\n");
    }

    return 0;
}
```

