#define MAX_NETWORK_ENTITIES 100
#define MAX_CONFIG_LINE_LENGTH 256

typedef struct {
    char ip_address[16];
    int port_number;
    char protocol_type[10];
} NetworkEntity;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_TAG;
} LTE_PDU;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int validate_ip_address(const char *ip) {
    // Simple IP address validation logic (IPv4 only for simplicity)
    int dots = 0;
    while (*ip) {
        if (*ip == '.') ++dots;
        else if (!isdigit(*ip)) return 0;
        ip++;
    }
    return dots == 3;
}

int validate_port_number(int port) {
    return port > 0 && port <= 65535;
}

int validate_protocol_type(const char *protocol) {
    // Simple protocol type validation
    return strcmp(protocol, "TCP") == 0 || strcmp(protocol, "UDP") == 0;
}

void log_message(const char *message) {
    printf("%s\n", message);
}

int parse_and_validate_config(const char *filename, NetworkEntity entities[], int max_entities) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char line[MAX_CONFIG_LINE_LENGTH];
    int count = 0;
    while (fgets(line, sizeof(line), file)) {
        if (count >= max_entities) break;

        NetworkEntity entity;
        sscanf(line, "%15[^ ] %d %9s", entity.ip_address, &entity.port_number, entity.protocol_type);

        if (!validate_ip_address(entity.ip_address) || !validate_port_number(entity.port_number) ||
            !validate_protocol_type(entity.protocol_type)) {
            log_message("Invalid configuration line");
            continue;
        }
        entities[count++] = entity;
    }

    fclose(file);
    return count;
}

int find_max_port_number(NetworkEntity *entities, int count) {
    int max_port = 0;
    for (int i = 0; i < count; ++i) {
        if (entities[i].port_number > max_port) {
            max_port = entities[i].port_number;
        }
    }
    return max_port;
}

LTE_PDU* create_pdus(int num_pdus, size_t *size) {
    LTE_PDU *pdus = malloc(num_pdus * sizeof(LTE_PDU));
    if (!pdus) return NULL;

    srand(time(NULL));
    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand() % 65535;
        pdus[i].CRC_INDICATION_TAG = rand() & 1; // Randomly set CRC flag
    }

    *size = num_pdus * sizeof(LTE_PDU);
    return pdus;
}

void process_network_config(const char *filename) {
    NetworkEntity entities[MAX_NETWORK_ENTITIES];
    int count = parse_and_validate_config(filename, entities, MAX_NETWORK_ENTITIES);

    if (count <= 0) {
        log_message("No valid network configurations found.");
        return;
    }

    int max_port = find_max_port_number(entities, count);
    printf("Maximum Port Number: %d\n", max_port);

    size_t pdu_size;
    LTE_PDU *pdus = create_pdus(count, &pdu_size);
    if (!pdus) {
        log_message("Memory allocation for PDUs failed.");
        return;
    }

    pthread_mutex_lock(&lock);
    // Log PDU creation details
    log_message("PDUs created successfully with size: ");
    printf("%zu bytes\n", pdu_size);

    free(pdus);
    pthread_mutex_unlock(&lock);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_network_config(argv[1]);
    return EXIT_SUCCESS;
}
