#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

// Assume these are defined elsewhere
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicArray;

// Memory pool for efficient allocation
#define MEMORY_POOL_SIZE 1024
char memoryPool[MEMORY_POOL_SIZE];
size_t nextFreeMemory = 0;
pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateFromPool(size_t size) {
    pthread_mutex_lock(&memoryMutex);
    if (nextFreeMemory + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&memoryMutex);
        return NULL; // Pool exhausted
    }
    void *mem = &memoryPool[nextFreeMemory];
    nextFreeMemory += size;
    pthread_mutex_unlock(&memoryMutex);
    return mem;
}

// Function to handle HTTP requests and populate the array
size_t writeCallback(void *ptr, size_t size, size_t nmemb, DynamicArray *array) {
