            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            free(array->data);
            free(array);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return NULL;
        }

        // Handle dynamic resizing
        while (array->size == array->capacity) {
            size_t newCapacity = array->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T *newData = allocateFromPool(newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newData) break; // Out of memory

            memcpy(newData, array->data, array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            free(array->data);
            array->data = newData;
            array->capacity = newCapacity;
        }

        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize cURL\n");
        free(array->data);
        free(array);
        curl_global_cleanup();
        return NULL;
    }

    curl_global_cleanup();
    return (array->size > 0) ? array : NULL;
}

