#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPoolNode {
    size_t size;
    void* memory;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode* head;
    pthread_mutex_t mutex;
    size_t priority_size;  // Size associated with the current priority level
    int (*allocation_priority)();
} CustomAllocator;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char **response_ptr = (char **)userp;
    *response_ptr = realloc(*response_ptr, realsize + 1);
    if (*response_ptr == NULL) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }
    memcpy(*response_ptr, contents, realsize);
    (*response_ptr)[realsize] = '\0';
    return realsize;
}

void initialize_allocator(CustomAllocator* allocator, size_t initial_size) {
    allocator->head = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
    allocator->head->size = initial_size;
    allocator->head->memory = malloc(initial_size);
    if (!allocator->head->memory) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    allocator->head->next = NULL;
    pthread_mutex_init(&allocator->mutex, NULL);
}

void* custom_allocator_allocate(CustomAllocator* allocator, size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&allocator->mutex);

    MemoryPoolNode *current = allocator->head;

    while (current != NULL) {
        if ((current->size - sizeof(MemoryPoolNode)) >= size) {
            ptr = current->memory;
            current->memory = (void*)((char*)ptr + size);
            current->size -= size;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&allocator->mutex);

    if (!ptr) {  // If not found, allocate new block
        ptr = malloc(size);
    }

    return ptr;
}

void custom_allocator_free(CustomAllocator* allocator, void *ptr) {
    // Implement a basic free strategy for simplicity in this example
    pthread_mutex_lock(&allocator->mutex);

    MemoryPoolNode *node = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
    node->memory = ptr;
    node->size = 0;  // We don't track size here, but could be improved
    node->next = allocator->head;
    allocator->head = node;

    pthread_mutex_unlock(&allocator->mutex);
}

void fetch_data_from_server(CustomAllocator* allocator, char **response) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/data");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)response);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

NFAPI_CRC_INDICATION_PDU_T* manage_dynamic_array(CustomAllocator *allocator) {
    char *response = NULL;
    fetch_data_from_server(allocator, &response);

    if (!response || strlen(response) == 0) {
        fprintf(stderr, "Failed to retrieve data from server.\n");
        return NULL;
    }

    // Assume the response contains a simple comma-separated list of integers
    char *token = strtok(response, ",");
    NFAPI_CRC_INDICATION_PDU_T* dynamic_array = (NFAPI_CRC_INDICATION_PDU_T*)
        custom_allocator_allocate(allocator, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!dynamic_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(response);
        return NULL;
    }

    size_t count = 0;

    while (token != NULL) {
        int RX_TAG = atoi(token);
        token = strtok(NULL, ",");
        int RNTI = atoi(token);
        token = strtok(NULL, ",");
        int CRC_TAG = atoi(token);

        dynamic_array[count].RX_UE_INFORMATION_TAG = RX_TAG;
        dynamic_array[count].RNTI = RNTI;
        dynamic_array[count].CRC_INDICATION_REL8_TAG = CRC_TAG;

        count++;

        // Allocate more space if needed
        if (count >= 1) {  // Assuming initial allocation for one entry
            NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)
                custom_allocator_allocate(allocator, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (count + 1));
            if (!new_array) {
                fprintf(stderr, "Memory allocation failed during expansion.\n");
                break;
            }
            memcpy(new_array, dynamic_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
            custom_allocator_free(allocator, dynamic_array);
            dynamic_array = new_array;
        }

        token = strtok(NULL, ",");
    }

    free(response);

    return dynamic_array;
}

int main() {
    CustomAllocator allocator;
    initialize_allocator(&allocator, 1024); // Initial size of 1 KB

    NFAPI_CRC_INDICATION_PDU_T* array = manage_dynamic_array(&allocator);

    if (array) {
        for (size_t i = 0; i < 3 /* change to actual count */; ++i) {
