        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1;
