        da->array = new_array;
        da->capacity = new_capacity;
    }

    memcpy(&da->array[da->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++da->size;

    pthread_mutex_unlock(&da->lock);
    return 0;
