#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CAPACITY 1000
#define MAX_RETRIES 5

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_CAPACITY];
    size_t count;
    pthread_mutex_t lock;
    unsigned long successful_initializations;
    unsigned long allocation_failures;
} DynamicArrayManager;

DynamicArrayManager manager = { .count = 0, .successful_initializations = 0, .allocation_failures = 0 };

void initialize_manager(DynamicArrayManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
}

int allocate_and_initialize(NFAPI_CRC_INDICATION_PDU_T **pdu, unsigned int tag, unsigned int rnti, unsigned int crcThreshold) {
    if (manager.count >= MAX_CAPACITY) return 0;

    for (unsigned int attempts = 0; attempts < MAX_RETRIES; ++attempts) {
        *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*pdu != NULL) {
            (*pdu)->RX_UE_INFORMATION_TAG = tag;
            (*pdu)->RNTI = rnti;
            srand((unsigned int)time(NULL) + attempts);
            (*pdu)->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 100 < crcThreshold) ? 1 : 0;

            pthread_mutex_lock(&manager->lock);
            manager.array[manager.count++] = *pdu;
            ++manager.successful_initializations;
            pthread_mutex_unlock(&manager->lock);

            return 1;
        }
    }

    pthread_mutex_lock(&manager->lock);
    ++manager.allocation_failures;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void perform_operation_on_array(void (*operation)(NFAPI_CRC_INDICATION_PDU_T *), unsigned int condition) {
    pthread_mutex_lock(&manager.lock);
    for (size_t i = 0; i < manager.count; ++i) {
        if (condition == /* specific condition */) {
            operation(manager.array[i]);
        }
    }
    pthread_mutex_unlock(&manager.lock);
}

void free_resources(DynamicArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

void log_statistics(const DynamicArrayManager *manager) {
    printf("Successful initializations: %lu\n", manager->successful_initializations);
    printf("Allocation failures: %lu\n", manager->allocation_failures);
