class TCPConnectionHandler {
public:
    // Placeholder for connection management logic
};

class ConnectionPool {
private:
    std::vector<TCPConnectionHandler> pool;
    std::mutex poolMutex;
    std::condition_variable cv;
    std::atomic<int> activeConnections{0};
    std::atomic<bool> shutdownFlag{false};

    void resizePool(size_t newSize) {
        std::lock_guard<std::mutex> lock(poolMutex);
        if (newSize > pool.size()) {
            // Expand the pool
            pool.resize(newSize);
            std::cout << "Resized pool to: " << newSize << "\n";
        } else if (newSize < pool.size()) {
            // Shrink the pool
            pool.resize(newSize);
            std::cout << "Shrunk pool to: " << newSize << "\n";
        }
    }

public:
    ConnectionPool(size_t initialSize) : pool(initialSize) {}

    TCPConnectionHandler* acquire() {
        std::unique_lock<std::mutex> lock(poolMutex);

        cv.wait(lock, [this]() { return activeConnections.load() < pool.size() || shutdownFlag.load(); });

        if (shutdownFlag.load()) {
            throw std::runtime_error("Cannot acquire connection. Pool is shutting down.");
        }

        // Simulate acquiring a connection
        ++activeConnections;
        return &pool[activeConnections - 1];
    }

    void release(TCPConnectionHandler* handler) {
        std::lock_guard<std::mutex> lock(poolMutex);

        if (shutdownFlag.load()) {
            delete handler; // Clean up resources if needed
            return;
        }

        --activeConnections;
        cv.notify_one();
    }

    void dynamicResize(size_t newSize) {
        resizePool(newSize);
    }

    void shutdown() noexcept {
        std::lock_guard<std::mutex> lock(poolMutex);
        shutdownFlag = true;
        cv.notify_all();

        // Clean up resources if needed
    }

    void logMetrics() const {
        std::cout << "Active Connections: " << activeConnections.load()
                  << ", Pool Size: " << pool.size() << "\n";
    }
};

int main() {
    ConnectionPool pool(100);

    // Example usage with threads simulating connection handling
    std::vector<std::thread> workers;

    auto workerFunction = [&pool]() {
        try {
            TCPConnectionHandler* handler = pool.acquire();
            // Simulate work being done with the connection
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            pool.release(handler);
        } catch (const std::exception& e) {
            std::cerr << "Worker error: " << e.what() << "\n";
        }
    };

    for (int i = 0; i < 10; ++i) {
        workers.emplace_back(workerFunction);
    }

    // Wait for all threads to finish
    for (auto& worker : workers) {
        if (worker.joinable()) {
            worker.join();
        }
    }

    pool.logMetrics();
    pool.shutdown();

    return 0;
}
```

