record* create_records(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL; // Basic parameter validation
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand() % 10000; // Example offset range
        do {
            records[i].key = rand() % (max_value - min_value + 1) + min_value;
        } while (contains_key(records, i, records[i].key));

        float value_range = max_value - min_value;
        records[i].value = ((float)rand() / RAND_MAX) * value_range + min_value;
    }

    return records;
}

int contains_key(record* records, int current_index, int key_to_check) {
    for (int i = 0; i < current_index; ++i) {
        if (records[i].key == key_to_check) {
            return 1;
        }
    }
    return 0;
}

void free_records(record *records) {
    if (records) {
        free(records);
    }
}
