typedef struct {
    void *handle;
    char *name;
} Algorithm;

Algorithm algorithms[] = {
    {NULL, "AES"},
    {NULL, "Camellia"},
    {NULL, "MD5"},
    {NULL, "SHA1"},
    {NULL, "SHA256"}
};

int load_algorithm(const char *algorithm_name) {
    void *handle;
    char lib_path[256];

    snprintf(lib_path, sizeof(lib_path), "%s.so", algorithm_name);
    handle = dlopen(lib_path, RTLD_LAZY);

    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        return -1;
    }

    for (int i = 0; i < sizeof(algorithms) / sizeof(Algorithm); ++i) {
        if (strcmp(algorithms[i].name, algorithm_name) == 0) {
            algorithms[i].handle = handle;
            return 0;
        }
    }

    dlclose(handle);
    return -1;
}

int load_configuration(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and load algorithms
        load_algorithm(strtok(line, "\n"));
    }
    fclose(file);
    return 0;
}

void cleanup() {
    for (int i = 0; i < sizeof(algorithms) / sizeof(Algorithm); ++i) {
        if (algorithms[i].handle) {
            dlclose(algorithms[i].handle);
        }
    }
}

