            pdu_array[i].RNTI = /* fetch value */;
            pdu_array[i].CRC_INDICATION_REL8_TAG = /* fetch value */;
            pdu_array[i].CRCFLAG = success;
        }
    }

    pthread_mutex_unlock(&lock);
    return success ? 1 : 0;
}
