    offsets = (long *)calloc(RECORD_COUNT, sizeof(long));
    keys = (int *)malloc(sizeof(int) * RECORD_COUNT);
    records = (record_t *)malloc(sizeof(record_t) * RECORD_COUNT);

    CHECK_NULL(offsets, cleanup);
    CHECK_NULL(keys, cleanup_offsets);
    CHECK_NULL(records, cleanup_keys);

    // Set random values for records
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < RECORD_COUNT; ++i) {
        int rand_value;
        if (!RAND_bytes((unsigned char *)&rand_value, sizeof(rand_value))) {
            perror("Failed to generate random number");
            goto cleanup_records;
        }
        records[i].value = rand_value % 1000; // Random value within a specified range
    }
    pthread_mutex_unlock(&mutex);

    FILE *log_file = fopen("records_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_records;
    }

    for (int i = 0; i < RECORD_COUNT; ++i) {
        fprintf(log_file, "Record %zu: %d\n", i, records[i].value);
    }
    fclose(log_file);

    // Periodically log the state of the 'records' array
    int log_count = 0;
    while (1) { // Simulate continuous operation
        pthread_mutex_lock(&mutex);
        if (++log_count >= LOG_FREQUENCY) {
            FILE *periodic_log_file = fopen("periodic_records_log.txt", "a");
            if (!periodic_log_file) {
                perror("Failed to open periodic log file");
                pthread_mutex_unlock(&mutex);
                continue;
            }

            for (size_t i = 0; i < RECORD_COUNT; ++i) {
                fprintf(periodic_log_file, "Record %zu: %d\n", i, records[i].value);
            }
            fclose(periodic_log_file);

            log_count = 0;
        }

        pthread_mutex_unlock(&mutex);
    }

cleanup_records:
    free(records);
cleanup_keys:
    free(keys);
cleanup_offsets:
    free(offsets);
cleanup:
    pthread_mutex_destroy(&mutex);
}

int main() {
    init_crypto_primitives();
    initialize_arrays_and_records();

    return 0;
}
