// Thread-safe function to initialize memory pool
void initMemoryPool(MemoryPool *pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->size = 0;
    pool->capacity = INITIAL_SIZE;
    pool->array = malloc(pool->capacity * sizeof(NFAPI_MESSAGE_PDU_T));
}

// Thread-safe function to resize memory pool
void resizeMemoryPool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        NFAPI_MESSAGE_PDU_T *new_array = realloc(pool->array, new_capacity * sizeof(NFAPI_MESSAGE_PDU_T));
        if (new_array) {
            pool->array = new_array;
            pool->capacity = new_capacity;
        } else {
            fprintf(stderr, "Memory allocation failed during resize.\n");
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

// Thread-safe function to add a new PDU
void addPdu(MemoryPool *pool, int rnti, float snr_value) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        resizeMemoryPool(pool);
    }
    NFAPI_MESSAGE_PDU_T *pdu = &pool->array[pool->size++];
    pdu->rnti = rnti;
    pdu->snr_value = snr_value;
    pdu->rx_ue_info_tag = rand() % 1000; // Example tag
    pdu->crc_indication_rel8_tag = rand() % 1000; // Example tag
    pthread_mutex_unlock(&pool->lock);
}

// Function to simulate SNR calculation based on channel model and environmental factors
float calculateSnr(float base_snr, float temperature, float humidity, float altitude) {
    float noise_factor = (rand() % 10 + 1) * 0.1;
    float env_factor = calculateEnvironmentalFactor(temperature, humidity, altitude);
    return base_snr - noise_factor * env_factor;
}

// Function to initialize UEs and populate the array
void initUes(MemoryPool *pool, size_t num_ues, float temperature, float humidity, float altitude) {
    for (size_t i = 0; i < num_ues; ++i) {
        int rnti = rand() % 10000;
        float base_snr = 20.0 + (rand() % 10);
        float snr_value = calculateSnr(base_snr, temperature, humidity, altitude);
        addPdu(pool, rnti, snr_value);

        // Simulate integration with external monitoring system
        if ((rand() % 100) < 5) { // Simulated network failure condition
            printf("Network error during UE initialization for RNTI %d. Retrying...\n", rnti);
            sleep(1); // Retry after a delay
            addPdu(pool, rnti, snr_value);
        }
    }
}

// Function to compute and log statistical metrics
void logStatistics(MemoryPool *pool) {
    float sum_snr = 0;
    float max_snr = -INFINITY;
    for (size_t i = 0; i < pool->size; ++i) {
        NFAPI_MESSAGE_PDU_T pdu = pool->array[i];
        sum_snr += pdu.snr_value;
        if (pdu.snr_value > max_snr) {
            max_snr = pdu.snr_value;
        }
    }

    float avg_snr = sum_snr / pool->size;
    float variance = 0;
    for (size_t i = 0; i < pool->size; ++i) {
        NFAPI_MESSAGE_PDU_T pdu = pool->array[i];
        variance += pow(pdu.snr_value - avg_snr, 2);
    }
    float stddev_snr = sqrt(variance / pool->size);

    printf("Average SNR: %.2f, Max SNR: %.2f, StdDev SNR: %.2f\n", avg_snr, max_snr, stddev_snr);
}

// Function to clean up memory pool
void cleanupMemoryPool(MemoryPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->array);
}

int main() {
    MemoryPool pool;
    initMemoryPool(&pool);

    // Example environmental factors
    float temperature = 25.0;
    float humidity = 50.0;
    float altitude = 100.0;

    // Initialize UEs
    initUes(&pool, 20, temperature, humidity, altitude);

    // Log statistics
    logStatistics(&pool);

    // Clean up
    cleanupMemoryPool(&pool);

    return 0;
}
