```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp; // For tracking when the entry was added
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    time_t now = time(NULL);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    pthread_mutex_lock(&list->lock);
    new_node->data = entry;
    new_node->timestamp = now;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_expired_entries(CRCList* list, time_t timeout) {
    pthread_mutex_lock(&list->lock);

    Node **curr = &list->head;
    while (*curr) {
        Node *entry = *curr;
        if (difftime(time(NULL), entry->timestamp) > timeout) {
            *curr = entry->next;
            free(entry);
        } else {
            curr = &entry->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_duplicates(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node **outer = &list->head;
    while (*outer) {
        Node *entry = *outer;
        Node *inner = entry->next;

        while (inner) {
            if (entry->data.RNTI == inner->data.RNTI) {
                Node *to_delete = inner;
                *outer = inner;
                inner = inner->next;
                free(to_delete);
            } else {
                outer = &inner->next;
                inner = inner->next;
            }
        }

        outer = &entry->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void purge_and_check_duplicates(CRCList* list, time_t timeout) {
    remove_expired_entries(list, timeout);
    remove_duplicates(list);
}

// Simulate a function that periodically calls the purging functions
void *purge_task(void* arg) {
    CRCList* list = (CRCList*)arg;
    while (1) {
        purge_and_check_duplicates(list, 60); // Purge entries older than 60 seconds
        sleep(30); // Run every 30 seconds
    }
}

int main() {
    srand(time(NULL));

    CRCList* crc_list = create_list();
    if (!crc_list) return -1;

    pthread_t purge_thread;
    if (pthread_create(&purge_thread, NULL, purge_task, crc_list)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    // Example of adding entries
    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand(),
            .CRC_INDICATION_REL8_TAG = rand() % 10,
            .CRCFLAG = rand() % 2
        };
        add_entry(crc_list, entry);
    }

    // Join thread (in a real application, you might not do this)
    pthread_join(purge_thread, NULL);

    return 0;
}
```

### Key Aspects:
- **Thread Safety**: The code uses `pthread_mutex_t` to ensure thread-safe operations on the linked list.
- **Dynamic Management**: Adds and removes entries dynamically while checking for expired data or duplicates.
- **Concurrency Handling**: Uses a separate thread to periodically purge old entries, simulating high-concurrency handling.
- **Error Handling**: Checks memory allocation failures and handles them gracefully.']

