// Constants to simulate noise factors and other parameters
#define MAX_CHANNELS 100
#define NOISE_FACTOR_BASE 0.1
#define UPDATE_INTERVAL_MS 100

typedef struct {
    int dl_transport_channel;
    int ul_transport_channel;
} TransportChannel;

typedef struct {
    double tx_power_level;
    double ber_indication; // Bit Error Rate
} LTE_TRANSPORT_CONTEXT_T;

typedef struct {
    LTE_TRANSPORT_CONTEXT_T* contexts[MAX_CHANNELS];
    size_t num_channels;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} NetworkSimulation;

// Global list of networks to manage multiple simultaneously
NetworkSimulation* network_simulations;
size_t num_networks = 0;
pthread_rwlock_t network_lock = PTHREAD_RWLOCK_INITIALIZER;

void calculate_ber(double noise_factor, double tx_power_level, double* ber) {
    // Simulate BER calculation based on noise and power level
    *ber = exp(-tx_power_level / (1.0 + noise_factor));
}

void* update_ber_values(void* arg) {
    NetworkSimulation* sim = (NetworkSimulation*)arg;

    while (1) {
        pthread_mutex_lock(&sim->lock);

        for (size_t i = 0; i < sim->num_channels; ++i) {
            double noise_factor = NOISE_FACTOR_BASE * ((double)rand() / RAND_MAX);
            calculate_ber(noise_factor, sim->contexts[i]->tx_power_level, &sim->contexts[i]->ber_indication);
        }

        pthread_mutex_unlock(&sim->lock);

        // Simulate update interval
        usleep(UPDATE_INTERVAL_MS * 1000);
    }
}

void initialize_network_simulation(size_t num_channels) {
    NetworkSimulation* sim = (NetworkSimulation*)malloc(sizeof(NetworkSimulation));

    sim->num_channels = num_channels;
    pthread_mutex_init(&sim->lock, NULL);

    for (size_t i = 0; i < num_channels; ++i) {
        sim->contexts[i] = (LTE_TRANSPORT_CONTEXT_T*)malloc(sizeof(LTE_TRANSPORT_CONTEXT_T));
        sim->contexts[i]->dl_transport_channel = rand() % 100;
        sim->contexts[i]->ul_transport_channel = rand() % 100;
        sim->contexts[i]->tx_power_level = ((double)rand() / RAND_MAX) * 10.0; // Random power level between 0 and 10
        calculate_ber(NOISE_FACTOR_BASE, sim->contexts[i]->tx_power_level, &sim->contexts[i]->ber_indication);
    }

    pthread_t updater_thread;
    pthread_create(&updater_thread, NULL, update_ber_values, sim);

    pthread_rwlock_wrlock(&network_lock);
    network_simulations = realloc(network_simulations, (num_networks + 1) * sizeof(NetworkSimulation*));
    network_simulations[num_networks++] = sim;
    pthread_rwlock_unlock(&network_lock);
}

void get_statistics(NetworkSimulation* sim, double* avg_ber, double* min_ber, double* max_ber) {
    pthread_mutex_lock(&sim->lock);

    double total_ber = 0.0;
    double current_min = DBL_MAX;
    double current_max = -DBL_MAX;

    for (size_t i = 0; i < sim->num_channels; ++i) {
        double ber = sim->contexts[i]->ber_indication;
        total_ber += ber;
        if (ber < current_min) current_min = ber;
        if (ber > current_max) current_max = ber;
    }

    *avg_ber = total_ber / sim->num_channels;
    *min_ber = current_min;
    *max_ber = current_max;

    pthread_mutex_unlock(&sim->lock);
}

void shutdown_network_simulation() {
    for (size_t i = 0; i < num_networks; ++i) {
        NetworkSimulation* sim = network_simulations[i];

        pthread_mutex_lock(&sim->lock);

        for (size_t j = 0; j < sim->num_channels; ++j) {
            free(sim->contexts[j]);
        }

        pthread_mutex_unlock(&sim->lock);
        pthread_mutex_destroy(&sim->lock);
    }

    free(network_simulations);
}

int main() {
    // Initialize multiple network simulations
    initialize_network_simulation(50); // Example of one network with 50 channels
    initialize_network_simulation(30); // Another network

    // Simulate some runtime before shutting down
    sleep(5);

    shutdown_network_simulation();

    return 0;
}
