#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define TIMEOUT_MS 1000
#define INITIAL_CAPACITY 1024

typedef struct {
    atomic_uintptr_t head;
    atomic_uintptr_t tail;
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} CRC_Queue;

CRC_Queue* create_crc_queue() {
    CRC_Queue* queue = (CRC_QUEUE*)malloc(sizeof(CRC_QUEUE));
    if (!queue) return NULL;

    queue->buffer = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!queue->buffer) {
        free(queue);
        return NULL;
    }

    atomic_store(&queue->head, 0);
    atomic_store(&queue->tail, 0);
    queue->capacity = INITIAL_CAPACITY;

    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);

    return queue;
}

void destroy_crc_queue(CRC_Queue* queue) {
    free(queue->buffer);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

bool enqueue(CRC_Queue* queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    size_t head = atomic_load(&queue->head);
    size_t next_head = (head + 1) % queue->capacity;

    if (next_head == atomic_load(&queue->tail)) {
        // Queue is full
        return false;
    }

    queue->buffer[head] = pdu;
    atomic_store(&queue->head, next_head);

    pthread_cond_signal(&queue->cond);
    return true;
}

bool dequeue(CRC_Queue* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    size_t tail = atomic_load(&queue->tail);

    if (tail == atomic_load(&queue->head)) {
        // Queue is empty
        return false;
    }

    *pdu = queue->buffer[tail];
    atomic_store(&queue->tail, (tail + 1) % queue->capacity);
    return true;
}

void purge_expired(CRC_Queue* queue, uint64_t current_time_ms) {
    pthread_mutex_lock(&queue->lock);

    size_t tail = atomic_load(&queue->tail);
    for (size_t i = tail; i != atomic_load(&queue->head); i = (i + 1) % queue->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &queue->buffer[i];

        uint64_t packet_time_ms = /* extract timestamp from pdu */;
        if (current_time_ms - packet_time_ms > TIMEOUT_MS) {
            // Move head to purge this entry
            atomic_store(&queue->tail, i + 1);
            pthread_cond_signal(&queue->cond);
        }
    }

    pthread_mutex_unlock(&queue->lock);
}

void process_packets(CRC_Queue* queue) {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        if (dequeue(queue, &pdu)) {
            // Process the packet
            printf("Processing packet with RNTI: %u\n", pdu.RNTI);
        } else {
            // Wait for new packets
            pthread_mutex_lock(&queue->lock);
            pthread_cond_wait(&queue->cond, &queue->lock);
            pthread_mutex_unlock(&queue->lock);
        }

        uint64_t current_time_ms = /* get current time in ms */;
        purge_expired(queue, current_time_ms);
    }
}

int main() {
    CRC_Queue* queue = create_crc_queue();
    if (!queue) {
        fprintf(stderr, "Failed to create CRC queue\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, (void *(*)(void *))process_packets, queue);

    // Simulate adding packets
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1234 };
    enqueue(queue, pdu);

    pthread_join(thread_id, NULL);
    destroy_crc_queue(queue);

    return EXIT_SUCCESS;
}
```

### Notes:
- The code uses a lock-free queue with atomic operations to minimize contention.
- A mutex and condition variable are used for safe access to the queue in `purge_expired`.
- The `process_packets` function runs in a separate thread, continuously processing packets.
- Error handling is included for memory allocation failures.
- Logging and detailed error recovery can be added as needed for debugging and performance analysis.']

