// Assume these types are defined elsewhere in your framework.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG *crcTag; // Pointer to avoid internal duplication
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **entries;
    size_t count;
    size_t capacity;
} DynamicArray;

// Status codes
#define SUCCESS 0
#define ERROR_NULL_POINTER -1
#define ERROR_INDEX_OUT_OF_BOUNDS -2
#define ERROR_MEMORY_ALLOCATION_FAILED -3

// Function prototypes
int dynamicArrayInit(DynamicArray *array, size_t initialCapacity);
int addEntry(DynamicArray *array, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG);
NFAPI_CRC_INDICATION_PDU_T* getEntryByIndex(const DynamicArray *array, size_t index);
int updateEntry(DynamicArray *array, size_t index, int newCRCFLAG);

// Initialize the dynamic array
int dynamicArrayInit(DynamicArray *array, size_t initialCapacity) {
    if (!array) return ERROR_NULL_POINTER;

    array->entries = (NFAPI_CRC_INDICATION_PDU_T**) malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array->entries) return ERROR_MEMORY_ALLOCATION_FAILED;

    array->count = 0;
    array->capacity = initialCapacity;
    return SUCCESS;
}

// Add a new entry to the dynamic array
int addEntry(DynamicArray *array, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (!array || !array->entries) return ERROR_NULL_POINTER;

    // Check if we need to expand the capacity
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **newEntries = realloc(array->entries, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!newEntries) return ERROR_MEMORY_ALLOCATION_FAILED;

        array->entries = newEntries;
        array->capacity = newCapacity;
    }

    // Allocate and set the new entry
    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) return ERROR_MEMORY_ALLOCATION_FAILED;

    entry->crcTag = (CRC_INDICATION_REL8_TAG*) malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!entry->crcTag) {
        free(entry);
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }

    entry->crcTag->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->crcTag->RNTI = RNTI;
    entry->CRCFLAG = CRCFLAG;

    array->entries[array->count++] = entry;
    return SUCCESS;
}

// Retrieve an entry by index
NFAPI_CRC_INDICATION_PDU_T* getEntryByIndex(const DynamicArray *array, size_t index) {
    if (!array || !array->entries || index >= array->count) return NULL;

    return array->entries[index];
}

// Update an existing entry's CRCFLAG
int updateEntry(DynamicArray *array, size_t index, int newCRCFLAG) {
    if (!array || !array->entries || index >= array->count) return ERROR_INDEX_OUT_OF_BOUNDS;

    NFAPI_CRC_INDICATION_PDU_T *entry = array->entries[index];
    entry->CRCFLAG = newCRCFLAG;
    return SUCCESS;
}

// Free the dynamic array
void freeDynamicArray(DynamicArray *array) {
    if (!array || !array->entries) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->entries[i]->crcTag);
        free(array->entries[i]);
    }

    free(array->entries);
    array->entries = NULL;
    array->count = 0;
    array->capacity = 0;
}

// Example of usage
int main() {
    DynamicArray array;
    if (dynamicArrayInit(&array, 10) != SUCCESS) {
        printf("Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    addEntry(&array, 1, 100, 1);
    NFAPI_CRC_INDICATION_PDU_T *entry = getEntryByIndex(&array, 0);
    if (entry) {
        printf("Retrieved entry: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               entry->crcTag->RX_UE_INFORMATION_TAG, entry->crcTag->RNTI, entry->CRCFLAG);
    }

    updateEntry(&array, 0, 0);
    entry = getEntryByIndex(&array, 0);
    if (entry) {
        printf("Updated entry: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               entry->crcTag->RX_UE_INFORMATION_TAG, entry->crcTag->RNTI, entry->CRCFLAG);
    }

    freeDynamicArray(&array);

    return EXIT_SUCCESS;
}
