// Log structure to minimize storage space
typedef struct {
    char* timestamp;
    size_t size;
    const void* data;
} AllocationLog;

#define LOG_BUFFER_SIZE 1024
AllocationLog logBuffer[LOG_BUFFER_SIZE];
int logIndex = 0;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

// Utility function to add logs
void add_log(const char* operation, const void* ptr, size_t size) {
    pthread_mutex_lock(&logMutex);
    if (logIndex < LOG_BUFFER_SIZE) {
        time_t rawtime;
        struct tm *info;

        time(&rawtime);
        info = localtime(&rawtime);

        logBuffer[logIndex].timestamp = strdup(asctime(info));
        logBuffer[logIndex].size = size;
        logBuffer[logIndex].data = ptr;
        logIndex++;
    }
    pthread_mutex_unlock(&logMutex);
}

// Function to manage a dynamic array of NFAPI_RRC_MEASUREMENT_REPORT_PDU_T structures
NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* manage_measurement_reports(unsigned int seed, size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Requested elements exceed maximum limit.\n");
        return NULL;
    }

    srand(seed);

    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T *array = malloc(num_elements * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for %zu elements.\n", num_elements);
        return NULL;
    }

    add_log("ALLOCATE", array, num_elements * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));

    for (size_t i = 0; i < num_elements; ++i) {
        // Ensure unique CELL_ID, RNTI and MEASUREMENT_ID
        array[i].CELL_ID = rand() % MAX_ELEMENTS + 1;
        array[i].RNTI = rand() % MAX_ELEMENTS + 1;
        array[i].MEASUREMENT_ID = rand() % MAX_ELEMENTS + 1;

        // Determine the measurement result with a pseudo-random value
        array[i].MEASUREMENT_RESULT = rand() % 2; // Random 0 or 1
    }

    return array;
}

// Function to free the dynamic array and log deallocation
void free_measurement_reports(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* array, size_t num_elements) {
    if (array != NULL) {
        add_log("DEALLOCATE", array, num_elements * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
        free(array);
    }
}

// Example function to demonstrate parallel processing
void process_measurement_report(void* arg) {
    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* report = (NFAPI_RRC_MEASUREMENT_REPORT_PDU_T*)arg;

    // Process the report here...
    printf("Processing CELL_ID: %d, RNTI: %d, MEASUREMENT_ID: %d\n",
           report->CELL_ID, report->RNTI, report->MEASUREMENT_ID);
}

// Function to demonstrate parallel processing of reports
void parallel_process_reports(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* array, size_t num_elements) {
    pthread_t threads[num_elements];

    for (size_t i = 0; i < num_elements; ++i) {
        if (pthread_create(&threads[i], NULL, process_measurement_report, &array[i])) {
            fprintf(stderr, "Error creating thread\n");
            break;
        }
    }

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    size_t num_reports = 5000; // Example number of reports
    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T* reports = manage_measurement_reports(time(NULL), num_reports);

    if (reports != NULL) {
        parallel_process_reports(reports, num_reports);
        free_measurement_reports(reports, num_reports);
    }

    return 0;
}
