uint32_t findLargestInteger(int validIntegers[], int count) {
    if (count == 0) return -1; // Return -1 if no valid integers
    uint32_t largest = validIntegers[0];
    for (int i = 1; i < count; ++i) {
        if (validIntegers[i] > largest) {
            largest = validIntegers[i];
        }
    }
    return largest;
}

char* computeMD5(const char *inputString, char *outputBuffer) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, strlen(inputString), (unsigned char*)&digest);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(outputBuffer + (i * 2), "%02x", (unsigned int)digest[i]);
    }
    outputBuffer[MD5_DIGEST_LENGTH * 2] = '\0';
    return outputBuffer;
}

