        pdus[i].RNTI = i + 1;
        pdus[i].CRC_INDICATION_REL8_TAG = (i % 2 == 0) ? 1 : 0; // Example logic for CRC
    }

    char md5Output[33] = {0};
    computeMD5("Example input string", md5Output);
    printf("MD5 Hash: %s\n", md5Output);

    for (int i = 0; i < numPDU; ++i) {
