['Below is a C function that dynamically allocates memory for and initializes multiple data structures as described. It includes error handling, validation, random value assignment, and efficient memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *label;
} record;

void initialize_data(int num_keys, const char **labels, size_t label_lengths[], 
                     long (*offsets)[], int (*keys)[] ,record (**records)[],
                     char *error_buffer, int min_value, int max_value) {

    // Seed the random number generator
    srand(time(NULL));

    // Validate that offsets is at least twice the size of keys
    if (num_keys > 0 && *offsets == NULL || num_keys * 2 <= sizeof(*offsets) / sizeof((**offsets)[0])) {
        snprintf(error_buffer, 256, "Offset array size must be at least twice the size of key array.");
        return;
    }

    // Allocate memory for keys and offsets
    *keys = (int *)malloc(num_keys * sizeof(int));
    if (*keys == NULL) {
        snprintf(error_buffer, 256, "Failed to allocate memory for keys.");
        return;
    }

    *offsets = (long (*)[num_keys * 2])malloc(sizeof(long[num_keys * 2]));
    if (*offsets == NULL) {
        free(*keys);
        snprintf(error_buffer, 256, "Failed to allocate memory for offsets.");
        return;
    }

    // Allocate memory for records
    *records = (record (*)[num_keys])malloc(sizeof(record[num_keys]));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        snprintf(error_buffer, 256, "Failed to allocate memory for records.");
        return;
    }

    // Initialize keys and offsets with random values
    for (int i = 0; i < num_keys; ++i) {
        (*keys)[i] = rand() % ((max_value - min_value + 1) + min_value); // Random int within range

        for (int j = 0; j < num_keys * 2; ++j) {
            (*offsets)[j][i] = rand(); // Random long value
        }

        // Allocate and initialize string labels
        char *label_copy = (char *)malloc(label_lengths[i] + 1);
        if (label_copy == NULL) {
            for (int k = 0; k < i; ++k) {
                free((*records)[k][0].label); // Free already allocated memory
            }
            free(*offsets);
            free(*keys);
            free(*records);
            snprintf(error_buffer, 256, "Failed to allocate memory for label strings.");
            return;
        }

        strncpy(label_copy, labels[i], label_lengths[i]);
        label_copy[label_lengths[i]] = '\0';

        // Initialize records
        (*records)[i][0].value = rand() % ((max_value - min_value + 1) + min_value); // Random int within range
        (*records)[i][0].label = label_copy;
    }

    printf("Data structures initialized successfully.\n");
}

int main() {
    const char *labels[] = {"Label1", "Label2"};
    size_t label_lengths[] = {6, 6};
    long offsets[2];
    int keys[2];
    record records[2];
    char error_buffer[256];

    initialize_data(2, labels, label_lengths, &offsets, &keys, &records, error_buffer, 10, 20);

    if (strlen(error_buffer) > 0) {
        printf("Error: %s\n", error_buffer);
    }

    // Clean up
    for (int i = 0; i < 2; ++i) {
        free(records[i][0].label);
    }
    free(keys);
    free(offsets[0]);
    free(offsets);
    free(records);

    return 0;
}
```

This function handles dynamic memory allocation, error handling, and initializes data structures as described. It also includes checks for allocation failures and validation for the size of the `offset` array relative to the `key` array.']

