void* align_ptr(void *ptr, size_t alignment) {
    uintptr_t address = (uintptr_t)ptr;
    if ((address % alignment) != 0) {
        address += alignment - (address % alignment);
    }
    return (void*)address;
}

int next_power_of_two(size_t n) {
    --n;
    n |= n >> 1;
    n |= n >> 2;
    n |= n >> 4;
    n |= n >> 8;
    n |= n >> 16;
