    return list;
}

void resize_if_needed(MessageList *list) {
    if ((float)list->count / list->capacity > LOAD_FACTOR) {
        size_t new_capacity = list->capacity * 2;
        Message *new_messages = calloc(new_capacity, sizeof(Message));

        for (size_t i = 0; i < list->count; ++i) {
            new_messages[i] = list->messages[i];
        }

        free(list->messages);
        list->messages = new_messages;
        list->capacity = new_capacity;
    }
}

void insert_message(MessageList *list, Message message) {
    pthread_mutex_lock(&list->lock);

    resize_if_needed(list);

    list->messages[list->count++] = message;

    // Log the insertion
    FILE *log_file = fopen("operations.log", "a");
    if (log_file) {
        fprintf(log_file, "INSERT: User ID %d at %ld with priority %d\n",
                message.user_id, message.timestamp, message.priority);
        fclose(log_file);
    }

    pthread_mutex_unlock(&list->lock);
}

Message* query_recent_by_user(MessageList *list, int user_id) {
    Message *recent_message = NULL;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->messages[i].user_id == user_id && 
            (!recent_message || list->messages[i].timestamp > recent_message->timestamp)) {
            recent_message = &list->messages[i];
        }
    }

    pthread_mutex_unlock(&list->lock);

    return recent_message;
}

MessageList* query_by_priority(MessageList *list, int priority) {
    MessageList *result = create_message_list();

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->messages[i].priority == priority) {
            insert_message(result, list->messages[i]);
        }
    }

    pthread_mutex_unlock(&list->lock);

    return result;
}

void serialize_to_file(MessageList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->count, sizeof(list->count), 1, file);
    fwrite(list->messages, sizeof(Message), list->count, file);

    fclose(file);
}

MessageList* deserialize_from_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    MessageList *list = create_message_list();

    fread(&list->count, sizeof(list->count), 1, file);
    resize_if_needed(list); // Ensure enough capacity

    fread(list->messages, sizeof(Message), list->count, file);

    fclose(file);
    return list;
}

void free_message_list(MessageList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->messages);
    free(list);
}
```

### Key Features:
- **Thread Safety**: Used `pthread_mutex` to protect concurrent access.
- **Dynamic Resizing**: The array of messages is resized when needed, doubling capacity each time the load factor exceeds 0.75.
- **Serialization/Deserialization**: Implemented using file I/O for saving/loading message lists from disk.
- **Logging**: Simple logging mechanism to a file (`operations.log`) that logs every insertion.
- **Memory Management**: Allocates memory dynamically and uses `calloc` to initialize arrays.

### Notes:
- For production-grade applications, consider more sophisticated hash tables or balanced trees for faster lookups by user ID. 
- Additional features such as deletion of messages or enhanced logging would require further code adjustments.
- Further optimizations may involve replacing simple mutex locks with finer-grained locking mechanisms if contention becomes an issue.']

