}

uint32_t simple_hash(int key) {
    return (key * 2654435761u) % table_size;
}

void free_memory(hash_node_t** table) {
    for (size_t i = 0; i < table_size; ++i) {
        hash_node_t* entry = table[i];
        while (entry != NULL) {
            hash_node_t* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(table);
}

int init_memory_system(size_t memory_limit) {
    if (memory_limit < TOTAL_MEMORY_LIMIT) {
        log("Memory limit too small to hold all records.");
        return -1;
    }

    hash_table = malloc(table_size * sizeof(hash_node_t*));
    if (!hash_table) {
        log("Failed to allocate memory for the hash table.");
        return -1;
    }
    memset(hash_table, 0, table_size * sizeof(hash_node_t*));

    // Additional logging or monitoring logic can be placed here.

    return 0;
}

void insert_record(int key, long offset_range_min, long offset_range_max) {
    uint32_t hash_key = simple_hash(key);
    record_t new_record = { (long)(rand() % (offset_range_max - offset_range_min + 1)) + offset_range_min,
                            (short)key }; // unique identifier as metadata

    hash_node_t* node = malloc(sizeof(hash_node_t));
    if (!node) {
        log("Failed to allocate memory for new record.");
        return;
    }
    node->key = key;
    node->data = new_record;

    hash_node_t* entry = hash_table[hash_key];
    node->next = entry;
    hash_table[hash_key] = node;
}

record_t* get_record(int key) {
    uint32_t hash_key = simple_hash(key);
    hash_node_t* entry = hash_table[hash_key];

    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }

    return (entry == NULL) ? NULL : &(entry->data);
}

void compact_memory() {
    // Placeholder for a memory compaction logic to reduce fragmentation.
    log("Memory compaction executed.");
}

void cleanup_system() {
    free_memory(hash_table);
    log("All allocated memory freed successfully.");
}

int main() {
    size_t memory_limit = TOTAL_MEMORY_LIMIT + 1024 * 512; // Example limit
    if (init_memory_system(memory_limit) != 0) {
        log("Initialization failed due to memory constraints.");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < MAX_KEYS; ++i) {
        insert_record(i, 1, 100);
    }

    compact_memory();

    for (int i = 0; i < MAX_KEYS; ++i) {
        record_t* rec = get_record(i);
        if (rec != NULL) {
            log("Retrieved Record: Offset = %ld, Metadata = %d", rec->offset, rec->metadata);
        }
    }

    cleanup_system();
    return EXIT_SUCCESS;
}
