#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id; // Example field
    char data[256]; // Example field
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_MANAGER_T;

// Function to initialize the manager
NFAPI_CRC_MANAGER_T* nfa_crc_manager_init(size_t initial_capacity) {
    NFAPI_CRC_MANAGER_T* manager = (NFAPI_CRC_MANAGER_T*)malloc(sizeof(NFAPI_CRC_MANAGER_T));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to add or update an element
int nfa_crc_manager_add_or_update(NFAPI_CRC_MANAGER_T* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager || !pdu.data) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check for existing entry and update it
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].id == pdu.id) {
            memcpy(&manager->array[i], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // If not found, add new entry
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    memcpy(&manager->array[manager->size], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to delete an element
int nfa_crc_manager_delete(NFAPI_CRC_MANAGER_T* manager, int id) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].id == id) {
            memmove(&manager->array[i], &manager->array[i + 1], (manager->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

// Function to free the manager
void nfa_crc_manager_free(NFAPI_CRC_MANAGER_T* manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->array);
    free(manager);
}
