        new_pdus[i] = list->pdus[i];
    }

    free(list->pdus);
    list->pdus = new_pdus;
    list->capacity = new_capacity;
}

// Add a MAC_PDU to the list
void add_pdu(PDU_List *list, L2_HEADER *l2_header, MACSDU *macsdu, L3_HEADER *l3_header) {
