}

// Free the dynamic list
void free_pdu_list(PDU_List *list) {
    for (size_t i = 0; i < list->count; ++i) {
        pthread_mutex_lock(&list->pdus[i]->lock);
        free(list->pdus[i]);
        pthread_mutex_unlock(&list->pdus[i]->lock);
    }
    free(list->pdus);
    pthread_rwlock_destroy(&list->rwlock);
