#define MAX_OFFSET 1000000
#define HASH_TABLE_INITIAL_CAPACITY 1024

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct HashNode {
    long offset;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    size_t size;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(initial_capacity, sizeof(HashNode*));
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

unsigned long hash(long offset, size_t capacity) {
    return (unsigned long)(offset % capacity);
}

int hash_table_insert(HashTable* table, long offset) {
    if (table->size >= table->capacity * 0.75) {
        // Simple rehashing strategy
        size_t new_capacity = table->capacity * 2;
        HashNode** new_buckets = calloc(new_capacity, sizeof(HashNode*));

        for (size_t i = 0; i < table->capacity; ++i) {
            HashNode* node = table->buckets[i];
            while (node) {
                unsigned long index = hash(node->offset, new_capacity);
                HashNode* next_node = node->next;
                node->next = new_buckets[index];
                new_buckets[index] = node;
                node = next_node;
            }
        }

        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }

    unsigned long index = hash(offset, table->capacity);
    HashNode* node = malloc(sizeof(HashNode));
    if (!node) return 0; // Memory allocation failed

    node->offset = offset;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    ++table->size;
    return 1;
}

int hash_table_contains(HashTable* table, long offset) {
    unsigned long index = hash(offset, table->capacity);
    HashNode* node = table->buckets[index];
    while (node) {
        if (node->offset == offset) return 1;
        node = node->next;
    }
    return 0;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(table->buckets);
    free(table);
}

int compare_records(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    return (recordA->offset > recordB->offset) - (recordA->offset < recordB->offset);
}

void initialize_records(Record* records, size_t num_records, double min_value, double max_value) {
    srand(time(NULL));
    HashTable* table = create_hash_table(HASH_TABLE_INITIAL_CAPACITY);

    for (size_t i = 0; i < num_records;) {
        long offset;
        do {
            offset = rand() % MAX_OFFSET + 1;
        } while (!hash_table_insert(table, offset));

        records[i].offset = offset;
        records[i].key = rand(); // Simple key generation
        records[i].value = min_value + (rand() / (double)RAND_MAX) * (max_value - min_value);

        ++i;
    }

    qsort(records, num_records, sizeof(Record), compare_records);
    free_hash_table(table);
}

void add_record(Record** records, size_t* current_size, size_t* allocated_size, long offset, int key, double value) {
    if (*current_size >= *allocated_size) {
        *allocated_size *= 2;
        *records = realloc(*records, *allocated_size * sizeof(Record));
    }
    (*records)[(*current_size)++] = (Record){offset, key, value};
}

void remove_record(Record** records, size_t* current_size, long offset) {
    for (size_t i = 0; i < *current_size; ++i) {
        if ((*records)[i].offset == offset) {
            memmove(&(*records)[i], &(*records)[i + 1], (*current_size - i - 1) * sizeof(Record));
            --*current_size;
            break;
        }
    }
}

void manage_records(size_t num_records, double min_value, double max_value) {
    Record* records = malloc(num_records * sizeof(Record));
    if (!records) return; // Handle allocation failure

    initialize_records(records, num_records, min_value, max_value);

    // Example usage of add and remove
    size_t current_size = num_records;
    size_t allocated_size = num_records;

    add_record(&records, &current_size, &allocated_size, 123456, 42, 3.14);
    remove_record(&records, &current_size, 1);

    // Process records with external library here

    free(records);
}

int main() {
    manage_records(1000, 0.0, 10.0);
    return 0;
}
