#define INITIAL_SIZE 10

typedef struct {
    uint8_t destination[6];
    uint8_t source[6];
    // Additional L2_HEADER fields...
} L2_HEADER;

typedef struct {
    uint8_t data[];
} MACSDU;

typedef struct {
    uint8_t protocol_type;
    uint16_t length;
    // Additional L3_HEADER fields...
} L3_HEADER;

typedef struct {
    L2_HEADER l2_header;
    MACSDU macsdu;
    L3_HEADER *l3_header;  // Optional
} MAC_PDU;

typedef struct {
    MAC_PDU *entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MacPduList;

MacPduList* create_mac_pdu_list(size_t initial_capacity) {
    MacPduList *list = malloc(sizeof(MacPduList));
    if (!list) return NULL;

    list->entries = malloc(initial_capacity * sizeof(MAC_PDU));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_mac_pdu_list(MacPduList *list, size_t new_capacity) {
    MAC_PDU *new_entries = realloc(list->entries, new_capacity * sizeof(MAC_PDU));
    if (new_entries) {
        list->entries = new_entries;
        list->capacity = new_capacity;
    } else {
        // Log memory allocation failure
        fprintf(stderr, "Memory allocation failed during resize.\n");
    }
}

void add_mac_pdu(MacPduList *list, MAC_PDU pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        resize_mac_pdu_list(list, new_capacity);
    }

    list->entries[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
}

void remove_mac_pdu(MacPduList *list, size_t index) {
    if (index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    free(list->entries[index].l3_header); // Free optional L3_HEADER
    memmove(&list->entries[index], &list->entries[index + 1],
            (list->size - index - 1) * sizeof(MAC_PDU));

    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void serialize_mac_pdu_list(const MacPduList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; ++i) {
        fwrite(&list->entries[i], sizeof(MAC_PDU), 1, file);
        if (list->entries[i].l3_header) {
            size_t len = sizeof(L3_HEADER) + /* dynamic length */ 0;
            fwrite(&len, sizeof(size_t), 1, file);
            fwrite(list->entries[i].l3_header, len, 1, file);
        } else {
            fwrite(&((size_t)0), sizeof(size_t), 1, file); // Null size for no L3_HEADER
        }
    }

    fclose(file);
}

void deserialize_mac_pdu_list(MacPduList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    fread(&list->size, sizeof(size_t), 1, file);

    resize_mac_pdu_list(list, list->size); // Resize to exact needed size

    for (size_t i = 0; i < list->size; ++i) {
        fread(&list->entries[i], sizeof(MAC_PDU), 1, file);

        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        if (len > 0) {
            list->entries[i].l3_header = malloc(len);
            fread(list->entries[i].l3_header, len, 1, file);
        } else {
            list->entries[i].l3_header = NULL;
        }
    }

    fclose(file);
}

void free_mac_pdu_list(MacPduList *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->entries[i].l3_header); // Free optional L3_HEADER
    }

    free(list->entries);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Additional functions to handle configuration service integration, logging, etc.
