} Record;

typedef struct {
    bool *used_offsets;
    size_t capacity;
} HashTable;

HashTable* create_hash_table(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    table->used_offsets = calloc(capacity, sizeof(bool));
    table->capacity = capacity;
    return table;
}

void free_hash_table(HashTable *table) {
    free(table->used_offsets);
    free(table);
}

bool check_and_set_offset(HashTable *table, long offset) {
    if (offset <= 0 || offset >= table->capacity) return false;
    if (!table->used_offsets[offset]) {
        table->used_offsets[offset] = true;
        return true;
    }
    return false;
}

void free_records(Record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_destroy(&records[i].lock);
    }
    free(records);
}

Record* initialize_records(size_t num_records, double range_min, double range_max, HashTable *table) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    srand(time(NULL));

    for (size_t i = 0; i < num_records;) {
        long offset = rand() % table->capacity;
        int key = rand();
        double value = range_min + ((double)rand() / RAND_MAX) * (range_max - range_min);

        if (check_and_set_offset(table, offset)) {
            records[i].offset = offset;
            records[i].key = key;
            records[i].value = value;
            records[i].log_count = 0;
            pthread_mutex_init(&records[i].lock, NULL);
            i++;
        }
    }

    return records;
}

int find_largest_integer(int *array, size_t size) {
    if (size == 0) return INT_MIN;

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void process_input_and_find_largest(int *arr, size_t size) {
    printf("Enter %zu integers:\n", size);
    for (size_t i = 0; i < size; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Invalid input detected.\n");
            exit(EXIT_FAILURE);
        }
    }

    int largest = find_largest_integer(arr, size);
    printf("The largest integer is: %d\n", largest);
}

int main() {
    size_t num_records = 1000000;
    double range_min = 1.0, range_max = 100.0;

    HashTable *table = create_hash_table(num_records);
    if (!table) {
        fprintf(stderr, "Failed to allocate hash table.\n");
        return EXIT_FAILURE;
    }

    Record *records = initialize_records(num_records, range_min, range_max, table);
    if (!records) {
        fprintf(stderr, "Failed to allocate records.\n");
        free_hash_table(table);
        return EXIT_FAILURE;
    }

    size_t num_integers = 10;
    int *int_array = malloc(num_integers * sizeof(int));
    if (!int_array) {
        fprintf(stderr, "Failed to allocate integer array.\n");
        free_records(records, num_records);
        free_hash_table(table);
        return EXIT_FAILURE;
    }

    process_input_and_find_largest(int_array, num_integers);

    free(int_array);
    free_records(records, num_records);
    free_hash_table(table);

    return 0;
}
```

### Key Points:
- **Memory Management**: Uses a pool allocator-like approach by managing memory in bulk for records and offsets.
- **Concurrency**: Utilizes `pthread_mutex_t` to ensure thread-safe logging within each record.
- **Validation**: Ensures unique, positive long offsets using a hash table.
- **Error Handling**: Checks for allocation failures and invalid inputs.
- **Extensibility**: Structs are designed to allow easy addition of new fields without breaking existing functionality.']

