#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef struct {
    int id;
    float value;
    char *description;
} Data;

typedef struct SessionNode {
    double *floatArray;
    size_t floatArraySize;
    size_t floatArrayCapacity;

    char **charKeys;
    size_t charKeysSize;
    size_t charKeysCapacity;

    Data *dataArray;
    size_t dataArraySize;
    size_t dataArrayCapacity;

    // Session-specific metadata
    int sessionId;
    pthread_mutex_t lock;

    struct SessionNode *next;
} SessionNode;

SessionNode* createSession(int sessionId) {
    SessionNode *session = malloc(sizeof(SessionNode));
    session->sessionId = sessionId;
    session->floatArraySize = 0;
    session->floatArrayCapacity = INITIAL_SIZE;
    session->floatArray = malloc(session->floatArrayCapacity * sizeof(double));

    session->charKeysSize = 0;
    session->charKeysCapacity = INITIAL_SIZE;
    session->charKeys = malloc(session->charKeysCapacity * sizeof(char*));

    session->dataArraySize = 0;
    session->dataArrayCapacity = INITIAL_SIZE;
    session->dataArray = malloc(session->dataArrayCapacity * sizeof(Data));

    pthread_mutex_init(&session->lock, NULL);

    return session;
}

void appendFloatArray(SessionNode *session, double value) {
    pthread_mutex_lock(&session->lock);

    if (session->floatArraySize == session->floatArrayCapacity) {
        size_t newCapacity = session->floatArrayCapacity * 2;
        double *newArray = realloc(session->floatArray, newCapacity * sizeof(double));
        if (!newArray) {
            perror("Failed to reallocate memory for floatArray");
            exit(EXIT_FAILURE);
        }
        session->floatArray = newArray;
        session->floatArrayCapacity = newCapacity;
    }

    session->floatArray[session->floatArraySize++] = value;

    pthread_mutex_unlock(&session->lock);
}

void appendCharKeys(SessionNode *session, const char *key) {
    pthread_mutex_lock(&session->lock);

    if (session->charKeysSize == session->charKeysCapacity) {
        size_t newCapacity = session->charKeysCapacity * 2;
        char **newArray = realloc(session->charKeys, newCapacity * sizeof(char*));
        if (!newArray) {
            perror("Failed to reallocate memory for charKeys");
            exit(EXIT_FAILURE);
        }
        session->charKeys = newArray;
        session->charKeysCapacity = newCapacity;
    }

    session->charKeys[session->charKeysSize++] = strdup(key);

    pthread_mutex_unlock(&session->lock);
}

void appendDataArray(SessionNode *session, Data data) {
    pthread_mutex_lock(&session->lock);

    if (session->dataArraySize == session->dataArrayCapacity) {
        size_t newCapacity = session->dataArrayCapacity * 2;
        Data *newArray = realloc(session->dataArray, newCapacity * sizeof(Data));
        if (!newArray) {
            perror("Failed to reallocate memory for dataArray");
            exit(EXIT_FAILURE);
        }
        session->dataArray = newArray;
        session->dataArrayCapacity = newCapacity;
    }

    session->dataArray[session->dataArraySize++] = data;

    pthread_mutex_unlock(&session->lock);
}

void freeSession(SessionNode *session) {
    if (!session) return;

    for (size_t i = 0; i < session->charKeysSize; ++i) {
        free(session->charKeys[i]);
    }

    free(session->floatArray);
    free(session->charKeys);
    free(session->dataArray);

    pthread_mutex_destroy(&session->lock);
    free(session);
}

void ingestData(SessionNode *session, double floatVal, const char *key, Data data) {
    appendFloatArray(session, floatVal);
    appendCharKeys(session, key);
    appendDataArray(session, data);
}

// Example of how to use the above functions
int main() {
    SessionNode *session = createSession(1);

    // Simulate ingestion of data
    ingestData(session, 3.14, "temperature", (Data){ .id = 1, .value = 23.5f, .description = "Temperature reading" });

    freeSession(session);
    return 0;
}
```

### Key Points:
- **Dynamic Memory Allocation**: The code uses `malloc` and `realloc` to dynamically manage memory for the arrays.
- **Thread Safety**: Mutexes (`pthread_mutex_t`) are used to ensure thread safety when updating shared data structures.
- **Atomic Operations**: While not explicitly using atomic operations, mutex locks provide atomicity in updates.
- **Scalability**: The code supports dynamic resizing of arrays to accommodate new entries efficiently.
- **Resource Management**: Proper memory cleanup is ensured with `freeSession`, which also destroys the mutexes.

This implementation provides a balance between performance and resource management while ensuring thread safety.']

