['Below is a C implementation that addresses your requirements for initializing a dynamic array of record structures with efficient memory management, parallel initialization using multiple threads, serialization/deserialization support, and robust error handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} DynamicArray;

// Function prototypes
DynamicArray* initialize_array(size_t initial_capacity);
void free_array(DynamicArray *array);
int add_record(DynamicArray *array, long offset, int key, double value);
void serialize_array(const char *filename, const DynamicArray *array);
int deserialize_array(const char *filename, DynamicArray *array);
void *initialize_records_thread(void *args);

// Initialize dynamic array
DynamicArray* initialize_array(size_t initial_capacity) {
    if (initial_capacity == 0)
        return NULL;

    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array)
        return NULL;

    array->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;

    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond_var, NULL);

    return array;
}

// Free dynamic array
void free_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        pthread_cond_destroy(&array->cond_var);

        free(array->records);
        free(array);
    }
}

// Add record to the array ensuring unique offset > 0
int add_record(DynamicArray *array, long offset, int key, double value) {
    if (offset <= 0)
        return -1;

    pthread_mutex_lock(&array->lock);

    // Expand capacity if needed
    while (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record *new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }

    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i].offset == offset)
            goto unlock_and_return;
    }

    array->records[array->count++] = (Record){offset, key, value};

unlock_and_return:
    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Serialization to disk
void serialize_array(const char *filename, const DynamicArray *array) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return;

    fwrite(&(array->count), sizeof(array->count), 1, file);
    fwrite(array->records, sizeof(Record), array->count, file);

    fclose(file);
}

// Deserialization from disk
int deserialize_array(const char *filename, DynamicArray *array) {
    FILE *file = fopen(filename, "rb");
    if (!file)
        return -1;

    size_t count;
    fread(&count, sizeof(count), 1, file);

    Record *new_records = (Record*)realloc(array->records, count * sizeof(Record));
    if (!new_records) {
        fclose(file);
        return -1; // Memory allocation failure
    }

    array->records = new_records;
    fread(array->records, sizeof(Record), count, file);

    array->count = count;
    array->capacity = count;

    fclose(file);
    return 0;
}

// Thread function for parallel record initialization
void *initialize_records_thread(void *args) {
    DynamicArray *array = (DynamicArray*)args;
    size_t start_index = rand() % array->capacity; // Simple random start point

    pthread_mutex_lock(&array->lock);
    while (array->count < array->capacity) {
        long offset = array->count + 1;
        int key = rand() % 1000; 
        double value = ((double)rand()) / RAND_MAX * 100.0;

        add_record(array, offset, key, value);

        if (array->count % 10000 == 0) {
            pthread_cond_signal(&array->cond_var);
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

// Example of parallel initialization
void initialize_records_parallel(DynamicArray *array, int num_threads) {
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_records_thread, array)) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    srand(time(NULL));

    DynamicArray *array = initialize_array(10000000); // Initial capacity for up to 10 million records

    if (!array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return 1;
    }

    int num_threads = 4; // Example thread count
    initialize_records_parallel(array, num_threads);

    serialize_array("records.dat", array);
    free_array(array);

    DynamicArray *loaded_array = initialize_array(0); // Start with no capacity
    if (!loaded_array) {
        fprintf(stderr, "Failed to reinitialize dynamic array\n");
        return 1;
    }

    deserialize_array("records.dat", loaded_array);

    free_array(loaded_array);
    return 0;
}
```

### Key Features:
- **Dynamic Memory Management**: Efficient memory allocation using `calloc` and `realloc`.
- **Parallel Initialization**: Uses multiple threads to speed up the initialization process.
- **Serialization/Deserialization**: Saves records to disk and reads them back efficiently.
- **Thread Safety**: Mutexes ensure thread-safe operations, while condition variables can help in signaling among threads if needed for advanced use cases.
- **Error Handling**: Checks and handles memory allocation failures gracefully.
- **Scalability**: Supports up to 10 million records by doubling the capacity as necessary.']

