#include <stdio.h>
#include <stdlib.h>

void find_and_print_largest(int *array, size_t size) {
    if (size == 0) {
        printf("Error: No integers to process.\n");
        return;
    }

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("The largest integer is: %d\n", largest);
}

int main() {
    int *array = NULL;
    size_t capacity = 10, size = 0;

    printf("Enter integers (type 'done' to finish):\n");

    char input[100];
    while (1) {
        if (scanf("%99s", input) != 1) {
            fprintf(stderr, "Error reading input.\n");
            continue;
        }

        if (strcmp(input, "done") == 0) break;

        int num = atoi(input);
        if (size >= capacity) {
            capacity *= 2;
            array = realloc(array, capacity * sizeof(int));
            if (!array) {
                fprintf(stderr, "Memory allocation failed.\n");
                return EXIT_FAILURE;
            }
        }

        array[size++] = num;
    }

    find_and_print_largest(array, size);

    free(array);
    return 0;
}
