['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_UES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    double SNR_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    NFAPI_MESSAGE_PDU_T* pool[MAX_UES];
    pthread_mutex_t lock;
} UEPool;

void init_UEPool(UEPool* ues) {
    for (int i = 0; i < MAX_UES; ++i) {
        ues->pool[i] = NULL;
    }
    pthread_mutex_init(&ues->lock, NULL);
}

NFAPI_MESSAGE_PDU_T* get_UEFromPool(UEPool* ues) {
    pthread_mutex_lock(&ues->lock);
    for (int i = 0; i < MAX_UES; ++i) {
        if (!ues->pool[i]) {
            pthread_mutex_unlock(&ues->lock);
            return malloc(sizeof(NFAPI_MESSAGE_PDU_T));
        }
    }
    pthread_mutex_unlock(&ues->lock);
    return NULL;
}

void release_UEToPool(UEPool* ues, NFAPI_MESSAGE_PDU_T* ue) {
    pthread_mutex_lock(&ues->lock);
    for (int i = 0; i < MAX_UES; ++i) {
        if (!ues->pool[i]) {
            ues->pool[i] = ue;
            pthread_mutex_unlock(&ues->lock);
            return;
        }
    }
    free(ue); // No available slots in the pool
    pthread_mutex_unlock(&ues->lock);
}

void simulateRadioConditions(NFAPI_MESSAGE_PDU_T* ue, double noise_level) {
    // Example radio condition simulation
    ue->RX_UE_INFORMATION_TAG = rand() % 100;
    ue->RNTI = rand() % 1000;
    ue->CRC_INDICATION_REL8_TAG = rand() % 10;

    // Simulate SNR with simple model: actual signal - noise level + fading effects
    double base_snr = (rand() % 20) + 30.0; 
    double fading_loss = (rand() % 5);
    ue->SNR_INDICATION_REL8_TAG = base_snr - noise_level - fading_loss;
}

void initialize_UEMessages(NFAPI_MESSAGE_PDU_T* ues, int num_ues, double noise_level) {
    if (num_ues <= 0 || num_ues > MAX_UES) return;

    UEPool pool;
    init_UEPool(&pool);

    for (int i = 0; i < num_ues; ++i) {
        NFAPI_MESSAGE_PDU_T* ue = get_UEFromPool(&pool);
        if (!ue) break; // Pool exhausted

        simulateRadioConditions(ue, noise_level);
        ues[i] = *ue;
        release_UEToPool(&pool, ue);
    }
}

int main() {
    double noise_level = 5.0;
    NFAPI_MESSAGE_PDU_T* ue_messages[MAX_UES];

    initialize_UEMessages(ue_messages, 100, noise_level);

    for (int i = 0; i < 100; ++i) {
        printf("UE %d: RX_TAG=%d RNTI=%d CRC_TAG=%d SNR=%.2f\n",
               i + 1,
               ue_messages[i].RX_UE_INFORMATION_TAG,
               ue_messages[i].RNTI,
               ue_messages[i].CRC_INDICATION_REL8_TAG,
               ue_messages[i].SNR_INDICATION_REL8_TAG);
    }

    return 0;
}
```

