typedef struct {
    int id;
    int priority;
    char status[10];
} Task;

// Function to allocate memory for an array of Tasks
Task* create_tasks(int initial_count, int priority_range) {
    if (initial_count <= 0 || priority_range <= 0) return NULL;

    Task *tasks = malloc(initial_count * sizeof(Task));
    if (!tasks) return NULL;

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < initial_count; ++i) {
        tasks[i].id = i + 1;
        tasks[i].priority = rand() % priority_range;
        strcpy(tasks[i].status, "pending");
    }

    return tasks;
}

// Function to add a new task at the given position
int add_task(Task **tasks, int *task_count, int new_priority) {
    if (!tasks || !*tasks) return -1;

    Task *new_tasks = realloc(*tasks, (*task_count + 1) * sizeof(Task));
    if (!new_tasks) return -1;

    int position = 0;
    while (position < *task_count && (*tasks)[position].priority <= new_priority)
        ++position;

    memmove(&new_tasks[position + 1], &new_tasks[position],
            (*task_count - position) * sizeof(Task));

    new_tasks[position].id = (*task_count) + 1;
    new_tasks[position].priority = new_priority;
    strcpy(new_tasks[position].status, "pending");

    *tasks = new_tasks;
    ++(*task_count);

    return position; // Position where the task was inserted
}

// Function to update a task's status or priority
void update_task(Task *tasks, int count, int id, const char *new_status, int new_priority) {
    for (int i = 0; i < count; ++i) {
        if (tasks[i].id == id) {
            if (new_status) strcpy(tasks[i].status, new_status);
            if (new_priority >= 0) tasks[i].priority = new_priority;
            break;
        }
    }
}

// Function to serialize tasks to a file
int serialize_tasks(const Task *tasks, int count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&count, sizeof(count), 1, file);
    fwrite(tasks, sizeof(Task), count, file);

    fclose(file);
    return 0;
}

// Function to deserialize tasks from a file
Task* deserialize_tasks(const char *filename, int *out_count) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    Task *tasks;
    fread(out_count, sizeof(*out_count), 1, file);

    tasks = malloc((*out_count) * sizeof(Task));
    if (!tasks) {
        fclose(file);
        return NULL;
    }

    fread(tasks, sizeof(Task), *out_count, file);

    fclose(file);
    return tasks;
}

// Main function for demonstration purposes
int main() {
    int task_count = 5;
    Task *tasks = create_tasks(task_count, 10);

    if (!tasks) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    add_task(&tasks, &task_count, 15);
    update_task(tasks, task_count, 3, "completed", 5);

    serialize_tasks(tasks, task_count, "tasks.dat");

    int deserialized_count = 0;
    Task *deserialized_tasks = deserialize_tasks("tasks.dat", &deserialized_count);

    if (deserialized_tasks) {
        for (int i = 0; i < deserialized_count; ++i) {
            printf("Task ID: %d, Priority: %d, Status: %s\n",
                   deserialized_tasks[i].id,
                   deserialized_tasks[i].priority,
                   deserialized_tasks[i].status);
        }

        free(deserialized_tasks);
    }

    free(tasks);

    return EXIT_SUCCESS;
}
