#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_SIGNAL_THRESHOLD -100

typedef struct {
    int tmsi;
    // Add other TMSI fields if necessary.
} UMTS_TMSI;

typedef struct {
    int cell_id;
    int location_area_code;
    UMTS_TMSI *tmsis;
    size_t num_tmsis;
    int signal_strength; // Assuming signal strength is available in the data
} UMTS_CELL_INFO;

typedef struct {
    UMTS_CELL_INFO **cells;
    size_t count;
    pthread_rwlock_t lock;
} CellInfoArray;

// Function to initialize a CellInfoArray
void initCellInfoArray(CellInfoArray *array) {
    array->cells = NULL;
    array->count = 0;
    pthread_rwlock_init(&array->lock, NULL);
}

// Function to free resources of the CellInfoArray
void destroyCellInfoArray(CellInfoArray *array) {
    if (array == NULL) return;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->cells[i] != NULL) {
            free(array->cells[i]->tmsis);
            free(array->cells[i]);
        }
    }
    free(array->cells);

    pthread_rwlock_destroy(&array->lock);
}

// Function to dynamically resize the CellInfoArray
void resizeCellInfoArray(CellInfoArray *array, size_t new_size) {
    UMTS_CELL_INFO **new_cells = realloc(array->cells, new_size * sizeof(UMTS_CELL_INFO *));
    if (new_cells == NULL) {
        perror("Failed to resize cell info array");
        exit(EXIT_FAILURE);
    }
    array->cells = new_cells;
}

// Function to add a cell to the CellInfoArray
void addCell(CellInfoArray *array, UMTS_CELL_INFO *cell_info) {
    pthread_rwlock_wrlock(&array->lock);

    if (array->count == 0 || array->cells == NULL) {
        resizeCellInfoArray(array, 1);
    } else if (array->count >= array->count) { // Assuming count is the capacity
        resizeCellInfoArray(array, array->count * 2);
    }

    array->cells[array->count++] = cell_info;

    pthread_rwlock_unlock(&array->lock);
}

// Function to filter cells based on signal strength threshold
void filterCellsBySignalStrength(CellInfoArray *array, int threshold) {
    pthread_rwlock_wrlock(&array->lock);

    size_t new_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->cells[i]->signal_strength >= threshold) {
            if (new_count == i) continue; // No need to move
            array->cells[new_count] = array->cells[i];
            new_count++;
        } else {
            free(array->cells[i]->tmsis);
            free(array->cells[i]);
        }
    }

    resizeCellInfoArray(array, new_count);
    array->count = new_count;

    pthread_rwlock_unlock(&array->lock);
}

// Function to load data from a JSON file or external API
void loadData(CellInfoArray *array) {
    // Simulate loading data (e.g., from a JSON file)
    // This function should parse the data and call addCell for each valid entry

    // Example of adding a cell manually for demonstration purposes
    UMTS_CELL_INFO *cell = malloc(sizeof(UMTS_CELL_INFO));
    cell->cell_id = 123;
    cell->location_area_code = 456;
    cell->num_tmsis = 1;
    cell->tmsis = malloc(cell->num_tmsis * sizeof(UMTS_TMSI));
    cell->tmsis[0].tmsi = 789;
    cell->signal_strength = -90;

    addCell(array, cell);
}

// Example usage
int main() {
    CellInfoArray array;
    initCellInfoArray(&array);

    loadData(&array); // Load data from a source

    filterCellsBySignalStrength(&array, MAX_SIGNAL_THRESHOLD);

    destroyCellInfoArray(&array);

    return 0;
}
