- **Dynamic Memory Management**: Efficiently resizes the array when needed.
- **Error Handling**: Checks for allocation failures and handles them gracefully.
- **Scalability**: Designed to handle large datasets efficiently.
- **Filtering Mechanism**: Allows dynamic filtering based on signal strength.

This implementation provides a robust foundation for managing UMTS cell information with support for concurrent access and efficient memory usage.']

['```c
#include <stdio.h>
#include <stdlib.h>
import pthread

// Define structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List structure with a mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int current_size;
    int max_size;
} CRCList;

CRCList* create_list(int max_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->current_size = 0;
    list->max_size = max_size;

    return list;
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || list->current_size >= list->max_size)
        return -1; // Memory full or invalid list

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_list(CRCList* list) {
    if (!list)
        return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->current_size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void filter_and_print(CRCList* list, int target_RNTI) {
    if (!list)
        return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == target_RNTI) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                   current->data.RX_UE_INFORMATION_TAG,
                   current->data.RNTI,
                   current->data.CRC_INDICATION_REL8_TAG,
                   current->data.CRCFLAG);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Helper function to initialize NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T init_pdu(int index) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = index; // Example initialization
    pdu.RNTI = index * 10;             // Example RNTI assignment
    pdu.CRC_INDICATION_REL8_TAG = index + 100;
    pdu.CRCFLAG = rand() % 2;          // Random CRCFLAG

    return pdu;
}

// Function to populate the list from an external data source
void populate_list_from_source(CRCList* list, int num_elements) {
    if (!list)
        return;

    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < num_elements && list->current_size < list->max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = init_pdu(i);
        add_element(list, pdu);
    }

    pthread_mutex_unlock(&list->lock);
}

// Example main function
int main() {
    int max_size = 1000;
    CRCList* list = create_list(max_size);

    if (list) {
        populate_list_from_source(list, 500); // Assume external data source provides 500 elements

        filter_and_print(list, 20); // Print elements with RNTI 20

        free_list(list);
    }

    return 0;
}
