#include <stdio.h>
#include <stdlib.h>
import time

#define MAX_HISTORY 100
#define CONFIG_FILE "config.txt"
#define BACKUP_FILE "backup.dat"

typedef struct {
    int cell_id;
    int lac;
    double signal_strength;
    time_t last_attempt;
} UMTS_CELL_INFO;

typedef struct {
    int tmsi;
    time_t timestamp;
} UMTS_TMSI;

typedef struct {
    UMTS_TMSI *tmsis;
    size_t count;
    size_t capacity;
} TMSI_LIST;

typedef struct {
    UMTS_CELL_INFO cell_info;
    TMSI_LIST tmsi_list;
    time_t history[MAX_HISTORY];
    size_t history_count;
} CELL_MANAGEMENT_ENTRY;

typedef struct {
    CELL_MANAGEMENT_ENTRY *entries;
    size_t count;
    size_t capacity;
} CELL_MANAGEMENT_SYSTEM;

// Function prototypes
void initialize_system(CELL_MANAGEMENT_SYSTEM *system);
int load_config(const char *filename, CELL_MANAGEMENT_SYSTEM *system, double signal_threshold);
void filter_cells(CELL_MANAGEMENT_SYSTEM *system, double signal_threshold);
void update_cell_status(CELL_MANAGEMENT_SYSTEM *system, UMTS_CELL_INFO new_info);
void cleanup_old_history(CELL_MANAGEMENT_SYSTEM *system);
void backup_system(const CELL_MANAGEMENT_SYSTEM *system);

// Helper functions
TMSI_LIST* create_tmsi_list(size_t capacity) {
    TMSI_LIST *list = (TMSI_LIST *)malloc(sizeof(TMSI_LIST));
    list->tmsis = (UMTS_TMSI *)malloc(capacity * sizeof(UMTS_TMSI));
    list->count = 0;
    list->capacity = capacity;
    return list;
}

void free_tmsi_list(TMSI_LIST *list) {
    if (list) {
        free(list->tmsis);
        free(list);
    }
}

// Main functions
void initialize_system(CELL_MANAGEMENT_SYSTEM *system) {
    system->entries = NULL;
    system->count = 0;
    system->capacity = 0;
}

int load_config(const char *filename, CELL_MANAGEMENT_SYSTEM *system, double signal_threshold) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    while (fscanf(file, "%d %d %lf %ld", &system->entries[system->count].cell_info.cell_id,
                  &system->entries[system->count].cell_info.lac,
                  &system->entries[system->count].cell_info.signal_strength,
                  &system->entries[system->count].cell_info.last_attempt) == 4) {
        if (system->count >= system->capacity) {
            size_t new_capacity = system->capacity ? system->capacity * 2 : 16;
            CELL_MANAGEMENT_ENTRY *new_entries = realloc(system->entries, new_capacity * sizeof(CELL_MANAGEMENT_ENTRY));
            if (!new_entries) return -1;
            system->entries = new_entries;
            system->capacity = new_capacity;
        }

        TMSI_LIST *tmsi_list = create_tmsi_list(10);
        system->entries[system->count].tmsi_list = *tmsi_list;
        system->entries[system->count].history_count = 0;

        system->count++;
    }
    fclose(file);

    filter_cells(system, signal_threshold);
    return 0;
}

void filter_cells(CELL_MANAGEMENT_SYSTEM *system, double signal_threshold) {
    for (size_t i = 0; i < system->count;) {
        if (system->entries[i].cell_info.signal_strength < signal_threshold) {
            free_tmsi_list(&system->entries[i].tmsi_list);
            memmove(&system->entries[i], &system->entries[i + 1],
                    (system->count - i - 1) * sizeof(CELL_MANAGEMENT_ENTRY));
            system->count--;
        } else {
            i++;
        }
    }
}

void update_cell_status(CELL_MANAGEMENT_SYSTEM *system, UMTS_CELL_INFO new_info) {
    for (size_t i = 0; i < system->count; ++i) {
        if (system->entries[i].cell_info.cell_id == new_info.cell_id) {
            system->entries[i].cell_info.signal_strength = new_info.signal_strength;
            system->entries[i].cell_info.last_attempt = time(NULL);
            break;
        }
    }

    // Add new entry if not found
    for (size_t i = 0; i < system->count; ++i) {
        if (system->entries[i].cell_info.cell_id == new_info.cell_id) return;
    }

    if (system->count >= system->capacity) {
        size_t new_capacity = system->capacity ? system->capacity * 2 : 16;
        CELL_MANAGEMENT_ENTRY *new_entries = realloc(system->entries, new_capacity * sizeof(CELL_MANAGEMENT_ENTRY));
        if (!new_entries) return;
        system->entries = new_entries;
        system->capacity = new_capacity;
    }

    TMSI_LIST *tmsi_list = create_tmsi_list(10);
    system->entries[system->count] = (CELL_MANAGEMENT_ENTRY){
        .cell_info = new_info,
        .tmsi_list = *tmsi_list,
        .history_count = 0
    };

    system->count++;
}

void cleanup_old_history(CELL_MANAGEMENT_SYSTEM *system) {
    for (size_t i = 0; i < system->count; ++i) {
        if (system->entries[i].history_count == MAX_HISTORY) {
