CellManager cell_manager = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize the cell manager
void init_cell_manager() {
    cell_manager.cells = (UMTS_CELL_INFO *)malloc(MAX_CELLS * sizeof(UMTS_CELL_INFO));
}

// Function to free memory for UMTS_TMSI list
void free_tmsi_list(UMTS_TMSI *tmsis, size_t count) {
    if (tmsis) {
        free(tmsis);
    }
}

// Function to add a cell info structure
int add_cell_info(const UMTS_CELL_INFO *cell_info) {
    pthread_mutex_lock(&cell_manager.lock);

    if (cell_manager.count >= MAX_CELLS) {
        pthread_mutex_unlock(&cell_manager.lock);
        return -1; // Memory full
    }

    if (cell_info->signal_strength < SIGNAL_THRESHOLD) {
        pthread_mutex_unlock(&cell_manager.lock);
        return 0; // Filtered out based on signal strength
    }

    cell_manager.cells[cell_manager.count++] = *cell_info;
    pthread_mutex_unlock(&cell_manager.lock);
    return 1;
}

// Function to free all allocated memory
void cleanup() {
    for (size_t i = 0; i < cell_manager.count; ++i) {
        free_tmsi_list(cell_manager.cells[i].tmsis, cell_manager.cells[i].tmsi_count);
    }
