static int max_key_value = 0;

typedef struct {
    long *offsets;
    int *keys;
    size_t num_records;
} ResourceStructure;

int fetch_network_metrics(int *result) {
    // Simulate asynchronous network operation
    // Returns 1 on success, 0 on failure
    pthread_mutex_lock(&global_lock);
    if (rand() % 2 == 0) {  // Randomly simulate success or failure
        *result = rand() % 100;  // Mocked result value
        return 1;
    }
    pthread_mutex_unlock(&global_lock);
    return 0;
}

void* execute_async_command(void* arg) {
    int *crcflag = (int*)arg;
    if (fetch_network_metrics(crcflag)) {
        pthread_mutex_lock(&global_lock);
        printf("Network metrics fetched successfully: %d\n", *crcflag);
        pthread_mutex_unlock(&global_lock);
    } else {
        pthread_mutex_lock(&global_lock);
        printf("Failed to fetch network metrics.\n");
        pthread_mutex_unlock(&global_lock);
    }
    return NULL;
}

int identify_max_key(ResourceStructure *resources) {
    int max = 0;
    for (size_t i = 0; i < resources->num_records; ++i) {
        if (resources->keys[i] > max) {
            max = resources->keys[i];
        }
    }
    pthread_mutex_lock(&global_lock);
    max_key_value = max;
    pthread_mutex_unlock(&global_lock);
    return max_key_value;
}

int initialize_resources(ResourceStructure **resource_structure, int min_val, int max_val) {
    ResourceStructure *res_struct;
    int key;

    res_struct = (ResourceStructure *)malloc(sizeof(ResourceStructure));
    if (!res_struct) {
        fprintf(stderr, "Failed to allocate memory for resource structure\n");
        return 0;
    }

    size_t num_records = 0;
    while (1) {
        printf("Enter number of keys (or negative to stop): ");
        scanf("%d", &key);
        if (key < 0) break;

        res_struct->offsets = realloc(res_struct->offsets, sizeof(long) * (num_records + 1));
        res_struct->keys = realloc(res_struct->keys, sizeof(int) * (num_records + 1));

        if (!res_struct->offsets || !res_struct->keys) {
            fprintf(stderr, "Memory allocation failed\n");
            free(res_struct->offsets);
            free(res_struct->keys);
            free(res_struct);
            return 0;
        }

        res_struct->offsets[num_records] = rand() % 100000;  // Mocked offset
        res_struct->keys[num_records] = (rand() % (max_val - min_val + 1)) + min_val;

        num_records++;
    }

    res_struct->num_records = num_records;
    *resource_structure = res_struct;

    if (num_records == 0) {
        fprintf(stderr, "No records initialized\n");
        free(res_struct);
        return 0;
    }

    pthread_t thread_id[MAX_THREADS];
    int crcflag;
    for (size_t i = 0; i < num_records && i < MAX_THREADS; ++i) {
        if (pthread_create(&thread_id[i], NULL, execute_async_command, &crcflag)) {
            fprintf(stderr, "Error creating thread\n");
            return 0;
        }
    }

    for (size_t i = 0; i < num_records && i < MAX_THREADS; ++i) {
        pthread_join(thread_id[i], NULL);
    }

    NFAPI_CRC_INDICATION_PDU_T *nfa_api_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_records);
    if (!nfa_api_array) {
        fprintf(stderr, "Failed to allocate memory for NFAPI array\n");
        free(res_struct->offsets);
        free(res_struct->keys);
        free(res_struct);
        return 0;
    }

    for (size_t i = 0; i < num_records; ++i) {
        nfa_api_array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        nfa_api_array[i].RNTI = rand() % 10000;
        nfa_api_array[i].CRC_INDICATION_REL8_TAG = (rand() % 256);
        nfa_api_array[i].CRCFLAG = crcflag;

        // Simulate usage of the data
    }

    printf("Max key value identified: %d\n", identify_max_key(res_struct));

    free(nfa_api_array);
    return 1;
}

int main() {
    ResourceStructure *resources = NULL;
    int min_val = 10, max_val = 50;

    if (initialize_resources(&resources, min_val, max_val)) {
        printf("Resources initialized successfully\n");
    } else {
        fprintf(stderr, "Failed to initialize resources\n");
    }

    // Clean up
    free(resources->offsets);
    free(resources->keys);
    free(resources);

    pthread_mutex_destroy(&global_lock);

    return 0;
}
