#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_ENTRIES 1024
#define CLEANUP_THRESHOLD 60 // seconds

typedef struct {
    int rnti;
    float signal_strength;
    time_t last_heard_time;
    int cell_id;
} UE_Entry;

typedef struct {
    int rnti;
    int crc_flag; // Assume CRCFLAG is an integer for simplicity
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global dynamic array of UE entries and its mutex
static UE_Entry *ue_array = NULL;
static size_t ue_count = 0;
static pthread_mutex_t ue_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_ue_system(size_t initial_capacity) {
    pthread_mutex_lock(&ue_mutex);
    ue_array = (UE_Entry *)calloc(initial_capacity, sizeof(UE_Entry));
    pthread_mutex_unlock(&ue_mutex);
}

void cleanup_ues() {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&ue_mutex);
    for (size_t i = 0; i < ue_count; ++i) {
        if ((current_time - ue_array[i].last_heard_time) > CLEANUP_THRESHOLD) {
            memmove(&ue_array[i], &ue_array[i + 1], (ue_count - i - 1) * sizeof(UE_Entry));
            --ue_count;
            --i; // recheck the same index
        }
    }
    pthread_mutex_unlock(&ue_mutex);
}

void update_ue_entry(int rnti, float signal_strength, int cell_id) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&ue_mutex);
    for (size_t i = 0; i < ue_count; ++i) {
        if (ue_array[i].rnti == rnti) {
            ue_array[i].signal_strength = signal_strength;
            ue_array[i].last_heard_time = current_time;
            ue_array[i].cell_id = cell_id;
            break;
        }
    }

    // Add new UE entry if not found
    for (size_t i = 0; i < ue_count; ++i) {
        if (ue_array[i].rnti == 0) { // Assume RNTI of 0 means unused slot
            ue_array[i] = (UE_Entry){.rnti = rnti, .signal_strength = signal_strength,
                                     .last_heard_time = current_time, .cell_id = cell_id};
            break;
        }
    }

    if (ue_count < MAX_UE_ENTRIES && !(ue_array[ue_count].rnti)) {
        ue_array[ue_count] = (UE_Entry){.rnti = rnti, .signal_strength = signal_strength,
                                       .last_heard_time = current_time, .cell_id = cell_id};
        ++ue_count;
    }
    pthread_mutex_unlock(&ue_mutex);
}

void generate_nfaapi_crc_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t list_size) {
    srand(time(NULL));

    for (size_t i = 0; i < list_size; ++i) {
        list[i].rnti = rand() % MAX_UE_ENTRIES;
        list[i].ue_info_tag.rnti = list[i].rnti;
        list[i].crc_indication_rel8_tag = rand();
        list[i].ue_info_tag.crc_flag = rand() % 2; // Random CRC flag
    }
}

void populate_data_structure(int *keys, long *offsets, int range_min, int range_max) {
    size_t i;
    while ((i = scanf("%d", &keys[i])) > 0 && keys[i] >= 0) {
        if (i == 0 || keys[i-1] < 0) break; // Ensure valid number of entries
        offsets[i - 1] = rand() % (range_max - range_min + 1) + range_min;
    }
}

int find_max_key(int *keys, size_t count, int *max_key) {
    if (!count || !keys) return -1;

    *max_key = keys[0];
    for (size_t i = 1; i < count; ++i) {
        if (keys[i] > *max_key) {
            *max_key = keys[i];
        }
    }

    return 0;
}

void free_resources() {
    pthread_mutex_lock(&ue_mutex);
    free(ue_array);
    ue_array = NULL;
    ue_count = 0;
    pthread_mutex_unlock(&ue_mutex);
}

int main() {
    initialize_ue_system(MAX_UE_ENTRIES);

    // Example of updating UE entry
    update_ue_entry(12345, -80.5f, 1);

    // Example cleanup call
    cleanup_ues();

    NFAPI_CRC_INDICATION_PDU_T pdu_list[10];
    generate_nfaapi_crc_list(pdu_list, sizeof(pdu_list) / sizeof(pdu_list[0]));

    int keys[MAX_UE_ENTRIES], max_key;
    long offsets[MAX_UE_ENTRIES];

    // Populate and find maximum key
    populate_data_structure(keys, offsets, 100, 200);
    if (find_max_key(keys, MAX_UE_ENTRIES, &max_key) == 0) {
        printf("Max Key: %d\n", max_key);
    }

    free_resources();
    return 0;
}
