// Function to generate and populate the NFAPI_CRC_INDICATION_PDU_T linked list
Node* generateNfaPduListWithConstraints(size_t maxMemoryThreshold) {
    size_t nodeSize = sizeof(Node);
    size_t pduSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    Node *head = NULL, *current = NULL;

    while ((nodeSize + pduSize) <= maxMemoryThreshold) {
        // Allocate a new node.
        Node* newNode = (Node*)malloc(nodeSize);
        if (!newNode) break;  // Exit if memory allocation fails.

        // Populate the node's data.
        newNode->data.rxInfoTag.someField = rand();  // Random value for demo purposes
        newNode->data.rnti = rand() % 65536;
        newNode->data.crcIndication.CRCFLAG = rand() % 2;

        // Link the new node into the list.
        if (head == NULL) {
            head = current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }

        maxMemoryThreshold -= (nodeSize + pduSize);
    }

    return head;
}
