#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define BUFFER_MAX_SIZE 2048

typedef struct {
    uint32_t packet_id;
    time_t timestamp;
    size_t data_size;
    char *data;
} Packet;

typedef struct {
    Packet *buffer;
    size_t head;
    size_t tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;  // Change to spinlock if preferred
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer* create_buffer(size_t capacity) {
    if (capacity == 0 || (capacity & (capacity - 1)) != 0) return NULL;  // Must be power of two

    CircularBuffer *cb = malloc(sizeof(CircularBuffer));
    cb->buffer = calloc(capacity, sizeof(Packet));
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->capacity = capacity;

    pthread_mutex_init(&cb->lock, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);

    return cb;
}

void destroy_buffer(CircularBuffer *cb) {
    if (cb) {
        free(cb->buffer);
        pthread_mutex_destroy(&cb->lock);
        pthread_cond_destroy(&cb->not_full);
        pthread_cond_destroy(&cb->not_empty);
        free(cb);
    }
}

static int is_old_packet(Packet *packet, time_t cutoff_time) {
    return packet->timestamp < cutoff_time;
}

static void split_and_enqueue(CircularBuffer *cb, Packet *packet, size_t max_size) {
    while (packet->data_size > 0) {
        size_t chunk_size = packet->data_size < max_size ? packet->data_size : max_size;

        // Create a new packet with the chunk
        Packet new_packet = {packet->packet_id, packet->timestamp, chunk_size, malloc(chunk_size)};
        memcpy(new_packet.data, packet->data, chunk_size);

        enqueue_packet(cb, &new_packet);
        free(new_packet.data);  // Free the data after enqueuing

        packet->data += chunk_size;
        packet->data_size -= chunk_size;
    }
}

void enqueue_packet(CircularBuffer *cb, Packet *packet) {
    if (cb == NULL || packet == NULL) return;

    pthread_mutex_lock(&cb->lock);

    while (cb->count >= cb->capacity) {
        pthread_cond_wait(&cb->not_full, &cb->lock);
    }

    if (is_old_packet(packet, time(NULL) - 60)) {  // Discard packets older than 60 seconds
        free(packet->data);
        free(packet);
        pthread_mutex_unlock(&cb->lock);
        return;
    } 

    if (packet->data_size > MAX_PACKET_SIZE) {
        split_and_enqueue(cb, packet, MAX_PACKET_SIZE);
        pthread_mutex_unlock(&cb->lock);
        return;
    }

    cb->buffer[cb->head] = *packet;
    cb->head = (cb->head + 1) % cb->capacity;
    ++cb->count;

    free(packet->data); // Free the data after storing it
    free(packet);

    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->lock);
}

Packet* dequeue_packet(CircularBuffer *cb) {
    if (cb == NULL) return NULL;

    pthread_mutex_lock(&cb->lock);

    while (cb->count == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->lock);
    }

    Packet *packet = malloc(sizeof(Packet));
    memcpy(packet, &cb->buffer[cb->tail], sizeof(Packet));

    cb->tail = (cb->tail + 1) % cb->capacity;
    --cb->count;

    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->lock);

    return packet;
}

void optimizeDataTransferStream() {
    CircularBuffer *buffer = create_buffer(BUFFER_MAX_SIZE);

    if (buffer == NULL) return;

    // Thread handling logic for reading/writing data to the buffer goes here

    destroy_buffer(buffer);
}
