#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Item {
    char *name;
    int id;
    struct Item *parent;
    struct Item *children; // Pointer to the first child in a linked list of children
} Item;

// Function prototypes
Item* create_item(const char *name, int id);
void add_child(Item *parent, const char *child_name, int child_id);
void traverse_and_print(Item *root);
void free_hierarchy(Item *root);

// Create an item and initialize its fields
Item* create_item(const char *name, int id) {
    Item *new_item = (Item *)malloc(sizeof(Item));
    if (!new_item) {
        fprintf(stderr, "Memory allocation failed for new item\n");
        return NULL;
    }

    new_item->name = strdup(name);
    if (!new_item->name) {
        fprintf(stderr, "Memory allocation failed for item name\n");
        free(new_item);
        return NULL;
    }

    new_item->id = id;
    new_item->parent = NULL;
    new_item->children = NULL;

    return new_item;
}

// Add a child to the parent item
void add_child(Item *parent, const char *child_name, int child_id) {
    if (!parent || !child_name) return;

    Item *new_child = create_item(child_name, child_id);
    if (!new_child) return; // Memory allocation failed

    new_child->parent = parent;

    // Insert the new child at the beginning of the children list
    new_child->children = parent->children;
    parent->children = new_child;
}

// Traverse and print item identifiers in a hierarchical order
void traverse_and_print(Item *root) {
    if (!root) return;

    printf("Item ID: %d\n", root->id);
    for (Item *child = root->children; child != NULL; child = child->children) {
        traverse_and_print(child);
    }
}

// Free the entire hierarchy starting from the root
void free_hierarchy(Item *root) {
    if (!root) return;

    // Recursively free children first
    for (Item *child = root->children; child != NULL;) {
        Item *next_child = child->children;
        free(child->name);
        free(child);
        child = next_child;
    }

    free(root); // Finally, free the current item
}

// Example of using these functions
int main() {
    // Create root item
