bool resizeList(CRCIndicationList *list, size_t new_capacity) {
    if (new_capacity > MAX_LIST_SIZE) return false; // Exceeds maximum allowed size

    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
