    }

    list->data = new_data;
    list->capacity = new_capacity;
    return true;
}

bool insertPDU(CRCIndicationList *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
