['Below is an implementation of the `generateNfaPduListWithConstraints` function in C. This implementation assumes some predefined types and constants based on your description, as well as necessary headers and utility functions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for maximum memory usage and max channels.
#define MAX_MEMORY_THRESHOLD 1024 * 1024 // Example: 1MB threshold
#define MAX_CHANNELS 100

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef uint32_t RX_UE_INFORMATION_TAG;  // Assuming 32-bit unsigned integer.
typedef uint16_t RNTI;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;  // Singly linked list for simplicity.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t current_memory_usage;
} NfaPduList;

void initializeNfaPduList(NfaPduList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->current_memory_usage = 0;
}

int generateRandomCRCFLAG() {
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1.
}

void updateStatistics(double *avg_ber, double *min_ber, double *max_ber,
                      double current_ber) {
    static int count = 0;
    static double total_ber = 0.0;

    count++;
    total_ber += current_ber;
    *avg_ber = total_ber / count;
    if (current_ber < *min_ber || count == 1)
        *min_ber = current_ber;
    if (current_ber > *max_ber)
        *max_ber = current_ber;
}

void generateNfaPduListWithConstraints(NfaPduList *list, int max_channels,
                                       double (*updateBER)(int)) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < max_channels && list->current_memory_usage < MAX_MEMORY_THRESHOLD; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_pdu || list->current_memory_usage + sizeof(*new_pdu) > MAX_MEMORY_THRESHOLD) {
            free(new_pdu);
            break;
        }

        new_pdu->rx_ue_information_tag = rand(); // Random RX_UE_INFORMATION_TAG.
        new_pdu->rnti = rand() % 65535;          // Random RNTI (16-bit).
        new_pdu->crc_indication_rel8_tag.CRCFLAG = generateRandomCRCFLAG();

        list->current_memory_usage += sizeof(*new_pdu);
        new_pdu->next = list->head;
        list->head = new_pdu;

        double ber = updateBER(i); // Callback to simulate BER update based on channel.
        static double avg_ber = 0.0, min_ber = DBL_MAX, max_ber = 0.0;

        updateStatistics(&avg_ber, &min_ber, &max_ber, ber);
    }

    pthread_mutex_unlock(&list->lock);

    printf("BER - Avg: %f, Min: %f, Max: %f\n", avg_ber, min_ber, max_ber);
}

void cleanupNfaPduList(NfaPduList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example BER update callback function.
double mockUpdateBER(int channel_index) {
    return (rand() % 1000) / 10000.0; // Simulate a BER value between 0.000 and 0.099
}

int main() {
    srand(time(NULL)); // Seed random number generator.

    NfaPduList pdu_list;
    initializeNfaPduList(&pdu_list);

    generateNfaPduListWithConstraints(&pdu_list, MAX_CHANNELS, mockUpdateBER);

    cleanupNfaPduList(&pdu_list);
    return 0;
}
```

### Key Points:
- **Thread Safety:** Uses `pthread_mutex_t` for thread-safe access to the linked list.
- **Memory Management:** Ensures memory usage does not exceed `MAX_MEMORY_THRESHOLD`.
- **Statistics Calculation:** Updates and prints average, minimum, and maximum BER values in real-time.
- **Dynamic Channel Handling:** Processes up to `max_channels`, with a random generation of RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG.
- **Cleanup Functionality:** Properly frees allocated memory.

This implementation is designed for integration into a larger network simulation framework. Adjustments may be needed based on specific requirements or system architecture constraints.']

