typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint32_t RNTI;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_LIST_T;

void initialize_list(NFAPI_CRC_LIST_T* list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int expand_capacity(NFAPI_CRC_LIST_T* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (temp == NULL) return -1;
    list->data = temp;
    list->capacity = new_capacity;
    return 0;
}

int populate_nfa_list(NFAPI_CRC_LIST_T* list, size_t n) {
    pthread_mutex_lock(&list->lock);

    if (n > list->capacity) {
        size_t new_capacity = n > list->capacity * 2 ? n : list->capacity * 2;
        if (expand_capacity(list, new_capacity) != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    uint16_t used_flags[65536] = {0};

    for (size_t i = 0; i < n; ++i) {
        list->data[i].rx_ue_information_tag.RNTI = rand() % 65535;
        list->data[i].rnti = rand() % 65535;

        uint16_t crcflag;
        do {
            crcflag = rand() % 65536;
        } while (used_flags[crcflag]);

        used_flags[crcflag] = 1;
        list->data[i].crc_indication_rel8_tag.CRCFLAG = crcflag;
    }

    if (list->size < n) list->size = n;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(NFAPI_CRC_LIST_T* list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void log_performance(size_t n, double time_taken) {
    printf("Processed %zu elements in %.2f seconds\n", n, time_taken);
}

