#include <time.h>

#define TEST_SIZE 1000

void test_populate_nfa_list() {
    NFAPI_CRC_LIST_T list;
    initialize_list(&list);

    clock_t start = clock();
    assert(populate_nfa_list(&list, TEST_SIZE) == 0);
    double time_taken = (double)(clock() - start) / CLOCKS_PER_SEC;

    log_performance(TEST_SIZE, time_taken);

    uint16_t crc_flags[65536] = {0};
    for (size_t i = 0; i < list.size; ++i) {
        assert(list.data[i].rx_ue_information_tag.RNTI > 0);
        assert(list.data[i].rnti > 0);

        uint16_t crcflag = list.data[i].crc_indication_rel8_tag.CRCFLAG;
        assert(crc_flags[crcflag] == 0); // Ensure uniqueness
        crc_flags[crcflag] = 1;
    }

    free_list(&list);
}

int main() {
    test_populate_nfa_list();
    printf("All tests passed.\n");
    return 0;
}
