#define MAX_BUFFS 1000

typedef struct {
    int RX_POWER_LEVEL;
    int RX_QUALITY_INDICATOR;
} LTE_PHY_RX_BUFFER_T;

typedef struct {
    LTE_PHY_RX_BUFFER_T buffers[MAX_BUFFS];
    size_t buffer_count;
    pthread_mutex_t lock;
} ChannelState;

typedef void (*SignalQualityCallback)(int new_quality);

ChannelState* create_channel_state() {
    ChannelState *channel = (ChannelState*)malloc(sizeof(ChannelState));
    if (!channel) return NULL;

    channel->buffer_count = 0;
    pthread_mutex_init(&channel->lock, NULL);

    return channel;
}

void free_channel_state(ChannelState *state) {
    pthread_mutex_destroy(&state->lock);
    free(state);
}

int add_buffer(ChannelState *state, LTE_PHY_RX_BUFFER_T buffer) {
    if (state->buffer_count >= MAX_BUFFS) return -1;

    pthread_mutex_lock(&state->lock);
    state->buffers[state->buffer_count++] = buffer;
    pthread_mutex_unlock(&state->lock);

    return 0;
}

void process_buffers(ChannelState *channels, int num_channels, SignalQualityCallback callback) {
    for (int i = 0; i < num_channels; ++i) {
        ChannelState *channel = &channels[i];

        pthread_mutex_lock(&channel->lock);
        for (size_t j = 0; j < channel->buffer_count; ++j) {
            LTE_PHY_RX_BUFFER_T *buf = &channel->buffers[j];

            // Simulate real-world radio conditions
            int noise_factor = rand() % 10;
            buf->RX_QUALITY_INDICATOR += noise_factor - (noise_factor / 2);

            callback(buf->RX_QUALITY_INDICATOR);
        }
        pthread_mutex_unlock(&channel->lock);
    }
}

void report_statistics(ChannelState *channels, int num_channels) {
    double total_power = 0.0;
    int min_quality = INT_MAX, max_quality = INT_MIN;

    for (int i = 0; i < num_channels; ++i) {
        ChannelState *channel = &channels[i];

        pthread_mutex_lock(&channel->lock);
        for (size_t j = 0; j < channel->buffer_count; ++j) {
            LTE_PHY_RX_BUFFER_T *buf = &channel->buffers[j];

            total_power += buf->RX_POWER_LEVEL;
            if (buf->RX_QUALITY_INDICATOR < min_quality)
                min_quality = buf->RX_QUALITY_INDICATOR;
            if (buf->RX_QUALITY_INDICATOR > max_quality)
                max_quality = buf->RX_QUALITY_INDICATOR;
        }
        pthread_mutex_unlock(&channel->lock);
    }

    double avg_power = total_power / (num_channels * MAX_BUFFS);
    printf("Average Signal Power Level: %.2f\n", avg_power);
    printf("Minimum Signal Quality Indicator: %d\n", min_quality);
    printf("Maximum Signal Quality Indicator: %d\n", max_quality);
}

void example_callback(int new_quality) {
    // Example callback function
    printf("Updated quality indicator to: %d\n", new_quality);
}
