char* read_input_strings(size_t count) {
    char **strings = malloc(count * sizeof(char *));
    if (!strings) {
        perror("Failed to allocate memory for strings");
        exit(EXIT_FAILURE);
    }

    printf("Enter %zu user names:\n", count);

    for (size_t i = 0; i < count; ++i) {
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), stdin)) {
            size_t len = strlen(buffer);
            if (buffer[len - 1] == '\n') {
                buffer[--len] = '\0';
            }
            strings[i] = strdup(buffer);
            if (!strings[i]) {
                perror("Failed to duplicate string");
                exit(EXIT_FAILURE);
            }
        } else {
            fprintf(stderr, "Error reading input\n");
            exit(EXIT_FAILURE);
        }
    }

    return (char *)strings;
}

const char* find_longest_string(char **strings, size_t count) {
    const char *longest = NULL;
    size_t max_length = 0;

    for (size_t i = 0; i < count; ++i) {
        if (!strings[i]) continue;
        size_t length = strlen(strings[i]);
        if (length > max_length) {
            longest = strings[i];
            max_length = length;
        }
    }

    return longest;
}

void manage_log_entries(size_t size, float min_val, float max_val) {
    log_entry *entries = malloc(size * sizeof(log_entry));
    if (!entries) {
        perror("Failed to allocate memory for log entries");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < size; ++i) {
        entries[i].f_value = min_val + ((float)rand() / RAND_MAX) * (max_val - min_val);
        entries[i].d_timestamp = time(NULL);
        char name_template[] = "User_%zu";
        char *name = malloc(snprintf(NULL, 0, name_template, i) + 1);
        if (!name) {
            perror("Failed to allocate memory for user name");
            exit(EXIT_FAILURE);
        }
        snprintf(name, sizeof(name), name_template, i);
        entries[i].user_name = strdup(name);
        free(name);

        if (!entries[i].user_name) {
            perror("Failed to duplicate string");
            exit(EXIT_FAILURE);
        }
    }

    char **input_strings = read_input_strings(size);

    const char *longest_string = find_longest_string(input_strings, size);
    printf("Longest user name: %s\n", longest_string);

    // Clean up
    for (size_t i = 0; i < size; ++i) {
        free(entries[i].user_name);
        free(input_strings[i]);
    }
    free(entries);
    free(input_strings);
