#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RANGE 1000
#define MAX_INPUT_SIZE 100
#define MAX_STRUCTS 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void handleMemoryAllocationError(void *ptr) {
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

int readUniqueIntegers(int **array, size_t limit) {
    int num;
    int unique[MAX_INPUT_SIZE] = {0};
    size_t count = 0;

    printf("Enter integers (max %zu): ", limit);
    while (count < limit && scanf("%d", &num) == 1) {
        if (num < 0 || num > MAX_RANGE) {
            fprintf(stderr, "Invalid input. Number must be between 0 and %d.\n", MAX_RANGE);
            break;
        }
        for (size_t i = 0; i < count; ++i) {
            if (unique[i] == num) {
                fprintf(stderr, "Duplicate entry detected. Try again.\n");
                scanf("%*s"); // clear invalid input
                return -1;
            }
        }
        unique[count++] = num;
    }

    *array = malloc(count * sizeof(int));
    handleMemoryAllocationError(*array);
    memcpy(*array, unique, count * sizeof(int));

    return count;
}

void printLargestInteger(const int *array, size_t length) {
    if (length == 0) {
        printf("No integers to display.\n");
        return;
    }
    int largest = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void serializeStructuresToFile(NFAPI_CRC_INDICATION_PDU_T *structs, size_t count) {
    FILE *file = fopen("crc_indications.bin", "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    fwrite(structs, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    if (ferror(file)) {
        fprintf(stderr, "Error occurred while writing to file.\n");
    } else {
        printf("Data serialized successfully.\n");
    }

    fclose(file);
}

void processStringAndSerializeNetworkData(char *inputStr, size_t sizeLimit, size_t maxMemoryThreshold) {
    if (strlen(inputStr) > sizeLimit || sizeof(inputStr) + 1 > maxMemoryThreshold) {
        return;
    }
    strcat(inputStr, "-");
    printf("Processed String: %s\n", inputStr);

    int *integers = NULL;
    size_t count = readUniqueIntegers(&integers, MAX_INPUT_SIZE);
    if (count >= 0) {
        printLargestInteger(integers, count);
        free(integers);
    }

    NFAPI_CRC_INDICATION_PDU_T structs[MAX_STRUCTS];
    srand(time(NULL));
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        structs[i].RX_UE_INFORMATION_TAG = rand() % 256;
        structs[i].RNTI = rand() % 1024;
        structs[i].CRC_INDICATION_REL8_TAG = rand() % 64;
        structs[i].CRCFLAG = (rand() % 100 < 50) ? 1 : 0; // 50% probability
    }

    serializeStructuresToFile(structs, MAX_STRUCTS);

