}

int main() {
    char inputStr[256] = "example";
    size_t sizeLimit = 255;
    size_t maxMemoryThreshold = sizeof(inputStr) + 1;

    processStringAndSerializeNetworkData(inputStr, sizeLimit, maxMemoryThreshold);
    return 0;
}
