            free(offsets); offsets = NULL;
            free(keys); keys = NULL;
            free(doubles); doubles = NULL;
            free(floats); floats = NULL;
            free(tags); tags = NULL;
            free(nodes); nodes = NULL;
            free(events); events = NULL;
            return NULL;
        }

        int node_id = rand() % (config->id_range_max - config->id_range_min + 1) + config->id_range_min;
        nodes[i]->identifier = node_id;

        event_t temp_event = { ((double)rand()) / RAND_MAX, time(NULL) };
        events[i] = temp_event;

        valid_float_check += (int)floats[i];
        sum_tags_and_keys += (int)tags[i] + keys[i];
    }

    if (valid_float_check != sum_tags_and_keys) {
        *error_buffer = strdup("Float values do not match the sum of char tags and int keys");
        sem_destroy(&semaphore);
        free(offsets); offsets = NULL;
        free(keys); keys = NULL;
        free(doubles); doubles = NULL;
        free(floats); floats = NULL;
        free(tags); tags = NULL;
        for (size_t i = 0; i < num_records; ++i) {
            free(nodes[i]);
        }
        free(nodes); nodes = NULL;
        free(events); events = NULL;
        return NULL;
    }

    // Ensure unique offsets and node identifiers
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = i + 1; j < num_records; ++j) {
            if (offsets[i] == offsets[j]) {
                *error_buffer = strdup("Offsets are not unique");
                sem_destroy(&semaphore);
                free(offsets); offsets = NULL;
                free(keys); keys = NULL;
                free(doubles); doubles = NULL;
                free(floats); floats = NULL;
                free(tags); tags = NULL;
                for (size_t k = 0; k < num_records; ++k) {
                    free(nodes[k]);
                }
                free(nodes); nodes = NULL;
                free(events); events = NULL;
                return NULL;
            }

            if (nodes[i]->identifier == nodes[j]->identifier) {
                *error_buffer = strdup("Node identifiers are not unique");
                sem_destroy(&semaphore);
                free(offsets); offsets = NULL;
                free(keys); keys = NULL;
                free(doubles); doubles = NULL;
                free(floats); floats = NULL;
                free(tags); tags = NULL;
                for (size_t k = 0; k < num_records; ++k) {
                    free(nodes[k]);
                }
                free(nodes); nodes = NULL;
                free(events); events = NULL;
                return NULL;
            }
        }
    }

    // Release the semaphore
    sem_destroy(&semaphore);

    // Return a pointer to a structure containing all allocated components
    struct data_models {
        long *offsets;
        int *keys;
        double *doubles;
        float *floats;
        char *tags;
        node_t **nodes;
        event_t *events;
    } *models = malloc(sizeof(struct data_models));

    if (!models) {
        *error_buffer = strdup("Memory allocation for models struct failed");
        free(offsets); offsets = NULL;
        free(keys); keys = NULL;
        free(doubles); doubles = NULL;
        free(floats); floats = NULL;
        free(tags); tags = NULL;
        for (size_t i = 0; i < num_records; ++i) {
            free(nodes[i]);
        }
        free(nodes); nodes = NULL;
        free(events); events = NULL;
        return NULL;
    }

    models->offsets = offsets;
    models->keys = keys;
    models->doubles = doubles;
    models->floats = floats;
    models->tags = tags;
    models->nodes = nodes;
    models->events = events;

    return models;
}
