// Function to allocate and initialize the dataset
RecordSet *create_record_set(size_t initial_size, int min_val, int max_val) {
    RecordSet *record_set = malloc(sizeof(RecordSet));
    if (!record_set) return NULL;

    record_set->data = malloc(initial_size * sizeof(int));
    if (!record_set->data) {
        free(record_set);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
