            fprintf(stderr, "Error generating random number\n");
            free(record_set->data);
            free(record_set);
            return NULL;
        }
        record_set->data[i] = ((rand_val % (max_val - min_val + 1)) + min_val);
    }

    record_set->size = initial_size;
    return record_set;
}

// Function to serialize the dataset
int serialize_record_set(const RecordSet *record_set, const char *file_path) {
    FILE *file = fopen(file_path, "wb");
    if (!file) return -1;

    size_t written = fwrite(&record_set->size, sizeof(size_t), 1, file);
    if (written != 1) goto err;

    written = fwrite(record_set->data, sizeof(int), record_set->size, file);
    if (written != record_set->size) goto err;

    fclose(file);
    return 0;

err:
    fclose(file);
    return -1;
}

// Function to deserialize the dataset
RecordSet *deserialize_record_set(const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return NULL;

    RecordSet *record_set = malloc(sizeof(RecordSet));
    if (!record_set) goto err;

    size_t read_size;
    fread(&read_size, sizeof(size_t), 1, file);

    record_set->data = malloc(read_size * sizeof(int));
    if (!record_set->data) {
        free(record_set);
        goto err;
    }

    size_t read_data = fread(record_set->data, sizeof(int), read_size, file);
    if (read_data != read_size) {
        free(record_set->data);
        free(record_set);
        goto err;
    }

    record_set->size = read_size;
    fclose(file);
    return record_set;

err:
    fclose(file);
    return NULL;
}

// Function to handle encryption and decryption
