#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int cell_id;
    int rsrp;  // in dBm
    int rsrq;  // in dB
    float sinr;  // in dB
} Measurement;

typedef struct Node {
    Measurement data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MeasurementList;

MeasurementList* create_measurement_list() {
    MeasurementList* list = (MeasurementList*)malloc(sizeof(MeasurementList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void calculate_sinr(Measurement* m) {
    // Simulated dynamic interference factor
    float interference_factor = 1.0;  // Placeholder for real model

    // Example SINR calculation
    m->sinr = (float)(m->rsrp - (m->rsrq + interference_factor));
}

void add_measurement(MeasurementList* list, int cell_id, int rsrp, int rsrq) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data.cell_id = cell_id;
    new_node->data.rsrp = rsrp;
    new_node->data.rsrq = rsrq;

    calculate_sinr(&new_node->data);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

Measurement* get_measurement(MeasurementList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.cell_id == cell_id) {
            Measurement* m = &current->data;
            pthread_mutex_unlock(&list->lock);
            return m;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void remove_measurement(MeasurementList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current) {
        if (current->data.cell_id == cell_id) {
            if (prev)
                prev->next = current->next;
            else
                list->head = current->next;

            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_measurement_list(MeasurementList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    MeasurementList* list = create_measurement_list();

    add_measurement(list, 1, -100, -10);
    add_measurement(list, 2, -110, -12);

    Measurement* m = get_measurement(list, 1);
    if (m) printf("Cell ID: %d, SINR: %.2f dB\n", m->cell_id, m->sinr);

    remove_measurement(list, 1);

    destroy_measurement_list(list);

    return 0;
}
