typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordList;

RecordList* create_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(RecordList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_record(RecordList* list, Record record) {
    if (!record.key || !isfinite(record.timestamp)) return 0;

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    new_node->data = record;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

void read_csv(const char* filename, RecordList* list) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        long offset;
        int key;
        double timestamp;
        char status;

        if (sscanf(buffer, "%ld,%d,%lf,%c", &offset, &key, &timestamp, &status) == 4) {
            Record record = {offset, key, timestamp, status};
            add_record(list, record);
        }
    }

    fclose(file);
}

void serialize(RecordList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(Record), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void deserialize(const char* filename, RecordList* list) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && !feof(file)) {
        fread(&(current->data), sizeof(Record), 1, file);
        if (!feof(file) && fread(dummy_buffer, 1, 0, file) == 0)
            break;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void update_records(RecordList* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for updating");
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        long offset;
        int key;
        double timestamp;
        char status;

        if (sscanf(buffer, "%ld,%d,%lf,%c", &offset, &key, &timestamp, &status) == 4) {
            Record record = {offset, key, timestamp, status};

            pthread_mutex_lock(&list->lock);

            Node* current = list->head;
            while (current) {
                if (current->data.key == key && current->data.offset == offset) break;
                if (!current->next) break;
                current = current->next;
            }

            if (current && current->data.key == key && current->data.offset == offset)
                pthread_mutex_unlock(&list->lock);
            else {
                Node* new_node = (Node*)malloc(sizeof(Node));
                if (!new_node) {
                    pthread_mutex_unlock(&list->lock);
                    continue;
                }
                new_node->data = record;
                new_node->next = list->head;
                list->head = new_node;

                pthread_mutex_unlock(&list->lock);
            }
        }
    }

    fclose(file);
}

void* read_thread(void* arg) {
    RecordList* list = (RecordList*)arg;
    // Perform read operations on the list
    return NULL;
}

int main() {
    RecordList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize record list\n");
        return EXIT_FAILURE;
    }

    read_csv("data.csv", list);
    serialize(list, "records.bin");
    deserialize("records.bin", list);

    // Simulate updates
    update_records(list, "update_data.csv");

    destroy_list(list);
