void expand_list_if_needed(CRC_Indication_List* list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return; // Handle reallocation failure gracefully

        list->data = new_data;
        list->capacity = new_capacity;
    }
}

int add_pdu(CRC_Indication_List* list, uint16_t rnti, RX_UE_INFORMATION_TAG rx_ue_info_tag) {
