    expand_list_if_needed(list);

    if (list->count == 0 || ((list->data[list->count - 1].crc_indication_rel8.CRCFLAG ^ generate_random_crcflag()) != 0)) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[list->count++];
        pdu->RNTI = rnti;
