        return -1; // Failed to add due to CRC flag condition
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_pdu(CRC_Indication_List* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->count == 0) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // No elements to remove
    }

    memmove(list->data, &list->data[1], --list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(CRC_Indication_List* list, size_t index) {
    if (index >= list->count)
        return NULL;

    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[index];

    pthread_mutex_unlock(&list->mutex);
    return pdu;
}

void destroy_list(CRC_Indication_List* list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

