pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_not_empty = PTHREAD_COND_INITIALIZER;
size_t buffer_size = 0;
const size_t max_buffer_size = 1024;

void* process_pdu(void *arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);

        // Wait until there's data to process
        while (buffer_size == 0) {
            pthread_cond_wait(&buffer_not_empty, &buffer_lock);
        }

        NFAPI_CRC_INDICATION_PDU_T pdu = pdu_buffer[--buffer_size];

        pthread_mutex_unlock(&buffer_lock);

        // Simulate processing the PDU
        printf("Processing RNTI: %u, CRCFLAG: %d\n", pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);

        // Here integrate with existing signal processing library...
    }
}

void enqueue_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&buffer_lock);

    if (buffer_size >= max_buffer_size) {
        fprintf(stderr, "Buffer overflow! Dropping PDU.\n");
        pthread_mutex_unlock(&buffer_lock);
        return;
    }

    pdu_buffer[buffer_size++] = *pdu;
    pthread_cond_signal(&buffer_not_empty);

    pthread_mutex_unlock(&buffer_lock);
}

void initialize_pipeline(size_t thread_count) {
    pthread_t threads[thread_count];
    pdu_buffer = (NFAPI_CRC_INDICATION_PDU_T*) malloc(max_buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_buffer) {
        fprintf(stderr, "Failed to allocate memory for PDU buffer.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, process_pdu, NULL) != 0) {
            fprintf(stderr, "Error creating thread %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void shutdown_pipeline() {
    free(pdu_buffer);
}

int main() {
    size_t num_threads = 4;
    initialize_pipeline(num_threads);

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand() % 65536;

        // Randomly set CRCFLAG
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        enqueue_pdu(&pdu);
    }

    // Run for a while before shutting down to simulate processing
    sleep(10);

    shutdown_pipeline();

    return 0;
}
