#include <pthread.h>
#include <time.h>

#define MAX_ACTIVE_STRUCTURES 1024

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t event_type;
} CELLULAR_EVENT_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CELLULAR_EVENT_REL8_TAG cellular_event_tag;
} NFAPI_CELLULAR_EVENT_PDU_T;

typedef union {
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
    NFAPI_CELLULAR_EVENT_PDU_T cellular_pdu;
} PDU;

typedef struct Node {
    PDU pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} PDULinkedList;

PDULinkedList list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void set_random_crc_flag(uint32_t *crc_flag) {
    uint32_t temp = rand();
    while ((temp & (*crc_flag)) == *crc_flag || (temp | *crc_flag) != *crc_flag) {
        temp = rand();
    }
    *crc_flag = temp;
}

int validate_rnti(int rnti) {
    return rnti > 0 && rnti < 65536; // Example validation
}

void add_crc_pdu(PDULinkedList* list, int rx_ue_tag, int rnti, uint32_t crc_flag) {
    if (!validate_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->pdu.crc_pdu.RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->pdu.crc_pdu.RNTI = rnti;
    new_node->pdu.crc_pdu.crc_tag.CRCFLAG = crc_flag;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void add_cellular_pdu(PDULinkedList* list, int rx_ue_tag, int rnti, uint16_t event_type) {
    if (!validate_rnti(rnti)) {
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Validate event type
    if (event_type < 1 || event_type > 10) { // Example range for valid types
        fprintf(stderr, "Invalid event type: %d\n", event_type);
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->pdu.cellular_pdu.RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->pdu.cellular_pdu.RNTI = rnti;
    new_node->pdu.cellular_pdu.cellular_event_tag.event_type = event_type;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void free_list(PDULinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void populate_pdus(PDULinkedList* list, size_t num_structures) {
    if (num_structures > MAX_ACTIVE_STRUCTURES) {
        fprintf(stderr, "Exceeded maximum active structures\n");
        return;
    }

    srand(time(NULL));
    uint32_t last_crc_flag = 0;

    for (size_t i = 0; i < num_structures; ++i) {
        if (rand() % 2 == 0) { // Randomly decide to add CRC or Cellular PDU
            uint32_t crc_flag;
            set_random_crc_flag(&crc_flag);
            while ((last_crc_flag & crc_flag) == last_crc_flag || (last_crc_flag | crc_flag) == last_crc_flag) {
                set_random_crc_flag(&crc_flag);
            }
            last_crc_flag = crc_flag;

            add_crc_pdu(list, rand(), rand() % 65536, crc_flag);
        } else {
            uint16_t event_type = rand() % 10 + 1;
            add_cellular_pdu(list, rand(), rand() % 65536, event_type);
        }
    }
}

int main() {
    PDULinkedList list;
    memset(&list, 0, sizeof(PDULinkedList));

    populate_pdus(&list, 100); // Example: Populate with 100 structures

    free_list(&list);

    return 0;
}
```

This code defines a linked list structure to manage dynamically allocated PDUs (`NFAPI_CRC_INDICATION_PDU_T` and `NFAPI_CELLULAR_EVENT_PDU_T`). It ensures thread safety using mutex locks, validates RNTI values, and manages CRC flags to differ by at least one bit. The function supports dynamic changes in the number of active structures and includes error handling for invalid inputs. Memory management is handled through allocation and deallocation functions, ensuring no leaks occur.']

