#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_PACKETS 10000

typedef struct {
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG; // Assume this is a simple integer flag for simplicity
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag[10];
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for synchronizing access to the dynamic list
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t capacity;
    size_t count;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->items = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    return list;
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list_mutex);
    if (list) {
        free(list->items);
        free(list);
    }
    pthread_mutex_unlock(&list_mutex);
}

int resize_if_needed(DynamicList *list) {
    pthread_mutex_lock(&list_mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_items = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_items) {
            pthread_mutex_unlock(&list_mutex);
            return -1; // Memory allocation failed
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list_mutex);
    return 0;
}

int add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->count == 0 || ((list->items[list->count - 1].crcflag ^ pdu.crcflag) & 0x1)) {
        int resize_status = resize_if_needed(list);
        if (resize_status != 0) return -2; // Failed to resize

        pthread_mutex_lock(&list_mutex);
        list->items[list->count++] = pdu;
        pthread_mutex_unlock(&list_mutex);
        return 0;
    }
    return -1; // CRC flag condition not met
}

void *packet_processing_thread(void *arg) {
    DynamicList *list = (DynamicList*)arg;

    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = rand() % 1000000; // Random RNTI
        memset(pdu.crc_indication_rel8_tag, rand() % 256, sizeof(pdu.crc_indication_rel8_tag));
        pdu.crcflag = rand() & 1; // Random CRC flag

        if (add_pdu(list, pdu) != 0) {
            printf("Error adding PDU\n");
        }
    }

    return NULL;
}

int main() {
    DynamicList *list = create_dynamic_list(1024);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, packet_processing_thread, list)) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_dynamic_list(list);

    return 0;
}
```

### Key Points
- **Concurrency:** Uses a mutex to protect access to the dynamic list.
- **Dynamic List Management:** Resizes when necessary, doubling capacity.
- **CRC Flag Condition:** Ensures that CRC flags of consecutive PDUs differ by at least one bit.
- **Threading:** Four threads simulate concurrent packet processing.
- **Error Handling:** Basic checks for memory allocation and resizing failures.']

