#define MAX_INTERFACES 10

typedef struct {
    char *interface;
    int packet_count;
    int byte_count;
    float error_rate;
    int status; // 0 for success, non-zero for failure
} InterfaceStats;

typedef struct {
    InterfaceStats stats[MAX_INTERFACES];
    int interface_count;
    pthread_mutex_t lock;
    FILE *log_file;
    int log_level;
} GlobalData;

GlobalData global_data;

void handle_signal(int sig) {
    // Graceful shutdown logic can be implemented here
}

void* process_interface(void *arg) {
    char *interface = (char *)arg;
    InterfaceStats *stats = &global_data.stats[0];
    for (int i = 0; i < global_data.interface_count; ++i) {
        if (strcmp(interface, stats[i].interface) == 0) {
            pcap_t *handle;
            char errbuf[PCAP_ERRBUF_SIZE];
            handle = pcap_open_live(interface, BUFSIZ, 1, 1000, errbuf);
            if (!handle) {
                pthread_mutex_lock(&global_data.lock);
                stats[i].status = -1; // Error opening interface
                fprintf(global_data.log_file, "Error: Failed to open %s: %s\n", interface, errbuf);
                pthread_mutex_unlock(&global_data.lock);
                return NULL;
            }

            struct pcap_stat pstat;
            if (pcap_stats(handle, &pstat) == 0) {
                stats[i].packet_count = pstat.ps_recv;
                stats[i].byte_count = pstat.ps_ifaddr->ifa_addr->sa_len; // Placeholder for actual byte count
                // Calculate error_rate as needed
                pthread_mutex_lock(&global_data.lock);
                fprintf(global_data.log_file, "Interface %s: Packets=%d Bytes=%d\n", interface, stats[i].packet_count, stats[i].byte_count);
                pthread_mutex_unlock(&global_data.lock);
            } else {
                pthread_mutex_lock(&global_data.lock);
                stats[i].status = -2; // Error retrieving stats
                fprintf(global_data.log_file, "Error: Failed to get statistics for %s\n", interface);
                pthread_mutex_unlock(&global_data.lock);
            }
            pcap_close(handle);
            return NULL;
        }
    }
    return NULL;
}

int processNetworkStats(char **interfaces, int interface_count, const char *log_filename, int log_level) {
    global_data.interface_count = interface_count;
    strncpy(global_data.log_file, log_filename, sizeof(global_data.log_file));
    global_data.log_level = log_level;

    pthread_mutex_init(&global_data.lock, NULL);
    global_data.log_file = fopen(log_filename, "w");
    if (!global_data.log_file) {
        perror("Failed to open log file");
        return 0;
    }

    signal(SIGINT, handle_signal);

    for (int i = 0; i < interface_count; ++i) {
        strcpy(global_data.stats[i].interface, interfaces[i]);
        global_data.stats[i].status = 0;
    }

    pthread_t threads[MAX_INTERFACES];
    for (int i = 0; i < interface_count; ++i) {
        if (pthread_create(&threads[i], NULL, process_interface, (void *)interfaces[i])) {
            perror("Failed to create thread");
            global_data.stats[i].status = -3;
        }
    }

    int all_success = 1;
    for (int i = 0; i < interface_count; ++i) {
        pthread_join(threads[i], NULL);
        if (global_data.stats[i].status != 0) {
            all_success = 0;
        }
    }

    fclose(global_data.log_file);
    pthread_mutex_destroy(&global_data.lock);

    return all_success ? 1 : 0;
}
