#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define custom memory allocator functions (simplified version)
void* custom_malloc(size_t size);
void custom_free(void* ptr);

typedef struct Record {
    time_t timestamp;
    int sequence_number;
    struct Record* next;
} Record;

typedef struct Session {
    char* session_id;
    Record* records_head;
    int total_records;
    double average_sequence_number;
    pthread_mutex_t lock;  // For thread safety
    struct Session* next;
} Session;

// Global variables for simplicity (would be managed more robustly in production)
Session* sessions_head = NULL;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void add_record_to_session(const char* session_id, int sequence_number);
double calculate_average_sequence(Session* session);

// Custom memory allocation and deallocation functions
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);  // Handle more gracefully in production
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

// Function to add a record to the session asynchronously
void add_record_to_session(const char* session_id, int sequence_number) {
    Session *session = NULL;

    pthread_mutex_lock(&global_lock);

    for (Session* current = sessions_head; current != NULL; current = current->next) {
        if (strcmp(current->session_id, session_id) == 0) {
            session = current;
            break;
        }
    }

    if (!session) { // Session not found, create a new one
        session = custom_malloc(sizeof(Session));
        session->session_id = strdup(session_id);
        session->records_head = NULL;
        session->total_records = 0;
        session->average_sequence_number = 0.0;
        pthread_mutex_init(&session->lock, NULL);

        session->next = sessions_head;
        sessions_head = session;

        pthread_mutex_unlock(&global_lock);
    } else {
        pthread_mutex_unlock(&global_lock);
    }

    // Lock the specific session for updating records
    pthread_mutex_lock(&session->lock);

    Record* new_record = custom_malloc(sizeof(Record));
    new_record->timestamp = time(NULL);
    new_record->sequence_number = sequence_number;
    new_record->next = session->records_head;

    session->records_head = new_record;
    session->total_records++;

    // Update the average sequence number
    double current_avg = calculate_average_sequence(session);
    session->average_sequence_number = ((current_avg * (session->total_records - 1)) + sequence_number) / session->total_records;

    pthread_mutex_unlock(&session->lock);
}

double calculate_average_sequence(Session* session) {
    if (!session || !session->records_head) return 0.0;

    Record* current = session->records_head;
    int sum = 0;
    int count = 0;

    while (current != NULL) {
        sum += current->sequence_number;
        count++;
        current = current->next;
    }

    return (double)sum / count;
}

// Example usage of asynchronous updates and external data source integration
void periodic_external_update() {
    pthread_mutex_lock(&global_lock);

    for (Session* session = sessions_head; session != NULL; session = session->next) {
        // Lock the specific session to update metrics
        pthread_mutex_lock(&session->lock);

        // Simulate fetching updated data and recalculating average sequence number
        double new_avg = calculate_average_sequence(session);
        session->average_sequence_number = new_avg;

        pthread_mutex_unlock(&session->lock);
    }

    pthread_mutex_unlock(&global_lock);
}

// Main function for testing (not part of the task)
int main() {
    add_record_to_session("session1", 10);
    add_record_to_session("session1", 20);

    periodic_external_update();

    // Cleanup would go here

    return 0;
}
```

### Key Points:
- **Thread Safety**: Each session is protected by its mutex (`pthread_mutex_t lock`) for safe concurrent access.
- **Custom Memory Management**: Simplified custom memory allocation functions are provided, which should be extended to prevent fragmentation in a full implementation.
- **Asynchronous Updates**: The `add_record_to_session` function allows asynchronous updates of session records. 
- **External Data Integration**: A placeholder function `periodic_external_update` demonstrates updating metrics from an external source without blocking the main operations.

This implementation focuses on balancing performance, memory efficiency, and scalability with ease of maintenance.']

