#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createNfadWithConstraints(int N, size_t maxMemory) {
    if (N <= 0 || maxMemory == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T **current = &head;

    while (N > 0) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode || ((size_t)(head + N - current + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > maxMemory) {
            // Free previously allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->RX_UE_INFORMATION_TAG; // Assuming RX_UE_INFORMATION_TAG is used as next pointer here.
                free(temp);
            }
            return NULL;
        }

        newNode->RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Simulating valid tag
        newNode->RNTI = rand() % 1000 + 1; // Simulating valid RNTI

        if (rand() % 2) {
            newNode->CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        } else {
            newNode->CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }

        *current = newNode;
        current = &newNode->RX_UE_INFORMATION_TAG; // Assuming RX_UE_INFORMATION_TAG is used as next pointer here.

        N--;
    }

    return head;
}

// Example usage:
