function processStringWithConstraints(inputString, sizeLimit, maxMemoryThreshold) {
    if (typeof inputString !== 'string' || typeof sizeLimit !== 'number' || typeof maxMemoryThreshold !== 'number') return null;

    const currentMemoryUsage = new Blob([inputString]).size;

    if (currentMemoryUsage + 1 <= maxMemoryThreshold && inputString.length <= sizeLimit) {
        return `${inputString}-`;
    }
    return null;
}

function traverseDOMAndFilterElements(root, selector, callback, result = []) {
    if (!root || typeof root.querySelectorAll !== 'function') return result;

    const elements = root.querySelectorAll(selector);

    elements.forEach(element => {
        if (callback(element)) {
            result.push(element);
        }

        // Recursively process child nodes
        traverseDOMAndFilterElements(element, selector, callback, result);
    });

    return result;
}

// Example usage:
// const filteredElements = traverseDOMAndFilterElements(document.body, '.example-class', element => 
//     element.id === 'specific-id' || element.classList.contains('another-class'));
