['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_OFFSET_THRESHOLD 1000000
#define KEY_MIN 1
#define KEY_MAX 10000
#define DEFAULT_SUM_LIMIT 5000000

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t capacity;
    size_t sum_limit;
    pthread_mutex_t lock;
} RecordCollection;

// Initialize the random number generator
void init_random() {
    srand(time(NULL));
}

double generate_random_double(double min, double max) {
    return min + ((max - min) * rand()) / (RAND_MAX);
}

long generate_unique_offset(RecordCollection *collection, long max_offset) {
    long offset;
    do {
        offset = rand() % max_offset + 1; // Ensure it's > 0
    } while (!is_offset_unique(collection, offset));
    return offset;
}

int is_offset_unique(RecordCollection *collection, long offset) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].offset == offset) {
            return 0;
        }
    }
    return 1;
}

int is_key_unique(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return 0;
        }
    }
    return 1;
}

void initialize_collection(RecordCollection *collection, size_t num_records, double value_min, double value_max, long max_offset_threshold, size_t sum_limit) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->records = malloc(num_records * sizeof(Record));
    if (!collection->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = num_records;
    collection->sum_limit = sum_limit;

    init_random();

    while (collection->count < num_records && can_add_record(collection)) {
        long offset;
        int key;
        double value;

        do {
            offset = generate_unique_offset(collection, max_offset_threshold);
            key = rand() % (KEY_MAX - KEY_MIN + 1) + KEY_MIN;
        } while (!is_key_unique(collection, key));

        value = generate_random_double(value_min, value_max);

        pthread_mutex_lock(&collection->lock);
        if (can_add_record(collection)) {
            collection->records[collection->count++] = (Record){offset, key, value};
        }
        pthread_mutex_unlock(&collection->lock);
    }

    if (collection->count < num_records) {
        fprintf(stderr, "Failed to initialize all records within constraints\n");
    }
}

int can_add_record(RecordCollection *collection) {
    long sum_offsets = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        sum_offsets += collection->records[i].offset;
    }
    return sum_offsets + collection->records[collection->count].offset <= collection->sum_limit;
}

void free_collection(RecordCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
}

void print_summary(const RecordCollection *collection) {
    long total_offset = 0;
    int max_key = KEY_MIN - 1, min_key = KEY_MAX + 1;
    double total_value = 0.0;

    for (size_t i = 0; i < collection->count; ++i) {
        total_offset += collection->records[i].offset;
        if (collection->records[i].key > max_key) {
            max_key = collection->records[i].key;
        }
        if (collection->records[i].key < min_key) {
            min_key = collection->records[i].key;
        }
        total_value += collection->records[i].value;
    }

    printf("Summary:\n");
