// Define a structure to encapsulate the random value generator logic
typedef struct {
    unsigned int seed;
    int minValue;
    int maxValue;
} RandomValueGenerator;

void initializeRandomValueGenerator(RandomValueGenerator* rvg, unsigned int seed, int minValue, int maxValue) {
    if (minValue > maxValue) {
        // Swap values if minValue is greater than maxValue
        int temp = minValue;
        minValue = maxValue;
        maxValue = temp;
    }
    rvg->seed = seed;
    rvg->minValue = minValue;
    rvg->maxValue = maxValue;
}

int generateRandomValue(RandomValueGenerator* rvg) {
    // Use rand_r for thread-safe random number generation
    if (rvg->minValue == rvg->maxValue) {
        return rvg->minValue;  // Avoid redundant computation when range is a single value
    }
    srand(rvg->seed);  // Seed the random number generator
    int range = rvg->maxValue - rvg->minValue + 1;
    return rand_r(&rvg->seed) % range + rvg->minValue;
}

NFAPI_CRC_INDICATION_PDU_T* generateNfarCrcIndications(int N, int minValue, int maxValue, unsigned int seed) {
