        indications[i].RX_UE_INFORMATION_TAG = generateRandomValue(&rvg); // Generate random RX_UE_INFORMATION_TAG
        indications[i].RNTI = generateRandomValue(&rvg);                  // Generate random RNTI

        // Set CRCFLAG to true or false with equal probability
        int crcFlagValue = generateRandomValue(&rvg) % 2; 
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (crcFlagValue == 0) ? 0 : 1;
    }

    return indications;
}

int main() {
