#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_LIST_SIZE 1000
#define LOG_FILE "nfa_ind_log.txt"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t allocated_count;
    size_t actual_count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = NULL;
    list->allocated_count = 0;
    list->actual_count = 0;

    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void log_event(const char* event) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", event);
        fclose(log_file);
    }
}

int allocate_and_populate_list(DynamicList* list, size_t n) {
    pthread_mutex_lock(&list->lock);

    if (!list || !n) {
        log_event("Error: Invalid input parameters.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (n > MAX_LIST_SIZE) {
        n = MAX_LIST_SIZE;
        log_event("List size truncated to maximum threshold.");
    }

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_event("Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    for (size_t i = 0; i < n; ++i) {
        new_data[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        new_data[i].RNTI = rand() % 1000;
    }

    free(list->data);
    list->data = new_data;
    list->allocated_count = n;
    list->actual_count = n;

    log_event("Allocated and populated list successfully.");

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_dynamic_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    if (list->data) {
        free(list->data);
        log_event("Freed memory for dynamic list.");
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int serialize_list_to_file(DynamicList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    size_t write_count = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->actual_count, file);
    if (write_count != list->actual_count) {
        log_event("Serialization failed.");
        pthread_mutex_unlock(&list->lock);
        fclose(file);
        return -1;
    }

    log_event("Serialized dynamic list to file successfully.");

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

int deserialize_list_from_file(DynamicList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T temp;
    size_t read_count = fread(&temp, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);

    if (read_count != 1) {
        log_event("Deserialization failed.");
        pthread_mutex_unlock(&list->lock);
        fclose(file);
        return -1;
    }

    size_t total_elements = fread(list->data + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->allocated_count - 1, file);

    if (total_elements != list->allocated_count - 1) {
        log_event("Deserialization incomplete.");
        pthread_mutex_unlock(&list->lock);
        fclose(file);
        free(list->data);
        return -1;
    }

    list->actual_count = total_elements + 1;

    log_event("Deserialized dynamic list from file successfully.");

    pthread_mutex_unlock(&list->lock);
    fclose(file);

    return 0;
}

void handle_external_dependencies(DynamicList* list) {
    // Simulate external dependencies handling
    if (rand() % 10 == 0) {  // Random failure simulation
        log_event("External dependency failed.");
    } else {
        log_event("Handled external dependencies successfully.");
    }
}
