```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

uint32_t generate_crc_flag(uint32_t previous_flag) {
    uint32_t new_flag = rand() & 0xFFFFFFFF;
    while ((new_flag ^ previous_flag) == 0) {
        new_flag = rand() & 0xFFFFFFFF;
    }
    return new_flag;
}

int add_element(CRCList* list, uint16_t rx_ue_info_tag, uint16_t rnti) {
    if (rnti == 0xFFFF) return -1; // Invalid RNTI

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    uint32_t previous_flag = 0;
    Node* current = list->head;

    if (current) {
        while (current->next) {
            current = current->next;
        }
        previous_flag = current->data.CRC_INDICATION_REL8_TAG.CRCFLAG;
    }

    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_crc_flag(previous_flag);
    new_node->next = NULL;

    if (!list->head) {
        list->head = new_node;
    } else {
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element(CRCList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(CRCList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    if (current) {
        result = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

void report_memory_usage(CRCList* list) {
    int count = 0;
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current) {
        count++;
        current = current->next;
    }

    printf("Memory Usage: %d elements\n", count);
    pthread_mutex_unlock(&list->lock);
}

void report_performance_metrics(CRCList* list) {
    // Placeholder for performance metrics reporting
    // Could include time taken for operations, number of operations per second, etc.
    printf("Performance Metrics: Not implemented\n");
}
