#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 10

typedef struct {
    int value;
} Record;

typedef struct {
    int RNTI;
    unsigned char RX_UE_INFORMATION_TAG[16];
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    Record* records;
    size_t record_count;
    pthread_mutex_t lock;
} Session;

typedef struct {
    Session sessions[MAX_SESSIONS];
    pthread_mutex_t global_lock;
} SessionManager;

// Mock function to simulate random value generation
bool generateRandomCRCFlag(int minValue, int maxValue) {
    return (rand() % 2) ? true : false;
}

void initializeSession(Session* session, size_t record_count, int record_value_range) {
    pthread_mutex_init(&session->lock, NULL);
    session->records = malloc(record_count * sizeof(Record));
    if (!session->records) {
        printf("Memory allocation failed for records. Continuing with reduced capacity.\n");
        session->record_count = 0;
    } else {
        session->record_count = record_count;
        for (size_t i = 0; i < record_count; ++i) {
            session->records[i].value = rand() % record_value_range + 1;
        }
    }
}

void cleanupSession(Session* session) {
    pthread_mutex_destroy(&session->lock);
    free(session->records);
}

NFAPI_CRC_INDICATION_PDU_T* generateNfarCrcIndicationsWithSessionManagement(
    size_t N, int minValue, int maxValue,
    int max_sessions, size_t record_array_size, int record_value_range) {

    SessionManager manager;
    pthread_mutex_init(&manager.global_lock, NULL);

    for (int i = 0; i < max_sessions; ++i) {
        initializeSession(&manager.sessions[i], record_array_size, record_value_range);
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        printf("Memory allocation failed for indications. Exiting.\n");
        return NULL;
    }

    srand(time(NULL));

    pthread_t threads[MAX_SESSIONS];
    for (int i = 0; i < N; ++i) {
        int session_index = rand() % max_sessions;

        pthread_mutex_lock(&manager.global_lock);
        Session* session = &manager.sessions[session_index];

        if (pthread_create(&threads[i], NULL, (void*)[](
            void* arg) -> void* {
                pthread_mutex_lock(&((Session*)arg)->lock);

                NFAPI_CRC_INDICATION_PDU_T* indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!indication) {
                    printf("Memory allocation failed for indication. Skipping.\n");
                    pthread_mutex_unlock(&((Session*)arg)->lock);
                    return NULL;
                }

                indication->RNTI = rand();
                memset(indication->RX_UE_INFORMATION_TAG, 0, sizeof(indication->RX_UE_INFORMATION_TAG));
                indication->CRCFLAG = generateRandomCRCFlag(minValue, maxValue);

                pthread_mutex_unlock(&((Session*)arg)->lock);
                return NULL;
            }, (void*)&session) != 0) {
            printf("Failed to create thread for session %d.\n", session_index);
        }

        pthread_mutex_unlock(&manager.global_lock);
    }

    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&manager.global_lock);

    for (int i = 0; i < max_sessions; ++i) {
        cleanupSession(&manager.sessions[i]);
    }

    return indications;
