#include <pthread.h>
#include <time.h>

typedef struct CRC_Indication_Rel8 {
    int CRCFLAG;
} CRC_Indication_Rel8;

typedef struct {
    unsigned long long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_Indication_Rel8 CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    int (*generate)(int min, int max);
    pthread_mutex_t mutex;
    unsigned int seed;
} RandomValueGenerator;

// Function prototypes
void initializeRandomValueGenerator(RandomValueGenerator* rvg, unsigned int seed);
int generateRandomInt(RandomValueGenerator* rvg, int minValue, int maxValue);

NFAPI_CRC_INDICATION_PDU_T* generateNfarCrcIndications(int N, int minValue, int maxValue, unsigned int seed) {
    RandomValueGenerator rvg;
    initializeRandomValueGenerator(&rvg, seed);

    Node *head = NULL, *tail = NULL;
    pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&listMutex);

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate unique RNTI
        int rnti;
        do {
            rnti = generateRandomInt(&rvg, 1, INT_MAX);
        } while (!isUniqueRNTI(rnti, head));

        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = (unsigned long)rnti;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generateRandomInt(&rvg, minValue, maxValue);

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            perror("Failed to allocate memory for new node");
            pthread_mutex_unlock(&listMutex);
            return NULL;
        }

        newNode->data = pdu;
        newNode->next = NULL;

        if (!head) head = newNode;
        if (tail) tail->next = newNode;
        tail = newNode;
    }

    pthread_mutex_unlock(&listMutex);

    return head;
}

void initializeRandomValueGenerator(RandomValueGenerator* rvg, unsigned int seed) {
    rvg->generate = generateRandomIntWrapper;
    pthread_mutex_init(&rvg->mutex, NULL);
    rvg->seed = seed;
    srand(seed); // Initialize the global random generator
}

int generateRandomInt(RandomValueGenerator* rvg, int minValue, int maxValue) {
    if (minValue > maxValue) return minValue;  // Handle edge case

    pthread_mutex_lock(&rvg->mutex);
    int range = maxValue - minValue + 1;
    int value = rand() % range + minValue;

    pthread_mutex_unlock(&rvg->mutex);
    return value < 0 ? !value : value;
}

int generateRandomIntWrapper(int min, int max) {
    RandomValueGenerator* rvg = ...; // Initialize or fetch as appropriate
    return generateRandomInt(rvg, min, max);
}

int isUniqueRNTI(unsigned long RNTI, Node* head) {
    while (head) {
        if (head->data.RNTI == RNTI)
            return 0;
        head = head->next;
    }
    return 1;
}
