#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_POOL_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned int seed;
} DynamicArray;

void log_event(const char* message) {
    fprintf(stderr, "%s\n", message);
}

DynamicArray* initialize_dynamic_array(unsigned int seed) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        log_event("Failed to allocate memory for DynamicArray");
        return NULL;
    }
    pthread_mutex_init(&array->lock, NULL);
    array->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_POOL_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->pool) {
        log_event("Failed to allocate initial memory pool");
        free(array);
        return NULL;
    }
    array->capacity = INITIAL_POOL_SIZE;
    array->count = 0;
    array->seed = seed;

    srand(seed);

    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &array->pool[i];
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    log_event("Dynamic array initialized successfully");
    return array;
}

int insert_pdu(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            log_event("Failed to reallocate memory pool");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->pool = new_pool;
        array->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* target_pdu = &array->pool[array->count++];
    *target_pdu = *pdu;

    pthread_mutex_unlock(&array->lock);
    log_event("PDU inserted successfully");
    return 0;
}

int delete_pdu(DynamicArray* array, size_t index) {
    if (index >= array->count) {
        log_event("Index out of bounds for deletion");
        return -1;
    }

    pthread_mutex_lock(&array->lock);

    memmove(&array->pool[index], &array->pool[index + 1], (array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count--;

    if (array->count < array->capacity / 4 && array->capacity > INITIAL_POOL_SIZE) {
        size_t new_capacity = array->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool && new_capacity != array->capacity) {
            log_event("Failed to shrink memory pool");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->pool = new_pool;
        array->capacity = new_capacity;
    }

    pthread_mutex_unlock(&array->lock);
    log_event("PDU deleted successfully");
    return 0;
}

void cleanup_dynamic_array(DynamicArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->pool);
    free(array);
    log_event("Dynamic array cleaned up successfully");
}
