    TX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    TX_POWER_LEVEL_TAG power_level;
} TX_MESSAGE_PDU_T;

#define INITIAL_CAPACITY 16

typedef struct {
    TX_MESSAGE_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MessageList;

void init_list(MessageList* list) {
    list->data = (TX_MESSAGE_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(TX_MESSAGE_PDU_T));
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

bool is_power_level_valid(int8_t prev_power, int8_t new_power) {
    return abs(prev_power - new_power) >= 1;
}

void ensure_capacity(MessageList* list) {
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        TX_MESSAGE_PDU_T* new_data = (TX_MESSAGE_PDU_T*)realloc(list->data, new_capacity * sizeof(TX_MESSAGE_PDU_T));
        if (!new_data) return; // Handle reallocation failure gracefully.
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

bool add_message(MessageList* list, TX_MESSAGE_PDU_T message) {
    pthread_mutex_lock(&list->lock);

    if (list->size > 0 && !is_power_level_valid(list->data[list->size - 1].power_level.tx_power_level, message.power_level.tx_power_level)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    ensure_capacity(list);
    list->data[list->size++] = message;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_message(MessageList* list, size_t index) {
    if (index >= list->size) return false;

    pthread_mutex_lock(&list->lock);

    for (size_t i = index; i < list->size - 1; ++i) {
        list->data[i] = list->data[i + 1];
    }
    --list->size;

    pthread_mutex_unlock(&list->lock);
    return true;
}

TX_MESSAGE_PDU_T* get_message(MessageList* list, size_t index) {
    if (index >= list->size) return NULL;

    pthread_mutex_lock(&list->lock);
    TX_MESSAGE_PDU_T* message = &list->data[index];
    pthread_mutex_unlock(&list->lock);

    return message;
}

void free_list(MessageList* list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}
