#define ID_LENGTH 10
#define MEASUREMENT_MIN -1000.0
#define MEASUREMENT_MAX 1000.0

typedef struct {
    long timestamp;
    double measurement;
    char* identifier;
} sensor;

int initialize_sensors(sensor*** sensors, size_t num_sensors) {
    if (num_sensors == 0 || sensors == NULL) return -1;

    *sensors = (sensor**)malloc(num_sensors * sizeof(sensor*));
    if (*sensors == NULL) return -2;

    long* timestamps = (long*)calloc(num_sensors, sizeof(long));
    double* measurements = (double*)calloc(num_sensors, sizeof(double));
    char** identifiers = (char**)malloc(num_sensors * sizeof(char*));

    if (!timestamps || !measurements || !identifiers) {
        free(timestamps);
        free(measurements);
        free(identifiers);
        free(*sensors);
        return -3;
    }

    srand(time(NULL));
    char id[ID_LENGTH + 1];
    int found_unique_id;

    for (size_t i = 0; i < num_sensors; ++i) {
        (*sensors)[i] = (sensor*)malloc(sizeof(sensor));
        if ((*sensors)[i] == NULL) goto cleanup;

        timestamps[i] = rand() % ((unsigned long)-1);

        measurements[i] = MEASUREMENT_MIN + ((double)rand() / RAND_MAX * 
                                             (MEASUREMENT_MAX - MEASUREMENT_MIN));

        do {
            found_unique_id = 1;
            for (int j = 0; j < ID_LENGTH; ++j)
                id[j] = 'a' + rand() % 26;

            id[ID_LENGTH] = '\0';

            for (size_t j = 0; j < i; ++j) {
                if (strcmp(identifiers[j], id) == 0) {
                    found_unique_id = 0;
                    break;
                }
            }

        } while (!found_unique_id);

        identifiers[i] = strdup(id);
        if (identifiers[i] == NULL) goto cleanup;

        (*sensors)[i]->timestamp = timestamps[i];
        (*sensors)[i]->measurement = measurements[i];
        (*sensors)[i]->identifier = identifiers[i];
    }

    free(timestamps);
    free(measurements);

    return 0;

cleanup:
    for (size_t i = 0; i < num_sensors; ++i) {
        if ((*sensors)[i]) {
            free((*sensors)[i]);
        }
        if (identifiers[i]) {
            free(identifiers[i]);
        }
    }

    free(*sensors);
    free(timestamps);
    free(measurements);
    free(identifiers);

    return -4;
}
