#define MAX_ELEMENTS 10000
#define CHUNK_SIZE 256

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_node(Node* node) {
    free(node);
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int is_valid_rnti(uint16_t rnti) {
    // Implement RNTI validation logic here
    return 1; // Placeholder for valid RNTI
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t previous_flag) {
    uint8_t crcflag;
    do {
        crcflag = rand() & 0xFF; // Random byte between 0 and 255
    } while ((crcflag ^ previous_flag) == 0);
    pdu->CRCFLAG = crcflag;
}

int add_element(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    if (!is_valid_rnti(data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Invalid RNTI
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    uint8_t previous_crcflag = list->tail ? list->tail->data.CRCFLAG : 0;
    set_random_crcflag(&data, previous_crcflag);

    new_node->data = data;
    new_node->next = NULL;

    if (list->count == 0) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_element(List* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }

            if (current == list->tail) {
                list->tail = prev;
            }

            destroy_node(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Element not found
}

NFAPI_CRC_INDICATION_PDU_T* get_element(List* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* data = &current->data;
            pthread_mutex_unlock(&list->lock);
            return data; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Element not found
}

void report_memory_usage(List* list) {
    // Implement memory usage reporting here
    printf("Current element count: %zu\n", list->count);
}

int main() {
    List* list = create_list();

    if (!list) {
        fprintf(stderr, "Failed to initialize list.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 123, .RNTI = 456 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 789, .RNTI = 101112 };

    add_element(list, pdu1);
    add_element(list, pdu2);

    report_memory_usage(list);

    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = get_element(list, 456);
    if (retrieved_pdu) {
        printf("Retrieved RNTI: %u\n", retrieved_pdu->RNTI);
    }

    remove_element(list, 456);
    report_memory_usage(list);

    destroy_list(list);

    return EXIT_SUCCESS;
}
