#define MAX_RECORDS 100

typedef struct {
    int value;
    char *buffer;
    EVP_CIPHER_CTX *ctx;
} record;

void handle_openssl_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, ERR_error_string(ERR_get_error(), NULL));
}

void generate_random_string(char *str, size_t length) {
    if (!RAND_bytes((unsigned char *)str, length)) {
        handle_openssl_error("Failed to generate random string");
        exit(EXIT_FAILURE);
    }
    str[length] = '\0';
}

record* initialize_records(size_t record_count, unsigned long offset[], size_t key_sizes[], size_t buffer_length) {
    record *records = calloc(record_count, sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < record_count; ++i) {
        records[i].buffer = malloc(buffer_length);
        if (!records[i].buffer) {
            fprintf(stderr, "Memory allocation failed for buffer\n");
            free(records);
            exit(EXIT_FAILURE);
        }

        generate_random_string(records[i].buffer, buffer_length);

        records[i].value = rand() % 100; // Random value within specified range

        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            handle_openssl_error("Failed to create cipher context");
            free(records[i].buffer);
            continue;
        }

        records[i].ctx = ctx;

        int result;
        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL) != 1) {
            handle_openssl_error("Failed to initialize encryption");
            EVP_CIPHER_CTX_free(ctx);
            free(records[i].buffer);
            continue;
        }

        if (EVP_CIPHER_CTX_set_key_length(ctx, key_sizes[i]) <= 0) {
            handle_openssl_error("Failed to set key length");
            EVP_CIPHER_CTX_free(ctx);
            free(records[i].buffer);
            continue;
        }

        // Assume IV is part of the random string here; in practice, manage it separately
        if (EVP_EncryptInit_ex(ctx, NULL, NULL, records[i].buffer, offset + i) <= 0) {
            handle_openssl_error("Failed to initialize encryption with key and IV");
            EVP_CIPHER_CTX_free(ctx);
            free(records[i].buffer);
            continue;
        }
    }

    return records;
}

void cleanup_records(record *records, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        if (records[i].ctx) {
            EVP_CIPHER_CTX_free(records[i].ctx);
        }
        if (records[i].buffer) {
            free(records[i].buffer);
        }
    }
    free(records);
}

void setup_random_seed(unsigned int seed) {
    srand(seed);  // For generating random values
}

record* initialize_crypto_records(size_t record_count, unsigned long offset[], size_t key_sizes[], size_t buffer_length, unsigned int seed, int mode) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    setup_random_seed(seed);

    record *records = NULL;

    pthread_mutex_lock(&lock);
    records = initialize_records(record_count, offset, key_sizes, buffer_length);
    pthread_mutex_unlock(&lock);

    return records;
}

// Example usage of the function
