void initializeArrays(int keyArraySize, long* offsetArray, int* keyArray, char* errorBuffer) {
    if (offsetArray == NULL || keyArray == NULL || errorBuffer == NULL) return;

    size_t offsetArraySize = 2 * keyArraySize * sizeof(long);

    // Memory allocation for arrays
    long* offsets = (long*)aligned_alloc(16, offsetArraySize); // Aligned to minimize fragmentation
    int* keys = (int*)malloc(keyArraySize * sizeof(int));

    if (!offsets || !keys) {
        snprintf(errorBuffer, 256, "Memory allocation failed for arrays.");
        if (offsets) free(offsets);
        if (keys) free(keys);
        return;
    }

    // Initialize RNG
    srand((unsigned int)time(NULL));

    // Populate the keys array and initialize offset values with random numbers
    for (int i = 0; i < keyArraySize; ++i) {
        keys[i] = rand() % 100 + 1; // Random number in range [1, 100]

        // Assign to both arrays as per requirement
        offsets[2 * i] = (long)keys[i];       // Example use of offset array
        offsets[2 * i + 1] = -1L;             // Placeholder or different usage
    }

    // Clean up and assign allocated memory back to the provided pointers
    memcpy(offsetArray, offsets, offsetArraySize);
    memcpy(keyArray, keys, keyArraySize * sizeof(int));

    free(offsets); // Free temporary allocation
}

int main() {
    int keyArray[100];
    long offsetArray[200]; // Ensuring it's large enough as per the task description
    char errorBuffer[256];

    initializeArrays(100, offsetArray, keyArray, errorBuffer);

    if (errorBuffer[0] != '\0') {
        printf("Error: %s\n", errorBuffer);
    } else {
        // Continue with operations knowing arrays are initialized...
        printf("Initialization successful.\n");
    }

    return 0;
}
