// Assuming these structures are defined as per your system's requirements
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_THREADS 10000

static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static atomic_int logging_enabled = ATOMIC_VAR_INIT(0);

// Function to enable/disable logging
void set_logging(int enabled) {
    atomic_store(&logging_enabled, enabled);
}

// Thread-safe function to allocate and initialize the array
NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_array(size_t N) {
    pthread_mutex_lock(&memory_lock);

    // Allocate memory for N structures
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    // Initialize each structure
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = (uint16_t)(i % 65535);  // Example RNTI assignment

        // Randomly set CRCFLAG
        srand(time(NULL) + i);
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (atomic_load(&logging_enabled)) {
            printf("Initialized PDU[%zu]: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n",
                   i, array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
    }

    pthread_mutex_unlock(&memory_lock);

    return array;
}

// Function to free allocated memory
void free_nfa_crc_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        pthread_mutex_lock(&memory_lock);
        free(array);
        pthread_mutex_unlock(&memory_lock);
    }
}
