typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 64
#define MAX_ELEMENTS 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    unsigned int seed;
    pthread_mutex_t lock;
    time_t last_allocation_time;
    uint32_t allocated_this_second;
    uint64_t total_allocated;
    uint64_t total_freed;
} DynamicArray;

// Helper functions
static inline uint32_t hash(const char *str, size_t index) {
    return (uint32_t)((uintptr_t)str ^ index);
}

static inline void log_event(const char *event) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), event);
}

// Custom memory allocation and resizing
void resize_array(DynamicArray *dyn_array, size_t new_capacity) {
    if (new_capacity > MAX_ELEMENTS) return;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_event("Memory allocation failed during resize.");
        return;
    }
    dyn_array->array = new_array;
    dyn_array->capacity = new_capacity;
    log_event("Array resized.");
}

void add_element(DynamicArray *dyn_array, const char *user_string) {
    pthread_mutex_lock(&dyn_array->lock);

    time_t now = time(NULL);
    if (difftime(now, dyn_array->last_allocation_time) < 1 && dyn_array->allocated_this_second >= 10) {
        pthread_mutex_unlock(&dyn_array->lock);
        return;
    }

    if (dyn_array->count == dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        resize_array(dyn_array, new_capacity);
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &dyn_array->array[dyn_array->count];
    element->RX_UE_INFORMATION_TAG = hash(user_string, dyn_array->count);
    element->RNTI = (uint16_t)(element->RX_UE_INFORMATION_TAG >> 16);
    srand(dyn_array->seed + dyn_array->count);
    element->CRCFLAG = rand() & 1;

    dyn_array->count++;
    dyn_array->total_allocated++;
    if (difftime(now, dyn_array->last_allocation_time) < 1) {
        dyn_array->allocated_this_second++;
    } else {
        dyn_array->allocated_this_second = 1;
        dyn_array->last_allocation_time = now;
    }

    pthread_mutex_unlock(&dyn_array->lock);
}

void free_element(DynamicArray *dyn_array, size_t index) {
    pthread_mutex_lock(&dyn_array->lock);

    if (index < dyn_array->count) {
        memmove(&dyn_array->array[index], &dyn_array->array[index + 1],
                (dyn_array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        dyn_array->count--;
        dyn_array->total_freed++;
    }

    pthread_mutex_unlock(&dyn_array->lock);
}

DynamicArray* create_dynamic_array(unsigned int seed) {
    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) {
        log_event("Memory allocation failed for dynamic array.");
        return NULL;
    }
    dyn_array->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        log_event("Memory allocation failed for initial array.");
        return NULL;
    }
    dyn_array->capacity = INITIAL_CAPACITY;
    dyn_array->count = 0;
    dyn_array->seed = seed;
    pthread_mutex_init(&dyn_array->lock, NULL);
    dyn_array->last_allocation_time = time(NULL);
    dyn_array->allocated_this_second = 0;
    dyn_array->total_allocated = 0;
    dyn_array->total_freed = 0;

    log_event("Dynamic array created.");
    return dyn_array;
}

void destroy_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        pthread_mutex_destroy(&dyn_array->lock);
        free(dyn_array);
        log_event("Dynamic array destroyed.");
    }
}
