#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int count;
    int total_crc_validations[MAX_ENTRIES];
} NFAPICRCList;

// Initialize the list
void init_list(NFAPICRCList* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    memset(list->total_crc_validations, 0, sizeof(list->total_crc_validations));
}

// Check if RNTI exists
int rnti_exists(NFAPICRCList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.crc_tag.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Add a new entry
void add_entry(NFAPICRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (rnti_exists(list, entry.crc_tag.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;

    if (list->count >= MAX_ENTRIES) {
        // Remove oldest entry
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    } else {
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
}

// Remove an entry by RNTI
void remove_entry(NFAPICRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current && current->data.crc_tag.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->count--;

    pthread_mutex_unlock(&list->lock);
}

// Print all RX_UE_INFORMATION_TAG values
void print_rx_ue_tags(NFAPICRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("%d\n", current->data.crc_tag.RX_UE_INFORMATION_TAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Export the list to a binary file
void export_list(NFAPICRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

// Import the list from a binary file
void import_list(NFAPICRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    while (fread(&(NFAPI_CRC_INDICATION_PDU_T){0}, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_entry(list, (NFAPI_CRC_INDICATION_PDU_T){.crc_tag = {.RX_UE_INFORMATION_TAG = rand(), .RNTI = rand()}}); // Populate with random data
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

// Main function to demonstrate usage
int main(void) {
    NFAPICRCList list;
    init_list(&list);

    // Example operations
    NFAPI_CRC_INDICATION_PDU_T entry = { .crc_tag = {.RX_UE_INFORMATION_TAG = 123, .RNTI = 456}, .CRCFLAG = rand() % 2 };
    add_entry(&list, entry);

    print_rx_ue_tags(&list);

    export_list(&list, "export.dat");
    remove_entry(&list, 456);
    import_list(&list, "export.dat");

    return 0;
}
