StateNode* create_sequence(Node** initial_states, int num_initial_states, Node* fsa, int target_state, int max_length) {
    if (!initial_states || !fsa || num_initial_states <= 0 || max_length <= 0) return NULL;

    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for arrays
    long* offsets = (long*)malloc(num_initial_states * sizeof(long));
    int* keys = (int*)malloc(num_initial_states * sizeof(int));
    record* records = (record*)malloc(num_initial_states * sizeof(record));

