    // Initialize arrays with random values
    for (int i = 0; i < num_initial_states; ++i) {
        offsets[i] = rand_range(1, 100);
        keys[i] = rand_range(1, 100);
        records[i].value = rand_range(1, 100);
    }

    // Create the state list
    StateNode* head = NULL;
    StateNode** current_tail = &head;

    for (int i = 0; i < num_initial_states && *current_tail != NULL; ++i) {
        StateNode* new_node = (StateNode*)malloc(sizeof(StateNode));
        if (!new_node) {
            // Cleanup in case of failure
            while (head) {
                StateNode* temp = head;
                head = head->next;
                free(temp);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        new_node->state_id = initial_states[i]->id;
        new_node->next = NULL;

        *current_tail = new_node;
        current_tail = &new_node->next;

        // Traverse the FSA
        if (initial_states[i] == fsa && initial_states[i]->id == target_state) {
            break; // Target state found, stop traversing
        }

        for (int j = 0; j < initial_states[i]->num_edges && new_node->next != NULL; ++j) {
            Node* next_node = initial_states[i]->edges[j].target_node;
            if (next_node->id == target_state) {
                StateNode* target_node = (StateNode*)malloc(sizeof(StateNode));
                if (!target_node) {
