                        StateNode* temp = head;
                        head = head->next;
                        free(temp);
                    }
                    free(offsets);
                    free(keys);
                    free(records);
                    return NULL;
                }

                target_node->state_id = next_node->id;
                target_node->next = NULL;

                *current_tail = target_node;
                current_tail = &target_node->next;

                break; // Target state reached, end traversal
            }
        }
    }

    return head;
}

