// Initialize the list with a given initial capacity
PduList* pdu_list_create(size_t initial_capacity) {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

// Add a new element to the list
int pdu_list_add(PduList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!temp_array) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }

        list->array = temp_array;
        list->capacity = new_capacity;
    }

    list->array[list->size] = element;
    list->size++;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Remove an element by index
int pdu_list_remove(PduList* list, size_t index) {
    if (index >= list->size) return -1; // Invalid index

    pthread_mutex_lock(&list->mutex);

    memmove(&list->array[index], &list->array[index + 1], 
            (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    list->size--;

    if (list->size < list->capacity / 4 && list->capacity > INITIAL_CAPACITY) {
        size_t new_capacity = list->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (temp_array) {
            list->array = temp_array;
            list->capacity = new_capacity;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Iterate over the array in forward direction
void pdu_list_iterate_forward(PduList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        callback(list->array[i]);
    }

    pthread_mutex_unlock(&list->mutex);
}

// Iterate over the array in reverse direction
void pdu_list_iterate_reverse(PduList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = list->size; i-- > 0;) {
        callback(list->array[i]);
    }

    pthread_mutex_unlock(&list->mutex);
}

// Free the list and its resources
void pdu_list_destroy(PduList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    free(list->array);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// A simple example callback function for iteration
void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
}

// Example usage
int main() {
    PduList* list = pdu_list_create(INITIAL_CAPACITY);

    if (!list) return EXIT_FAILURE;

    // Populate with dummy data and random CRCFLAG
    for (int i = 0; i < 15; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = i, .RNTI = i + 100, 
                                               .CRC_INDICATION_REL8_TAG = { .CRCFLAG = rand() % 2 } };
        pdu_list_add(list, element);
    }

    // Iterate forward
    printf("Forward iteration:\n");
    pdu_list_iterate_forward(list, print_pdu);

    // Iterate reverse
    printf("\nReverse iteration:\n");
    pdu_list_iterate_reverse(list, print_pdu);

    // Remove an element and show the list again
    if (pdu_list_remove(list, 5) == 0) {
        printf("\nAfter removing index 5:\n");
        pdu_list_iterate_forward(list, print_pdu);
    }

    // Cleanup
    pdu_list_destroy(list);

    return EXIT_SUCCESS;
}
```

This code provides a thread-safe dynamic array implementation for managing `NFAPI_CRC_INDICATION_PDU_T` structures. The list supports adding and removing elements, iterating in both directions, and handles memory allocation efficiently to prevent fragmentation or overflow. Thread safety is ensured with mutex locks during modifications. Remember that for production-level implementations, additional error handling and more sophisticated persistent storage solutions should be considered.']

