#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 5000

typedef struct {
    uint32_t frame_id;
    char payload[256]; // Example fixed size, adjust as necessary
} L2_RX_FRAME_HEADER;

typedef struct {
    L2_RX_FRAME_HEADER header;
    char *frame_payload;
    time_t timestamp;
} NFAPI_L2_RX_FRAME_T;

typedef struct Node {
    NFAPI_L2_RX_FRAME_T frame;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    double total_bytes_received;
    double start_time;
} FrameList;

FrameList* init_frame_list() {
    FrameList* list = malloc(sizeof(FrameList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->total_bytes_received = 0.0;
    clock_t start_clock = clock();
    list->start_time = (double)start_clock / CLOCKS_PER_SEC;
    return list;
}

int contains_frame_id(FrameList* list, uint32_t frame_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->frame.header.frame_id == frame_id)
            return 1;
        current = current->next;
    }
    return 0;
}

void add_frame(FrameList* list, NFAPI_L2_RX_FRAME_T new_frame) {
    if (contains_frame_id(list, new_frame.header.frame_id))
        return;

    Node* new_node = malloc(sizeof(Node));
    new_node->frame = new_frame;
    new_node->next = NULL;

    if (list->size == 0 || list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
    list->total_bytes_received += strlen(new_frame.frame_payload);

    if (list->size > MAX_ENTRIES) {
        Node* to_remove = list->head;
        list->head = list->head->next;
        free(to_remove);
        list->size--;
    }
}

void remove_frame(FrameList* list, uint32_t frame_id) {
    Node **indirect = &list->head;
    while (*indirect != NULL) {
        if ((*indirect)->frame.header.frame_id == frame_id) {
            Node* to_delete = *indirect;
            *indirect = (*indirect)->next;
            free(to_delete->frame.frame_payload);
            free(to_delete);
            list->size--;
            return;
        }
        indirect = &(*indirect)->next;
    }
}

void print_frame_payload_lengths(FrameList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("Frame payload length: %zu\n", strlen(current->frame.frame_payload));
        current = current->next;
    }
}

double calculate_average_throughput(FrameList* list) {
    double elapsed_time = ((double)clock() / CLOCKS_PER_SEC) - list->start_time;
    return elapsed_time > 0 ? (list->total_bytes_received / elapsed_time) : 0.0;
}

void export_to_file(FrameList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->frame.header.frame_id, sizeof(current->frame.header.frame_id), 1, file);
        size_t payload_len = strlen(current->frame.frame_payload) + 1; // Including null terminator
        fwrite(&payload_len, sizeof(payload_len), 1, file);
        fwrite(current->frame.frame_payload, payload_len, 1, file);
        current = current->next;
    }

    fclose(file);
}

void import_from_file(FrameList* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    while (fscanf(file, "%u", &list->tail->frame.header.frame_id) == 1) {
        size_t payload_len;
        fread(&payload_len, sizeof(payload_len), 1, file);

        char* new_payload = malloc(payload_len);
        fread(new_payload, payload_len, 1, file);

        NFAPI_L2_RX_FRAME_T new_frame = { .header.frame_id };
        strcpy(new_frame.frame_payload, new_payload);
        new_frame.timestamp = time(NULL); // Example timestamp

        add_frame(list, new_frame);
        free(new_payload);
    }

    fclose(file);
}

void free_list(FrameList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete->frame.frame_payload);
        free(to_delete);
    }
    free(list);
}
```']

['Here is a C function that dynamically allocates memory for an array of `NFAPI_CRC_INDICATION_PDU_T` structures, handles allocation failures gracefully, logs appropriate error messages, and ensures bounds checking. It also provides a mechanism to deallocate the allocated memory when no longer needed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to allocate and populate the array
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdus(int N, int* error_code) {
    if (N <= 0) {
        *error_code = 0; // No error, no allocation needed
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for %d structures.\n", N);
        *error_code = -1; // Allocation error
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example validation
        if (array[i].RX_UE_INFORMATION_TAG < 0 || array[i].RX_UE_INFORMATION_TAG > 99) {
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG for index %d.\n", i);
            *error_code = -2; // Validation error
            free(array);
            return NULL;
        }

        array[i].RNTI = rand() % 1000; // Example validation
        if (array[i].RNTI < 0 || array[i].RNTI > 999) {
            fprintf(stderr, "Invalid RNTI for index %d.\n", i);
            *error_code = -2; // Validation error
            free(array);
            return NULL;
        }

        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256; // Random CRCFLAG
    }

    *error_code = 0; // Success
    return array;
}

// Function to deallocate the memory
void free_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array != NULL) {
        free(array);
    }
}
```

### Key Points:

- **Error Handling**: The function returns an error code via a pointer parameter, allowing the caller to handle errors appropriately.

- **Bounds Checking and Validation**: Each structure is validated before being added to the array. If validation fails, the memory is freed, and an error code is returned.

- **Memory Deallocation**: A separate function `free_crc_indication_pdus` ensures that allocated memory can be properly released when no longer needed.

- **Randomization**: The `CRCFLAG` is set randomly for demonstration purposes, simulating variability in real-world data. 

- **Logging**: Error messages are logged to standard error output to aid debugging and monitoring.']

