['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int field1;
    unsigned int field2;
} MAC_PDU_Header;

typedef struct {
    unsigned char buffer[256];
} BSR_BSRBuffer;

typedef struct {
    unsigned int harq_info;
} DL_HARQ_Information;

typedef struct {
    MAC_PDU_Header pdu_header;
    BSR_BSRBuffer bsr_buffer;
    DL_HARQ_Information dl_harq_information;
} MAC_Transmission_TypeA;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

MAC_Transmission_TypeA* create_transmissions(int num) {
    if (num <= 0) return NULL;

    MAC_Transmission_TypeA* transmissions = malloc(num * sizeof(MAC_Transmission_TypeA));
    if (transmissions == NULL) {
        perror("Failed to allocate memory for transmissions");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    pthread_t threads[num];
    int thread_args[num];

    for (int i = 0; i < num; i++) {
        thread_args[i] = i;
        if (pthread_create(&threads[i], NULL, initialize_transmission, &transmissions[i]) != 0) {
            perror("Failed to create thread");
            free(transmissions);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num; i++) {
        pthread_join(threads[i], NULL);
    }

    return transmissions;
}

void* initialize_transmission(void* arg) {
    MAC_Transmission_TypeA* transmission = (MAC_Transmission_TypeA*)arg;

    pthread_mutex_lock(&mutex);

    // Initialize PDU Header with random values
    transmission->pdu_header.field1 = rand() % 1000;
    transmission->pdu_header.field2 = rand() % 1000;

    // Initialize BSR Buffer with random values
    for (int i = 0; i < sizeof(transmission->bsr_buffer.buffer); i++) {
        transmission->bsr_buffer.buffer[i] = rand() % 256;
    }

    // Initialize DL HARQ Information with a random value
    transmission->dl_harq_information.harq_info = rand() % 100;

    pthread_mutex_unlock(&mutex);

    return NULL;
}

void free_transmissions(MAC_Transmission_TypeA* transmissions) {
    if (transmissions != NULL) {
        free(transmissions);
    }
}
