['Below is a C implementation for a modular encryption and message handling library as described in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <openssl/hmac.h>
#include <time.h>

typedef struct {
    char *payload;
    time_t timestamp;
} message;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_data(long* offsets, int* keys, message** messages, size_t count, size_t payload_length) {
    if (!offsets || !keys || !messages) return -1;

    // Allocate memory
    long *offsets_array = malloc(count * sizeof(long));
    int *keys_array = malloc(count * sizeof(int));
    message *messages_array = malloc(count * sizeof(message));

    if (!offsets_array || !keys_array || !messages_array) {
        free(offsets_array);
        free(keys_array);
        free(messages_array);
        return -1;
    }

    // Initialize arrays
    for (size_t i = 0; i < count; ++i) {
        offsets_array[i] = rand() % 10000;  // Example offset value generation
        keys_array[i] = rand() % 256;       // Example key value generation

        messages_array[i].payload = malloc(payload_length);
        if (!messages_array[i].payload) {
            for (size_t j = 0; j < i; ++j)
                free(messages_array[j].payload);
            free(offsets_array);
            free(keys_array);
            free(messages_array);
            return -1;
        }

        strncpy(messages_array[i].payload, "Predefined String", payload_length);
        messages_array[i].timestamp = time(NULL);

        // Log timestamp
        printf("Message %zu initialized at %ld\n", i, messages_array[i].timestamp);
    }

    // Verify data integrity and set output pointers
    for (size_t i = 0; i < count; ++i) {
        if (strncmp(messages_array[i].payload, "Predefined String", payload_length) != 0 || messages_array[i].timestamp == 0) {
            free(offsets_array);
            free(keys_array);
            for (size_t j = 0; j < count; ++j)
                free(messages_array[j].payload);
            free(messages_array);
            return -1;
        }
    }

    *offsets = offsets_array;
    *keys = keys_array;
    *messages = messages_array;

    return 0;
}

void cleanup_data(long* offsets, int* keys, message** messages, size_t count) {
    if (offsets && *offsets)
        free(*offsets);
    if (keys && *keys)
        free(*keys);
    if (messages && *messages) {
        for (size_t i = 0; i < count; ++i)
            free((*messages)[i].payload);
        free(*messages);
    }
}

// Example usage of OpenSSL encryption/decryption
void example_encrypt_decrypt(const unsigned char* plaintext, int plaintext_len, const unsigned char* key,
                             const unsigned char* iv, unsigned char* ciphertext, unsigned char* decryptedtext) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;

    // Create and initialise the context
    if(!(ctx = EVP_CIPHER_CTX_new())) return;

    // Initialise the encryption operation with AES-256-CBC algorithm
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto cleanup;

    // Provide the message to be encrypted, and obtain the encrypted output.
    if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto cleanup;
    ciphertext_len = len;

    // Finalise the encryption. Further ciphertext bytes may be written at this stage.
    if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) 
        goto cleanup;
    ciphertext_len += len;

    // Clean up
cleanup:
    EVP_CIPHER_CTX_free(ctx);

    // Set up decryption operation
    if(!(ctx = EVP_CIPHER_CTX_new())) return;

    // Initialise the decryption operation with the same key and IV as used for encryption
    if(1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto cleanup_decrypt;

    // Provide the message to be decrypted, and obtain the plaintext output.
    if(1 != EVP_DecryptUpdate(ctx, decryptedtext, &len, ciphertext, ciphertext_len))
        goto cleanup_decrypt;

    // Finalise the decryption
    if(1 != EVP_DecryptFinal_ex(ctx, decryptedtext + len, &len)) 
        goto cleanup_decrypt;

    // Clean up
cleanup_decrypt:
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    message *messages = NULL;

    size_t count = 10;          // Example count
    size_t payload_length = 50; // Example payload length

    if (initialize_data(&offsets, &keys, &messages, count, payload_length) != 0) {
        fprintf(stderr, "Initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Example encryption/decryption usage
    const unsigned char *key = (unsigned char *)"0123456789abcdef0123456789abcdef"; // 32 bytes for AES-256-CBC
    const unsigned char *iv = (unsigned char *)"1234567890abcdef";
    const unsigned char plaintext[] = "This is a test message.";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    example_encrypt_decrypt(plaintext, strlen((char *)plaintext), key, iv, ciphertext, decryptedtext);

    // Cleanup resources
    cleanup_data(&offsets, &keys, &messages, count);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Thread Safety**: The global mutex `lock` is defined but not used in this simplified example. In a real-world application, you would use `pthread_mutex_lock()` and `pthread_mutex_unlock()` around shared resources.
- **Memory Management**: Dynamic memory allocation for offsets, keys, and message payloads with proper cleanup to prevent leaks.
- **Cryptographic Operations**: Example usage of OpenSSL's AES encryption/decryption functions.
- **Logging**: Basic timestamp logging during message initialization.

### Considerations:
- Ensure the OpenSSL library is correctly linked when compiling (`-lssl -lcrypto`).
- This example uses static key and IV for demonstration; in practice, you should securely manage these values.']

