void initialize_data_structures(char *error_buffer, int max_records, int lower_bound, int upper_bound) {
    // Ensure the key size is adjusted to satisfy offset requirements.
    int key_size = max_records;
    if (key_size > 0 && 2 * key_size < max_records) {
        key_size = max_records / 2;
    }

    long *offset_array = malloc(2 * key_size * sizeof(long));
    int *key_array = malloc(key_size * sizeof(int));
    Record *record_array = malloc(max_records * sizeof(Record));

    if (!offset_array || !key_array || !record_array) {
        snprintf(error_buffer, 256, "Memory allocation failed");
        free(offset_array);
        free(key_array);
        free(record_array);
        return;
    }

    // Initialize offset and key arrays
    for (int i = 0; i < 2 * key_size; ++i) {
        offset_array[i] = (long)i;
    }

    for (int i = 0; i < key_size; ++i) {
        key_array[i] = i;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Initialize records with random values within the given bounds
    for (int i = 0; i < max_records; ++i) {
        record_array[i].value = lower_bound + rand() % (upper_bound - lower_bound + 1);
    }

    // Validate conditions
    if ((2 * key_size != sizeof(offset_array) / sizeof(long)) || 
        (key_size != sizeof(key_array) / sizeof(int))) {
        snprintf(error_buffer, 256, "Array size validation failed");
        free(offset_array);
        free(key_array);
        free(record_array);
        return;
    }

    // If everything is successful
    printf("Initialization successful\n");
}

int main() {
    char error_buffer[256];
    Record *records = initialize_data_structures(error_buffer, 1000, 1, 10);

    if (records) {
        // Use the data structures here...
        free(records);
    } else {
        fprintf(stderr, "Error: %s\n", error_buffer);
    }

    return 0;
}
