typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} NFAPIList;

NFAPIList* create_list() {
    NFAPIList* list = malloc(sizeof(NFAPIList));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_rnti_present(NFAPIList* list, int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return 1;
        current = current->next;
    }
    return 0;
}

void add_entry(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (is_rnti_present(list, entry.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(&new_node->data, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list->count == MAX_ENTRIES) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp->data.RX_UE_INFORMATION_TAG);
        free(temp);
        list->count--;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void remove_entry(NFAPIList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL)
        goto unlock;

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->data.RX_UE_INFORMATION_TAG);
    free(current);

    list->count--;

unlock:
    pthread_mutex_unlock(&list->lock);
}

void iterate_and_print(NFAPIList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        printf("%s\n", current->data.RX_UE_INFORMATION_TAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void export_to_binary(NFAPIList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    fwrite(&list->count, sizeof(size_t), 1, file);

    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void import_from_binary(NFAPIList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count && list->count < MAX_ENTRIES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        fread(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        add_entry(list, entry);
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void destroy_list(NFAPIList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp->data.RX_UE_INFORMATION_TAG);
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
