#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_LOG_LEVEL 3

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct HashNode {
    long offset;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

#define HASH_TABLE_SIZE 1024

HashTable* create_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(HASH_TABLE_SIZE, sizeof(HashNode*));
    table->size = HASH_TABLE_SIZE;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned long hash(long offset) {
    return offset % HASH_TABLE_SIZE;
}

int insert_hash_table(HashTable* table, long offset) {
    unsigned long index = hash(offset);
    HashNode* new_node = malloc(sizeof(HashNode));
    if (!new_node) return 0;

    pthread_mutex_lock(&table->lock);
    new_node->offset = offset;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);

    return 1;
}

int check_hash_table(HashTable* table, long offset) {
    unsigned long index = hash(offset);
    HashNode* node = table->buckets[index];

    pthread_mutex_lock(&table->lock);
    while (node) {
        if (node->offset == offset) {
            pthread_mutex_unlock(&table->lock);
            return 1;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);

    return 0;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

void log_message(int level, const char* message) {
    if (level > MAX_LOG_LEVEL) return;

    time_t now = time(NULL);
    printf("[%s] Level %d: %s\n", ctime(&now), level, message);
}

Record* allocate_records(size_t count, double min_value, double max_value, int log_level) {
    HashTable* table = create_hash_table();
    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        log_message(log_level, "Memory allocation failed for records.");
        free_hash_table(table);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        long offset;
        do {
            offset = rand() % 100000 + 1; // Ensure positive and non-zero
        } while (!check_hash_table(table, offset));

        records[i].offset = offset;
        records[i].key = rand();
        records[i].value = min_value + (max_value - min_value) * ((double)rand() / RAND_MAX);

        if (!insert_hash_table(table, offset)) {
            log_message(log_level, "Failed to insert offset into hash table.");
            free(records);
            free_hash_table(table);
            return NULL;
        }
    }

    log_message(log_level, "Records allocated and initialized successfully.");
    free_hash_table(table);
    return records;
}

void free_records(Record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t count = 1000;
    double min_value = 0.0, max_value = 1.0;
    int log_level = 2;

    Record* records = allocate_records(count, min_value, max_value, log_level);

    if (records) {
        // Process records...
        free_records(records);
    }

    return 0;
}
