#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define OFFSET_ARRAY_SIZE 10000

typedef struct {
    long *offset;
    int key;
} record;

typedef struct node {
    record data;
    struct node* prev;
    struct node* next;
} node_t;

// Global variables
node_t sentinel;
int max_key_value = -1;
pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;
long offsets[OFFSET_ARRAY_SIZE];
int initialized_offsets = 0;
#define HASH_TABLE_SIZE 65536

typedef struct hash_entry {
    int key;
    struct hash_entry* next;
} hash_entry_t;

hash_entry_t *hash_table[HASH_TABLE_SIZE];

// Hash function
unsigned int custom_hash(int key) {
    return (key & 0xFFFF) % HASH_TABLE_SIZE; 
}

// Initialize memory pool for offsets
void initialize_memory_pool() {
    pthread_mutex_lock(&memory_pool_lock);
    if (!initialized_offsets) {
        for (int i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
            offsets[i] = 0;
        }
        initialized_offsets = 1;
    }
    pthread_mutex_unlock(&memory_pool_lock);
}

// Initialize hash table
void initialize_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

// Add key to hash table
int add_key_to_hash(int key) {
    unsigned int index = custom_hash(key);

    pthread_mutex_lock(&memory_pool_lock);
    for (hash_entry_t *entry = hash_table[index]; entry != NULL; entry = entry->next) {
        if (entry->key == key) {
            pthread_mutex_unlock(&memory_pool_lock);
            return 0; // Key already exists
        }
    }

    hash_entry_t* new_entry = malloc(sizeof(hash_entry_t));
    new_entry->key = key;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
    pthread_mutex_unlock(&memory_pool_lock);

    return 1; // Key added successfully
}

// Initialize doubly linked list with sentinel node
void initialize_linked_list() {
    sentinel.prev = &sentinel;
    sentinel.next = &sentinel;
}

// Add record to the linked list
void add_record_to_list(node_t *new_node) {
    new_node->prev = sentinel.prev;
    new_node->next = &sentinel;

    sentinel.prev->next = new_node;
    sentinel.prev = new_node;
}

// Free memory pool and other resources
void free_resources(int num_keys) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_entry_t *entry = hash_table[i];
        while (entry != NULL) {
            hash_entry_t *next = entry->next;
            free(entry);
            entry = next;
        }
    }

    node_t* current = sentinel.next;
    while (current != &sentinel) {
        node_t* to_delete = current;
        current = current->next;
        free(to_delete);
    }
}

// Find the record with maximum key value
void find_max_key_value() {
    int local_max = -1;
    node_t* current = sentinel.next;

    while (current != &sentinel) {
        if (current->data.key > local_max) {
            local_max = current->data.key;
        }
        current = current->next;
    }

    pthread_mutex_lock(&memory_pool_lock);
    max_key_value = local_max;
    pthread_mutex_unlock(&memory_pool_lock);
}

// Main function to manage memory for data structures
void manage_memory() {
    initialize_memory_pool();
    initialize_hash_table();
    initialize_linked_list();

    int num_keys = 0;
    int key;

    printf("Enter keys (negative number to stop): ");
    while (scanf("%d", &key) && key >= 0) {
        if (!add_key_to_hash(key)) {
            fprintf(stderr, "Duplicate or invalid key encountered: %d\n", key);
            continue;
        }
        num_keys++;
    }

    if (num_keys == 0) {
        fprintf(stderr, "No valid keys provided.\n");
        return;
    }

    node_t* records = malloc(num_keys * sizeof(node_t));
    int offset_index = 0;

    printf("Re-entering keys to create records: ");
    for (int i = 0; i < num_keys; ++i) {
        scanf("%d", &key);
        if (!add_key_to_hash(key)) {
            fprintf(stderr, "Error re-entering key: %d\n", key);
            continue;
        }

        records[i].data.offset = &offsets[offset_index++];
        records[i].data.key = key;

        add_record_to_list(&records[i]);
    }

    find_max_key_value();
    printf("Maximum key value in records: %d\n", max_key_value);

    free(records);
    free_resources(num_keys);
}

int main() {
    manage_memory();
    return 0;
}
```

This code implements the required functionality using a custom memory pool, hash table for uniqueness checks, and a doubly linked list with a sentinel node. It handles input errors gracefully and ensures thread safety for concurrent access to shared resources.']

