#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_CONFIGS 1024

typedef struct {
    unsigned short port;
    char *hostname;
    char protocol; // 'T' for TCP, 'U' for UDP
} Config;

struct sockaddr_in* initialize_sockets(Config *configs, int config_count) {
    if (config_count > MAX_CONFIGS) {
        config_count = MAX_CONFIGS;
    }

    struct sockaddr_in *sockets = malloc(config_count * sizeof(struct sockaddr_in));
    if (!sockets) {
        perror("Memory allocation failed");
        return NULL;
    }

    int success_count = 0;

    for (int i = 0; i < config_count; ++i) {
        Config *config = &configs[i];

        // Validate port
        if (config->port == 0 || config->port > 65535) {
            fprintf(stderr, "Invalid port number: %hu\n", config->port);
            continue;
        }

        struct addrinfo hints, *res, *p;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET; // IPv4
        hints.ai_socktype = (config->protocol == 'T') ? SOCK_STREAM : SOCK_DGRAM;

        int getaddrinfo_result = getaddrinfo(config->hostname, NULL, &hints, &res);
        if (getaddrinfo_result != 0) {
            fprintf(stderr, "getaddrinfo error for %s: %s\n", config->hostname, gai_strerror(getaddrinfo_result));
            continue;
        }

        int valid_host = 0;
        for (p = res; p != NULL && !valid_host; p = p->ai_next) {
            char *ip_str = inet_ntoa(((struct sockaddr_in *)p->ai_addr)->sin_addr);
            if (ip_str) {
                sockets[success_count].sin_family = AF_INET;
                sockets[success_count].sin_port = htons(config->port);
                memcpy(&sockets[success_count].sin_addr, &((struct sockaddr_in *)p->ai_addr)->sin_addr, sizeof(struct in_addr));
                valid_host = 1;
            }
        }

        freeaddrinfo(res);

        if (valid_host) {
            success_count++;
        } else {
            fprintf(stderr, "Invalid hostname: %s\n", config->hostname);
        }
    }

    return realloc(sockets, success_count * sizeof(struct sockaddr_in));
}
