#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Entry* next;
} Entry;

typedef struct {
    Entry* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPIList;

NFAPIList* create_list() {
    NFAPIList* list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_list(NFAPIList* list) {
    Entry* current = list->head;
    while (current) {
        Entry* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count >= MAX_ENTRIES) return -1;

    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return -1;
    memcpy(&new_entry->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_entry->next = list->head;
    list->head = new_entry;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int update_entry(NFAPIList* list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (current->pdu.RNTI == rnti) {
            memcpy(&current->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return -1; // Not found
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(NFAPIList* list, uint16_t rnti) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (current->pdu.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->pdu;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return NULL; // Not found
}

void log_error(const char* message) {
    time_t now = time(NULL);
    printf("[%s] ERROR: %s\n", ctime(&now), message);
}

// Example garbage collection function
void garbage_collect(NFAPIList* list) {
    if (!list || list->count == 0) return;

    pthread_mutex_lock(&list->lock);
    Entry** current = &list->head;
    while (*current) {
        Entry* entry = *current;
        if (entry->pdu.CRCFLAG == 0) { // Example condition for garbage collection
            *current = entry->next;
            free(entry);
            list->count--;
        } else {
            current = &entry->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    NFAPIList* list = create_list();
    if (!list) {
        log_error("Failed to create list");
        return -1;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {123, 456, 78, rand() % 2};
    add_entry(list, pdu);

    pdu.CRCFLAG = 1; // Update CRCFLAG for demonstration
    update_entry(list, 456, pdu);

    NFAPI_CRC_INDICATION_PDU_T* retrieved = get_entry(list, 456);
    if (retrieved) {
        printf("Retrieved RNTI: %u\n", retrieved->RNTI);
    }

    garbage_collect(list);
    destroy_list(list);

    return 0;
}
