int allocate_and_process(NFAPI_CRC_INDICATION_PDU_T **array, size_t N, size_t batchSize) {
    if (N <= 0) return SUCCESS;

    *array = NULL;
    size_t currentSize = 0;
    int resultCode = SUCCESS;

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < N; ++i) {
        size_t newSize = currentSize + batchSize > N ? N - currentSize : batchSize;

        // Dynamic resizing if necessary
        if (newSize > currentSize) {
            NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);
            if (!temp) {
                fprintf(stderr, "Memory allocation failed\n");
                resultCode = ERROR_ALLOCATION;
                break;
            }
            *array = temp;
        }

        // Populate and validate new structures
        for (size_t j = currentSize; j < currentSize + batchSize && j < N; ++j) {
            (*array)[j].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value, should be valid in real scenario
            (*array)[j].RNTI = rand() % 1000;                  // Example value, should be valid in real scenario
            (*array)[j].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

            // Validate the structure (example validation)
