                fprintf(stderr, "Invalid structure at index %zu\n", j);
                resultCode = ERROR_ALLOCATION;
            }
        }

        currentSize += newSize;
    }
    pthread_mutex_unlock(&lock);

    return resultCode;
}

void deallocate_array(NFAPI_CRC_INDICATION_PDU_T *array) {
