#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define SUCCESS 0
#define ERROR -1

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    size_t block_size;
    size_t pool_size;
    unsigned char *pool_memory;
    pthread_mutex_t lock;
} MemoryPool;

// Global memory pool for demonstration purposes
MemoryPool g_pool;

void log_error(const char* message) {
    // Assume an external logging function is available
    printf("Error: %s\n", message);
}

int init_memory_pool(size_t block_size, size_t pool_size) {
    pthread_mutex_init(&g_pool.lock, NULL);

    if (pthread_mutex_lock(&g_pool.lock)) {
        log_error("Failed to lock memory pool mutex");
        return ERROR;
    }

    g_pool.block_size = block_size;
    g_pool.pool_size = pool_size;

    g_pool.pool_memory = malloc(pool_size);
    if (!g_pool.pool_memory) {
        pthread_mutex_unlock(&g_pool.lock);
        log_error("Memory pool allocation failed");
        return ERROR;
    }

    pthread_mutex_unlock(&g_pool.lock);

    // Initialize the pool as a free list
    unsigned char *current_block = g_pool.pool_memory;
    for (size_t i = 0; i < pool_size - block_size; i += block_size) {
        *(void**)(current_block) = current_block + block_size;
        current_block += block_size;
    }
    *(void**)(current_block) = NULL;

    return SUCCESS;
}

void* allocate_from_pool() {
    if (pthread_mutex_lock(&g_pool.lock)) {
        log_error("Failed to lock memory pool mutex");
        return NULL;
    }

    void *block = g_pool.pool_memory;
    g_pool.pool_memory = *(void**)(block);

    pthread_mutex_unlock(&g_pool.lock);

    return block;
}

void free_to_pool(void* block) {
    if (pthread_mutex_lock(&g_pool.lock)) {
        log_error("Failed to lock memory pool mutex");
        return;
    }

    *(void**)(block) = g_pool.pool_memory;
    g_pool.pool_memory = block;

    pthread_mutex_unlock(&g_pool.lock);
}

int initialize_data_structure(size_t num_offsets, size_t num_keys,
                              record **records, long **offsets, int **keys,
                              FILE *file_handle) {

    if (!file_handle || !records || !offsets || !keys) {
        log_error("Invalid arguments");
        return ERROR;
    }

    srand(time(NULL));

    // Allocate arrays
    offsets = malloc(num_offsets * sizeof(long));
    keys = malloc(num_keys * sizeof(int));
    records = malloc(num_keys * sizeof(record*));

    if (!offsets || !keys || !records) {
        log_error("Array allocation failed");
        return ERROR;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % 1000; // Example offset values
    }

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = rand() % 100; // Random key values

        record *new_record = allocate_from_pool();
        if (!new_record) {
            log_error("Record allocation failed");
            goto cleanup;
        }

        new_record->value = rand() % 50; // Initialize to random value
        records[i] = new_record;
    }

    // Serialize and write to file
    fwrite(offsets, sizeof(long), num_offsets, file_handle);
    fwrite(keys, sizeof(int), num_keys, file_handle);

    for (size_t i = 0; i < num_keys; ++i) {
        fwrite(records[i], sizeof(record), 1, file_handle);
    }

    return SUCCESS;

cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);
    for (size_t i = 0; i < num_keys && records[i]; ++i) {
        free_to_pool(records[i]);
    }
    if (records) free(records);

    return ERROR;
}

void cleanup_memory_pool() {
    pthread_mutex_lock(&g_pool.lock);

    // Free all blocks
    while (g_pool.pool_memory) {
        unsigned char *current_block = g_pool.pool_memory;
        g_pool.pool_memory = *(void**)(current_block);
        free(current_block);
    }

    pthread_mutex_unlock(&g_pool.lock);
    pthread_mutex_destroy(&g_pool.lock);

    if (g_pool.pool_memory) {
        free(g_pool.pool_memory);
    }
}

// Example usage
int main() {
    init_memory_pool(sizeof(record), 1024 * sizeof(record));

    FILE *file_handle = fopen("data.bin", "wb");
    if (!file_handle) {
        log_error("Failed to open file for writing");
        return ERROR;
    }

    long *offsets;
    int *keys;
    record *records;

    if (initialize_data_structure(10, 5, &records, &offsets, &keys, file_handle) != SUCCESS) {
        cleanup_memory_pool();
        fclose(file_handle);
        return ERROR;
    }

    // Clean up
    for (int i = 0; i < 5; ++i) {
        free_to_pool(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    fclose(file_handle);
    cleanup_memory_pool();

    return SUCCESS;
}
