['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_NFAS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int active_RNTIs[MAX_NFAS];
    int size;
} NFADynamicList;

void initialize_list(NFADynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    memset(list->active_RNTIs, 0, sizeof(list->active_RNTIs));
    list->size = 0;
}

int is_active_rnti(NFADynamicList* list, uint16_t rnti) {
    return list->active_RNTIs[rnti] != 0;
}

void register_rnti(NFADynamicList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);
    if (list->size < MAX_NFAS) {
        list->active_RNTIs[rnti] = 1;
    }
    pthread_mutex_unlock(&list->lock);
}

void deregister_rnti(NFADynamicList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);
    if (rnti < MAX_NFAS) {
        list->active_RNTIs[rnti] = 0;
    }
    pthread_mutex_unlock(&list->lock);
}

void insert_pdu(NFADynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (is_active_rnti(list, pdu.RNTI)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = list->head;
        list->head = new_node;

        if (list->size < MAX_NFAS) {
            pdu.CRCFLAG = 1; // Set CRCFLAG as RNTI is active
            list->size++;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_pdu(NFADynamicList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(NFADynamicList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL && current->data.RNTI != rnti) {
        current = current->next;
