        }
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

uint32_t calculate_crc(uint8_t* data, size_t length) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < length; ++i) {
