#define MAX_SOCKETS 1024
#define BUFFER_SIZE 65536
#define THREAD_POOL_SIZE 8

typedef struct {
    int socket_fd;
    struct sockaddr_in addr;
} SocketDescriptor;

typedef struct {
    Packet packet_data; // Assuming a structure for your packet
    unsigned short checksum;
} IncomingPacket;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static SocketDescriptor *sockets[MAX_SOCKETS];
static int active_socket_count = 0;
static volatile int shutdown_flag = 0;

void log_message(const char *message) {
    FILE *log_file = fopen("network_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

unsigned short calculate_checksum(void *data, size_t len) {
    unsigned long sum;
    unsigned short *ptr = data;

    while (len > 1) {
        sum += *ptr++;
        if (sum & 0x80000000)
            sum = (sum & 0xFFFF) + (sum >> 16);
        len -= sizeof(unsigned short);
    }

    if (len > 0)
        sum += *(unsigned char *)ptr;

    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);

    return ~sum;
}

void *handle_packets(void *arg) {
    SocketDescriptor *sd = (SocketDescriptor *) arg;
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    while (!shutdown_flag) {
        ssize_t received_bytes = recvfrom(sd->socket_fd, buffer, BUFFER_SIZE, 0,
                                          (struct sockaddr *)&client_addr, &addr_len);

        if (received_bytes <= 0) {
            continue; // Handle errors appropriately in production code
        }

        IncomingPacket *packet = (IncomingPacket *)buffer;

        // Verify checksum
        unsigned short calculated_checksum = calculate_checksum(packet->packet_data.data,
                                                               packet->packet_data.len);
        if (calculated_checksum != packet->checksum) {
            log_message("Checksum mismatch");
            continue;
        }

        // Process packet based on type
        switch (packet->packet_data.type) {
            case PACKET_TYPE_A:
                process_type_a(packet); // Implement specific processing functions
                break;
            case PACKET_TYPE_B:
                process_type_b(packet);
                break;
            default:
                log_message("Unknown packet type");
                continue;
        }

        log_message("Packet processed successfully");
    }
    return NULL;
}

void initialize_network_interface() {
    int udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345); // Example port
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(udp_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(udp_socket);
        exit(EXIT_FAILURE);
    }

    pthread_t threads[THREAD_POOL_SIZE];
    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        SocketDescriptor *sd = malloc(sizeof(SocketDescriptor));
        if (!sd) {
            perror("Memory allocation failed");
            continue;
        }

        sd->socket_fd = udp_socket;
        pthread_mutex_lock(&mutex);
        sockets[active_socket_count++] = sd;
        pthread_mutex_unlock(&mutex);

        if (pthread_create(&threads[i], NULL, handle_packets, (void *)sd) != 0) {
            perror("Thread creation failed");
            free(sd);
        }
    }

    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    shutdown_flag = 1;
    for (int i = 0; i < active_socket_count; ++i) {
        close(sockets[i]->socket_fd);
        free(sockets[i]);
    }
}
