        static std::mutex idMutex;
        static int sensorCounter = 0;

        std::lock_guard<std::mutex> lock(idMutex);
        return "sensor_" + std::to_string(sensorCounter++);
    }

    double generateRandomTemperature() const {
        static thread_local std::mt19937 localGenerator(std::random_device{}());
        static thread_local std::uniform_real_distribution<> temperatureDistribution(-50.0, 150.0);

        return temperatureDistribution(localGenerator);
    }
};
