// Function to validate bearer context
int validateBearer(BearerContext *bearer) {
    // Implement validation logic
    return bearer->isValid;
}

// Define a UE Context structure
typedef struct UeContext {
    int ueId;
    RrcState rrcState;
    size_t numBearers;
    BearerContext *bearers;
    struct UeContext *next;
} UeContext;

// Define a Dynamic List of UE Contexts
typedef struct {
    UeContext *head;
    pthread_mutex_t lock;
} UeList;

// Initialize the dynamic list
void initializeUeList(UeList *ueList) {
    ueList->head = NULL;
    pthread_mutex_init(&ueList->lock, NULL);
}

// Add a new UE context to the list
int addUeContext(UeList *ueList, int ueId, RrcState rrcState, BearerContext *newBearers, size_t numNewBearers) {
    pthread_mutex_lock(&ueList->lock);

    UeContext *newContext = (UeContext *)malloc(sizeof(UeContext));
    if (!newContext) {
        pthread_mutex_unlock(&ueList->lock);
        return -1;  // Memory allocation failure
    }

    newContext->ueId = ueId;
    newContext->rrcState = rrcState;
    newContext->numBearers = 0;

    for (size_t i = 0; i < numNewBearers; ++i) {
        if (!validateBearer(&newBearers[i])) {
            free(newContext);
            pthread_mutex_unlock(&ueList->lock);
            return -2;  // Invalid bearer
        }
    }

    newContext->bearers = (BearerContext *)malloc(numNewBearers * sizeof(BearerContext));
    if (!newContext->bearers) {
        free(newContext);
        pthread_mutex_unlock(&ueList->lock);
        return -1;  // Memory allocation failure
    }

    memcpy(newContext->bearers, newBearers, numNewBearers * sizeof(BearerContext));
    newContext->numBearers = numNewBearers;
    newContext->next = ueList->head;
    ueList->head = newContext;

    pthread_mutex_unlock(&ueList->lock);
    return 0;  // Success
}

// Remove a UE context from the list
int removeUeContext(UeList *ueList, int ueId) {
    pthread_mutex_lock(&ueList->lock);

    UeContext **current = &ueList->head;
    while (*current) {
        if ((*current)->ueId == ueId) {
            UeContext *toRemove = *current;
            *current = toRemove->next;

            free(toRemove->bearers);
            free(toRemove);
            pthread_mutex_unlock(&ueList->lock);
            return 0;  // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&ueList->lock);
    return -1;  // UE not found
}

// Cleanup the dynamic list
void cleanupUeList(UeList *ueList) {
    pthread_mutex_lock(&ueList->lock);

    UeContext *current = ueList->head;
    while (current) {
        UeContext *toFree = current;
        current = current->next;

        free(toFree->bearers);
        free(toFree);
    }
    ueList->head = NULL;

    pthread_mutex_unlock(&ueList->lock);
    pthread_mutex_destroy(&ueList->lock);
}
