    printf("%s\n", message);
}

int initialize_network_interface() {
    int sockfd;
    struct sockaddr_in server_addr;

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(sockfd);
        return -1;
    }

    log_message("Network interface initialized and bound to port.");
    return sockfd;
}

void *handle_incoming_packets(void *arg) {
    int sockfd = *(int *)arg;
    char buffer[MAX_PACKET_SIZE];
    struct sockaddr_in client_addr;
    socklen_t len = sizeof(client_addr);

    while (1) {
        ssize_t n = recvfrom(sockfd, buffer, MAX_PACKET_SIZE, 0,
                             (struct sockaddr *)&client_addr, &len);
        if (n < 0) {
            perror("recvfrom");
            continue;
        }

        // Verify checksum and process packet
        // Placeholder for actual checksum verification and processing logic

        log_message("Packet received and processed.");
    }
}

void initialize_crc_array_manager(size_t initial_capacity) {
    pthread_mutex_lock(&crc_manager.lock);
    crc_manager.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_manager.array) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&crc_manager.lock);
        return;
    }
    crc_manager.capacity = initial_capacity;
    crc_manager.count = 0;
    for (size_t i = 0; i < initial_capacity; ++i) {
        crc_manager.creation_time[i] = time(NULL);
    }
    pthread_mutex_unlock(&crc_manager.lock);

    log_message("CRC array manager initialized.");
}

void populate_crc_array(uint32_t seed) {
    srand(seed);
    pthread_mutex_lock(&crc_manager.lock);
    for (size_t i = 0; i < crc_manager.capacity && i < 1000000; ++i) {
        crc_manager.array[i].RX_UE_INFORMATION_TAG = rand();
        crc_manager.array[i].RNTI = rand() % 65536;
        crc_manager.array[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF;
        crc_manager.array[i].CRCFLAG = rand() & 1;
    }
    pthread_mutex_unlock(&crc_manager.lock);

    log_message("CRC array populated.");
}

void cleanup_crc_array(time_t age_threshold) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&crc_manager.lock);
    for (size_t i = 0; i < crc_manager.count; ++i) {
        if (current_time - crc_manager.creation_time[i] > age_threshold) {
            // Shift elements to fill the gap
            memmove(&crc_manager.array[i], &crc_manager.array[i + 1],
                    (crc_manager.count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --crc_manager.count;
            crc_manager.creation_time[i] = current_time; // Update time of moved element
        }
    }
    pthread_mutex_unlock(&crc_manager.lock);

    log_message("CRC array cleaned up.");
}

void serialize_crc_array(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&crc_manager.lock);
    fwrite(crc_manager.array, sizeof(NFAPI_CRC_INDICATION_PDU_T), crc_manager.count, file);
    pthread_mutex_unlock(&crc_manager.lock);

    fclose(file);
    log_message("CRC array serialized.");
}

void deserialize_crc_array(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&crc_manager.lock);
    fread(crc_manager.array, sizeof(NFAPI_CRC_INDICATION_PDU_T), crc_manager.capacity, file);
    crc_manager.count = fsize(file); // Implement fsize function to get file size
    pthread_mutex_unlock(&crc_manager.lock);

    fclose(file);
    log_message("CRC array deserialized.");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <seed>\n", argv[0]);
        return EXIT_FAILURE;
    }

    uint32_t seed = strtoul(argv[1], NULL, 10);

    int sockfd = initialize_network_interface();
    if (sockfd < 0) {
        return EXIT_FAILURE;
    }

    pthread_t packet_thread;
    if (pthread_create(&packet_thread, NULL, handle_incoming_packets, &sockfd)) {
        perror("Failed to create packet handling thread");
        close(sockfd);
        return EXIT_FAILURE;
    }

    initialize_crc_array_manager(10000);
    populate_crc_array(seed);

    // Simulate cleanup and serialization
    cleanup_crc_array(60); // 1 minute age threshold
    serialize_crc_array("crc_state.bin");

    pthread_join(packet_thread, NULL);
    close(sockfd);

    free(crc_manager.array);
    return EXIT_SUCCESS;
}
