#define MAX_RECORDS 10000000

typedef struct {
    int key;
    double weight;
    char *resource_name;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t lock;
    size_t buffer_pool_size;
    record buffer_pool[MAX_RECORDS];
} record_collection;

static inline void log_memory_event(const char* event, size_t size) {
    printf("Memory %s: %zu bytes\n", event, size);
}

record_collection* create_record_collection(size_t count) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Requested number of records exceeds maximum limit.\n");
        return NULL;
    }

    record_collection *collection = malloc(sizeof(record_collection));
    if (!collection) {
        perror("Failed to allocate memory for collection metadata");
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);
    collection->count = count;
    collection->buffer_pool_size = (count < MAX_RECORDS) ? count : MAX_RECORDS;

    log_memory_event("allocated", sizeof(record_collection));

    // Initialize buffer pool
    for (size_t i = 0; i < collection->buffer_pool_size; ++i) {
        collection->buffer_pool[i].key = -1;
        collection->buffer_pool[i].weight = 0.0;
        collection->buffer_pool[i].resource_name = NULL;
    }

    // Allocate memory for records if count is less than buffer pool size
    if (count < MAX_RECORDS) {
        collection->records = malloc(count * sizeof(record));
        if (!collection->records) {
            perror("Failed to allocate memory for records");
            free(collection);
            pthread_mutex_destroy(&collection->lock);
            return NULL;
        }
        log_memory_event("allocated", count * sizeof(record));
    } else {
        // Use buffer pool directly when number of records is very large
        collection->records = collection->buffer_pool;
    }

    return collection;
}

void destroy_record_collection(record_collection* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].resource_name);
    }

    if (collection->records != collection->buffer_pool) {
        free(collection->records);
        log_memory_event("deallocated", collection->count * sizeof(record));
    }

    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
    log_memory_event("deallocated", sizeof(record_collection));
}

int initialize_record(record* rec, int key, double weight, const char* resource_name) {
    if (!rec || !resource_name) return -1;

    rec->key = key;
    rec->weight = weight;

    pthread_mutex_lock(&collection->lock);

    size_t len = strlen(resource_name) + 1;
    char *name_copy = malloc(len);
    if (!name_copy) {
        perror("Failed to allocate memory for resource name");
        return -1;
    }

    memcpy(name_copy, resource_name, len);
    rec->resource_name = name_copy;

    pthread_mutex_unlock(&collection->lock);

    log_memory_event("allocated", len);

    return 0;
}

int main() {
    record_collection *collection = create_record_collection(1000000);
    if (!collection) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return EXIT_FAILURE;
    }

    // Example usage
    for (size_t i = 0; i < collection->count; ++i) {
        char name[20];
        snprintf(name, sizeof(name), "Resource_%zu", i);
        if (initialize_record(&collection->records[i], i, i * 1.5, name) != 0) {
            fprintf(stderr, "Failed to initialize record %zu\n", i);
        }
    }

    // Destroy collection
    destroy_record_collection(collection);

    return EXIT_SUCCESS;
}
