typedef struct {
    int log_level;
    char timestamp_format[256];
    char log_destination[256];
} LoggingEntity;

typedef struct {
    int event_id;
    char timestamp[256];
    char message[1024];
    int severity;
} LoggingEvent;

#define MAX_ENTITIES 100
#define MAX_EVENTS 500

LoggingEntity entities[MAX_ENTITIES];
int entity_count = 0;

typedef struct EventNode {
    LoggingEvent data;
    struct EventNode* next;
} EventNode;

typedef struct PriorityQueue {
    EventNode* head;
    pthread_mutex_t lock;
} PriorityQueue;

PriorityQueue queue;

void init_priority_queue(PriorityQueue* pq) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
}

int enqueue_event(PriorityQueue* pq, LoggingEvent event) {
    pthread_mutex_lock(&pq->lock);

    EventNode* newNode = (EventNode*)malloc(sizeof(EventNode));
    if (!newNode) return -1;

    newNode->data = event;
    newNode->next = pq->head;
    pq->head = newNode;

    pthread_mutex_unlock(&pq->lock);
    return 0;
}

LoggingEvent dequeue_event(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);

    if (pq->head == NULL) {
        pthread_mutex_unlock(&pq->lock);
        LoggingEvent empty_event = {0};
        return empty_event;
    }

    EventNode* temp = pq->head;
    LoggingEvent event = temp->data;
    pq->head = pq->head->next;

    free(temp);

    pthread_mutex_unlock(&pq->lock);
    return event;
}

