        if (sscanf(line, "%d %s %255s", &entity.log_level, entity.timestamp_format, entity.log_destination) == 3) {
            if (entity_count < MAX_ENTITIES) {
                entities[entity_count++] = entity;
            }
        }
    }

    fclose(file);
    return 0;
}

