    for (int i = 0; i < entity_count; ++i) {
        if (entities[i].log_level < 1 || entities[i].log_level > 5) {
            fprintf(stderr, "Invalid log level at index %d\n", i);
            return -1;
        }
    }
    return 0;
}

void process_event_stream(PriorityQueue* pq) {
    // Simulated event processing
    for (int i = 0; i < 100; ++i) {
        LoggingEvent event = {i, "timestamp", "message", rand() % 5 + 1};
        enqueue_event(pq, event);
    }
}

void process_events(PriorityQueue* pq) {
    while (1) {
        LoggingEvent event = dequeue_event(pq);
        if (event.event_id == 0) break;

        // Simulate logging logic
        printf("Logging Event ID: %d, Severity: %d\n", event.event_id, event.severity);
    }
}

void cleanup_priority_queue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);

    EventNode* current = pq->head;
    while (current != NULL) {
        EventNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&pq->lock);
    pthread_mutex_destroy(&pq->lock);
}

int main() {
