void init_dynamic_array(DynamicArray* array) {
    pthread_mutex_init(&array->lock, NULL);
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->offsets = malloc(array->capacity * sizeof(long));
    array->keys = malloc(array->capacity * sizeof(int));
    if (!array->offsets || !array->keys) {
        log_memory_usage("Failed to allocate memory for arrays.");
        exit(EXIT_FAILURE);
    }
}

void free_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->offsets);
    free(array->keys);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int add_record(DynamicArray* array, long offset, int key) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        resize_arrays(array);
    }

    array->offsets[array->size] = offset;
    array->keys[array->size] = key;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

void resize_arrays(DynamicArray* array) {
    size_t new_capacity = array->capacity * RESIZE_FACTOR;
    long* new_offsets = realloc(array->offsets, new_capacity * sizeof(long));
    int* new_keys = realloc(array->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        log_memory_usage("Failed to reallocate memory for arrays.");
        exit(EXIT_FAILURE);
    }

    array->capacity = new_capacity;
}

