    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_memory_usage("Failed to open file for serialization.");
        return;
    }

    fwrite(&array->capacity, sizeof(size_t), 1, file);
    fwrite(&array->size, sizeof(size_t), 1, file);
    fwrite(array->offsets, sizeof(long), array->size, file);
    fwrite(array->keys, sizeof(int), array->size, file);

    fclose(file);
    pthread_mutex_unlock(&array->lock);
}

DynamicArray* deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_memory_usage("Failed to open file for deserialization.");
        return NULL;
