    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) {
        fclose(file);
        return NULL;
    }

    fread(&array->capacity, sizeof(size_t), 1, file);
    fread(&array->size, sizeof(size_t), 1, file);

    array->offsets = malloc(array->capacity * sizeof(long));
    array->keys = malloc(array->capacity * sizeof(int));

    if (!array->offsets || !array->keys) {
        free(array->offsets);
