#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <arpa/inet.h> // For inet_ntop
#include <time.h>

typedef struct {
    int socket_fd;
    struct in_addr local_ip;
    struct in_addr remote_ip;
    uint8_t status_flags;  // Example: 0x01 for active, 0x02 for inactive
} TCP_CONNECTION_RECORD_T;

// Define structure to hold connection records and manage concurrency
typedef struct {
    size_t capacity;
    size_t count;
    TCP_CONNECTION_RECORD_T *records;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;  // For conditionally waiting
} ConnectionManager;

// Initialize the connection manager with a given initial capacity
ConnectionManager* init_connection_manager(size_t initial_capacity) {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->records = malloc(sizeof(TCP_CONNECTION_RECORD_T) * initial_capacity);
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    return manager;
}

// Function to add a new connection record
int add_connection(ConnectionManager *manager, TCP_CONNECTION_RECORD_T record) {
    if (!manager || manager->count >= manager->capacity) return -1;

    pthread_mutex_lock(&manager->lock);
    manager->records[manager->count++] = record;
    pthread_cond_signal(&manager->cond_var);  // Signal any waiting threads
    pthread_mutex_unlock(&manager->lock);

    return 0;  // Success
}

// Periodically update connection statuses based on inactivity timeouts
void* status_updater(void *arg) {
    ConnectionManager *manager = (ConnectionManager *)arg;
    while (1) {  // This should be controlled for graceful shutdowns
        pthread_mutex_lock(&manager->lock);

        time_t now = time(NULL);
        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->records[i].status_flags == 0x01 && 
                difftime(now, /* last active timestamp */) > /* inactivity timeout */) {
                manager->records[i].status_flags = 0x02;  // Set to inactive
            }
        }

        pthread_cond_broadcast(&manager->cond_var);  // Notify other threads of changes
        pthread_mutex_unlock(&manager->lock);

        sleep(5);  // Adjust interval as needed
    }
    return NULL;
}

// Clean up resources when shutting down the manager
void cleanup_connection_manager(ConnectionManager *manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        pthread_cond_destroy(&manager->cond_var);
        free(manager);
    }
}

// Example usage: Create and start a thread to manage status updates
int main() {
    ConnectionManager *conn_mgr = init_connection_manager(100);

    if (!conn_mgr) return EXIT_FAILURE;

    // Start background thread for updating statuses
    pthread_t updater_thread;
    pthread_create(&updater_thread, NULL, status_updater, conn_mgr);

    // Simulate adding connections and other operations here

    // Join threads and cleanup (normally part of graceful shutdown)
    pthread_join(updater_thread, NULL);
    cleanup_connection_manager(conn_mgr);

    return EXIT_SUCCESS;
}
```

This code provides a basic framework for managing TCP connection records in a thread-safe manner. It includes initialization, addition of new connections, status updates based on activity timeouts, and resource cleanup. Adjustments may be necessary to fit specific use cases or integrate with additional monitoring and logging tools.']

