// Define the structure for MAC header and payload
typedef struct {
    unsigned char dest_mac[6];
    unsigned char src_mac[6];
} MAC_HEADER;

typedef struct {
    char data[1500]; // Typical maximum Ethernet frame size
} MAC_PAYLOAD;

// Define the structure for MAC frames with a timestamp
typedef struct MAC_FRAME {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    time_t timestamp;
    struct MAC_FRAME *next;
} MAC_FRAME;

// Function to create a new MAC_FRAME
MAC_FRAME* create_mac_frame(unsigned char dest_mac[6], unsigned char src_mac[6]) {
    MAC_FRAME *new_frame = (MAC_FRAME *)malloc(sizeof(MAC_FRAME));
    if (!new_frame) return NULL;

    memcpy(new_frame->header.dest_mac, dest_mac, 6);
    memcpy(new_frame->header.src_mac, src_mac, 6);
    new_frame->timestamp = time(NULL); // Set current timestamp
    new_frame->next = NULL;

    return new_frame;
}

// Function to detect if a frame is duplicate based on MAC addresses
int is_duplicate(MAC_FRAME *head, unsigned char dest_mac[6], unsigned char src_mac[6]) {
    MAC_FRAME *current = head;
    while (current) {
        if (memcmp(current->header.dest_mac, dest_mac, 6) == 0 &&
            memcmp(current->header.src_mac, src_mac, 6) == 0) {
            return 1; // Duplicate found
        }
        current = current->next;
    }
    return 0; // No duplicate
}

// Function to add a frame to the linked list if it's not a duplicate
int add_frame(MAC_FRAME **head, unsigned char dest_mac[6], unsigned char src_mac[6]) {
    if (is_duplicate(*head, dest_mac, src_mac)) {
        return 0; // Frame is duplicate, do not add
    }

    MAC_FRAME *new_frame = create_mac_frame(dest_mac, src_mac);
    if (!new_frame) {
        perror("Failed to allocate memory for new frame");
        return -1;
    }

    // Insert the new frame at the beginning of the list
    new_frame->next = *head;
    *head = new_frame;

    return 1; // Frame added successfully
}

// Function to free all frames in the linked list
void free_frames(MAC_FRAME **head) {
    MAC_FRAME *current = *head;
    while (current) {
        MAC_FRAME *temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

