#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <time.h>

#define MAX_CONNECTIONS 1024
#define INACTIVITY_TIMEOUT 300 // seconds

typedef struct {
    int socket_fd;
    struct sockaddr_in local_addr;
    struct sockaddr_in remote_addr;
    uint8_t connection_status; // e.g., CONNECTED, DISCONNECTED
    time_t last_activity;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int connection_limit;
    FILE *log_file;
    // External monitoring service handle, if applicable
} ConnectionManager;

ConnectionManager* create_connection_manager(size_t initial_capacity, int limit) {
    ConnectionManager *manager = (ConnectionManager *)malloc(sizeof(ConnectionManager));
    manager->connections = (TCP_CONNECTION_RECORD_T *)calloc(initial_capacity, sizeof(TCP_CONNECTION_RECORD_T));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
    manager->connection_limit = limit;
    manager->log_file = fopen("connections.log", "a+");
    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            close(manager->connections[i].socket_fd);
        }
        free(manager->connections);
        pthread_mutex_destroy(&manager->lock);
        pthread_cond_destroy(&manager->cond_var);
        fclose(manager->log_file);
        free(manager);
    }
}

int add_connection(ConnectionManager *manager, int socket_fd, struct sockaddr_in local_addr, struct sockaddr_in remote_addr) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->connection_limit) {
        fprintf(manager->log_file, "Connection limit reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].socket_fd == socket_fd) {
            pthread_mutex_unlock(&manager->lock);
            fprintf(manager->log_file, "Socket already exists.\n");
            return -1;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TCP_CONNECTION_RECORD_T *new_connections = (TCP_CONNECTION_RECORD_T *)realloc(manager->connections, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            fprintf(manager->log_file, "Memory allocation failed.\n");
            return -1;
        }
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    TCP_CONNECTION_RECORD_T *conn = &manager->connections[manager->count++];
    conn->socket_fd = socket_fd;
    memcpy(&conn->local_addr, &local_addr, sizeof(struct sockaddr_in));
    memcpy(&conn->remote_addr, &remote_addr, sizeof(struct sockaddr_in));
    conn->connection_status = 1; // CONNECTED
    conn->last_activity = time(NULL);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_connection(ConnectionManager *manager, int socket_fd) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].socket_fd == socket_fd) {
            close(manager->connections[i].socket_fd);
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->count - i - 1) * sizeof(TCP_CONNECTION_RECORD_T));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    fprintf(manager->log_file, "Socket not found.\n");
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

TCP_CONNECTION_RECORD_T* find_connection(ConnectionManager *manager, int socket_fd) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i].socket_fd == socket_fd) {
            TCP_CONNECTION_RECORD_T *conn = &manager->connections[i];
            pthread_mutex_unlock(&manager->lock);
            return conn;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void update_connection_status(ConnectionManager *manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(now, manager->connections[i].last_activity) > INACTIVITY_TIMEOUT) {
            manager->connections[i].connection_status = 0; // DISCONNECTED
            close(manager->connections[i].socket_fd);
            memmove(&manager->connections[i], &manager->connections[i + 1], (manager->count - i - 1) * sizeof(TCP_CONNECTION_RECORD_T));
            --manager->count;
            i--; // Adjust index due to removal
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void* monitor_connections(void *arg) {
    ConnectionManager *manager = (ConnectionManager *)arg;

    while (1) {
        update_connection_status(manager);

        // Integrate with external monitoring service if needed

        sleep(60); // Run every minute
    }

    return NULL;
}
