#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 10000

typedef struct {
    long offset;
    int key;
    int value;
} record;

void manage_memory(int initial_size) {
    if (initial_size < 1 || initial_size > 1000) {
        fprintf(stderr, "Initial size must be between 1 and 1000.\n");
        return;
    }

    size_t offset_array_size = initial_size;
    size_t key_array_size = initial_size;

    long *offsets = malloc(offset_array_size * sizeof(long));
    int *keys = malloc(key_array_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Initial allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Seed for reproducibility
    srand(time(NULL));

    size_t current_offset_count = 0;
    size_t current_key_count = 0;

    while (current_offset_count < MAX_SIZE && current_key_count < MAX_SIZE) {
        // Example logic to decide when to add new elements
        if ((rand() % 10) == 0) { // Simulate demand for growth
            if (current_offset_count < offset_array_size) {
                offsets[current_offset_count++] = rand();
            } else if (offset_array_size < MAX_SIZE) {
                long *new_offsets = realloc(offsets, (offset_array_size + initial_size) * sizeof(long));
                if (!new_offsets) break;
                offsets = new_offsets;
                offset_array_size += initial_size;
                offsets[current_offset_count++] = rand();
            }

            if (current_key_count < key_array_size) {
                keys[current_key_count++] = rand() % 1000; // Example value
            } else if (key_array_size < MAX_SIZE) {
                int *new_keys = realloc(keys, (key_array_size + initial_size) * sizeof(int));
                if (!new_keys) break;
                keys = new_keys;
                key_array_size += initial_size;
                keys[current_key_count++] = rand() % 1000; // Example value
            }
        }
    }

    size_t record_count = current_offset_count * current_key_count;

    record *records = malloc(record_count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    for (size_t i = 0; i < record_count; ++i) {
        size_t offset_idx = i / current_key_count;
        size_t key_idx = i % current_key_count;

        records[i].offset = offsets[offset_idx];
        records[i].key = keys[key_idx];
        records[i].value = rand() % 2001 - 1000; // Random value between -1000 and 1000
    }

    // Example of processing records (e.g., printing them)
    for (size_t i = 0; i < record_count; ++i) {
        printf("Offset: %ld, Key: %d, Value: %d\n", records[i].offset, records[i].key, records[i].value);
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manage_memory(100); // Example initial size
    return 0;
}
