    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        HTTP_REQUEST_T **new_requests = (HTTP_REQUEST_T **)realloc(array->requests, new_capacity * sizeof(HTTP_REQUEST_T *));
        if (!new_requests) {
            pthread_mutex_unlock(&array->lock);
            return; // Handle memory allocation failure
        }
        array->requests = new_requests;
        array->capacity = new_capacity;
    }

    validate_request(request);
    array->requests[array->count++] = request;

    pthread_cond_signal(&array->cond);
    pthread_mutex_unlock(&array->lock);
}

HTTP_REQUEST_T *get_next_request(RequestArray *array) {
    pthread_mutex_lock(&array->lock);

    while (array->count == 0) {
        pthread_cond_wait(&array->cond, &array->lock);
    }

    HTTP_REQUEST_T *request = array->requests[0];
    memmove(array->requests, array->requests + 1, (--array->count) * sizeof(HTTP_REQUEST_T *));
    pthread_mutex_unlock(&array->lock);

    return request;
}

void* handle_requests(void *arg) {
    RequestArray *array = (RequestArray *)arg;

    while (1) {
        HTTP_REQUEST_T *request = get_next_request(array);
        if (!request) continue; // Handle termination condition

        // Process the request
        // Integrate with caching services, load balancers, etc.

        // Respond to the request
        free(request->url);
        for (size_t i = 0; i < request->num_headers; ++i) {
            free(request->request_headers[i]);
        }
        free(request->request_headers);
        free(request->body_content);
        free(request);

        // Log and monitor processing details
    }

    return NULL;
}

void start_request_handling(RequestArray *array, int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, handle_requests, array);
    }
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void periodic_schema_update(RequestArray *array) {
    while (1) {
        // Wait for a predefined interval
        sleep(60);

        pthread_mutex_lock(&array->lock);

        // Update schemas and validate all requests if necessary

        pthread_mutex_unlock(&array->lock);
    }
}
