// Node of linked list to store integers
typedef struct ListNode {
    int data;
    struct ListNode* next;
} ListNode;

// Function declarations
ListNode* readIntegers();
void freeList(ListNode* head);
int findLargestInteger(ListNode* head);
void generateNFAPI_CRC_INDICATION_PDUs(int count);
int isValidLTEData(int tag, int rnti);

// Mutex for thread-safe shared resource access
pthread_mutex_t lock;

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int numberOfStructures = atoi(argv[1]);

    // Initialize the mutex
    pthread_mutex_init(&lock, NULL);

    // Read integers into a linked list and find the largest one
    ListNode* head = readIntegers();
    if (head) {
        printf("Largest integer: %d\n", findLargestInteger(head));
        freeList(head);
    }

    // Generate CRC indication PDUs
    generateNFAPI_CRC_INDICATION_PDUs(numberOfStructures);

    // Destroy the mutex
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}

// Reads integers from standard input and stores them in a linked list
ListNode* readIntegers() {
    ListNode* head = NULL, *tail = NULL;
    int num;

    while (scanf("%d", &num) == 1) {
        // Check for invalid input
        if (num < -2147483648 || num > 2147483647) {
            fprintf(stderr, "Invalid integer: %d\n", num);
            continue;
        }

        ListNode* newNode = malloc(sizeof(ListNode));
        if (!newNode) {
            perror("Failed to allocate memory");
            freeList(head);
            return NULL;
        }

        newNode->data = num;
        newNode->next = NULL;

        if (tail) {
            tail->next = newNode;
        } else {
            head = newNode;
        }

        tail = newNode;
    }

    return head;
}

// Frees the memory allocated for a linked list
void freeList(ListNode* head) {
    ListNode *current, *temp;
    current = head;

    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
}

// Finds and returns the largest integer in the linked list
int findLargestInteger(ListNode* head) {
    if (!head) return INT_MIN;

    int maxVal = head->data;
    ListNode* node = head->next;

    while (node) {
        if (node->data > maxVal)
            maxVal = node->data;
        node = node->next;
    }

    return maxVal;
}

// Generates NFAPI_CRC_INDICATION_PDU_T structures with realistic LTE data
void generateNFAPI_CRC_INDICATION_PDUs(int count) {
    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate valid random values within typical ranges
        do {
            pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
            pdu.RNTI = rand() % 1048576;
        } while (!isValidLTEData(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI));

        // Set CRCFLAG based on a predefined probability (e.g., 50%)
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 100 < 50) ? 1 : 0;

        pthread_mutex_lock(&lock);
        printf("Generated PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
        pthread_mutex_unlock(&lock);
    }
}

// Validates the LTE data fields
int isValidLTEData(int tag, int rnti) {
    // Replace these ranges with realistic ones for your scenario
    return (tag >= 0 && tag < 10000) && (rnti > 0 && rnti <= 1048576);
}
