#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_SESSIONS 1000
#define MAX_QOS_FLOWS_PER_UE 10

typedef struct {
    int dataRate; // Data rate in kbps
} QosFlow;

typedef struct {
    int ueId;
    int totalGrants;
    int maxGrantsPerUe;
    QosFlow qosFlows[MAX_QOS_FLOWS_PER_UE];
    int qosFlowCount;
    float bandwidthThreshold; // Total data rate threshold in Mbps
} UeSessionData;

typedef struct {
    UeSessionData sessions[MAX_UE_SESSIONS];
    int sessionCount;
} SessionManager;

// Function to initialize and populate UeSessionData
void initializeSessions(SessionManager *manager, int initialUeCount) {
    manager->sessionCount = 0;

    for (int i = 0; i < initialUeCount && manager->sessionCount < MAX_UE_SESSIONS; ++i) {
        UeSessionData session;
        session.ueId = i + 1;
        session.totalGrants = 0;
        session.maxGrantsPerUe = 5; // Example limit
        session.qosFlowCount = 0;
        session.bandwidthThreshold = 10.0f; // Example threshold in Mbps

        manager->sessions[manager->sessionCount++] = session;
    }
}

// Function to add a grant request for a specific UE
int addGrantRequest(SessionManager *manager, int ueId) {
    if (ueId <= 0 || ueId > MAX_UE_SESSIONS) return -1;

    UeSessionData *session = &manager->sessions[ueId - 1];
    if (session->totalGrants >= session->maxGrantsPerUe) return -2;

    session->totalGrants++;
    return 0;
}

// Function to add a QoS flow with data rate for a specific UE
int addQosFlow(SessionManager *manager, int ueId, int dataRateKbps) {
    if (ueId <= 0 || ueId > MAX_UE_SESSIONS) return -1;

    UeSessionData *session = &manager->sessions[ueId - 1];
    if (session->qosFlowCount >= MAX_QOS_FLOWS_PER_UE) return -2;

    int totalKbps = session->bandwidthThreshold * 1000;
    for (int i = 0; i < session->qosFlowCount; ++i) {
        totalKbps -= session->qosFlows[i].dataRate;
    }

    if (totalKbps < dataRateKbps) return -3;

    session->qosFlows[session->qosFlowCount++].dataRate = dataRateKbps;
    return 0;
}

// Function to update QoS flow data rate
int updateQosFlowDataRate(SessionManager *manager, int ueId, int qosIndex, int newDataRateKbps) {
    if (ueId <= 0 || ueId > MAX_UE_SESSIONS || qosIndex < 0 || qosIndex >= MAX_QOS_FLOWS_PER_UE) return -1;

    UeSessionData *session = &manager->sessions[ueId - 1];
    int totalKbps = session->bandwidthThreshold * 1000;
    for (int i = 0; i < session->qosFlowCount; ++i) {
        if (i != qosIndex) {
            totalKbps -= session->qosFlows[i].dataRate;
        }
    }

    if (totalKbps < newDataRateKbps) return -2;

    session->qosFlows[qosIndex].dataRate = newDataRateKbps;
    return 0;
}

// Function to remove a grant request for a specific UE
int removeGrantRequest(SessionManager *manager, int ueId) {
    if (ueId <= 0 || ueId > MAX_UE_SESSIONS) return -1;

    UeSessionData *session = &manager->sessions[ueId - 1];
    if (session->totalGrants == 0) return -2;

    session->totalGrants--;
    return 0;
}

// Function to remove a QoS flow for a specific UE
int removeQosFlow(SessionManager *manager, int ueId, int qosIndex) {
    if (ueId <= 0 || ueId > MAX_UE_SESSIONS || qosIndex < 0 || qosIndex >= MAX_QOS_FLOWS_PER_UE) return -1;

    UeSessionData *session = &manager->sessions[ueId - 1];
    if (qosIndex >= session->qosFlowCount) return -2;

    for (int i = qosIndex; i < session->qosFlowCount - 1; ++i) {
        session->qosFlows[i] = session->qosFlows[i + 1];
    }

    session->qosFlowCount--;
    return 0;
}

// Example usage
int main() {
    SessionManager manager;
    initializeSessions(&manager, 10);

    addGrantRequest(&manager, 1);
    addQosFlow(&manager, 1, 500); // Add 500 kbps flow

    updateQosFlowDataRate(&manager, 1, 0, 1000); // Update to 1000 kbps
    removeGrantRequest(&manager, 1);
    removeQosFlow(&manager, 1, 0);

    return 0;
}
