typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_list(unsigned int max_size, unsigned int *actual_size) {
    NFAPI_CRC_INDICATION_PDU_T *crc_list = NULL;
    unsigned long input_value, i, j;
    unsigned int count = 0;
    unsigned int duplicate_check = 0;

    if (max_size == 0 || actual_size == NULL) return NULL;

    crc_list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list) {
        log_error("Memory allocation failed for CRC list.");
        return NULL;
    }

    while ((fscanf(stdin, "%lu", &input_value) == 1) && (count < max_size)) {
        // Check for integer overflow when checking for duplicates
        for (i = 0; i < count; i++) {
            if (count > ULONG_MAX - input_value) {
                log_error("Integer overflow detected while comparing inputs.");
                free(crc_list);
                return NULL;
            }

            if ((unsigned int)(crc_list[i].RX_UE_INFORMATION_TAG ^ crc_list[i].RNTI ^ input_value) == 0) {
                duplicate_check = 1;
                break;
            }
        }

        if (!duplicate_check) {
            crc_list[count].RX_UE_INFORMATION_TAG = (input_value >> 16) & 0xFFFF; // Extract high bits
            crc_list[count].RNTI = input_value & 0xFFFF;                         // Extract low bits

            crc_list[count].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag: 0 or 1

            count++;
        }
    }

    *actual_size = count;
    return crc_list;
}

int main() {
    unsigned int max_size = 10000; // This can be read from a config file/environment variable
    unsigned int actual_size = 0;

    NFAPI_CRC_INDICATION_PDU_T* list = allocate_crc_list(max_size, &actual_size);

    if (list) {
        printf("List allocated with %u entries.\n", actual_size);

        // Free the memory after use
        free(list);
    }

    return 0;
}
