```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_UES 100
#define HASH_FUNCTION_DEFAULT "sha256"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_TAGS;

typedef struct {
    UE_TAGS ue_tags;
    float SNR_INDICATION_REL8_TAG;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    UE_TAGS ue_tags;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void initialize_pdu_arrays(NFAPI_MESSAGE_PDU_T* pdu_array, NFAPI_CRC_INDICATION_PDU_T* crc_pdu_array, size_t num_ues);
float calculate_snr();
void log_performance_metrics(float snr_time, int memory_allocations);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// PHP code integration
char *php_generate_random_string(size_t length, const char *charset) {
    static char buffer[256];
    snprintf(buffer, sizeof(buffer), "php -r 'echo bin2hex(random_bytes(%zu));'", length);
    FILE *fp = popen(buffer, "r");
    if (fp == NULL) return NULL;
    char result[length*2+1];
    fread(result, 1, length*2, fp);
    pclose(fp);
    size_t len = strlen(result);
    buffer[len/2] = '\0'; // Convert hex to ASCII
    for (size_t i = 0; i < len/2; ++i) {
        buffer[i] = charset[(unsigned char)strtol(result + 2*i, NULL, 16)];
    }
    return strdup(buffer);
}

char *php_hash_password(const char *password) {
    static char command[256];
    snprintf(command, sizeof(command), "php -r 'echo hash(\"%s\", \"%s\");'", HASH_FUNCTION_DEFAULT, password);
    FILE *fp = popen(command, "r");
    if (fp == NULL) return NULL;
    char buffer[64];
    fread(buffer, 1, sizeof(buffer)-1, fp);
    pclose(fp);
    return strdup(buffer);
}

void initialize_pdu_arrays(NFAPI_MESSAGE_PDU_T* pdu_array, NFAPI_CRC_INDICATION_PDU_T* crc_pdu_array, size_t num_ues) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_ues && i < MAX_UES; ++i) {
        pdu_array[i].ue_tags.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu_array[i].ue_tags.RNTI = rand() % 65536;

        crc_pdu_array[i].ue_tags.RX_UE_INFORMATION_TAG = pdu_array[i].ue_tags.RX_UE_INFORMATION_TAG;
        crc_pdu_array[i].ue_tags.RNTI = pdu_array[i].ue_tags.RNTI;

        // Simulate SNR calculation
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        pdu_array[i].SNR_INDICATION_REL8_TAG = calculate_snr();
        clock_gettime(CLOCK_MONOTONIC, &end);

        float snr_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        log_performance_metrics(snr_time, num_ues);

        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        crc_pdu_array[i].CRC_INDICATION_REL8_TAG = pdu_array[i].CRC_INDICATION_REL8_TAG;
    }

    pthread_mutex_unlock(&mutex);
}

float calculate_snr() {
    // Simulate an adaptive radio channel model with stochastic noise
    return (rand() % 100) / 10.0 + ((float) rand() / RAND_MAX - 0.5) * 2; // Example SNR value
}

void log_performance_metrics(float snr_time, int memory_allocations) {
    printf("SNR calculation time: %.6f seconds\n", snr_time);
    printf("Memory allocations during initialization: %d\n", memory_allocations);
}

int main() {
    srand(time(NULL));

    NFAPI_MESSAGE_PDU_T pdu_array[MAX_UES];
    NFAPI_CRC_INDICATION_PDU_T crc_pdu_array[MAX_UES];

    initialize_pdu_arrays(pdu_array, crc_pdu_array, MAX_UES);

    // PHP integration example
    char *random_string = php_generate_random_string(10, "abcdefghijklmnopqrstuvwxyz");
    printf("Random String: %s\n", random_string);
    free(random_string);

    char *hashed_password = php_hash_password("password123");
    printf("Hashed Password: %s\n", hashed_password);
    free(hashed_password);

    return 0;
}
```

### Design Choices:
- **Thread Safety**: Used `pthread_mutex_t` to ensure thread-safe updates to shared resources.
- **Performance Optimization**: Minimized memory allocations by using fixed-size arrays and avoiding unnecessary data copying.
- **PHP Integration**: Utilized PHP for generating random strings and hashing passwords, providing flexibility in handling these tasks.
