import pthread.h
import time.h

#define MAX_UE 100

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    float SNR_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_MESSAGE_PDU_T *message_pdu_array[MAX_UE];
    NFAPI_CRC_INDICATION_PDU_T *crc_pdu_list[MAX_UE];
    pthread_mutex_t lock;
    unsigned int message_count;
} RadioEnvironment;

float calculate_snr(unsigned int ue_index, float noise_level) {
    // Simulate SNR calculation based on a stochastic model
    return 10.0f + (float)(ue_index % 5) - noise_level;
}

void log_performance_metrics(RadioEnvironment *env, const char *message, double duration) {
    printf("Performance Log: %s took %.6f seconds\n", message, duration);
}

RadioEnvironment* initialize_radio_environment(unsigned int ue_count) {
    RadioEnvironment *env = malloc(sizeof(RadioEnvironment));
    if (!env) return NULL;

    pthread_mutex_init(&env->lock, NULL);
    env->message_count = 0;

    for (unsigned int i = 0; i < ue_count && i < MAX_UE; ++i) {
        NFAPI_MESSAGE_PDU_T *msg_pdu = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
        if (!msg_pdu) {
            perror("Failed to allocate memory for message PDU");
            return NULL;
        }

        env->message_pdu_array[i] = msg_pdu;

        float noise_level = (float)(rand() % 100) / 10.0f; // Random noise level
        double start_time = clock();

        msg_pdu->RX_UE_INFORMATION_TAG = i + 1;
        msg_pdu->RNTI = 1000 + i;
        msg_pdu->SNR_INDICATION_REL8_TAG = calculate_snr(i, noise_level);

        double end_time = clock();
        log_performance_metrics(env, "Calculate SNR", (end_time - start_time) / CLOCKS_PER_SEC);

        NFAPI_CRC_INDICATION_PDU_T *crc_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_pdu) {
            perror("Failed to allocate memory for CRC PDU");
            free(msg_pdu);
            return NULL;
        }

        env->crc_pdu_list[i] = crc_pdu;

        crc_pdu->RX_UE_INFORMATION_TAG = i + 1;
        crc_pdu->RNTI = 1000 + i;
        crc_pdu->CRC_INDICATION_REL8_TAG = (i % 2 == 0) ? 101 : 102;
    }

    return env;
}

void cleanup_radio_environment(RadioEnvironment *env) {
    if (!env) return;

    pthread_mutex_lock(&env->lock);
    for (unsigned int i = 0; i < MAX_UE && env->message_pdu_array[i]; ++i) {
        free(env->message_pdu_array[i]);
        free(env->crc_pdu_list[i]);
    }
    pthread_mutex_unlock(&env->lock);

    pthread_mutex_destroy(&env->lock);
    free(env);
}

void update_snr_values(RadioEnvironment *env, float noise_level) {
    if (!env) return;

    pthread_mutex_lock(&env->lock);
    for (unsigned int i = 0; i < MAX_UE && env->message_pdu_array[i]; ++i) {
        double start_time = clock();

        env->message_pdu_array[i]->SNR_INDICATION_REL8_TAG = calculate_snr(i, noise_level);

        double end_time = clock();
        log_performance_metrics(env, "Update SNR", (end_time - start_time) / CLOCKS_PER_SEC);
    }
    pthread_mutex_unlock(&env->lock);
}

int main() {
    RadioEnvironment *radio_env = initialize_radio_environment(50);
    if (!radio_env) {
        fprintf(stderr, "Failed to initialize radio environment\n");
        return EXIT_FAILURE;
    }

    float noise_level = 2.5f; // Example of a changing noise level
    update_snr_values(radio_env, noise_level);

    cleanup_radio_environment(radio_env);
    return EXIT_SUCCESS;
}
