    // Mutex for thread safety
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Lock the mutex to ensure thread-safe memory allocation
    pthread_mutex_lock(&lock);

    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;
    size_t record_count = num_records;

    // Fallback threshold for performance degradation
    const size_t fallback_threshold = 1000; 

    if (record_count > fallback_threshold) {
        fprintf(stderr, "Reducing number of records to %zu due to high allocation request.\n", fallback_threshold);
        record_count = fallback_threshold;
    }

    // Allocate memory with error checking
    offsets = (long*) calloc(record_count, sizeof(long));
    keys = (int*) malloc(record_count * sizeof(int));
    records = (Record*) malloc(record_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");

        // Free already allocated memory
        free(offsets);
        free(keys);
        free(records);

        pthread_mutex_unlock(&lock);  // Unlock before returning NULL
        return NULL;
    }

    // Set max buffer length based on configuration or default value
    size_t actual_max_len = (max_buffer_length == 0) ? default_max_len : max_buffer_length;

    for (size_t i = 0; i < record_count; ++i) {
        offsets[i] = rand() % 1000000L;
        keys[i] = rand_value_min + rand() % ((rand_value_max - rand_value_min) + 1);

        records[i].buffer = (char*) malloc(actual_max_len * sizeof(char));
