            fprintf(stderr, "Memory allocation for buffer failed at index %zu.\n", i);

            // Free already allocated resources on failure
            free(offsets);
            free(keys);
            while(i > 0) { 
                free(records[--i].buffer);  // Ensure all buffers are freed before returning
            }
            free(records);

            pthread_mutex_unlock(&lock);
            return NULL;
        }

        memset(records[i].buffer, '\0', actual_max_len);  // Initialize buffer to zero
        records[i].value = keys[i];
    }

    // Log successful allocation and initialization
    printf("Arrays allocated and initialized successfully for %zu records.\n", record_count);

    pthread_mutex_unlock(&lock);  // Unlock after operation completion

    return (void*) malloc(sizeof(long*) * 3 + sizeof(int*) + sizeof(Record*) +
                         sizeof(offsets) + sizeof(keys) + sizeof(records));
}

