typedef struct {
    // Placeholder structure for UE context information
    int ueId;
} UEContext;

typedef struct {
    // Placeholder structure for RRC connection information
    int rrcState;
} RRCConnectionInfo;

typedef struct {
    UEContext* ueContext;
    RRCConnectionInfo* rrcConnection;
    char* downlinkBuffer;
} SessionState;

typedef struct {
    SessionState** sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} SessionManager;

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = (SessionState**)calloc(initial_capacity, sizeof(SessionState*));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

int add_session(SessionManager* manager, int ueId, int rrcState, size_t buffer_size) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->mutex);

    // Reallocate memory if capacity is reached
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        SessionState** new_sessions = (SessionState**)realloc(manager->sessions, new_capacity * sizeof(SessionState*));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    SessionState* session = (SessionState*)malloc(sizeof(SessionState));
    if (!session) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Memory allocation failed
    }

    session->ueContext = (UEContext*)malloc(sizeof(UEContext));
    session->rrcConnection = (RRCConnectionInfo*)malloc(sizeof(RRCConnectionInfo));
    session->downlinkBuffer = (char*)calloc(buffer_size, sizeof(char));

    if (!session->ueContext || !session->rrcConnection || !session->downlinkBuffer) {
        free(session->downlinkBuffer);
        free(session->rrcConnection);
        free(session->ueContext);
        free(session);
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Memory allocation failed
    }

    session->ueContext->ueId = ueId;
    session->rrcConnection->rrcState = rrcState;

    manager->sessions[manager->count++] = session;

    pthread_mutex_unlock(&manager->mutex);

    return 0; // Success
}

void remove_session(SessionManager* manager, int index) {
    if (!manager || index < 0 || index >= manager->count) return;

    pthread_mutex_lock(&manager->mutex);

    SessionState* session = manager->sessions[index];
    if (session) {
        free(session->downlinkBuffer);
        free(session->rrcConnection);
        free(session->ueContext);
        free(session);

        // Shift the sessions
        memmove(&manager->sessions[index], &manager->sessions[index + 1],
                (manager->count - index - 1) * sizeof(SessionState*));
        manager->count--;
    }

    pthread_mutex_unlock(&manager->mutex);
}

void destroy_session_manager(SessionManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]->downlinkBuffer);
        free(manager->sessions[i]->rrcConnection);
        free(manager->sessions[i]->ueContext);
        free(manager->sessions[i]);
    }

    free(manager->sessions);

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
