    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned int crcflag_threshold; // Configurable threshold
} DynamicList;

// Initialize the dynamic list
void init_dynamic_list(DynamicList *list, unsigned int crcflag_threshold) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->crcflag_threshold = crcflag_threshold;
}

// Resize the dynamic list
void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        list->data = new_data;
        list->capacity = new_capacity;
    } else {
        perror("Failed to resize dynamic list");
        exit(EXIT_FAILURE);
    }
}

// Validate the CRC indication
bool validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Implement validation logic here (e.g., non-zero tags, valid flags)
    return pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0;
}

// Add a new CRC indication to the list
void add_crc_indication(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!validate_crc_indication(pdu)) return;

    pthread_mutex_lock(&list->lock);

    if (pdu->CRC_INDICATION_REL8_TAG.CRCFLAG < list->crcflag_threshold) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        resize_dynamic_list(list, new_capacity);
