    init_dynamic_list(&crc_list, 10);

    // Simulate adding CRC indications
    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i + 1,
