                                           .CRC_INDICATION_REL8_TAG = { .CRCFLAG = rand() % 20 } };
        add_crc_indication(&crc_list, &pdu);
    }

    // Free resources
    free_dynamic_list(&crc_list);

    return 0;
}
```

