import <pthread.h>

#define MAX_ELEMENTS 10000
#define VALID_RANGE_MIN 0
#define VALID_RANGE_MAX 65535

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void log_message(const char *message) {
    printf("%s\n", message);
}

DynamicArray* create_dynamic_array() {
    DynamicArray *dyn_array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;
    dyn_array->array = NULL;
    dyn_array->size = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);
    return dyn_array;
}

bool resize_dynamic_array(DynamicArray *dyn_array, size_t new_size) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return false;
    dyn_array->array = new_array;
    dyn_array->size = new_size;
    return true;
}

bool add_pdu_to_dynamic_array(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&dyn_array->lock);
    if (dyn_array->size >= MAX_ELEMENTS) {
        log_message("Max elements reached.");
        pthread_mutex_unlock(&dyn_array->lock);
        return false;
    }

    bool resized = resize_dynamic_array(dyn_array, dyn_array->size + 1);
    if (!resized) {
        pthread_mutex_unlock(&dyn_array->lock);
        return false;
    }

    dyn_array->array[dyn_array->size - 1] = pdu;
    pthread_mutex_unlock(&dyn_array->lock);
    return true;
}

void free_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        pthread_mutex_destroy(&dyn_array->lock);
        free(dyn_array);
    }
}

bool is_valid_int(uint16_t num) {
    return num >= VALID_RANGE_MIN && num <= VALID_RANGE_MAX;
}

void process_input(DynamicArray *dyn_array) {
    size_t n;
    if (scanf("%zu", &n) != 1 || n > MAX_ELEMENTS) {
        log_message("Invalid input size.");
        return;
    }

    uint16_t *integers = (uint16_t *)malloc(n * sizeof(uint16_t));
    if (!integers) {
        log_message("Memory allocation failed for integers.");
        return;
    }

    uint16_t max_value = VALID_RANGE_MIN;
    size_t count = 0;

    for (size_t i = 0; i < n; ++i) {
        if (scanf("%hu", &integers[i]) != 1 || !is_valid_int(integers[i])) {
            log_message("Invalid integer input.");
            free(integers);
            return;
        }
        if (integers[i] > max_value) {
            max_value = integers[i];
        }
    }

    printf("Largest integer: %hu\n", max_value);

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % VALID_RANGE_MAX + 1;
        pdu.RNTI = rand() % VALID_RANGE_MAX + 1;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (!add_pdu_to_dynamic_array(dyn_array, pdu)) {
            log_message("Failed to add PDU.");
            break;
        }
    }

    free(integers);
}

int main() {
    DynamicArray *dyn_array = create_dynamic_array();
    if (!dyn_array) {
        log_message("Failed to create dynamic array.");
        return 1;
    }

    process_input(dyn_array);

    free_dynamic_array(dyn_array);
    return 0;
}
```

