    DL_FRAME_PDSCH_TAG pdsch;
    DL_FRAME_PCH_TAG pch;
    DL_FRAME_SCH_TAG sch;
} LTE_DL_FRAME_MESSAGE_T;

typedef struct {
    LTE_DL_FRAME_MESSAGE_T* frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} FrameManager;

// Function to initialize the FrameManager
int initFrameManager(FrameManager *manager, size_t initial_capacity) {
    if (!manager) return -1;

    manager->frames = (LTE_DL_FRAME_MESSAGE_T*)malloc(initial_capacity * sizeof(LTE_DL_FRAME_MESSAGE_T));
    if (!manager->frames) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager->frames);
        fprintf(stderr, "Mutex initialization failed\n");
        return -1;
    }

    // Logging: FrameManager initialized
    printf("FrameManager initialized with capacity %zu\n", initial_capacity);

    return 0;
}

// Function to add a new frame
int addFrame(FrameManager *manager, LTE_DL_FRAME_MESSAGE_T frame) {
    if (!manager || pthread_mutex_lock(&manager->lock) != 0)
        return -1;

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_DL_FRAME_MESSAGE_T* new_frames = realloc(manager->frames, new_capacity * sizeof(LTE_DL_FRAME_MESSAGE_T));

        if (!new_frames) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    manager->frames[manager->count++] = frame;

    // Logging: Frame added
    printf("Frame added. Total frames: %zu\n", manager->count);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to update an existing frame by index
int updateFrame(FrameManager *manager, size_t index, LTE_DL_FRAME_MESSAGE_T frame) {
    if (!manager || pthread_mutex_lock(&manager->lock) != 0 || index >= manager->count)
        return -1;

    manager->frames[index] = frame;

    // Logging: Frame updated
    printf("Frame at index %zu updated\n", index);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to get the number of frames currently stored
size_t getFrameCount(FrameManager *manager) {
    if (!manager || pthread_mutex_lock(&manager->lock) != 0)
        return (size_t)-1;

    size_t count = manager->count;

    pthread_mutex_unlock(&manager->lock);
    return count;
}

// Function to clean up the FrameManager
void cleanupFrameManager(FrameManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->frames);
    manager->frames = NULL;
    manager->capacity = 0;
    manager->count = 0;

    if (pthread_mutex_unlock(&manager->lock) != 0)
        fprintf(stderr, "Mutex unlock failed\n");

    // Logging: FrameManager cleaned up
    printf("FrameManager cleaned up\n");
}
```

