#include <string.h>

char* processStringWithConstraints(const char *input, size_t sizeLimit, size_t maxMemoryThreshold) {
    if (!input || strlen(input) > sizeLimit) {
        return NULL;
    }

    size_t inputLength = strlen(input);
    size_t newSize = inputLength + 2; // for '\0' and '-'

    if (newSize > maxMemoryThreshold) {
        return NULL;
    }

    char *result = malloc(newSize);
    if (!result) {
        return NULL;
    }

    strcpy(result, input);
    result[inputLength] = '-';
    result[newSize - 1] = '\0';

    // Error handling and logging for memory allocation failure
    if (newSize > maxMemoryThreshold || !result) {
        fprintf(stderr, "Failed to allocate memory or exceeded memory threshold\n");
        free(result); // Clean up in case of error
        return NULL;
    }

    return result;
}

// Example usage: Assume this is part of a larger signal processing pipeline
void processPipeline(const char *data[], size_t dataSize, size_t sizeLimit, size_t maxMemoryThreshold) {
    for (size_t i = 0; i < dataSize; ++i) {
        char *processed = processStringWithConstraints(data[i], sizeLimit, maxMemoryThreshold);

        if (!processed) {
            // Log failure and retry logic here
            fprintf(stderr, "Failed to process string at index %zu\n", i);
            continue;
        }

        // Further processing...
        printf("Processed: %s\n", processed);
        free(processed);  // Ensure no memory leaks
    }
}

// JavaScript function for extracting matching elements from DOM tree using recursion

function extractMatchingElements(root, selector) {
    const results = [];

    if (!root || !(root instanceof Node)) return results;

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE) {
            // Filtering logic based on class name or ID
            if ((node.id && node.id.includes(selector)) || 
                (node.className && node.classList.contains(selector))) {
                results.push(node);
            }

            // Minimize memory usage by using a non-allocating approach for child nodes
            const children = Array.from(node.children);  // Create shallow copy
            children.forEach(traverse);
        }        
    }

    traverse(root);

    return results;
}

// Example of usage within the DOM context

document.addEventListener('DOMContentLoaded', (event) => {
    const elements = extractMatchingElements(document.body, 'my-class');
    console.log(elements); // Log or process matched elements
});
