#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3
#define LOG_LEVEL_CRITICAL 4

typedef struct {
    time_t timestamp;
    int log_level;
    char *message;
} log_entry;

// Function prototypes
void initialize_logging_system(const char *config_file, int num_logs);
void cleanup_logging_system(log_entry *logs, int num_logs);
void add_hash_algorithm(const char *algorithm);
char *generate_random_string(size_t min_len, size_t max_len);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_logging_system(const char *config_file, int num_logs) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        fprintf(stderr, "Configuration file missing or outdated. Using default algorithms.\n");
    } else {
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            add_hash_algorithm(strtok(line, "\n"));
        }
        fclose(file);
    }

    log_entry *logs = malloc(num_logs * sizeof(log_entry));
    time_t *timestamps = malloc(num_logs * sizeof(time_t));

    if (!logs || !timestamps) {
        fprintf(stderr, "Memory allocation failed.\n");
        cleanup_logging_system(logs, num_logs);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_logs; ++i) {
        pthread_mutex_lock(&mutex);
        timestamps[i] = time(NULL);
        logs[i].timestamp = timestamps[i];
        logs[i].log_level = rand() % 5;
        size_t min_len = getenv("MIN_LOG_LEN") ? atoi(getenv("MIN_LOG_LEN")) : 10;
        size_t max_len = getenv("MAX_LOG_LEN") ? atoi(getenv("MAX_LOG_LEN")) : 50;
        logs[i].message = generate_random_string(min_len, max_len);
        pthread_mutex_unlock(&mutex);

        if (!logs[i].message) {
            fprintf(stderr, "Failed to generate random string for log entry.\n");
            break;
        }
    }

    // Example usage
    for (int i = 0; i < num_logs; ++i) {
        printf("[%ld] Level %d: %s\n", logs[i].timestamp, logs[i].log_level, logs[i].message);
    }

