#define MAX_RNTI_CONFLICTS 1000

sem_t *init_semaphore(int initial_value) {
    sem_t *sema = malloc(sizeof(sem_t));
    if (sema == NULL || sem_init(sema, 0, initial_value) != 0) {
        free(sema);
        return NULL;
    }
    return sema;
}

void delete_semaphore(sem_t *sema) {
    if (sema && sem_destroy(sema) == 0) {
        free(sema);
    }
}

int allocate_records(int num_records, double value_min, double value_max, Record ***records) {
    if (num_records <= 0 || records == NULL) return -1;

    *records = malloc(num_records * sizeof(Record *));
    if (*records == NULL) return -1;

    long current_offset = 1;
    for (int i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) goto error_cleanup;

        (*records)[i]->offset = current_offset++;
        (*records)[i]->key = rand() % MAX_RNTI_CONFLICTS;
        (*records)[i]->precision_value = value_min + (double)rand() / RAND_MAX * (value_max - value_min);
    }

    return 0;

error_cleanup:
    for (int i = 0; i < num_records; ++i) {
        if ((*records)[i] != NULL) free((*records)[i]);
    }
    free(*records);
    *records = NULL;
    return -1;
}

