    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    if (fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file) != count) {
        perror("Error writing data to file");
    }

    fclose(file);
}

int generate_crc_indications(int num_records, double value_min, double value_max, int *result_count) {
    if (num_records <= 0 || result_count == NULL) return -1;

    Record **records = NULL;
    NFAPI_CRC_INDICATION_PDU_T *crc_data = malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_data) return -1;

    int status = allocate_records(num_records, value_min, value_max, &records);
    if (status != 0) {
        free(crc_data);
        return status;
    }

    for (int i = 0; i < num_records; ++i) {
        crc_data[i].RX_UE_INFORMATION_TAG = rand();
        crc_data[i].RNTI = records[i]->key;

        // Check RNTI conflicts
        int conflict_found = 0;
        for (int j = 0; j < i && !conflict_found; ++j) {
            if (crc_data[j].RNTI == crc_data[i].RNTI) {
                conflict_found = 1;
                --i; // Retry this index
            }
        }

        crc_data[i].CRC_INDICATION_REL8_TAG = rand();
        crc_data[i].CRCFLAG = ((rand() % 100) < 50) ? 'Y' : 'N'; // 50% probability

        free(records[i]);
    }
    free(records);

    write_to_file("crc_indications.bin", crc_data, num_records);
    *result_count = num_records;

    free(crc_data);
    return 0;
}

int main() {
    srand(time(NULL));

    int result_count;
    sem_t *semaphore = init_semaphore(1); // For demonstration purposes

    if (!semaphore) {
        fprintf(stderr, "Failed to initialize semaphore\n");
        return EXIT_FAILURE;
    }

    int status = generate_crc_indications(1000, 0.0, 1.0, &result_count);
    if (status != 0) {
        fprintf(stderr, "Error generating CRC indications: %d\n", status);
    } else {
        printf("Generated %d CRC indications.\n", result_count);
    }

    delete_semaphore(semaphore);

    return EXIT_SUCCESS;
}
