Logger logger;

void init_logger(const char* filename) {
    logger.log_file = fopen(filename, "w");
    if (!logger.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&logger.lock, NULL);
}

void log_snr_value(uint32_t rnti, int16_t snr_value) {
    pthread_mutex_lock(&logger.lock);
    fprintf(logger.log_file, "RNTI: %u, SNR Value: %d\n", rnti, snr_value);
    fflush(logger.log_file);
    pthread_mutex_unlock(&logger.lock);
}

// Function to simulate dynamic radio channel model
int16_t calculate_snr() {
    return (rand() % 31) - 15; // Simulating SNR between -15 and +15 dB
}

// Thread-safe function to initialize and populate the array
NFAPI_MESSAGE_PDU_T* init_population_array(size_t initial_size, size_t num_elements, int *allocation_attempts, int *successful_allocations) {
    pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_MESSAGE_PDU_T *array = (NFAPI_MESSAGE_PDU_T *)malloc(initial_size * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!array) return NULL;

    size_t current_size = initial_size;
    *allocation_attempts = 0;
    *successful_allocations = 0;

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&allocation_lock);
        (*allocation_attempts)++;

        if (i >= current_size) {
            size_t new_size = current_size * 2;
            NFAPI_MESSAGE_PDU_T* temp_array = realloc(array, new_size * sizeof(NFAPI_MESSAGE_PDU_T));

            if (!temp_array) {
                free(array);
                pthread_mutex_unlock(&allocation_lock);
                return NULL;
            }

            array = temp_array;
            current_size = new_size;
        }

        array[i].ue_info_tag.rnti = (uint32_t)(rand() % 0xFFFFFFFF); // Simulate RNTI
        array[i].rnti = array[i].ue_info_tag.rnti; // Assigning same value for simplicity
        array[i].crc_indication_rel8_tag = 0; // Placeholder value, implement as needed

        int16_t snr_value = calculate_snr();
        array[i].snr_indication_rel8_tag.snr_value = snr_value;

        log_snr_value(array[i].rnti, snr_value);

        (*successful_allocations)++;
        pthread_mutex_unlock(&allocation_lock);
    }

    return array;
}

// Example usage
int main() {
    srand(time(NULL));
    init_logger("snr_log.txt");

    size_t initial_size = 10;
    size_t num_elements = 100;
    int allocation_attempts, successful_allocations;

    NFAPI_MESSAGE_PDU_T* pdu_array = init_population_array(initial_size, num_elements, &allocation_attempts, &successful_allocations);

    if (pdu_array) {
        printf("Total Allocation Attempts: %d\n", allocation_attempts);
        printf("Successful Allocations: %d\n", successful_allocations);
        free(pdu_array);
    }

    fclose(logger.log_file);
    pthread_mutex_destroy(&logger.lock);
    return 0;
}
