#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t key; // Unique key for the record
    int value;    // Randomly initialized integer within a range
} Record;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    Record *record_array;
    size_t pdu_count;
    size_t record_count;
    pthread_mutex_t lock;
} DynamicArrayManager;

// Custom memory pool allocator (simplified for demonstration)
void* custom_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
    }
    return ptr;
}

void* custom_realloc(void *ptr, size_t size) {
    void *new_ptr = realloc(ptr, size);
    if (!new_ptr) {
        fprintf(stderr, "Memory reallocation failed\n");
    }
    return new_ptr;
}

void free_custom(void *ptr) {
    free(ptr);
}

// Initialize structures with pseudo-random values
void initialize_structures(DynamicArrayManager *manager, unsigned int seed, size_t max_value_range) {
    pthread_mutex_lock(&manager->lock);

    // Seed the random number generator
    srand(seed);

    for (size_t i = 0; i < manager->pdu_count; ++i) {
        manager->pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        manager->pdu_array[i].RNTI = rand() & 0xFFFF;
        manager->pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        manager->pdu_array[i].CRCFLAG = rand() % 2;
    }

    for (size_t i = 0; i < manager->record_count; ++i) {
        do {
            manager->record_array[i].key = rand();
        } while (/* check for duplicate keys */);

        manager->record_array[i].value = rand() % max_value_range;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to create and initialize dynamic arrays
DynamicArrayManager* create_dynamic_arrays(size_t pdu_count, size_t record_count) {
    if (pdu_count <= 0 || record_count <= 0) {
        fprintf(stderr, "Invalid array sizes\n");
        return NULL;
    }

    DynamicArrayManager *manager = custom_alloc(sizeof(DynamicArrayManager));
    if (!manager) return NULL;

    manager->pdu_array = custom_alloc(pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->record_array = custom_alloc(record_count * sizeof(Record));

    if (!manager->pdu_array || !manager->record_array) {
        free_custom(manager->pdu_array);
        free_custom(manager->record_array);
        free_custom(manager);
        return NULL;
    }

    manager->pdu_count = pdu_count;
    manager->record_count = record_count;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to resize dynamic arrays
int resize_dynamic_arrays(DynamicArrayManager *manager, size_t new_pdu_count, size_t new_record_count) {
    if (!manager || new_pdu_count <= 0 || new_record_count <= 0) {
        fprintf(stderr, "Invalid parameters for resizing\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    manager->pdu_array = custom_realloc(manager->pdu_array, new_pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->record_array = custom_realloc(manager->record_array, new_record_count * sizeof(Record));

    if (!manager->pdu_array || !manager->record_array) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->pdu_count = new_pdu_count;
    manager->record_count = new_record_count;

    // Initialize newly allocated space
    for (size_t i = manager->pdu_count; i < new_pdu_count; ++i) {
        manager->pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        manager->pdu_array[i].RNTI = rand() & 0xFFFF;
        manager->pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        manager->pdu_array[i].CRCFLAG = rand() % 2;
    }

    for (size_t i = manager->record_count; i < new_record_count; ++i) {
        do {
            manager->record_array[i].key = rand();
        } while (/* check for duplicate keys */);

        manager->record_array[i].value = rand();
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to free allocated memory
void destroy_dynamic_arrays(DynamicArrayManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free_custom(manager->pdu_array);
    free_custom(manager->record_array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free_custom(manager);
}

