#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define RANDOM_RANGE_MAX 100
#define MEMORY_THRESHOLD (1024 * 1024 * 512) // 512 MB for example

typedef struct {
    int value;
} record;

void log_memory_usage(const char* filename);
int ensure_buffer_size(char** buffer, size_t current_size, size_t required_size);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_data_structures(long num_offsets, int num_keys, char** error_buffer) {
    if (num_offsets < 2 * num_keys || num_keys > MAX_RECORDS / 2) {
        snprintf(*error_buffer, ensure_buffer_size(error_buffer, strlen(""), 128), "Validation failed: offset size must be at least twice key size and records <= 10000.");
        return -1;
    }

    pthread_mutex_lock(&lock);

    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    int* keys = (int*)malloc(num_keys * sizeof(int));
    record* records = (record*)malloc(num_keys * sizeof(record));
    unsigned short* status_flags = (unsigned short*)malloc(num_keys * sizeof(unsigned short));

    if (!offsets || !keys || !records || !status_flags) {
        char error_msg[256] = "Memory allocation failed.";
        snprintf(*error_buffer, ensure_buffer_size(error_buffer, strlen(""), 255), "%s", error_msg);
        pthread_mutex_unlock(&lock);
        free(offsets); offsets = NULL;
        free(keys); keys = NULL;
        free(records); records = NULL;
        free(status_flags); status_flags = NULL;
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < num_keys; ++i) {
        records[i].value = rand() % RANDOM_RANGE_MAX;
    }

    pthread_mutex_unlock(&lock);

    // Start logging memory usage
    log_memory_usage("memory_log.txt");

    return 0;
}

int ensure_buffer_size(char** buffer, size_t current_size, size_t required_size) {
    if (current_size < required_size) {
        char* new_buffer = (char*)realloc(*buffer, required_size);
        if (!new_buffer) {
            return current_size;
        }
        *buffer = new_buffer;
    }
    return required_size;
}

void log_memory_usage(const char* filename) {
    FILE* file = fopen(filename, "a");
    if (!file) {
        // Fallback: Use memory-mapped file or a temporary buffer
        printf("Log file unavailable. Using fallback method.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    void* ptr;
    size_t total_mem_usage = 0;

    // Calculate used memory (simplified example, not exhaustive)
    for (int i = 0; i < MAX_RECORDS / 2; ++i) {
        ptr = &((record*)malloc(sizeof(record)))[0];
        if (ptr) {
            total_mem_usage += sizeof(record);
            free(ptr);
        }
    }

    fprintf(file, "Memory usage: %zu bytes\n", total_mem_usage);
    fclose(file);

    pthread_mutex_unlock(&lock);

    // Schedule next log entry
    struct timespec ts = {60, 0};
    nanosleep(&ts, NULL);
    log_memory_usage(filename);
}
