['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node for doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the dynamic list structure with thread safety in mind
typedef struct {
    Node* head;
    Node* tail;
    int count;
    pthread_mutex_t lock;
    size_t capacity;  // Maximum number of elements allowed
} NFAPI_List;

// Function to initialize the list
void nfaPI_list_init(NFAPI_List* list, size_t max_capacity) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = max_capacity;
}

// Function to destroy the list and free all resources
void nfaPI_list_destroy(NFAPI_List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

// Function to add a new element to the list
bool nfaPI_list_add(NFAPI_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return false; // List is full
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = pdu;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node; // First element
    }

    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to iterate over the list in forward direction
void nfaPI_list_iterate_forward(NFAPI_List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the list in backward direction
void nfaPI_list_iterate_backward(NFAPI_List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->tail;
    while (current != NULL) {
        callback(current->data);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example callback function for iteration
void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %s\n",
           pdu.RX_UE_INFORMATION_TAG,
           pdu.RNTI,
           pdu.CRC_INDICATION_REL8_TAG,
           pdu.CRCFLAG ? "true" : "false");
}

int main() {
    NFAPI_List list;
    nfaPI_list_init(&list, 10);

    for (int i = 0; i < 5; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i, 100 + i, i % 256, rand() % 2};
        nfaPI_list_add(&list, pdu);
    }

    printf("Iterating forward:\n");
    nfaPI_list_iterate_forward(&list, print_pdu);

    printf("\nIterating backward:\n");
    nfaPI_list_iterate_backward(&list, print_pdu);

    nfaPI_list_destroy(&list);

    return 0;
}
