        (*records)[i]->offset = 0;
        (*records)[i]->key = 0;
        (*records)[i]->value = 0.0;
    }

    if (!validate_offsets(*records, num_records)) {
        free_records(*records, num_records);
        return -1;
    }

    return 0;
}

void free_records(Record **records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) free(records[i]);
    }
    free(records);
}

int validate_offsets(const Record *records, int num_records) {
    long seen_offsets[num_records];
    memset(seen_offsets, -1, sizeof(seen_offsets));

    for (int i = 0; i < num_records; ++i) {
        if (records[i]->offset <= 0) return 0;

        for (int j = 0; j < i; ++j) {
            if (records[j]->offset == records[i]->offset) return 0;
        }

        seen_offsets[i] = records[i]->offset;
    }
    return 1;
}

void log_operation(const char *operation, size_t data_size, const char *error_info) {
    pthread_mutex_lock(&mutex);
    printf("Operation: %s, Data Size: %zu", operation, data_size);
    if (error_info && strlen(error_info)) {
        printf(", Error Info: %s", error_info);
    }
    printf("\n");
    pthread_mutex_unlock(&mutex);
}

// Example usage of conditional compilation for DES modes
#ifdef USE_HARDWARE_ACCELERATION
void crypto_operation_hardware(const Record *records, int num_records) {
    // Placeholder for hardware-accelerated operations
    log_operation("Crypto Operation (Hardware)", 0, NULL);
}
#else
void crypto_operation_software(const Record *records, int num_records) {
    // Placeholder for software-based cryptographic operations
    log_operation("Crypto Operation (Software)", 0, NULL);
}
#endif

int main() {
    Record **records;
    int num_records = 10;

    if (allocate_records(num_records, &records) == 0) {
        printf("Records allocated and validated successfully.\n");

        // Example encryption mode selection
        #ifdef USE_HARDWARE_ACCELERATION
            crypto_operation_hardware(records[0], num_records);
        #else
            crypto_operation_software(records[0], num_records);
        #endif

        free_records(records, num_records);
    } else {
        log_operation("Record Allocation Failed", 0, "Memory allocation error or validation failure");
    }

    return 0;
}
```

