int is_valid_event_type(int event_type) {
    return (event_type == VALID_EVENT_TYPE_1 || event_type == VALID_EVENT_TYPE_2);
}

// Memory pool and lock for thread safety
typedef struct {
    void* memory;
    size_t size;
} MemoryPool;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

MemoryPool create_memory_pool(size_t item_size, size_t num_items) {
    MemoryPool pool;
    pool.size = item_size * num_items;
    pool.memory = malloc(pool.size);
    return pool;
}

void* pool_allocate(MemoryPool* pool, size_t item_size) {
    pthread_mutex_lock(&pool_lock);
    if (pool->memory == NULL || ((char*)pool->memory + pool->size) - (char*)malloc(1) < item_size) {
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    void* ptr = pool->memory;
    pool->memory = (void*)((char*)pool->memory + item_size);
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void pool_free(MemoryPool* pool) {
    free(pool->memory);
    pool->memory = NULL;
}

// Priority queue for recent items
typedef struct {
    void** items;
    size_t capacity;
    size_t count;
} PriorityQueue;

void pq_init(PriorityQueue* pq, size_t capacity) {
    pq->items = malloc(capacity * sizeof(void*));
    pq->capacity = capacity;
    pq->count = 0;
}

int pq_push(PriorityQueue* pq, void* item) {
    if (pq->count == pq->capacity) return -1; // Full
    pq->items[pq->count++] = item;
    return 0;
}

void* pq_pop(PriorityQueue* pq) {
    if (pq->count == 0) return NULL;
    void* item = pq->items[--pq->count];
    return item;
}

// Function to manage the dynamic list
void manage_dynamic_list(size_t N, size_t M, size_t K) {
    MemoryPool crc_pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), N);
    MemoryPool event_pool = create_memory_pool(sizeof(CELLULAR_EVENT_REL8_TAG), M);

    PriorityQueue recent_queue;
    pq_init(&recent_queue, K);

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* crc_pdu = pool_allocate(&crc_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_pdu) continue;

        time_t now;
        time(&now);
        crc_pdu->ue_info_tag.timestamp = (int)now;
        crc_pdu->rnti = rand() % 1000; // Example RNTI

        pq_push(&recent_queue, crc_pdu);
    }

    for (size_t i = 0; i < M; ++i) {
        CELLULAR_EVENT_REL8_TAG* event_pdu = pool_allocate(&event_pool, sizeof(CELLULAR_EVENT_REL8_TAG));
        if (!event_pdu) continue;

        time_t now;
        time(&now);
        event_pdu->timestamp = (int)now;

        // Randomly choose a valid event type
        int event_type = rand() % 3; // Example range
        if (is_valid_event_type(event_type)) {
            event_pdu->event_type = event_type;
        } else {
            fprintf(stderr, "Invalid event type encountered.\n");
            continue;
        }

        pq_push(&recent_queue, event_pdu);
    }

    // Logging and cleanup logic can be added here

    pool_free(&crc_pool);
    pool_free(&event_pool);

    while (pq_pop(&recent_queue) != NULL); // Clear priority queue
}

int main() {
