#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    double value;
    int *key_ptr;
} large_data;

typedef struct element {
    large_data *data_ptr;
    int ref_count;
    pthread_mutex_t mutex;
    struct element *next;
} element;

// Global variables for the data structures
large_data **large_data_array = NULL;
int *small_keys_array = NULL;
element *head_element_list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t current_element_count = 0;

// Function prototypes
void initialize_memory(size_t num_large, size_t num_small);
void cleanup_memory();
int add_element(large_data *data);
large_data* create_large_data(int key_index);

void initialize_memory(size_t num_large, size_t num_small) {
    // Allocate array of large_data objects
    large_data_array = (large_data**)malloc(num_large * sizeof(large_data*));
    if (!large_data_array) {
        perror("Failed to allocate memory for large_data_array");
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize small_keys array
    small_keys_array = (int*)calloc(num_small, sizeof(int));
    if (!small_keys_array) {
        perror("Failed to allocate memory for small_keys_array");
        free(large_data_array);
        exit(EXIT_FAILURE);
    }

    // Initialize large_data objects with unique timestamps
    for (size_t i = 0; i < num_large; ++i) {
        large_data_array[i] = create_large_data(i % num_small);
    }
}

void cleanup_memory() {
    pthread_mutex_lock(&list_mutex);

    // Free element list
    element *current = head_element_list;
    while (current != NULL) {
        element *next = current->next;
        free(current->data_ptr);  // Assuming data_ptr needs to be freed as well
        pthread_mutex_destroy(&current->mutex);
        free(current);
        current = next;
    }

    // Free large_data objects
    for (size_t i = 0; i < current_element_count && large_data_array[i] != NULL; ++i) {
        free(large_data_array[i]->key_ptr);  // Assuming key_ptr needs to be freed as well
        free(large_data_array[i]);
    }
    free(large_data_array);

    // Free small_keys array
    free(small_keys_array);

    pthread_mutex_unlock(&list_mutex);
}

int add_element(large_data *data) {
    if (current_element_count >= MAX_ELEMENTS) {
        fprintf(stderr, "Maximum element limit reached.\n");
        return -1;
    }

    pthread_mutex_lock(&list_mutex);

    // Allocate new element
    element *new_elem = (element*)malloc(sizeof(element));
    if (!new_elem) {
        perror("Failed to allocate memory for new element");
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    new_elem->data_ptr = data;
    new_elem->ref_count = 1;
    pthread_mutex_init(&new_elem->mutex, NULL);
    new_elem->next = head_element_list;

    head_element_list = new_elem;
    current_element_count++;

    pthread_mutex_unlock(&list_mutex);

    return 0;
}

large_data* create_large_data(int key_index) {
    large_data *data = (large_data*)malloc(sizeof(large_data));
    if (!data) {
        perror("Failed to allocate memory for large_data");
        exit(EXIT_FAILURE);
    }

    data->value = (double)time(NULL);  // Initialize with a unique timestamp
    data->key_ptr = &small_keys_array[key_index];

    return data;
}

int main() {
    initialize_memory(10, 5);

    for (size_t i = 0; i < 10; ++i) {
        if (add_element(large_data_array[i]) != 0) {
            fprintf(stderr, "Failed to add element %zu\n", i);
        }
    }

    cleanup_memory();
    return 0;
}
```

### Design Choices and Trade-offs:

1. **Thread Safety**: The `element` list is protected by a mutex (`list_mutex`) to ensure thread-safe operations when adding elements. Each `element` also has its own mutex for individual synchronization, allowing fine-grained locking.

2. **Memory Management**: 
   - Arrays are allocated using `malloc` and initialized with `calloc` where necessary.
   - Memory is freed in reverse order of allocation to prevent leaks.
   - Graceful degradation: If memory allocation fails at any point, the program exits after cleaning up already allocated resources.

3. **Concurrency Considerations**:
   - The global mutex (`list_mutex`) ensures that only one thread can modify the `element` list at a time, which is crucial for maintaining consistency but may become a bottleneck under high concurrency.
   - Each element has its own mutex to allow concurrent operations on different elements without blocking each other.

4. **Resource Limiting**:
   - The maximum size of the `element` list (`MAX_ELEMENTS`) prevents memory exhaustion by capping the number of allowed elements.
   - If this limit is reached, additional elements cannot be added, and an error message is logged.

5. **Error Handling**:
   - Memory allocation failures are checked immediately, and appropriate error messages are printed using `perror`.
   - The program exits on critical failures to prevent undefined behavior.

6. **Initialization with Unique Timestamps**: 
   - Each `large_data` object is initialized with a timestamp derived from the current time (`time(NULL)`), ensuring uniqueness.

This implementation balances between thread safety, memory management efficiency, and error handling, making it suitable for scenarios with varying concurrency levels.']

