```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

// Structure Definitions
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Global Variables
Node* head = NULL;
Node* tail = NULL;
size_t pool_size = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void initialize_pool(size_t initial_capacity);
void resize_pool(size_t new_capacity);
void add_structure(int RX_UE_INFORMATION_TAG, unsigned int RNTI, int CRC_INDICATION_REL8_TAG);
Node* get_next_node(Node* current);
Node* get_previous_node(Node* current);
void iterate_list_forward(void (*func)(NFAPI_CRC_INDICATION_PDU_T));
void iterate_list_backward(void (*func)(NFAPI_CRC_INDICATION_PDU_T));
void cleanup();

// Initialize the pool with a given capacity
void initialize_pool(size_t initial_capacity) {
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < initial_capacity; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = rand() % 1000;
        new_node->data.CRC_INDICATION_REL8_TAG = rand();
        new_node->data.CRCFLAG = (rand() % 2) == 1;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }
    pool_size = initial_capacity;
    pthread_mutex_unlock(&list_mutex);
}

// Resize the pool to a new capacity
void resize_pool(size_t new_capacity) {
    pthread_mutex_lock(&list_mutex);

    size_t current_capacity = 0;
    Node* current = head;
    while (current && current_capacity < pool_size) {
        current = current->next;
        ++current_capacity;
    }

    if (new_capacity > current_capacity) {
        for (size_t i = current_capacity; i < new_capacity; ++i) {
            Node* new_node = malloc(sizeof(Node));
            if (!new_node) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }
            new_node->data.RX_UE_INFORMATION_TAG = rand();
            new_node->data.RNTI = rand() % 1000;
            new_node->data.CRC_INDICATION_REL8_TAG = rand();
            new_node->data.CRCFLAG = (rand() % 2) == 1;

            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    } else {
        while (current_capacity > new_capacity && head) {
            Node* temp = head;
            head = head->next;
            if (head) {
                head->prev = NULL;
            }
            free(temp);
            --current_capacity;
        }
    }

    pool_size = new_capacity;
    pthread_mutex_unlock(&list_mutex);
}

// Add a structure to the list
void add_structure(int RX_UE_INFORMATION_TAG, unsigned int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list_mutex);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = (rand() % 2) == 1;

    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        new_node->prev = tail;
        tail = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Get the next node in the list
Node* get_next_node(Node* current) {
    return current ? current->next : NULL;
}

// Get the previous node in the list
Node* get_previous_node(Node* current) {
    return current ? current->prev : NULL;
}

// Iterate over the list forward
void iterate_list_forward(void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current) {
        func(current->data);
        current = get_next_node(current);
    }
    pthread_mutex_unlock(&list_mutex);
}

// Iterate over the list backward
void iterate_list_backward(void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list_mutex);
    Node* current = tail;
    while (current) {
        func(current->data);
        current = get_previous_node(current);
    }
    pthread_mutex_unlock(&list_mutex);
}

// Cleanup allocated structures
void cleanup() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* next = get_next_node(current);
        free(current);
        current = next;
    }

    head = tail = NULL;
    pool_size = 0;

    pthread_mutex_unlock(&list_mutex);
}

// Example function for iterating
void print_structure(NFAPI_CRC_INDICATION_PDU_T data) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %s\n",
           data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG,
           data.CRCFLAG ? "true" : "false");
}

int main() {
    initialize_pool(10);

    add_structure(12345, 6789, 101112);
    iterate_list_forward(print_structure);

    resize_pool(20);
    cleanup();

    return 0;
}
```

This code implements a thread-safe doubly-linked list to manage NFAPI_CRC_INDICATION_PDU_T structures. It includes functions for initializing the pool, resizing it dynamically, adding new structures, iterating over the list in both directions, and cleaning up resources. Thread safety is ensured using mutex locks.']

