typedef struct {
    time_t timestamp;
    unsigned long id;
    size_t payload_length;
    void *payload;
} DataPacket;

#define PACKET_LIFETIME_SECONDS 300 // Example lifetime of packets

typedef struct PacketNode {
    DataPacket packet;
    struct PacketNode* next;
} PacketNode;

typedef struct {
    PacketNode** table;
    pthread_mutex_t* locks;
    size_t capacity;
} PacketTable;

unsigned long hash(unsigned long id, size_t capacity) {
    return id % capacity;
}

PacketTable* create_packet_table(size_t capacity) {
    PacketTable* table = (PacketTable*)malloc(sizeof(PacketTable));
    table->table = (PacketNode**)calloc(capacity, sizeof(PacketNode*));
    table->locks = (pthread_mutex_t*)malloc(capacity * sizeof(pthread_mutex_t));
    for (size_t i = 0; i < capacity; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
    table->capacity = capacity;
    return table;
}

void free_packet_table(PacketTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        PacketNode* node = table->table[i];
        while (node) {
            PacketNode* next = node->next;
            if (node->packet.payload) {
                free(node->packet.payload);
            }
            free(node);
            node = next;
        }
    }
    free(table->locks);
    free(table->table);
    free(table);
}

int add_packet(PacketTable* table, DataPacket packet) {
    unsigned long index = hash(packet.id, table->capacity);
    pthread_mutex_lock(&table->locks[index]);

    PacketNode* node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!node) return -1; // Memory allocation failure

    node->packet = packet;
    node->next = table->table[index];
    table->table[index] = node;

    pthread_mutex_unlock(&table->locks[index]);
    return 0;
}

DataPacket* get_packet(PacketTable* table, unsigned long id) {
    unsigned long index = hash(id, table->capacity);
    pthread_mutex_lock(&table->locks[index]);

    PacketNode* node = table->table[index];
    while (node) {
        if (node->packet.id == id && 
            difftime(time(NULL), node->packet.timestamp) < PACKET_LIFETIME_SECONDS) {
            pthread_mutex_unlock(&table->locks[index]);
            return &node->packet;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL; // Packet not found or expired
}

int update_packet(PacketTable* table, DataPacket updated_packet) {
    unsigned long index = hash(updated_packet.id, table->capacity);
    pthread_mutex_lock(&table->locks[index]);

    PacketNode* node = table->table[index];
    while (node) {
        if (node->packet.id == updated_packet.id) {
            node->packet.payload_length = updated_packet.payload_length;
            if (updated_packet.payload) {
                if (node->packet.payload) free(node->packet.payload);
                node->packet.payload = malloc(updated_packet.payload_length);
                memcpy(node->packet.payload, updated_packet.payload, updated_packet.payload_length);
            } else {
                if (node->packet.payload) {
                    free(node->packet.payload);
                    node->packet.payload = NULL;
                }
            }
            pthread_mutex_unlock(&table->locks[index]);
            return 0; // Success
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return -1; // Packet not found
}

void invalidate_expired_packets(PacketTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        PacketNode **node = &table->table[i], *prev = NULL;
        while (*node) {
            if (difftime(time(NULL), (*node)->packet.timestamp) >= PACKET_LIFETIME_SECONDS) {
                PacketNode* to_delete = *node;
                *node = (*node)->next;

                if (to_delete->packet.payload) free(to_delete->packet.payload);
                free(to_delete);

                continue;
            }
            prev = *node;
            node = &(*node)->next;
        }

        pthread_mutex_unlock(&table->locks[i]);
    }
}

// Periodic update mechanism using a separate thread
void* external_data_source_thread(void* arg) {
    PacketTable* table = (PacketTable*)arg;
    while (1) {
        // Simulate receiving updated packets from an external source
        // For demonstration, we'll sleep and then invalidate some packets.
        sleep(60);
        invalidate_expired_packets(table);
        // Implement logic to handle updates here
    }
    return NULL;
}

// Usage example
int main() {
    PacketTable* table = create_packet_table(1024);

    pthread_t updater_thread;
    pthread_create(&updater_thread, NULL, external_data_source_thread, (void*)table);

    DataPacket packet1 = {time(NULL), 12345, sizeof("Hello"), strdup("Hello")};
    add_packet(table, packet1);

    DataPacket* retrieved_packet = get_packet(table, 12345);
    if (retrieved_packet) {
        printf("Retrieved Packet: %s\n", (char*)retrieved_packet->payload);
    }

    free_packet_table(table);
    pthread_cancel(updater_thread);
    pthread_join(updater_thread, NULL);

    return 0;
}
```

This code implements a simple modular library for managing `DataPacket` structures. It uses a hash table with separate chaining to store packets and supports multi-threaded access using mutexes. The library allows adding, updating, and retrieving packets by their identifier and handles packet invalidation based on a predefined lifetime. A separate thread simulates external updates and periodic invalidation of expired packets.']

