ListNode* create_linked_list(int num_records, int key_range_min, int key_range_max,
                             int record_value_range_min, int record_value_range_max, int string_length) {
    if (num_records <= 0 || key_range_min >= key_range_max || 
        record_value_range_min >= record_value_range_max || string_length <= 0)
        return NULL;

    ListNode *head = NULL;
    ListNode **current = &head;

    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_records; ++i) {
        // Allocate and initialize a new node
        ListNode *new_node = malloc(sizeof(ListNode));
        if (!new_node) return head; // Return partially built list

        // Initialize record's value with a random number within the range
        new_node->record.value = rand() % (record_value_range_max - record_value_range_min + 1) 
                                + record_value_range_min;

        // Allocate and initialize string with random alphanumeric characters
        new_node->record.name = malloc(string_length + 1);
        if (!new_node->record.name) {
            free(new_node); // Clean up current node
            while (*current != NULL) { // Free the entire list
                ListNode *temp = *current;
                *current = (*current)->next;
                free(temp->record.name);
                free(temp);
            }
            return head; 
        }

        for (int j = 0; j < string_length; ++j)
            new_node->record.name[j] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"[
                                      rand() % 62];
        new_node->record.name[string_length] = '\0';

        // Link the new node into the list
        *current = new_node;
        current = &new_node->next;

        // Optionally store a key for each record (not shown in output)
    }

    return head;
}

void free_linked_list(ListNode *head) {
    ListNode *current = head;
    while (current != NULL) {
        ListNode *next_node = current->next;
        free(current->record.name);
        free(current);
        current = next_node;
    }
}

int main() {
    int num_records = 1000;
    int key_range_min = 1, key_range_max = 100;
    int record_value_range_min = 10, record_value_range_max = 50;
    int string_length = 8;

    ListNode *list_head = create_linked_list(num_records, key_range_min, key_range_max,
                                             record_value_range_min, record_value_range_max, string_length);

    if (list_head) {
        // List is created successfully. Use or display the list as needed.

        free_linked_list(list_head);
    } else {
        printf("Failed to create linked list.\n");
    }

    return 0;
}
