void initializeChannelConfigurationsAndMeasurements(int numberOfChannels,
                                                   LTEPHYRICChannelConfig_t **channelConfigs,
                                                   LTEPHYRICRICMeasurementResults_t **measurementResults) {
    // Allocate memory for the number of channels requested.
    *channelConfigs = (LTEPHYRICChannelConfig_t *)malloc(numberOfChannels * sizeof(LTEPHYRICChannelConfig_t));
    if (*channelConfigs == NULL) {
        fprintf(stderr, "Memory allocation failed for channel configurations.\n");
        exit(EXIT_FAILURE);
    }

    *measurementResults = (LTEPHYRICMeasurementResults_t *)malloc(numberOfChannels * sizeof(LTEPHYRICMeasurementResults_t));
    if (*measurementResults == NULL) {
        fprintf(stderr, "Memory allocation failed for measurement results.\n");
        free(*channelConfigs); // Free already allocated memory
        exit(EXIT_FAILURE);
    }

    // Initialize channel configurations and measurement results.
    for (int i = 0; i < numberOfChannels; ++i) {
        (*channelConfigs)[i].channelID = i;
        (*channelConfigs)[i].bandwidth = 20 * (i % 5 + 1); // Example bandwidth values: 20, 40, 60, 80, 100 kHz
        (*channelConfigs)[i].centerFrequency = 700e6 + i * 0.2e6; // Center frequencies starting from 700 MHz with a step of 0.2 MHz
        snprintf((*channelConfigs)[i].modulationType, sizeof((*channelConfigs)[i].modulationType), "QPSK"); // Default modulation type

        (*measurementResults)[i].channelID = i;
        (*measurementResults)[i].signalStrength = -100 + (rand() % 50); // Example signal strength between -100 dBm and -50 dBm
        (*measurementResults)[i].noiseLevel = -120 + (rand() % 30);     // Example noise level between -120 dBm and -90 dBm
        (*measurementResults)[i].SNR = (*measurementResults)[i].signalStrength - (*measurementResults)[i].noiseLevel;
    }
}

// Function to clean up allocated memory.
void cleanupChannelConfigurationsAndMeasurements(LTEPHYRICChannelConfig_t *channelConfigs,
                                                 LTEPHYRICMeasurementResults_t *measurementResults) {
    free(channelConfigs);
    free(measurementResults);
}

int main() {
