    LTEPHYRICChannelConfig_t *channelConfigs;
    LTEPHYRICMeasurementResults_t *measurementResults;

    initializeChannelConfigurationsAndMeasurements(numberOfChannels, &channelConfigs, &measurementResults);

    // Use the channel configurations and measurement results...

    cleanupChannelConfigurationsAndMeasurements(channelConfigs, measurementResults);

    return 0;
}
