#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_THRESHOLD 1048576 // Example threshold (1 MB)
#define RANDOM_OFFSET_RANGE_MAX 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    pthread_mutex_t lock;
} RecordArray;

void log_memory_usage(size_t used_memory) {
    printf("Current memory usage: %zu bytes\n", used_memory);
}

size_t calculate_memory_size(size_t count) {
    return sizeof(Record) * count;
}

RecordArray* allocate_record_array(size_t initial_capacity, size_t max_capacity) {
    RecordArray *record_array = malloc(sizeof(RecordArray));
    if (!record_array) return NULL;

    record_array->capacity = 0;
    pthread_mutex_init(&record_array->lock, NULL);

    size_t used_memory = 0;
    for (size_t current_capacity = initial_capacity; current_capacity <= max_capacity && 
         used_memory + calculate_memory_size(current_capacity) <= MEMORY_THRESHOLD; current_capacity *= 2) {
        record_array->records = realloc(record_array->records, calculate_memory_size(current_capacity));

        if (!record_array->records) {
            free(record_array);
            return NULL;
        }

        used_memory += calculate_memory_size(current_capacity);
        log_memory_usage(used_memory);

        if (current_capacity <= max_capacity) {
            record_array->capacity = current_capacity;
        } else {
            break; // Maximum capacity reached without exceeding memory threshold
        }
    }

    return record_array;
}

void initialize_records(RecordArray *record_array, size_t num_records) {
    if (!record_array || record_array->records == NULL || record_array->capacity < num_records) {
        fprintf(stderr, "Error: Cannot initialize records\n");
        return;
    }

    pthread_mutex_lock(&record_array->lock);

    for (size_t i = 0; i < num_records; ++i) {
        if (i >= record_array->capacity) break;

        record_array->records[i].key = (int)i;
        record_array->records[i].offset = rand() % RANDOM_OFFSET_RANGE_MAX;
    }

    pthread_mutex_unlock(&record_array->lock);
}

void update_record_offset(RecordArray *record_array, int key, long new_offset) {
    if (!record_array || !record_array->records) return;

    pthread_mutex_lock(&record_array->lock);

    for (size_t i = 0; i < record_array->capacity; ++i) {
        if (record_array->records[i].key == key) {
            record_array->records[i].offset = new_offset;
            break;
        }
    }

    pthread_mutex_unlock(&record_array->lock);
}

void free_record_array(RecordArray *record_array) {
    if (record_array) {
        if (record_array->records) {
            free(record_array->records);
        }

        pthread_mutex_destroy(&record_array->lock);
        free(record_array);
    }
}

int main() {
    srand(time(NULL));

    size_t initial_capacity = 64;
    size_t max_capacity = 1024;

    RecordArray *record_array = allocate_record_array(initial_capacity, max_capacity);

    if (!record_array) {
        fprintf(stderr, "Failed to allocate record array\n");
        return EXIT_FAILURE;
    }

    initialize_records(record_array, 100); // Initialize with 100 records

    update_record_offset(record_array, 10, 12345L); // Example: Update offset for key = 10

    free_record_array(record_array);

    return EXIT_SUCCESS;
}
