NFAPI_CRC_INDICATION_PDU_T* generateNficIndicationList(size_t num_indications, unsigned int seed) {
    if (num_indications <= 0) return NULL;

    srand(seed);
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(num_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_indications; ++i) {
        indications[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = rand() % MAX_RNTI + 1;
        indications[i].CRC_INDICATION_REL8_TAG.RNTI = rand() % MAX_RNTI + 1;
        indications[i].CRCFLAG = rand() % MAX_CRC_FLAGS;
    }
    pthread_mutex_unlock(&lock);

    pthread_mutex_destroy(&lock);
    return indications;
}

void freeNficIndicationList(NFAPI_CRC_INDICATION_PDU_T *indications) {
    if (indications) {
        free(indications);
    }
}
