function copyDataChunks(chunks, numBytesToCopy) {
    if (!Array.isArray(chunks) || chunks.length === 0 || numBytesToCopy <= 0) return Buffer.alloc(0);

    let totalBytes = 0;
    for (let chunk of chunks) {
        if (!(chunk instanceof Uint8Array)) continue;
        totalBytes += chunk.byteLength;
        if (totalBytes >= numBytesToCopy) break;
    }

    const resultBuffer = Buffer.allocUnsafe(numBytesToCopy);
    let bytesCopied = 0;

    for (let chunk of chunks) {
        if (!(chunk instanceof Uint8Array)) continue;

        const chunkSize = Math.min(chunk.byteLength, numBytesToCopy - bytesCopied);
        chunk.copy(resultBuffer, bytesCopied, 0, chunkSize);
        bytesCopied += chunkSize;

        if (bytesCopied >= numBytesToCopy) break;
    }

    return resultBuffer.slice(0, bytesCopied);
}
```

