['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>

#define MAX_CONNECTIONS 10000

typedef struct {
    char ip_address[16]; // IPv4 address as a string, e.g., "192.168.0.1"
    uint16_t port;
    int status;          // Active (1) or inactive (0)
    time_t last_active;  // Timestamp of the last activity
} TCPConnection;

typedef struct {
    TCPConnection *connections;
    size_t capacity;
    size_t active_count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} ConnectionPool;

// Initialize connection pool
void initialize_pool(ConnectionPool *pool, size_t initial_capacity) {
    pool->connections = (TCPConnection *)malloc(initial_capacity * sizeof(TCPConnection));
    if (!pool->connections) {
        perror("Failed to allocate memory for connections");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->active_count = 0;

    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond_var, NULL);
}

// Add a new connection
int add_connection(ConnectionPool *pool, const char *ip_address, uint16_t port) {
    pthread_mutex_lock(&pool->lock);

    if (pool->active_count >= pool->capacity) {
        // Resize the array dynamically
        size_t new_capacity = pool->capacity * 2;
        TCPConnection *new_connections = realloc(pool->connections, new_capacity * sizeof(TCPConnection));
        if (!new_connections) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->connections = new_connections;
        pool->capacity = new_capacity;
    }

    size_t index = pool->active_count++;
    strcpy(pool->connections[index].ip_address, ip_address);
    pool->connections[index].port = port;
    pool->connections[index].status = 1;
    pool->connections[index].last_active = time(NULL);

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

// Remove inactive connections older than a specified duration (in seconds)
void remove_inactive_connections(ConnectionPool *pool, int duration) {
    time_t now = time(NULL);

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->active_count; ++i) {
        if (pool->connections[i].status && (now - pool->connections[i].last_active > duration)) {
            // Mark as inactive
            pool->connections[i].status = 0;
        }
    }

    // Compact the array to remove inactive connections
    size_t new_active_count = 0;
    for (size_t i = 0; i < pool->active_count; ++i) {
        if (pool->connections[i].status) {
            if (new_active_count != i) {
                pool->connections[new_active_count] = pool->connections[i];
            }
            new_active_count++;
        }
    }

    pool->active_count = new_active_count;
    pthread_mutex_unlock(&pool->lock);
}

// Get the number of active connections
size_t get_active_connections(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);
    size_t count = pool->active_count;
    pthread_mutex_unlock(&pool->lock);
    return count;
}

// Diagnostic tool to monitor the connection pool
void diagnostic_tool(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->lock);

    printf("Active Connections: %zu\n", get_active_connections(pool));
    printf("Memory Usage: %zu bytes\n", pool->capacity * sizeof(TCPConnection));

    for (size_t i = 0; i < pool->active_count; ++i) {
        printf("IP: %s, Port: %hu, Last Active: %ld\n",
               pool->connections[i].ip_address,
               pool->connections[i].port,
               pool->connections[i].last_active);
    }

    pthread_mutex_unlock(&pool->lock);
}

// Clean up connection pool
void cleanup_pool(ConnectionPool *pool) {
    free(pool->connections);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond_var);
}

int main() {
    ConnectionPool pool;
    initialize_pool(&pool, 100);

    add_connection(&pool, "192.168.0.1", 8080);
    add_connection(&pool, "192.168.0.2", 8081);

    diagnostic_tool(&pool);

