#include <vector>
#include <random>
#include <algorithm>
#include <mutex>
#include <memory>
#include <iostream>

class ExternalDataProcessingLibrary {
public:
    static void processRecords(const std::vector<std::tuple<long, int, double>>& records) {
        // Placeholder for external library processing logic.
        std::cout << "Processing records...\n";
    }
};

struct Record {
    long offset;
    int key;
    double value;

    bool operator<(const Record& other) const {
        return offset < other.offset;
    }
};

class AdvancedRandomRecordManager {
private:
    std::vector<Record> records_;
    mutable std::mutex mtx_;

public:
    AdvancedRandomRecordManager() : records_(1024, {0, 0, 0.0}) {}

    ~AdvancedRandomRecordManager() {
        records_.clear();
    }

    void initializeRecords(int numRecords, int minValue, int maxValue) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> keyDist(1, 1000);
        std::uniform_real_distribution<> valueDist(minValue, maxValue);

        records_.resize(numRecords);
        for (auto& record : records_) {
            do {
                record.offset = std::abs(gen()) % 1000000;
                record.key = keyDist(gen);
                record.value = valueDist(gen);
            } while (record.offset == 0 || std::find(records_.begin(), records_.end(), record) != records_.end());
        }
    }

    void mergeRecords(const AdvancedRandomRecordManager& other) {
        std::lock_guard<std::mutex> lock(mtx_);

        for (const auto& rec : other.records_) {
            if (std::none_of(records_.begin(), records_.end(), [&](const Record& r) { return r.offset == rec.offset; })) {
                records_.push_back(rec);
            }
        }

        // Ensure unique offsets
        std::sort(records_.begin(), records_.end());
        auto last = std::unique(records_.begin(), records_.end());
        records_.erase(last, records_.end());
    }

    void filterRecords(double threshold) {
        std::lock_guard<std::mutex> lock(mtx_);

        auto it = std::remove_if(records_.begin(), records_.end(),
                                 [threshold](const Record& record) { return record.value < threshold; });

        records_.erase(it, records_.end());

        // Adjust offsets to maintain uniqueness
        long offset = 1;
        for (auto& record : records_) {
            while (std::find_if(records_.begin(), records_.end(), 
                                [offset](const Record& r) { return r.offset == offset; }) != records_.end()) {
                ++offset;
            }
            record.offset = offset++;
        }
    }

    void integrateWithExternalLibrary() const {
        std::lock_guard<std::mutex> lock(mtx_);
        ExternalDataProcessingLibrary::processRecords(records_);
    }

    // Performance Optimization using parallel execution (if supported)
    void batchProcess(const std::function<void(int, int)>& func, int batchSize = 1000) {
        std::lock_guard<std::mutex> lock(mtx_);

        #ifdef _OPENMP
        #pragma omp parallel for
        #endif
        for (int i = 0; i < records_.size(); i += batchSize) {
            int end = std::min(i + batchSize, static_cast<int>(records_.size()));
            func(i, end);
        }
    }

    // Example method to handle concurrent access and scalability.
    void addRecord(const Record& record) {
        std::lock_guard<std::mutex> lock(mtx_);
        records_.push_back(record);

        // Ensure unique offsets
        auto it = std::lower_bound(records_.begin(), records_.end(), record);
        if (it != records_.end() && it->offset == record.offset) {
            long newOffset = *std::max_element(records_.begin(), records_.end(),
                                               [](const Record& a, const Record& b) { return a.offset < b.offset; }).offset + 1;
            record.offset = newOffset;
            records_.insert(it, record);
        } else {
            records_.insert(it, record);
        }
    }

    // Edge cases and validation
    bool validate() const {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto& record : records_) {
            if (record.offset <= 0) return false;
        }
        return true;
    }
};
