#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int sessionID;
    time_t expirationTimestamp;
    int activityLevel;
} Session;

typedef struct {
    Session* sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionList;

SessionList* initSessionList(size_t initialCapacity) {
    SessionList* list = (SessionList*)malloc(sizeof(SessionList));
    list->sessions = (Session*)calloc(initialCapacity, sizeof(Session));
    list->capacity = initialCapacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resizeSessionList(SessionList* list) {
    size_t newCapacity = list->capacity * 2;
    Session* newSessions = (Session*)realloc(list->sessions, newCapacity * sizeof(Session));
    if (!newSessions) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->sessions = newSessions;
    list->capacity = newCapacity;
}

int addOrRenewSession(SessionList* list, int sessionID, time_t expirationTimestamp, int activityLevel) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->sessions[i].sessionID == sessionID) {
            list->sessions[i].expirationTimestamp = expirationTimestamp;
            list->sessions[i].activityLevel = activityLevel;
            pthread_mutex_unlock(&list->lock);
            return 1; // Renewed
        }
    }

    if (list->count >= list->capacity) {
        resizeSessionList(list);
    }

    int newIdx = list->count++;
    list->sessions[newIdx] = (Session){sessionID, expirationTimestamp, activityLevel};

    pthread_mutex_unlock(&list->lock);
    return 0; // Added
}

size_t getActiveSessions(SessionList* list) {
    size_t activeCount = 0;
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->sessions[i].expirationTimestamp > currentTime && list->sessions[i].activityLevel > 0) {
            activeCount++;
        }
    }
    pthread_mutex_unlock(&list->lock);

    return activeCount;
}

void cleanUpExpiredSessions(SessionList* list) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count;) {
        if (list->sessions[i].expirationTimestamp <= currentTime || list->sessions[i].activityLevel == 0) {
            memmove(&list->sessions[i], &list->sessions[i + 1], (list->count - i - 1) * sizeof(Session));
            list->count--;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void freeSessionList(SessionList* list) {
    if (list) {
        free(list->sessions);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}
```

### Key Points:
- **Dynamic Resizing:** The `resizeSessionList` function doubles the capacity when needed, ensuring efficient memory usage.
- **Thread Safety:** A mutex (`pthread_mutex_t lock`) is used to handle race conditions during concurrent access.
- **Active Session Counting:** `getActiveSessions` provides an efficient way to count sessions that are still valid and active.
- **Session Cleanup:** The `cleanUpExpiredSessions` function removes expired or inactive sessions, optimizing memory usage.
- **Memory Management:** Proper allocation and deallocation of resources ensure no memory leaks occur.

This implementation balances efficiency, thread safety, and scalability for managing user sessions in a high-concurrency environment.']

