#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} DynamicList;

// Function to initialize the dynamic list
bool initDynamicList(DynamicList* list, size_t initial_capacity) {
    if (!list) return false;

    list->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) return false;

    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    list->size = 0;
    list->capacity = initial_capacity;

    return true;
}

// Function to resize the dynamic list
bool resizeDynamicList(DynamicList* list, size_t new_capacity) {
    if (!list || new_capacity < list->size) return false;

    NFAPI_CRC_INDICATION_PDU_T* temp_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_array) return false;

    list->array = temp_array;
    list->capacity = new_capacity;
    return true;
}

// Function to add an element to the dynamic list
bool addElement(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        bool success = resizeDynamicList(list, list->capacity * 2);
        if (!success) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    list->array[list->size] = element;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to generate a random CRCFLAG
void setRandomCRCFlag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        srand(time(NULL));
        pdu->CRCFLAG = rand() % 2 == 0;
    }
}

// Function to free the dynamic list resources
void destroyDynamicList(DynamicList* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);

    free(list->array);
    list->array = NULL;
    list->size = 0;
    list->capacity = 0;
}

// Function to adjust the maximum number of concurrent structures at runtime
bool adjustMaxConcurrentStructures(DynamicList* list, size_t new_max) {
    if (!list || new_max < list->size) return false;

    bool success = resizeDynamicList(list, new_max);
    if (success && new_max > list->capacity) {
        // Ensure the array is resized to exactly `new_max` capacity
        success = resizeDynamicList(list, new_max);
    }

    return success;
}

// Logging function (enabled/disabled via macro)
#ifdef ENABLE_LOGGING
#define LOG(message) printf("LOG: %s\n", message)
#else
