#include <pthread.h>

typedef struct {
    int channelID;
    int bandwidth;  // in kHz
    double centerFrequency; // in MHz
    char modulationType[20]; // e.g., "QPSK", "16-QAM"
} LTEPHYRICChannelConfig_t;

typedef struct {
    int signalStrength;
    int noiseLevel;
    float SNR; // Signal-to-Noise Ratio
} LTEPHYRICMeasurementResults_t;

typedef struct Node {
    LTEPHYRICChannelConfig_t config;
    LTEPHYRICMeasurementResults_t results;
    struct Node* next;
} Node;

// External logging function prototype
void log_event(const char *message);

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

Node* head = NULL;

int initializeList() {
    pthread_mutex_lock(&listMutex);
    head = NULL;
    pthread_mutex_unlock(&listMutex);
    return 0; // Success
}

int addChannelConfig(LTEPHYRICChannelConfig_t config) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        log_event("Memory allocation failed for new channel config.");
        return -1; // Failure
    }

    pthread_mutex_lock(&listMutex);
    newNode->config = config;
    newNode->results = (LTEPHYRICMeasurementResults_t){0, 0, 0.0}; // Default values
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&listMutex);

    return 0; // Success
}

int updateMeasurementResults(int channelID, LTEPHYRICMeasurementResults_t results) {
    Node* current = head;

    while (current) {
        if (pthread_mutex_trylock(&listMutex) == 0) {
            if (current->config.channelID == channelID) {
                current->results = results;
                pthread_mutex_unlock(&listMutex);
                return 0; // Success
            }
            pthread_mutex_unlock(&listMutex);
        }
        current = current->next;
    }

    log_event("Channel ID not found for updating measurement results.");
    return -1; // Failure
}

int serializeToFile(const char *filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_event("Failed to open file for writing.");
        return -1;
    }

    pthread_mutex_lock(&listMutex);
    Node* current = head;

    while (current) {
        fwrite(&current->config, sizeof(LTEPHYRICChannelConfig_t), 1, file);
        fwrite(&current->results, sizeof(LTEPHYRICMeasurementResults_t), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&listMutex);
    fclose(file);
    return 0; // Success
}

int deserializeFromFile(const char *filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_event("Failed to open file for reading.");
        return -1;
    }

    pthread_mutex_lock(&listMutex);
    LTEPHYRICChannelConfig_t config;
    LTEPHYRICMeasurementResults_t results;

    while (fread(&config, sizeof(LTEPHYRICChannelConfig_t), 1, file) == 1) {
        fread(&results, sizeof(LTEPHYRICMeasurementResults_t), 1, file);

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            log_event("Memory allocation failed for deserialized data.");
            fclose(file);
            pthread_mutex_unlock(&listMutex);
            return -1;
        }

        newNode->config = config;
        newNode->results = results;
        newNode->next = head;
        head = newNode;
    }

    pthread_mutex_unlock(&listMutex);
    fclose(file);
    return 0; // Success
}

void cleanupList() {
    pthread_mutex_lock(&listMutex);

    Node* current = head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    head = NULL;

    pthread_mutex_unlock(&listMutex);
}
