typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
} NFAPI_CRC_INDICATION_PDU_T;

int compare_int(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pcr_indications(int n, int crc_flag_threshold, int* final_count, FILE* log_file) {
    if (n <= 0 || final_count == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(log_file, "Memory allocation failed.\n");
        return NULL;
    }

    int rnti_set[n];
    int unique_count = 0;

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        int new_rnti = rand() % 10000 + 1;
        bool duplicate_found = false;

        for (int j = 0; j < unique_count; j++) {
            if (rnti_set[j] == new_rnti) {
                duplicate_found = true;
                break;
            }
        }

        if (!duplicate_found) {
            rnti_set[unique_count++] = new_rnti;

            list[i].ue_info.RNTI = new_rnti;
            list[i].ue_info.crc_tag.CRCFLAG = rand() % 10 + 1; // CRCFLAG between 1 and 10

            fprintf(log_file, "Created structure with RNTI: %d, CRCFLAG: %d\n",
                    list[i].ue_info.RNTI, list[i].ue_info.crc_tag.CRCFLAG);
        }
    }

    qsort(rnti_set, unique_count, sizeof(int), compare_int);

    int filtered_count = 0;
    NFAPI_CRC_INDICATION_PDU_T *filtered_list = malloc(unique_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!filtered_list) {
        free(list);
        fprintf(log_file, "Memory allocation failed for filtered list.\n");
        return NULL;
    }

    int j = 0;
    for (int i = 0; i < unique_count; i++) {
        for (int k = 0; k < n; k++) {
            if (list[k].ue_info.RNTI == rnti_set[i] && list[k].ue_info.crc_tag.CRCFLAG >= crc_flag_threshold) {
                filtered_list[j++] = list[k];
                fprintf(log_file, "Filtered structure with RNTI: %d, CRCFLAG: %d\n",
                        list[k].ue_info.RNTI, list[k].ue_info.crc_tag.CRCFLAG);
                break;
            }
        }
    }

    *final_count = j;

    free(list);

    fprintf(log_file, "Created: %d, Filtered: %d, Final Count: %d\n", n, unique_count, *final_count);

    return filtered_list;
}
