// Define the record structure
typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Logging function pointer and its argument (either stdout or file)
void (*log_function)(const char *message, void *arg) = NULL;
void *log_arg = NULL;

// Function to initialize logging
void init_logging(void (*func)(const char *, void *), void *arg) {
    log_function = func;
    log_arg = arg;
}

// Example logging functions
static void console_log(const char *message, void *arg) {
    (void)arg; // Unused parameter
    printf("%s\n", message);
}

static void file_log(const char *message, void *arg) {
    FILE *file = (FILE *)arg;
    fprintf(file, "%s\n", message);
    fflush(file); // Ensure it's written immediately
}

// Function to log messages using the current logging setup
void log_message(const char *message) {
    if (log_function) {
        log_function(message, log_arg);
    }
}

// Function to create and initialize records
Record **create_records(int num_records, int range_min, int range_max, unsigned int seed) {
    pthread_mutex_lock(&lock);

    // Validate input
    if (num_records <= 0 || range_min > range_max) {
        log_message("Invalid input parameters.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate memory for records array
    Record **records = malloc(num_records * sizeof(Record *));
    if (!records) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Seed the random number generator
    srand(seed);

    // Allocate and initialize each record
    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            log_message("Memory allocation failed during record creation.");

            // Free previously allocated memory
            while (--i >= 0) free(records[i]);
            free(records);

            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[i]->key = i + 1; // Unique integer key starting from 1
        records[i]->offset = (long)i * 1000; // Example offset calculation

        // Generate a random value within the specified range
        records[i]->value = range_min + rand() % (range_max - range_min + 1);
    }

    pthread_mutex_unlock(&lock);
    return records;
}

// Function to free allocated records
void free_records(Record **records, int num_records) {
    if (!records) return;

    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
}
