DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    for (size_t i = 0; i < MAX_UES; ++i)
        da->contexts[i] = NULL;

    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (!da) return;

    for (size_t i = 0; i < MAX_UES && da->contexts[i]; ++i)
        free(da->contexts[i]);

    pthread_mutex_destroy(&da->lock);
    free(da);
}

int add_context(DynamicArray* da, int ue_id, const char* radio_resources, int config_status) {
    if (!da || da->size >= MAX_UES) return -1;

    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < MAX_UES && da->contexts[i]; ++i)
        if (da->contexts[i]->ue_id == ue_id) {
            // Update existing context
            free(da->contexts[i]->radio_resources);
            da->contexts[i]->radio_resources = strdup(radio_resources);
            da->contexts[i]->config_status = config_status;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }

    UE_Context* new_context = (UE_Context*)malloc(sizeof(UE_Context));
    if (!new_context) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    new_context->ue_id = ue_id;
    new_context->radio_resources = strdup(radio_resources);
    new_context->config_status = config_status;

    da->contexts[da->size++] = new_context;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int update_context(DynamicArray* da, int ue_id, const char* radio_resources, int config_status) {
