    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < MAX_UES && da->contexts[i]; ++i)
        callback(da->contexts[i]->ue_id, da->contexts[i]->config_status);

    pthread_mutex_unlock(&da->lock);
}

