['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MAX_RNTI_SIZE 4096

typedef struct {
    int rnti;
    long offset;
    int key;
    struct record {
        int value;
    } data;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for managing the list and synchronization
NFAPI_CRC_INDICATION_PDU_T *elements = NULL;
pthread_mutex_t lock;
int element_count = 0;
double average_latency = 0.0;
pthread_cond_t cond_var;

// Function prototypes
void initialize_system();
void shutdown_system();
int add_element(int rnti, long offset, int key, int value);
void update_average_latency(double new_latency);
NFAPI_CRC_INDICATION_PDU_T* find_by_rnti(int rnti);

// External latency measurement service simulation
double get_external_latency() {
    // Simulate getting external latency; in real-world, this would be an API call
    return (rand() % 100) + 50.0;
}

void initialize_system() {
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond_var, NULL);
    elements = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elements) {
        fprintf(stderr, "Failed to allocate memory for elements.\n");
        exit(EXIT_FAILURE);
    }
}

void shutdown_system() {
    free(elements);
    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond_var);
}

int add_element(int rnti, long offset, int key, int value) {
    if (rnti < 0 || rnti >= MAX_RNTI_SIZE) return -1;

    pthread_mutex_lock(&lock);

    // Check for unique RNTI
    for (int i = 0; i < element_count; ++i) {
        if (elements[i].rnti == rnti) {
            pthread_mutex_unlock(&lock);
            return -2; // RNTI already exists
        }
    }

    if (element_count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&lock);
        return -3; // Exceeded maximum elements
    }

    NFAPI_CRC_INDICATION_PDU_T *new_element = &elements[element_count++];
    new_element->rnti = rnti;
    new_element->offset = offset;
    new_element->key = key;
    new_element->data.value = value;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

void update_average_latency(double new_latency) {
    pthread_mutex_lock(&lock);

    average_latency = ((average_latency * (element_count - 1)) + new_latency) / element_count;

    pthread_cond_broadcast(&cond_var);
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_by_rnti(int rnti) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < element_count; ++i) {
        if (elements[i].rnti == rnti) {
            pthread_mutex_unlock(&lock);
            return &elements[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void* latency_update_thread(void *arg) {
    while (1) {
        double new_latency = get_external_latency();
        update_average_latency(new_latency);

        // Sleep for a random period to simulate periodic updates
        sleep(rand() % 5 + 1);
    }
    return NULL;
}

int main() {
    initialize_system();

    pthread_t latency_thread;
    pthread_create(&latency_thread, NULL, latency_update_thread, NULL);

    srand(time(NULL));

    // Example usage
    add_element(1234, rand(), rand(), rand() % 1000);
    NFAPI_CRC_INDICATION_PDU_T *found = find_by_rnti(1234);
    if (found) {
        printf("Found element with RNTI: %d\n", found->rnti);
    }

    // Simulate running
    sleep(10);

    shutdown_system();

    pthread_cancel(latency_thread);
    return 0;
}
