    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging mechanism
void log_message(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] %s\n", ctime(&now), message);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int n, int *size) {
    if (n <= 0 || size == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("Memory allocation failed for CRC indication list.");
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        list[i].RNTI = rand() % 10000;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    *size = n;
    return list;
}

// Function to establish connection and query the database
void* db_query(void *args) {
    char **res;
    PGresult *result;
    const char *conninfo;
    int supervisor_id, batch_size;

    struct args_t {
        const char *username;
        const char *password;
        const char *connection_string;
        int supervisor_id;
    } *db_args = (struct args_t *)args;

    conninfo = db_args->connection_string;

    if (conninfo == NULL || strlen(conninfo) == 0) {
        log_message("Invalid database connection string.");
        return NULL;
    }

    PGconn *conn = PQconnectdb(conninfo);
    if (PQstatus(conn) != CONNECTION_OK) {
        log_message(PQerrorMessage(conn));
        PQfinish(conn);
        return NULL;
    }

    char query[256];
    snprintf(query, sizeof(query), "SELECT employee_name, city, address FROM employees WHERE supervisor_id = %d;", db_args->supervisor_id);

    result = PQexec(conn, query);
    if (PQresultStatus(result) != PGRES_TUPLES_OK) {
        log_message(PQerrorMessage(conn));
        PQclear(result);
        PQfinish(conn);
        return NULL;
    }

    int rows = PQntuples(result);
    batch_size = rows > MAX_BATCH_SIZE ? MAX_BATCH_SIZE : rows;

    for (int i = 0; i < rows; i += batch_size) {
        int end = i + batch_size > rows ? rows : i + batch_size;
        for (int j = i; j < end; ++j) {
            res = PQgetvalue(result, j, 0);
            log_message(res[0]); // Log employee name
            // Process other fields as needed...
        }
    }

    PQclear(result);
    PQfinish(conn);
    return NULL;
}

// Main function to integrate the operations
void perform_operations(const char *username, const char *password, const char *connection_string, int supervisor_id) {
    struct args_t db_args = { username, password, connection_string, supervisor_id };

    pthread_t thread;
    if (pthread_create(&thread, NULL, db_query, &db_args) != 0) {
        log_message("Failed to create database query thread.");
        return;
    }

    int list_size;
    NFAPI_CRC_INDICATION_PDU_T *list = create_crc_indication_list(10, &list_size);
    if (!list) {
        log_message("Failed to create CRC indication list.");
        pthread_join(thread, NULL);
        return;
    }

    // Process the list as needed...

    free(list);

    pthread_join(thread, NULL);
}

int main(int argc, char *argv[]) {
    const char *username = "your_username";
    const char *password = "your_password";
    const char *connection_string = "your_connection_string";
    int supervisor_id = 1;

    perform_operations(username, password, connection_string, supervisor_id);

    return 0;
}
