#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_BANDS 10

typedef struct {
    int RSSI;
    int CQI;
} CHANNEL_QUALITY_T;

typedef struct {
    CHANNEL_QUALITY_T quality;
    float BER_ERROR_RATE;
    char FEC_PERFORMANCE_OUTCOME[50];
} PHY_CHANNEL_STATE_T;

typedef struct {
    PHY_CHANNEL_STATE_T* channels;
    size_t num_channels;
    pthread_mutex_t lock;
    int avg_RSSI;
    int min_RSSI;
    int max_RSSI;
} CHANNEL_GROUP_T;

CHANNEL_GROUP_T channel_groups[MAX_BANDS];

void initialize_channel_group(CHANNEL_GROUP_T *group, size_t max_channels) {
    group->channels = (PHY_CHANNEL_STATE_T*) malloc(max_channels * sizeof(PHY_CHANNEL_STATE_T));
    if (!group->channels) {
        perror("Failed to allocate memory for channels");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&group->lock, NULL);
    group->num_channels = max_channels;
    group->avg_RSSI = 0;
    group->min_RSSI = 100; // Assuming RSSI ranges from -100 to 100
    group->max_RSSI = -101;
}

void update_channel_state(PHY_CHANNEL_STATE_T *channel) {
    // Simulate random noise factors and environmental changes
    int rssi = rand() % 201 - 100; // Random RSSI between -100 and 100
    int cqi = rand() % 31; // CQI typically ranges from 0 to 30

    pthread_mutex_lock(&channel->lock);
    channel->quality.RSSI = rssi;
    channel->quality.CQI = cqi;
    pthread_mutex_unlock(&channel->lock);

    return;
}

void* update_channels(void *arg) {
    CHANNEL_GROUP_T *group = (CHANNEL_GROUP_T*) arg;

    for (size_t i = 0; i < group->num_channels; ++i) {
        update_channel_state(&group->channels[i]);

        pthread_mutex_lock(&group->lock);
        int rssi = group->channels[i].quality.RSSI;
        group->avg_RSSI += rssi;

        if (rssi < group->min_RSSI)
            group->min_RSSI = rssi;
        if (rssi > group->max_RSSI)
            group->max_RSSI = rssi;

        pthread_mutex_unlock(&group->lock);
    }

    pthread_mutex_lock(&group->lock);
    group->avg_RSSI /= group->num_channels;
    pthread_mutex_unlock(&group->lock);

    return NULL;
}

void adaptive_modulation_and_coding(PHY_CHANNEL_STATE_T *channel) {
    if (channel->quality.CQI > 20) {
        strcpy(channel->FEC_PERFORMANCE_OUTCOME, "High Performance");
    } else if (channel->quality.CQI > 10) {
        strcpy(channel->FEC_PERFORMANCE_OUTCOME, "Medium Performance");
    } else {
        strcpy(channel->FEC_PERFORMANCE_OUTCOME, "Low Performance");
    }

    channel->BER_ERROR_RATE = ((float)(30 - channel->quality.CQI)) / 100.0;
}

void process_frequency_band(size_t band_index, size_t max_channels) {
    initialize_channel_group(&channel_groups[band_index], max_channels);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, update_channels, &channel_groups[band_index])) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread_id, NULL)) {
        perror("Failed to join thread");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < channel_groups[band_index].num_channels; ++i) {
        adaptive_modulation_and_coding(&channel_groups[band_index].channels[i]);
    }
}

void cleanup_channel_group(CHANNEL_GROUP_T *group) {
    pthread_mutex_destroy(&group->lock);
    free(group->channels);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    size_t max_channels = 50; // Example maximum channels per band
    for (size_t i = 0; i < MAX_BANDS; ++i) {
        process_frequency_band(i, max_channels);
        cleanup_channel_group(&channel_groups[i]);
    }

    return 0;
}
```

