#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CELLS 100
#define LOG_LEVEL_VERBOSE 2
#define LOG_LEVEL_MINIMAL 0

typedef struct {
    int PCI;
} TX_CELL_INFO;

typedef struct {
    float RSRP; // Reference Signal Received Power
    float RSRQ; // Reference Signal Received Quality
    float SINR; // Signal to Interference plus Noise Ratio
} LTE_TRANSPORT_CONTEXT;

typedef void (*SINR_CALCULATION_CALLBACK)(LTE_TRANSPORT_CONTEXT *context, int num_cells);

// Logging function with configurable levels
void log_message(int level, const char *format, ...) {
    static int current_log_level = LOG_LEVEL_MINIMAL;

    if (level <= current_log_level) {
        va_list args;
        va_start(args, format);
        vprintf(format, args);
        printf("\n");
        va_end(args);
    }
}

// Simulate SINR calculation with random shadowing
void simulate_sinr(LTE_TRANSPORT_CONTEXT *context) {
    float shadowing = ((float)rand() / RAND_MAX - 0.5f) * 10; // Random shadowing factor between -5 and +5 dB
    context->SINR = context->RSRP + context->RSRQ + shadowing;
}

// Callback mechanism for SINR calculation
void default_sinr_callback(LTE_TRANSPORT_CONTEXT *context, int num_cells) {
    for (int i = 0; i < num_cells; ++i) {
        simulate_sinr(&context[i]);
        log_message(LOG_LEVEL_VERBOSE, "Calculated SINR for PCI %d: %.2f dB", context[i].PCI, context[i].SINR);
    }
}

// Initialize and populate LTE_TRANSPORT_CONTEXT array
void initialize_transport_context(LTE_TRANSPORT_CONTEXT *contexts, int num_cells) {
    if (num_cells > MAX_CELLS || contexts == NULL) return;

    for (int i = 0; i < num_cells; ++i) {
        contexts[i].PCI = rand() % 503;
        contexts[i].RSRP = ((float)rand() / RAND_MAX * 30) - 113; // Typical RSRP range: -140 to -110 dBm
        contexts[i].RSRQ = ((float)rand() / RAND_MAX * 20) - 19.5; // Typical RSRQ range: -25 to -4 dB

        log_message(LOG_LEVEL_VERBOSE, "Initialized cell PCI %d with RSRP %.2f and RSRQ %.2f", contexts[i].PCI, contexts[i].RSRP, contexts[i].RSRQ);
    }
}

// Dynamic update function for the LTE_TRANSPORT_CONTEXT list
void update_transport_context(LTE_TRANSPORT_CONTEXT **contexts, int *num_cells, int add_remove_flag, int pci) {
    static LTE_TRANSPORT_CONTEXT *dynamic_contexts = NULL;
    if (dynamic_contexts == NULL) {
        dynamic_contexts = malloc(MAX_CELLS * sizeof(LTE_TRANSPORT_CONTEXT));
    }

    if (add_remove_flag > 0 && (*num_cells) < MAX_CELLS) { // Add a new cell
        initialize_transport_context(dynamic_contexts + *num_cells, 1);
        log_message(LOG_LEVEL_VERBOSE, "Added new cell with PCI %d", pci);
        (*num_cells)++;
    } else if (add_remove_flag < 0 && *num_cells > 0) { // Remove an existing cell
        int index = -1;
        for (int i = 0; i < *num_cells; ++i) {
            if (dynamic_contexts[i].PCI == pci) {
                index = i;
                break;
            }
        }

        if (index != -1) {
            memmove(dynamic_contexts + index, dynamic_contexts + index + 1, (*num_cells - index - 1) * sizeof(LTE_TRANSPORT_CONTEXT));
            log_message(LOG_LEVEL_VERBOSE, "Removed cell with PCI %d", pci);
            (*num_cells)--;
        }
    }

    // Update the main context array
    memcpy(*contexts, dynamic_contexts, *num_cells * sizeof(LTE_TRANSPORT_CONTEXT));
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    LTE_TRANSPORT_CONTEXT contexts[MAX_CELLS];
    int num_cells = 10;

    initialize_transport_context(contexts, num_cells);

    SINR_CALCULATION_CALLBACK callback = default_sinr_callback;
    callback(contexts, num_cells);

    // Simulate dynamic updates
    update_transport_context(&contexts, &num_cells, 1, 123); // Add a cell
    update_transport_context(&contexts, &num_cells, -1, 456); // Remove a cell

    return 0;
}
