    }

    // Allocate memory for keys ensuring concurrent access safety
    pthread_mutex_t keyMutex = PTHREAD_MUTEX_INITIALIZER;
    int* keys = malloc(numKeys * sizeof(int));
    if (keys == NULL) {
        perror("Failed to allocate key array");
