    float RSRP;   // Reference Signal Received Power
    float SNR;    // Signal-to-Noise Ratio
} LTE_PHY_Stats;

#define FLOAT_RANGE_MIN -100.0f
#define FLOAT_RANGE_MAX 0.0f
#define MIN_RSRP -140.0f
#define MAX_RSRP -50.0f
#define MIN_SNR 0.0f
#define MAX_SNR 30.0f

// Function to find the smallest number in an array
float find_smallest_number(const float* arr, size_t len) {
    if (len == 0) return FLT_MAX;

    float min = arr[0];
    for (size_t i = 1; i < len; ++i) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

// Function to read floating-point numbers, validate range, and store them
float* read_and_validate_floats(size_t *size) {
    float *numbers = NULL;
    size_t capacity = 0;
    size_t count = 0;

    printf("Enter floating-point numbers (range [%f, %f]):\n", FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);

    while (1) {
        if (count >= capacity) {
            capacity = (capacity == 0) ? 10 : capacity * 2;
            float* temp = realloc(numbers, sizeof(float) * capacity);
            if (!temp) {
                free(numbers);
                printf("Memory allocation error.\n");
                return NULL;
            }
            numbers = temp;
        }

        char line[256];
        if (!fgets(line, sizeof(line), stdin)) {
            if (feof(stdin)) break;  // Exit on EOF
            perror("Error reading input");
            free(numbers);
            return NULL;
        }

        float number;
        if (sscanf(line, "%f", &number) == 1 && number >= FLOAT_RANGE_MIN && number <= FLOAT_RANGE_MAX) {
            numbers[count++] = number;
        } else {
            printf("Invalid or out-of-range input. Try again.\n");
        }
    }

    *size = count;
    return numbers;
}

// Function to populate LTE PHY layer statistics
LTE_PHY_Stats* create_lte_phy_stats(size_t *size) {
    LTE_PHY_Stats *stats = NULL;
    size_t capacity = 0;
    size_t count = 0;

    printf("Enter the number of LTE PHY layer stats: ");

    if (scanf("%zu", size) != 1 || *size <= 0) {
        perror("Error reading input");
        return NULL;
    }

    for (size_t i = 0; i < *size; ++i) {
        if (count >= capacity) {
            capacity = (capacity == 0) ? 10 : capacity * 2;
            LTE_PHY_Stats* temp = realloc(stats, sizeof(LTE_PHY_Stats) * capacity);
            if (!temp) {
                free(stats);
                perror("Memory allocation error");
                return NULL;
            }
            stats = temp;
        }

        printf("\nEnter OFDM symbol index for stat %zu: ", i + 1);
        scanf("%d", &stats[count].ofdmSymbolIndex);

        do {
            printf("Enter RSRP (range [%f, %f]): ", MIN_RSRP, MAX_RSRP);
            if (scanf("%f", &stats[count].RSRP) != 1 || stats[count].RSRP < MIN_RSRP || stats[count].RSRP > MAX_RSRP) {
                printf("Invalid RSRP value. Try again.\n");
                while(getchar() != '\n'); // Clear input buffer
            }
        } while (stats[count].RSRP < MIN_RSRP || stats[count].RSRP > MAX_RSRP);

        do {
            printf("Enter SNR (range [%f, %f]): ", MIN_SNR, MAX_SNR);
            if (scanf("%f", &stats[count].SNR) != 1 || stats[count].SNR < MIN_SNR || stats[count].SNR > MAX_SNR) {
                printf("Invalid SNR value. Try again.\n");
                while(getchar() != '\n'); // Clear input buffer
            }
        } while (stats[count].SNR < MIN_SNR || stats[count].SNR > MAX_SNR);

        ++count;
    }

    *size = count;
    return stats;
}

int main() {
    size_t float_count, lte_stats_count;

    float* numbers = read_and_validate_floats(&float_count);
    if (!numbers) {
        printf("Failed to read and validate floating-point numbers.\n");
        return 1;
    }

    float smallest_number = find_smallest_number(numbers, float_count);
    printf("Smallest number: %f\n", smallest_number);

    LTE_PHY_Stats* lte_stats = create_lte_phy_stats(&lte_stats_count);
    if (!lte_stats) {
        printf("Failed to create LTE PHY layer statistics.\n");
        free(numbers);
        return 1;
    }

    // Clean up
    free(numbers);
    free(lte_stats);

    return 0;
}
