typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    uint8_t CRCFLAG; // Flag to be randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Function to allocate and populate the array of structures.
NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu_array(size_t max_count, size_t *success_count) {
    if (max_count > 10000) {
        printf("Error: Max count exceeds the limit of 10,000.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        printf("Memory allocation failed for %zu elements.\n", max_count);
        return NULL;
    }

    // Initialize success counter
    size_t successes = 0;

    // Mutex for thread safety in multi-threaded environments
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < max_count; ++i) {
        pthread_mutex_lock(&mutex); // Ensure thread safety

        array[i].tag.RX_UE_INFORMATION_TAG = rand(); // Simulate an RX_UE_INFORMATION_TAG
        array[i].tag.RNTI = rand() & 0xFFFF; // Simulate a RNTI with valid range
        array[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG to 0 or 1

        successes++;

        pthread_mutex_unlock(&mutex);
    }

    *success_count = successes;

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

int main() {
    size_t success_count = 0;
    const size_t max_structures = 10000; // Maximum number of structures to handle

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = create_crc_pdu_array(max_structures, &success_count);

    if (pdu_array) {
        printf("Successfully created %zu CRC indication PDU structures.\n", success_count);

        // Use the pdu_array as needed...

        free_crc_pdu_array(pdu_array);
    } else {
        printf("Failed to create CRC indication PDU structures.\n");
    }

    return 0;
}
```

