#include <stdlib.h>
#include <string.h>

// Define the structures
typedef struct {
    short* data;
} RecordMetaData;

typedef struct {
    int key;
    long offset;
    RecordMetaData metadata;
} Record;

// Hash function to populate RecordMetaData with derived values
int hash_function(int key) {
    // Simple example of a hash-like operation for demonstration
    return (key * 2654435761 % 2**32);
}

Record** create_records(int n, int max_key_size) {
    if (n <= 0 || max_key_size <= 0) {
        return NULL;
    }

    Record** records = malloc(n * sizeof(Record*));
    if (!records) {
        return NULL; // Memory allocation failure
    }

    for (int i = 0; i < n; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            // Clean up already allocated memory to prevent leaks
            while (i > 0) {
                free(records[--i]);
            }
            free(records);
            return NULL;
        }

        records[i]->key = i;   // Example key, you can customize this as needed
        records[i]->offset = i;

        RecordMetaData* metadata = malloc(sizeof(RecordMetaData));
        if (!metadata) {
            // Clean up already allocated memory to prevent leaks
            free(records[i]);
            while (i > 0) {
                free(records[--i]);
            }
            free(records);
            return NULL;
        }

        records[i]->metadata.data = calloc(max_key_size, sizeof(short));
        if (!records[i]->metadata.data) {
            // Clean up already allocated memory to prevent leaks
            free(metadata);
            free(records[i]);
            while (i > 0) {
                free(records[--i]);
            }
            free(records);
            return NULL;
        }

        int hash_value = hash_function(i);
        for (int j = 0; j < max_key_size && j < sizeof(int); ++j) { // Ensuring we don't go beyond key size
            records[i]->metadata.data[j] = (short)((hash_value >> (8 * j)) & 0xFF);
        }

        metadata->data = records[i]->metadata.data;
    }

    return records;
}
