['Below is a C implementation for the described task. This code includes the structure definitions, custom memory pool handling, SNR calculation based on simulated noise factors, runtime statistics logging, and error handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <math.h>

#define MAX_UE_COUNT 10000

typedef struct {
    uint16_t rnti;
    int8_t snr; // in dB
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t crc;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t snr_indicator;
} SNR_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    SNR_INDICATION_REL8_TAG snr_indication_rel8_tag;
} NFAPI_MESSAGE_PDU_T;

// Memory pool structure
typedef struct {
    size_t element_size;
    size_t capacity;
    size_t count;
    void *pool;
} MemoryPool;

// Function prototypes
void init_memory_pool(MemoryPool *mp, size_t element_size, size_t initial_capacity);
int resize_memory_pool(MemoryPool *mp, size_t new_capacity);
NFAPI_MESSAGE_PDU_T* allocate_from_pool(MemoryPool *mp);
void free_memory_pool(MemoryPool *mp);

// Function to simulate SNR calculation
int8_t calculate_snr(uint16_t rnti) {
    // Simulate random noise factor based on RNTI (or other factors)
    return (rand() % 31) - 15; // Random SNR value between -15 and +15 dB
}

// Function to initialize and populate the NFAPI_MESSAGE_PDU_T array
int init_and_populate_nfa_message_pdu_array(NFAPI_MESSAGE_PDU_T **array, size_t ue_count,
                                            MemoryPool *mp, int log_level) {
    if (ue_count > MAX_UE_COUNT || !array || !mp) return -1;

    *array = allocate_from_pool(mp);
    if (*array == NULL) return -2; // Out of memory

    int8_t snr_values[MAX_UE_COUNT];
    double total_snr = 0.0;
    int min_snr = 127, max_snr = -128;

    clock_t start_time = clock();
    for (size_t i = 0; i < ue_count; ++i) {
        (*array)[i].rx_ue_info_tag.rnti = i + 1;
        (*array)[i].rx_ue_info_tag.snr = snr_values[i] = calculate_snr(i + 1);

        total_snr += snr_values[i];
        if (snr_values[i] < min_snr) min_snr = snr_values[i];
        if (snr_values[i] > max_snr) max_snr = snr_values[i];

        (*array)[i].crc_indication_rel8_tag.crc = rand() % 256;
        (*array)[i].snr_indication_rel8_tag.snr_indicator = (uint16_t)snr_values[i];
    }

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    if (log_level > 0) {
        printf("SNR Stats:\n");
        printf("Average SNR: %.2f dB\n", total_snr / ue_count);
        printf("Min SNR: %d dB\n", min_snr);
        printf("Max SNR: %d dB\n", max_snr);
        printf("Time taken: %.4f seconds\n", time_taken);
    }

    return 0;
}

// Memory pool functions
void init_memory_pool(MemoryPool *mp, size_t element_size, size_t initial_capacity) {
    mp->element_size = element_size;
    mp->capacity = initial_capacity;
    mp->count = 0;
    mp->pool = malloc(mp->element_size * mp->capacity);
}

int resize_memory_pool(MemoryPool *mp, size_t new_capacity) {
    void *new_pool = realloc(mp->pool, mp->element_size * new_capacity);
    if (new_pool == NULL) return -1;

    mp->capacity = new_capacity;
    mp->pool = new_pool;
    return 0;
}

NFAPI_MESSAGE_PDU_T* allocate_from_pool(MemoryPool *mp) {
    if (mp->count >= mp->capacity && resize_memory_pool(mp, mp->capacity * 2) != 0)
        return NULL; // Out of memory

    NFAPI_MESSAGE_PDU_T *element = (NFAPI_MESSAGE_PDU_T *)((char *)mp->pool + mp->element_size * mp->count);
    ++mp->count;
    return element;
}

void free_memory_pool(MemoryPool *mp) {
    if (mp->pool) {
        free(mp->pool);
        mp->pool = NULL;
        mp->capacity = 0;
        mp->count = 0;
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    MemoryPool memory_pool;
    init_memory_pool(&memory_pool, sizeof(NFAPI_MESSAGE_PDU_T), 100);

    NFAPI_MESSAGE_PDU_T *array = NULL;
    int result = init_and_populate_nfa_message_pdu_array(&array, 5000, &memory_pool, 1);

    if (result == 0) {
        printf("Initialization and population successful.\n");
    } else {
        fprintf(stderr, "Error initializing population: %d\n", result);
    }

    free_memory_pool(&memory_pool);

    return result;
}
```

### Explanation:
- **Memory Pool:** A custom memory pool is implemented to manage `NFAPI_MESSAGE_PDU_T` structures efficiently. The pool dynamically resizes based on the number of UEs.
- **SNR Calculation:** Simulated using a random value between -15 and +15 dB.
- **Logging:** Provides runtime statistics including average SNR, minimum and maximum SNR values, and initialization time.
- **Error Handling:** Checks for invalid inputs and memory allocation failures, returning error codes where necessary.']

