int executeCommand(const char* command) {
    // Simulate command execution. Replace with actual logic.
    if (strcmp(command, "SUCCESS") == 0)
        return 1;
    else if (strcmp(command, "FAILURE") == 0)
        return 0;
    else
        return -1; // Unknown command
}

NFAPI_CRC_INDICATION_PDU_T* generateNFAResults(const char** commands, size_t numCommands,
                                               unsigned int RX_UE_INFORMATION_TAG, 
                                               unsigned int RNTI, 
                                               unsigned int CRC_INDICATION_REL8_TAG,
                                               size_t* processedCount) {
    if (numCommands == 0 || commands == NULL || processedCount == NULL) {
        *processedCount = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* results = NULL;
    int successCount = 0;

    for (size_t i = 0; i < numCommands; ++i) {
        int result = executeCommand(commands[i]);
        if (result == 1) { // Command succeeded
            results = realloc(results, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (successCount + 1));
            if (!results) {
                free(results); // Cleanup on failure
                *processedCount = 0;
                return NULL;
            }

            results[successCount].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            results[successCount].RNTI = RNTI;
            results[successCount].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            results[successCount].CRCFLAG = 1; // Success
            successCount++;
        } else if (result == 0) { // Command failed
            continue; // Optionally handle failure cases as needed
        } else {
            fprintf(stderr, "Unknown command: %s\n", commands[i]);
            free(results);
            *processedCount = 0;
            return NULL;
        }
    }

    *processedCount = successCount;
    if (successCount == 0) {
        free(results);
        results = NULL;
    }

    return results;
}

// Example usage
