// Define structure for CRC_INDICATION_REL8_TAG
typedef struct {
    time_t timestamp;
    int long_offset;
    int int_key;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Define structure for CELLULAR_EVENT_REL8_TAG
typedef struct {
    time_t timestamp;
    int event_type; // Valid event types are defined in a set of constants
    int record;
} CELLULAR_EVENT_REL8_TAG;

#define MAX_EVENT_TYPE 5

const int VALID_EVENT_TYPES[MAX_EVENT_TYPE] = {1, 2, 3, 4, 5};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Function to initialize a random number generator
void init_rand() {
    srand((unsigned)time(NULL));
}

// Function to populate CRC_INDICATION_REL8_TAG structures
CRC_INDICATION_REL8_TAG* create_crc_list(int N, int min_val, int max_val) {
    CRC_INDICATION_REL8_TAG *crc_list = (CRC_INDICATION_REL8_TAG*)malloc(N * sizeof(CRC_INDICATION_REL8_TAG));
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);
        crc_list[i].timestamp = time(NULL);
        crc_list[i].long_offset = rand() % 10000;
        crc_list[i].int_key = rand() % 1000;
        crc_list[i].CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG
        pthread_mutex_unlock(&lock);
    }
    return crc_list;
}

// Function to populate CELLULAR_EVENT_REL8_TAG structures with validation
CELLULAR_EVENT_REL8_TAG* create_event_list(int M, int min_val, int max_val) {
    CELLULAR_EVENT_REL8_TAG *event_list = (CELLULAR_EVENT_REL8_TAG*)malloc(M * sizeof(CELLULAR_EVENT_REL8_TAG));
    for (int i = 0; i < M; ++i) {
        pthread_mutex_lock(&lock);
        event_list[i].timestamp = time(NULL);

        // Randomly select an event type
        int event_type = rand() % MAX_EVENT_TYPE + 1;
        if (event_type > VALID_EVENT_TYPES[MAX_EVENT_TYPE - 1]) {
            fprintf(stderr, "Invalid event type encountered: %d\n", event_type);
            pthread_mutex_unlock(&lock);
            continue; // Skip invalid types
        }

        event_list[i].event_type = event_type;
        event_list[i].record = rand() % (max_val - min_val + 1) + min_val;

        pthread_mutex_unlock(&lock);
    }
    return event_list;
}

// Example function to demonstrate memory deallocation and cleanup
void free_lists(CRC_INDICATION_REL8_TAG *crc_list, CELLULAR_EVENT_REL8_TAG *event_list, int N, int M) {
    if (crc_list != NULL) {
        free(crc_list);
    }
    if (event_list != NULL) {
        free(event_list);
    }
}

// Main function to demonstrate usage
int main() {
    init_rand();

    int N = 10; // Number of CRC_INDICATION_REL8_TAG structures
    int M = 15; // Number of CELLULAR_EVENT_REL8_TAG structures

    int min_val = 0;
    int max_val = 100;

    CRC_INDICATION_REL8_TAG *crc_list = create_crc_list(N, min_val, max_val);
    CELLULAR_EVENT_REL8_TAG *event_list = create_event_list(M, min_val, max_val);

    // Simulate some processing
    sleep(1); 

    // Cleanup
    free_lists(crc_list, event_list, N, M);
    pthread_mutex_destroy(&lock);

    return 0;
}
```

This code defines two structures representing different types of wireless communication events and functions to initialize and populate these lists. It uses mutex locks for thread safety during list population. The `create_crc_list` function initializes CRC_INDICATION_REL8_TAG structures, while the `create_event_list` validates event types against a set of predefined valid types. Memory is dynamically allocated for each structure, and random values are used to simulate real-world scenarios. Cleanup functions ensure proper memory deallocation.']

