#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INPUT_SIZE 1000
#define MAX_CHANNELS 20

typedef struct {
    int TX_ANTENNA_PORT;
    int CHANNEL_BANDWIDTH; // in MHz, possible values: 5, 10, 15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100
    double CENTER_FREQUENCY; // in GHz, typical range for NR: 0.4 to 6 GHz
    int TX_POWER_LEVEL; // in dBm, random value between -10 and +23 with predefined probabilities
} LTE_PHY_TESTER_CONFIG_T;

typedef struct {
    LTE_PHY_TESTER_CONFIG_T* configs;
    size_t count;
} ConfigSet;

void freeConfigSet(ConfigSet* set) {
    if (set->configs != NULL) {
        free(set->configs);
        set->configs = NULL;
    }
}

int validateFrequency(double freq) {
    return freq >= 0.4 && freq <= 6.0;
}

int validateChannelBandwidth(int bandwidth) {
    int valid_bandwidths[] = {5, 10, 15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100};
    for (size_t i = 0; i < sizeof(valid_bandwidths) / sizeof(int); ++i) {
        if (valid_bandwidths[i] == bandwidth) return 1;
    }
    return 0;
}

int randomTxPowerLevel() {
    int levels[] = {-10, -5, 0, 3, 7, 10, 13, 17, 20, 23};
    int probabilities[] = {10, 15, 20, 15, 10, 10, 10, 5, 3, 2}; // probabilities in percentage
    int totalProb = 0;
    for (size_t i = 0; i < sizeof(probabilities) / sizeof(int); ++i)
        totalProb += probabilities[i];

    int randomValue = rand() % totalProb + 1;
    int cumulativeProbability = 0;

    for (size_t i = 0; i < sizeof(levels) / sizeof(int); ++i) {
        cumulativeProbability += probabilities[i];
        if (randomValue <= cumulativeProbability)
            return levels[i];
    }
    return -10; // fallback in case of an error
}

int main(int argc, char* argv[]) {
    srand(time(NULL));

    size_t inputSize = MAX_INPUT_SIZE;
    double* inputs = malloc(inputSize * sizeof(double));
    if (inputs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    int numInputs = 0;
    double value;
    printf("Enter floating-point numbers for frequencies (0 to stop):\n");

    while (numInputs < inputSize && scanf("%lf", &value) == 1) {
        if (value == 0) break; // end of inputs
        if (!validateFrequency(value)) {
            fprintf(stderr, "Invalid frequency: %.2f\n", value);
            continue;
        }
        for (int i = 0; i < numInputs; ++i) {
            if (inputs[i] == value) {
                fprintf(stderr, "Duplicate frequency: %.2f\n", value);
                continue;
            }
        }
        inputs[numInputs++] = value;
    }

    if (numInputs > MAX_CHANNELS) {
        fprintf(stderr, "Too many frequencies entered.\n");
        free(inputs);
        return 1;
    }

    ConfigSet configSet;
    configSet.count = numInputs;
    configSet.configs = malloc(configSet.count * sizeof(LTE_PHY_TESTER_CONFIG_T));
    if (configSet.configs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(inputs);
        return 1;
    }

    for (size_t i = 0; i < configSet.count; ++i) {
        LTE_PHY_TESTER_CONFIG_T* config = &configSet.configs[i];

        // Set TX_ANTENNA_PORT randomly
        config->TX_ANTENNA_PORT = rand() % 4 + 1;

        // Set CHANNEL_BANDWIDTH randomly from valid options
        int bandwidthOptions[] = {5, 10, 15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100};
        config->CHANNEL_BANDWIDTH = bandwidthOptions[rand() % (sizeof(bandwidthOptions) / sizeof(int))];

        // Set CENTER_FREQUENCY from input
        config->CENTER_FREQUENCY = inputs[i];

        // Set TX_POWER_LEVEL based on predefined probability distribution
        config->TX_POWER_LEVEL = randomTxPowerLevel();
    }

    FILE* file = fopen("test_config.bin", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        freeConfigSet(&configSet);
        free(inputs);
        return 1;
    }

    size_t writtenBytes = fwrite(configSet.configs, sizeof(LTE_PHY_TESTER_CONFIG_T), configSet.count, file);

    if (writtenBytes != configSet.count) {
        fprintf(stderr, "Failed to write all configurations to the file\n");
    } else {
        printf("Configurations successfully serialized and written to 'test_config.bin'\n");
    }

    fclose(file);
    freeConfigSet(&configSet);
    free(inputs);

    return 0;
}
