#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

Record* create_records(size_t record_count, int key_min, int key_max, double value_min, double value_max) {
    if (record_count == 0 || key_min >= key_max) {
        return NULL;
    }

    // Seed random number generator
    srand(time(NULL));

    Record *records = malloc(record_count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        long offset;
        do {
            offset = rand() % ((long)record_count * 10); // Ensure unique offsets
        } while (offset <= 0 || find_offset(records, i, offset));

        records[i].offset = offset;
        records[i].key = key_min + rand() % (key_max - key_min + 1);
        records[i].value = value_min + ((double)rand() / RAND_MAX * (value_max - value_min));
    }

    // Shuffle to reduce memory access pattern predictability
    for (size_t i = record_count - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        Record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }

    return records;
}

int find_offset(Record *records, size_t count, long offset) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i].offset == offset) {
            return 1;
        }
    }
    return 0;
}

void free_records(Record *records) {
    free(records);
}

int main() {
    size_t record_count = 10000;
    int key_min = 1, key_max = 10;
    double value_min = -50.0, value_max = 50.0;

    Record *records = create_records(record_count, key_min, key_max, value_min, value_max);
    if (!records) {
        return EXIT_FAILURE;
    }

    // Further processing with the records

    free_records(records);
    return EXIT_SUCCESS;
}
```

### Design Choices and Trade-offs:

1. **Memory Allocation:**
   - Pre-allocated buffer is used to minimize allocation overhead.
   - `malloc` is used for simplicity; custom allocators could be considered for fragmentation handling.

2. **Unique Offsets:**
   - Random generation with a check ensures unique, non-zero offsets.
   - Offset range is scaled with record count to reduce collision probability.

3. **Randomization and Shuffling:**
   - Ensures varied memory access patterns to mitigate cache prediction issues.

4. **Error Handling:**
   - Checks for invalid inputs (e.g., zero or negative counts) and allocation failures.

5. **Performance Considerations:**
   - Trade-offs between direct per-record allocation and bulk allocation are considered.
   - Shuffling records post-creation helps in reducing predictable access patterns.

6. **Maintainability and Scalability:**
   - Modular design with separate functions for creation, searching, and freeing records.
   - Easy to extend or modify for different data processing needs.

This implementation balances efficiency, usability, and maintainability while addressing potential memory fragmentation issues.']

