        else if (strcmp(log_level_str, "WARNING") == 0) log_level = LOG_LEVEL_WARNING;
        else if (strcmp(log_level_str, "ERROR") == 0) log_level = LOG_LEVEL_ERROR;
    }
}

NFAPI_CRC_INDICATION_PDU_T* manage_crc_list(NFAPI_CRC_INDICATION_PDU_T **list, int *size) {
    set_log_level_from_env();

    NFAPI_CRC_INDICATION_PDU_T *new_entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed");
        return NULL;
    }

    // Simulating data filling
    new_entry->RX_UE_INFORMATION_TAG = rand() % 0xFFFF;
    new_entry->RNTI = rand() % 0xFFFF;
    new_entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

    validate_pdu(new_entry);

    if (*size >= MAX_ENTRIES) {
        log_message(LOG_LEVEL_WARNING, "Max entries reached, consider resizing or clearing list");
        free(new_entry);
        return NULL;
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*list, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        log_message(LOG_LEVEL_ERROR, "Memory reallocation failed");
        free(new_entry);
        return NULL;
    }

    (*list)[*size] = *new_entry;
    (*size)++;

    log_message(LOG_LEVEL_DEBUG, "New PDU added successfully");

    return new_entry;
}

void cleanup_crc_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    if (list && *list) {
        free(*list);
        *list = NULL;
    }
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    int pdu_size = 0;

    for (int i = 0; i < 100000; ++i) { // Simulating high-frequency data stream
        manage_crc_list(&pdu_list, &pdu_size);
    }

    cleanup_crc_list(&pdu_list);

    return 0;
}
