```c
#include <stdio.h>
#include <stdlib.h>
#include <libxml/parser.h>
#include <libxml/xmlschemas.h>

int parseAndValidateXmlDocument(const char* url, const char* xsdPath, size_t maxMemoryUsage) {
    if (!url || !xsdPath) return -1;

    xmlParserCtxtPtr ctxt = NULL;
    xmlDocPtr doc = NULL;
    xmlSchemaParserCtxtPtr schemaParserCtxt = NULL;
    xmlSchemaPtr schema = NULL;
    xmlSchemaValidCtxtPtr validCtxt = NULL;

    // Initialize libxml2
    LIBXML_TEST_VERSION

    // Load XML Schema
    schemaParserCtxt = xmlSchemaNewParserCtxt(xsdPath);
    if (schemaParserCtxt == NULL) {
        fprintf(stderr, "Failed to load XSD\n");
        return -1;
    }

    schema = xmlSchemaParse(schemaParserCtxt);
    xmlSchemaFreeParserCtxt(schemaParserCtxt);

    if (schema == NULL) {
        fprintf(stderr, "Failed to parse XSD\n");
        return -1;
    }

    // Set up the validation context
    validCtxt = xmlSchemaNewValidCtxt(schema);
    if (validCtxt == NULL) {
        fprintf(stderr, "Failed to create validation context\n");
        xmlSchemaFree(schema);
        return -1;
    }

    // Parse XML from network stream
    ctxt = xmlNewParserCtxt();
    if (ctxt == NULL) {
        fprintf(stderr, "Failed to create parser context\n");
        xmlSchemaFreeValidCtxt(validCtxt);
        xmlSchemaFree(schema);
        return -1;
    }

    doc = xmlCtxtReadFile(ctxt, url, NULL, XML_PARSE_NOENT | XML_PARSE_DTDLOAD);

    if (doc == NULL) {
        fprintf(stderr, "Failed to parse document\n");
        xmlFreeParserCtxt(ctxt);
        xmlSchemaFreeValidCtxt(validCtxt);
        xmlSchemaFree(schema);
        return -1;
    }

    // Validate the parsed document
    int ret = xmlSchemaValidateDoc(validCtxt, doc);

    if (ret != 0) {
        fprintf(stderr, "Validation error\n");
    } else {
        printf("Document is valid\n");
    }

    // Clean up
    xmlFreeDoc(doc);
    xmlSchemaFreeValidCtxt(validCtxt);
    xmlSchemaFree(schema);
    xmlCleanupParser();

    return ret == 0 ? 0 : -1;
}
