typedef struct {
    uint32_t frame_type;
    uint32_t channel_type;
} PduConfig;

void parse_yaml_config(const char *filename, PduConfig *configurations, size_t *count) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open config file: %s", filename);
        return;
    }

    yaml_parser_t parser;
    if (!yaml_parser_initialize(&parser)) {
        log_error("Failed to initialize YAML parser.");
        fclose(file);
        return;
    }

    yaml_parser_set_input_file(&parser, file);

    yaml_event_t event;
    int done = 0;

    *count = 0;
    while (!done) {
        if (!yaml_parser_parse(&parser, &event)) {
            log_error("YAML parsing error: %s", parser.problem);
            break;
        }

        switch (event.type) {
            case YAML_MAPPING_START_EVENT:
                // Handle mapping start
                break;

            case YAML_SEQUENCE_START_EVENT:
                // Handle sequence start
                break;

            case YAML_SCALAR_EVENT:
                if (*count < MAX_PDU_COUNT) {
                    yaml_parser_get_timestamp(&parser);
                    uint32_t frame_type = atol(event.data.scalar.value);
                    yaml_parser_get_timestamp(&parser);
                    uint32_t channel_type = atol(event.data.scalar.value);

                    configurations[*count].frame_type = frame_type;
                    configurations[*count].channel_type = channel_type;

                    (*count)++;
                } else {
                    log_warning("Exceeded maximum PDU count.");
                }
                break;

            case YAML_MAPPING_END_EVENT:
            case YAML_SEQUENCE_END_EVENT:
                done = 1;
                break;

            default:
                // Handle other events
                break;
        }

        yaml_event_delete(&event);
    }

    yaml_parser_delete(&parser);
    fclose(file);
}

