        pdus[i].pdu_header.channel_type = configurations[i].channel_type;

        generate_mac_header(&pdus[i], i);

        if (!nfa_api_add_pdu(pdus + i, 1)) {
            log_error("Failed to add PDU at index %zu", i);
        }
    }
}

