#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <unistd.h>

#define MAX_TASKS 100

typedef struct {
    void (*callback)(void* data);
    void *data;
    int frequency; // in seconds
    int priority;
    time_t next_run_time;
} TaskDescriptor;

typedef struct {
    TaskDescriptor tasks[MAX_TASKS];
    size_t task_count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} TaskQueue;

TaskQueue* create_task_queue() {
    TaskQueue *queue = (TaskQueue*)malloc(sizeof(TaskQueue));
    queue->task_count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    return queue;
}

void destroy_task_queue(TaskQueue *queue) {
    free(queue);
}

int load_tasks_from_json(const char *filename, TaskQueue *queue) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    struct json_object *parsed_json;
    struct json_object *tasks_obj;

    parsed_json = json_object_from_file(file);
    fclose(file);

    if (json_object_object_get_ex(parsed_json, "tasks", &tasks_obj)) {
        size_t n_tasks = json_object_array_length(tasks_obj);
        for (size_t i = 0; i < n_tasks && queue->task_count < MAX_TASKS; ++i) {
            struct json_object *task_obj;
            json_object_array_get_idx(tasks_obj, i, &task_obj);

            TaskDescriptor task;
            task.frequency = json_object_get_int(json_object_object_get_ex(task_obj, "frequency", NULL));
            task.priority = json_object_get_int(json_object_object_get_ex(task_obj, "priority", NULL));

            // Simplified: Assume callback and data are predefined
            task.callback = some_callback_function; 
            task.data = some_data;

            task.next_run_time = time(NULL) + task.frequency;
            pthread_mutex_lock(&queue->lock);
            queue->tasks[queue->task_count++] = task;
            pthread_mutex_unlock(&queue->lock);
        }
    }

    json_object_put(parsed_json);
    return 0;
}

void* task_scheduler(void *arg) {
    TaskQueue *queue = (TaskQueue*)arg;

    while (1) {
        time_t now = time(NULL);

        pthread_mutex_lock(&queue->lock);
        for (size_t i = 0; i < queue->task_count; ++i) {
            if (now >= queue->tasks[i].next_run_time) {
                queue->tasks[i].callback(queue->tasks[i].data);
                queue->tasks[i].next_run_time = now + queue->tasks[i].frequency;
            }
        }
        pthread_mutex_unlock(&queue->lock);

        // Sleep for a short duration to reduce CPU usage
        usleep(100000); 
    }

    return NULL;
}

int main() {
    TaskQueue *task_queue = create_task_queue();

    if (load_tasks_from_json("tasks.json", task_queue) != 0) {
        fprintf(stderr, "Failed to load tasks\n");
        destroy_task_queue(task_queue);
        return EXIT_FAILURE;
    }

    pthread_t scheduler_thread;
    pthread_create(&scheduler_thread, NULL, task_scheduler, task_queue);

    // Wait for the thread to finish (in real applications, use a signal or condition)
    pthread_join(scheduler_thread, NULL);

    destroy_task_queue(task_queue);
    return 0;
}
```

