NETWORK_STATISTIC_TAG networkStats[MAX_INTERFACES];
int initializedInterfaces = 0;

void initializeNetworkStatistics() {
    for (int i = 0; i < MAX_INTERFACES; ++i) {
        snprintf(networkStats[i].interfaceName, sizeof(networkStats[i].interfaceName), "Interface_%d", i + 1);
        networkStats[i].byteCount = 0;
        networkStats[i].packetCount = 0;
        networkStats[i].packetLossPercentage = 0.0f;
    }
}

int executeCommand(const char *command, char *const argv[]) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0; // Error during fork
    } else if (pid > 0) { 
        int status;
        waitpid(pid, &status, 0); // Wait for the child process to finish
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    } else {
        execvp(command, argv);
        perror("execvp");
        exit(EXIT_FAILURE);
    }
}

int updateNetworkStatistics() {
    char *command = "update_network_status"; // Placeholder command
    char *args[] = { command, NULL };

    if (executeCommand(command, args)) {
        return 1;
    } else {
        fprintf(stderr, "Failed to execute the network update command.\n");
        return 0;
    }
}

int initNetworkMonitor() {
    initializeNetworkStatistics();

    while (initializedInterfaces < MAX_INTERFACES) {
        if (updateNetworkStatistics()) {
            initializedInterfaces++;
        } else {
            // Fallback: Use stale data
            fprintf(stderr, "Using stale data for interface %d.\n", initializedInterfaces + 1);
        }

        sleep(UPDATE_INTERVAL);
    }

    return initializedInterfaces == MAX_INTERFACES;
}
