#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define DEFAULT_CAPACITY 1000
#define LOAD_FACTOR_THRESHOLD 0.7

typedef struct HashNode {
    char *key;
    int value;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    HashNode **buckets;
    size_t capacity;
    size_t count;
} HashTable;

unsigned long hash_function(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

HashTable* create_hash_table() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = DEFAULT_CAPACITY;
    table->count = 0;
    table->buckets = (HashNode**)calloc(table->capacity, sizeof(HashNode*));
    return table;
}

void free_hash_node(HashNode *node) {
    if (node) {
        free(node->key);
        free(node);
    }
}

void resize_hash_table(HashTable *table);

void hash_table_insert(HashTable *table, const char *key, int value) {
    unsigned long index = hash_function(key, table->capacity);
    HashNode *node = table->buckets[index];

    while (node) {
        if (strcmp(node->key, key) == 0) {
            node->value = value;
            return;
        }
        node = node->next;
    }

    HashNode *new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->count++;

    if ((double)table->count / table->capacity > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; i++) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free_hash_node(temp);
        }
    }
    free(table->buckets);
    free(table);
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashNode **new_buckets = (HashNode**)calloc(new_capacity, sizeof(HashNode*));

    for (size_t i = 0; i < table->capacity; i++) {
        HashNode *node = table->buckets[i];
        while (node) {
            unsigned long new_index = hash_function(node->key, new_capacity);
            HashNode *next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

typedef struct ListNode {
    long timestamp;
    int opcode;
    struct ListNode *prev, *next;
} ListNode;

ListNode* create_list_node(long timestamp, int opcode) {
    ListNode *node = (ListNode*)malloc(sizeof(ListNode));
    node->timestamp = timestamp;
    node->opcode = opcode;
    node->prev = node->next = NULL;
    return node;
}

void free_list_node(ListNode *node) {
    if (node) free(node);
}

typedef struct DoublyLinkedList {
    ListNode *head, *tail;
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = list->tail = NULL;
    return list;
}

void insert_in_order(DoublyLinkedList *list, long timestamp, int opcode) {
    ListNode *new_node = create_list_node(timestamp, opcode);

    if (!list->head || list->head->timestamp >= timestamp) {
        new_node->next = list->head;
        if (list->head) list->head->prev = new_node;
        list->head = new_node;
        if (!list->tail) list->tail = new_node;
        return;
    }

    ListNode *current = list->head;
    while (current->next && current->next->timestamp < timestamp) {
        current = current->next;
    }

    new_node->next = current->next;
    if (current->next) current->next->prev = new_node;
    current->next = new_node;
    new_node->prev = current;

    if (!new_node->next) list->tail = new_node;
}

void free_doubly_linked_list(DoublyLinkedList *list) {
    ListNode *current = list->head;
    while (current) {
        ListNode *temp = current;
        current = current->next;
        free_list_node(temp);
    }
    free(list);
}

long find_most_recent_operation(DoublyLinkedList *list, int opcode) {
    long most_recent_timestamp = -1;
    ListNode *current = list->head;

    while (current) {
        if (current->opcode == opcode) {
            most_recent_timestamp = current->timestamp;
        }
        current = current->next;
    }

    return most_recent_timestamp;
}

void process_operations() {
    HashTable *hash_table = create_hash_table();
    DoublyLinkedList *operation_list = create_doubly_linked_list();
    long most_recent_128_timestamp = -1;

    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        long timestamp;
        int opcode;
        char key[129];

        if (sscanf(line, "%ld %d %[^\n]", &timestamp, &opcode, key) == 3) {
            insert_in_order(operation_list, timestamp, opcode);
            hash_table_insert(hash_table, key, opcode);

            most_recent_128_timestamp = find_most_recent_operation(operation_list, 128);
        }
    }

    printf("Most recent operation code 128: %ld\n", most_recent_128_timestamp);

    free_doubly_linked_list(operation_list);
    free_hash_table(hash_table);
}

int main() {
    process_operations();
    return 0;
}
