#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_KEYS 65536
#define OFFSET_ARRAY_SIZE 10000

typedef struct {
    // Define your structure here as per NFAPI_MESSAGE_PDU_T requirements.
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    double SNR_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_PDU_T;

typedef struct record {
    atomic_long *offset_ptr;
    int key;
    struct record *next;
} record_t;

atomic_int max_key = 0;
record_t* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long offsets[OFFSET_ARRAY_SIZE];
int *keys_array = NULL;
size_t keys_count = 0;

void initialize_offsets() {
    for (int i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        offsets[i] = i;
    }
}

int add_key(int key) {
    if (key < 0 || key >= MAX_KEYS) return -1;
    for (size_t i = 0; i < keys_count; ++i) {
        if (keys_array[i] == key) return -1;
    }
    int* new_keys_array = realloc(keys_array, (keys_count + 1) * sizeof(int));
    if (!new_keys_array) return -1;
    keys_array = new_keys_array;
    keys_array[keys_count++] = key;
    return 0;
}

void insert_record(atomic_long *offset_ptr, int key) {
    record_t* new_record = malloc(sizeof(record_t));
    if (!new_record) return;

    new_record->offset_ptr = offset_ptr;
    new_record->key = key;
    new_record->next = NULL;

    pthread_mutex_lock(&lock);
    new_record->next = head;
    head = new_record;
    if (atomic_load_explicit(&max_key, memory_order_relaxed) < key) {
        atomic_store_explicit(&max_key, key, memory_order_release);
    }
    pthread_mutex_unlock(&lock);
}

void process_input(int expected_records) {
    int key;
    for (size_t i = 0; i < keys_count; ++i) {
        if (scanf("%d", &key) != 1 || add_key(key)) {
            fprintf(stderr, "Invalid or duplicate key\n");
            exit(EXIT_FAILURE);
        }
    }

    if (keys_count != expected_records) {
        fprintf(stderr, "Number of keys does not match the expected number\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < keys_count; ++i) {
        atomic_long *offset_ptr = &offsets[i];
        insert_record(offset_ptr, keys_array[i]);
    }
}

void free_records() {
    record_t* current = head;
    while (current) {
        record_t* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <expected_records>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int expected_records = atoi(argv[1]);
    initialize_offsets();
    keys_array = malloc(sizeof(int) * expected_records);
    if (!keys_array) {
        perror("Failed to allocate memory for keys");
        return EXIT_FAILURE;
    }

    process_input(expected_records);

    printf("Maximum key: %d\n", atomic_load_explicit(&max_key, memory_order_relaxed));

    free_records();
    free(keys_array);
    return EXIT_SUCCESS;
}
