// Function to update statistics using a rolling window algorithm
void update_statistics(PHY_TRANSPORT_CHANNEL_STATS_T *array, int num_elements) {
    if (!array || num_elements <= 0) {
        log_message("Error: Invalid input data.");
        return;
    }

    const int window_size = 10;
    float quality_measurements[window_size] = {0.0f};
    float noise_measurements[window_size] = {0.0f};

    for (int i = 0; i < num_elements; ++i) {
        // Simulate new measurement data
        float new_quality_measurement = rand() % 100 / 10.0f;
        float new_noise_measurement = rand() % 100 / 10.0f;

        // Update the rolling window for quality and noise
        for (int j = 0; j < window_size - 1; ++j) {
            quality_measurements[j] = quality_measurements[j + 1];
            noise_measurements[j] = noise_measurements[j + 1];
        }

        quality_measurements[window_size - 1] = new_quality_measurement;
        noise_measurements[window_size - 1] = new_noise_measurement;

        // Calculate moving averages
        float avg_quality = 0.0f, avg_noise = 0.0f;
        for (int j = 0; j < window_size; ++j) {
            avg_quality += quality_measurements[j];
            avg_noise += noise_measurements[j];
        }

        array[i].RECEIVED_QUALITY_INDICATOR = avg_quality / window_size;
        array[i].CHANNEL_NOISE = avg_noise / window_size;

        // Simulate TX power level adjustment
        array[i].TX_POWER_LEVEL = (array[i].TX_POWER_LEVEL + rand() % 3 - 1) % 10 + 1;
    }

    log_message("Statistics updated successfully.");
}

