#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPI_CARDS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t available_count;
} MemoryPool;

MemoryPool* create_memory_pool(size_t pool_size) {
    MemoryPool* mem_pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mem_pool) return NULL;

    mem_pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mem_pool->pool) {
        free(mem_pool);
        return NULL;
    }

    mem_pool->pool_size = pool_size;
    pthread_mutex_init(&mem_pool->lock, NULL);
    pthread_cond_init(&mem_pool->cond, NULL);
    mem_pool->available_count = pool_size;

    return mem_pool;
}

void destroy_memory_pool(MemoryPool* mem_pool) {
    if (mem_pool) {
        free(mem_pool->pool);
        pthread_mutex_destroy(&mem_pool->lock);
        pthread_cond_destroy(&mem_pool->cond);
        free(mem_pool);
    }
}

int populate_nfaapi_crc_list(size_t N, MemoryPool* mem_pool, unsigned int seed, size_t max_concurrent_allocations) {
    if (!mem_pool || !mem_pool->pool || N > mem_pool->pool_size) return -1;

    pthread_mutex_lock(&mem_pool->lock);

    srand(seed);
    size_t allocated_count = 0;
    while (allocated_count < N && mem_pool->available_count > 0) {
        if (allocated_count >= max_concurrent_allocations) {
            pthread_cond_wait(&mem_pool->cond, &mem_pool->lock);
        }

        for (size_t i = 0; i < N && allocated_count < N; ++i) {
            if (!mem_pool->pool[i].RX_UE_INFORMATION_TAG) { // Assume uninitialized structures have a default value
                mem_pool->pool[i].RX_UE_INFORMATION_TAG = rand() % 100;
                mem_pool->pool[i].RNTI = rand() % 1000;
                mem_pool->pool[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
                mem_pool->pool[i].CRCFLAG = rand() % 2;

                allocated_count++;
                mem_pool->available_count--;
            }
        }

        pthread_cond_signal(&mem_pool->cond);
    }

    if (allocated_count < N) {
        pthread_mutex_unlock(&mem_pool->lock);
        return -2; // Allocation failed
    }

    pthread_mutex_unlock(&mem_pool->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_populated_list(MemoryPool* mem_pool, size_t N, unsigned int seed, size_t max_concurrent_allocations) {
    if (populate_nfaapi_crc_list(N, mem_pool, seed, max_concurrent_allocations) != 0) {
        return NULL;
    }

    pthread_mutex_lock(&mem_pool->lock);
    while (mem_pool->available_count == mem_pool->pool_size) {
        pthread_cond_wait(&mem_pool->cond, &mem_pool->lock);
    }
    pthread_mutex_unlock(&mem_pool->lock);

    return mem_pool->pool;
}

int main() {
    size_t N = 100;
    unsigned int seed = 42;
    size_t max_concurrent_allocations = 10;

    MemoryPool* mem_pool = create_memory_pool(N * MAX_NFAPI_CARDS);
    if (!mem_pool) {
        printf("Failed to create memory pool\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = get_populated_list(mem_pool, N, seed, max_concurrent_allocations);
    if (!list) {
        printf("Failed to populate list\n");
    } else {
        // Use the populated list
        for (size_t i = 0; i < N; ++i) {
            printf("Structure %zu: RX=%d, RNTI=%d, CRC_TAG=%d, CRCFLAG=%d\n",
                   i,
                   list[i].RX_UE_INFORMATION_TAG,
                   list[i].RNTI,
                   list[i].CRC_INDICATION_REL8_TAG,
                   list[i].CRCFLAG);
        }
    }

    destroy_memory_pool(mem_pool);

    return 0;
}
```

### Key Points:
- **Memory Management**: A `MemoryPool` structure is used to manage the memory pool, including synchronization with a mutex and condition variable.
- **Thread Safety**: Mutexes ensure that only one thread can modify shared resources at a time. The condition variable helps manage backpressure when resource limits are approached.
- **Error Handling**: If allocation fails or if the number of requested structures exceeds available capacity, appropriate error codes are returned.
- **Randomization**: `srand` and `rand` are used to set random values for structure fields based on a given seed. This ensures repeatability with the same seed.
- **Performance Considerations**: The implementation uses a single lock for simplicity but could be optimized further by using more granular locks if contention becomes an issue.']

