    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_pdu_to_list(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !pthread_mutex_lock(&list->lock)) {
        fprintf(stderr, "Error locking PduList\n");
        return -1;
    }

    // Check for unique RNTI
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            fprintf(stderr, "Duplicate RNTI found\n");
            return -1;
        }
    }

    // Resize if necessary
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 4;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
