    memcpy(buffer, &record->offset, sizeof(record->offset));
    memcpy(buffer + sizeof(record->offset), &record->key, sizeof(record->key));
    memcpy(buffer + sizeof(record->offset) + sizeof(record->key), &record->timestamp, sizeof(record->timestamp));
    memcpy(buffer + sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp), record->id, MAX_ID_LENGTH);
    unsigned int checksum = calculate_checksum(record, sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp) + MAX_ID_LENGTH);
    memcpy(buffer + sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp) + MAX_ID_LENGTH, &checksum, CHECKSUM_SIZE);
    *length = sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp) + MAX_ID_LENGTH + CHECKSUM_SIZE;
}

int deserialize_record(const unsigned char *buffer, Record *record) {
    if (buffer == NULL || record == NULL) return -1;

    memcpy(&record->offset, buffer, sizeof(record->offset));
    memcpy(&record->key, buffer + sizeof(record->offset), sizeof(record->key));
    memcpy(&record->timestamp, buffer + sizeof(record->offset) + sizeof(record->key), sizeof(record->timestamp));
    memcpy(record->id, buffer + sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp), MAX_ID_LENGTH);

    unsigned int stored_checksum;
    memcpy(&stored_checksum, buffer + sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp) + MAX_ID_LENGTH, CHECKSUM_SIZE);

    unsigned int calculated_checksum = calculate_checksum(buffer, sizeof(record->offset) + sizeof(record->key) + sizeof(record->timestamp) + MAX_ID_LENGTH);

    return stored_checksum == calculated_checksum ? 0 : -1;
}

void *parse_csv_file(void *arg) {
    char **file_paths = (char **)arg;
    RecordArray *record_array = malloc(sizeof(RecordArray));
    record_array->records = NULL;
    record_array->count = 0;
    pthread_mutex_init(&record_array->lock, NULL);

    FILE *fp;
    char line[1024];

    for (int i = 0; file_paths[i] != NULL; ++i) {
        fp = fopen(file_paths[i], "r");
        if (!fp) continue;

        while (fgets(line, sizeof(line), fp)) {
            Record record;
            char *token = strtok(line, ",");

            if (sscanf(token++, "%ld", &record.offset) != 1 || 
                sscanf(token++, "%d", &record.key) != 1 ||
                sscanf(token++, "%lf", &record.timestamp) != 1 ||
                token == NULL) {
                continue;
            }
            strncpy(record.id, token, MAX_ID_LENGTH - 1);
            record.id[MAX_ID_LENGTH - 1] = '\0';

            unsigned char buffer[1024];
            size_t length;
            serialize_record(&record, buffer, &length);

            pthread_mutex_lock(&record_array->lock);
            record_array->records = realloc(record_array->records, (record_array->count + 1) * sizeof(Record));
            memcpy(record_array->records + record_array->count, buffer, length);
            record_array->count++;
            pthread_mutex_unlock(&record_array->lock);
        }

        fclose(fp);
    }

    return (void *)record_array;
}

RecordArray* parse_multiple_csv_files_concurrently(char **file_paths) {
    int num_threads = 0;
    while (file_paths[num_threads] != NULL) ++num_threads;

    pthread_t threads[num_threads];
    RecordArray *results = malloc(num_threads * sizeof(RecordArray));

    for (int i = 0; i < num_threads; ++i) {
        char **files_to_process = &file_paths[i];
        if (!pthread_create(&threads[i], NULL, parse_csv_file, files_to_process)) {
            results[i] = *(RecordArray *)parse_csv_file((void *)files_to_process);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return results;
}
