#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY_THRESHOLD 1024 * 1024 // Example: 1MB threshold
#define MEMORY_POOL_SIZE 64

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_FLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void **pool;
    size_t pool_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {0};

void initialize_memory_pool() {
    memory_pool.pool = malloc(MEMORY_POOL_SIZE * sizeof(void *));
    memory_pool.pool_size = MEMORY_POOL_SIZE;
    memory_pool.used_size = 0;
    pthread_mutex_init(&memory_pool.lock, NULL);
}

void* pool_allocate(size_t size) {
    if (size > MAX_MEMORY_THRESHOLD || memory_pool.used_size + size > MEMORY_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL; // Out of memory
    }
    void *ptr = malloc(size);
    pthread_mutex_lock(&memory_pool.lock);
    memory_pool.pool[memory_pool.used_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)] = ptr;
    memory_pool.used_size += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* createNfadWithConstraints(size_t max_memory) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **tail = &head;
    initialize_memory_pool();

    while (memory_pool.used_size < max_memory) {
        NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*) pool_allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) break;

        node->RX_UE_INFORMATION_TAG = rand() % 10000; // Example generation
        node->RNTI = rand() % 1000000; // Example generation
        node->CRC_FLAG = rand() & 1; // Random CRCFLAG

        *tail = node;
        tail = &(node->next);
    }

    return head;
}

void serializeNfad(NFAPI_CRC_INDICATION_PDU_T* head, FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* deserializeNfad(FILE* file, size_t max_memory) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **tail = &head;
    initialize_memory_pool();

    while (memory_pool.used_size < max_memory) {
        NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*) pool_allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node || fread(node, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) break;

        *tail = node;
        tail = &(node->next);
    }

    return head;
}

