    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

void initialize_list(DynamicList* list) {
    list->head = NULL;
    list->count = 0;
    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        exit(EXIT_FAILURE);
    }
}

bool add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->mutex);
        return false; // Graceful degradation
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        perror("Failed to allocate memory");
        return false;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool remove_from_list(DynamicList* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.crc_info.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return false; // Element not found
    }

    if (prev == NULL) { // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->count--;

    pthread_mutex_unlock(&list->mutex);
    return true;
}

void cleanup_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);

    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
}

void destroy_list(DynamicList* list) {
    cleanup_list(list);
    if (pthread_mutex_destroy(&list->mutex) != 0) {
        perror("Mutex destruction failed");
    }
}

// Demonstrative example of unsafe code

typedef struct UnsafeNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct UnsafeNode* next;
} UnsafeNode;

typedef struct {
    UnsafeNode* head;
} UnsafeList;

void add_unsafely(UnsafeList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    UnsafeNode* new_node = (UnsafeNode*)malloc(sizeof(UnsafeNode));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = list->head; // Potential race condition
    list->head = new_node;       // If multiple threads access concurrently, corruption may occur
}

// Safe Implementation Considerations:
// - Using mutexes to protect shared resources prevents race conditions.
// - Limiting structure count avoids excessive memory use and potential leaks.
// - Structured cleanup ensures all allocated nodes are freed.

int main() {
    DynamicList list;
    initialize_list(&list);

    NFAPI_CRC_INDICATION_PDU_T data = {{.RX_UE_INFORMATION_TAG = 1, .RNTI = 1001}};
    add_to_list(&list, data);

    remove_from_list(&list, 1);

    destroy_list(&list);

    return 0;
}
```

### Key Features:
- **Concurrency Management**: Uses `pthread_mutex_t` for thread safety.
- **Resource Management**: Limits maximum structures with `MAX_STRUCTURES`.
- **Error Handling and Logging**: Returns error status on failure; logs errors using `perror`.
- **Memory Usage Optimization**: Reuses list count and structured cleanup to minimize dynamic allocation overhead.
- **Dependency Management**: Requires POSIX threads library (`pthread`).
- **Edge Case Handling**: Gracefully handles full list scenario without crashing.

The unsafe code example highlights the importance of synchronization mechanisms in preventing race conditions, which are mitigated by mutex locks in the safe implementation.']

