#include "signal_processing_library.h"  // Assume this is the external library

#define MAX_UE_COUNT 1000
#define SNR_SAMPLING_RATE 10.0f  // Hz, adjust as needed

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    float SNR;
    float CRC_INDICATION_REL8_TAG;
} UE_SNR_INFO_T;

pthread_mutex_t ue_list_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_MESSAGE_PDU_T ue_list[MAX_UE_COUNT];
int current_ue_count = 0;
float noise_factor[MAX_UE_COUNT];

// Simulated radio channel model
float simulate_channel(float signal, int index) {
    // Add random noise to the signal
    float noise = (rand() % 100) / 100.0f - 0.5f;  // Noise between -0.5 and +0.5
    return signal + noise_factor[index] * noise;
}

// Function to apply advanced filtering techniques using external library
float filter_snr(float snr) {
    return apply_advanced_filtering(snr);  // Assume this function is provided by the library
}

void* ue_list_manager(void* arg) {
    while (1) {
        pthread_mutex_lock(&ue_list_lock);

        for (int i = 0; i < current_ue_count; ++i) {
            float signal_strength = (float)(rand() % 100); // Simulated signal strength
            float raw_snr = simulate_channel(signal_strength, i);

            ue_list[i].SNR = filter_snr(raw_snr);
        }

        pthread_mutex_unlock(&ue_list_lock);

        sleep(1 / SNR_SAMPLING_RATE);
    }
    return NULL;
}

void initialize_ues(int n) {
    if (n > MAX_UE_COUNT) {
        fprintf(stderr, "Exceeded maximum UE capacity.\n");
        return;
    }

    pthread_t manager_thread;
    pthread_create(&manager_thread, NULL, ue_list_manager, NULL);

    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&ue_list_lock);

        ue_list[i].RX_UE_INFORMATION_TAG = rand(); // Simulated tag
        ue_list[i].RNTI = rand() % 65536;          // RNTI must be within a valid range

        noise_factor[i] = (rand() % 100) / 50.0f - 1.0f;  // Noise factor between -2 and +0

        pthread_mutex_unlock(&ue_list_lock);
    }

    current_ue_count = n;
}

void update_ues(int add_remove_flag, int ue_index) {
    pthread_mutex_lock(&ue_list_lock);

    if (add_remove_flag == 1 && current_ue_count < MAX_UE_COUNT) { // Add UE
        ue_list[current_ue_count].RX_UE_INFORMATION_TAG = rand();
        ue_list[current_ue_count].RNTI = rand() % 65536;
        noise_factor[current_ue_count] = (rand() % 100) / 50.0f - 1.0f;

        current_ue_count++;
    } else if (add_remove_flag == 0 && ue_index >= 0 && ue_index < current_ue_count) { // Remove UE
        for (int i = ue_index; i < current_ue_count - 1; ++i) {
            ue_list[i] = ue_list[i + 1];
            noise_factor[i] = noise_factor[i + 1];
        }
        current_ue_count--;
    }

    pthread_mutex_unlock(&ue_list_lock);
}

void log_performance(const char* level, const char* message) {
    if (strcmp(level, "INFO") == 0 || strcmp(level, "DEBUG") == 0) {
        printf("[%s] %s\n", level, message);
    }
}

int main() {
    srand(time(NULL));

    initialize_ues(100);

    // Simulate adding and removing UEs
    sleep(5);
    update_ues(1, -1);  // Add a UE

    sleep(5);
    update_ues(0, 10);  // Remove the UE at index 10

    return 0;
}
