```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define BUFFER_POOL_SIZE 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    int value;
    long offset;
    int key;
    double data;
} record;

record *buffer_pool[BUFFER_POOL_SIZE];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Logger structure
typedef struct {
    FILE *file;
    int level;
} logger;

logger log;

void init_logger(const char *filename, int level) {
    log.file = fopen(filename, "a");
    if (!log.file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log.level = level;
}

void log_message(int level, const char *message) {
    if (level >= log.level) {
        fprintf(log.file, "%s\n", message);
        fflush(log.file);
    }
}

record* allocate_record() {
    pthread_mutex_lock(&pool_lock);

    for (int i = 0; i < BUFFER_POOL_SIZE; ++i) {
        if (!buffer_pool[i]) {
            buffer_pool[i] = malloc(sizeof(record));
            if (!buffer_pool[i]) {
                log_message(LOG_LEVEL_ERROR, "Memory allocation failed");
                pthread_mutex_unlock(&pool_lock);
                return NULL;
            }
            pthread_mutex_unlock(&pool_lock);
            return buffer_pool[i];
        }
    }

    pthread_mutex_unlock(&pool_lock);
    log_message(LOG_LEVEL_ERROR, "Buffer pool exhausted");
    return NULL;
}

void free_record(record *rec) {
    if (rec) {
        int index = -1;
        for (int i = 0; i < BUFFER_POOL_SIZE; ++i) {
            if (buffer_pool[i] == rec) {
                index = i;
                break;
            }
        }
        if (index != -1) {
            pthread_mutex_lock(&pool_lock);
            free(buffer_pool[index]);
            buffer_pool[index] = NULL;
            pthread_mutex_unlock(&pool_lock);
        } else {
            log_message(LOG_LEVEL_ERROR, "Attempting to free untracked record");
            free(rec);
        }
    }
}

void initialize_record(record *rec) {
    rec->value = rand() % 1000;
    rec->offset = rand() % 1000000L;
    rec->key = rand() % 10000;
    rec->data = (double)rand() / RAND_MAX * 100.0;
}

void* process_dataset(void *arg) {
    record **records = (record **)arg;
    size_t num_records = *((size_t *)(((char*)arg) + sizeof(record *)));

    for (size_t i = 0; i < num_records; ++i) {
        initialize_record(records[i]);
    }

    log_message(LOG_LEVEL_INFO, "Batch processing completed");

    return NULL;
}

void process_in_parallel(record **datasets, size_t num_datasets, size_t records_per_dataset) {
    pthread_t threads[num_datasets];
    for (size_t i = 0; i < num_datasets; ++i) {
        if (pthread_create(&threads[i], NULL, process_dataset, datasets + i * records_per_dataset)) {
            log_message(LOG_LEVEL_ERROR, "Failed to create thread");
        }
    }

    for (size_t i = 0; i < num_datasets; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));

    init_logger("app.log", LOG_LEVEL_INFO);

    size_t total_records = MAX_RECORDS;
    size_t datasets_per_thread = 10;
    record **datasets = malloc(datasets_per_thread * sizeof(record *));
    if (!datasets) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for dataset pointers");
        return EXIT_FAILURE;
    }

    pthread_mutex_lock(&pool_lock);
    for (size_t i = 0; i < datasets_per_thread; ++i) {
        record *record_set = malloc(total_records / datasets_per_thread * sizeof(record *));
        if (!record_set) {
            log_message(LOG_LEVEL_ERROR, "Memory allocation failed for records");
            break;
        }
        for (size_t j = 0; j < total_records / datasets_per_thread; ++j) {
            record_set[j] = allocate_record();
            if (!record_set[j]) {
                log_message(LOG_LEVEL_ERROR, "Failed to allocate record from pool");
                free(record_set);
                break;
            }
        }
        datasets[i] = record_set;
    }
    pthread_mutex_unlock(&pool_lock);

    process_in_parallel(datasets, datasets_per_thread, total_records / datasets_per_thread);

    for (size_t i = 0; i < datasets_per_thread; ++i) {
        for (size_t j = 0; j < total_records / datasets_per_thread; ++j) {
            free_record(datasets[i][j]);
        }
        free(datasets[i]);
    }

    free(datasets);
    fclose(log.file);

    return EXIT_SUCCESS;
}
```

### Key Aspects:
- **Buffer Pool Management:** Uses a fixed-size buffer pool to manage memory allocation, reducing fragmentation and improving performance.
- **Thread Safety:** Ensures safe access to shared resources using mutexes.
- **Logging System:** Provides flexible logging with configurable levels for both file-based and console outputs.
- **Error Handling:** Gracefully manages errors in memory allocation and thread creation with detailed logs.
- **Concurrency:** Processes multiple datasets in parallel using POSIX threads, ensuring efficient resource utilization.']

