#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

// Assuming MAC_RLCENTITY_T and MAC_PHYCONTEXT_T are defined somewhere
typedef struct {
    // Fields for MAC_RLCENTITY_T
} MAC_RLCENTITY_T;

typedef struct {
    // Fields for MAC_PHYCONTEXT_T
} MAC_PHYCONTEXT_T;

typedef struct {
    MAC_RLCENTITY_T rlc_entity;
    MAC_PHYCONTEXT_T phy_context;
    uint8_t *buffer;
    size_t buffer_size;
} MAC_CONTEXT_T;

typedef struct Node {
    MAC_CONTEXT_T *context;
    struct Node* next;
} Node;

typedef struct {
    atomic_uintptr_t head;
    atomic_uintptr_t tail;
    pthread_mutex_t mutex;
} LockFreeQueue;

// Function prototypes
void init_queue(LockFreeQueue *queue);
int enqueue(LockFreeQueue *queue, MAC_CONTEXT_T *context);
MAC_CONTEXT_T* dequeue(LockFreeQueue *queue);
void destroy_context(MAC_CONTEXT_T *context);

LockFreeQueue mac_context_queue;

void manage_mac_contexts() {
    // Initialize the queue
    init_queue(&mac_context_queue);

    // Example usage: Enqueuing and dequeuing contexts
    MAC_CONTEXT_T *new_context = malloc(sizeof(MAC_CONTEXT_T));
    new_context->buffer_size = 1024; // Example buffer size
    new_context->buffer = malloc(new_context->buffer_size);

    // Fill in the fields for rlc_entity and phy_context as needed

    enqueue(&mac_context_queue, new_context);

    MAC_CONTEXT_T *dequeued_context = dequeue(&mac_context_queue);
    if (dequeued_context) {
        destroy_context(dequeued_context);
        free(dequeued_context);
    }

    // Destroy remaining contexts in the queue
    while ((dequeued_context = dequeue(&mac_context_queue))) {
        destroy_context(dequeued_context);
        free(dequeued_context);
    }
}

void init_queue(LockFreeQueue *queue) {
    atomic_store_uintptr(&(queue->head), 0);
    atomic_store_uintptr(&(queue->tail), 0);
    pthread_mutex_init(&(queue->mutex), NULL);
}

int enqueue(LockFreeQueue *queue, MAC_CONTEXT_T *context) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->context = context;
    new_node->next = 0; // nullptr

    uintptr_t tail;
    do {
        tail = atomic_load_uintptr(&(queue->tail));
        Node* last = (Node*)(tail);

        if (last != 0 && !atomic_compare_exchange_weak_uintptr(&(last->next), &0, (uintptr_t)new_node)) {
            continue; // Retry
        }

        uintptr_t new_tail = (uintptr_t)new_node;
        if (!atomic_compare_exchange_weak_uintptr(&(queue->tail), &tail, new_tail)) {
            free(new_node);
            return -1;
        }
    } while (tail != atomic_load_uintptr(&(queue->tail)));

    // Ensure the head is updated after a successful enqueue
    uintptr_t head = atomic_load_uintptr(&(queue->head));
    if (head == tail) {
        atomic_store_uintptr(&(queue->head), new_tail);
    }

    return 0;
}

MAC_CONTEXT_T* dequeue(LockFreeQueue *queue) {
    uintptr_t head;
    do {
        head = atomic_load_uintptr(&(queue->head));

        if (head == atomic_load_uintptr(&(queue->tail))) {
            return NULL; // Queue is empty
        }

        Node* first_node = (Node*)(head);
        MAC_CONTEXT_T *context = first_node->context;

        uintptr_t new_head = (uintptr_t)first_node->next;
        if (!atomic_compare_exchange_weak_uintptr(&(queue->head), &head, new_head)) {
            continue; // Retry
        }

        free(first_node);
        return context;
    } while (1);
}

void destroy_context(MAC_CONTEXT_T *context) {
    if (context->buffer) {
        free(context->buffer);
    }
}
