typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct HashTableEntry {
    long offset;
    struct HashTableEntry *next;
} HashTableEntry;

#define HASH_TABLE_SIZE 1024

// Function prototypes
record* create_records(size_t num_records, double min_value, double max_value);
int validate_unique_offsets(record *records, size_t num_records);
void free_hash_table(HashTableEntry **hash_table);

// Helper functions for hash table operations
static inline unsigned long hash_function(long offset) {
    return (unsigned long)(offset % HASH_TABLE_SIZE);
}

// Global variables for lock-free and logging mechanisms
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
atomic_int conflict_count = 0;

record* create_records(size_t num_records, double min_value, double max_value) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Hash table for checking unique offsets
    HashTableEntry *hash_table[HASH_TABLE_SIZE] = {NULL};

    for (size_t i = 0; i < num_records; ++i) {
        do {
            records[i].offset = rand() % 100000000 + 1;
        } while (!validate_offset(records[i].offset, hash_table));

        records[i].key = rand(); // or any specific key generation logic
        records[i].value = min_value + (double)(rand() / (RAND_MAX / (max_value - min_value)));
    }

    if (!validate_unique_offsets(records, num_records)) {
        free(records);
        free_hash_table(hash_table);
        return NULL;
    }

    // Additional performance optimizations and logging can be added here

    free_hash_table(hash_table);
    return records;
}

int validate_offset(long offset, HashTableEntry **hash_table) {
    unsigned long index = hash_function(offset);

    pthread_mutex_lock(&mutex);
    HashTableEntry *entry = hash_table[index];

    while (entry) {
        if (entry->offset == offset) {
            conflict_count++;
            pthread_mutex_unlock(&mutex);
            return 0; // Offset not unique
        }
        entry = entry->next;
    }

    // Insert into hash table
    HashTableEntry *new_entry = malloc(sizeof(HashTableEntry));
    if (!new_entry) {
        perror("Failed to allocate memory for hash table entry");
        pthread_mutex_unlock(&mutex);
        return 0; // Handle allocation failure gracefully
    }
    new_entry->offset = offset;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;

    pthread_mutex_unlock(&mutex);
    return 1; // Offset is unique
}

int validate_unique_offsets(record *records, size_t num_records) {
    // Implemented for completeness, but logic should be merged with `validate_offset`
    HashTableEntry *hash_table[HASH_TABLE_SIZE] = {NULL};

    for (size_t i = 0; i < num_records; ++i) {
        if (!validate_offset(records[i].offset, hash_table)) {
            return 0;
        }
    }

    free_hash_table(hash_table);
    return 1;
}

void free_hash_table(HashTableEntry **hash_table) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = hash_table[i];
        while (entry) {
            HashTableEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
}
