        pdu_array[i].RNTI = rand() % 65536; // Random value as placeholder
        pdu_array[i].crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
    }

    return pdu_array;
}

// Function to parse JSON and YAML files, handle redundancy, and integrate data
void process_files(const char* json_file_path, const char* yaml_file_path) {
    FILE *jsonFile = fopen(json_file_path, "r");
    if (!jsonFile) {
        fprintf(stderr, "Failed to open JSON file\n");
        return;
    }

    json_error_t error;
    json_t *root_json = json_loadf(jsonFile, 0, &error);
    fclose(jsonFile);

    if (!root_json) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return;
    }

    // Load YAML file
    FILE *yamlFile = fopen(yaml_file_path, "r");
    if (!yamlFile) {
        fprintf(stderr, "Failed to open YAML file\n");
        json_decref(root_json);
        return;
    }

    yaml_parser_t parser;
    if (!yaml_parser_initialize(&parser)) {
        fprintf(stderr, "Failed to initialize YAML parser\n");
        fclose(yamlFile);
        json_decref(root_json);
        return;
    }

    yaml_event_t event;
    if (!yaml_parser_set_input_file(&parser, yamlFile)) {
        fprintf(stderr, "Failed to set input file for YAML parser\n");
        yaml_parser_delete(&parser);
        fclose(yamlFile);
        json_decref(root_json);
        return;
    }

    // Process JSON and YAML
    while (1) {
        if (!yaml_parser_parse(&parser, &event)) {
            fprintf(stderr, "Error parsing YAML event\n");
            break;
        }

        // Handle events here

        yaml_event_delete(&event);

        if (event.type == YAML_STREAM_END_EVENT) {
            break;
        }
    }

    yaml_parser_delete(&parser);
    fclose(yamlFile);
    json_decref(root_json);

    // Example of handling asynchronous data feeds
    srand(time(NULL)); // Seed for randomness in CRCFLAG

    size_t pdu_count = 10; // Example count, can be adjusted dynamically
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = init_crc_indication_pdu_array(pdu_count);
    if (!pdu_array) {
        fprintf(stderr, "Failed to initialize PDU array\n");
    } else {
        // Process the pdu_array as needed
        free(pdu_array); // Clean up memory when done
    }
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <json_file> <yaml_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_files(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
