typedef struct NetworkEntity {
    // Placeholder for network entity details
} NetworkEntity;

typedef struct MessageObject {
    char *buffer;
    size_t buffer_size;
    NetworkEntity *connection_handler;
    NetworkEntity *message_processor;
} MessageObject;

typedef struct DynamicList {
    MessageObject **messages;
    size_t count;
    size_t capacity;
    pthread_rwlock_t lock;
    size_t total_memory_used;
} DynamicList;

DynamicList* initialize_dynamic_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicList *list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->messages = malloc(initial_capacity * sizeof(MessageObject*));
    if (!list->messages) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_rwlock_init(&list->lock, NULL);
    list->total_memory_used = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        list->messages[i] = NULL;
    }

    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->messages[i]) {
            free(list->messages[i]->buffer);
            free(list->messages[i]);
        }
    }
    free(list->messages);
    pthread_rwlock_unlock(&list->lock);

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

int add_message(DynamicList *list, size_t buffer_size) {
    if (!list || buffer_size == 0) return -1;

    pthread_rwlock_wrlock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        MessageObject **new_messages = realloc(list->messages, new_capacity * sizeof(MessageObject*));
        if (!new_messages) {
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }
        list->messages = new_messages;
        for (size_t i = list->capacity; i < new_capacity; ++i) {
            list->messages[i] = NULL;
        }
        list->capacity = new_capacity;
    }

    MessageObject *new_message = malloc(sizeof(MessageObject));
    if (!new_message) {
        pthread_rwlock_unlock(&list->lock);
        return -1;
    }

    new_message->buffer_size = buffer_size;
    new_message->buffer = malloc(buffer_size);
    if (!new_message->buffer) {
        free(new_message);
        pthread_rwlock_unlock(&list->lock);
        return -1;
    }
    memset(new_message->buffer, 0, buffer_size);

    new_message->connection_handler = NULL; // Placeholder for actual connection handler
    new_message->message_processor = NULL; // Placeholder for actual message processor

    list->messages[list->count++] = new_message;
    list->total_memory_used += sizeof(MessageObject) + buffer_size;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void remove_message(DynamicList *list, size_t index) {
    if (!list || index >= list->count) return;

    pthread_rwlock_wrlock(&list->lock);

    if (list->messages[index]) {
        free(list->messages[index]->buffer);
        free(list->messages[index]);
        list->total_memory_used -= sizeof(MessageObject) + list->messages[index]->buffer_size;
    }

    memmove(&list->messages[index], &list->messages[index + 1],
            (list->count - index - 1) * sizeof(MessageObject*));
    list->count--;

    pthread_rwlock_unlock(&list->lock);
}

void log_usage_statistics(const DynamicList *list) {
    if (!list) return;

    pthread_rwlock_rdlock(&list->lock);

    printf("Active Messages: %zu\n", list->count);
    printf("Total Memory Used: %zu bytes\n", list->total_memory_used);

    pthread_rwlock_unlock(&list->lock);
}
