#include <stdint.h>

// Definitions
#define INITIAL_CAPACITY 1024
#define THRESHOLD_FACTOR 2

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    bool shutdown;
} NFAPI_CRC_LIST;

// Utility function to log CRC indication details
void log_crc_details(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %u, RNTI: %hu, "
           "CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %s\n",
           pdu->RX_UE_INFORMATION_TAG,
           pdu->RNTI,
           pdu->CRC_INDICATION_REL8_TAG,
           pdu->CRCFLAG ? "true" : "false");
}

// Function to initialize the NFAPI_CRC_LIST
NFAPI_CRC_LIST* nfa_crc_list_init() {
    NFAPI_CRC_LIST* list = malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->shutdown = false;

    return list;
}

// Function to destroy the NFAPI_CRC_LIST
void nfa_crc_list_destroy(NFAPI_CRC_LIST* list) {
    if (!list) return;

    free(list->array);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

// Function to resize the array when needed
bool nfa_crc_list_resize(NFAPI_CRC_LIST* list) {
    size_t new_capacity = list->capacity * THRESHOLD_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return false;

    list->array = new_array;
    list->capacity = new_capacity;
    return true;
}

// Function to add a new element in a thread-safe manner
bool nfa_crc_list_add(NFAPI_CRC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity && !nfa_crc_list_resize(list)) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }

    // Copy data and generate random CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T new_pdu = *pdu;
    new_pdu.CRCFLAG = rand() % 2; // Randomize the CRCFLAG

    list->array[list->count++] = new_pdu;

    log_crc_details(&new_pdu);

    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Function to process elements (dummy function for demonstration)
void* nfa_crc_list_processor(void* arg) {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)arg;

    while (!list->shutdown) {
        pthread_mutex_lock(&list->mutex);

        // Process elements here
        if (list->count > 0) {
            for (size_t i = 0; i < list->count; ++i) {
                log_crc_details(&list->array[i]);
                // Processing logic goes here...
            }

            // Clear processed data
            list->count = 0;
        }

        pthread_mutex_unlock(&list->mutex);
    }

    return NULL;
}

// Example usage within a multi-threaded framework
int main() {
    NFAPI_CRC_LIST* crc_list = nfa_crc_list_init();
    if (!crc_list) {
        fprintf(stderr, "Failed to initialize CRC list\n");
        return EXIT_FAILURE;
    }

    pthread_t processor_thread;
    if (pthread_create(&processor_thread, NULL, nfa_crc_list_processor, crc_list)) {
        fprintf(stderr, "Error creating processor thread\n");
        nfa_crc_list_destroy(crc_list);
        return EXIT_FAILURE;
    }

    // Simulate adding elements in a multi-threaded environment
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = i % 65535 };
        if (!nfa_crc_list_add(crc_list, &pdu)) {
            fprintf(stderr, "Failed to add element\n");
        }
    }

    // Signal shutdown
    pthread_mutex_lock(&crc_list->mutex);
    crc_list->shutdown = true;
    pthread_cond_broadcast(&crc_list->cond);
    pthread_mutex_unlock(&crc_list->mutex);

    pthread_join(processor_thread, NULL);
    nfa_crc_list_destroy(crc_list);

    return EXIT_SUCCESS;
}
