    }
}

void cleanup_crypto_algorithms() {
    // Cleanup operations
}

void* memory_management_example(size_t long_size, size_t int_size, size_t record_count) {
    pthread_mutex_lock(&mutex);

    long *long_array = malloc(long_size * sizeof(long));
    int *int_array = malloc(int_size * sizeof(int));
    record *records = malloc(record_count * sizeof(record));

    if (!long_array || !int_array || !records) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < long_size; ++i) {
        long_array[i] = rand() % 100;
    }

    for (size_t i = 0; i < int_size; ++i) {
        int_array[i] = rand() % 50;
    }

    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % 200;
    }

    // Simulate operations with allocated memory
    printf("Memory management example completed\n");

    free(long_array);
    free(int_array);
    free(records);

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "ERROR: %s\n", message);
        fclose(log_file);
    }
}
