#define MEMORY_THRESHOLD_MB 512.0  // MB

#define RETRY_COUNT 3

int process_data(long *offsets, int *keys, Record **records, size_t num_records) {
    sem_t semaphore;
    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Semaphore init failed");
        return -1;
    }

    // Initialize thread pool
    if (!start_thread_pool(INITIAL_THREAD_POOL_SIZE, MAX_THREAD_POOL_CAPACITY)) {
        log_info("Failed to start thread pool");
        sem_destroy(&semaphore);
        return -2;
    }

    for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
        // Allocate memory
        offsets = (long *)malloc(num_records * sizeof(long));
        keys = (int *)malloc(num_records * sizeof(int));
        *records = (Record *)malloc(num_records * sizeof(Record));

        if (!offsets || !keys || !(*records)) {
            free(offsets);
            free(keys);
            free(*records);

            log_info("Memory allocation failed, retrying...");

            // Consider exponential backoff strategy here for retries
        } else {
            break;  // Successful allocation
        }
    }

    if (!offsets || !keys || !(*records)) {
        log_info("Failed to allocate memory after retries");
        stop_thread_pool();
        sem_destroy(&semaphore);
        return -3;
    }

    // Simulate processing
