#include <time.h>

#define MIN_SIZE 10
#define MAX_SIZE 10000

typedef struct {
    int value;
} record;

typedef enum { SUCCESS = 0, ERROR_INVALID_INPUT, ERROR_MEMORY_ALLOCATION, ERROR_EXTERNAL_SOURCE } StatusCode;

// External data source simulation
int fetchDataFromSource(int *data, size_t size) {
    // Simulate a delay or failure
    if (rand() % 5 == 0) return -1; // Failure case

    for (size_t i = 0; i < size; ++i) {
        data[i] = rand() % 100 + 1;
    }
    return SUCCESS;
}

StatusCode initializeMemory(size_t array_size, long **offsets, int **keys, record ***records, int max_value, size_t *total_memory_usage) {
    if (array_size < MIN_SIZE || array_size > MAX_SIZE) {
        fprintf(stderr, "Error: Invalid input size.\n");
        return ERROR_INVALID_INPUT;
    }

    // Calculate memory usage
    size_t offset_mem = sizeof(long) * array_size;
    size_t key_mem = sizeof(int) * array_size;
    size_t record_mem = sizeof(record) * array_size;

    if (*total_memory_usage + offset_mem + key_mem + record_mem > MAX_SIZE * (sizeof(long) + sizeof(int) + sizeof(record))) {
        fprintf(stderr, "Error: Memory usage exceeds limit.\n");
        return ERROR_MEMORY_ALLOCATION;
    }

    // Allocate memory
    *offsets = malloc(offset_mem);
    *keys = malloc(key_mem);
    *records = malloc(record_mem);

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return ERROR_MEMORY_ALLOCATION;
    }

    // Initialize arrays
    for (size_t i = 0; i < array_size; ++i) {
        (*offsets)[i] = rand() % max_value + 1;
        (*keys)[i] = rand() % max_value + 1;
    }

    int *used_values = calloc(max_value, sizeof(int));
    if (used_values == NULL) {
        fprintf(stderr, "Error: Memory allocation for tracking values failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return ERROR_MEMORY_ALLOCATION;
    }

    // Fetch data from external source
    int *external_data = malloc(array_size * sizeof(int));
    if (external_data == NULL) {
        fprintf(stderr, "Error: Memory allocation for external data failed.\n");
        free(*offsets);
        free(*keys);
        free(*records);
        free(used_values);
        return ERROR_MEMORY_ALLOCATION;
    }

    if (fetchDataFromSource(external_data, array_size) != SUCCESS) {
        fprintf(stderr, "Warning: Failed to fetch data from external source.\n");
    } else {
        for (size_t i = 0; i < array_size; ++i) {
            ((*records)[i]).value = external_data[i];
        }
    }

    // Ensure unique random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        if (((*records)[i]).value == 0) { // If no data from source or failed
            int value;
            do {
                value = rand() % max_value + 1;
            } while (used_values[value - 1] != 0);
            ((*records)[i]).value = value;
        }
        used_values[((*records)[i]).value - 1] = 1;
    }

    free(external_data);
    free(used_values);

    *total_memory_usage += offset_mem + key_mem + record_mem;

    return SUCCESS;
}

void freeMemory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    size_t total_memory_usage = 0;
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    StatusCode status = initializeMemory(50, &offsets, &keys, &records, 100, &total_memory_usage);

    if (status != SUCCESS) {
        return -1;
    }

    // Use the memory...

    freeMemory(offsets, keys, records);
    return 0;
}
