fn compile_project(project_path: &Path, log_mutex: Arc<Mutex<FilePathLog>>) -> ProjectSummary {
    let start_time = Instant::now();
    let rss_before_kb = get_resident_set_size().unwrap_or_default();

    let rustc_process = catch_with_exit_code(move || {
        Command::new("cargo")
            .arg("build")
            .current_dir(project_path)
            .stdout(log_mutex.clone())
            .stderr(log_mutex.clone())
            .spawn()
            .expect("Failed to start cargo process")
            .wait_with_output()
    });

    let end_time = Instant::now();
    let duration_ms = end_time.duration_since(start_time).as_millis();

    let rss_after_kb = get_resident_set_size().unwrap_or_default();

    match rustc_process {
        Ok((exit_code, Some(output))) => {
            log_mutex.lock().unwrap().write_all(&output).unwrap();
            ProjectSummary {
                exit_code,
                duration_ms,
                rss_before_kb,
                rss_after_kb,
                logs: log_mutex.lock().unwrap().read_logs(),
            }
        },
        Ok((exit_code, None)) => {
            let mut logs = Vec::new();
            if let Ok(mut handle) = File::open(log_mutex.lock().unwrap()) {
                handle.read_to_end(&mut logs).unwrap();
            }
            ProjectSummary {
                exit_code,
                duration_ms,
                rss_before_kb,
                rss_after_kb,
                logs: logs.iter().map(|s| String::from_utf8_lossy(s).to_string()).collect(),
            }
        },
        Err((exit_code, Some(output))) => {
            log_mutex.lock().unwrap().write_all(&output).unwrap();
            ProjectSummary {
                exit_code,
                duration_ms,
                rss_before_kb,
                rss_after_kb,
                logs: log_mutex.lock().unwrap().read_logs(),
            }
        },
        Err((exit_code, None)) => {
            let mut logs = Vec::new();
            if let Ok(mut handle) = File::open(log_mutex.lock().unwrap()) {
                handle.read_to_end(&mut logs).unwrap();
            }
            ProjectSummary {
                exit_code,
                duration_ms,
                rss_before_kb,
                rss_after_kb,
                logs: logs.iter().map(|s| String::from_utf8_lossy(s).to_string()).collect(),
            }
        },
    }
}

struct FilePathLog(File);

impl FilePathLog {
    fn write_all(&mut self, buf: &[u8]) -> io::Result<()> {
        self.0.write_all(buf)
    }

    fn read_logs(&self) -> Vec<Vec<u8>> {
        let mut buffer = vec![];
        if let Ok(mut file) = File::open(self.0.try_clone().unwrap()) {
            file.read_to_end(&mut buffer).unwrap();
        }
        vec![buffer]
    }
}

impl Drop for FilePathLog {
    fn drop(&mut self) {
        // You may want to reset or delete the log file here.
    }
}

fn compile_projects_concurrently(project_paths: Vec<&Path>) -> HashMap<String, ProjectSummary> {
    use std::thread;

    let summaries = Arc::new(Mutex::new(HashMap::new()));
    let log_mutex = Arc::new(Mutex::new(File::create("temp_log").unwrap()));

    let handles: Vec<_> = project_paths.into_iter().map(|path| {
        let summaries_clone = summaries.clone();
        let log_mutex_clone = log_mutex.clone();

        thread::spawn(move || {
            let name = path.to_string_lossy().into_owned();
            let summary = compile_project(path, log_mutex_clone);
            let mut summaries_guard = summaries_clone.lock().unwrap();
            summaries_guard.insert(name, summary);
        })
    }).collect();

    for handle in handles {
        handle.join().unwrap();
    }

    let mut results = HashMap::new();
    let summaries_lock = summaries.lock().unwrap();
    results.extend(summaries_lock.drain());

    results
}

fn main() {
    // Example usage: List of project paths to compile.
    let project_paths = vec![Path::new("project1"), Path::new("project2")];
    let summaries = compile_projects_concurrently(project_paths);

    for (name, summary) in summaries.iter() {
        println!("Project: {}\nSummary:\n{:?}", name, summary);
    }
}
```

This code uses multi-threading to handle multiple projects concurrently. It captures the compilation logs and RSS values before and after the process. Errors are captured using `rustc_driver::catch_with_exit_code`, which also handles capturing stdout/stderr for logging purposes. Note that `get_resident_set_size` needs a proper implementation depending on your platform.

The function is designed to handle large numbers of projects efficiently, utilizing threads to scale with the number of available CPU cores while managing memory and log handling using file-based temporary storage to prevent excessive in-memory usage.']

