['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    char *payload_type;
    time_t timestamp;
    char *content;
    size_t content_length;
} Message;

typedef struct {
    Message *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned long group_id;
} MessageArray;

MessageArray* initialize_message_array(unsigned long group_id, size_t initial_capacity) {
    MessageArray *array = malloc(sizeof(MessageArray));
    array->messages = malloc(initial_capacity * sizeof(Message));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->group_id = group_id;
    return array;
}

void resize_message_array(MessageArray *array) {
    size_t new_capacity = array->capacity * 2;
    Message *new_messages = malloc(new_capacity * sizeof(Message));
    memcpy(new_messages, array->messages, array->count * sizeof(Message));
    free(array->messages);
    array->messages = new_messages;
    array->capacity = new_capacity;
}

int add_message(MessageArray *array, int id, const char *payload_type, time_t timestamp, const char *content) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_message_array(array);
    }

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Message with this ID already exists
        }
    }

    Message *msg = &array->messages[array->count++];
    msg->id = id;
    msg->payload_type = strdup(payload_type);
    msg->timestamp = timestamp;
    msg->content_length = strlen(content);
    msg->content = malloc(msg->content_length + 1);
    strcpy(msg->content, content);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_message(MessageArray *array, int id, const char *payload_type, time_t timestamp, const char *content) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            free(array->messages[i].payload_type);
            free(array->messages[i].content);

            array->messages[i].payload_type = strdup(payload_type);
            array->messages[i].timestamp = timestamp;
            array->messages[i].content_length = strlen(content);
            array->messages[i].content = malloc(array->messages[i].content_length + 1);
            strcpy(array->messages[i].content, content);

            pthread_mutex_unlock(&array->lock);
            return 0; // Message updated successfully
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1; // Message not found
}

int* retrieve_messages(MessageArray *array, time_t start_time, time_t end_time, size_t *count) {
    pthread_mutex_lock(&array->lock);

    *count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].timestamp >= start_time && array->messages[i].timestamp <= end_time) {
            (*count)++;
        }
    }

    int *result_ids = malloc(*count * sizeof(int));
    size_t index = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].timestamp >= start_time && array->messages[i].timestamp <= end_time) {
            result_ids[index++] = array->messages[i].id;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return result_ids;
}

typedef struct {
    int value;
} Record;

void initialize_records(Record *records, size_t count, int min_value, int max_value) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }
}

void free_message_array(MessageArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->messages[i].payload_type);
        free(array->messages[i].content);
    }

    free(array->messages);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
