function handleUserAccountRequest($request) {
    $response = ['status' => 'error', 'message' => ''];

    try {
        // Database connection (Assuming PDO is used)
        $pdo = new PDO('mysql:host=your_host;dbname=your_db', 'username', 'password');

        // Start a transaction
        $pdo->beginTransaction();

        if (!isset($request['name']) || !isset($request['email']) || !isset($request['password'])) {
            throw new Exception('Missing required fields.');
        }

        $id = isset($request['id']) ? (int)$request['id'] : null;
        $name = filter_var($request['name'], FILTER_SANITIZE_STRING);
        $email = filter_var($request['email'], FILTER_VALIDATE_EMAIL);
        $password = password_hash($request['password'], PASSWORD_DEFAULT);
        $subAction = isset($request['sub_action']) ? strtolower($request['sub_action']) : null;

        if (!$email) {
            throw new Exception('Invalid email format.');
        }

        // Email availability check with retry logic
        $isEmailAvailable = checkEmailAvailabilityWithRetry($email);

        if (!$isEmailAvailable && !$id) {  // If creating a new user and email is taken
            throw new Exception('Email already in use.');
        }

        if ($subAction) {
            switch ($subAction) {
                case 'delete':
                    deleteUser($pdo, $id);
                    break;
                case 'archive':
                    archiveUser($pdo, $id);
                    break;
                case 'reactivate':
                    reactivateUser($pdo, $id);
                    break;
                default:
                    throw new Exception('Invalid sub_action.');
            }
        } else {
            if ($id) {
                updateUser($pdo, $id, $name, $email, $password);
            } else {
                createUser($pdo, $name, $email, $password);
            }
        }

        // Commit transaction
        $pdo->commit();

        // Log the action
        logAction($request, $subAction);

        $response['status'] = 'success';
        $response['message'] = 'User account processed successfully.';
    } catch (Exception $e) {
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }
        $response['message'] = $e->getMessage();
    }

    return json_encode($response);
}

