#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define SNR_THRESHOLD 5

typedef struct {
    int ueId;
    int servingCellConfig;
} UEConnectionInfo;

typedef struct {
    double value;
    struct SNRValue *next;
} SNRValue;

// Function prototypes
int populateUEConnectionList(UEConnectionInfo **list, size_t maxEntries);
double generateRandomSNR(double previousSNR);
void handleError(const char* errorMsg);

int main() {
    srand(time(NULL)); // Seed the random number generator

    UEConnectionInfo *ueConnections = NULL;
    if (populateUEConnectionList(&ueConnections, MAX_LIST_SIZE) != 0) {
        fprintf(stderr, "Failed to populate UE connection list.\n");
        return EXIT_FAILURE;
    }

    // Example of how to free allocated memory
    for (size_t i = 0; ueConnections && i < MAX_LIST_SIZE; ++i) {
        if (!ueConnections[i].servingCellConfig) break;

        SNRValue *snr = ueConnections[i].servingCellConfig;
        while (snr) {
            SNRValue *temp = snr;
            snr = snr->next;
            free(temp);
        }
    }

    free(ueConnections);
    return EXIT_SUCCESS;
}

int populateUEConnectionList(UEConnectionInfo **list, size_t maxEntries) {
    if (!list || maxEntries == 0) {
        handleError("Invalid arguments to populate list.");
        return -1;
    }

    *list = (UEConnectionInfo *)malloc(maxEntries * sizeof(UEConnectionInfo));
    if (*list == NULL) {
        handleError("Memory allocation failed for UE connection list.");
        return -1;
    }

    for (size_t i = 0; i < maxEntries; ++i) {
        (*list)[i].ueId = i + 1;
        (*list)[i].servingCellConfig = rand() % 2;

        if (!(*list)[i].servingCellConfig) continue;

        SNRValue *firstSNR = (SNRValue *)malloc(sizeof(SNRValue));
        if (!firstSNR) {
            handleError("Memory allocation failed for first SNR value.");
            return -1;
        }
        firstSNR->value = generateRandomSNR(0);
        (*list)[i].servingCellConfig = firstSNR;

        SNRValue *currentSNR = firstSNR;
        double lastValue = firstSNR->value;

        for (int j = 1; j < rand() % 10 + 5; ++j) { // Random number of SNR values per UE
            SNRValue *newSNR = (SNRValue *)malloc(sizeof(SNRValue));
            if (!newSNR) {
                handleError("Memory allocation failed for new SNR value.");
                return -1;
            }

            double newValue = generateRandomSNR(lastValue);
            while (fabs(newValue - lastValue) > SNR_THRESHOLD) { // Ensure stability
                newValue = generateRandomSNR(lastValue);
            }

            newSNR->value = newValue;
            currentSNR->next = newSNR;
            currentSNR = newSNR;
            lastValue = newValue;
        }

        currentSNR->next = NULL; // Terminate the list
    }

    return 0;
}

double generateRandomSNR(double previousSNR) {
    double snrRangeMin = (previousSNR > SNR_THRESHOLD) ? previousSNR - SNR_THRESHOLD : 0;
    double snrRangeMax = previousSNR + SNR_THRESHOLD;

    // Simulate potential delay or failure from external service
    if ((rand() % 10) == 0) {
        handleError("External SNR measurement service failed.");
        return previousSNR; // Fallback to the last known good value
    }

    double randomOffset = (double)(rand() % (int)((snrRangeMax - snrRangeMin) * 100)) / 100.0;
    return snrRangeMin + randomOffset;
}

void handleError(const char* errorMsg) {
