// Function to validate the integrity of CRC flags using parity checks.
int validate_crc_flag(unsigned int crc_flag) {
    // Simple parity check (even number of 1s)
    int parity = 0;
    while (crc_flag) {
        parity ^= (crc_flag & 1);
        crc_flag >>= 1;
    }
    return (parity == 0); // Returns 1 if valid, 0 otherwise.
}

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_array(size_t num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for CRC indication array.\n");
        return NULL;
    }

    // Example system performance metric cache.
    unsigned int cached_crc_flag = 0; // Assume some initial value based on system metrics.

    size_t successful_count = 0;

    for (size_t i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1; // Example assignment
        array[i].RNTI = i + 1000; // Ensure uniqueness by starting at a different base value

        unsigned int crc_flag;

        if (validate_crc_flag(cached_crc_flag)) {
            crc_flag = cached_crc_flag; // Use cached value if valid.
        } else {
            // Simulate real-time CRC flag determination based on system performance metrics.
            crc_flag = (i % 2 == 0) ? 0xAAAA : 0x5555; // Example logic for determining CRCFLAG
            if (!validate_crc_flag(crc_flag)) {
                fprintf(stderr, "CRC flag validation failed at index %zu.\n", i);
                continue;
            }
        }

        array[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = array[i].RX_UE_INFORMATION_TAG;
        array[i].crc_indication_rel8_tag.RNTI = array[i].RNTI;
        array[i].crc_indication_rel8_tag.crc_flag = crc_flag;

        // Cache the CRC flag for possible reuse.
        cached_crc_flag = crc_flag;

        successful_count++;
    }

    printf("Successfully created %zu CRC indication structures.\n", successful_count);

    return array;
}

// Example usage
