['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct EventRecord {
    int eventId;
    long timestamp; // Unix epoch time or similar
    char metadata[256];
    struct EventRecord *next;
} EventRecord;

// Function prototypes
EventRecord* create_event_record(int eventId, long timestamp, const char *metadata);
void insert_event(EventRecord **head, EventRecord *newEvent);
void delete_event_by_id(EventRecord **head, int eventId);
EventRecord* find_event_by_id(const EventRecord *head, int eventId);
void sort_events_by_timestamp(EventRecord **head);
void process_records_in_time_range(EventRecord *head, long startTime, long endTime, void (*process)(EventRecord *));
void update_metadata_conditionally(EventRecord *head, const char *condition, const char *newMetadata);
void free_event_records(EventRecord **head);
void print_event_details(const EventRecord *event);

// Function implementations
EventRecord* create_event_record(int eventId, long timestamp, const char *metadata) {
    EventRecord *record = (EventRecord*)malloc(sizeof(EventRecord));
    if (!record) return NULL;

    record->eventId = eventId;
    record->timestamp = timestamp;
    strncpy(record->metadata, metadata, sizeof(record->metadata) - 1);
    record->next = NULL;

    return record;
}

void insert_event(EventRecord **head, EventRecord *newEvent) {
    if (!head || !newEvent) return;

    newEvent->next = *head;
    *head = newEvent;
}

void delete_event_by_id(EventRecord **head, int eventId) {
    if (!head || !*head) return;

    EventRecord *temp = *head, *prev = NULL;
    while (temp && temp->eventId != eventId) {
        prev = temp;
        temp = temp->next;
    }

    if (!temp) return; // Event not found

    if (prev) {
        prev->next = temp->next;
    } else {
        *head = temp->next;
    }

    free(temp);
}

EventRecord* find_event_by_id(const EventRecord *head, int eventId) {
    while (head) {
        if (head->eventId == eventId) return (EventRecord*) head;
        head = head->next;
    }

    return NULL;
}

void sort_events_by_timestamp(EventRecord **head) {
    if (!head || !*head) return;

    int swapped;
    EventRecord *ptr1, *lptr = NULL;

    do {
        swapped = 0;
        ptr1 = *head;

        while (ptr1->next != lptr) {
            if (ptr1->timestamp > ptr1->next->timestamp) {
                // Swap event nodes
                int tempEventId = ptr1->eventId;
                long tempTimestamp = ptr1->timestamp;
                char tempMetadata[256];
                strcpy(tempMetadata, ptr1->metadata);

                ptr1->eventId = ptr1->next->eventId;
                ptr1->timestamp = ptr1->next->timestamp;
                strncpy(ptr1->metadata, ptr1->next->metadata, sizeof(ptr1->metadata) - 1);

                ptr1->next->eventId = tempEventId;
                ptr1->next->timestamp = tempTimestamp;
                strcpy(ptr1->next->metadata, tempMetadata);

                swapped = 1;
            }
            ptr1 = ptr1->next;
        }

        lptr = ptr1;
    } while (swapped);
}

void process_records_in_time_range(EventRecord *head, long startTime, long endTime, void (*process)(EventRecord *)) {
    while (head) {
        if (head->timestamp >= startTime && head->timestamp <= endTime) {
            process(head);
        }
        head = head->next;
    }
}

void update_metadata_conditionally(EventRecord *head, const char *condition, const char *newMetadata) {
    while (head) {
        if (strstr(head->metadata, condition)) {
            strncpy(head->metadata, newMetadata, sizeof(head->metadata) - 1);
        }
        head = head->next;
    }
}

void free_event_records(EventRecord **head) {
    EventRecord *temp;

    while (*head) {
        temp = (*head)->next;
        free(*head);
        *head = temp;
    }

    *head = NULL;
}

void print_event_details(const EventRecord *event) {
    if (!event) return;
    printf("Event ID: %d, Timestamp: %ld, Metadata: %s\n", event->eventId, event->timestamp, event->metadata);
}
```

This code provides a comprehensive implementation for managing a dynamic collection of historical events using a linked list. It supports efficient insertion, deletion, and retrieval operations while also allowing sorting by timestamp. Batch operations are implemented via functions that process records in a specified time range or update metadata conditionally. Memory management is handled to prevent leaks, with checks included during allocation failures. The code can be further extended to integrate with external data sources as needed for synchronization purposes.']

