```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IP_LENGTH 16
#define MAC_ADDRESS_LENGTH 18

typedef struct {
    char ip_address[MAX_IP_LENGTH];
    char subnet_mask[MAX_IP_LENGTH];
    char mac_address[MAC_ADDRESS_LENGTH];
    float packet_loss_percentage;
    int throughput; // in Mbps
    int latency; // in ms
} NIC;

typedef void (*NetworkConditionCallback)(NIC *nic);

typedef struct {
    NIC *nics;
    size_t max_nics;
    pthread_mutex_t mutex;
    NetworkConditionCallback callback;
} NICPool;

void initialize_nic_pool(NICPool *pool, size_t max_nics, NetworkConditionCallback callback) {
    pool->max_nics = max_nics;
    pool->callback = callback;
    pool->nics = calloc(max_nics, sizeof(NIC));
    pthread_mutex_init(&pool->mutex, NULL);
}

void update_nic_metrics(NIC *nic) {
    // Simulate network condition updates
    nic->packet_loss_percentage += 0.1; // Example change
    nic->throughput += 10;
    nic->latency += 5;

    if (pool.callback != NULL) {
        pool.callback(nic);
    }
}

void* nic_monitor_thread(void *arg) {
    NICPool *pool = (NICPool*)arg;

    while (1) {
        pthread_mutex_lock(&pool->mutex);

        for (size_t i = 0; i < pool->max_nics; ++i) {
            update_nic_metrics(&pool->nics[i]);
        }

        pthread_mutex_unlock(&pool->mutex);
        sleep(5); // Update every 5 seconds
    }
}

void report_statistics(NICPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    float avg_throughput = 0;
    int max_latency = 0;
    float total_packet_loss = 0;

    for (size_t i = 0; i < pool->max_nics; ++i) {
        avg_throughput += pool->nics[i].throughput;
        if (pool->nics[i].latency > max_latency) {
            max_latency = pool->nics[i].latency;
        }
        total_packet_loss += pool->nics[i].packet_loss_percentage;
    }

    printf("Average Throughput: %.2f Mbps\n", avg_throughput / pool->max_nics);
    printf("Max Latency: %d ms\n", max_latency);
    printf("Total Packet Loss: %.2f%%\n", total_packet_loss);

    pthread_mutex_unlock(&pool->mutex);
}

void cleanup_nic_pool(NICPool *pool) {
    free(pool->nics);
    pthread_mutex_destroy(&pool->mutex);
}

int main() {
    NICPool pool;
    initialize_nic_pool(&pool, 10, NULL);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, nic_monitor_thread, (void*)&pool);

    while (1) {
        report_statistics(&pool);
        sleep(60); // Report every minute
    }

    cleanup_nic_pool(&pool);
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe access to NIC objects.
- **Dynamic Updates**: Supports real-time updates via a callback function.
- **Statistics Reporting**: Periodically aggregates and reports network performance metrics.
- **Resource Management**: Handles memory allocation and deallocation carefully.
- **Scalability**: Designed to handle varying network loads efficiently.

This implementation provides a foundation for managing NIC objects in a concurrent environment, with room for future enhancements.']

