    float SINR_ESTIMATE;
    int CHANNEL_QUALITY_INDICATION_TAG;
    int LINK_LAYER_ERROR_RATE_TAG;
} NR_UES_STATS_T;

float calculate_sinus(float signal_strength, float interference) {
    return (signal_strength - interference);
}

void initialize_and_populate_array(NR_UES_STATS_T array[], size_t ue_count) {
    srand(time(NULL));

    for (size_t i = 0; i < ue_count; ++i) {
