        float signal_strength = rand() % 30 + 50; // Example range: 50 to 80
        float interference = rand() % 20 + 5;     // Example range: 5 to 25

        array[i].TX_POWER_LEVEL = rand() % 31;    // TX power levels typically from 0 to 30 dBm
        array[i].SINR_ESTIMATE = calculate_sinus(signal_strength, interference);
        array[i].CHANNEL_QUALITY_INDICATION_TAG = (int)(array[i].SINR_ESTIMATE / 10); // Example scaling factor
        array[i].LINK_LAYER_ERROR_RATE_TAG = rand() % 101;    // Error rate percentage

        printf("UE[%zu] - TX Power: %d, SINR Estimate: %.2f, CQI Tag: %d, LER Rate Tag: %d\n",
               i, array[i].TX_POWER_LEVEL, array[i].SINR_ESTIMATE,
               array[i].CHANNEL_QUALITY_INDICATION_TAG, array[i].LINK_LAYER_ERROR_RATE_TAG);
    }

    // Simulate network congestion handling
    float current_load = ((float) ue_count / MAX_UE_COUNT);

    if (current_load > CONGESTION_THRESHOLD) {
        int delay_seconds = (int)((current_load - CONGESTION_THRESHOLD) * DELAY_MAX_SECONDS);

        printf("Network congestion detected. Applying a delay of %d seconds.\n", delay_seconds);
        sleep(delay_seconds); // Simulate network delay
    }
}

