['```java
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ResourceManagementFramework {
    private final Logger logger = Logger.getLogger(ResourceManagementFramework.class.getName());
    private final ConcurrentMap<String, ResourcePool> resourcePools = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void configureResource(String resourceId, int minSize, int maxSize, long idleTimeoutMillis, Priority priority) {
        ResourcePool pool = new ResourcePool(minSize, maxSize, idleTimeoutMillis, priority);
        resourcePools.put(resourceId, pool);
    }

    public CompletableFuture<ResourceInstance> acquireResourceAsync(String resourceId) {
        ResourcePool pool = resourcePools.get(resourceId);
        if (pool == null) throw new IllegalArgumentException("Resource not configured: " + resourceId);

        return CompletableFuture.supplyAsync(() -> {
            try {
                return pool.acquire();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new CompletionException(e);
            }
        });
    }

    public void releaseResource(String resourceId, ResourceInstance instance) {
        ResourcePool pool = resourcePools.get(resourceId);
        if (pool != null) {
            pool.release(instance);
        }
    }

    public void startMonitoring() {
        scheduler.scheduleAtFixedRate(this::logStatistics, 0, 10, TimeUnit.SECONDS);
    }

    private void logStatistics() {
        for (Map.Entry<String, ResourcePool> entry : resourcePools.entrySet()) {
            ResourcePool pool = entry.getValue();
            logger.log(Level.INFO, "Resource: {0}, Active: {1}, Max Capacity Reached: {2}, Failures: {3}",
                    new Object[]{entry.getKey(), pool.getActiveCount(), pool.isMaxCapacityReached(), pool.getFailureCount()});
        }
    }

    private static class ResourcePool {
        private final int minSize;
        private final int maxSize;
        private final long idleTimeoutMillis;
        private final Priority priority;
        private final BlockingQueue<ResourceInstance> availableResources = new LinkedBlockingQueue<>();
        private final Set<ResourceInstance> allResources = Collections.synchronizedSet(new HashSet<>());
        private final AtomicInteger activeCount = new AtomicInteger(0);
        private final AtomicInteger failureCount = new AtomicInteger(0);

        public ResourcePool(int minSize, int maxSize, long idleTimeoutMillis, Priority priority) {
            this.minSize = minSize;
            this.maxSize = maxSize;
            this.idleTimeoutMillis = idleTimeoutMillis;
            this.priority = priority;
            initializeResources(minSize);
        }

        private void initializeResources(int size) {
            for (int i = 0; i < size; i++) {
                ResourceInstance instance = createResource();
                if (instance != null && isReady(instance)) {
                    availableResources.offer(instance);
                    allResources.add(instance);
                }
            }
        }

        public synchronized ResourceInstance acquire() throws InterruptedException {
            ResourceInstance resource = availableResources.poll(this.idleTimeoutMillis, TimeUnit.MILLISECONDS);
            if (resource == null && activeCount.get() < maxSize) {
                resource = createResource();
                if (resource != null && isReady(resource)) {
                    allResources.add(resource);
                }
            }
            if (resource != null) {
                activeCount.incrementAndGet();
            } else {
                failureCount.incrementAndGet();
            }
            return resource;
        }

        public void release(ResourceInstance instance) {
            availableResources.offer(instance);
            activeCount.decrementAndGet();
        }

        private ResourceInstance createResource() {
            // Implement resource creation logic
            return new ResourceInstance();
        }

        private boolean isReady(ResourceInstance instance) {
            // Implement readiness validation logic
