    }

    for (int i = 0; i < num_ports; ++i) {
        params->ports[i] = rand() % 65536; // Random port number
        params->timeouts[i] = rand() % 1000; // Random timeout value

        total_chars += sizeof(int);
    }

    if (total_chars > max_chars) {
        snprintf(error_message, buffer_size, "Error: Combined length of strings and integers exceeds limit.");
        goto cleanup;
    }

    free(error_message);
    return params;

cleanup:
