    RX_UE_INFORMATION_TAG ue_info;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_RX_FRAME_T;

// Function prototypes
void calculate_mean_and_stddev(float *array, size_t n);
int populate_frames(NFAPI_RX_FRAME_T **frames, size_t count);

int main() {
    float *numbers = NULL;
    size_t capacity = 10;
    size_t length = 0;

    numbers = (float *)malloc(capacity * sizeof(float));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    printf("Enter floating-point numbers (negative to stop):\n");

    while (1) {
        float number;
        if (scanf("%f", &number) != 1) {
            break; // Exit on non-numeric input
        }

        if (number < 0.0) {
            fprintf(stderr, "Negative value detected, exiting...\n");
            free(numbers);
            return EXIT_FAILURE;
        }

        if (length == capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(float));
            if (!numbers) {
                fprintf(stderr, "Memory allocation failed\n");
                return EXIT_FAILURE;
            }
        }

        numbers[length++] = number;
    }

    if (length > 0) {
        calculate_mean_and_stddev(numbers, length);
    } else {
        printf("No valid data to process.\n");
    }

    free(numbers);

    // Populating frames
    size_t frame_count = 5; // Example value
    NFAPI_RX_FRAME_T *frames = NULL;
    if (populate_frames(&frames, frame_count) == EXIT_SUCCESS) {
        for (size_t i = 0; i < frame_count; ++i) {
            printf("Frame %zu: UE Identity = %d, RNTI = %d, CRCFLAG = %d\n",
                   i + 1, frames[i].ue_info.UE_Identity, frames[i].RNTI,
                   frames[i].crc_tag.CRCFLAG);
        }
    }

    free(frames);

    return EXIT_SUCCESS;
}

void calculate_mean_and_stddev(float *array, size_t n) {
    float sum = 0.0f, mean, stddev = 0.0f;

    for (size_t i = 0; i < n; ++i) {
        sum += array[i];
    }
    mean = sum / n;

    for (size_t i = 0; i < n; ++i) {
        stddev += pow(array[i] - mean, 2);
    }

    stddev = sqrt(stddev / n);

    printf("Mean: %.5f\n", mean);
    printf("Standard Deviation: %.5f\n", stddev);
}

int populate_frames(NFAPI_RX_FRAME_T **frames, size_t count) {
    *frames = (NFAPI_RX_FRAME_T *)malloc(count * sizeof(NFAPI_RX_FRAME_T));
    if (!*frames) {
        fprintf(stderr, "Memory allocation failed for frames\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < count; ++i) {
        (*frames)[i].ue_info.UE_Identity = rand() % 1000 + 1; // Example identity
        (*frames)[i].RNTI = rand() % 500 + 1; // Example RNTI

        int probability_threshold = rand() % 100;
        if (probability_threshold < 50) { // Example threshold
            (*frames)[i].crc_tag.CRCFLAG = 1;
        } else {
            (*frames)[i].crc_tag.CRCFLAG = 0;
        }
    }

    return EXIT_SUCCESS;
}
