['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define MEMORY_LIMIT (50 * 1024 * 1024) // 50 MB

typedef struct {
    int crc_flag;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    size_t used;
} CRCManager;

CRCManager* create_crc_manager(size_t initial_capacity) {
    CRCManager* manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->used = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond_var, NULL);

    return manager;
}

void destroy_crc_manager(CRCManager* manager) {
    if (!manager) return;

    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}

int resize_if_needed(CRCManager* manager, size_t additional_size) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used + additional_size > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if ((new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > MEMORY_LIMIT) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory limit reached
        }

        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_crc_indication(CRCManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (resize_if_needed(manager, 1) != 0) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->used < manager->capacity) {
        manager->array[manager->used++] = pdu;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void reset_crc_flags(CRCManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->used; ++i) {
        manager->array[i].crc_flag = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_unused_structures(CRCManager* manager, size_t threshold) {
    pthread_mutex_lock(&manager->lock);

    if (manager->capacity - manager->used > threshold) {
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(manager->used, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        for (size_t i = 0; i < manager->used; ++i) {
            new_array[i] = manager->array[i];
        }

        free(manager->array);
        manager->array = new_array;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    CRCManager* manager = create_crc_manager(1000);

    if (!manager) {
        fprintf(stderr, "Failed to initialize CRC Manager\n");
        return EXIT_FAILURE;
    }

    // Add elements...
    NFAPI_CRC_INDICATION_PDU_T pdu = { .crc_flag = 1 };
    if (add_crc_indication(manager, pdu) != 0) {
        fprintf(stderr, "Failed to add CRC indication\n");
    }

    reset_crc_flags(manager);
    cleanup_unused_structures(manager, 500);

    destroy_crc_manager(manager);
    return EXIT_SUCCESS;
}
