        if (array[i].RX_UE_INFORMATION_TAG == 0 || array[i].RNTI == 0) {
            log_error("Array validation failed: Invalid tags");
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* manage_crc_array(UE_INFO *ue_info, size_t N) {
    if (ue_info == NULL || N == 0) {
        log_error("Empty UE_INFO array or zero elements.");
        return NULL;
    }

    pthread_mutex_lock(&array_lock);
    NFAPI_CRC_INDICATION_PDU_T *crc_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_array == NULL) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&array_lock);
        return NULL;
    }

    srand(time(NULL));

    unsigned int rx_tag_count = 0;
    for (size_t i = 0; i < N && i < sizeof(ue_info)/sizeof(UE_INFO); ++i) {
        crc_array[i].RX_UE_INFORMATION_TAG = ++rx_tag_count;
        crc_array[i].RNTI = ue_info[i].RNTI;

        bool set_crcflag = (rand() % 5 == 0);
        if (set_crcflag || (crcflag_counter < N / 5)) {
            crc_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = true;
            crcflag_counter++;
        } else {
            crc_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = false;
        }
    }

    pthread_mutex_unlock(&array_lock);

    if (!validate_array(crc_array, N)) {
        free(crc_array);
        return NULL;
    }

    log_info("Array managed successfully with CRCFLAG counter: %lu", crcflag_counter);
    return crc_array;
}
