#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CAPACITY 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    time_t timestamp;
    int CRCFLAG; // Randomized
} NFAPI_CRC_INDICATION_PDU_T;

// Simple slab allocator for demonstration purposes
#define SLAB_SIZE 32

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *slabs[MAX_CAPACITY / SLAB_SIZE];
    size_t used;
} SlabAllocator;

SlabAllocator *create_allocator() {
    SlabAllocator *allocator = malloc(sizeof(SlabAllocator));
    allocator->used = 0;
    for (int i = 0; i < MAX_CAPACITY / SLAB_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *slab = malloc(SLAB_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(slab, 0, SLAB_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        allocator->slabs[i] = slab;
    }
    return allocator;
}

void destroy_allocator(SlabAllocator *allocator) {
    for (int i = 0; i < MAX_CAPACITY / SLAB_SIZE; ++i) {
        free(allocator->slabs[i]);
    }
    free(allocator);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(SlabAllocator *allocator) {
    if (allocator->used >= MAX_CAPACITY) return NULL;

    int slab_index = allocator->used / SLAB_SIZE;
    int offset = allocator->used % SLAB_SIZE;

    NFAPI_CRC_INDICATION_PDU_T *slab = allocator->slabs[slab_index];
    if (!slab[offset].RX_UE_INFORMATION_TAG) { // Check if uninitialized
        allocator->used++;
        return &slab[offset];
    }
    return NULL;
}

void deallocate_pdu(SlabAllocator *allocator, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int slab_index = ((char*)pdu - (char*)allocator->slabs[0]) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int offset = ((char*)pdu - (char*)allocator->slabs[slab_index]) / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, unsigned int rx_ue_tag, unsigned int rnti,
                    unsigned short crc_rel8_tag, int randomize_crcflag, double frequency) {
    pdu->RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    pdu->timestamp = time(NULL);

    if (randomize_crcflag && ((double)rand() / RAND_MAX) < frequency) {
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    } else {
        pdu->CRCFLAG = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T* filter_pdus(SlabAllocator *allocator, unsigned int target_rnti) {
    for (int i = 0; i < allocator->used; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &allocator->slabs[i / SLAB_SIZE][i % SLAB_SIZE];
        if (pdu->RNTI == target_rnti && pdu->RX_UE_INFORMATION_TAG != 0) {
            return pdu;
        }
    }
    return NULL; // No match found
}

void integrate_with_external_source(SlabAllocator *allocator, int (*fetch_data)(NFAPI_CRC_INDICATION_PDU_T**)) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    while (fetch_data(&pdu) == 0 && allocator->used < MAX_CAPACITY) { // Assuming fetch_data returns 0 on success
        if (!pdu) break;

        initialize_pdu(pdu, rand(), rand() % 65535, rand() % 1024, 1, 0.5); // Example initialization
        allocate_pdu(allocator);
    }
}

int main() {
    srand(time(NULL));

    SlabAllocator *allocator = create_allocator();

    integrate_with_external_source(allocator, fetch_data);

    unsigned int target_rnti = 12345; // Example RNTI to filter
    NFAPI_CRC_INDICATION_PDU_T *filtered_pdu = filter_pdus(allocator, target_rnti);

    if (filtered_pdu) {
        printf("Filtered PDU: RNTI=%u\n", filtered_pdu->RNTI);
    } else {
        printf("No matching PDU found.\n");
    }

    destroy_allocator(allocator);

    return 0;
}

int fetch_data(NFAPI_CRC_INDICATION_PDU_T **pdu) {
    static int call_count = 0;
    if (call_count < 10) { // Simulating fetching data from an external source
        *pdu = allocate_pdu(NULL); // Pass the actual allocator
        call_count++;
        return 0; // Success
    }
    return -1; // No more data
}
```

### Key Design Choices:
- **Slab Allocator**: Reduces fragmentation and improves cache locality by allocating memory in contiguous chunks.
- **Dynamic Resizing**: Managed through slab allocation without explicit resizing logic, leveraging fixed slabs for simplicity.
- **Filtering Mechanism**: Linear search optimized for small datasets; can be extended with more complex data structures if needed.
- **External Integration**: Simulated fetch function to demonstrate integration with external updates.
- **Error Handling**: Basic error handling in memory allocation and external fetching functions.']

