typedef struct {
    char name[50];
    int age;
} Person;

typedef enum {
    COMPLETED,
    PENDING,
    FAILED
} TransactionStatus;

typedef struct {
    time_t timestamp;
    double amount;
    TransactionStatus status;
} Transaction;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

double calculate_average_transaction_amount(Transaction *transactions, size_t num_transactions) {
    double total = 0.0;
    for (size_t i = 0; i < num_transactions; ++i) {
        total += transactions[i].amount;
    }
    return total / num_transactions;
}

int compare_transactions(const void *a, const void *b) {
    Transaction *ta = (Transaction *)a;
    Transaction *tb = (Transaction *)b;
    return difftime(ta->timestamp, tb->timestamp);
}

void process_transactions(size_t num_persons, size_t num_transactions) {
    Person *persons = malloc(num_persons * sizeof(Person));
    if (!persons) {
        log_error("Failed to allocate memory for persons");
        return;
    }

    Transaction *transactions = malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        free(persons);
        log_error("Failed to allocate memory for transactions");
        return;
    }

    // Initialize person objects
    for (size_t i = 0; i < num_persons; ++i) {
        snprintf(persons[i].name, sizeof(persons[i].name), "Person %zu", i + 1);
        persons[i].age = rand() % 100;
    }

    // Read transactions from standard input
    for (size_t i = 0; i < num_transactions; ++i) {
        if (fscanf(stdin, "%ld %lf %d", &transactions[i].timestamp, &transactions[i].amount, (int *)&transactions[i].status) != 3) {
            log_error("Invalid input format");
            free(persons);
            free(transactions);
            return;
        }
    }

    // Calculate and print the average transaction amount
    double avg_amount = calculate_average_transaction_amount(transactions, num_transactions);
    printf("Average Transaction Amount: %.2f\n", avg_amount);

    // Sort transactions by timestamp
    qsort(transactions, num_transactions, sizeof(Transaction), compare_transactions);

    // Print sorted transactions
    for (size_t i = 0; i < num_transactions; ++i) {
        printf("%ld %lf %d\n", transactions[i].timestamp, transactions[i].amount, transactions[i].status);
    }

    // Free allocated memory
    free(persons);
    free(transactions);
}

int main() {
    size_t num_persons = 5;
    size_t num_transactions = 10;

    printf("Enter %zu transactions (timestamp amount status):\n", num_transactions);
    process_transactions(num_persons, num_transactions);

    return 0;
}
