    double value;
} Record;

// Memory pool structure for custom allocation
typedef struct {
    size_t block_size;
    void *memory_pool;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void init_memory_pool(MemoryPool *pool, size_t block_size, size_t total_blocks);
void* pool_alloc(MemoryPool *pool);
void free_memory_pool(MemoryPool *pool);

// Error handling and logging
#define LOG_LEVEL_VERBOSE 1
#define LOG_LEVEL_ERROR   2

int log_level = LOG_LEVEL_VERBOSE;

void log_message(int level, const char *message) {
    if (level <= log_level) {
        fprintf(stderr, "%s\n", message);
    }
}

// Function to dynamically allocate and initialize an array of records
Record* create_records(size_t num_records, double min_value, double max_value,
                       MemoryPool *pool, void (*callback)(const Record*)) {

    if (num_records == 0 || pool == NULL) {
        log_message(LOG_LEVEL_ERROR, "Invalid input parameters.");
        return NULL;
    }

    Record *records = (Record *)pool_alloc(pool);
    if (!records) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for records.");
        return NULL;
    }

    // Generate unique offsets and random keys
    long offset_value = 1; // Start from 1 to ensure positive value
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offset_value++;
        records[i].key = rand() % 1000; // Example key generation

        // Initialize double values within the given range
        double value = ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value;
        records[i].value = value;

        if (callback) {
            callback(&records[i]);
        }
    }
    pthread_mutex_unlock(&pool->lock);

    return records;
}

void init_memory_pool(MemoryPool *pool, size_t block_size, size_t total_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->memory_pool = malloc(block_size * total_blocks);
    if (!pool->memory_pool) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for the pool.");
        exit(EXIT_FAILURE);
    }
    pool->used_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void* pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_blocks >= pool->total_blocks) {
        pthread_mutex_unlock(&pool->lock);
        log_message(LOG_LEVEL_ERROR, "Memory pool exhausted.");
        return NULL;
    }

    void *block = (char*)pool->memory_pool + (pool->used_blocks * pool->block_size);
    pool->used_blocks++;

    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
}

// Example callback function for integration with external data processing library
void example_callback(const Record *record) {
    // Implement according to the specific API of the external library
    printf("Processing record: offset=%ld, key=%d, value=%.2f\n", record->offset, record->key, record->value);
}

int main() {
    size_t num_records = 1000;
    double min_value = 10.0, max_value = 20.0;

    // Initialize memory pool
    MemoryPool pool;
    init_memory_pool(&pool, sizeof(Record), num_records);

    // Create records with callback integration
    Record *records = create_records(num_records, min_value, max_value, &pool, example_callback);

    if (records) {
        // Further processing...

        free_memory_pool(&pool);  // Free the custom memory pool
    }

    return 0;
}
```

### Key Points:
- **Custom Memory Pool**: A simple memory pool is implemented to manage allocation efficiently. It uses a mutex for thread safety.
- **Unique Offsets and Range Initialization**: Offsets are unique, starting from 1. Double values are initialized within the specified range.
- **Callback Interface**: The function supports a callback interface for integration with an external library.
- **Error Handling**: Basic logging is implemented to capture errors and messages based on verbosity levels.
- **Thread Safety**: Mutexes ensure thread safety during memory allocation.

This code aims to balance efficiency, error handling, and flexibility for different hardware configurations. Adjustments might be necessary based on specific requirements or the actual external library API being integrated with.']

