typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG; // Randomly set for each element
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
    uint32_t checksum; // Simple checksum for demonstration
} LinkedList;

uint32_t generate_random_crcflag() {
    return rand() % 2;
}

void update_checksum(LinkedList* list) {
    uint32_t newChecksum = 0;
    Node* current = list->head;
    while (current != NULL) {
        newChecksum ^= current->data.RX_UE_INFORMATION_TAG ^
                        current->data.RNTI ^ 
                        current->data.CRCFLAG;
        current = current->next;
    }
    list->checksum = newChecksum;
}

LinkedList* create_linked_list(size_t capacity) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->checksum = 0;

    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int append_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || !pthread_mutex_lock(&list->lock)) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newNode->data = data;
    newNode->next = NULL;

    if (!list->head) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }

    list->count++;
    update_checksum(list);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void handle_data_integrity(LinkedList* list) {
    uint32_t expectedChecksum = 0;
    Node* current = list->head;
    while (current != NULL) {
        expectedChecksum ^= current->data.RX_UE_INFORMATION_TAG ^
                            current->data.RNTI ^ 
                            current->data.CRCFLAG;
        current = current->next;
    }

    if (expectedChecksum != list->checksum) {
        fprintf(stderr, "Data integrity error detected.\n");
        // Handle correction here
    }
}

void* data_update_thread(void* arg) {
    LinkedList* list = (LinkedList*)arg;

    for (size_t i = 0; i < 100; ++i) { // Simulate updates
        NFAPI_CRC_INDICATION_PDU_T newElement;
        newElement.RX_UE_INFORMATION_TAG = rand();
        newElement.RNTI = rand() % 65535;
        newElement.CRCFLAG = generate_random_crcflag();

        append_to_list(list, newElement);
    }

    return NULL;
}

void populate_linked_list(LinkedList* list, size_t N) {
    srand(time(NULL));

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) { // Simulate concurrent updates
        if (pthread_create(&threads[i], NULL, data_update_thread, (void*)list)) {
            fprintf(stderr, "Error creating thread\n");
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    handle_data_integrity(list);
}

