#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1048576 // 1 MB in bytes

// Structure definition
typedef struct {
    int value;
    long *offset_ptr;
} record;

// Function for logging errors
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Thread-safe random number generator initialization
pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned int srandom_seed;

void initialize_random() {
    time_t now = time(NULL);
    pthread_mutex_lock(&rand_mutex);
    srandom_seed = (unsigned)now;
    pthread_mutex_unlock(&rand_mutex);
}

int generate_random(int min, int max) {
    pthread_mutex_lock(&rand_mutex);
    int result = random_r(&srandom_seed, &srandom_seed) % (max - min + 1) + min;
    pthread_mutex_unlock(&rand_mutex);
    return result;
}

// Memory allocation and initialization function
void manage_memory_allocation(size_t num_offsets_input) {
    size_t num_offsets = num_offsets_input;

    // Calculate the maximum number of offsets that can be allocated without exceeding 1 MB
    size_t max_num_offsets = MAX_MEMORY / sizeof(long); 
    if (num_offsets > max_num_offsets) {
        num_offsets = max_num_offsets;
    }

    // Align to 64 bytes for each allocation
    void *aligned_alloc(size_t alignment, size_t size) {
        void *ptr = NULL;
        if (posix_memalign(&ptr, alignment, size)) {
            return NULL; // Allocation failed
        }
        return ptr;
    }

    // Allocate memory for offsets
    long *offsets = aligned_alloc(64, num_offsets * sizeof(long));
    if (!offsets) {
        log_error("Failed to allocate memory for offsets.");
        return;
    }

    // Number of keys is half the number of offsets (rounding down)
    size_t num_keys = num_offsets / 2;

    // Allocate memory for keys
    int *keys = aligned_alloc(64, num_keys * sizeof(int));
    if (!keys) {
        log_error("Failed to allocate memory for keys.");
        free(offsets);
        return;
    }

    // Initialize record structures
    size_t num_records = num_offsets;
    record *records = aligned_alloc(64, num_records * sizeof(record));
    if (!records) {
        log_error("Failed to allocate memory for records.");
        free(keys);
        free(offsets);
        return;
    }

    initialize_random();

    // Populate the records array
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = generate_random(0, 1000);
        records[i].offset_ptr = &offsets[i];
    }

    // Print each record's int value followed by corresponding offset value
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu: Int Value = %d, Offset = %ld\n", i, records[i].value, *records[i].offset_ptr);
    }

    // Free the allocated memory
    free(keys);
    free(offsets);
    free(records);
}

int main() {
    size_t num_offsets_input;
    printf("Enter number of offsets: ");
    if (scanf("%zu", &num_offsets_input) != 1 || num_offsets_input <= 0) {
        log_error("Invalid input. Please enter a positive integer.");
        return EXIT_FAILURE;
    }

    manage_memory_allocation(num_offsets_input);
    return EXIT_SUCCESS;
}
```

