#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int valid;
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char CRCFLAG;
    time_t timestamp;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFALIST;

#define SUCCESS 0
#define MEMORY_ERROR -1

NFALIST* create_list() {
    NFALIST *list = (NFALIST *)malloc(sizeof(NFALIST));
    if (!list) return NULL;

    list->size = 0;
    list->capacity = 10; // Initial capacity
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int resize_list(NFALIST *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) return MEMORY_ERROR;

    list->elements = new_elements;
    list->capacity = new_capacity;
    return SUCCESS;
}

int add_element(NFALIST *list, int rnti, int valid, unsigned char crcflag) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&list->lock);
        return MEMORY_ERROR; // List full
    }

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;

        int result = resize_list(list, new_capacity);
        if (result != SUCCESS) {
            pthread_mutex_unlock(&list->lock);
            return MEMORY_ERROR;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[list->size];
    element->ue_info_tag.valid = valid;
    element->ue_info_tag.RNTI = rnti;
    element->rnti = rnti;
    element->crc_indication_tag.CRCFLAG = crcflag;
    element->crc_indication_tag.timestamp = time(NULL);

    list->size++;

    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

int filter_list(NFALIST *src, NFALIST **dst, int target_rnti) {
    pthread_mutex_lock(&src->lock);

    for (size_t i = 0; i < src->size; ++i) {
        if (src->elements[i].rnti == target_rnti) {
            size_t dst_capacity = 1;
            *dst = create_list();
            if (!*dst) {
                pthread_mutex_unlock(&src->lock);
                return MEMORY_ERROR;
            }

            while ((*dst)->size < src->size && (*dst)->elements[(*dst)->size].rnti != target_rnti) {
                NFAPI_CRC_INDICATION_PDU_T element = src->elements[i];
                int result = add_element(*dst, element.rnti, element.ue_info_tag.valid, element.crc_indication_tag.CRCFLAG);
                if (result == MEMORY_ERROR) {
                    pthread_mutex_destroy(&(*dst)->lock);
                    free((*dst)->elements);
                    free(*dst);
                    pthread_mutex_unlock(&src->lock);
                    return MEMORY_ERROR;
                }
            }

            break; // Exit after first match
        }
    }

    pthread_mutex_unlock(&src->lock);

    if ((*dst) && (*dst)->size == 0) { // If no elements were added
        destroy_list(*dst);
        *dst = NULL;
    }

    return SUCCESS;
}

void destroy_list(NFALIST *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->elements);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int serialize_list(const NFALIST *list, const char *filename) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
        return MEMORY_ERROR;
    }

    fwrite(&list->size, sizeof(size_t), 1, file);
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);

    fclose(file);

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return SUCCESS;
}

int deserialize_list(NFALIST **list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return MEMORY_ERROR;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    NFALIST *nfaList = create_list();
    if (!nfaList) {
        fclose(file);
        return MEMORY_ERROR;
    }

    nfaList->capacity = size > MAX_ELEMENTS ? MAX_ELEMENTS : size;
    int result = resize_list(nfaList, nfaList->capacity);
    if (result == MEMORY_ERROR) {
        destroy_list(nfaList);
        fclose(file);
        return MEMORY_ERROR;
    }

    fread(nfaList->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);

    nfaList->size = size;

    fclose(file);
    *list = nfaList;

    return SUCCESS;
}

