#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define MAX_TRANSACTIONS_PER_SECOND 1000000
#define BLOOM_FILTER_SIZE (MAX_TRANSACTIONS_PER_SECOND / 10)
#define TRANSACTION_DESC_LEN 256

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct {
    unsigned long transaction_id;
    char description[TRANSACTION_DESC_LEN];
    float amount;
    time_t timestamp;
} Transaction;

typedef struct {
    void *pool;
    size_t block_size;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

// Bloom filter for unique transaction ID checks
unsigned char bloom_filter[BLOOM_FILTER_SIZE];

void init_bloom_filter() {
    memset(bloom_filter, 0, BLOOM_FILTER_SIZE);
}

int check_bloom_filter(unsigned long id) {
    size_t index = id % BLOOM_FILTER_SIZE;
    return bloom_filter[index];
}

void add_to_bloom_filter(unsigned long id) {
    size_t index = id % BLOOM_FILTER_SIZE;
    bloom_filter[index] = 1;
}

// Memory pool functions
MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->pool_size = num_blocks;
    pool->pool = calloc(num_blocks, block_size);
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    static void *current_position = (char*)pool->pool;
    if ((char*)current_position + pool->block_size > (char*)pool->pool + pool->pool_size * pool->block_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }
    void *block = current_position;
    current_position += pool->block_size;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Record management
Record* records[MAX_RECORDS];
size_t num_records = 0;

pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

void add_record(long offset, int key, double value) {
    if (offset <= 0 || num_records >= MAX_RECORDS) return;
    pthread_mutex_lock(&record_lock);
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i]->offset == offset) {
            pthread_mutex_unlock(&record_lock);
            return; // Offset must be unique
        }
    }
    Record *new_record = allocate_from_pool(create_memory_pool(sizeof(Record), MAX_RECORDS));
    if (!new_record) {
        pthread_mutex_unlock(&record_lock);
        return;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    records[num_records++] = new_record;
    pthread_mutex_unlock(&record_lock);
}

// Transaction management
Transaction* transactions[MAX_TRANSACTIONS_PER_SECOND];
size_t num_transactions = 0;

pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;

void add_transaction(unsigned long transaction_id, const char *description, float amount, time_t timestamp) {
    if (check_bloom_filter(transaction_id)) return; // Already processed
    pthread_mutex_lock(&transaction_lock);
    Transaction *new_transaction = allocate_from_pool(create_memory_pool(sizeof(Transaction), MAX_TRANSACTIONS_PER_SECOND));
    if (!new_transaction) {
        pthread_mutex_unlock(&transaction_lock);
        return;
    }
    new_transaction->transaction_id = transaction_id;
    strncpy(new_transaction->description, description, TRANSACTION_DESC_LEN - 1);
    new_transaction->amount = amount;
    new_transaction->timestamp = timestamp;
    transactions[num_transactions++] = new_transaction;
    add_to_bloom_filter(transaction_id);
    pthread_mutex_unlock(&transaction_lock);
}

// Serialization and deserialization
void serialize_records(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;
    fwrite(records, sizeof(Record*), num_records, file);
    fclose(file);
}

void deserialize_records(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;
    fread(records, sizeof(Record*), MAX_RECORDS, file);
    fclose(file);
}

// Logging memory usage
void log_memory_usage() {
    size_t total_memory_used = num_records * sizeof(Record) + num_transactions * sizeof(Transaction);
    printf("Memory Usage: %zu bytes\n", total_memory_used);
}

int main() {
    init_bloom_filter();
    // Example usage
    add_record(1, 100, 123.45);
    add_transaction(1234567890UL, "Test transaction", 99.99f, time(NULL));
    serialize_records("records.dat");
    deserialize_records("records.dat");
    log_memory_usage();

    MemoryPool *record_pool = create_memory_pool(sizeof(Record), MAX_RECORDS);
    free_memory_pool(record_pool);

    return 0;
}
```

This code provides a basic implementation of the requirements, including memory pool management, bloom filter for transaction ID uniqueness, and thread safety using mutexes. Serialization and deserialization functions are also included to manage persistence.']

