void initializeDataStructures(size_t arraySize, const char* filenameTemplate) {
    double *doubleArray = NULL;
    char **stringArray = NULL;
    element *elementArray = NULL;

    // Allocate memory for the arrays
    doubleArray = (double *)malloc(arraySize * sizeof(double));
    stringArray = (char **)malloc(arraySize * sizeof(char *));
    elementArray = (element *)malloc(arraySize * sizeof(element));

    // Check if any allocation failed and handle gracefully
    if (!doubleArray || !stringArray || !elementArray) {
        fprintf(stderr, "Memory allocation failed\n");

        // Free any allocated memory before exiting
        free(doubleArray);
        free(stringArray);
        free(elementArray);

        exit(EXIT_FAILURE);  // Exit with failure status code
    }

    for (size_t i = 0; i < arraySize; ++i) {
        // Initialize double array elements
        doubleArray[i] = (double)i * 1.1;

        // Generate unique filenames using the template and index, then allocate memory
        char filename[256];
        snprintf(filename, sizeof(filename), "%s_%zu", filenameTemplate, i);
        stringArray[i] = strdup(filename);  // Use strdup to copy strings

        if (!stringArray[i]) {
            fprintf(stderr, "Memory allocation for string failed at index %zu\n", i);

            // Free previously allocated memory
            free(doubleArray);
            for (size_t j = 0; j < i; ++j) {
                free(stringArray[j]);
            }
            free(stringArray);
            free(elementArray);

            exit(EXIT_FAILURE);  // Exit with failure status code
        }

        // Initialize element struct members
        elementArray[i].floatValue = (float)i * 2.2;
        elementArray[i].intValue = (int)i * 3;
        elementArray[i].boolValue = i % 2 == 0;  // Alternate true/false
    }

    // Example usage of the arrays, would typically be more meaningful logic here

    // Release allocated memory to prevent leaks
    for (size_t i = 0; i < arraySize; ++i) {
        free(stringArray[i]);  // Free each dynamically allocated string
    }
    free(doubleArray);
    free(stringArray);
    free(elementArray);
}

// Example usage
int main() {
    initializeDataStructures(10, "example_filename");
    return 0;
}
