#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDINGS 100

typedef enum {
    AUDIO,
    VIDEO,
    OTHER
} MEDIA_TYPE;

typedef struct {
    time_t RECORDING_START_TIME;
    int RECORDING_DURATION; // in seconds
    MEDIA_TYPE MEDIA_TYPE;
} MEDIA_STREAM_RECORDING_T;

typedef struct {
    MEDIA_STREAM_RECORDING_T *recordings;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t capacity;
    int storage_capacity;
    float network_bandwidth_limit;
} RecordingManager;

RecordingManager* create_recording_manager(int initial_capacity, int storage_capacity, float bandwidth_limit) {
    RecordingManager *manager = (RecordingManager *)malloc(sizeof(RecordingManager));
    manager->recordings = (MEDIA_STREAM_RECORDING_T *)malloc(initial_capacity * sizeof(MEDIA_STREAM_RECORDING_T));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->storage_capacity = storage_capacity;
    manager->network_bandwidth_limit = bandwidth_limit;
    return manager;
}

void free_recording_manager(RecordingManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager->recordings);
    free(manager);
}

int add_recording(RecordingManager *manager, MEDIA_STREAM_RECORDING_T recording) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity || 
        manager->storage_capacity - recording.RECORDING_DURATION < 0 ||
        recording.MEDIA_TYPE == VIDEO && recording.RECORDING_DURATION > manager->network_bandwidth_limit) {

        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->recordings = realloc(manager->recordings, new_capacity * sizeof(MEDIA_STREAM_RECORDING_T));
        manager->capacity = new_capacity;
    }

    manager->recordings[manager->count++] = recording;

    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void* process_recordings(void* arg) {
    RecordingManager *manager = (RecordingManager *)arg;

    while (1) {
        pthread_mutex_lock(&manager->lock);

        if (manager->count == 0) {
            pthread_cond_wait(&manager->cond, &manager->lock);
        }

        // Process recordings
        for (size_t i = 0; i < manager->count; ++i) {
            MEDIA_STREAM_RECORDING_T *recording = &manager->recordings[i];
            time_t current_time = time(NULL);

            if (current_time >= recording->RECORDING_START_TIME) {
                // Simulate media processing
                printf("Processing recording of type %d starting at %ld\n", recording->MEDIA_TYPE, recording->RECORDING_START_TIME);

                // Update storage and bandwidth usage
                manager->storage_capacity -= recording->RECORDING_DURATION;

                // Clear processed recording
                if (i < manager->count - 1) {
                    *recording = manager->recordings[manager->count - 1];
                }
                --manager->count;
            }
        }

        pthread_mutex_unlock(&manager->lock);

        // Simulate time delay for processing
        sleep(1);
    }

    return NULL;
}

int main() {
    RecordingManager *manager = create_recording_manager(10, 1000, 300.0);

    pthread_t processing_thread;
    pthread_create(&processing_thread, NULL, process_recordings, manager);

    // Simulate adding recordings
    MEDIA_STREAM_RECORDING_T new_recording = { .RECORDING_START_TIME = time(NULL) + 5, .RECORDING_DURATION = 10, .MEDIA_TYPE = AUDIO };
    add_recording(manager, new_recording);

    pthread_join(processing_thread, NULL);

    free_recording_manager(manager);
    return 0;
