#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

#define MAX_THREADS 10000
#define RECORD_COUNT 1000
#define INITIAL_POOL_SIZE 50
#define MAX_STRUCTURES 500
#define LOG_FLUSH_INTERVAL 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
} record_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Buffer pool structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t capacity;
    size_t used;
} BufferPool;

void initialize_random() {
    srand(time(NULL));
}

int is_unique_rnti(int rnti, NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    for (int i = 0; i < count; ++i) {
        if (array[i].RNTI == rnti) return 0;
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* create_struct(BufferPool* pool) {
    pthread_mutex_lock(&lock);

    if (pool->used >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        pool->pool = new_pool;
        pool->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* struct_ptr = &pool->pool[pool->used];
    struct_ptr->RX_UE_INFORMATION_TAG = rand();
    do {
        struct_ptr->RNTI = rand();
    } while (!is_unique_rnti(struct_ptr->RNTI, pool->pool, pool->used));
    struct_ptr->CRC_INDICATION_REL8_TAG = rand();
    struct_ptr->CRCFLAG = rand() % 2;

    pool->used++;
    pthread_mutex_unlock(&lock);

    return struct_ptr;
}

void log_structure(NFAPI_CRC_INDICATION_PDU_T* struct_ptr, int count) {
    static int flush_count = 0;

    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
           struct_ptr->RX_UE_INFORMATION_TAG,
           struct_ptr->RNTI,
           struct_ptr->CRC_INDICATION_REL8_TAG,
           struct_ptr->CRCFLAG);

    flush_count++;
    if (flush_count >= LOG_FLUSH_INTERVAL) {
        fflush(stdout);
        flush_count = 0;
    }
}

void* worker(void* arg) {
    BufferPool* pool = (BufferPool*)arg;

    for (int i = 0; i < RECORD_COUNT; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_struct(pool);
        if (!pdu) break;

        log_structure(pdu, i);

        // Simulate processing delay
        usleep(1000); 
    }

    return NULL;
}

int main() {
    initialize_random();

    BufferPool pool = { malloc(INITIAL_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T)), INITIAL_POOL_SIZE, 0 };

    if (!pool.pool) {
        printf("Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker, &pool);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(pool.pool);

    return EXIT_SUCCESS;
}
