['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_RANGE 1000
#define CONFIG_FILE "settings.cfg"
#define BIN_FILE "crc_indications.bin"
#define LOG_FILE "process_log.txt"
#define PRIMARY_LIST_SIZE 1024 // Max elements in primary list
#define SECONDARY_QUEUE_SIZE 10

typedef struct {
    int rx_ue_information_tag;
    int rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    // Other fields...
} NFAPI_CELLULAR_EVENT_PDU_T;

// Configuration settings
int range_limit = MAX_RANGE;
double crc_probability = 0.5;
int compression_threshold = 1024;
pthread_mutex_t mutex_primary = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_secondary = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    void *data;
    size_t size;
} Element;

typedef struct {
    Element elements[PRIMARY_LIST_SIZE];
    size_t count;
} PrimaryList;

typedef struct {
    void **queue;
    size_t front, rear, size;
} SecondaryQueue;

PrimaryList primary_list = {.count = 0};
SecondaryQueue secondary_queue = {.queue = malloc(SECONDARY_QUEUE_SIZE * sizeof(void*)), .front = 0, .rear = -1, .size = SECONDARY_QUEUE_SIZE};

void load_config() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file) {
        fscanf(file, "%d", &range_limit);
        fscanf(file, "%lf", &crc_probability);
        fscanf(file, "%d", &compression_threshold);
        fclose(file);
    } else {
        fprintf(stderr, "Configuration file missing or unreadable. Using default settings.\n");
    }
}

bool is_within_range(int value) {
    return value >= 0 && value < range_limit;
}

unsigned int custom_hash(int *data, size_t length) {
    unsigned int hash = 5381;
    for (size_t i = 0; i < length; ++i) {
        hash = ((hash << 5) + hash) + data[i];
    }
    return hash % range_limit;
}

bool validate_data(NFAPI_CRC_INDICATION_PDU_T *crcs, size_t n, NFAPI_CELLULAR_EVENT_PDU_T *events, size_t m) {
    int temp[2 * (n + m)];

    for (size_t i = 0; i < n; ++i) {
        if (!is_within_range(crcs[i].tag.rx_ue_information_tag) || !is_within_range(crcs[i].tag.rnti)) return false;
        temp[i * 2] = crcs[i].tag.rx_ue_information_tag;
        temp[i * 2 + 1] = crcs[i].tag.rnti;
    }

    for (size_t i = 0; i < m; ++i) {
        if (!is_within_range(events[i].tag.rx_ue_information_tag) || !is_within_range(events[i].tag.rnti)) return false;
        temp[n * 2 + i * 2] = events[i].tag.rx_ue_information_tag;
        temp[n * 2 + i * 2 + 1] = events[i].tag.rnti;
    }

    unsigned int hash_table[range_limit];
    memset(hash_table, -1, sizeof(hash_table));

    for (size_t i = 0; i < 2 * (n + m); ++i) {
        unsigned int index = custom_hash(&temp[i], 1);

        if (hash_table[index] != -1) return false;
        hash_table[index] = i;
    }

    return true;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s]: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

bool add_to_primary_list(void *element, size_t size) {
    pthread_mutex_lock(&mutex_primary);

    if (primary_list.count >= PRIMARY_LIST_SIZE) {
        pthread_mutex_unlock(&mutex_primary);
        return false;
    }

    primary_list.elements[primary_list.count].data = malloc(size);
    memcpy(primary_list.elements[primary_list.count].data, element, size);
    primary_list.elements[primary_list.count].size = size;

    log_message("Added to primary list");

    pthread_mutex_unlock(&mutex_primary);

    return true;
}

bool add_to_secondary_queue(void *element) {
    pthread_mutex_lock(&mutex_secondary);

    if ((secondary_queue.rear + 1) % SECONDARY_QUEUE_SIZE == secondary_queue.front) {
        pthread_mutex_unlock(&mutex_secondary);
        return false;
    }

    secondary_queue.rear = (secondary_queue.rear + 1) % SECONDARY_QUEUE_SIZE;
    secondary_queue.queue[secondary_queue.rear] = element;

    log_message("Added to secondary queue");

    pthread_mutex_unlock(&mutex_secondary);

    return true;
}

void serialize_and_write(FILE *file, void *data, size_t size) {
    fwrite(data, 1, size, file);
}

int main(int argc, char **argv) {
    load_config();

    int n = (argc > 1) ? atoi(argv[1]) : 5;
    int m = (argc > 2) ? atoi(argv[2]) : 3;

    NFAPI_CRC_INDICATION_PDU_T *crcs = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CELLULAR_EVENT_PDU_T *events = malloc(m * sizeof(NFAPI_CELLULAR_EVENT_PDU_T));

    if (!crcs || !events) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        crcs[i].tag.rx_ue_information_tag = rand() % range_limit;
        crcs[i].tag.rnti = rand() % range_limit;
        crcs[i].crcflag = (double)rand() / RAND_MAX < crc_probability;

        if (!add_to_primary_list(&crcs[i], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            fprintf(stderr, "Failed to add CRC indication\n");
            free(crcs);
            free(events);
            return 1;
        }

        if (i < SECONDARY_QUEUE_SIZE && !add_to_secondary_queue(&crcs[i])) {
            log_message("Failed to add to secondary queue");
        }
    }

    for (int i = 0; i < m; ++i) {
        events[i].tag.rx_ue_information_tag = rand() % range_limit;
        events[i].tag.rnti = rand() % range_limit;

        if (!add_to_primary_list(&events[i], sizeof(NFAPI_CELLULAR_EVENT_PDU_T))) {
            fprintf(stderr, "Failed to add cellular event\n");
            free(crcs);
            free(events);
            return 1;
        }
    }

    if (!validate_data(crcs, n, events, m)) {
        log_message("Data validation failed");
        free(crcs);
        free(events);
        return 1;
    }

    FILE *bin_file = fopen(BIN_FILE, "wb");
    if (!bin_file) {
        fprintf(stderr, "Failed to open binary file\n");
        free(crcs);
        free(events);
        return 1;
    }

    for (size_t i = 0; i < primary_list.count; ++i) {
        serialize_and_write(bin_file, primary_list.elements[i].data, primary_list.elements[i].size);
    }

    fclose(bin_file);

    log_message("Serialization complete");

    free(crcs);
    free(events);
    free(secondary_queue.queue);

    return 0;
}
