```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_UES 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_MESSAGE_PDU_T* ues[MAX_UES];
    int num_ues;
    float snr_stats[3]; // [average, min, max]
} ChannelState;

// Random noise generator
float generate_random_noise() {
    return (rand() / (float)RAND_MAX) * 10.0; // Simulate noise factor between 0 and 10 dB
}

void initialize_channel(ChannelState* channel) {
    pthread_mutex_init(&channel->lock, NULL);
    channel->num_ues = 0;
    channel->snr_stats[0] = 0.0f;
    channel->snr_stats[1] = FLT_MAX;
    channel->snr_stats[2] = -FLT_MAX;
}

void calculate_snr_and_update(ChannelState* channel, int ue_index) {
    float noise_factor = generate_random_noise();
    float snr_value = 20.0f - noise_factor; // Base SNR of 20 dB reduced by noise factor

    pthread_mutex_lock(&channel->lock);

    if (ue_index < channel->num_ues && channel->ues[ue_index] != NULL) {
        NFAPI_MESSAGE_PDU_T* pdu = channel->ues[ue_index];
        pdu->SNR_INDICATION_REL8_TAG = (uint8_t)(snr_value);

        // Update SNR statistics
        float avg_snr = channel->snr_stats[0];
        int count = channel->num_ues;

        avg_snr = ((avg_snr * (count - 1)) + snr_value) / count;
        if (snr_value < channel->snr_stats[1]) {
            channel->snr_stats[1] = snr_value;
        }
        if (snr_value > channel->snr_stats[2]) {
            channel->snr_stats[2] = snr_value;
        }

        channel->snr_stats[0] = avg_snr;

        printf("UE %d: SNR updated to %.2f dB\n", ue_index, snr_value);
    } else {
        fprintf(stderr, "Warning: UE index out of bounds or memory allocation failed.\n");
    }

    pthread_mutex_unlock(&channel->lock);
}

void add_ue(ChannelState* channel) {
    if (channel->num_ues >= MAX_UES) {
        fprintf(stderr, "Error: Maximum UEs reached. Cannot add more UEs.\n");
        return;
    }

    NFAPI_MESSAGE_PDU_T* pdu = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for new UE.\n");
        return;
    }

    pthread_mutex_lock(&channel->lock);

    pdu->RX_UE_INFORMATION_TAG = rand() % 10000; // Simulate a unique tag
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2); // Randomly set CRC indication

    channel->ues[channel->num_ues++] = pdu;

    pthread_mutex_unlock(&channel->lock);
}

void remove_ue(ChannelState* channel, int ue_index) {
    pthread_mutex_lock(&channel->lock);

    if (ue_index < channel->num_ues && channel->ues[ue_index] != NULL) {
        free(channel->ues[ue_index]);
        for (int i = ue_index; i < channel->num_ues - 1; ++i) {
            channel->ues[i] = channel->ues[i + 1];
        }
        channel->ues[channel->num_ues - 1] = NULL;
        --channel->num_ues;

        printf("UE %d removed.\n", ue_index);
    } else {
        fprintf(stderr, "Warning: UE index out of bounds or UE does not exist.\n");
    }

    pthread_mutex_unlock(&channel->lock);
}

void* snr_update_thread(void* arg) {
    ChannelState* channel = (ChannelState*)arg;

    while (1) {
        for (int i = 0; i < channel->num_ues; ++i) {
            calculate_snr_and_update(channel, i);
        }

        pthread_mutex_lock(&channel->lock);

        printf("SNR Stats - Average: %.2f dB, Min: %.2f dB, Max: %.2f dB\n",
               channel->snr_stats[0], channel->snr_stats[1], channel->snr_stats[2]);

        pthread_mutex_unlock(&channel->lock);

        sleep(5); // Update every 5 seconds
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    ChannelState channels[4]; // Example with four channels

    for (int i = 0; i < 4; ++i) {
        initialize_channel(&channels[i]);
    }

    pthread_t update_threads[4];

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&update_threads[i], NULL, snr_update_thread, &channels[i])) {
            fprintf(stderr, "Error creating thread.\n");
            return EXIT_FAILURE;
        }
    }

    // Simulate adding UEs to channels
    for (int i = 0; i < MAX_UES / 2; ++i) {
        add_ue(&channels[0]);
    }

    // Join threads (in a real application, you might want to handle shutdown gracefully)
    for (int i = 0; i < 4; ++i) {
        pthread_join(update_threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
