['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_OFFSET 1000000
#define MAX_SUM_OFFSETS 50000000

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rwlock;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = malloc(initial_capacity * sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_rwlock_init(&manager->rwlock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager *manager) {
    if (manager) {
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        pthread_rwlock_destroy(&manager->rwlock);
        free(manager);
    }
}

bool is_valid_offset(long offset) {
    return offset > 0 && offset <= MAX_OFFSET;
}

bool is_unique_offset(RecordManager *manager, long offset) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].offset == offset) {
            return false;
        }
    }
    return true;
}

bool is_valid_key(int key) {
    return key >= 0 && key <= INT_MAX;
}

bool is_unique_key(RecordManager *manager, int key) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            return false;
        }
    }
    return true;
}

double generate_random_value(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

bool initialize_records(RecordManager *manager, size_t num_records, int key_min, int key_max, double value_min, double value_max) {
    pthread_mutex_lock(&manager->lock);

    if (num_records > manager->capacity) {
        Record *new_records = realloc(manager->records, num_records * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        manager->records = new_records;
        manager->capacity = num_records;
    }

    long sum_offsets = 0;
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        long offset;
        int key;
        double value;

        do {
            offset = rand() % MAX_OFFSET + 1;
        } while (!is_valid_offset(offset) || !is_unique_offset(manager, offset) || sum_offsets + offset > MAX_SUM_OFFSETS);

        do {
            key = rand() % (key_max - key_min + 1) + key_min;
        } while (!is_valid_key(key) || !is_unique_key(manager, key));

        value = generate_random_value(value_min, value_max);

        manager->records[i].offset = offset;
        manager->records[i].key = key;
        manager->records[i].value = value;

        sum_offsets += offset;
    }

    manager->count = num_records;
    pthread_mutex_unlock(&manager->lock);
    return true;
}

void add_record(RecordManager *manager, long offset, int key, double value) {
    pthread_rwlock_wrlock(&manager->rwlock);

    if (!is_valid_offset(offset) || !is_unique_offset(manager, offset)) {
        pthread_rwlock_unlock(&manager->rwlock);
        fprintf(stderr, "Error: Invalid or duplicate offset.\n");
        return;
    }

    if (!is_valid_key(key) || !is_unique_key(manager, key)) {
        pthread_rwlock_unlock(&manager->rwlock);
        fprintf(stderr, "Error: Invalid or duplicate key.\n");
        return;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_rwlock_unlock(&manager->rwlock);
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return;
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->count++] = (Record){offset, key, value};
    pthread_rwlock_unlock(&manager->rwlock);
}

void remove_record(RecordManager *manager, long offset) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].offset == offset) {
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->records[j] = manager->records[j + 1];
            }
            --manager->count;
            pthread_rwlock_unlock(&manager->rwlock);
            return;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    fprintf(stderr, "Error: Record with offset %ld not found.\n", offset);
}

void update_record(RecordManager *manager, long offset, int key, double value) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].offset == offset) {
            if (!is_valid_key(key)) {
                pthread_rwlock_unlock(&manager->rwlock);
                fprintf(stderr, "Error: Invalid key.\n");
                return;
            }
            manager->records[i].key = key;
            manager->records[i].value = value;
            pthread_rwlock_unlock(&manager->rwlock);
            return;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    fprintf(stderr, "Error: Record with offset %ld not found.\n", offset);
}

Record* get_record_by_offset(RecordManager *manager, long offset) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].offset == offset) {
            Record *record = malloc(sizeof(Record));
            if (!record) {
                pthread_rwlock_unlock(&manager->rwlock);
                return NULL;
            }
            *record = manager->records[i];
            pthread_rwlock_unlock(&manager->rwlock);
            return record;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    fprintf(stderr, "Error: Record with offset %ld not found.\n", offset);
    return NULL;
}

Record* get_record_by_key(RecordManager *manager, int key) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            Record *record = malloc(sizeof(Record));
            if (!record) {
                pthread_rwlock_unlock(&manager->rwlock);
                return NULL;
            }
            *record = manager->records[i];
            pthread_rwlock_unlock(&manager->rwlock);
            return record;
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    fprintf(stderr, "Error: Record with key %d not found.\n", key);
    return NULL;
}

void generate_report(RecordManager *manager) {
    pthread_rwlock_rdlock(&manager->rwlock);

    if (manager->count == 0) {
        printf("No records available for reporting.\n");
        pthread_rwlock_unlock(&manager->rwlock);
        return;
    }

    long sum_offsets = 0;
    int max_key = manager->records[0].key;
    int min_key = manager->records[0].key;
    double total_value = 0.0;

    for (size_t i = 0; i < manager->count; ++i) {
        sum_offsets += manager->records[i].offset;
        if (manager->records[i].key > max_key) max_key = manager->records[i].key;
        if (manager->records[i].key < min_key) min_key = manager->records[i].key;
        total_value += manager->records[i].value;
    }

    double avg_offset = (double)sum_offsets / manager->count;

    printf("Report:\n");
    printf("Average Offset: %.2f\n", avg_offset);
    printf("Max Key: %d\n", max_key);
    printf("Min Key: %d\n", min_key);
    printf("Total Value Sum: %.2f\n", total_value);

    pthread_rwlock_unlock(&manager->rwlock);
}
```']

