    } else if (strcmp(algorithm, "Camellia") == 0) {
        if (!EVP_EncryptInit_ex(record->cipher_ctx, EVP_camellia_128_cbc(), NULL, NULL, NULL)) {
            handle_openssl_error();
        }
    } // Add other algorithms as needed

    return record;
}

// Handle OpenSSL errors
void handle_openssl_error() {
    ERR_print_errors_fp(stderr);
    exit(EXIT_FAILURE);
}

// Clean up cryptographic record
void cleanup_crypto_record(CryptoRecord *record) {
    if (record) {
        pthread_mutex_lock(&record->lock);
        EVP_CIPHER_CTX_free(record->cipher_ctx);
        EVP_MD_CTX_free(record->digest_ctx);
        pthread_mutex_unlock(&record->lock);

        free(record->algorithm_name);
        pthread_mutex_destroy(&record->lock);
        free(record);
    }
}

// Example function for performing encryption
int encrypt_data(CryptoRecord *record, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext) {
    pthread_mutex_lock(&record->lock);

    if (!EVP_EncryptInit_ex(record->cipher_ctx, NULL, NULL, (unsigned char *)"key", (unsigned char *)"iv")) {
        handle_openssl_error();
    }

    int len;
    int ciphertext_len;

    if (!EVP_EncryptUpdate(record->cipher_ctx, ciphertext, &len, plaintext, plaintext_len)) {
        handle_openssl_error();
    }
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(record->cipher_ctx, ciphertext + len, &len)) {
        handle_openssl_error();
    }
    ciphertext_len += len;

    pthread_mutex_unlock(&record->lock);
    return ciphertext_len;
}

// Example function for computing digest
int compute_digest(CryptoRecord *record, const unsigned char *data, int data_len,
                   unsigned char *digest) {
    pthread_mutex_lock(&record->lock);

    if (!EVP_DigestInit_ex(record->digest_ctx, EVP_sha1(), NULL)) {
        handle_openssl_error();
    }

    if (!EVP_DigestUpdate(record->digest_ctx, data, data_len)) {
        handle_openssl_error();
    }

    unsigned int digest_len;
    if (!EVP_DigestFinal_ex(record->digest_ctx, digest, &digest_len)) {
        handle_openssl_error();
    }

    pthread_mutex_unlock(&record->lock);
    return 0; // Success
}

int main() {
    initialize_crypto_module();

    CryptoRecord *record = setup_crypto_record("AES", 256);
    if (!record) {
