['Below is the C code implementing the described task. This solution takes into account memory efficiency, thread safety, dynamic memory allocation, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_COUNT 10000

typedef struct {
    unsigned int tag;
    unsigned long rnti;
    unsigned short crc_indication;
    float snr;
} NFAPI_MESSAGE_PDU_T;

typedef struct Record {
    long *offset_ptr;
    int key;
    struct Record *next;
} Record;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static float global_max_snr = -1.0f;
static Record *head = NULL;

float calculate_snr() {
    // Simulate SNR calculation with random noise
    return (rand() % 100) / 10.0 + (rand() % 20 - 10) / 100.0; // Example range: 0.0 to 11.9
}

void *snr_cache(void *data) {
    NFAPI_MESSAGE_PDU_T *nfa = (NFAPI_MESSAGE_PDU_T *) data;
    nfa->snr = calculate_snr();
    return NULL;
}

int is_valid_key(int key) {
    return key >= 0 && key <= 65535;
}

void add_record(long *offsets, int num_keys, int keys[]) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < num_keys; ++i) {
        // Check for duplicate keys
        Record *current = head;
        while (current) {
            if (current->key == keys[i]) {
                fprintf(stderr, "Duplicate key found: %d\n", keys[i]);
                exit(EXIT_FAILURE);
            }
            current = current->next;
        }

        Record *new_record = malloc(sizeof(Record));
        if (!new_record) {
            perror("Failed to allocate memory for new record");
            exit(EXIT_FAILURE);
        }

        new_record->offset_ptr = &offsets[i];
        new_record->key = keys[i];
        new_record->next = head;
        head = new_record;

        // Update global maximum SNR
        if (keys[i] > global_max_snr) {
            global_max_snr = keys[i];
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void free_records() {
    Record *current = head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    long resource_offsets[10000] = {0};
    int num_keys, key;

    printf("Enter number of keys: ");
    scanf("%d", &num_keys);

    if (num_keys <= 0) {
        fprintf(stderr, "Number of keys must be positive.\n");
        return EXIT_FAILURE;
    }

    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys array");
        return EXIT_FAILURE;
    }

    printf("Enter %d unique keys (0-65535):\n", num_keys);
    int count = 0;
    while (count < num_keys) {
        scanf("%d", &key);
        if (key < 0) break;

        if (!is_valid_key(key)) {
            fprintf(stderr, "Invalid key: %d\n", key);
            continue;
        }

        for (int i = 0; i < count; ++i) {
            if (keys[i] == key) {
                fprintf(stderr, "Duplicate key found: %d\n", key);
                exit(EXIT_FAILURE);
            }
        }

        keys[count++] = key;
    }

    if (count != num_keys) {
        fprintf(stderr, "Number of unique keys entered does not match the expected number.\n");
        free(keys);
        return EXIT_FAILURE;
    }

    NFAPI_MESSAGE_PDU_T nfa_array[MAX_UE_COUNT];
    pthread_t threads[MAX_UE_COUNT];

    for (int i = 0; i < MAX_UE_COUNT; ++i) {
        nfa_array[i].tag = rand() % 256;
        nfa_array[i].rnti = rand();
        nfa_array[i].crc_indication = rand() & 0xFFFF;

        pthread_create(&threads[i], NULL, snr_cache, &nfa_array[i]);
    }

    for (int i = 0; i < MAX_UE_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }

    add_record(resource_offsets, num_keys, keys);

    printf("Maximum key value: %d\n", global_max_snr);

    free_records();
    free(keys);

    return EXIT_SUCCESS;
}
```

### Key Points:
- The code uses threading to calculate SNR values concurrently for performance.
- Memory allocation failures are checked and handled gracefully with error messages.
- Thread safety is ensured using a mutex when accessing the linked list.
- Unique key validation and duplicate checks ensure data integrity.
- A singly linked list manages records, allowing efficient insertions at the head.
- The program dynamically calculates SNR values simulating real-world conditions.
- Memory management strategies are implemented to avoid memory leaks.']

