    if (context->pool_size == 0) {
        size_t new_pool_size = context->pool_size + INITIAL_POOL_SIZE;
        RRC_CONNECTION_CONFIG_T *new_pool = realloc(context->rrc_config_pool, new_pool_size * sizeof(RRC_CONNECTION_CONFIG_T));
        if (!new_pool) {
            pthread_mutex_unlock(&context->lock);
            return NULL; // Handle memory allocation failure
        }
        context->rrc_config_pool = new_pool;
        context->pool_size = new_pool_size;
