    pthread_mutex_lock(&aes_manager.ctx_locks[index]);
    EVP_CIPHER_CTX_init(ctx);
    pthread_mutex_unlock(&aes_manager.ctx_locks[index]);
}

void finalize_aes_context(EVP_CIPHER_CTX *ctx, int index) {
    pthread_mutex_lock(&aes_manager.ctx_locks[index]);
    EVP_CIPHER_CTX_cleanup(ctx);
    pthread_mutex_unlock(&aes_manager.ctx_locks[index]);
}

int aes_initialize() {
    for (int i = 0; i < MAX_CIPHER_CONTEXTS; ++i) {
        pthread_mutex_init(&aes_manager.ctx_locks[i], NULL);
        initialize_aes_context(&aes_manager.ctx[i], i);
    }
    aes_manager.active_count = 0;
    return 0;
}

void aes_cleanup() {
    for (int i = 0; i < MAX_CIPHER_CONTEXTS; ++i) {
        finalize_aes_context(aes_manager.ctx[i], i);
        pthread_mutex_destroy(&aes_manager.ctx_locks[i]);
    }
}

