    data->device_ids = (char **)malloc(initial_capacity * DEVICE_ID_BUFFER_SIZE);
    data->events = (sensor_event *)malloc(initial_capacity * SENSOR_EVENT_STRUCT_SIZE);

    if (!data->sensor_readings || !data->device_ids || !data->events) {
        // Handle allocation failure
        log_message("Failed to allocate sensor data memory.");
        exit(EXIT_FAILURE);
    }
}

void update_sensor_data(SensorData *data, double new_reading, const char *new_id, sensor_event new_event) {
    pthread_mutex_lock(&data->lock);

    if (data->count >= data->capacity) {
        // Double the capacity
        size_t new_capacity = data->capacity * 2;
        data->sensor_readings = (double *)realloc(data->sensor_readings, new_capacity * sizeof(double));
        data->device_ids = (char **)realloc(data->device_ids, new_capacity * DEVICE_ID_BUFFER_SIZE);
        data->events = (sensor_event *)realloc(data->events, new_capacity * SENSOR_EVENT_STRUCT_SIZE);

        if (!data->sensor_readings || !data->device_ids || !data->events) {
            log_message("Failed to reallocate sensor data memory.");
            pthread_mutex_unlock(&data->lock);
            exit(EXIT_FAILURE);
        }

        data->capacity = new_capacity;
    }

    // Update the data
    data->sensor_readings[data->count] = new_reading;
    strncpy(data->device_ids[data->count], new_id, DEVICE_ID_BUFFER_SIZE);
    data->events[data->count] = new_event;

    ++data->count;

    pthread_mutex_unlock(&data->lock);
