    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        list->messages = (ZEROMQ_MESSAGE *)realloc(list->messages, new_capacity * sizeof(ZEROMQ_MESSAGE));

        if (!list->messages) {
