            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }

        list->capacity = new_capacity;
    }

    // Add the new message
    list->messages[list->count++] = new_message;

    pthread_mutex_unlock(&list->lock);
