#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_ELEMENTS 10000

typedef struct CRC_INDICATION_REL8_TAG {
    uint16_t CRCFLAG; // Randomly set
} CRC_INDICATION_REL8_TAG;

typedef struct RX_UE_INFORMATION_TAG {
    int UE_ID;
    uint32_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    int count;
    pthread_mutex_t mutex;
} CRC_LIST;

CRC_LIST* create_list() {
    CRC_LIST *list = (CRC_LIST *)malloc(sizeof(CRC_LIST));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(CRC_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_element(CRC_LIST *list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t crc_flag) {
    if (list->count >= MAX_ELEMENTS) return;

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return;

    new_node->ue_info_tag = ue_info_tag;
    new_node->crc_indication_rel8_tag.CRCFLAG = crc_flag;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void serialize_list(CRC_LIST *list, uint8_t **buffer, size_t *size) {
    pthread_mutex_lock(&list->mutex);

    // Calculate required buffer size
    size_t total_size = sizeof(int); // Count of elements
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        total_size += sizeof(RX_UE_INFORMATION_TAG);
        total_size += sizeof(CRC_INDICATION_REL8_TAG);
        current = current->next;
    }

    *buffer = (uint8_t *)malloc(total_size);
    if (!*buffer) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    uint8_t *ptr = *buffer;

    // Write count
    int count = list->count;
    memcpy(ptr, &count, sizeof(count));
    ptr += sizeof(count);

    // Write elements
    current = list->head;
    while (current) {
        RX_UE_INFORMATION_TAG ue_info_tag = current->ue_info_tag;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag = current->crc_indication_rel8_tag;

        memcpy(ptr, &ue_info_tag, sizeof(ue_info_tag));
        ptr += sizeof(ue_info_tag);

        memcpy(ptr, &crc_indication_rel8_tag, sizeof(crc_indication_rel8_tag));
        ptr += sizeof(crc_indication_rel8_tag);

        current = current->next;
    }

    *size = total_size;

    pthread_mutex_unlock(&list->mutex);
}

void deserialize_list(CRC_LIST *list, const uint8_t *buffer) {
    pthread_mutex_lock(&list->mutex);

    // Clear existing list
    destroy_list(list);
    list->head = NULL;
    list->count = 0;

    int count;
    memcpy(&count, buffer, sizeof(count));
    buffer += sizeof(count);

    for (int i = 0; i < count && list->count < MAX_ELEMENTS; ++i) {
        RX_UE_INFORMATION_TAG ue_info_tag;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;

        memcpy(&ue_info_tag, buffer, sizeof(ue_info_tag));
        buffer += sizeof(ue_info_tag);

        memcpy(&crc_indication_rel8_tag, buffer, sizeof(crc_indication_rel8_tag));
        buffer += sizeof(crc_indication_rel8_tag);

        add_element(list, ue_info_tag, crc_indication_rel8_tag.CRCFLAG);
    }

    pthread_mutex_unlock(&list->mutex);
}
