#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
import json-c/json.h;
import zstd.h;
import sqlite3.h;
#include <pthread.h>
#include <time.h>

typedef struct {
    int sensor_count;
    char sensor_type;
    time_t event_timestamp;
    float sensor_value;
    double quality_metric;
    uint64_t identifier;
    char *description;
} SensorRecord;

typedef struct {
    SensorRecord **records;
    size_t count;
    size_t capacity;
    sqlite3 *db;
    pthread_mutex_t lock;
} SensorDatabase;

void init_sensor_db(SensorDatabase *db, const char *db_path) {
    db->records = NULL;
    db->count = 0;
    db->capacity = 10;
    db->records = malloc(db->capacity * sizeof(SensorRecord*));
    pthread_mutex_init(&db->lock, NULL);

    if (sqlite3_open_v2(db_path, &db->db, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE, NULL) != SQLITE_OK) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db->db));
        exit(1);
    }
}

void validate_and_store_sensor(SensorDatabase *db, SensorRecord *record) {
    pthread_mutex_lock(&db->lock);

    // Validate against the external database
    char query[256];
    snprintf(query, sizeof(query), "SELECT COUNT(*) FROM sensors WHERE identifier = %llu", record->identifier);
    sqlite3_stmt *stmt;
    if (sqlite3_prepare_v2(db->db, query, -1, &stmt, NULL) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW && sqlite3_column_int(stmt, 0) > 0) {
            pthread_mutex_unlock(&db->lock);
            return; // Record already exists
        }
    }

    // Store the record in memory
    if (db->count >= db->capacity) {
        db->capacity *= 2;
        db->records = realloc(db->records, db->capacity * sizeof(SensorRecord*));
    }
    db->records[db->count++] = record;

    pthread_mutex_unlock(&db->lock);
}

void free_sensor_db(SensorDatabase *db) {
    for (size_t i = 0; i < db->count; ++i) {
        free(db->records[i]->description);
        free(db->records[i]);
    }
    free(db->records);
    sqlite3_close(db->db);
    pthread_mutex_destroy(&db->lock);
}

void serialize_to_compressed_json(SensorDatabase *db, const char *output_file) {
    json_object *jArray = json_object_new_array();
    for (size_t i = 0; i < db->count; ++i) {
        SensorRecord *record = db->records[i];
        json_object *jObj = json_object_new_object();
        json_object_object_add(jObj, "sensor_count", json_object_new_int(record->sensor_count));
        json_object_object_add(jObj, "sensor_type", json_object_new_string(&record->sensor_type));
        json_object_object_add(jObj, "event_timestamp", json_object_new_int64((int64_t)record->event_timestamp));
        json_object_object_add(jObj, "sensor_value", json_object_new_double(record->sensor_value));
        json_object_object_add(jObj, "quality_metric", json_object_new_double(record->quality_metric));
        char idStr[20];
        snprintf(idStr, sizeof(idStr), "%" PRIu64, record->identifier);
        json_object_object_add(jObj, "identifier", json_object_new_string(idStr));
        json_object_object_add(jObj, "description", json_object_new_string(record->description));
        json_object_array_add(jArray, jObj);
    }

    char *json_str = strdup(json_object_to_json_string(jArray));
    size_t compressed_size = ZSTD_compressBound(strlen(json_str));
    void *compressed_data = malloc(compressed_size);

    size_t cSize = ZSTD_compress(compressed_data, compressed_size, json_str, strlen(json_str), 1);
    if (cSize == ZSTD_ERROR(bufferTooSmall)) {
        fprintf(stderr, "Compression buffer too small\n");
        free(compressed_data);
        return;
    }

    FILE *file = fopen(output_file, "wb");
    fwrite(&cSize, sizeof(size_t), 1, file);
    fwrite(compressed_data, cSize, 1, file);
    fclose(file);

    free(json_str);
    free(compressed_data);
}

void parse_csv_and_store(const char *csv_path, SensorDatabase *db) {
    FILE *file = fopen(csv_path, "r");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        SensorRecord *record = malloc(sizeof(SensorRecord));
        record->description = malloc(256);

        sscanf(line, "%d,%c,%ld,%f,%lf,%" SCNu64 ",%255s",
               &record->sensor_count,
               &record->sensor_type,
               &record->event_timestamp,
               &record->sensor_value,
               &record->quality_metric,
               &record->identifier,
               record->description);

        validate_and_store_sensor(db, record);
    }

    fclose(file);
}

void log_access(const char *message) {
    FILE *log_file = fopen("access.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}
