// Logging function
void log_message(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Function to initialize the list
DynamicList* init_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) {
        log_message("Memory allocation failed for list");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    return list;
}

// Function to add a new element
int add_element(DynamicList* list) {
    if (pthread_mutex_lock(&list->lock)) {
        log_message("Mutex lock failed");
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_message("Memory allocation failed for new node");
        return -1;
    }

    // Populate the structure with random data
    srand(time(NULL) + rand());
    new_node->data.valid_RX_UE_INFORMATION_TAG = rand();
    new_node->data.RNTI = rand();
    new_node->data.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    if (list->count > MAX_LIST_SIZE) {
        log_message("List size exceeded maximum threshold, truncating");
        while (list->count > MAX_LIST_SIZE / 2) { // Example truncation
            Node* temp = list->head;
            list->head = list->head->next;
            free(temp);
            list->count--;
        }
    }

    pthread_mutex_unlock(&list->lock);
    log_message("Added new element to the list");
    return 0;
}

// Function to serialize the list
int serialize_list(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    log_message("List serialized successfully");
    return 0;
}

// Function to deserialize the list
int deserialize_list(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T temp_data;

    while (fread(&temp_data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fclose(file);
            pthread_mutex_unlock(&list->lock);
            log_message("Memory allocation failed during deserialization");
            return -1;
        }

        new_node->data = temp_data;
        new_node->next = list->head;
        list->head = new_node;
    }

    if (ferror(file)) {
        log_message("Error reading file during deserialization");
    } else {
        log_message("List deserialized successfully");
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the list
void free_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->mutex);

    log_message("List freed successfully");
}

// Example usage
int main() {
    DynamicList* list = init_list();
    if (!list) return -1;

    for (int i = 0; i < MAX_LIST_SIZE + 50; i++) {
        add_element(list);
    }

    serialize_list(list, "nfa_list.dat");
    free_list(list);

    list = init_list();
    deserialize_list(list, "nfa_list.dat");

    free_list(list);
    free(list);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for locking to ensure thread safety during concurrent access.
- **Memory Management**: Handles dynamic memory allocation with checks and logs errors appropriately. Truncates the list when it exceeds a specified size.
- **Serialization/Deserialization**: Supports binary serialization to maintain data fidelity and performance.
- **Logging**: Logs important events such as allocations, deallocations, and errors for debugging and analysis.
- **Error Handling**: Includes robust error handling throughout the code.

This implementation balances performance, memory usage, and ease of use while being scalable for future growth.']

