    CODEC_AAC,
    // Add more codecs as needed
} CodecType;

typedef struct {
    Resolution resolution;
    FrameRate frameRate;
    AudioBitrate audioBitrate;
    CodecType codecType;
    float currentLoadPercentage;
} MediaStreamConfig;

typedef struct {
    int mediaTag;
    double timestamp;
    float qualityLevel;
} MediaStreamTag;

typedef struct {
    MediaStreamTag *tags;
    size_t count;
} MediaStreamBundle;

int loadConfiguration(const char *filePath, MediaStreamConfig *streams, size_t maxStreams) {
    FILE *file = fopen(filePath, "r");
    if (!file) return -1;

    int streamCount = 0;
    while (streamCount < maxStreams && fscanf(file, "%d %d %f %d %d %f",
                                              &streams[streamCount].resolution.width,
                                              &streams[streamCount].resolution.height,
                                              &streams[streamCount].frameRate.frameRate,
                                              &streams[streamCount].audioBitrate.audioBitrate,
                                              (int *)&streams[streamCount].codecType,
                                              &streams[streamCount].currentLoadPercentage) == 6) {
        streamCount++;
    }

    fclose(file);
    return streamCount;
}

void validateAndOptimizeStreams(MediaStreamConfig *streams, int count, float maxBandwidth) {
    for (int i = 0; i < count; i++) {
        // Validate parameters
        if (streams[i].resolution.width <= 0 || streams[i].resolution.height <= 0 ||
            streams[i].frameRate.frameRate <= 0 || streams[i].audioBitrate.audioBitrate <= 0 ||
            streams[i].currentLoadPercentage < 0 || streams[i].currentLoadPercentage > 100) {
            // Handle invalid stream configuration
            continue;
        }

        // Optimize quality and resource usage
        float estimatedBandwidth = (streams[i].resolution.width * streams[i].resolution.height * 
                                    streams[i].frameRate.frameRate + 
                                    streams[i].audioBitrate.audioBitrate);

        if (estimatedBandwidth > maxBandwidth) {
            // Adjust quality level based on current load and bandwidth
            float adjustmentFactor = maxBandwidth / estimatedBandwidth;
            streams[i].resolution.width *= adjustmentFactor;
            streams[i].resolution.height *= adjustmentFactor;
            streams[i].frameRate.frameRate *= adjustmentFactor;
            streams[i].audioBitrate.audioBitrate *= adjustmentFactor;
        }
    }
}

MediaStreamBundle optimizeMediaStream(const char *configFilePath, float maxBandwidth) {
    MediaStreamConfig streams[MAX_STREAMS];
    int streamCount = loadConfiguration(configFilePath, streams, MAX_STREAMS);

    if (streamCount < 0) {
        // Handle file loading error
        return (MediaStreamBundle){NULL, 0};
    }

    validateAndOptimizeStreams(streams, streamCount, maxBandwidth);

    MediaStreamTag *tags = malloc(streamCount * sizeof(MediaStreamTag));
    if (!tags) {
        // Handle memory allocation failure
        return (MediaStreamBundle){NULL, 0};
    }

    for (int i = 0; i < streamCount; i++) {
        tags[i].mediaTag = i + 1;
        tags[i].timestamp = (double)(i * 1000); // Example timestamp
        tags[i].qualityLevel = streams[i].currentLoadPercentage > 75 ? 0.5 : 1.0;
    }

    return (MediaStreamBundle){tags, streamCount};
}
