```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>

// Define the structure for CRC indication
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for cellular event
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    time_t timestamp;
    int event_type;
} NFAPI_CELLULAR_EVENT_PDU_T;

// Error logging function
void log_error(const char *message, const char *log_file) {
    FILE *file = fopen(log_file, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

// Initialize cryptographic primitives
int init_crypto_primitives() {
    // Add AES cipher
    if (!EVP_add_cipher(&aes_cbc)) {
        log_error("Failed to add AES cipher.", "crypto_errors.log");
        return -1;
    }

    // Add Camellia cipher
    if (!EVP_add_cipher(&camellia_ecb)) {
        log_error("Failed to add Camellia cipher.", "crypto_errors.log");
        return -1;
    }

    // Add MD5 digest
    if (!EVP_add_digest(&md5)) {
        log_error("Failed to add MD5 digest.", "crypto_errors.log");
        return -1;
    }

    // Add SHA-256 digest
    if (!EVP_add_digest(&sha256)) {
        log_error("Failed to add SHA-256 digest.", "crypto_errors.log");
        return -1;
    }

    // Add RSA with SHA256
    if (!EVP_add_digest_alias("SHA256", &sha256)) {
        log_error("Failed to alias SHA256.", "crypto_errors.log");
        return -1;
    }

    return 0;
}

// Structure for managing CRC and cellular event lists
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crc_list;
    int crc_count;
    pthread_mutex_t crc_lock;

    NFAPI_CELLULAR_EVENT_PDU_T *cellular_event_list;
    int cellular_event_count;
    pthread_mutex_t cellular_event_lock;
} EventManager;

// Function to initialize the event manager
EventManager* init_event_manager(int N, int M) {
    EventManager *manager = malloc(sizeof(EventManager));
    if (!manager) {
        log_error("Failed to allocate memory for EventManager.", "errors.log");
        return NULL;
    }

    manager->crc_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->cellular_event_list = malloc(M * sizeof(NFAPI_CELLULAR_EVENT_PDU_T));

    if (!manager->crc_list || !manager->cellular_event_list) {
        log_error("Failed to allocate memory for event lists.", "errors.log");
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->crc_lock, NULL);
    pthread_mutex_init(&manager->cellular_event_lock, NULL);

    manager->crc_count = 0;
    manager->cellular_event_count = 0;

    return manager;
}

// Function to create a CRC indication structure
void* create_crc_indication(void *arg) {
    EventManager *manager = (EventManager *)arg;
    int index = rand() % 100; // Example random index

    pthread_mutex_lock(&manager->crc_lock);
    if (manager->crc_count < N) {
        manager->crc_list[manager->crc_count].RX_UE_INFORMATION_TAG = index;
        manager->crc_list[manager->crc_count].RNTI = rand() % 1000;
        manager->crc_list[manager->crc_count].CRC_INDICATION_REL8_TAG = rand() % 10;
        manager->crc_list[manager->crc_count].CRCFLAG = rand() % 2;

        log_error("Created CRC indication.", "event_log.log");
        manager->crc_count++;
    }
    pthread_mutex_unlock(&manager->crc_lock);

    return NULL;
}

// Function to create a cellular event structure
void* create_cellular_event(void *arg) {
    EventManager *manager = (EventManager *)arg;
    int index = rand() % 100; // Example random index

    pthread_mutex_lock(&manager->cellular_event_lock);
    if (manager->cellular_event_count < M) {
        manager->cellular_event_list[manager->cellular_event_count].RX_UE_INFORMATION_TAG = index;
        manager->cellular_event_list[manager->cellular_event_count].RNTI = rand() % 1000;
        manager->cellular_event_list[manager->cellular_event_count].timestamp = time(NULL);
        manager->cellular_event_list[manager->cellular_event_count].event_type = rand() % 5;

        log_error("Created cellular event.", "event_log.log");
        manager->cellular_event_count++;
    }
    pthread_mutex_unlock(&manager->cellular_event_lock);

    return NULL;
}

// Main function to manage events
void manage_events(int N, int M) {
    EventManager *manager = init_event_manager(N, M);
    if (!manager) {
        log_error("Failed to initialize event manager.", "errors.log");
        return;
    }

    pthread_t crc_threads[N];
    pthread_t cellular_threads[M];

    for (int i = 0; i < N; i++) {
        pthread_create(&crc_threads[i], NULL, create_crc_indication, manager);
    }

    for (int j = 0; j < M; j++) {
        pthread_create(&cellular_threads[j], NULL, create_cellular_event, manager);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(crc_threads[i], NULL);
    }

    for (int j = 0; j < M; j++) {
        pthread_join(cellular_threads[j], NULL);
    }

    free(manager->crc_list);
    free(manager->cellular_event_list);
    pthread_mutex_destroy(&manager->crc_lock);
    pthread_mutex_destroy(&manager->cellular_event_lock);
    free(manager);
}

int main() {
    // Initialize cryptographic primitives
    if (init_crypto_primitives() != 0) {
        return -1;
    }

    int N = 10; // Number of CRC structures
    int M = 15; // Number of cellular event structures

    manage_events(N, M);

    return 0;
}
```

### Key Points:

- **Cryptographic Initialization**: Uses OpenSSL's `EVP_add_cipher`, `EVP_add_digest`, and `EVP_add_digest_alias` to initialize cryptographic primitives.
- **Thread Safety**: Utilizes mutex locks to ensure thread-safe operations on shared resources.
- **Dynamic Memory Allocation**: Allocates memory for lists of structures dynamically based on user input.
- **Logging Mechanism**: Logs errors and events to specified files, aiding in debugging and monitoring.
- **Multi-threading**: Creates separate threads for handling CRC and cellular event structures concurrently.

This code is designed to be modular, efficient, and robust against concurrency issues, making it suitable for high-load environments.']

