void add_connection(TCP_CONNECTION_INFO_T *connection_info, NFAPI_CRC_INDICATION_PDU_T *crc_info) {
    pthread_mutex_lock(&pool.mutex);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool.connections[i] == NULL) {
            pool.connections[i] = connection_info;
            pool.crc_info[i] = crc_info;
            break;
        }
    }

    pthread_mutex_unlock(&pool.mutex);
}

void remove_connection(int connection_id) {
    pthread_mutex_lock(&pool.mutex);

    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (pool.connections[i] && pool.connections[i]->CONNECTION_ID == connection_id) {
            free(pool.connections[i]);
            free(pool.crc_info[i]);
            pool.connections[i] = NULL;
            pool.crc_info[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&pool.mutex);
}

