// Assume a JSON schema object is already defined somewhere as `config_schema`

typedef struct {
    char *key;
    char *iv;
    char *cipher_type;
} ConfigParams;

int validate_json(const char *file_path, const jsonschema_t *schema, ConfigParams *params) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        fprintf(stderr, "Error: Unable to open configuration file.\n");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *content = malloc(length + 1);
    fread(content, 1, length, file);
    content[length] = '\0';
    fclose(file);

    json_t *json_data = json_loads(content, 0, NULL);
    free(content);

    if (!json_data) {
        fprintf(stderr, "Error: Invalid JSON format.\n");
        return -2;
    }

    int schema_result = jsonschema_validate(schema, json_data, NULL);
    if (schema_result != JSON_SCHEMA_VALID) {
        json_t *error = json_copy(jsonschema_get_error());
        fprintf(stderr, "Validation Error: %s\n", json_dumps(error, 0));
        json_decref(error);
        json_decref(json_data);
        return -3;
    }

    json_t *key_json = json_object_get(json_data, "encryption_key");
    json_t *iv_json = json_object_get(json_data, "initialization_vector");
    json_t *cipher_type_json = json_object_get(json_data, "cipher_type");

    params->key = strdup(json_string_value(key_json));
    params->iv = strdup(json_string_value(iv_json));
    params->cipher_type = strdup(json_string_value(cipher_type_json));

    json_decref(json_data);
    return 0;
}

