```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define DEFAULT_KEY_RANGE 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pduArray[MAX_ELEMENTS];
    Record *recordArray[MAX_ELEMENTS];
    size_t pduCount;
    size_t recordCount;
    pthread_mutex_t lock;
} DynamicArrayManager;

unsigned int generate_random_number(unsigned int max, unsigned int seed) {
    srand(seed);
    return rand() % (max + 1);
}

int allocate_memory(DynamicArrayManager *manager, size_t pduSize, size_t recordSize) {
    if (pduSize > MAX_ELEMENTS || recordSize > MAX_ELEMENTS) {
        fprintf(stderr, "Allocation error: Exceeds maximum limit.\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < pduSize; ++i) {
        manager->pduArray[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->pduArray[i]) {
            fprintf(stderr, "Allocation error: Failed to allocate PDU.\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    for (size_t i = 0; i < recordSize; ++i) {
        manager->recordArray[i] = malloc(sizeof(Record));
        if (!manager->recordArray[i]) {
            fprintf(stderr, "Allocation error: Failed to allocate Record.\n");
            pthread_mutex_unlock(&manager->lock);
            for (size_t j = 0; j < i; ++j) free(manager->recordArray[j]);
            return -1;
        }
    }

    manager->pduCount = pduSize;
    manager->recordCount = recordSize;

    pthread_mutex_unlock(&manager->lock);

    // Logging allocations
    printf("Allocated %zu PDU structures and %zu Record structures.\n", pduSize, recordSize);

    return 0;
}

void initialize_pdu_array(DynamicArrayManager *manager, unsigned int seed) {
    for (size_t i = 0; i < manager->pduCount; ++i) {
        manager->pduArray[i]->RX_UE_INFORMATION_TAG = generate_random_number(UINT_MAX, seed);
        manager->pduArray[i]->RNTI = generate_random_number(UINT_MAX, seed + 1);
        manager->pduArray[i]->CRC_INDICATION_REL8_TAG = generate_random_number(USHRT_MAX, seed + 2);
        manager->pduArray[i]->CRCFLAG = (generate_random_number(1, seed + 3) == 0) ? 0 : 1;
    }
}

void initialize_record_array(DynamicArrayManager *manager, unsigned int seed, int valueRangeMin, int valueRangeMax) {
    int keys[DEFAULT_KEY_RANGE] = {0};

    for (size_t i = 0; i < manager->recordCount; ++i) {
        int key;
        do {
            key = generate_random_number(DEFAULT_KEY_RANGE - 1, seed + i);
        } while (keys[key]);

        keys[key] = 1;

        manager->recordArray[i]->value = generate_random_number(valueRangeMax, seed + i + 4) + valueRangeMin;
        manager->recordArray[i]->offset = malloc(sizeof(long));
        if (!manager->recordArray[i]->offset) {
            fprintf(stderr, "Allocation error: Failed to allocate offset for Record.\n");
            break;
        }
        *manager->recordArray[i]->offset = 0; // Initialize with default value
        manager->recordArray[i]->key = &keys[key];
    }
}

void free_memory(DynamicArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->pduCount; ++i) {
        if (manager->pduArray[i]) {
            free(manager->pduArray[i]);
        }
    }

    for (size_t i = 0; i < manager->recordCount; ++i) {
        if (manager->recordArray[i]) {
            if (manager->recordArray[i]->offset) {
                free(manager->recordArray[i]->offset);
            }
            free(manager->recordArray[i]);
        }
    }

    pthread_mutex_unlock(&manager->lock);

    printf("Freed all allocated memory.\n");
}

void serialize_array(DynamicArrayManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for writing.\n");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->pduCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->pduCount; ++i) {
        fwrite(manager->pduArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fwrite(&manager->recordCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->recordCount; ++i) {
        int keyValue = *(manager->recordArray[i]->key);
        long offset = *(manager->recordArray[i]->offset);
        fwrite(&manager->recordArray[i]->value, sizeof(int), 1, file);
        fwrite(&keyValue, sizeof(int), 1, file);
        fwrite(&offset, sizeof(long), 1, file);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

void deserialize_array(DynamicArrayManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for reading.\n");
        return;
    }

    pthread_mutex_lock(&manager->lock);

    size_t pduCount, recordCount;
    fread(&pduCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < pduCount; ++i) {
        manager->pduArray[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->pduArray[i]) {
            fprintf(stderr, "Allocation error: Failed to allocate PDU during deserialization.\n");
            break;
        }
        fread(manager->pduArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fread(&recordCount, sizeof(size_t), 1, file);
    for (size_t i = 0; i < recordCount; ++i) {
        manager->recordArray[i] = malloc(sizeof(Record));
        if (!manager->recordArray[i]) {
            fprintf(stderr, "Allocation error: Failed to allocate Record during deserialization.\n");
            break;
        }
        int value, key;
        long offset;
        fread(&value, sizeof(int), 1, file);
        fread(&key, sizeof(int), 1, file);
        fread(&offset, sizeof(long), 1, file);

        manager->recordArray[i]->value = value;
        manager->recordArray[i]->key = malloc(sizeof(int));
        *(manager->recordArray[i]->key) = key;
        manager->recordArray[i]->offset = malloc(sizeof(long));
        *(manager->recordArray[i]->offset) = offset;
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

void initialize_dynamic_array_manager(DynamicArrayManager *manager, size_t pduSize, size_t recordSize, unsigned int seed,
                                     int valueRangeMin, int valueRangeMax) {
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        fprintf(stderr, "Mutex init failed.\n");
        return;
    }

    if (allocate_memory(manager, pduSize, recordSize) == -1) {
        pthread_mutex_destroy(&manager->lock);
        return;
    }

    initialize_pdu_array(manager, seed);
    initialize_record_array(manager, seed, valueRangeMin, valueRangeMax);

    // Example log message for initialization
    printf("Dynamic array manager initialized with %zu PDU and %zu Record elements.\n", pduSize, recordSize);
}

int main() {
    DynamicArrayManager manager;
    memset(&manager, 0, sizeof(manager));

    initialize_dynamic_array_manager(&manager, 5000, 5000, time(NULL), 10, 100);

    serialize_array(&manager, "data.bin");
    deserialize_array(&manager, "data.bin");

    free_memory(&manager);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

### Key Points:
- **Concurrency**: Utilizes a mutex (`pthread_mutex_t`) to ensure thread-safe access and modifications.
- **Memory Management**: Allocates and deallocates memory for `NFAPI_CRC_INDICATION_PDU_T` and `Record` structures, handling allocation failures gracefully.
- **Initialization**: Uses a pseudo-random generator seeded by the caller to initialize structure fields uniquely.
- **Serialization/Deserialization**: Provides functions to serialize the array to a binary file and deserialize it back into memory.
- **Logging**: Logs important operations such as allocations and deallocations for debugging purposes.']

