// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node of linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Memory pool structure
typedef struct {
    size_t blockSize;
    unsigned char* block;
    unsigned char* current;
    unsigned char* end;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t numBlocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    size_t totalSize = blockSize * numBlocks;
    pool->block = (unsigned char*)malloc(totalSize);
    if (!pool->block) {
        free(pool);
        return NULL;
    }

    pool->current = pool->block;
    pool->end = pool->block + totalSize;
    return pool;
}

void* allocateFromPool(MemoryPool* pool) {
    if (pool->current + pool->blockSize > pool->end) {
        return NULL; // Pool exhausted
    }

    void* block = pool->current;
    pool->current += pool->blockSize;
    return block;
}

void destroyMemoryPool(MemoryPool* pool) {
    free(pool->block);
    free(pool);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data, MemoryPool* pool) {
    Node* node = (Node*)allocateFromPool(pool);
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;
    return node;
}

void generateNfadWithConstraints(Node** head, size_t maxMemoryUsage, int numElements) {
    MemoryPool* pool = createMemoryPool(sizeof(NFAPI_CRC_INDICATION_PDU_T), numElements);
