            .RX_UE_INFORMATION_TAG = rand() % 100, 
            .RNTI = rand() % 100, 
            .CRC_INDICATION_REL8_TAG = rand() % 10, 
            .CRCFLAG = rand() % 2
        };

        Node* newNode = createNode(data, pool);
        if (!newNode) {
            // Handle allocation failure; cleanup or break as needed
            break;
        }

        if (*head == NULL) {
            *head = newNode;
        } else {
            current->next = newNode;
        }

        current = newNode;
    }

    destroyMemoryPool(pool);
}

