// Global variables for rate limiting
static pthread_mutex_t rate_limit_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long last_execution_time = 0;
static const unsigned int rate_limit_interval_ms = 1000; // Example interval, configurable

int generateNfareport(NFAPI_CRC_INDICATION_PDU_T* reportArray, size_t arraySize) {
    pthread_t async_thread;
    struct timespec next_allowed_time;
    int result = 0;

    if (pthread_mutex_lock(&rate_limit_lock) != 0) return 0;
    clock_gettime(CLOCK_REALTIME, &next_allowed_time);
    next_allowed_time.tv_sec += rate_limit_interval_ms / 1000;
    next_allowed_time.tv_nsec += (rate_limit_interval_ms % 1000) * 1000000;

    if (last_execution_time != 0 && 
        (next_allowed_time.tv_sec < last_execution_time || 
         (next_allowed_time.tv_sec == last_execution_time &&
          next_allowed_time.tv_nsec <= last_execution_time))) {

        pthread_mutex_unlock(&rate_limit_lock);
        return 0; // Rate limit not met
    }

    last_execution_time = next_allowed_time.tv_sec;
    if (pthread_cond_timedwait_until(NULL, &rate_limit_lock, &next_allowed_time) != 0) {
        pthread_mutex_unlock(&rate_limit_lock);
        return 0; // Timed wait failed
    }

    pthread_mutex_unlock(&rate_limit_lock);

    // Fork and execute another command in background
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            // Command execution successful
            for (size_t i = 0; i < arraySize; ++i) {
                reportArray[i].RX_UE_INFORMATION_TAG = rand(); // Placeholder value
                reportArray[i].RNTI = rand();
                reportArray[i].CRC_INDICATION_REL8_TAG = rand();

                int crcflag;
                if (async_command_execution(&crcflag)) {
                    reportArray[i].CRCFLAG = crcflag;
                    update_external_monitoring_service("Command successful");
                    result = 1;
                } else {
                    // Leave CRCFLAG uninitialized
                    update_external_monitoring_service("Command failed");
                }
            }
        }
    }

    return result;
}
