#define MAX_UE_COUNT 1000
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    uint16_t rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t crc_indication_rel8_tag;
    float snr_indication_rel8_tag;
} NFAPI_MESSAGE_PDU_T;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

int is_valid_rnti(uint16_t rnti) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX);
}

float simulate_snr() {
    // Simulate SNR with random noise factor
    float base_snr = 10.0; // Base SNR value in dB
    float noise_factor = ((float)rand() / RAND_MAX) * 5.0; // Random noise between 0 and 5
    return base_snr - noise_factor;
}

void initialize_nfa_messages(NFAPI_MESSAGE_PDU_T* nfa_messages, int ue_count) {
    if (!nfa_messages || ue_count <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    for (int i = 0; i < ue_count; ++i) {
        uint16_t rnti;
        do {
            rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        } while (!is_valid_rnti(rnti));

        nfa_messages[i].crc_indication_rel8_tag = i % 256; // Example CRC tag
        nfa_messages[i].snr_indication_rel8_tag = simulate_snr();

        printf("UE %d: RNTI=%u, SNR=%.2f dB\n", i + 1, rnti, nfa_messages[i].snr_indication_rel8_tag);
    }
}

int main() {
    initialize_random();

    NFAPI_MESSAGE_PDU_T* nfa_messages = (NFAPI_MESSAGE_PDU_T*)calloc(MAX_UE_COUNT, sizeof(NFAPI_MESSAGE_PDU_T));
    if (!nfa_messages) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    int ue_count = MAX_UE_COUNT; // Set the desired number of UEs
    initialize_nfa_messages(nfa_messages, ue_count);

    free(nfa_messages);
    return 0;
}
