#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <jansson.h>

typedef struct SensorReading {
    double timestamp;
    int sensor_id;
    float measurement_value;
    char location_identifier[256];
    float calibration_constant;
    struct SensorReading* prev;
    struct SensorReading* next;
} SensorReading;

float calculate_standard_deviation(float* values, size_t count) {
    float mean = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        mean += values[i];
    }
    mean /= count;

    float variance = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        variance += pow(values[i] - mean, 2);
    }
    variance /= count;

    return sqrt(variance);
}

int validate_and_calibrate(float* value, float calibration_constant, float lower_bound, float upper_bound) {
    *value *= calibration_constant;
    if (*value < lower_bound || *value > upper_bound) {
        return 0; // Invalid
    }
    return 1; // Valid
}

void insert_sorted(SensorReading** head, SensorReading* new_node) {
    if (!*head || (*head)->timestamp > new_node->timestamp) {
        new_node->next = *head;
        if (*head) (*head)->prev = new_node;
        *head = new_node;
        return;
    }

    SensorReading* current = *head;
    while (current->next && current->next->timestamp <= new_node->timestamp) {
        current = current->next;
    }

    new_node->next = current->next;
    if (current->next) current->next->prev = new_node;
    current->next = new_node;
    new_node->prev = current;
}

int is_duplicate(SensorReading* head, SensorReading* node) {
    while (head) {
        if (head->sensor_id == node->sensor_id &&
            head->measurement_value == node->measurement_value &&
            head->calibration_constant == node->calibration_constant) {
            return 1;
        }
        head = head->next;
    }
    return 0;
}

void free_list(SensorReading* head) {
    SensorReading* current = head;
    while (current) {
        SensorReading* next = current->next;
        free(current);
        current = next;
    }
}

