        sensor_map[sensor_id] = sensor_metadata;

        // Validate bounds
        if (lower_bound >= upper_bound) {
            fprintf(stderr, "Invalid bounds for sensor %d\n", sensor_id);
            free(sensor_metadata);
            continue;
        }
    }

    SensorReading* head = NULL;
    float* values_array = malloc(10000 * sizeof(float));
    size_t count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        pthread_mutex_lock(&lock);

        double timestamp;
        int sensor_id;
        float measurement_value;
        if (sscanf(line, "%lf,%d,%f", &timestamp, &sensor_id, &measurement_value) != 3) {
            pthread_mutex_unlock(&lock);
            continue; // Skip invalid lines
        }

        SensorReading* new_node = malloc(sizeof(SensorReading));
        new_node->timestamp = timestamp;
        new_node->sensor_id = sensor_id;

        if (!sensor_map[sensor_id]) {
            free(new_node);
            pthread_mutex_unlock(&lock);
            continue; // Invalid sensor ID
        }

        strncpy(new_node->location_identifier, sensor_map[sensor_id]->location_identifier, sizeof(new_node->location_identifier));
        new_node->calibration_constant = sensor_map[sensor_id]->calibration_constant;

        if (!validate_and_calibrate(&measurement_value, new_node->calibration_constant, 
                                    json_real_value(json_object_get(values[i][2])), 
                                    json_real_value(json_object_get(values[i][3])))) {
            free(new_node);
            pthread_mutex_unlock(&lock);
            continue; // Invalid measurement
        }

        if (is_duplicate(head, new_node)) {
            free(new_node);
        } else {
            insert_sorted(&head, new_node);
            values_array[count++] = measurement_value;
        }

        pthread_mutex_unlock(&lock);
    }

    fclose(fp);

    float standard_deviation = calculate_standard_deviation(values_array, count);
    printf("Standard Deviation: %f\n", standard_deviation);

    free_list(head);
    free(sensor_map);
    free(values_array);
    json_decref(root);
    pthread_mutex_destroy(&lock);
}
