#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the Record structure
typedef struct {
    int value;
} Record;

// Function to dynamically allocate and initialize memory
void* allocate_memory(int num_records, int num_offsets, int num_keys, const long* init_offsets, const int* init_keys) {
    // Calculate total size needed for all data in a single block
    size_t record_size = sizeof(Record);
    size_t offset_size = sizeof(long);
    size_t key_size = sizeof(int);

    size_t total_size = (num_records * record_size) + (num_offsets * offset_size) + (num_keys * key_size);

    // Allocate memory for the entire block
    void* memory_block = malloc(total_size);
    if (!memory_block) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Set pointers to each part within the block
    Record* records = (Record*)memory_block;
    long* offsets = (long*)(records + num_records);
    int* keys = (int*)(offsets + num_offsets);

    // Initialize records, offsets, and keys if data is available
    for (int i = 0; i < num_records; ++i) {
        records[i].value = 0; // Default initialization
    }

    for (int i = 0; i < num_offsets && init_offsets != NULL; ++i) {
        offsets[i] = init_offsets ? init_offsets[i] : 0;
    }

    for (int i = 0; i < num_keys && init_keys != NULL; ++i) {
        keys[i] = init_keys ? init_keys[i] : 0;
    }

    // Verify integrity (simple check, expand as needed)
    if ((char*)keys - (char*)memory_block != total_size - (num_keys * key_size)) {
        fprintf(stderr, "Memory layout error\n");
        free(memory_block);
        return NULL;
    }

    return memory_block;  // Return pointer to the start of the block
}

// Usage example and cleanup would be managed externally from this function.
```

### Key Considerations:
- **Contiguous Memory**: The entire allocation is done in a single call to `malloc` to ensure that all elements are in one contiguous memory block, which helps with cache performance and minimizes fragmentation.
- **Error Handling**: Proper error checking after each allocation step ensures the program handles memory allocation failures gracefully by freeing allocated resources before returning an error.
- **Data Integrity**: A simple check is included to verify that the layout of data within the memory block matches expectations. This can be expanded based on specific requirements or constraints.
- **Default Initialization**: Each part of the structure (records, offsets, keys) is initialized with default values in case input data is missing or incomplete.

This function assumes `init_offsets` and `init_keys` may be NULL, handling such cases by using zero as a fallback initialization value. This ensures robustness when external data sources might be inconsistent or delayed.']

