['Below is a C implementation that manages a dynamically allocated array of `MAC_ECONTEXT` structures with thread-safe operations using mutexes and condition variables for synchronization. The function allocates memory dynamically for the MAC Service Data Units (SDUs) and populates them with random data.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MAC_ENTITY_COUNT 100

typedef struct {
    int id; // Unique MAC Entity ID
    void *dl_frame;
} DL_FRAME;

typedef struct {
    unsigned char *data;
    size_t length;
} MAC_SDU;

typedef struct {
    int mac_entity_id;
    DL_FRAME *dl_frame;
    MAC_SDU **sdus;
    size_t sdu_count;
} MAC_ECONTEXT;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    MAC_ECONTEXT **contexts;
    size_t context_count;
    size_t capacity;
} MAC_CONTEXT_MANAGER;

MAC_CONTEXT_MANAGER* create_mac_context_manager(size_t initial_capacity) {
    MAC_CONTEXT_MANAGER *manager = malloc(sizeof(MAC_CONTEXT_MANAGER));
    if (!manager) return NULL;

    manager->contexts = calloc(initial_capacity, sizeof(MAC_ECONTEXT *));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);

    manager->context_count = 0;
    manager->capacity = initial_capacity;

    return manager;
}

void destroy_mac_context_manager(MAC_CONTEXT_MANAGER *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->context_count; ++i) {
        MAC_ECONTEXT *ctx = manager->contexts[i];
        for (size_t j = 0; j < ctx->sdu_count; ++j) {
            free(ctx->sdus[j]->data);
            free(ctx->sdus[j]);
        }
        free(ctx->sdus);
        // Free dl_frame if necessary
        free(ctx);
    }

    free(manager->contexts);

    pthread_mutex_unlock(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

MAC_ECONTEXT* allocate_mac_econtext(MAC_CONTEXT_MANAGER *manager, int mac_entity_id, DL_FRAME *dl_frame, size_t sdu_count) {
    if (!manager || sdu_count == 0) return NULL;

    MAC_ECONTEXT *new_context = malloc(sizeof(MAC_ECONTEXT));
    if (!new_context) return NULL;

    new_context->mac_entity_id = mac_entity_id;
    new_context->dl_frame = dl_frame;
    new_context->sdus = calloc(sdu_count, sizeof(MAC_SDU *));
    if (!new_context->sdus) {
        free(new_context);
        return NULL;
    }

    for (size_t i = 0; i < sdu_count; ++i) {
        MAC_SDU *sdu = malloc(sizeof(MAC_SDU));
        if (!sdu) {
            // Cleanup on failure
            while (--i >= 0) free(new_context->sdus[i]);
            free(new_context->sdus);
            free(new_context);
            return NULL;
        }
        sdu->length = rand() % 256 + 1; // Random data length
        sdu->data = malloc(sdu->length);
        if (!sdu->data) {
            while (--i >= 0) free(new_context->sdus[i]);
            free(new_context->sdus);
            free(new_context);
            return NULL;
        }
        for (size_t j = 0; j < sdu->length; ++j) {
            sdu->data[j] = rand() % 256; // Populate with random data
        }
        new_context->sdus[i] = sdu;
    }

    pthread_mutex_lock(&manager->lock);
    if (manager->context_count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        MAC_ECONTEXT **new_contexts = realloc(manager->contexts, new_capacity * sizeof(MAC_ECONTEXT *));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            // Cleanup on failure
            for (size_t i = 0; i < sdu_count; ++i) free(new_context->sdus[i]);
            free(new_context->sdus);
            free(new_context);
            return NULL;
        }
        manager->contexts = new_contexts;
        memset(manager->contexts + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(MAC_ECONTEXT *));
        manager->capacity = new_capacity;
    }

    manager->contexts[manager->context_count++] = new_context;

    pthread_mutex_unlock(&manager->lock);

    return new_context;
}

// Additional utility functions and integration points for logging, diagnostics,
// schema validation, performance tuning, etc., should be implemented as needed.
```

### Key Points:
- **Thread-Safety**: The implementation uses a mutex to ensure thread-safe operations when modifying shared resources like the context array.
- **Dynamic Memory Management**: The function dynamically allocates memory for each `MAC_ECONTEXT` and its SDUs, ensuring proper cleanup in case of allocation failures.
- **Scalability**: The manager resizes its internal storage as needed to accommodate more contexts.
- **Error Handling**: Proper checks are in place for all dynamic allocations, with appropriate cleanup if any fail.

This code serves as a foundation. Further enhancements can include integrating logging mechanisms, optimizing performance under high load, and adding configuration options for better resource management based on the specific needs of your web server framework.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_SIZE 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG:1; // Only one bit for the flag
        uint7_t reserved:7;
    } CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} FSA_State_Manager;

FSA_State_Manager* create_manager(size_t initial_capacity) {
    FSA_State_Manager *manager = (FSA_State_Manager *)malloc(sizeof(FSA_State_Manager));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resize_manager(FSA_State_Manager *manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return; // Handle failure gracefully

    manager->array = new_array;
    manager->capacity = new_capacity;
}

void free_manager(FSA_State_Manager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->array);
    free(manager);
}

int add_state(FSA_State_Manager *manager, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_SIZE) new_capacity = MAX_SIZE;

        resize_manager(manager, new_capacity);
        if (manager->capacity == manager->size) { // Check for failed allocation
            pthread_mutex_unlock(&manager->lock);
            return -1; 
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->size++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag
    pdu->timestamp = time(NULL);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void serialize_manager(FSA_State_Manager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);
    fwrite(&manager->size, sizeof(size_t), 1, file);
    fwrite(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->size, file);
    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

int deserialize_manager(FSA_State_Manager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    if (new_size > manager->capacity) {
        resize_manager(manager, new_size);
        if (manager->capacity < new_size) { // Check for failed allocation
            pthread_mutex_unlock(&manager->lock);
            fclose(file);
            return -1;
        }
    }

    fread(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    manager->size = new_size;

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
    return 0;
}

// Example usage:
/*
int main() {
    FSA_State_Manager *manager = create_manager(100);
    if (!manager) {
        fprintf(stderr, "Failed to create manager\n");
        return EXIT_FAILURE;
    }

    add_state(manager, 1, 2);

    serialize_manager(manager, "state_data.bin");

    free_manager(manager);
    return 0;
}
*/
