    PHY_RX_SYMBOL* symbols;
    float snr_estimate;
    FEC_DECODING_STATUS fec_status;
} PHY_RX_FRAME;

typedef struct {
    int error_code;
    char error_message[256];
} ERROR_INFO;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes for simulation of RF channel effects
float simulateSnr(float base_snr);
FEC_DECODING_STATUS simulateFecStatus();

int initAndPopulateFrames(PHY_RX_FRAME* frames, size_t num_frames, ERROR_INFO* error_info) {
    pthread_mutex_lock(&lock);

    if (num_frames > MAX_FRAMES) {
        snprintf(error_info->error_message, sizeof(error_info->error_message), "Exceeded maximum number of frames: %zu", num_frames);
        error_info->error_code = -1;
        pthread_mutex_unlock(&lock);
        return -1;
    }

    for (size_t i = 0; i < num_frames; ++i) {
        // Allocate and initialize RX_FRAME_HEADER
        frames[i].header = (RX_FRAME_HEADER*)malloc(sizeof(RX_FRAME_HEADER));
        if (!frames[i].header) {
            snprintf(error_info->error_message, sizeof(error_info->error_message), "Memory allocation failed for RX_FRAME_HEADER at index %zu", i);
            error_info->error_code = -2;
            pthread_mutex_unlock(&lock);
            return -2;
        }
        frames[i].header->sequence_number = (unsigned int)i;

        // Allocate and initialize PHY_RX_SYMBOL
        const size_t num_symbols_per_frame = 100;  // Example number of symbols per frame
        frames[i].symbols = (PHY_RX_SYMBOL*)malloc(num_symbols_per_frame * sizeof(PHY_RX_SYMBOL));
        if (!frames[i].symbols) {
            free(frames[i].header);
            snprintf(error_info->error_message, sizeof(error_info->error_message), "Memory allocation failed for PHY_RX_SYMBOL at index %zu", i);
            error_info->error_code = -3;
            pthread_mutex_unlock(&lock);
            return -3;
        }

        // Populate symbols with simulated data
        for (size_t j = 0; j < num_symbols_per_frame; ++j) {
            frames[i].symbols[j].amplitude = ((float)rand() / RAND_MAX) * 2.0f - 1.0f;
            frames[i].symbols[j].phase = ((float)rand() / RAND_MAX) * 360.0f;
        }

        // Simulate SNR and FEC status
        float base_snr = 10.0f;  // Example base SNR value
        frames[i].snr_estimate = simulateSnr(base_snr);
        frames[i].fec_status = simulateFecStatus();
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

float simulateSnr(float base_snr) {
    // Simulate fading and interference effects on SNR
    float fading_effect = ((float)rand() / RAND_MAX) * 2.0f - 1.0f;  // Fading effect between -1 and 1
    float interference = ((float)rand() / RAND_MAX) * 5.0f;  // Interference level up to 5dB
    return base_snr + fading_effect - interference;
}

FEC_DECODING_STATUS simulateFecStatus() {
    // Randomly determine FEC decoding status
    return (rand() % 2 == 0) ? FEC_SUCCESS : FEC_ERROR;
}
