// Function to read integers from stdin and store them in an array
int* read_integers(int *count) {
    char buffer[MAX_INPUT_SIZE];
    int i = 0;
    while (fgets(buffer, MAX_INPUT_SIZE, stdin)) {
        if (buffer[0] == '#') break; // Stop reading on encountering a comment line
        int num = atoi(buffer);
        (*count)++;
        if (*count > MAX_RECORDS) {
            fprintf(stderr, "Error: Exceeded maximum allowed records.\n");
            exit(EXIT_FAILURE);
        }
        // Allocate memory dynamically for the integers
        int *numbers = (int *)realloc(*count ? *count : 1, sizeof(int) * (*count));
        numbers[i++] = num;
    }
    return numbers;
}

// Function to find the largest integer in the array
int find_largest_integer(int *array, int count) {
    int max = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > max) max = array[i];
    }
    return max;
}

