        crc_list[i].crc_indication.rnti = i + 1; // Example RNTI, could be another random value or derived from input
    }
    return crc_list;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int count = 0;
    int *numbers = read_integers(&count);

    if (count > 0) {
        printf("Largest integer: %d\n", find_largest_integer(numbers, count));

        NFAPI_CRC_INDICATION_PDU_T* crc_list = generate_crc_indications(count);

