#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_OFFSETS 1000
#define OFFSET_RANGE 50
#define MAX_KEYS 500
#define KEY_RANGE_START 1
#define KEY_RANGE_END 10000
#define TIMESTAMP_WINDOW 60 // seconds

typedef struct {
    long *offset;
    int *key;
    int accessed;
    time_t last_accessed;
} Record;

int initialize_records(Record **records, size_t num_records) {
    if (num_records == 0 || records == NULL)
        return -1; // Error code for invalid input

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = malloc(sizeof(long) * MAX_OFFSETS);
    int *keys = malloc(sizeof(int) * MAX_KEYS);
    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return -2; // Error code for memory allocation failure
    }

    srand(time(NULL));

    long offset_sum = 0;
    for (size_t i = 0; i < num_records && i < MAX_OFFSETS; i++) {
        offsets[i] = offset_sum + rand() % OFFSET_RANGE;
        offset_sum += offsets[i];
    }

    size_t key_count = 0;
    while (key_count < num_records && key_count < MAX_KEYS) {
        int new_key = KEY_RANGE_START + rand() % (KEY_RANGE_END - KEY_RANGE_START + 1);
        for (size_t j = 0; j < key_count; j++) {
            if (keys[j] == new_key)
                break;
            if (j == key_count - 1) {
                keys[key_count++] = new_key;
            }
        }
    }

    *records = malloc(sizeof(Record) * num_records);
    if (!*records) {
        free(offsets);
        free(keys);
        pthread_mutex_destroy(&lock);
        return -3; // Error code for memory allocation failure
    }

    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].offset = &offsets[i];
        if (i < key_count)
            (*records)[i].key = &keys[i];
        else
            (*records)[i].key = NULL;
        (*records)[i].accessed = 0;

        pthread_mutex_lock(&lock);
        time_t current_time = time(NULL);
        while (current_time - (*records)[i].last_accessed < TIMESTAMP_WINDOW) {
            current_time = time(NULL); // Re-fetch to avoid busy-wait
        }
        (*records)[i].last_accessed = current_time;
        pthread_mutex_unlock(&lock);
    }

    free(offsets);
    free(keys);

    pthread_mutex_destroy(&lock);
    return num_records; // Success code indicating number of initialized records
}

int main() {
    Record *records = NULL;
    int result = initialize_records(&records, 100); // Initialize with 100 records

    if (result < 0) {
        printf("Error initializing records: %d\n", result);
    } else {
        printf("Successfully initialized %d records.\n", result);
    }

    free(records);
    return 0;
}
