#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>
#include <time.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[32];
    unsigned int RNTI;
    char CRC_INDICATION_REL8_TAG[32];
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t count;
} PduList;

void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

char* generate_md5_hash(const char* imei) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)imei, strlen(imei), (unsigned char*)&digest);

    char* hash = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!hash) handle_error("Memory allocation failed");

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(hash + (i * 2), "%02x", digest[i]);
    return hash;
}

void* process_imei(void* arg) {
    const char* imei = (const char*)arg;
    if (!imei || strlen(imei) != 15) handle_error("Invalid IMEI");

    NFAPI_CRC_INDICATION_PDU_T pdu;
    strcpy(pdu.RX_UE_INFORMATION_TAG, "RX_TAG");
    pdu.RNTI = rand() % 65536; // Simulate RNTI generation
    strcpy(pdu.CRC_INDICATION_REL8_TAG, "CRC_TAG");
    pdu.CRCFLAG = rand() % 2;

    char* hash = generate_md5_hash(imei);

    printf("RX_UE_INFORMATION_TAG: %s\n", pdu.RX_UE_INFORMATION_TAG);
    printf("RNTI: %u\n", pdu.RNTI);
    printf("CRC_INDICATION_REL8_TAG: %s\n", pdu.CRC_INDICATION_REL8_TAG);
    printf("CRCFLAG: %u\n", pdu.CRCFLAG);
    printf("MD5 Hash of IMEI: %s\n", hash);

    free(hash);
    return NULL;
}

PduList process_imeis(const char** imeis, size_t count) {
    PduList pdu_list = {NULL, 0};
    pthread_t* threads = malloc(count * sizeof(pthread_t));
    if (!threads) handle_error("Memory allocation failed");

    for (size_t i = 0; i < count; ++i) {
        if (pthread_create(&threads[i], NULL, process_imei, (void*)imeis[i])) {
            free(threads);
            handle_error("Thread creation failed");
        }
    }

    pdu_list.pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list.pdus) {
        free(threads);
        handle_error("Memory allocation failed");
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
        pdu_list.count++;
    }

    free(threads);
    return pdu_list;
}

int main() {
    srand(time(NULL));
    const char* imeis[] = {"123456789012345", "987654321098765"};
    PduList pdus = process_imeis(imeis, 2);

    // Cleanup
    free(pdus.pdus);
    return 0;
}
