} NR_UE_Measurement_Report;

typedef struct {
    NR_UE_Measurement_Report *reports[MAX_REPORTS];
    size_t count;
    size_t last_used_index;
    pthread_mutex_t lock;
} ReportManager;

ReportManager* create_report_manager() {
    ReportManager* manager = (ReportManager*)malloc(sizeof(ReportManager));
    if (!manager) return NULL;

    for (int i = 0; i < MAX_REPORTS; ++i) {
        manager->reports[i] = NULL;
    }
    manager->count = 0;
    manager->last_used_index = -1;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void free_report_manager(ReportManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < MAX_REPORTS && manager->reports[i]; ++i) {
        free(manager->reports[i]);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_report(ReportManager* manager, NR_UE_Measurement_Report report) {
    if (!manager || manager->count >= MAX_REPORTS) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t index = (manager->last_used_index + 1) % MAX_REPORTS;
    for (; manager->reports[index]; ++index, index %= MAX_REPORTS) {}

    manager->reports[index] = (NR_UE_Measurement_Report*)malloc(sizeof(NR_UE_Measurement_Report));
    if (!manager->reports[index]) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    *manager->reports[index] = report;
    manager->last_used_index = index;
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_report_by_id(ReportManager* manager, int measurement_id) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_REPORTS && manager->reports[i]; ++i) {
        if (manager->reports[i]->MEASUREMENT_ID == measurement_id) {
            free(manager->reports[i]);
            manager->reports[i] = NULL;
            --manager->count;

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int retrieve_report_by_criteria(ReportManager* manager, int measurement_id) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_REPORTS && manager->reports[i]; ++i) {
        if (manager->reports[i]->MEASUREMENT_ID == measurement_id) {
            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

// Placeholder for synchronization with external data source
void synchronize_with_external_source(ReportManager* manager) {
    // Implement logic to synchronize reports
}

