typedef struct {
    long offset;
    int key;
    double value;
} Record;

#define INITIAL_CAPACITY 10

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

int initialize_records(RecordArray *arr, size_t num_records, double min_value, double max_value) {
    if (num_records == 0) return -1;

    pthread_mutex_init(&arr->lock, NULL);

    arr->capacity = INITIAL_CAPACITY;
    arr->records = malloc(arr->capacity * sizeof(Record));
    if (!arr->records) return -1;

    srand((unsigned int)time(NULL));

    size_t i;
    for (i = 0; i < num_records && i < arr->capacity; ++i) {
        arr->records[i].offset = rand() % 100000 + 1; // Ensure non-zero
        arr->records[i].key = i;
        arr->records[i].value = min_value + (max_value - min_value) * ((double)rand() / RAND_MAX);
    }

    arr->count = num_records;

    return 0;
}

int resize_record_array(RecordArray *arr, size_t new_capacity) {
    pthread_mutex_lock(&arr->lock);

    Record *new_records = realloc(arr->records, new_capacity * sizeof(Record));
    if (!new_records) {
        pthread_mutex_unlock(&arr->lock);
        return -1;
    }

    arr->records = new_records;
    arr->capacity = new_capacity;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

void add_record(RecordArray *arr, long offset, int key, double value) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count == arr->capacity) {
        if (resize_record_array(arr, arr->capacity * 2) != 0) {
            pthread_mutex_unlock(&arr->lock);
            return;
        }
    }

    arr->records[arr->count].offset = offset;
    arr->records[arr->count].key = key;
    arr->records[arr->count].value = value;
    ++arr->count;

    pthread_mutex_unlock(&arr->lock);
}

void free_records(RecordArray *arr) {
    pthread_mutex_lock(&arr->lock);

    free(arr->records);
    arr->records = NULL;
    arr->capacity = 0;
    arr->count = 0;

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

void log_memory_operations(const char *operation, size_t size) {
    // Placeholder for logging memory operations
    printf("%s: %zu bytes\n", operation, size);
}
