typedef struct {
    int event_id;
    char* event_type;
    void* data_buffer;
} EventHandler;

typedef struct {
    EventHandler* handlers;
    size_t count;
} EventHandlerList;

// Function to initialize a handler
EventHandler* init_handler(int id, const char* type) {
    EventHandler* handler = (EventHandler*)malloc(sizeof(EventHandler));
    if (!handler) return NULL;

    handler->event_id = id;
    handler->event_type = strdup(type);
    if (!handler->event_type) {
        free(handler);
        return NULL;
    }

    // Allocate data buffer, size based on event type or fixed size
    handler->data_buffer = malloc(1024);  // Example fixed size allocation
    if (!handler->data_buffer) {
        free(handler->event_type);
        free(handler);
        return NULL;
    }

    return handler;
}

// Function to load external dependencies, returns success as boolean
int load_external_dependencies() {
    // Dummy implementation for loading dependencies
    // Return 0 for failure or non-zero for success
    return 1; 
}

// Error logging function
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

EventHandlerList parse_json_config(const char* json_str) {
    EventHandlerList handler_list = { .handlers = NULL, .count = 0 };

    // Parse JSON configuration string
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if (!root) {
        log_error("Failed to parse JSON: ");
        fprintf(stderr, "%.*s\n", (int)error.text.size, error.text.ptr);
        return handler_list; // Return empty list on failure
    }

    int load_success = load_external_dependencies();
    if (!load_success) {
        log_error("External dependency loading failed.");
        json_decref(root);
        return handler_list;
    }

    size_t index = 0;
    json_t *event_array = json_object_get(root, "events");
    if (json_is_array(event_array)) {
        size_t event_count = json_array_size(event_array);

        handler_list.handlers = (EventHandler*)malloc(sizeof(EventHandler) * event_count);
        if (!handler_list.handlers) {
            log_error("Memory allocation failed for handlers.");
            json_decref(root);
            return handler_list;
        }

        for (size_t i = 0; i < event_count; ++i) {
            json_t *event_obj = json_array_get(event_array, i);

            if (!json_is_object(event_obj)) continue;

            int id = json_integer_value(json_object_get(event_obj, "id"));
            const char* type = json_string_value(json_object_get(event_obj, "type"));

            EventHandler* handler = init_handler(id, type);
            if (handler) {
                handler_list.handlers[index++] = *handler;
                free(handler); // Since we copied the fields
                ++handler_list.count;
            } else {
                log_error("Failed to initialize event handler.");
            }
        }

        // Resize handlers array after actual count is known
        EventHandler* resized_handlers = (EventHandler*)realloc(handler_list.handlers, sizeof(EventHandler) * handler_list.count);
        if (!resized_handlers && handler_list.count > 0) {
            log_error("Memory reallocation failed for handlers.");
            free(handler_list.handlers);
            handler_list.handlers = NULL;
            handler_list.count = 0;
        } else {
            handler_list.handlers = resized_handlers;
        }
    }

    json_decref(root); // Decref the root to prevent memory leaks
    return handler_list;
}
