#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_OFFSETS 10000
#define KEY_RANGE 65536

typedef struct record {
    long *offset;
    int key;
    struct record *next;
} Record;

long offsets[MAX_OFFSETS] = {0};
Record *head = NULL, *tail = NULL;

// Global variable for maximum key value found
int max_key_value = -1;
pthread_mutex_t max_key_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct CacheEntry {
    int session_id;
    char session_details[256]; // Example size, adjust as necessary
    struct CacheEntry *next;
} CacheEntry;

#define CACHE_SIZE 100

CacheEntry *cache_head = NULL, *cache_tail = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to add entry to the cache
void cache_add(int session_id, const char *session_details) {
    pthread_mutex_lock(&cache_lock);

    CacheEntry *new_entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    if (!new_entry) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }
    new_entry->session_id = session_id;
    strncpy(new_entry->session_details, session_details, sizeof(new_entry->session_details) - 1);
    new_entry->next = NULL;

    // Add to the end of the cache
    if (cache_tail) {
        cache_tail->next = new_entry;
    } else {
        cache_head = new_entry;
    }
    cache_tail = new_entry;

    pthread_mutex_unlock(&cache_lock);
}

// Helper function to find entry in the cache
const char *cache_find(int session_id) {
    pthread_mutex_lock(&cache_lock);

    CacheEntry *current = cache_head;
    while (current) {
        if (current->session_id == session_id) {
            const char *details = current->session_details;
            pthread_mutex_unlock(&cache_lock);
            return details;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

// Helper function to initialize the cache
void init_cache() {
    pthread_mutex_init(&cache_lock, NULL);
    // Add any other initializations needed for cache here
}

// Function to manage memory and process inputs
void manage_memory_and_process() {
    int num_keys = 0;
    int *keys = (int *)malloc(KEY_RANGE * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < KEY_RANGE; ++i) keys[i] = -1;

    printf("Enter the number of unique keys followed by the keys themselves:\n");
    int key;
    while (scanf("%d", &key) && key >= 0) {
        if (num_keys >= KEY_RANGE || keys[key] != -1 || key < 0 || key > 65535) {
            fprintf(stderr, "Invalid key input\n");
            free(keys);
            exit(EXIT_FAILURE);
        }
        keys[key] = key;
        num_keys++;
    }

    Record *records[num_keys];
    for (int i = 0; i < num_keys; ++i) {
        if (keys[i] != -1) {
            records[i] = (Record *)malloc(sizeof(Record));
            if (!records[i]) {
                fprintf(stderr, "Memory allocation error\n");
                exit(EXIT_FAILURE);
            }
            records[i]->offset = &offsets[i % MAX_OFFSETS];
            records[i]->key = keys[i];
            records[i]->next = NULL;

            if (tail) tail->next = records[i];
            else head = records[i];
            tail = records[i];

            pthread_mutex_lock(&max_key_lock);
            if (records[i]->key > max_key_value) {
                max_key_value = records[i]->key;
            }
            pthread_mutex_unlock(&max_key_lock);
        }
    }

    // Traverse the linked list to find max key value
    Record *current = head;
    while (current) {
        cache_add(current->key, "Fetched session details");  // Placeholder for actual session fetching logic

        current = current->next;
    }

    printf("Max Key Value: %d\n", max_key_value);

    // Free allocated memory
    free(keys);
    current = head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    init_cache();
    manage_memory_and_process();

    // Example cache cleanup logic, if needed for a fixed-size cache
    pthread_mutex_lock(&cache_lock);
    CacheEntry *current = cache_head;
    while (current) {
        CacheEntry *temp = current;
        current = current->next;
        free(temp);
    }
    cache_head = NULL;
    cache_tail = NULL;
    pthread_mutex_unlock(&cache_lock);

    return 0;
}
