}

IMEIProcessingResult process_imei(char *imei) {
    IMEIProcessingResult result = {NULL, 0, {0}, rand() % 2};

    if (!validate_imei(imei, result.md5_hash)) {
        log_access("Invalid IMEI format");
        return result; // Error handling for invalid IMEI
    }

    char* pdu_data = (char*) malloc(sizeof(char) * 256); // Placeholder allocation size
    if (!pdu_data) {
        log_access("Memory allocation failure");
        return result;
    }

    // Example of populating NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < 3; ++i) { // Assume fixed number of PDUs for simplicity
        NFAPI_CRC_INDICATION_PDU_T pdu;
        snprintf(pdu_data, sizeof(char) * 256, "PDU_%d", i);
        pdu.rx_ue_information_tag = strdup(pdu_data);
        pdu.rnti = rand() % 1000;
        snprintf(pdu_data, sizeof(char) * 256, "CRC%d", i);
        pdu.crc_indication_rel8_tag = strdup(pdu_data);

        result.pdu_list = (NFAPI_CRC_INDICATION_PDU_T*) realloc(result.pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (result.pdu_count + 1));
        if (!result.pdu_list) {
            log_access("Memory reallocation failure");
            break;
        }

        result.pdu_list[result.pdu_count++] = pdu;
    }

    free(pdu_data);

    return result;
}

void parse_csv(const char *filename, SensorRecord **head) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_access("File open failure");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        SensorRecord* record = (SensorRecord*) malloc(sizeof(SensorRecord));
        if (!record) {
            log_access("Memory allocation for sensor record failed");
            break;
        }

        // Parse CSV and populate record fields
        sscanf(line, "%d,%c,%ld,%f,%lf,%llu,%[^\n]", &record->sensor_count,
               &record->sensor_type, &record->event_timestamp,
               &record->sensor_value, &record->quality_metric, 
               (unsigned long long*)&record->unique_id, record->description);

        pthread_mutex_lock(&lock);
        // Check for duplicates and add to list
        SensorRecord *current = *head;
        while (current) {
            if (current->unique_id == record->unique_id) {
                free(record->description); 
                free(record);
                pthread_mutex_unlock(&lock);
                break;
            }
            current = current->next;
        }

        record->next = *head;
        *head = record;
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
}

int main() {
    const char* imei = "490154203237518";
    IMEIProcessingResult result = process_imei(imei);

    for (size_t i = 0; i < result.pdu_count; ++i) {
        printf("PDU %zu: RX UE Information Tag = %s, RNTI = %d, CRC Indication Rel8 Tag = %s\n",
               i, result.pdu_list[i].rx_ue_information_tag,
               result.pdu_list[i].rnti, result.pdu_list[i].crc_indication_rel8_tag);
        free(result.pdu_list[i].rx_ue_information_tag);
        free(result.pdu_list[i].crc_indication_rel8_tag);
    }

    if (result.pdu_list) {
        free(result.pdu_list);
    }

    SensorRecord *head = NULL;
    parse_csv("sensors.csv", &head);

    while (head) {
        printf("Sensor ID: %llu, Type: %c, Value: %.2f\n", head->unique_id,
               head->sensor_type, head->sensor_value);
        SensorRecord *temp = head;
        head = head->next;
        free(temp->description);
        free(temp);
    }

    return 0;
}
