void manage_dynamic_list(size_t num_entries) {
    if (num_entries > 10000) {
        log_error("Exceeded maximum allowed entries.");
        return;
    }

    long *offsets = malloc(num_entries * sizeof(long));
    int *keys = malloc(num_entries * sizeof(int));

    if (!offsets || !keys) {
        log_error("Memory allocation failed.");
        free(offsets);
        free(keys);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    Record *records = malloc(num_entries * sizeof(Record));

    if (!pdus || !records) {
        log_error("Memory allocation failed.");
        free(offsets);
        free(keys);
        free(pdus);
        free(records);
        return;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        // Randomly initialize fields
        pdus[i].crcTag.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        pdus[i].crcTag.RNTI = rand() % 10000;
        pdus[i].CRCFLAG = rand() % 2;

        offsets[i] = (long)(rand() % 100000); // Example offset values
        keys[i] = rand() % 5000; // Example key values

        records[i].value = rand() % 100; // Random value in range [0, 99]

        if (!validate_pdu(&pdus[i])) {
            log_warning("Invalid PDU encountered at index %zu.", i);
        }
    }

    // Process the data as required...

    free(offsets);
    free(keys);
    free(pdus);
    free(records);
}

void log_error(const char *message) {
#ifdef DEBUG
    fprintf(stderr, "ERROR: %s\n", message);
#endif
}

void log_warning(const char *message) {
#ifdef DEBUG
    fprintf(stdout, "WARNING: %s\n", message);
#endif
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->crcTag.RX_UE_INFORMATION_TAG <= 0 || pdu->crcTag.RNTI <= 0) {
        return 0; // Invalid data
    }
    return 1;
}
