NFAPI_CRC_INDICATION_PDU_T* allocate_ue_indicators(unsigned int seed, size_t *allocated_size) {
    NFAPI_CRC_INDICATION_PDU_T *indicators = NULL;
    size_t increment_size = MAX_UE_INDICATORS / 10; // Increment in chunks
    unsigned char crcflag;

    srand(seed); // Initialize random number generator with seed

    for (size_t current_size = 0; current_size <= MAX_UE_INDICATORS; current_size += increment_size) {
        size_t new_size = current_size + increment_size;

        if (new_size > MAX_UE_INDICATORS) {
            new_size = MAX_UE_INDICATORS;
        }

        indicators = realloc(indicators, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!indicators) {
            fprintf(stderr, "Memory allocation failed.\n");
            free(indicators);
            return NULL;
        }

        // Check memory limit
        if ((new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > MEMORY_LIMIT_MB) {
            fprintf(stderr, "Memory usage exceeded 1 MB limit.\n");
            free(indicators);
            return NULL;
        }

        for (size_t i = current_size; i < new_size; ++i) {
            indicators[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Example valid tag
            indicators[i].RNTI = rand() % 65535 + 1; // Example valid RNTI
            indicators[i].CRC_INDICATION_REL8_TAG = (rand() % 256); // Example CRC tag
            crcflag = rand() % 2;
            indicators[i].CRCFLAG = crcflag;
        }

        *allocated_size = new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    return indicators;
}
