        pthread_mutex_init(&network_configs[i].lock, NULL);
        network_configs[i].num_channels = 0;
    }
}

LTE_TRANSPORT_CONTEXT_T* allocate_transport_context(size_t max_channels) {
    LTE_TRANSPORT_CONTEXT_T *contexts = malloc(max_channels * sizeof(LTE_TRANSPORT_CONTEXT_T));
    if (!contexts) {
        perror("Failed to allocate memory for transport contexts");
        exit(EXIT_FAILURE);
    }

    // Simulate dynamic initialization based on environmental factors
    for (size_t i = 0; i < max_channels; ++i) {
        contexts[i].config = /* Initialize config */;
        contexts[i].stats.average_throughput = 0.0;
        contexts[i].stats.minimum_latency = INT_MAX;
        contexts[i].stats.maximum_packet_loss = 0;

        // Randomly simulate interference for demonstration
        contexts[i].interference_level = (double)rand() / RAND_MAX; 
    }
    return contexts;
}

void update_channel_statistics(NetworkConfig *network, size_t index, const PHY_LAYER_STATS_T *new_stats) {
    pthread_mutex_lock(&network->lock);
    if (index < network->num_channels) {
        network->channels[index]->stats = *new_stats;
    }
    pthread_mutex_unlock(&network->lock);
}

void reconfigure_network(NetworkConfig *network, size_t max_channels) {
    pthread_mutex_lock(&network->lock);

    // Safely reinitialize contexts
    free(network->channels[0]);
    network->channels[0] = allocate_transport_context(max_channels);
    network->num_channels = max_channels;

    pthread_mutex_unlock(&network->lock);
}

void *network_monitor(void *arg) {
    NetworkConfig *network = (NetworkConfig *)arg;
    while (1) {
        // Simulate real-time data feed and update statistics
        PHY_LAYER_STATS_T new_stats = {/* Update from external sources */};

        for (size_t i = 0; i < network->num_channels; ++i) {
            update_channel_statistics(network, i, &new_stats);
        }
        sleep(1); // Simulate periodic updates every second
    }

    return NULL;
}

void initialize_network(int network_id, size_t max_channels) {
    if (network_id >= MAX_NETWORKS || max_channels > MAX_CHANNELS_PER_NETWORK) {
        fprintf(stderr, "Invalid network configuration\n");
        return;
    }

    NetworkConfig *config = &network_configs[network_id];
    pthread_mutex_lock(&config->lock);
    config->channels[0] = allocate_transport_context(max_channels);
    config->num_channels = max_channels;
    pthread_mutex_unlock(&config->lock);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, network_monitor, config) != 0) {
        perror("Failed to create monitoring thread");
        exit(EXIT_FAILURE);
    }
}

void cleanup_network_configs() {
    for (int i = 0; i < MAX_NETWORKS; ++i) {
        NetworkConfig *config = &network_configs[i];

        pthread_mutex_lock(&config->lock);
        if (config->channels[0]) {
            free(config->channels[0]);
        }
        pthread_mutex_unlock(&config->lock);

        pthread_mutex_destroy(&config->lock);
    }
}

int main() {
    srand(time(NULL));

    initialize_network_configs();

    for (int i = 0; i < MAX_NETWORKS; ++i) {
        initialize_network(i, MAX_CHANNELS_PER_NETWORK);
    }

    // The program would normally run indefinitely
    sleep(10); 

    cleanup_network_configs();
    return 0;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_mutex_t` for safe concurrent access to shared resources.
- **Dynamic Reconfiguration**: Supports reconfiguring network settings without disrupting ongoing processing.
- **Performance Optimization**: Minimizes dynamic allocations and synchronizes access using efficient mechanisms.
- **Real-time Updates**: Periodically updates channel statistics from simulated external data feeds.
- **Concurrent Network Management**: Handles multiple networks, each with its own set of channels.

This code provides a comprehensive framework for simulating and managing wireless network configurations in real time.']

