#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define OFFSET_ARRAY_SIZE 10000
#define MAX_KEY_VALUE 65535

typedef struct Record {
    long *offset;
    int key;
    struct Record *prev, *next;
} Record;

typedef struct {
    Record *head, *tail;
    pthread_mutex_t lock;
} ThreadSafeList;

long offset_array[OFFSET_ARRAY_SIZE];
ThreadSafeList list = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER};
int global_max_key = -1;
pthread_mutex_t max_key_lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(void* buffer, const char* message) {
    snprintf(buffer, 256, "%s", message);
}

Record* find_record_by_key(int key) {
    pthread_mutex_lock(&list.lock);
    Record *current = list.head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list.lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list.lock);
    return NULL;
}

void update_global_max_key(int key) {
    pthread_mutex_lock(&max_key_lock);
    if (key > global_max_key) {
        global_max_key = key;
    }
    pthread_mutex_unlock(&max_key_lock);
}

ThreadSafeList* create_thread_safe_list() {
    ThreadSafeList *lst = malloc(sizeof(ThreadSafeList));
    if (!lst) return NULL;

    lst->head = lst->tail = NULL;
    pthread_mutex_init(&lst->lock, NULL);
    return lst;
}

void add_record(ThreadSafeList *list, long *offset, int key) {
    pthread_mutex_lock(&list->lock);

    Record *existing = find_record_by_key(key);
    if (existing != NULL || key < 0 || key > MAX_KEY_VALUE) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle allocation failure
    }

    new_record->offset = offset;
    new_record->key = key;
    new_record->prev = list->tail;
    new_record->next = NULL;

    if (list->tail != NULL)
        list->tail->next = new_record;
    else
        list->head = new_record;

    list->tail = new_record;

    update_global_max_key(key);
    pthread_mutex_unlock(&list->lock);
}

void free_list(ThreadSafeList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int validate_and_add_keys(ThreadSafeList *list, int *keys, size_t num_keys, void* error_buffer) {
    for (size_t i = 0; i < num_keys; ++i) {
        if (keys[i] < 0 || keys[i] > MAX_KEY_VALUE) {
            log_error(error_buffer, "Invalid key range.");
            return -1;
        }

        Record *existing = find_record_by_key(keys[i]);
        if (existing != NULL) {
            log_error(error_buffer, "Duplicate key found.");
            return -1;
        }
    }

    for (size_t i = 0; i < num_keys; ++i) {
        add_record(list, &offset_array[keys[i] % OFFSET_ARRAY_SIZE], keys[i]);
    }

    return 0;
}

// Sample usage
int main() {
    void *error_buffer = malloc(256);
    ThreadSafeList *list = create_thread_safe_list();
    if (!list) {
        log_error(error_buffer, "Failed to allocate thread-safe list.");
        return -1;
    }

    int keys[] = {1000, 2000, 3000}; // Example keys
    size_t num_keys = sizeof(keys) / sizeof(keys[0]);

    if (validate_and_add_keys(list, keys, num_keys, error_buffer) != 0) {
        printf("Error: %s\n", (char *)error_buffer);
        free(error_buffer);
        free_list(list);
        return -1;
    }

    // Cleanup
    free_list(list);
    free(error_buffer);

    return 0;
}
