#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RANDOM_STRING_LEN 32
#define KEY_SIZE 16 // Example key size, can be adjusted

typedef struct {
    int value;
    char buffer[RANDOM_STRING_LEN + 1];
    EVP_CIPHER_CTX *ctx;
} record;

void handleErrors(void) {
    fprintf(stderr, "An error occurred\n");
    ERR_print_errors_fp(stderr);
    exit(EXIT_FAILURE);
}

void generateRandomValue(int *value, int min, int max) {
    if (!RAND_add(&seed, 1, sizeof(seed))) {
        handleErrors();
    }
    RAND_seed((unsigned char*)&seed, sizeof(seed));
    *value = rand() % (max - min + 1) + min;
}

void generateRandomString(char *str, size_t length) {
    if (!RAND_bytes((unsigned char*)str, length)) {
        handleErrors();
    }
    str[length] = '\0';
}

void initializeRecord(record *rec, int min_val, int max_val, unsigned long seed, const EVP_CIPHER *cipher_type) {
    generateRandomValue(&rec->value, min_val, max_val);
    generateRandomString(rec->buffer, RANDOM_STRING_LEN);

    rec->ctx = EVP_CIPHER_CTX_new();
    if (!rec->ctx) handleErrors();

    EVP_CIPHER_CTX_init(rec->ctx);
    unsigned char key[KEY_SIZE], iv[EVP_MAX_IV_LENGTH];

    if (!RAND_bytes(key, KEY_SIZE)) {
        handleErrors();
    }
    if (!RAND_bytes(iv, EVP_CIPHER_iv_length(cipher_type))) {
        handleErrors();
    }

    if (EVP_EncryptInit_ex(rec->ctx, cipher_type, NULL, key, iv) != 1) {
        handleErrors();
    }

    // Set dynamic key and IV lengths
    if (cipher_type == EVP_aes_256_cbc()) { 
        EVP_CIPHER_CTX_set_key_length(rec->ctx, KEY_SIZE * 2); // Example: use a longer key for AES-256
    } else if (cipher_type == EVP_camellia_128_cbc()) {
        EVP_CIPHER_CTX_set_key_length(rec->ctx, KEY_SIZE);
    }
    EVP_CIPHER_CTX_set_iv_length(rec->ctx, EVP_CIPHER_iv_length(cipher_type));

    // Additional context setup can be done here based on the mode
}

void cleanupRecord(record *rec) {
    if (rec->ctx) {
        EVP_CIPHER_CTX_cleanup(rec->ctx);
        EVP_CIPHER_CTX_free(rec->ctx);
    }
}

void* processRecords(void *arg) {
    int num_records = *(int*)arg;
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    const EVP_CIPHER *cipher_type = EVP_aes_256_cbc(); // Example cipher type
    unsigned long seed = time(NULL);
    pthread_t threads[num_records];

    for (int i = 0; i < num_records; ++i) {
        initializeRecord(&records[i], 1, 100, seed, cipher_type);

        // Create a thread to handle encryption/decryption for each record
        if (pthread_create(&threads[i], NULL, processRecords, &records[i])) {
            fprintf(stderr, "Error creating thread\n");
            pthread_exit(NULL);
        }
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
        cleanupRecord(&records[i]);
    }

    free(records);

    return NULL;
}

void performCryptoOperations(int num_records) {
    if (!RAND_poll()) {
        handleErrors();
    }
    pthread_t main_thread;

    if (pthread_create(&main_thread, NULL, processRecords, &num_records)) {
        fprintf(stderr, "Error creating main processing thread\n");
        exit(EXIT_FAILURE);
    }

    pthread_join(main_thread, NULL);
}
