#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <semaphore.h>

class RandomRecordManager {
public:
    struct Record {
        long offset;
        int key;
        double value;

        Record(long o, int k, double v) : offset(o), key(k), value(v) {}
    };

    RandomRecordManager(size_t numRecords, double minRange, double maxRange);
    ~RandomRecordManager();

    void initializeCollection(size_t numRecords, double minRange, double maxRange);

private:
    static std::mt19937 rng;
    static std::mutex mtx;

    std::vector<Record> records;
    sem_t accessSemaphore;

    bool validateOffsets() const;

    static long generateUniqueOffset();
};

std::mt19937 RandomRecordManager::rng(std::random_device{}());
std::mutex RandomRecordManager::mtx;

RandomRecordManager::RandomRecordManager(size_t numRecords, double minRange, double maxRange)
    : records(numRecords), accessSemaphore(1) {
    initializeCollection(numRecords, minRange, maxRange);
}

RandomRecordManager::~RandomRecordManager() {
    sem_destroy(&accessSemaphore);
}

void RandomRecordManager::initializeCollection(size_t numRecords, double minRange, double maxRange) {
    std::uniform_real_distribution<double> dist(minRange, maxRange);

    for (size_t i = 0; i < numRecords; ++i) {
        long uniqueOffset;
        do {
            uniqueOffset = generateUniqueOffset();
        } while (!validateOffsets());

        records[i] = Record(uniqueOffset, static_cast<int>(i), dist(rng));
    }
}

bool RandomRecordManager::validateOffsets() const {
    std::unordered_set<long> offsets(records.size());
    for (const auto& record : records) {
        if (record.offset <= 0 || !offsets.insert(record.offset).second) {
            return false;
        }
    }
    return true;
}

long RandomRecordManager::generateUniqueOffset() {
    static std::uniform_int_distribution<long> offsetDist(1, 1000000000); // Example range for offsets
    long offset = offsetDist(rng);
    std::lock_guard<std::mutex> lock(mtx);
    return offset; // Further uniqueness checks can be added here as needed.
}
