typedef struct Record {
    int value;
    char* identifier;
    char* json_representation;
    struct Record* prev;
    struct Record* next;
} Record;

// Helper function to generate a random alphanumeric string
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* str = malloc(length + 1);
    if (str == NULL) return NULL;

    for (size_t i = 0; i < length; i++) {
        int index = rand() % (sizeof(charset) - 1);
        str[i] = charset[index];
    }
    str[length] = '\0';
    return str;
}

// Helper function to generate a random JSON object
char* generate_random_json(size_t max_length) {
    const char* types[] = {"\"string\"", "\"number\"", "\"boolean\"", "{}", "[]"};
    size_t num_types = sizeof(types) / sizeof(types[0]);

    char* json = malloc(max_length + 1);
    if (json == NULL) return NULL;

    int length = rand() % max_length + 1;
    snprintf(json, length + 1, "%s", types[rand() % num_types]);
    return json;
}

// Function to initialize and allocate memory for arrays and linked list
void initialize_data(
    long* offsets,
    int* keys,
    Record** records,
    char*** identifiers,
    size_t num_elements,
    size_t identifier_length,
    size_t json_max_length) {

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    *offsets = malloc(num_elements * sizeof(long));
    *keys = malloc(num_elements * sizeof(int));
    *records = calloc(num_elements, sizeof(Record*));
    *identifiers = malloc(num_elements * sizeof(char*));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *identifiers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&lock);

        (*offsets)[i] = rand() % 10000;

        (*keys)[i] = rand() % 1000;

        (*identifiers)[i] = generate_random_string(identifier_length);
        if ((*identifiers)[i] == NULL) {
            fprintf(stderr, "Failed to allocate identifier string\n");
            break;
        }

        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            free((*identifiers)[i]);
            fprintf(stderr, "Failed to allocate record structure\n");
            break;
        }

        (*records)[i]->value = rand() % 1000;

        char* json_str = generate_random_json(json_max_length);
        if (json_str == NULL) {
            fprintf(stderr, "Failed to allocate JSON string\n");
            free((*identifiers)[i]);
            free((*records)[i]);
            break;
        }
        (*records)[i]->json_representation = json_str;

        char* identifier_copy = strdup((*identifiers)[i]);
        if (identifier_copy == NULL) {
            fprintf(stderr, "Failed to duplicate identifier string\n");
            free(json_str);
            free((*records)[i]);
            break;
        }
        (*records)[i]->identifier = identifier_copy;

        pthread_mutex_unlock(&lock);
    }

    // Initialize doubly linked list
    for (size_t i = 0; i < num_elements; ++i) {
        if (i > 0) {
            (*records)[i - 1]->next = (*records)[i];
            (*records)[i]->prev = (*records)[i - 1];
        }
    }

    pthread_mutex_destroy(&lock);
}

// Function to free allocated memory
void cleanup_data(
    long* offsets,
    int* keys,
    Record** records,
    char*** identifiers,
    size_t num_elements) {

    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);

    for (size_t i = 0; i < num_elements; ++i) {
        if (records[i] != NULL) {
            if (records[i]->json_representation != NULL) free(records[i]->json_representation);
            if (records[i]->identifier != NULL) free(records[i]->identifier);
            free(records[i]);
        }
        if (identifiers[i] != NULL) free(identifiers[i]);
    }

    free(records);
    free(*identifiers);
}

int main() {
    size_t num_elements = 10;
    size_t identifier_length = 8;
    size_t json_max_length = 50;

    long* offsets;
    int* keys;
    Record** records;
    char*** identifiers;

    initialize_data(&offsets, &keys, &records, &identifiers, num_elements, identifier_length, json_max_length);

    // Simulate usage
    sleep(1); // Assume some processing happens here

    cleanup_data(&offsets, &keys, &records, &identifiers, num_elements);

    return 0;
}
