typedef struct {
    uint32_t fcs;
} MAC_FCS;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    MAC_FCS fcs;
} MAC_FRAME;

int initialize_frames(MAC_FRAME *frames, size_t num_frames, const uint8_t *input_stream,
                      size_t input_length, int enable_strict_alignment) {

    if (num_frames > MAX_FRAMES) {
        return -1; // Error: too many frames requested
    }

    for (size_t i = 0; i < num_frames && input_length > 0; ++i) {
        MAC_FRAME *frame = &frames[i];
        size_t payload_size;

        if (input_length >= PAYLOAD_MAX_SIZE) {
            payload_size = PAYLOAD_MAX_SIZE;
        } else if (input_length < MIN_PAYLOAD_SIZE) {
            // Ensure minimum frame size by padding
            payload_size = input_length + (MIN_PAYLOAD_SIZE - input_length);
        } else {
            payload_size = input_length;
        }

        // Calculate total frame size
        size_t total_frame_size = sizeof(MAC_HEADER) + payload_size + sizeof(MAC_FCS);

        if (total_frame_size > MAX_FRAME_SIZE) {
            return -2; // Error: frame size exceeds maximum allowed limit
        }

        // Allocate memory for the MAC_PAYLOAD data
        frame->payload.data = malloc(payload_size);
        if (!frame->payload.data) {
            // Handle out-of-memory condition gracefully
            for (size_t j = 0; j < i; ++j) {
                free(frames[j].payload.data); // Free already allocated memory
            }
            return -3; // Error: memory allocation failed
