        input_length -= payload_size;

        if (enable_strict_alignment && (uintptr_t)frame->payload.data % sizeof(uint32_t)) {
            // Optional strict alignment check, not enforced here but should be handled per requirements.
        }
    }

    return 0; // Success
}

void free_frames(MAC_FRAME *frames, size_t num_frames) {
