### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

void ShuffleRecords(long* offsets, int numOffsets, int* keys, int numKeys, record** shuffledRecords, int* shuffledKeys, long* shuffledOffsets, unsigned int seed) {
    if (numOffsets != numKeys || numOffsets == 0) {
        printf("Error: Mismatched number of offsets and keys or zero elements.\n");
        return;
    }

    // Allocate memory for records
    *shuffledRecords = malloc(numOffsets * sizeof(record));
    *shuffledKeys = malloc(numOffsets * sizeof(int));
    *shuffledOffsets = malloc(numOffsets * sizeof(long));

    if (!(*shuffledRecords) || !(*shuffledKeys) || !(*shuffledOffsets)) {
        printf("Memory allocation failed.\n");
        free(*shuffledRecords);
        free(*shuffledKeys);
        free(*shuffledOffsets);
        return;
    }

    // Initialize records
    for (int i = 0; i < numOffsets; ++i) {
        (*shuffledRecords)[i].key = keys[i];
        (*shuffledRecords)[i].offset = offsets[i];
        (*shuffledKeys)[i] = keys[i];
        (*shuffledOffsets)[i] = offsets[i];
    }

    // Seed the random number generator
    srand(seed);

    // Shuffle records using Fisher-Yates algorithm
    for (int i = numOffsets - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        record tempRecord = (*shuffledRecords)[i];
        int tempKey = (*shuffledKeys)[i];
        long tempOffset = (*shuffledOffsets)[i];

        (*shuffledRecords)[i] = (*shuffledRecords)[j];
        (*shuffledKeys)[i] = (*shuffledKeys)[j];
        (*shuffledOffsets)[i] = (*shuffledOffsets)[j];

        (*shuffledRecords)[j] = tempRecord;
        (*shuffledKeys)[j] = tempKey;
        (*shuffledOffsets)[j] = tempOffset;
    }
}

// Example usage
int main() {
    long offsets[] = {10, 20, 30};
    int keys[] = {1, 2, 3};

    record* shuffledRecords = NULL;
    int* shuffledKeys = NULL;
    long* shuffledOffsets = NULL;

    ShuffleRecords(offsets, 3, keys, 3, &shuffledRecords, shuffledKeys, shuffledOffsets, 42);

    if (shuffledRecords) {
        for (int i = 0; i < 3; ++i) {
            printf("Record %d: Key = %d, Offset = %ld\n", i, shuffledKeys[i], shuffledOffsets[i]);
        }
        free(shuffledRecords);
        free(shuffledKeys);
        free(shuffledOffsets);
    }

    return 0;
}
