using System;

public class RandomValueGenerator
{
    private readonly float minFloatRange;
    private readonly float maxFloatRange;
    private readonly int minIntRange;
    private readonly int maxIntRange;

    public RandomValueGenerator(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        minFloatRange = minFloat;
        maxFloatRange = maxFloat;
        minIntRange = minInt;
        maxIntRange = maxInt;
    }

    // Simulates fetching a random float from an external data source
    public float FetchRandomFloat()
    {
        return (float)new Random().NextDouble() * (maxFloatRange - minFloatRange) + minFloatRange;
    }

    // Simulates fetching a random integer from an external data source
    public int FetchRandomInt()
    {
        return new Random().Next(minIntRange, maxIntRange);
    }

    public float GenerateRandomFloat(bool inclusiveMax)
    {
        double value = FetchRandomFloat();
        if (inclusiveMax && Math.Abs(maxFloatRange - value) < 1e-9)
            value += 0.0001f; // small adjustment to include the upper bound
        return (float)value;
    }

    public int GenerateRandomInt(bool inclusiveMax)
    {
        int value = FetchRandomInt();
        if (inclusiveMax && value == maxIntRange - 1)
            ++value; // adjust to include the upper bound
        return value;
    }

    public override string ToString()
    {
        return $"Float Range: [{minFloatRange}, {maxFloatRange}], Int Range: [{minIntRange}, {maxIntRange}]";
    }
}

// Example usage in a C# program
public class Program
{
    public static void Main()
    {
        RandomValueGenerator generator = new RandomValueGenerator(0.0f, 1.0f, 0, 100);

        Console.WriteLine(generator.ToString());
        Console.WriteLine("Random Float (inclusive): " + generator.GenerateRandomFloat(true));
        Console.WriteLine("Random Int (exclusive): " + generator.GenerateRandomInt(false));
    }
}
