} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_THREADS 4

void *populate_structure(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *) arg;

    // Simulate populating RX_UE_INFORMATION_TAG and RNTI
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;  // Example value
    pdu->RNTI = rand() % 1000;                    // Example value

    return NULL;
}

int execute_command_and_set_crcflag(char *command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid > 0) { // Parent process
        int status;
        wait(&status);

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 1;  // Command executed successfully
        }
    } else { // Child process
        execlp(command, command, NULL);  // Replace with the actual command you want to execute
        perror("execlp");
        exit(EXIT_FAILURE);
    }

    return 0;
}

int generateNfaReports(NFAPI_CRC_INDICATION_PDU_T **reports, int num_reports, char *command) {
    if (!reports || !command) return 0;

    NFAPI_CRC_INDICATION_PDU_T *allocated_reports = malloc(num_reports * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!allocated_reports) {
        perror("malloc");
        return 0;
    }

    pthread_t threads[MAX_THREADS];
    int thread_count = (num_reports < MAX_THREADS) ? num_reports : MAX_THREADS;

    for (int i = 0; i < num_reports; i++) {
        if (i % thread_count == 0 && i != 0) {
            // Join all running threads before starting new ones
            for (int j = 0; j < thread_count; j++) {
                pthread_join(threads[j], NULL);
            }
        }

        pthread_create(&threads[i % thread_count], NULL, populate_structure, &allocated_reports[i]);
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    int success = execute_command_and_set_crcflag(command);

    if (success) {
        for (int i = 0; i < num_reports; i++) {
            allocated_reports[i].crc_indication_tag.CRCFLAG = 1;
        }
        *reports = allocated_reports;
        return 1;
    } else {
        free(allocated_reports);
        *reports = NULL;
        return 0;
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *reports = NULL;
    int result = generateNfaReports(&reports, 10, "ls");

    if (result) {
        printf("Command executed successfully and reports generated.\n");
        for (int i = 0; i < 10 && reports[i].RX_UE_INFORMATION_TAG != 0; ++i) { // Assuming non-zero tags
            printf("Report %d: RX_UE_INFORMATION_TAG = %u, RNTI = %u, CRCFLAG = %u\n",
                   i,
