['Below is an implementation in C for managing a dynamic linked list of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_ENTRIES 1000

typedef struct {
    // Assume these types are defined elsewhere
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int current_size = 0;

void insert_sorted(NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (current_size >= MAX_ENTRIES) {
        // Remove the least recently added entry
        Node* temp = head;
        head = head->next;
        free(temp);
        current_size--;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = new_data;

    // Insert in sorted order
    if (!head || head->data.RNTI > new_data.RNTI) {
        newNode->next = head;
        head = newNode;
    } else {
        Node* current = head;
        while (current->next && current->next->data.RNTI < new_data.RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    current_size++;
}

int get_list_size() {
    return current_size;
}

void free_list() {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    current_size = 0;
}
```

### Key Points:
- **Dynamic Memory Allocation**: The list is managed using dynamic memory allocation to handle varying sizes efficiently.
- **Sorting**: New entries are inserted in sorted order based on `RNTI`.
- **Size Limitation**: If the list exceeds 1000 entries, the least recently added entry (the head) is removed.
- **Memory Management**: Proper allocation and deallocation of memory are ensured to prevent leaks.
- **Concurrency Considerations**: For high-throughput scenarios, consider using mutexes or other synchronization mechanisms if this code is used in a multithreaded environment.']

