#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_BUFFER_SIZE 5000

typedef struct {
    time_t timestamp;
    int transaction_id;
    bool success_flag;
} MAC_TRANSACTION_RECORD;

typedef struct {
    MAC_TRANSACTION_RECORD *buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    size_t count;
} CircularBuffer;

void initialize_buffer(CircularBuffer *cb, size_t capacity) {
    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->buffer = (MAC_TRANSACTION_RECORD *)malloc(capacity * sizeof(MAC_TRANSACTION_RECORD));
}

void free_buffer(CircularBuffer *cb) {
    free(cb->buffer);
}

bool is_full(const CircularBuffer *cb) {
    return cb->count == cb->capacity;
}

bool is_empty(const CircularBuffer *cb) {
    return cb->count == 0;
}

void enqueue_transaction(CircularBuffer *cb, MAC_TRANSACTION_RECORD record) {
    if (is_full(cb)) {
        // Overwrite the oldest transaction
        cb->tail = (cb->tail + 1) % cb->capacity;
    } else {
        cb->count++;
    }

    cb->buffer[cb->head] = record;
    cb->head = (cb->head + 1) % cb->capacity;

    // Log the buffer state change
    printf("Enqueued transaction ID: %d\n", record.transaction_id);
}

MAC_TRANSACTION_RECORD dequeue_transaction(CircularBuffer *cb) {
    MAC_TRANSACTION_RECORD record = {0, -1, false};

    if (is_empty(cb)) {
        fprintf(stderr, "Attempt to dequeue from an empty buffer.\n");
        return record;
    }

    record = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count--;

    // Log the buffer state change
    printf("Dequeued transaction ID: %d\n", record.transaction_id);

    return record;
}

int count_successful_transactions(const CircularBuffer *cb) {
    int success_count = 0;

    for (size_t i = 0; i < cb->count; ++i) {
        size_t index = (cb->tail + i) % cb->capacity;
        if (cb->buffer[index].success_flag) {
            success_count++;
        }
    }

    return success_count;
}

void log_buffer_state(const CircularBuffer *cb) {
    printf("Current Buffer State:\n");
    printf("Capacity: %zu, Count: %zu\n", cb->capacity, cb->count);
    for (size_t i = 0; i < cb->count; ++i) {
        size_t index = (cb->tail + i) % cb->capacity;
        printf("Transaction ID: %d, Timestamp: %ld, Success: %s\n",
               cb->buffer[index].transaction_id,
               cb->buffer[index].timestamp,
               cb->buffer[index].success_flag ? "Yes" : "No");
    }
}

int main() {
    CircularBuffer cb;
    initialize_buffer(&cb, MAX_BUFFER_SIZE);

    // Example usage
    MAC_TRANSACTION_RECORD record1 = {time(NULL), 101, true};
    enqueue_transaction(&cb, record1);

    MAC_TRANSACTION_RECORD record2 = {time(NULL) + 10, 102, false};
    enqueue_transaction(&cb, record2);

    log_buffer_state(&cb);
    printf("Successful Transactions: %d\n", count_successful_transactions(&cb));

    free_buffer(&cb);
    return 0;
}
