### C Code: `nfaapi.c`

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_QUEUE_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to compare two PDU structures based on RNTI
int compare_pdu(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pduA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pduB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pduA->RNTI - pduB->RNTI;
}

// Function to handle the queue
int handle_nfaapi_pdu_queue(NFAPI_CRC_INDICATION_PDU_T **queue, int *size) {
    static NFAPI_CRC_INDICATION_PDU_T internalQueue[MAX_QUEUE_SIZE];
    static int currentSize = 0;

    if (*size > MAX_QUEUE_SIZE) {
        // Discard oldest entries to make space
        if (currentSize + *size > MAX_QUEUE_SIZE) {
            int discardCount = currentSize + *size - MAX_QUEUE_SIZE;
            memmove(internalQueue, internalQueue + discardCount, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (MAX_QUEUE_SIZE - discardCount));
            currentSize = MAX_QUEUE_SIZE - discardCount;
        }
    } else if (*size > 0) {
        // Add new entries
        memcpy(&internalQueue[currentSize], queue[*size - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * *size);
        currentSize += *size;

        // Sort the queue by RNTI
        qsort(internalQueue, currentSize, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);
    }

    // Update pointer to the internal queue
    *queue = internalQueue;

    return 0;  // Success
}

// Function to initialize an array with random values
int initialize_rach_array(NFAPI_RACH_REQ_PDU_T **array, int N, unsigned int seed) {
    if (N <= 0) return -1;  // Error: Invalid size

    *array = malloc(sizeof(NFAPI_RACH_REQ_PDU_T) * N);
    if (*array == NULL) return -2;  // Error: Memory allocation failed

    srand(seed);  // Seed the random number generator
    for (int i = 0; i < N; ++i) {
        (*array)[i].UTRAN_CELL_ID = rand() % 10000;
        (*array)[i].TMSI = rand() % 1000000;
        (*array)[i].PREAMBLE_SEQ_NOM = rand() % 8;
        (*array)[i].corruption_flag = (rand() % 2) == 1;
    }

    return 0;  // Success
}

// Example structure for RACH_REQ_PDU_T, modify as needed
typedef struct {
    int UTRAN_CELL_ID;
    int TMSI;
    unsigned char PREAMBLE_SEQ_NOM;
    unsigned char corruption_flag;
} NFAPI_RACH_REQ_PDU_T;

