#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <limits.h>

typedef struct record {
    long *offset_ptr;
    int key;
    double value;
    struct record *next;
} Record;

#define MAX_RESOURCES 10000
#define KEY_RANGE_MAX 65535

// Global variable for maximum key in the linked list.
static int global_max_key = INT_MIN;

// Hash table to ensure unique and greater than zero offsets.
typedef struct {
    long *data[MAX_RESOURCES];
    int size;
} OffsetHashTable;

OffsetHashTable* create_offset_hash_table() {
    OffsetHashTable *table = malloc(sizeof(OffsetHashTable));
    memset(table->data, 0, sizeof(long*) * MAX_RESOURCES);
    table->size = 0;
    return table;
}

int hash_function(long offset) {
    return (int)(offset % MAX_RESOURCES);
}

long* allocate_memory_pool(size_t record_count, size_t record_size) {
    // Allocate a large block of memory for all records.
    void *pool = malloc(record_count * record_size);
    if (!pool) return NULL;

    return pool;
}

Record* create_record(long offset, int key, double value, long *offset_array) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->offset_ptr = &offset_array[offset / sizeof(long)];
    record->key = key;
    record->value = value;
    record->next = NULL;

    return record;
}

int is_key_valid(int *keys, int size, int new_key) {
    for (int i = 0; i < size; i++) {
        if (keys[i] == new_key || keys[i] < 0 || keys[i] > KEY_RANGE_MAX)
            return 0;
    }
    return 1;
}

long generate_unique_offset(OffsetHashTable *table) {
    long offset = 1 + rand() % ((ULONG_MAX / sizeof(long)) - 1);
    while (!table->data[hash_function(offset)]) {
        table->data[hash_function(offset)] = &offset;
        table->size++;
        return offset;
    }
    return generate_unique_offset(table); // Recurse until unique
}

Record* init_records(int record_count, int key_count, double value_min, double value_max) {
    long *offset_array = (long*)malloc(sizeof(long) * MAX_RESOURCES);
    if (!offset_array) return NULL;

    memset(offset_array, 0, sizeof(long) * MAX_RESOURCES);

    OffsetHashTable *hash_table = create_offset_hash_table();

    int *keys = malloc(key_count * sizeof(int));
    if (!keys) {
        free(offset_array);
        return NULL;
    }

    for (int i = 0; i < key_count; ) {
        int new_key = rand() % (KEY_RANGE_MAX + 1);
        if (is_key_valid(keys, i, new_key)) {
            keys[i++] = new_key;
        }
    }

    Record *head = NULL;

    for (int i = 0; i < record_count; ++i) {
        long offset = generate_unique_offset(hash_table);
        double value = ((double)rand() / RAND_MAX) * (value_max - value_min) + value_min;

        int key = keys[rand() % key_count];

        Record *record = create_record(offset, key, value, offset_array);
        if (!record) {
            // Free previously allocated resources on error
            free_keys(keys, i);
            free_hash_table(hash_table);
            free(offset_array);
            return NULL;
        }

        record->next = head;
        head = record;

        if (key > global_max_key)
            global_max_key = key;
    }

    free(keys);
    free_offset_hash_table(hash_table);

    return head;
}

void free_keys(int *keys, int size) {
    free(keys);
}

void free_record_list(Record *head) {
    while (head) {
        Record *temp = head;
        head = head->next;
        free(temp);
    }
}

void free_hash_table(OffsetHashTable *table) {
    memset(table->data, 0, sizeof(long*) * MAX_RESOURCES);
    free(table);
}

int main() {
