['Below is a C implementation that manages an array of `record` structures using dynamic memory allocation, hash table for uniqueness validation, semaphore for thread safety, and integrates error handling. It also considers efficiency in memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
    sem_t semaphore;      // To manage concurrent access
} RecordArray;

typedef struct Node {
    long offset;
    struct Node* next;
} HashNode;

#define HASH_TABLE_SIZE 4096

HashNode *hash_table[HASH_TABLE_SIZE];

unsigned int hash_function(long offset) {
    return (offset % HASH_TABLE_SIZE);
}

int is_offset_unique(long offset) {
    unsigned int index = hash_function(offset);
    HashNode *node = hash_table[index];

    while (node != NULL) {
        if (node->offset == offset) {
            return 0;
        }
        node = node->next;
    }
    return 1;
}

void insert_offset(long offset) {
    unsigned int index = hash_function(offset);
    HashNode *new_node = (HashNode *)malloc(sizeof(HashNode));

    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for hash node\n");
        exit(EXIT_FAILURE);
    }

    new_node->offset = offset;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode *node = hash_table[i];

        while (node != NULL) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
}

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray *arr = (RecordArray*)malloc(sizeof(RecordArray));

    if (!arr) {
        fprintf(stderr, "Failed to allocate memory for RecordArray\n");
        exit(EXIT_FAILURE);
    }

    arr->records = (record *)malloc(initial_capacity * sizeof(record));
    arr->capacity = initial_capacity;
    arr->count = 0;

    pthread_mutex_init(&arr->lock, NULL);
    sem_init(&arr->semaphore, 0, 1);

    if (!arr->records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(arr);
        exit(EXIT_FAILURE);
    }

    memset(hash_table, 0, sizeof(hash_table));
    return arr;
}

void destroy_record_array(RecordArray *arr) {
    if (arr) {
        free(arr->records);
        pthread_mutex_destroy(&arr->lock);
        sem_destroy(&arr->semaphore);
        free_hash_table();
        free(arr);
    }
}

int add_record(RecordArray *arr, int key, double min_val, double max_val) {
    sem_wait(&arr->semaphore);

    if (pthread_mutex_lock(&arr->lock)) {
        fprintf(stderr, "Failed to lock mutex\n");
        return -1;
    }

    // Dynamically resize the array if needed
    if (arr->count == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        record *new_records = realloc(arr->records, new_capacity * sizeof(record));

        if (!new_records) {
            fprintf(stderr, "Failed to reallocate memory for records\n");
            pthread_mutex_unlock(&arr->lock);
            sem_post(&arr->semaphore);
            return -1;
        }

        arr->records = new_records;
        arr->capacity = new_capacity;
    }

    long offset;
    do {
        offset = rand() % (LONG_MAX / 2) + 1; // Ensure positive and reasonably large value
    } while (!is_offset_unique(offset));

    record *new_record = &arr->records[arr->count++];
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = min_val + ((max_val - min_val) * (double)rand() / RAND_MAX);

    insert_offset(new_record->offset);

    pthread_mutex_unlock(&arr->lock);
    sem_post(&arr->semaphore);

    return 0; // Success
}

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

int main() {
    initialize_random_seed();

    RecordArray *record_array = create_record_array(INITIAL_CAPACITY);

    for (int i = 0; i < 10000; ++i) {  // Example: add 10,000 records
        if (add_record(record_array, i % 100, 0.0, 1.0)) {
            fprintf(stderr, "Failed to add record at index %d\n", i);
        }
    }

    destroy_record_array(record_array);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses a mutex for mutual exclusion and semaphores for managing concurrent access.
- **Unique Offsets**: Utilizes a simple hash table to ensure uniqueness of offsets.
- **Dynamic Resizing**: Dynamically resizes the array when needed using `realloc`.
- **Error Handling**: Includes error checks with appropriate handling, ensuring memory is freed in case of failures.
- **Memory Pooling/Allocation Strategy**: Demonstrates efficient memory allocation patterns suitable for scalability.

Note: The code assumes a basic hash table implementation and could be further optimized or extended based on specific requirements.']

