// libnumproc.c
#include "libnumproc.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(Record *records, size_t count) {
    double min_val = atof(getenv("MIN_VAL") ?: "0.0");
    double max_val = atof(getenv("MAX_VAL") ?: "1.0");

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].field1 = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);
        records[i].field2 = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);
    }
}

void sort_data(double *data, size_t indices[], size_t size, const char *config_file) {
    // Parse config file and select sorting algorithm
    FILE *file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    char line[256];
    enum SortAlgorithm algo = QUICKSORT; // Default

    while (fgets(line, sizeof(line), file)) {
        if (strcmp(line, "QUICKSORT\n") == 0) {
            algo = QUICKSORT;
        } else if (strcmp(line, "MERGESORT\n") == 0) {
            algo = MERGESORT;
        } else if (strcmp(line, "HEAPSORT\n") == 0) {
            algo = HEAPSORT;
        }
    }

    fclose(file);

    switch (algo) {
        case QUICKSORT:
            qsort(data, size, sizeof(double), compare);
            break;
        case MERGESORT:
            merge_sort(data, indices, size);
            break;
        case HEAPSORT:
            heap_sort(data, indices, size);
            break;
    }
}

void aggregate_data(const double *data, size_t size, double *result) {
    pthread_mutex_lock(&lock);
    *result = 0.0;
    for (size_t i = 0; i < size; ++i) {
        *result += data[i];
    }
    pthread_mutex_unlock(&lock);
}

void filter_data(const double *data, size_t size, double *filtered, size_t *count, bool (*predicate)(double)) {
    size_t j = 0;
    for (size_t i = 0; i < size; ++i) {
        if (predicate(data[i])) {
            filtered[j++] = data[i];
        }
    }
    *count = j;
}

void transform_data(double *data, size_t size, void (*transform)(double *)) {
    for (size_t i = 0; i < size; ++i) {
        transform(&data[i]);
    }
}

void free_resources(void) {
    // Implement resource cleanup
}

// Sorting algorithms implementations and utility functions go here

```

