    return records;
}

// Utility function to generate a unique identifier from a character set.
char* generate_unique_identifier(size_t length, const char* charset) {
    size_t charset_length = strlen(charset);
    char *identifier = malloc((length + 1) * sizeof(char));
    if (!identifier) return NULL;

    for (size_t i = 0; i < length; ++i) {
        identifier[i] = charset[rand() % charset_length];
    }
    identifier[length] = '\0';

