#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint32_t ts;
    uint16_t len;
    uint16_t checksum;
} TPACKET_V3_HDR;

uint16_t compute_checksum(uint8_t *data, size_t length) {
    uint32_t sum = 0;
    for (size_t i = 0; i < length; i += 2) {
        uint16_t word;
        if (i + 1 < length) {
            word = (data[i] << 8) | data[i + 1];
        } else {
            word = (data[i] << 8);
        }
        sum += word;
    }

    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }

    return ~sum;
}

void process_numbers_and_packets() {
    size_t capacity = 10;
    float *numbers = malloc(capacity * sizeof(float));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    float smallest_number = __FLT_MAX__;
    while (scanf("%f", &numbers[count]) == 1) {
        if (numbers[count] < smallest_number) {
            smallest_number = numbers[count];
        }

        if (++count >= capacity) {
            capacity *= 2;
            float *new_numbers = realloc(numbers, capacity * sizeof(float));
            if (!new_numbers) {
                free(numbers);
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            numbers = new_numbers;
        }
    }

    printf("Smallest number: %f\n", smallest_number);

    TPACKET_V3_HDR *packet_headers = malloc(capacity * sizeof(TPACKET_V3_HDR));
    if (!packet_headers) {
        free(numbers);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        uint32_t ts = (uint32_t)(numbers[i] * 1000); // example timestamp conversion
        size_t packet_length = sizeof(float);

        if (packet_length > 1500 || packet_length == 0) { // assume valid Ethernet MTU and check for malformed packets
            continue;
        }

        uint8_t data[packet_length];
        memcpy(data, &numbers[i], packet_length);

        TPACKET_V3_HDR header = {
            .ts = ts,
            .len = (uint16_t)packet_length,
            .checksum = compute_checksum(data, packet_length)
        };

        packet_headers[i] = header;
    }

    for (size_t i = 0; i < count; ++i) {
        printf("Packet %zu: TS=%u, LEN=%u, CHECKSUM=0x%04X\n", 
               i, packet_headers[i].ts, packet_headers[i].len, packet_headers[i].checksum);
    }

    free(numbers);
    free(packet_headers);
}

int main() {
    process_numbers_and_packets();
    return 0;
}
