typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    FILE* log_file;
} DynamicArray;

void init_dynamic_array(DynamicArray* da, const char* log_filename) {
    pthread_mutex_init(&da->mutex, NULL);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    da->log_file = fopen(log_filename, "a");
    if (!da->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void free_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->mutex);
    if (da->array) {
        free(da->array);
        fprintf(da->log_file, "Deallocated memory for array of size %zu\n", da->size);
    }
    pthread_mutex_unlock(&da->mutex);
    fclose(da->log_file);
    pthread_mutex_destroy(&da->mutex);
}

int resize_dynamic_array(DynamicArray* da, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(da->log_file, "Memory allocation failed for capacity %zu\n", new_capacity);
        return -1;
    }
    da->capacity = new_capacity;
    da->array = new_array;
    fprintf(da->log_file, "Resized array to capacity %zu\n", new_capacity);
    return 0;
}

int add_element(DynamicArray* da, uint32_t seed) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity && resize_dynamic_array(da, da->capacity == 0 ? 1 : da->capacity * 2) != 0) {
        fprintf(da->log_file, "Failed to allocate memory for new element\n");
        pthread_mutex_unlock(&da->mutex);
        return -1;
    }

    srand(seed + da->size);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &da->array[da->size];
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = (uint16_t)rand();
    pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);
    pdu->CRCFLAG = (uint8_t)(rand() % 2);

    da->size++;
    fprintf(da->log_file, "Added element at index %zu\n", da->size - 1);

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void save_state_to_disk(DynamicArray* da, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(da->log_file, "Failed to open file for saving state\n");
        return;
    }
    fwrite(&da->size, sizeof(size_t), 1, file);
    fwrite(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->size, file);
    fclose(file);
    fprintf(da->log_file, "Saved state to disk at size %zu\n", da->size);
}

void load_state_from_disk(DynamicArray* da, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(da->log_file, "Failed to open file for loading state\n");
        return;
    }
    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);
    if (resize_dynamic_array(da, new_size) != 0) {
