        return;
    }
    fread(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    da->size = new_size;
    fclose(file);
    fprintf(da->log_file, "Loaded state from disk at size %zu\n", da->size);
}

void initialize_array_with_seed(DynamicArray* da, const char* log_filename, uint32_t seed) {
    init_dynamic_array(da, log_filename);

    for (size_t i = 0; i < MAX_ELEMENTS && add_element(da, seed + i) == 0; ++i) {
        // Intentionally left blank
    }
}

