#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_SEQ_NUM 20000
#define HASH_TABLE_SIZE 10007 // A prime number for better distribution

typedef struct {
    uint32_t *seq_num_ptr;
    int key;
} packet;

typedef struct {
    packet *table[HASH_TABLE_SIZE];
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    uint8_t PDCP_SN;      // Placeholder for actual type
    uint8_t RLC_STATUS_REPORT; // Placeholder for actual type
    uint8_t TX_BUFFER_STATE;   // Placeholder for actual type
    uint8_t RX_BUFFER_STATE;   // Placeholder for actual type
    float packet_loss_rate;
    float delay;
    float jitter;
} LAYER2_MESSAGE_T;

uint32_t sequence_numbers[MAX_SEQ_NUM];

// Initialize hash table and lock
HashTable* create_hash_table() {
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    memset(ht->table, 0, sizeof(packet*) * HASH_TABLE_SIZE);
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

// Free hash table
void free_hash_table(HashTable *ht) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        if (ht->table[i]) {
            free(ht->table[i]->seq_num_ptr); // Assuming seq_num_ptr is dynamically allocated
            free(ht->table[i]);
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

// Hash function
unsigned int hash(int key) {
    return (key * 2654435761u) % HASH_TABLE_SIZE;
}

// Insert packet into the hash table
int insert_packet(HashTable *ht, uint32_t *seq_num_ptr, int key) {
    pthread_mutex_lock(&ht->lock);

    unsigned int index = hash(key);
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        unsigned int pos = (index + i) % HASH_TABLE_SIZE;

        if (!ht->table[pos]) {
            packet *pkt = malloc(sizeof(packet));
            if (!pkt) {
                pthread_mutex_unlock(&ht->lock);
                return -1;
            }

            pkt->seq_num_ptr = seq_num_ptr;
            pkt->key = key;
            ht->table[pos] = pkt;
            break;
        } else if (ht->table[pos]->key == key) {
            free(pkt); // Avoid memory leak
            pthread_mutex_unlock(&ht->lock);
            return -2; // Duplicate key
        }
    }

    pthread_mutex_unlock(&ht->lock);
    return 0;
}

// Initialize and populate LAYER2_MESSAGE_T array
void initialize_layer2_messages(LAYER2_MESSAGE_T *messages, size_t num_msgs) {
    for (size_t i = 0; i < num_msgs; ++i) {
        messages[i].PDCP_SN = rand() % 256;
        messages[i].RLC_STATUS_REPORT = rand() % 256;
        messages[i].TX_BUFFER_STATE = rand() % 256;
        messages[i].RX_BUFFER_STATE = rand() % 256;

        // Simulate real-world conditions
        messages[i].packet_loss_rate = (rand() % 100) / 100.0;
        messages[i].delay = (rand() % 100) + 10; // Delay in ms
        messages[i].jitter = (rand() % 50) / 10.0; // Jitter in ms

        // Priority logic can be added here if necessary
    }
}

// Populate sequence numbers
void populate_sequence_numbers() {
    for (uint32_t i = 0; i < MAX_SEQ_NUM; ++i) {
        sequence_numbers[i] = i;
    }
}

int main() {
    initialize_layer2_messages(NULL, 0); // Placeholder for actual message array initialization

    HashTable *ht = create_hash_table();
    if (!ht) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    populate_sequence_numbers();

    int num_packets;
    printf("Enter number of packets: ");
    scanf("%d", &num_packets);

    uint16_t keys[num_packets];

    for (int i = 0; i < num_packets; ++i) {
        printf("Enter key %d: ", i + 1);
        if (scanf("%hu", &keys[i]) != 1 || keys[i] > UINT16_MAX) {
            fprintf(stderr, "Invalid key\n");
            free_hash_table(ht);
            return EXIT_FAILURE;
        }
    }

    // Check for duplicate keys
    for (int i = 0; i < num_packets; ++i) {
        for (int j = i + 1; j < num_packets; ++j) {
            if (keys[i] == keys[j]) {
                fprintf(stderr, "Duplicate key detected\n");
                free_hash_table(ht);
                return EXIT_FAILURE;
            }
        }
    }

    // Populate hash table
    int highest_seq_num = -1;
    for (int i = 0; i < num_packets; ++i) {
        uint32_t *seq_ptr = &sequence_numbers[i]; // Example mapping

        if (insert_packet(ht, seq_ptr, keys[i]) != 0) {
            fprintf(stderr, "Error inserting packet\n");
            free_hash_table(ht);
            return EXIT_FAILURE;
        }

        if (seq_ptr && *seq_ptr > highest_seq_num) {
            highest_seq_num = *seq_ptr;
        }
    }

    printf("Highest sequence number: %u\n", highest_seq_num);

    // Cleanup
    free_hash_table(ht);

    return EXIT_SUCCESS;
}
