        CRC_INDICATION_REL8_TAG crcTag;
        crcTag.CRCFLAG = (unsigned char)(i ^ CRC_XOR_CONSTANT);
    }

    NFAPIArrayManager *manager = (NFAPIArrayManager *)malloc(sizeof(NFAPIArrayManager));
    if (!manager) {
        free(pduArray);
        return NULL;
    }

    manager->nfaPdus = pduArray;
    manager->count = n;

    return manager;
}

typedef struct {
    long *timestamps;
    double *measurements;
    char **identifiers;
    int count;
} SensorManager;

SensorManager* init_sensor_manager(int num_sensors) {
    if (num_sensors <= 0) return NULL;

    SensorManager *manager = (SensorManager *)malloc(sizeof(SensorManager));
    if (!manager) return NULL;

    manager->timestamps = (long *)calloc(num_sensors, sizeof(long));
    manager->measurements = (double *)calloc(num_sensors, sizeof(double));
    manager->identifiers = (char **)malloc(num_sensors * sizeof(char *));
    if (!manager->timestamps || !manager->measurements || !manager->identifiers) {
        free(manager->timestamps);
        free(manager->measurements);
        free(manager->identifiers);
        free(manager);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_sensors; ++i) {
        manager->timestamps[i] = rand() % 100000;

        double min_val = 1.0, max_val = 10.0;
        manager->measurements[i] = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);

        char buffer[16];
        snprintf(buffer, sizeof(buffer), "sensor_%d", i);
        size_t len = strlen(buffer) + 1;

        // Unique identifier allocation
        manager->identifiers[i] = (char *)malloc(len);
        if (!manager->identifiers[i]) {
            for (int j = 0; j < i; ++j) free(manager->identifiers[j]);
            free(manager->timestamps);
            free(manager->measurements);
            free(manager->identifiers);
            free(manager);
            return NULL;
        }

        strcpy(manager->identifiers[i], buffer);
    }

    manager->count = num_sensors;

    return manager;
}

void free_nfa_pdu_array(NFAPIArrayManager *manager) {
    if (manager) {
        free(manager->nfaPdus);
        free(manager);
    }
}

void free_sensor_manager(SensorManager *manager) {
    if (manager) {
        for (int i = 0; i < manager->count; ++i) {
            free(manager->identifiers[i]);
        }
        free(manager->timestamps);
        free(manager->measurements);
        free(manager->identifiers);
        free(manager);
    }
}

// Thread-safe example function using mutexes
#include <pthread.h>

typedef struct {
    SensorManager *manager;
    pthread_mutex_t lock;
} SafeSensorManager;

SafeSensorManager* init_safe_sensor_manager(int num_sensors) {
    SafeSensorManager *safeManager = (SafeSensorManager *)malloc(sizeof(SafeSensorManager));
    if (!safeManager) return NULL;

    safeManager->manager = init_sensor_manager(num_sensors);
    if (!safeManager->manager) {
        free(safeManager);
        return NULL;
    }

    pthread_mutex_init(&safeManager->lock, NULL);

    return safeManager;
}

void resize_safe_sensor_manager(SafeSensorManager *safeManager, int new_size) {
    if (!safeManager) return;

    pthread_mutex_lock(&safeManager->lock);

    // Free old resources
    free_sensor_manager(safeManager->manager);

    // Allocate new resources
    safeManager->manager = init_sensor_manager(new_size);

    pthread_mutex_unlock(&safeManager->lock);
}

void free_safe_sensor_manager(SafeSensorManager *safeManager) {
    if (safeManager) {
        pthread_mutex_destroy(&safeManager->lock);
        free_sensor_manager(safeManager->manager);
        free(safeManager);
    }
}
