['Below is a C implementation for managing a dynamic linked list of `NFAPI_CRC_INDICATION_PDU_T` structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Assuming these structures are defined elsewhere in the codebase.
typedef struct {
    int value;
} RX_UE_INFORMATION_TAG;

typedef unsigned int RNTI;

typedef struct {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} CRC_Indication_List;

// Function to create a new node
NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->ue_info_tag = ue_info;
    new_node->rnti = rnti;
    new_node->crc_ind_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

// Function to check for RNTI uniqueness in the list
bool is_rnti_unique(CRC_Indication_List *list, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) return false;
        current = current->next;
    }
    return true;
}

// Function to add a node to the list
bool add_node(CRC_Indication_List *list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    if (!is_rnti_unique(list, rnti)) {
        printf("Duplicate RNTI detected.\n");
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(ue_info, rnti);
    if (!new_node) return false;

    if (list->head == NULL) { // Empty list
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    return true;
}

// Function to free the entire list
void free_list(CRC_Indication_List *list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_node = current->next;
        free(current);
        current = next_node;
    }
    list->head = NULL;
    list->tail = NULL;
}

// Function to iterate forward
void iterate_forward(CRC_Indication_List *list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        func(current);
        current = current->next;
    }
}

// Function to iterate backward
void iterate_backward(CRC_Indication_List *list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->tail;
    while (current != NULL) {
        func(current);
        current = current->prev;
    }
}

// Example usage
void print_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    printf("RNTI: %u, CRCFLAG: %d\n", node->rnti, node->crc_ind_rel8_tag.CRCFLAG);
}

int main() {
    CRC_Indication_List list = {NULL, NULL};

    // Add nodes
    add_node(&list, (RX_UE_INFORMATION_TAG){.value = 1}, 1001);
    add_node(&list, (RX_UE_INFORMATION_TAG){.value = 2}, 1002);

    // Iterate forward
    iterate_forward(&list, print_node);

    // Iterate backward
    iterate_backward(&list, print_node);

    // Free the list
    free_list(&list);

    return 0;
}
```

This code provides a dynamic linked list with functions to add nodes while ensuring RNTI uniqueness, iterate in both directions, and manage memory efficiently.']

