```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

#define MAX_LATENCY_HISTORY 100

// Define a simple hash table for fast lookups
#define HASH_TABLE_SIZE 1024

typedef struct {
    long offset;
    pthread_mutex_t lock; // Lock for thread safety on individual entries
    record_t *records;
    int count;
} session_t;

session_t *sessions[HASH_TABLE_SIZE];

unsigned long hash(int key) {
    return (unsigned long)key % HASH_TABLE_SIZE;
}

void initialize_sessions() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        sessions[i] = NULL;
    }
}

int add_session(long offset, int key) {
    unsigned long index = hash(key);
    pthread_mutex_lock(&sessions[index]->lock); // Lock the session entry

    session_t *session = (session_t *)malloc(sizeof(session_t));
    if (!session) {
        perror("Failed to allocate memory for session");
        pthread_mutex_unlock(&sessions[index]->lock);
        return -1;
    }

    session->offset = offset;
    session->count = 0;
    session->records = NULL;
    pthread_mutex_init(&session->lock, NULL);

    // Link the new session into the hash table
    session_t *new_node = session;
    new_node->next = sessions[index];
    sessions[index] = new_node;

    pthread_mutex_unlock(&sessions[index]->lock);
    return 0;
}

record_t* add_record(session_t *session, int min_val, int max_val) {
    if (!session || !session->records) {
        perror("Invalid session or records pointer");
        return NULL;
    }

    // Ensure thread safety while updating the record
    pthread_mutex_lock(&session->lock);

    // Resize if necessary
    session->count++;
    session->records = (record_t *)realloc(session->records, session->count * sizeof(record_t));
    if (!session->records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&session->lock);
        return NULL;
    }

    // Generate random value within the specified range
    record_t new_record;
    srand(time(NULL));
    new_record.value = rand() % (max_val - min_val + 1) + min_val;

    session->records[session->count - 1] = new_record;

    pthread_mutex_unlock(&session->lock);
    return &session->records[session->count - 1];
}

void update_latency_data(float *latency_history, float new_latency, int *history_count) {
    if (*history_count < MAX_LATENCY_HISTORY) {
        latency_history[*history_count] = new_latency;
        (*history_count)++;
    } else {
        // Overwrite the oldest data
        for (int i = 1; i < MAX_LATENCY_HISTORY; i++) {
            latency_history[i - 1] = latency_history[i];
        }
        latency_history[MAX_LATENCY_HISTORY - 1] = new_latency;
    }

    float sum = 0.0f;
    for (int i = 0; i < *history_count; i++) {
        sum += latency_history[i];
    }

    printf("Average Latency: %.2f ms\n", sum / (*history_count));
}

// Simulate external service update
void* external_latency_service(void *arg) {
    float latency_history[MAX_LATENCY_HISTORY] = {0};
    int history_count = 0;

    while (1) {
        // Sleep for variable intervals (simulated with a fixed time here)
        sleep(5);

        // Simulate receiving new latency data
        float new_latency = ((float)rand() / RAND_MAX) * 100; // Random latency value

        update_latency_data(latency_history, new_latency, &history_count);
    }

    return NULL;
}

int main() {
    initialize_sessions();

    pthread_t latency_thread;
    if (pthread_create(&latency_thread, NULL, external_latency_service, NULL)) {
        perror("Failed to create thread for external latency service");
        exit(EXIT_FAILURE);
    }

    // Example usage
    long offset = 123456789L;
    int key = 42;

    if (add_session(offset, key) == -1) {
        fprintf(stderr, "Failed to add session\n");
        return EXIT_FAILURE;
    }

    unsigned long index = hash(key);
    pthread_mutex_lock(&sessions[index]->lock);

    session_t *session = sessions[index];
    record_t *record = add_record(session, 10, 100);

    if (record) {
        printf("Record value: %d\n", record->value);
    }

    pthread_mutex_unlock(&sessions[index]->lock);

    // Wait for the latency thread to finish (it won't in this example)
    pthread_join(latency_thread, NULL);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Each session has a mutex lock to prevent race conditions during read/write operations.
- **Dynamic Memory Management**: Sessions and records are dynamically allocated with appropriate checks for allocation failures.
- **Latency Updates**: An external thread simulates periodic latency updates without affecting the main operation flow.
- **Hash Table**: Used for efficient key lookups, minimizing contention in a multi-threaded environment.
- **Integration & Logging**: A basic structure is provided to demonstrate integration with logging frameworks (not fully implemented here).

This code aims to balance performance, memory usage, and maintainability while handling threading issues effectively.']

