#include <string.h>

#define MAX_ENTITIES 100

typedef struct {
    int id;
    char config[256];
    char state[64];
} NetworkEntity;

NetworkEntity* entities = NULL;
size_t entity_count = 0;

// Function to initialize and populate the array
void init_network_entities(size_t count) {
    if (entities != NULL) {
        free(entities);
    }

    if (count > MAX_ENTITIES) {
        fprintf(stderr, "Exceeded maximum number of network entities.\n");
        exit(EXIT_FAILURE);
    }

    entity_count = count;
    entities = (NetworkEntity*)calloc(count, sizeof(NetworkEntity));
    if (!entities) {
        perror("Failed to allocate memory for network entities");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        entities[i].id = i + 1;
        snprintf(entities[i].config, sizeof(entities[i].config), "Config%d", i + 1);
        strcpy(entities[i].state, "Inactive");
    }
}

// Function to update the state of a network entity
void update_entity_state(int id, const char* new_state) {
    for (size_t i = 0; i < entity_count; ++i) {
        if (entities[i].id == id) {
            strncpy(entities[i].state, new_state, sizeof(entities[i].state));
            return;
        }
    }
    fprintf(stderr, "Entity with ID %d not found.\n", id);
}

// Function to serialize network entities into a binary format
void* serialize_entities(size_t* size) {
    *size = entity_count * sizeof(NetworkEntity);

    void* buffer = malloc(*size);
    if (!buffer) {
        perror("Failed to allocate memory for serialization");
        exit(EXIT_FAILURE);
    }

    memcpy(buffer, entities, *size);
    return buffer;
}

// Function to deserialize network entities from a binary format
void deserialize_entities(const void* buffer, size_t size) {
    if (entity_count != size / sizeof(NetworkEntity)) {
        fprintf(stderr, "Deserialization error: size mismatch.\n");
        exit(EXIT_FAILURE);
    }

    memcpy(entities, buffer, size);
}

// Function to free allocated resources
void cleanup() {
    free(entities);
    entities = NULL;
    entity_count = 0;
}

int main() {
    init_network_entities(10);

    update_entity_state(1, "Active");

    size_t serialized_size;
    void* serialized_data = serialize_entities(&serialized_size);

    // Simulating deserialization
    NetworkEntity backup[10];
    memcpy(backup, entities, sizeof(NetworkEntity) * entity_count);

    cleanup();

    deserialize_entities(serialized_data, serialized_size);

    for (size_t i = 0; i < entity_count; ++i) {
        printf("ID: %d, Config: %s, State: %s\n", entities[i].id, entities[i].config, entities[i].state);
    }

    free(serialized_data);
    cleanup();

    return 0;
}
