    return (rand() % 100) + (rand() / (RAND_MAX / 0.5));
}

void calculate_statistics(ChannelState *channel) {
    double total_snr = 0;
    double min = __DBL_MAX__;
    double max = -__DBL_MAX__;
    int count = 0;

    for (int i = 0; i < channel->max_ues; ++i) {
        if (channel->ue_array[i].SNR_INDICATION_REL8_TAG > 0) { // Assuming valid SNR
            total_snr += channel->ue_array[i].SNR_INDICATION_REL8_TAG;
            min = fmin(min, channel->ue_array[i].SNR_INDICATION_REL8_TAG);
            max = fmax(max, channel->ue_array[i].SNR_INDICATION_REL8_TAG);
            count++;
        }
    }

    if (count > 0) {
        channel->avg_snr = total_snr / count;
        channel->min_snr = min;
        channel->max_snr = max;
    } else {
        channel->avg_snr = channel->min_snr = channel->max_snr = 0.0;
    }
}

int initialize_channel(ChannelState *channel, size_t memory_limit) {
    pthread_mutex_init(&channel->lock, NULL);
    channel->max_ues = MAX_UE_OFFSET; // Or set dynamically
    channel->memory_limit = memory_limit;

    if (malloc_size(sizeof(NFAPI_MESSAGE_PDU_T) * channel->max_ues) > channel->memory_limit) {
        perror("Memory limit exceeded");
        return -1;
    }

    channel->ue_array = malloc(sizeof(NFAPI_MESSAGE_PDU_T) * channel->max_uses);
    if (!channel->ue_array) {
        perror("Failed to allocate memory for UE array");
        pthread_mutex_destroy(&channel->lock);
        return -1;
    }

    memset(channel->ue_array, 0, sizeof(NFAPI_MESSAGE_PDU_T) * channel->max_ues);
    channel->update_snr = simulate_snr_update;

    return 0;
}

void update_ue_snr(ChannelState *channel) {
    pthread_mutex_lock(&channel->lock);

    for (int i = 0; i < channel->max_ues; ++i) {
        if (channel->ue_array[i].SNR_INDICATION_REL8_TAG > 0) { // Assuming valid SNR
            channel->ue_array[i].SNR_INDICATION_REL8_TAG = channel->update_snr();
        }
    }

    calculate_statistics(channel);
    pthread_mutex_unlock(&channel->lock);
}

void cleanup_channel(ChannelState *channel) {
    if (channel->ue_array) {
        free(channel->ue_array);
    }
    pthread_mutex_destroy(&channel->lock);
}

SharedResources* initialize_shared_resources(int num_offsets, int num_keys) {
    if (num_offsets < 10 || num_offsets > MAX_UE_OFFSET ||
        num_keys < 10 || num_keys > MAX_UE_OFFSET) {
        perror("Invalid number of offsets or keys");
        return NULL;
    }

    SharedResources *resources = malloc(sizeof(SharedResources));
    if (!resources) {
        perror("Failed to allocate memory for shared resources");
        return NULL;
    }

    resources->offset_values = malloc(sizeof(long) * num_offsets);
    resources->keys = malloc(sizeof(int) * num_keys);

    if (!resources->offset_values || !resources->keys) {
        perror("Memory allocation failed for shared resources");
        free(resources->offset_values);
        free(resources->keys);
        free(resources);
        return NULL;
    }

    srand(time(NULL));
    int used_numbers = 0;

    resources->record_count = num_offsets; // Assuming equal to num_offsets for simplicity
    resources->records = malloc(sizeof(Record *) * resources->record_count);

    if (!resources->records) {
        perror("Memory allocation failed for records");
        free(resources->offset_values);
        free(resources->keys);
        free(resources);
        return NULL;
    }

    int max_val = 1000; // Example range
    while (used_numbers < resources->record_count) {
        int rand_num = rand() % max_val;
        int duplicate = 1;

        for (int i = 0; i < used_numbers && duplicate; ++i) {
            if (resources->records[i]->unique_value == rand_num) {
                duplicate = 0;
            }
        }

        if (duplicate) {
            resources->records[used_numbers] = malloc(sizeof(Record));
            resources->records[used_numbers]->unique_value = rand_num;
            used_numbers++;
        }
    }

    return resources;
}

void cleanup_shared_resources(SharedResources *resources) {
    if (!resources) return;

    for (int i = 0; i < resources->record_count; ++i) {
        free(resources->records[i]);
    }

    free(resources->records);
    free(resources->offset_values);
    free(resources->keys);
    free(resources);
}

// Example logging function
void log_memory_usage(size_t used_memory, size_t limit) {
    printf("Memory Usage: %zu/%zu\n", used_memory, limit);
}
