#include <time.h>

#define MAX_INPUT_SIZE 10000
#define VALUE_RANGE_MIN 1
#define VALUE_RANGE_MAX 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int is_valid_input(int *values, int count) {
    if (count > MAX_INPUT_SIZE) return 0;

    for (int i = 0; i < count; ++i) {
        if (values[i] < VALUE_RANGE_MIN || values[i] > VALUE_RANGE_MAX)
            return 0;

        for (int j = i + 1; j < count; ++j) {
            if (values[i] == values[j])
                return 0;
        }
    }

    return 1;
}

void serialize_and_write(const NFAPI_CRC_INDICATION_PDU_T *data, int size, const char *filename) {
    FILE *file = NULL;
    uint8_t retry_count = 0;

    while (retry_count < 3) {
        file = fopen(filename, "wb");
        if (!file)
            return;

        if (fwrite(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file) == size) {
            fclose(file);
            break;
        }

        fclose(file);
        retry_count++;
        srand(time(NULL));
        sleep(rand() % 5); // Random delay between retries
    }
}

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int main() {
    int input_size;
    scanf("%d", &input_size);

    int *values = malloc(input_size * sizeof(int));
    if (!values) {
        log_error("Memory allocation failed for input values");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < input_size; ++i) {
        scanf("%d", &values[i]);
    }

    if (!is_valid_input(values, input_size)) {
        free(values);
        printf("Invalid input: duplicates found or out of range values\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = malloc(input_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        log_error("Memory allocation failed for data structures");
        free(values);
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    int max_value = 0;

    for (int i = 0; i < input_size; ++i) {
        data[i].RX_UE_INFORMATION_TAG = values[i];
        data[i].RNTI = (values[i] * 2) % 65536;
        data[i].CRC_INDICATION_REL8_TAG = (values[i] / 10) % 256;
        data[i].CRCFLAG = rand() % 2;

        if (values[i] > max_value)
            max_value = values[i];
    }

    printf("Largest integer: %d\n", max_value);

    serialize_and_write(data, input_size, "crc_indications.bin");

    free(values);
    free(data);

    return EXIT_SUCCESS;
}
