#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define MAX_THREADS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_t thread_id;
    int active;
} ThreadPoolThread;

ThreadPoolThread thread_pool[MAX_THREADS];
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_cv = PTHREAD_COND_INITIALIZER;

int get_max_threads_from_env() {
    char *env_var = getenv("MAX_CONCURRENT_THREADS");
    if (env_var) {
        return atoi(env_var);
    }
    return MAX_THREADS;
}

void* execute_command(void* arg) {
    int* command_success = (int*)arg;
    // Simulate command execution
    sleep(1); // Replace with actual command execution logic
    *command_success = rand() % 2; // Random success or failure
    return NULL;
}

void initialize_thread_pool(int max_threads) {
    for (int i = 0; i < max_threads; ++i) {
        thread_pool[i].active = 0;
        pthread_create(&thread_pool[i].thread_id, NULL, execute_command, &thread_pool[i]);
    }
}

int acquire_thread_from_pool() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < get_max_threads_from_env(); ++i) {
        if (!thread_pool[i].active) {
            thread_pool[i].active = 1;
            pthread_mutex_unlock(&pool_mutex);
            return i;
        }
    }
    pthread_cond_wait(&pool_cv, &pool_mutex);
    for (int i = 0; i < get_max_threads_from_env(); ++i) {
        if (!thread_pool[i].active) {
            thread_pool[i].active = 1;
            pthread_mutex_unlock(&pool_mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return -1;
}

void release_thread_to_pool(int index) {
    pthread_mutex_lock(&pool_mutex);
    thread_pool[index].active = 0;
    pthread_cond_signal(&pool_cv);
    pthread_mutex_unlock(&pool_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* generateNfaReports() {
    int max_threads = get_max_threads_from_env();
    initialize_thread_pool(max_threads);

    // Simulate fetching data from an external source
    const int dataset_size = 100; // Replace with actual size
    NFAPI_CRC_INDICATION_PDU_T* reports = malloc(dataset_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!reports) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < dataset_size; ++i) {
        int command_index = acquire_thread_from_pool();
        if (command_index == -1) {
            fprintf(stderr, "Failed to acquire thread from pool\n");
            free(reports);
            return NULL;
        }

        int command_success;
        pthread_create(NULL, NULL, execute_command, &command_success);

        // Simulate data assignment
        reports[i].RX_UE_INFORMATION_TAG = rand(); // Replace with actual data
        reports[i].RNTI = rand(); // Replace with actual data

        if (command_success) {
            reports[i].CRC_INDICATION_REL8_TAG = 1; // Set CRCFLAG based on command success
        } else {
            reports[i].CRC_INDICATION_REL8_TAG = 0;
        }

        release_thread_to_pool(command_index);
    }

    return reports;
}

void cleanup() {
    for (int i = 0; i < get_max_threads_from_env(); ++i) {
        pthread_cancel(thread_pool[i].thread_id);
        pthread_join(thread_pool[i].thread_id, NULL);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* reports = generateNfaReports();
    if (reports) {
        // Process reports
        free(reports);
    }
    cleanup();
    return 0;
}
