void init_list(NFAPI_CRC_LIST *list) {
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(NFAPI_CRC_LIST *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

void resize_list(NFAPI_CRC_LIST *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_pdu(NFAPI_CRC_LIST *list, uint32_t RNTI, int rx_ue_information_tag, uint8_t CRCFLAG) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resize_list(list);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {RNTI, rx_ue_information_tag};
    ((CRC_INDICATION_REL8_TAG *)(&pdu + 1))->CRCFLAG = CRCFLAG;

    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
}

void iterate_list(NFAPI_CRC_LIST *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        callback(&(list->data[i]));
    }

    pthread_mutex_unlock(&list->lock);
}

uint32_t crc32(const void *data, size_t n_bytes) {
    uint32_t crc = ~0u;
    const uint8_t *byte_data = (const uint8_t *)data;

    for (size_t i = 0; i < n_bytes; ++i) {
        crc ^= byte_data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ ((crc & 1) ? 0xEDB88320 : 0);
        }
    }

    return ~crc;
}

int validate_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    CRC_INDICATION_REL8_TAG *tag = (CRC_INDICATION_REL8_TAG *)(&pdu + 1);
    uint32_t calculated_crc = crc32(pdu, sizeof(*pdu));
    return tag->CRCFLAG == ((calculated_crc & 0x01) != 0); // Example validation
}

void populate_list(NFAPI_CRC_LIST *list, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        uint32_t RNTI = rand() % 100000;
        int rx_ue_information_tag = rand(); // Placeholder for actual tag generation
        uint8_t CRCFLAG = rand() & 1;

        add_pdu(list, RNTI, rx_ue_information_tag, CRCFLAG);
    }
}

int main() {
    NFAPI_CRC_LIST list;
    init_list(&list);

    size_t num_elements = 10000; // Example number of elements
    populate_list(&list, num_elements);

    iterate_list(&list, [](NFAPI_CRC_INDICATION_PDU_T *pdu) {
        if (!validate_crc(pdu)) {
            printf("CRC validation failed for RNTI: %u\n", pdu->RNTI);
        }
    });

    free_list(&list);
    return 0;
}
