// Define constants for simulation purposes
#define MAX_UE_COUNT 1000
#define INITIAL_ALLOC_SIZE 10

typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    float snr_value;
} SNR_INDICATION_REL8_TAG;

typedef struct {
    uint32_t crc_indication_rel8_tag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    SNR_INDICATION_REL8_TAG snr_indication_rel8;
} NFAPI_MESSAGE_PDU_T;

// Dynamic list structure
typedef struct {
    NFAPI_MESSAGE_PDU_T* ues;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UE_Session_List;

// Function prototypes
UE_Session_List* initialize_ue_session_list();
void destroy_ue_session_list(UE_Session_List* list);
int add_ue_to_list(UE_Session_List* list, uint16_t ue_id);
NFAPI_MESSAGE_PDU_T* get_ue_from_list(const UE_Session_List* list, uint16_t ue_id);
float simulate_snr_value(); // Simulate SNR based on a radio channel model

// Initialize the dynamic list
UE_Session_List* initialize_ue_session_list() {
    UE_Session_List* list = (UE_Session_List*)malloc(sizeof(UE_Session_List));
    if (!list) return NULL;

    list->ues = (NFAPI_MESSAGE_PDU_T*)malloc(INITIAL_ALLOC_SIZE * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!list->ues) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = INITIAL_ALLOC_SIZE;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Destroy the dynamic list
void destroy_ue_session_list(UE_Session_List* list) {
    if (list) {
        free(list->ues);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Add a new UE to the list
int add_ue_to_list(UE_Session_List* list, uint16_t ue_id) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_MESSAGE_PDU_T* new_ues = realloc(list->ues, new_capacity * sizeof(NFAPI_MESSAGE_PDU_T));
        if (!new_ues) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->ues = new_ues;
        list->capacity = new_capacity;
    }

    NFAPI_MESSAGE_PDU_T* ue = &list->ues[list->count++];
    ue->rx_ue_information.rx_ue_information_tag = ue_id;
    ue->rnti = rand(); // Simulate RNTI
    ue->crc_indication_rel8.crc_indication_rel8_tag = rand(); // Simulate CRC tag
    ue->snr_indication_rel8.snr_value = simulate_snr_value();

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Retrieve a UE from the list by ID
NFAPI_MESSAGE_PDU_T* get_ue_from_list(const UE_Session_List* list, uint16_t ue_id) {
    if (!list) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->ues[i].rx_ue_information.rx_ue_information_tag == ue_id) {
            NFAPI_MESSAGE_PDU_T* result = &list->ues[i];
            pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
            return result;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return NULL;
}

// Simulate SNR value calculation
float simulate_snr_value() {
    // Simple simulation of SNR, normally would use more complex models
    float noise_factor = (rand() % 100) / 10.0f;
    float signal_strength = (rand() % 100) + 50.0f; // Arbitrary signal strength
    return signal_strength - noise_factor;
}

// Example usage of the list management functions
int main() {
    UE_Session_List* ue_list = initialize_ue_session_list();
    if (!ue_list) {
        fprintf(stderr, "Failed to initialize UE session list\n");
        return EXIT_FAILURE;
    }

    for (uint16_t i = 0; i < MAX_UE_COUNT; ++i) {
        if (add_ue_to_list(ue_list, i) != 0) {
            fprintf(stderr, "Failed to add UE with ID %d\n", i);
            break;
        }
    }

    // Example of retrieving a UE
    NFAPI_MESSAGE_PDU_T* ue = get_ue_from_list(ue_list, 5);
    if (ue) {
        printf("UE with ID 5: SNR = %.2f\n", ue->snr_indication_rel8.snr_value);
    }

    destroy_ue_session_list(ue_list);
    return EXIT_SUCCESS;
}
```

This code provides a dynamic list to manage `NFAPI_MESSAGE_PDU_T` structures, simulating real-world conditions and ensuring efficient memory management and thread safety. The `simulate_snr_value()` function is a placeholder for more complex radio channel models.']

