#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

#define MAX_LOG_MESSAGES 1000

typedef struct {
    int rx_ue_info_tag;
    unsigned long rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct log_entry {
    time_t timestamp;
    char *message;
} log_entry_t;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void *ptr) {
    free(ptr);
}

void log_message(log_entry_t **log_entries, int level, const char *format, ...) {
    pthread_mutex_lock(&log_mutex);

    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);

    log_entry_t *entry = allocate_memory(sizeof(log_entry_t));
    entry->timestamp = now;

    size_t msg_len = strlen(buffer) + 1;
    entry->message = allocate_memory(msg_len);
    strncpy(entry->message, buffer, msg_len);

    va_end(args);

    pthread_mutex_unlock(&log_mutex);

    log_entries[*log_entries ? *log_entries : NULL] = entry;
}

void setup_logging() {
    // Example of adding a digest algorithm
    if (!EVP_add_digest(EVP_sha256())) {
        fprintf(stderr, "Failed to add SHA-256\n");
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = allocate_memory(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    log_entry_t *log_entries[MAX_LOG_MESSAGES] = {NULL};

    for (int i = 0; i < n; ++i) {
        pdus[i].rx_ue_info_tag = rand() % 100;
        pdus[i].rnti = rand();
        pdus[i].crcflag = rand() & 1;

        log_message(log_entries, INFO, "Created PDU with RX_UE_INFORMATION_TAG: %d, RNTI: %lu, CRCFLAG: %u",
                    pdus[i].rx_ue_info_tag, pdus[i].rnti, pdus[i].crcflag);
    }

    // Cleanup logs
    for (int i = 0; log_entries[i]; ++i) {
        free_memory(log_entries[i]->message);
        free_memory(log_entries[i]);
    }

    return pdus;
}

void cleanup_nfa_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus, int n) {
    if (pdus) {
        free_memory(pdus);
    }
}

int main() {
    srand(time(NULL));

    setup_logging();

    int n = 10; // Number of PDUs to create
    NFAPI_CRC_INDICATION_PDU_T *pdus = create_nfa_crc_pdu(n);

    cleanup_nfa_crc_pdu(pdus, n);

    return 0;
}
```

### Key Points:
- **Memory Management**: Uses `malloc` and custom functions for allocation and deallocation.
- **Concurrency Safety**: Utilizes a mutex (`pthread_mutex_t`) to protect shared resources.
- **Logging**: A simple logging mechanism is implemented with timestamps and log levels.
- **OpenSSL Integration**: Demonstrates adding a digest algorithm using OpenSSL's EVP library.
- **Error Handling**: Logs errors on memory allocation failure and exits the program.

### Notes:
- Ensure you link against OpenSSL (`-lssl -lcrypto`) during compilation.
- This implementation is simplified for demonstration purposes. In production, consider more sophisticated logging, error handling, and configuration management.']

