// C Function: processDatabaseOperations

#include <stdio.h>
#include <stdlib.h>
#include <libpq-fe.h>

#define MAX_QUERIES_PER_SECOND 100

void handle_db_error(PGconn *conn) {
    fprintf(stderr, "Connection to database failed: %s", PQerrorMessage(conn));
    PQfinish(conn);
    exit(1);
}

PGresult* execute_query_batch(PGconn *conn, const char **queries, int num_queries) {
    PGresult *res = NULL;
    for (int i = 0; i < num_queries; i++) {
        res = PQexecPrepared(conn, "prepared_statement", 1,
                             &queries[i], NULL, NULL, 0);
        if (PQstatus(res) != PGRES_TUPLES_OK && PQresultStatus(res) != PGRES_COMMAND_OK) {
            fprintf(stderr, "Query execution failed: %s\n", PQerrorMessage(conn));
            PQclear(res);
            break;
        }
        PQclear(res);
    }
    return res;
}

void processDatabaseOperations(const char **queries, int num_queries) {
    if (!queries || num_queries <= 0) return;

    PGconn *conn = PQconnectdb("user=username dbname=mydb hostaddr=127.0.0.1 port=5432");
    if (PQstatus(conn) != CONNECTION_OK) handle_db_error(conn);

    int queries_per_batch = MAX_QUERIES_PER_SECOND;
    for (int i = 0; i < num_queries; i += queries_per_batch) {
        int batch_size = (i + queries_per_batch > num_queries) ? num_queries - i : queries_per_batch;

        // Execute each batch of queries
        execute_query_batch(conn, &queries[i], batch_size);

        // Sleep to maintain the 100 QPS rate limit
        usleep(10000000 / MAX_QUERIES_PER_SECOND);
    }

    PQfinish(conn);
}

