        fgets(strings[i], sizeof(strings[i]), stdin);
        strings[i][strcspn(strings[i], "\n")] = '\0'; // Remove newline character
    }
}

char** allocate_and_read_strings(size_t *size, int max_size) {
    printf("Enter number of strings (max %d): ", max_size);
    if (scanf("%zu", size) != 1 || (*size > max_size)) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    char **strings = malloc(*size * sizeof(char*));
    if (!strings) {
        perror("Failed to allocate memory for strings array");
        return NULL;
    }

    for (size_t i = 0; i < *size; ++i) {
        strings[i] = malloc(256); // Arbitrary size limit per string
        if (!strings[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            while (--i >= 0) free(strings[i]);
            free(strings);
            return NULL;
        }
    }

    read_strings_and_find_max_length(strings, *size);
    return strings;
}

void print_longest_string(char **strings, size_t size) {
    if (size == 0) {
        printf("No strings to process\n");
        return;
    }

    size_t max_index = 0;
    for (size_t i = 1; i < size; ++i) {
        if (strlen(strings[i]) > strlen(strings[max_index])) {
            max_index = i;
        }
    }
    printf("Longest string: %s\n", strings[max_index]);
}

void free_strings(char **strings, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(strings[i]);
    }
    free(strings);
}

