#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
    long offset;
    int key;
} Record;

// Error codes
#define SUCCESS 0
#define ALLOCATION_FAILURE -1

// Function to dynamically manage memory for three interdependent data structures
int manage_memory(long num_offsets, int num_keys, int key_range) {
    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for Offset Array using a hash table for collision resolution
    long *offsets = (long *)calloc(num_offsets, sizeof(long));
    if (!offsets) return ALLOCATION_FAILURE;

    // Hash function and size for offsets
    unsigned int hash_size = num_offsets * 2;
    int *hash_table = (int *)calloc(hash_size, sizeof(int));
    if (!hash_table) {
        free(offsets);
        return ALLOCATION_FAILURE;
    }

    // Populate the offset array ensuring uniqueness using a simple linear probing hash table
    for (long i = 0; i < num_offsets;) {
        long new_offset = rand() % num_offsets;
        unsigned int index = new_offset % hash_size;

        while (hash_table[index] != -1 && hash_table[index] != new_offset) {
            index = (index + 1) % hash_size;
        }

        if (hash_table[index] == -1) {
            offsets[i++] = new_offset;
            hash_table[index] = new_offset;
        }
    }

    // Allocate memory for Key Array and ensure uniqueness within a specified range
    int *keys = (int *)calloc(num_keys, sizeof(int));
    if (!keys) {
        free(offsets);
        free(hash_table);
        return ALLOCATION_FAILURE;
    }

    int used_keys[key_range];
    memset(used_keys, -1, sizeof(used_keys));

    for (int i = 0; i < num_keys;) {
        int new_key = rand() % key_range;

        if (used_keys[new_key] == -1) {
            keys[i++] = new_key;
            used_keys[new_key] = new_key;
        }
    }

    // Allocate memory for Record Structures
    Record *records = (Record *)malloc(num_offsets * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        free(hash_table);
        return ALLOCATION_FAILURE;
    }

    // Populate record structures with random values and references to offset and key
    for (long i = 0; i < num_offsets; ++i) {
        records[i].value = rand() % key_range;
        records[i].offset = offsets[i];

        // Map each offset to a key, ensuring the mapping is within bounds of keys array
        int index = i % num_keys;
        records[i].key = keys[index];
    }

    printf("Memory management completed successfully.\n");

    // Cleanup (for demonstration purposes; in real usage, you might keep these for further operations)
    free(offsets);
    free(keys);
    free(hash_table);
    free(records);

    return SUCCESS;
}

int main() {
    int result = manage_memory(1000, 500, 2000); // Example usage
    if (result == ALLOCATION_FAILURE) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
