import java.io.IOException;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

public class NFVIndicatorManager {

    private static final Logger logger = Logger.getLogger(NFVIndicatorManager.class.getName());
    private static final String JSON_CONFIG_PATH = "config.json";
    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static void main(String[] args) {
        Executors.newFixedThreadPool(10).submit(() -> {
            try {
                List<NFVIndicator> indicators = loadIndicatorsFromJSON(JSON_CONFIG_PATH);

                String directoryPathToDelete = "target_directory";
                deleteDirectoryIfExists(directoryPathToDelete);

            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error processing JSON or deleting directory", e);
            }
        });
    }

    private static List<NFVIndicator> loadIndicatorsFromJSON(String jsonFilePath) throws IOException {
        JsonNode rootNode = objectMapper.readTree(new File(jsonFilePath));

        if (!rootNode.isArray()) {
            throw new IllegalArgumentException("Root element is not an array");
        }

        List<NFVIndicator> indicators = List.of(rootNode.elements()).stream()
                .map(node -> validateAndCreateNFVIndicator(node))
                .collect(Collectors.toList());

        return indicators;
    }

    private static NFVIndicator validateAndCreateNFVIndicator(JsonNode node) throws IOException {
        if (!node.isObject()) {
            throw new JsonProcessingException("Invalid JSON object") {};
        }

        ObjectNode indicatorNode = (ObjectNode) node;
        String rxUeInfo = indicatorNode.path("rx_UE_info").asText();
        String rnti = indicatorNode.path("rnti").asText();
        boolean crcIndication = indicatorNode.path("crc_indication").asBoolean();

        // Schema validation rules
        if (rxUeInfo == null || rxUeInfo.isEmpty()) {
            throw new JsonProcessingException("RX UE info is missing or empty") {};
        }

        if (rnti == null || rnti.isEmpty()) {
            throw new JsonProcessingException("RNTI is missing or empty") {};
        }

        return new NFVIndicator(rxUeInfo, rnti, crcIndication);
    }

    private static void deleteDirectoryIfExists(String directoryPath) throws IOException {
        Path path = Paths.get(directoryPath);

        if (Files.exists(path)) {
            try {
                Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
                    @Override
                    public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                        Files.delete(file);
                        return FileVisitResult.CONTINUE;
                    }

                    @Override
                    public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
                        Files.delete(dir);
                        return FileVisitResult.CONTINUE;
                    }
                });
            } catch (IOException e) {
                logger.log(Level.WARNING, "Error deleting directory: " + directoryPath, e);
            }
        }
    }

    static class NFVIndicator {
        private final String rxUeInfo;
        private final String rnti;
        private final boolean crcIndication;

        public NFVIndicator(String rxUeInfo, String rnti, boolean crcIndication) {
            this.rxUeInfo = rxUeInfo;
            this.rnti = rnti;
            this.crcIndication = crcIndication;
        }
    }
}
