#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // Assuming a single character for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    pthread_mutex_t lock;
} List;

List list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int isRNTIUnique(int rnti) {
    pthread_mutex_lock(&list.lock);
    Node* current = list.head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list.lock);
            return 0; // RNTI is not unique
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list.lock);
    return 1; // RNTI is unique
}

int addEntry(NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list.size >= MAX_ENTRIES || !isRNTIUnique(entry.RNTI)) {
        return -1; // Cannot add entry
    }

    pthread_mutex_lock(&list.lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list.lock);
        return -1; // Memory allocation failed
    }

    newNode->data = entry;
    newNode->next = list.head;
    list.head = newNode;
    list.size++;

    pthread_mutex_unlock(&list.lock);

    logMemoryUsage(); // Custom logging function

    return 0; // Success
}

void removeEntry(int rnti) {
    pthread_mutex_lock(&list.lock);

    Node *current = list.head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list.lock);
        return; // Entry not found
    }

    if (prev == NULL) {
        list.head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list.size--;

    pthread_mutex_unlock(&list.lock);

    logMemoryUsage(); // Custom logging function
}

void serializeList(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);

    fclose(file);
}

void deserializeList(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&list.lock);

    NFAPI_CRC_INDICATION_PDU_T entry;
    while (fread(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        addEntry(entry);
    }

    pthread_mutex_unlock(&list.lock);

    fclose(file);
}

void logMemoryUsage() {
    // Placeholder for memory logging logic
    printf("Current list size: %d\n", list.size);
}

void generateRandomEntries(int numEntries) {
    srand(time(NULL));
    for (int i = 0; i < numEntries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        entry.RX_UE_INFORMATION_TAG = rand() % 10000;
        entry.RNTI = rand() % 65536;
        entry.CRC_INDICATION_REL8_TAG = rand() % 256;
        entry.CRCFLAG = (rand() % 2) ? '1' : '0';

        addEntry(entry);
    }
}

int main() {
    generateRandomEntries(500); // Example usage
    serializeList("list.dat");
    deserializeList("list.dat");

    return 0;
}
