#define MAX_CONFIG_SIZE 256

typedef struct {
    char key[MAX_CONFIG_SIZE];
    int value;
} ConfigEntry;

typedef struct {
    unsigned long timestamp;
    int event_type;
    char *description;
} EventLogEntry;

typedef struct {
    int thread_id;
    _Bool ready;
} ThreadState;

typedef struct SystemComponents {
    ConfigEntry *config;
    int *metrics;
    EventLogEntry *event;
    ThreadState *thread_state;
    float *resource_usage;
    size_t config_size;
    size_t metrics_size;
    size_t event_size;
    size_t thread_state_size;
    size_t resource_usage_size;
} SystemComponents;

SystemComponents* initialize_system_components(size_t config_size, size_t metrics_size,
                                               char *error_buffer) {
    // Calculate sizes based on constraints
    if (metrics_size != 0 && (metrics_size > 1000 || config_size > 1000 ||
                              config_size + metrics_size + 2 * config_size +
                              metrics_size + 1 > 1000)) {
        strcpy(error_buffer, "Invalid configuration sizes.");
        return NULL;
    }

    size_t event_size = 2 * config_size;
    size_t thread_state_size = metrics_size;

    // Total elements
    size_t total_elements = config_size + metrics_size + event_size +
                            thread_state_size + 1;

    if (total_elements > 1000) {
        strcpy(error_buffer, "Total number of components exceeds limit.");
        return NULL;
    }

    SystemComponents *components = malloc(sizeof(SystemComponents));
    if (!components) {
        strcpy(error_buffer, "Memory allocation for system components failed.");
        return NULL;
    }

    components->config_size = config_size;
    components->metrics_size = metrics_size;
    components->event_size = event_size;
    components->thread_state_size = thread_state_size;
    components->resource_usage_size = 1; // Single resource usage indicator

    components->config = malloc(config_size * sizeof(ConfigEntry));
    if (!components->config) {
        free(components);
        strcpy(error_buffer, "Memory allocation for config failed.");
        return NULL;
    }

    components->metrics = malloc(metrics_size * sizeof(int));
    if (!components->metrics) {
        free(components->config);
        free(components);
        strcpy(error_buffer, "Memory allocation for metrics failed.");
        return NULL;
    }

    components->event = malloc(event_size * sizeof(EventLogEntry));
    if (!components->event) {
        free(components->metrics);
        free(components->config);
        free(components);
        strcpy(error_buffer, "Memory allocation for event logs failed.");
        return NULL;
    }

    for (size_t i = 0; i < event_size; ++i) {
        components->event[i].description = malloc(MAX_CONFIG_SIZE); // Allocate memory for the description
        if (!components->event[i].description) {
            for (size_t j = 0; j < i; ++j) free(components->event[j].description);
            free(components->event);
            free(components->metrics);
            free(components->config);
            free(components);
            strcpy(error_buffer, "Memory allocation for event descriptions failed.");
            return NULL;
        }
    }

    components->thread_state = malloc(thread_state_size * sizeof(ThreadState));
    if (!components->thread_state) {
        for (size_t i = 0; i < event_size; ++i) free(components->event[i].description);
        free(components->event);
        free(components->metrics);
        free(components->config);
        free(components);
        strcpy(error_buffer, "Memory allocation for thread states failed.");
        return NULL;
    }

    components->resource_usage = malloc(components->resource_usage_size * sizeof(float));
    if (!components->resource_usage) {
        free(components->thread_state);
        for (size_t i = 0; i < event_size; ++i) free(components->event[i].description);
        free(components->event);
        free(components->metrics);
        free(components->config);
        free(components);
        strcpy(error_buffer, "Memory allocation for resource usage failed.");
        return NULL;
    }

    // Initialize components with default values
    memset(components->config, 0, config_size * sizeof(ConfigEntry));
    memset(components->metrics, 0, metrics_size * sizeof(int));
    for (size_t i = 0; i < event_size; ++i) {
        components->event[i].timestamp = 0;
        components->event[i].event_type = 0;
        strcpy(components->event[i].description, "");
    }
    memset(components->thread_state, 0, thread_state_size * sizeof(ThreadState));
    memset(components->resource_usage, 0, components->resource_usage_size * sizeof(float));

    return components;
}

void free_system_components(SystemComponents *components) {
    if (components) {
        for (size_t i = 0; i < components->event_size; ++i) {
            free(components->event[i].description);
        }
        free(components->event);
        free(components->thread_state);
        free(components->resource_usage);
        free(components->metrics);
        free(components->config);
        free(components);
    }
}
