#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

#define MAX_ELEMENTS 10000

// Global variables for managing the list and thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int count = 0;
unsigned char pool[MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T)];

// Function to initialize a node using pool memory
Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* node = (Node*)(pool + (count++ * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    if (node == NULL || count >= MAX_ELEMENTS) return NULL;
    memcpy(&node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->next = NULL;
    return node;
}

// Function to calculate checksum
unsigned char calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    unsigned char checksum = 0;
    const unsigned char* bytes = (const unsigned char*)pdu;
    for (int i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        checksum ^= bytes[i];
    }
    return checksum;
}

// Function to add a new node
void add_node(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lock);

    if (count >= MAX_ELEMENTS) {
        printf("List is full.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node* newNode = create_node(pdu);
    if (!newNode) {
        printf("Failed to allocate memory for new node.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    unsigned char expectedCrcFlag = calculate_checksum(&newNode->data);

    if (newNode->data.CRCFLAG == expectedCrcFlag) {
        newNode->next = head;
        head = newNode;
    } else {
        printf("CRC flag integrity check failed.\n");
        free(newNode); // Release the memory
    }

    pthread_mutex_unlock(&lock);
}

// Function to serialize the list to a file
void serialize_list(const char* filename) {
    pthread_mutex_lock(&lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

// Function to deserialize the list from a file
void deserialize_list(const char* filename) {
    pthread_mutex_lock(&lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Failed to open file for reading.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    while (fread(&((NFAPI_CRC_INDICATION_PDU_T){0}), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_node(&((NFAPI_CRC_INDICATION_PDU_T){0}));
    }

    fclose(file);
    pthread_mutex_unlock(&lock);
}

// Function to free the list
void free_list() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        // No need to explicitly free as we are using pool allocation.
    }

    head = NULL;
    count = 0;

    pthread_mutex_unlock(&lock);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, calculate_checksum(&pdu)};
    add_node(&pdu);

    serialize_list("list.bin");
    free_list();

    deserialize_list("list.bin");

    free_list();
    return 0;
}
