        : rng_(std::random_device{}()), min_value_(min_val), max_value_(max_val),
          max_records_(max_rec), gc_interval_ms_(gc_interval) {
        startGarbageCollector();
    }

    ~DynamicDataHandler() {
        stopGarbageCollector();
        for (auto& thread : gc_threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    bool addRecord(long offset, int key, double value) {
        std::unique_lock lock(mutex_);
        if (data_records_.size() >= max_records_ || offset <= 0 || data_records_.count(offset)) {
            return false;
        }
        data_records_[offset] = Record(offset, key, value);
        return true;
    }

    bool updateRecord(long offset, double newValue) {
        std::unique_lock lock(mutex_);
        auto it = data_records_.find(offset);
        if (it == data_records_.end()) {
            return false;
        }
        it->second.value = newValue;
        return true;
    }

    Record* getRecord(long offset) {
        std::shared_lock lock(mutex_);
        auto it = data_records_.find(offset);
        return it != data_records_.end() ? &it->second : nullptr;
    }

    void generateRandomValue(double& out_value) const {
        std::uniform_real_distribution<double> dist(min_value_, max_value_);
        out_value = dist(rng_);
    }

private:
    void startGarbageCollector() {
        gc_threads_.emplace_back([this]() {
            while (!stop_gc_) {
                std::this_thread::sleep_for(std::chrono::milliseconds(gc_interval_ms_));
                // Simplified garbage collection logic
                std::unique_lock lock(mutex_);
                if (data_records_.size() < max_records_ / 2) {
                    // Placeholder for actual memory reclamation logic
                }
            }
        });
    }

    void stopGarbageCollector() {
        stop_gc_ = true;
    }

    // Error handling, logging, and configuration loading are omitted for brevity
};

