    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;

    srand(time(NULL));
    new_node->crc_tag.RX_UE_INFORMATION_TAG = rand();
    new_node->crc_tag.RNTI = rand();
    new_node->crc_tag.CRCFLAG = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void delete_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void traverse_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->crc_tag.RX_UE_INFORMATION_TAG,
               current->crc_tag.RNTI,
               current->crc_tag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void delete_file(const char* filename) {
    char command[256];
    snprintf(command, sizeof(command), "java -cp . DeleteFile %s", filename);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        perror("Failed to run command");
        return;
    }

    char path[1035];
    while (fgets(path, sizeof(path), fp) != NULL)
        printf("%s", path);

    pclose(fp);
}

int main() {
    LinkedList* list = create_list();

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize pdu fields as needed
        insert_node(list, pdu);
    }

    traverse_list(list);

    delete_list(list);

    delete_file("testfile.txt");

    return 0;
}
