#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_LINKED_LIST_SIZE 10000
#define MAX_ARRAY_SIZE 1500

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node* head = NULL;
NFAPI_CRC_INDICATION_PDU_T* array[MAX_ARRAY_SIZE];
size_t array_count = 0;

void initialize_random() {
    srand(time(NULL));
}

int validate_crc_flag(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Replace with actual checksum validation logic
    return (pdu.CRC_INDICATION_REL8_TAG.CRCFLAG % 2 == 0);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_entry_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    if (validate_crc_flag(data)) {
        Node* new_node = create_node(data);

        // Check size of the linked list
        Node* temp = head;
        int count = 0;
        while (temp != NULL) {
            temp = temp->next;
            count++;
        }
        if (count < MAX_LINKED_LIST_SIZE) {
            new_node->next = head;
            head = new_node;
        } else {
            free(new_node);
        }
    }

    pthread_mutex_unlock(&lock);
}

void remove_entry_by_rnti(uint16_t rnti) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev = NULL;

    while (temp != NULL && temp->data.RNTI != rnti) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    if (prev == NULL) {
        // Remove head
        head = temp->next;
    } else {
        prev->next = temp->next;
    }

    free(temp);

    pthread_mutex_unlock(&lock);
}

void iterate_and_print_list() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u\n", 
               current->data.RX_UE_INFORMATION_TAG, 
               current->data.RNTI);
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

int add_entry_to_array(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    if (validate_crc_flag(data)) {
        if (array_count < MAX_ARRAY_SIZE) {
            array[array_count++] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!array[array_count - 1]) {
                perror("Failed to allocate memory");
                pthread_mutex_unlock(&lock);
                exit(EXIT_FAILURE);
            }
            array[array_count - 1]->RX_UE_INFORMATION_TAG = data.RX_UE_INFORMATION_TAG;
            array[array_count - 1]->RNTI = data.RNTI;
            array[array_count - 1]->CRC_INDICATION_REL8_TAG.CRCFLAG = data.CRC_INDICATION_REL8_TAG.CRCFLAG;
        } else {
            pthread_mutex_unlock(&lock);
            return -1; // Array is full
        }
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

void serialize_data(FILE* file) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    for (size_t i = 0; i < array_count; i++) {
        fwrite(array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    pthread_mutex_unlock(&lock);
}

void deserialize_data(FILE* file) {
    pthread_mutex_lock(&lock);

    while (!feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T data;
        if (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
            add_entry_to_list(data);
        }
    }

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;

    for (size_t i = 0; i < array_count; i++) {
        free(array[i]);
    }

    pthread_mutex_unlock(&lock);
}

// Unit test examples
void test_add_and_remove() {
    initialize_random();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1001 };
    pdu1.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    add_entry_to_list(pdu1);
    iterate_and_print_list();

    remove_entry_by_rnti(1001);
    iterate_and_print_list();
}

int main() {
    test_add_and_remove();

    // Further tests and logic can be added here.

    cleanup();
    pthread_mutex_destroy(&lock);

    return 0;
}
