#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_SIZE 1048576 // Example: 1 MB max log file size
#define LOG_ROTATION_INTERVAL 3600 // Rotate every hour

typedef struct {
    size_t size;
    char *data;
    time_t timestamp;
} LogEntry;

typedef struct {
    FILE *file;
    pthread_mutex_t lock;
    off_t current_size;
    time_t last_rotation_time;
} LogManager;

LogManager log_manager = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0};

void rotate_log() {
    if (log_manager.file) {
        fclose(log_manager.file);
        char rotated_filename[256];
        snprintf(rotated_filename, sizeof(rotated_filename), "logfile_%ld.log", time(NULL));
        rename("current_logfile.log", rotated_filename);
    }

    log_manager.file = fopen("current_logfile.log", "a");
    if (!log_manager.file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log_manager.current_size = 0;
    log_manager.last_rotation_time = time(NULL);
}

void write_log_entry(LogEntry *entry) {
    pthread_mutex_lock(&log_manager.lock);

    if (log_manager.file == NULL || !ferror(log_manager.file)) {
        if (time(NULL) - log_manager.last_rotation_time >= LOG_ROTATION_INTERVAL ||
            log_manager.current_size + entry->size > MAX_LOG_SIZE) {
            rotate_log();
        }

        fwrite(entry->data, 1, entry->size, log_manager.file);
        log_manager.current_size += entry->size;
    }

    pthread_mutex_unlock(&log_manager.lock);
}

void log_data(const char *data, size_t size) {
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) {
        perror("Failed to allocate memory for log entry");
        return;
    }

    entry->size = size;
    entry->data = strndup(data, size);
    if (!entry->data) {
        free(entry);
        perror("Failed to duplicate log data");
        return;
    }
    entry->timestamp = time(NULL);

    write_log_entry(entry);

    free(entry->data);
    free(entry);
}

void init_logging_system() {
    pthread_mutex_lock(&log_manager.lock);
    if (!log_manager.file) {
        log_manager.file = fopen("current_logfile.log", "a");
        if (!log_manager.file) {
            perror("Failed to open initial log file");
            exit(EXIT_FAILURE);
        }
        log_manager.current_size = 0;
        log_manager.last_rotation_time = time(NULL);
    }
    pthread_mutex_unlock(&log_manager.lock);
}

void cleanup_logging_system() {
    pthread_mutex_lock(&log_manager.lock);
    if (log_manager.file) {
        fclose(log_manager.file);
        rotate_log(); // Final rotation to ensure all logs are saved
    }
    pthread_mutex_unlock(&log_manager.lock);
}

__attribute__((constructor))
static void initialize() {
    init_logging_system();
}

__attribute__((destructor))
static void finalize() {
    cleanup_logging_system();
}
