#define BUCKET_COUNT 1009 // A prime number for better distribution

typedef struct {
    int RX_POWER;
    double SNR;
    double BER;
    uint32_t PHY_LAYER_EVENT;
} NFAPI_L1PHY_STATISTICS_T;

typedef struct Entry {
    char *key;
    NFAPI_L1PHY_STATISTICS_T data;
    struct Entry *next;
} Entry;

typedef struct {
    Entry **buckets;
    pthread_mutex_t locks[BUCKET_COUNT];
    size_t entry_count;
} HashTable;

uint32_t hash_function(const char *key) {
    uint32_t hash = 0;
    while (*key) {
        hash = (hash << 5) + hash + *key++;
    }
    return hash % BUCKET_COUNT;
}

HashTable* create_table() {
    HashTable *table = malloc(sizeof(HashTable));
    table->buckets = calloc(BUCKET_COUNT, sizeof(Entry *));
    table->entry_count = 0;
    for (int i = 0; i < BUCKET_COUNT; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
    return table;
}

void free_entry(Entry *entry) {
    if (entry) {
        free(entry->key);
        free(entry);
    }
}

void destroy_table(HashTable *table) {
    for (int i = 0; i < BUCKET_COUNT; ++i) {
        Entry *entry = table->buckets[i];
        while (entry) {
            Entry *next = entry->next;
            free_entry(entry);
            entry = next;
        }
    }
    free(table->buckets);
    for (int i = 0; i < BUCKET_COUNT; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }
    free(table);
}

void update_statistics(HashTable *table, const char *key, double snr) {
    uint32_t index = hash_function(key);
    pthread_mutex_lock(&table->locks[index]);

    Entry *entry = table->buckets[index];
    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            entry->data.SNR = ((entry->data.SNR + snr) / 2.0); // Rolling average
            pthread_mutex_unlock(&table->locks[index]);
            return;
        }
        entry = entry->next;
    }

    if (table->entry_count < MAX_KEYS) {
        Entry *new_entry = malloc(sizeof(Entry));
        new_entry->key = strdup(key);
        new_entry->data.SNR = snr; // Initial value
        new_entry->next = table->buckets[index];
        table->buckets[index] = new_entry;
        ++table->entry_count;
    }

    pthread_mutex_unlock(&table->locks[index]);
}

double get_snr_average(HashTable *table, const char *key) {
    uint32_t index = hash_function(key);
    pthread_mutex_lock(&table->locks[index]);

    Entry *entry = table->buckets[index];
    double snr = 0.0;
    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            snr = entry->data.SNR;
            break;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return snr;
}

void serialize_table(HashTable *table, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&table->entry_count, sizeof(size_t), 1, file);
    for (int i = 0; i < BUCKET_COUNT; ++i) {
        pthread_mutex_lock(&table->locks[i]);
        Entry *entry = table->buckets[i];
        while (entry) {
            size_t key_len = strlen(entry->key) + 1;
            fwrite(&key_len, sizeof(size_t), 1, file);
            fwrite(entry->key, sizeof(char), key_len, file);
            fwrite(&(entry->data), sizeof(NFAPI_L1PHY_STATISTICS_T), 1, file);
            entry = entry->next;
        }
        pthread_mutex_unlock(&table->locks[i]);
    }

    fclose(file);
}

HashTable* deserialize_table(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    HashTable *table = create_table();
    fread(&table->entry_count, sizeof(size_t), 1, file);

    for (int i = 0; i < BUCKET_COUNT; ++i) {
        pthread_mutex_lock(&table->locks[i]);
        while (fread(&size_t key_len, sizeof(size_t), 1, file)) {
            char *key = malloc(key_len);
            fread(key, sizeof(char), key_len, file);
            NFAPI_L1PHY_STATISTICS_T data;
            fread(&data, sizeof(NFAPI_L1PHY_STATISTICS_T), 1, file);

            Entry *new_entry = malloc(sizeof(Entry));
            new_entry->key = strdup(key);
            new_entry->data = data;
            new_entry->next = table->buckets[i];
            table->buckets[i] = new_entry;

            free(key);
        }
        pthread_mutex_unlock(&table->locks[i]);
    }

    fclose(file);
    return table;
}

int main() {
    HashTable *table = create_table();

    update_statistics(table, "key1", 10.0);
    printf("SNR for key1: %f\n", get_snr_average(table, "key1"));

    serialize_table(table, "hash_table.dat");
    HashTable *loaded_table = deserialize_table("hash_table.dat");

    if (loaded_table) {
        printf("Loaded SNR for key1: %f\n", get_snr_average(loaded_table, "key1"));
        destroy_table(loaded_table);
    }

    destroy_table(table);

    return 0;
}
