#define MAX_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t length;
    pthread_mutex_t lock;
} PDUArray;

void handle_signal(int sig) {
    fprintf(stderr, "Process interrupted by signal %d\n", sig);
    exit(EXIT_FAILURE);
}

int execute_background_command() {
    pid_t pid = fork();
    if (pid == -1) return 0; // Fork failed
    if (pid > 0) { // Parent process
        int status;
        wait(&status);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
    // Child process: execute the command here
    execl("/path/to/your/command", "command", (char *)NULL);
    return 0; // If exec fails
}

int createNfareport(PDUArray *array, int N) {
    if (N > MAX_SIZE) {
        fprintf(stderr, "Error: N exceeds maximum allowed size\n");
        return 0;
    }

    signal(SIGINT, handle_signal);

    pthread_mutex_init(&array->lock, NULL);

    array->data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        pthread_mutex_destroy(&array->lock);
        return 0;
    }

    if (!execute_background_command()) {
        free(array->data);
        pthread_mutex_destroy(&array->lock);
        return 0;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&array->lock);

        array->data[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        array->data[i].RNTI = i + 1;
        array->data[i].CRCFLAG = rand() % 2; // Random CRCFLAG

        pthread_mutex_unlock(&array->lock);
    }

    array->length = N;

    return 1;
}
