    if (index < manager->count) {
        pthread_mutex_lock(&manager->lock);
        free(manager->ue_array[index]);
        memmove(&manager->ue_array[index], &manager->ue_array[index + 1],
                (manager->count - index - 1) * sizeof(NFAPI_MESSAGE_PDU_T*));
        manager->count--;
        log_message(LOG_LEVEL_INFO, "UE removed.");
