    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* head = NULL;
int list_size = 0;

void enqueue(NFAPI_CRC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list_mutex);
    if (list_size < LINKED_LIST_MAX_SIZE) {
        node->next = head;
        head = node;
        list_size++;
        printf("Element enqueued. Current size: %d\n", list_size);
    } else {
        printf("Overflow condition: Linked list is full.\n");
        free(node);
    }
    pthread_mutex_unlock(&list_mutex);
}

void* populate_network_entities() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) return NULL;

    NetworkEntity entities[100];
    int entity_count = 0;
