    for (int i = 0; i < entity_count; i++) {
        if (entities[i].portNumber > max_port && entities[i].portNumber <= MAX_PORT_NUMBER) {
            max_port = entities[i].portNumber;
        }
    }

    printf("Maximum port number: %d\n", max_port);

    for (int i = 0; i < entity_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) continue;

        node->rx_ue_info.RNTI = rand() % 10000;
        node->crc_indication_rel8.CRCFLAG = rand() % 2;
        enqueue(node);
    }

    return NULL;
}

void test_linked_list() {
    pthread_t thread;
    pthread_create(&thread, NULL, populate_network_entities, NULL);
    pthread_join(thread, NULL);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        printf("RNTI: %lu, CRCFLAG: %d\n", current->rx_ue_info.RNTI, current->crc_indication_rel8.CRCFLAG);
        current = current->next;
    }
}

int main() {
    test_linked_list();
    return 0;
}
