void find_largest_integer(int *arr, int size) {
    if (size == 0) return;

    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest)
            largest = arr[i];
    }
    printf("Largest integer: %d\n", largest);
}

int validate_offsets(long *offsets, int count) {
    int seen[MAX_OFFSET_VALUE] = {0};
    for (int i = 0; i < count; ++i) {
        if (offsets[i] <= 0 || offsets[i] >= MAX_OFFSET_VALUE)
            return 0;
        if (seen[offsets[i]]) 
            return 0;
        seen[offsets[i]] = 1;
    }
    return 1;
}

int validate_node_ids(NODE_T *nodes, int count) {
    int seen[NODE_ID_RANGE + 1] = {0};
    for (int i = 0; i < count; ++i) {
        if (nodes[i].id <= 0 || nodes[i].id > NODE_ID_RANGE)
            return 0;
        if (seen[nodes[i].id])
            return 0;
        seen[nodes[i].id] = 1;
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_nfa_api(int n, char *error_buffer) {
    int *integers = NULL;
    size_t len, i;

    // Read integers from stdin
    for (i = 0; ; ++i) {
        if (scanf("%zu", &len) != 1 || len <= 0)
            break;

        integers = realloc(integers, (i + 1) * sizeof(*integers));
        if (!integers) {
            strcpy(error_buffer, "Memory allocation failed");
            return NULL;
        }
        integers[i] = len;
    }

    find_largest_integer(integers, i);
    free(integers);

    // Initialize NFAPI structures
    NFAPI_CRC_INDICATION_PDU_T *nfa_api = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_api) {
