        nfa_api[i].rx_ue_information_tag = rand() % 100;
        nfa_api[i].rnti = rand() % 10000;
        nfa_api[i].crc_indication_rel8_tag.CRCFLAG = rand() & 1;
    }

    // Initialize other structures
    long *offsets = malloc(n * sizeof(*offsets));
    int *keys = malloc(n * sizeof(*keys));
    double *doubles = malloc(n * sizeof(*doubles));
    float *floats = malloc(n * sizeof(*floats));
    char *tags = malloc(n * sizeof(*tags));
    NODE_T *nodes = malloc(n * sizeof(*nodes));
    int *indices = malloc(n * sizeof(*indices));
    EVENT_T *events = malloc(n * sizeof(*events));
    STATUS_T *statuses = malloc(n * sizeof(*statuses));

    if (!offsets || !keys || !doubles || !floats || !tags || !nodes || !indices || !events || !statuses) {
        strcpy(error_buffer, "Memory allocation failed");
        free(offsets);
        free(keys);
        free(doubles);
        free(floats);
        free(tags);
        free(nodes);
        free(indices);
        free(events);
        free(statuses);
        free(nfa_api);
        return NULL;
    }

    for (i = 0; i < n; ++i) {
        offsets[i] = rand() % MAX_OFFSET_VALUE + 1;
        keys[i] = rand();
        doubles[i] = rand() / (double)RAND_MAX;
        tags[i] = 'A' + (rand() % 26);
        nodes[i].id = rand() % NODE_ID_RANGE + 1;
        indices[i] = i;
        events[i].value = rand() / (double)RAND_MAX;
        events[i].timestamp = time(NULL); // Synchronize with system time
        statuses[i] = rand() & 1 ? SUCCESS : FAILURE;
    }

    if (!validate_offsets(offsets, n)) {
        strcpy(error_buffer, "Offset validation failed");
        free(offsets);
        free(keys);
        free(doubles);
        free(floats);
        free(tags);
        free(nodes);
        free(indices);
        free(events);
        free(statuses);
        free(nfa_api);
        return NULL;
    }

    if (!validate_node_ids(nodes, n)) {
        strcpy(error_buffer, "Node ID validation failed");
        free(offsets);
        free(keys);
        free(doubles);
        free(floats);
        free(tags);
        free(nodes);
        free(indices);
        free(events);
        free(statuses);
        free(nfa_api);
        return NULL;
    }

    if (n != (sizeof(floats) / sizeof(floats[0])) + (sizeof(tags) / sizeof(tags[0])) + (sizeof(indices) / sizeof(indices[0]))) {
        strcpy(error_buffer, "Float count mismatch");
        free(offsets);
        free(keys);
        free(doubles);
        free(floats);
        free(tags);
        free(nodes);
        free(indices);
        free(events);
        free(statuses);
        free(nfa_api);
        return NULL;
    }

    sem_t semaphore;
    if (sem_init(&semaphore, 0, 1) != 0) {
        strcpy(error_buffer, "Semaphore initialization failed");
        free(offsets);
        free(keys);
        free(doubles);
        free(floats);
        free(tags);
        free(nodes);
        free(indices);
        free(events);
        free(statuses);
        free(nfa_api);
        return NULL;
    }

    // Simulate processing with semaphore
    sem_wait(&semaphore);
    // Critical section
    sem_post(&semaphore);

    sem_destroy(&semaphore);

    free(offsets);
    free(keys);
    free(doubles);
    free(floats);
    free(tags);
    free(nodes);
    free(indices);
    free(events);
    free(statuses);

    return nfa_api;
}
