#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned long timestamp;
    int packet_id;
    char *payload;
} Packet;

typedef struct {
    Packet **packets;
    size_t count;
    size_t capacity;
} PacketList;

PacketList* init_packet_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    PacketList *list = (PacketList*)malloc(sizeof(PacketList));
    list->packets = (Packet**)calloc(initial_capacity, sizeof(Packet*));
    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

void grow_packet_list(PacketList *list) {
    size_t new_capacity = list->capacity * 2;
    Packet **new_packets = (Packet**)realloc(list->packets, new_capacity * sizeof(Packet*));
    if (!new_packets) {
        fprintf(stderr, "Failed to reallocate memory for packet list.\n");
        return;
    }
    memset(new_packets + list->count, 0, (new_capacity - list->count) * sizeof(Packet*));

    list->packets = new_packets;
    list->capacity = new_capacity;
}

void add_packet(PacketList *list, unsigned long timestamp, int packet_id, size_t payload_size) {
    if (!list || list->count >= list->capacity) {
        grow_packet_list(list);
    }

    Packet *packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        fprintf(stderr, "Failed to allocate memory for new packet.\n");
        return;
    }

    packet->timestamp = timestamp;
    packet->packet_id = packet_id;

    char *pattern = (char*)calloc(payload_size, sizeof(char));
    if (!pattern) {
        free(packet);
        fprintf(stderr, "Failed to allocate memory for payload.\n");
        return;
    }

    for (size_t i = 0; i < payload_size; ++i) {
        pattern[i] = (packet_id * (i + 1)) % 256; // Example pattern
    }

    packet->payload = pattern;

    list->packets[list->count++] = packet;
}

void free_packet_list(PacketList *list) {
    if (!list) return;

    for (size_t i = 0; i < list->count; ++i) {
        Packet *packet = list->packets[i];
        if (packet) {
            free(packet->payload);
            free(packet);
        }
    }

    free(list->packets);
    free(list);
}

// Example usage
int main() {
    PacketList *packet_list = init_packet_list(10);

    for (int i = 0; i < 20; ++i) { // Adding more packets than initial capacity to test growth
        add_packet(packet_list, time(NULL), i, 50);
    }

    free_packet_list(packet_list);

    return 0;
}
```

This C code defines a `PacketList` structure that manages an array of pointers to `Packet` structures. Each `Packet` contains a timestamp, a unique packet identifier, and a dynamically allocated payload filled with a pattern based on its index and identifier.

### Key Features:
- **Dynamic Memory Allocation**: The function grows the list's capacity when needed using reallocation.
- **Error Handling**: Checks for allocation failures and outputs error messages to standard error.
- **Memory Management**: Ensures all allocated memory is freed when no longer required, preventing memory leaks.
- **Growth Strategy**: Doubles the size of the array each time it needs more space to balance between resizing costs and memory efficiency.']

