```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define STATUS_ACTIVE 1
#define STATUS_INACTIVE 2

typedef struct {
    int SESSION_ID;
    char USER_NAME[256];
    time_t LOGIN_TIME;
    time_t LAST_ACTIVITY_TIME;
    double TOTAL_TIME_ON_SITE; // In seconds
    int PAGE_VISIT_COUNT;
    int STATUS;
} USER_SESSION_T;

// Session pool and control variables
USER_SESSION_T *session_pool = NULL;
size_t max_sessions = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t session_cond = PTHREAD_COND_INITIALIZER;

void initialize_session_pool(size_t initial_max_sessions) {
    pthread_mutex_lock(&session_lock);

    // Reinitialize the pool if needed
    if (session_pool != NULL) {
        free(session_pool);
        session_pool = NULL;
    }

    max_sessions = initial_max_sessions;
    session_pool = (USER_SESSION_T *)calloc(max_sessions, sizeof(USER_SESSION_T));
    pthread_mutex_unlock(&session_lock);
}

int add_session(const char *user_name, int session_id) {
    pthread_mutex_lock(&session_lock);

    // Search for an inactive or non-existent slot
    for (size_t i = 0; i < max_sessions; ++i) {
        if (session_pool[i].STATUS == STATUS_INACTIVE || session_pool[i].SESSION_ID == 0) {
            session_pool[i].SESSION_ID = session_id;
            strncpy(session_pool[i].USER_NAME, user_name, sizeof(session_pool[i].USER_NAME));
            session_pool[i].LOGIN_TIME = time(NULL);
            session_pool[i].LAST_ACTIVITY_TIME = session_pool[i].LOGIN_TIME;
            session_pool[i].TOTAL_TIME_ON_SITE = 0.0;
            session_pool[i].PAGE_VISIT_COUNT = 0;
            session_pool[i].STATUS = STATUS_ACTIVE;

            pthread_mutex_unlock(&session_lock);
            return i; // Return the index where the new session was added
        }
    }

    pthread_mutex_unlock(&session_lock);
    return -1; // Indicate failure to add a new session (pool full)
}

int remove_session(int session_id) {
    pthread_mutex_lock(&session_lock);

    for (size_t i = 0; i < max_sessions; ++i) {
        if (session_pool[i].SESSION_ID == session_id) {
            session_pool[i].STATUS = STATUS_INACTIVE;
            session_pool[i].SESSION_ID = 0;

            pthread_mutex_unlock(&session_lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&session_lock);
    return -1; // Indicate failure to remove the session (not found)
}

void update_session_activity(int session_id) {
    pthread_mutex_lock(&session_lock);

    for (size_t i = 0; i < max_sessions; ++i) {
        if (session_pool[i].SESSION_ID == session_id && session_pool[i].STATUS == STATUS_ACTIVE) {
            time_t current_time = time(NULL);
            double elapsed_time = difftime(current_time, session_pool[i].LAST_ACTIVITY_TIME);

            session_pool[i].TOTAL_TIME_ON_SITE += elapsed_time;
            session_pool[i].PAGE_VISIT_COUNT++;
            session_pool[i].LAST_ACTIVITY_TIME = current_time;

            pthread_mutex_unlock(&session_lock);
            return; // Successfully updated
        }
    }

    pthread_mutex_unlock(&session_lock);
}

void scale_sessions(size_t new_max_sessions) {
    pthread_mutex_lock(&session_lock);

    if (new_max_sessions > max_sessions) {
        session_pool = (USER_SESSION_T *)realloc(session_pool, new_max_sessions * sizeof(USER_SESSION_T));
        for (size_t i = max_sessions; i < new_max_sessions; ++i) {
            session_pool[i].SESSION_ID = 0;
            session_pool[i].STATUS = STATUS_INACTIVE;
        }
    } else if (new_max_sessions < max_sessions) {
        // Optionally handle reducing the pool size
        for (size_t i = new_max_sessions; i < max_sessions; ++i) {
            if (session_pool[i].STATUS == STATUS_ACTIVE) {
                session_pool[i].STATUS = STATUS_INACTIVE;
                session_pool[i].SESSION_ID = 0;
            }
        }
    }

    max_sessions = new_max_sessions;
    pthread_mutex_unlock(&session_lock);
}

void log_session_change(const char *message, int session_id) {
    // A simple logging function
    time_t now = time(NULL);
    printf("[%s] %d: %s\n", ctime(&now), session_id, message);
}

// Callback to be called periodically (e.g., via a timer)
void periodic_update_callback(void (*update_func)(int)) {
    pthread_mutex_lock(&session_lock);

    for (size_t i = 0; i < max_sessions; ++i) {
        if (session_pool[i].STATUS == STATUS_ACTIVE) {
            update_func(session_pool[i].SESSION_ID);
        }
    }

    pthread_mutex_unlock(&session_lock);
}

int main() {
    // Example usage
    initialize_session_pool(10); // Start with a pool of 10 sessions

    int session_index = add_session("Alice", 1);
    if (session_index >= 0) {
        log_session_change("Session added", 1);
    }

    update_session_activity(1);

    scale_sessions(20); // Scale up to 20 sessions
    remove_session(1);

    periodic_update_callback(update_session_activity);

    free(session_pool); // Clean-up
    return 0;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that the session pool can be accessed by multiple threads safely.
- **Dynamic Scaling**: The `scale_sessions` function handles both increasing and decreasing the size of the session pool dynamically.
- **Real-time Updates**: The periodic update mechanism (using a callback) updates activity metrics without significant latency.
- **Logging**: A simple logging system records changes in session status with minimal overhead. This can be expanded to more sophisticated centralized or distributed systems if needed.
- **Efficiency Considerations**: Memory allocation and copying are minimized by using fixed-size arrays for sessions, and `realloc` is used when scaling up.

This code provides a foundation that balances performance needs and thread safety while offering flexibility in managing user session data. Adjustments can be made based on specific application requirements or additional features.']

