```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

typedef struct MemoryPool {
    size_t blockSize;
    void* startPtr;
    void** freeList;
    size_t freeCount;
} MemoryPool;

// Function prototypes
MemoryPool* createMemoryPool(size_t blockSize, size_t poolSize);
void destroyMemoryPool(MemoryPool* pool);
void* allocateFromPool(MemoryPool* pool);
void freeAllToPool(MemoryPool* pool);

Record* initializeRecords(int startKey, int endKey, int numRecords, int logToFile, const char *logFileName);
int isDuplicateKey(const Record* records, int count, int key);
void logRecordDetails(FILE* file, const Record* record);
void sortAndFilter(Record* records, size_t count);

// Create a memory pool
MemoryPool* createMemoryPool(size_t blockSize, size_t poolSize) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    void* poolBlock = malloc(blockSize * poolSize);
    pool->blockSize = blockSize;
    pool->startPtr = poolBlock;
    pool->freeList = malloc(poolSize * sizeof(void*));

    for (size_t i = 0; i < poolSize - 1; ++i) {
        void** current = (void**)&poolBlock + i;
        *current = ((char*)poolBlock) + blockSize * (i + 1);
    }
    void** last = (void**)(&((char*)poolBlock)[(poolSize - 1) * blockSize]);
    *last = NULL;

    pool->freeCount = poolSize;
    return pool;
}

// Destroy a memory pool
void destroyMemoryPool(MemoryPool* pool) {
    free(pool->startPtr);
    free(pool->freeList);
    free(pool);
}

// Allocate from the memory pool
void* allocateFromPool(MemoryPool* pool) {
    if (pool->freeCount == 0) return NULL;
    void** freeBlock = pool->freeList + (pool->freeCount - 1);
    --(pool->freeCount);
    return *freeBlock;
}

// Free all allocations back to the pool
void freeAllToPool(MemoryPool* pool) {
    size_t i = 0;
    for (void** block = pool->freeList; i < pool->freeSize && block[i] != NULL; ++i)
        ; // Find the count of used blocks

    pool->freeCount += i;

    void* current = pool->startPtr;
    void** last = pool->freeList + pool->freeCount - 1;

    for (size_t j = 0; j < i; ++j) {
        *last-- = current;
        current = ((char*)current) + pool->blockSize;
    }
    *(last + 1) = NULL;
}

Record* initializeRecords(int startKey, int endKey, int numRecords, int logToFile, const char* logFileName) {
    if (startKey >= endKey || numRecords <= 0) return NULL;

    MemoryPool* pool = createMemoryPool(sizeof(Record), numRecords);

    Record* records = malloc(numRecords * sizeof(Record));
    if (!records) {
        destroyMemoryPool(pool);
        return NULL;
    }

    FILE* logFile = NULL;
    if (logToFile) {
        logFile = fopen(logFileName, "w");
        if (!logFile) {
            free(records);
            destroyMemoryPool(pool);
            return NULL;
        }
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < numRecords; ++i) {
        int key;
        do {
            key = startKey + rand() % (endKey - startKey + 1);
        } while(isDuplicateKey(records, i, key));

        Record* record = allocateFromPool(pool);
        if (!record) break;

        pthread_mutex_lock(&mutex);
        record->offset = i + 1; // Ensure positive and unique
        record->key = key;
        record->value = (double)rand() / RAND_MAX;
        records[i] = *record;
        pthread_mutex_unlock(&mutex);

        if (logFile) {
            logRecordDetails(logFile, &records[i]);
        }
    }

    if (logFile) fclose(logFile);
    sortAndFilter(records, numRecords); // Assuming external library integration for sorting and filtering

    freeAllToPool(pool);
    destroyMemoryPool(pool);
    pthread_mutex_destroy(&mutex);

    return records;
}

int isDuplicateKey(const Record* records, int count, int key) {
    for (int i = 0; i < count; ++i)
        if (records[i].key == key) return 1;
    return 0;
}

void logRecordDetails(FILE* file, const Record* record) {
    fprintf(file, "Offset: %ld, Key: %d, Value: %.5f\n", record->offset, record->key, record->value);
}

void sortAndFilter(Record* records, size_t count) {
    // Placeholder for external library sorting and filtering
}
