    printf("RNTI: %d, SNR: %.2f\n", rnti, snr);
    pthread_mutex_unlock(&global_lock);
}

// Function to dynamically resize the array
int resize_array(NFAPI_MESSAGE_PDU_T* pdu_array, size_t new_size) {
    if (new_size > MAX_UE_COUNT) return -1;

    UEInformation* new_info = realloc(pdu_array->ue_info, new_size * sizeof(UEInformation));
    if (!new_info) return -1;

    memset(new_info + pdu_array->count, 0, (new_size - pdu_array->count) * sizeof(UEInformation));
    pdu_array->ue_info = new_info;
    pdu_array->count = new_size;

    return 0;
}

// Function to initialize and populate the array
void init_and_populate_pdu(int ue_count) {
    static NFAPI_MESSAGE_PDU_T pdu_array = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

    if (ue_count > pdu_array.count) {
        pthread_mutex_lock(&pdu_array.lock);
        if (resize_array(&pdu_array, ue_count)) {
            fprintf(stderr, "Failed to resize array\n");
            pthread_mutex_unlock(&pdu_array.lock);
            return;
        }
        pthread_mutex_unlock(&pdu_array.lock);
    }

    pthread_mutex_lock(&pdu_array.lock);

    clock_t start = clock();
    for (size_t i = 0; i < pdu_array.count && i < ue_count; ++i) {
        // Simulate SNR and RNTI
        pdu_array.ue_info[i].SNR = rand() % 20 - 5;
        pdu_array.ue_info[i].RNTI = rand();

        if (pdu_array.ue_info[i].SNR < SNR_THRESHOLD) {
            printf("Flagging UE for poor channel quality: RNTI %d\n", pdu_array.ue_info[i].RNTI);
        }

        log_UE_info(pdu_array.ue_info[i].RNTI, pdu_array.ue_info[i].SNR);

        // Simulate dynamic behavior based on network load
        if (network_load > 70) {
            printf("High network load detected, adjusting processing priority\n");
        }
    }

    clock_t end = clock();
    double avg_time_per_ue = (double)(end - start) / CLOCKS_PER_SEC / ue_count;
    printf("Average processing time per UE: %.6f seconds\n", avg_time_per_ue);

    if (avg_time_per_ue > 0.001) { // Threshold in seconds
        fprintf(stderr, "Processing threshold exceeded\n");
    }

    pthread_mutex_unlock(&pdu_array.lock);
}

void* thread_function(void* arg) {
    int ue_count = *(int*)arg;
    init_and_populate_pdu(ue_count);
    return NULL;
}

int main() {
    const int num_threads = 4;
    pthread_t threads[num_threads];
    int ue_counts[num_threads] = {100, 200, 300, 400};

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &ue_counts[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
