['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CONFIG_FILE "config.cfg"
#define LOG_FILE "crc_log.txt"
#define DEFAULT_RANGE_MIN 0
#define DEFAULT_RANGE_MAX 1000
#define DEFAULT_CRC_PROBABILITY 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        time_t now = time(NULL);
        fprintf(log, "[%s] %s\n", ctime(&now), message);
        fclose(log);
    }
}

int read_config(char *range_min_str, char *range_max_str, char *crc_prob_str) {
    FILE *config = fopen(CONFIG_FILE, "r");
    if (!config) return 0;

    if (fscanf(config, "%s %s %s", range_min_str, range_max_str, crc_prob_str) != 3) {
        fclose(config);
        return 0;
    }

    fclose(config);
    return 1;
}

void print_error_and_exit(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    log_message(message);
    exit(EXIT_FAILURE);
}

int validate_integer(int num, int min, int max) {
    return (num >= min && num <= max);
}

int find_largest_int(int *arr, size_t count) {
    if (count == 0) print_error_and_exit("No integers to process.");

    int largest = arr[0];
    for (size_t i = 1; i < count; ++i) {
        if (arr[i] > largest) largest = arr[i];
    }
    return largest;
}

void populate_crc_structures(NFAPI_CRC_INDICATION_PDU_T *array, size_t size) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        array[i].RNTI = rand() % 500;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 10;

        int random_value = rand() % 100;
        if (random_value < crc_probability) {
            array[i].CRCFLAG = 1;
        } else {
            array[i].CRCFLAG = 0;
        }
    }
}

void process_integers(int *count_stats[3]) {
    char range_min_str[10], range_max_str[10], crc_prob_str[10];
    int range_min = DEFAULT_RANGE_MIN, range_max = DEFAULT_RANGE_MAX, crc_probability = DEFAULT_CRC_PROBABILITY;

    if (!read_config(range_min_str, range_max_str, crc_prob_str)) {
        log_message("Using default configuration values.");
    } else {
        sscanf(range_min_str, "%d", &range_min);
        sscanf(range_max_str, "%d", &range_max);
        sscanf(crc_prob_str, "%d", &crc_probability);
        log_message("Configuration file loaded successfully.");
    }

    int num;
    size_t count = 0, capacity = 10;
    int *arr = malloc(capacity * sizeof(int));
    if (!arr) print_error_and_exit("Memory allocation failed for input array.");

    while (scanf("%d", &num) == 1) {
        if (!validate_integer(num, range_min, range_max)) {
            free(arr);
            print_error_and_exit("Input integer out of valid range.");
        }

        if (count >= capacity) {
            capacity *= 2;
            int *new_arr = realloc(arr, capacity * sizeof(int));
            if (!new_arr) print_error_and_exit("Memory reallocation failed for input array.");
            arr = new_arr;
        }

        arr[count++] = num;

        // Update statistics
        if (num > 0) count_stats[0]++;
        else if (num < 0) count_stats[1]++;
        else count_stats[2]++;
    }

