Metadata* create_metadata(char value) {
    Metadata *new_meta = (Metadata*)malloc(sizeof(Metadata));
    if (!new_meta) return NULL; // Handle allocation failure

    new_meta->value = value;
    new_meta->next = NULL;
    return new_meta;
}

// Function to manage memory for records
int manage_records(Record ***records, size_t *num_records, int limit, int batch_count, char metadata_value) {
    if (limit <= 0 || batch_count <= 0) {
        fprintf(stderr, "Invalid limit or batch count.\n");
        return -1; // Error code for invalid input
    }

    pthread_mutex_lock(&lock);

    if (*records == NULL) {
        *records = malloc(limit * sizeof(Record*));
        if (!(*records)) {
            perror("Failed to allocate memory for records");
            pthread_mutex_unlock(&lock);
            return -1; // Error code for allocation failure
        }
    }

    size_t current_count = *num_records;
    if (current_count + batch_count > limit) {
        fprintf(stderr, "Exceeding the specified record limit.\n");
        pthread_mutex_unlock(&lock);
        return -2; // Error code for exceeding limit
    }

    for (size_t i = 0; i < batch_count; ++i) {
        (*records)[current_count + i] = (Record*)malloc(sizeof(Record));
        if (!(*records)[current_count + i]) {
            perror("Failed to allocate memory for record");
            // Free any previously allocated records in this batch
            while (i > 0) free((*records)[current_count + --i]);
            pthread_mutex_unlock(&lock);
            return -1; // Error code for allocation failure
        }

        (*records)[current_count + i]->data = 0;
        (*records)[current_count + i]->key = 0;

        Metadata *meta = create_metadata(metadata_value);
        if (!meta) {
            free((*records)[current_count + i]);
            fprintf(stderr, "Failed to allocate metadata.\n");
            pthread_mutex_unlock(&lock);
            return -1; // Error code for allocation failure
        }
        (*records)[current_count + i]->metadata = meta;
    }

    *num_records += batch_count;

    pthread_mutex_unlock(&lock);
    return 0; // Success
}

// Function to free the allocated records and metadata.
void free_records(Record **records, size_t num_records) {
    if (records == NULL) return;

    for (size_t i = 0; i < num_records; ++i) {
        Metadata *meta = records[i]->metadata;
        while (meta) {
            Metadata *temp = meta;
            meta = meta->next;
            free(temp);
        }
        free(records[i]);
    }

    free(records);
}

int main() {
    Record *records = NULL;
    size_t num_records = 0;
    int result;

    result = manage_records(&records, &num_records, 100, 10, 'A');
    if (result != 0) {
        fprintf(stderr, "Error occurred: %d\n", result);
    }

    // Example of freeing the records
    free_records(records, num_records);

    return 0;
}
