}

// Thread-safe linked list management functions
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST;

NFAPI_CRC_INDICATION_LIST* initList(void) {
    NFAPI_CRC_INDICATION_LIST* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeList(NFAPI_CRC_INDICATION_LIST* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addNode(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation error
    }

    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Initialize and manage dynamic arrays with logging and memory integrity check
int initDynamicArrays(size_t size, long** offsets, int** keys, void** records) {
