// Define the dataItem structure.
typedef struct {
    size_t id;
    uint8_t *data;
    uint32_t timestamp;
} dataItem;

// Hash table node and hash table definitions for identifier management.
#define HASH_TABLE_SIZE 16384

typedef struct HashNode {
    size_t id;
    struct HashNode *next;
} HashNode;

HashNode *hashTable[HASH_TABLE_SIZE];

unsigned long hashFunction(size_t id) {
    return id % HASH_TABLE_SIZE;
}

int isIdUnique(size_t id) {
    unsigned long index = hashFunction(id);
    for (HashNode *node = hashTable[index]; node; node = node->next) {
        if (node->id == id) {
            return 0;
        }
    }
    return 1;
}

void addIdToHashTable(size_t id) {
    unsigned long index = hashFunction(id);
    HashNode *newNode = malloc(sizeof(HashNode));
    newNode->id = id;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
}

// Custom pool allocator for efficient memory management.
#define POOL_SIZE 1024

typedef struct {
    uint8_t *pool;
    size_t max_size;
    size_t current_pos;
} MemoryPool;

MemoryPool* createMemoryPool(size_t item_count, size_t max_data_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->max_size = item_count * (sizeof(dataItem) + max_data_size);
    mp->pool = malloc(mp->max_size);
    mp->current_pos = 0;
    return mp;
}

void* poolAllocate(MemoryPool *mp, size_t size) {
    if (mp->current_pos + size > mp->max_size) {
        fprintf(stderr, "Memory Pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    void *ptr = mp->pool + mp->current_pos;
    mp->current_pos += size;
    return ptr;
}

void freeMemoryPool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

// Mutex for synchronizing access to the hash table.
pthread_mutex_t hashMutex = PTHREAD_MUTEX_INITIALIZER;

dataItem* initializeCollection(size_t item_count, size_t max_data_size) {
    MemoryPool *memory_pool = createMemoryPool(item_count, max_data_size);

    dataItem *collection = poolAllocate(memory_pool, sizeof(dataItem) * item_count);

    pthread_t threads[4];
    int thread_part = item_count / 4;
    for (int i = 0; i < 4; ++i) {
        size_t start_index = i * thread_part;
        size_t end_index = (i == 3) ? item_count : start_index + thread_part;

        pthread_create(&threads[i], NULL, [](void* arg) -> void* {
            auto args = static_cast<struct {
                dataItem* collection;
                MemoryPool* memory_pool;
                size_t start_index;
                size_t end_index;
                size_t max_data_size;
            }*>(arg);

            for (size_t j = args->start_index; j < args->end_index; ++j) {
                pthread_mutex_lock(&hashMutex);
                size_t id;
                do {
                    id = rand() % 1000000 + 1;
                } while (!isIdUnique(id));
                addIdToHashTable(id);
                pthread_mutex_unlock(&hashMutex);

                dataItem *item = &args->collection[j];
                item->id = id;
                item->data = poolAllocate(args->memory_pool, max_data_size);
                item->timestamp = (uint32_t)time(NULL);
            }
            return NULL;
        }, new struct {
            dataItem* collection;
            MemoryPool* memory_pool;
            size_t start_index;
            size_t end_index;
            size_t max_data_size;
        }{collection, memory_pool, start_index, end_index, max_data_size});
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return collection;
}

void freeCollection(dataItem *collection, size_t item_count) {
    MemoryPool *memory_pool = (MemoryPool*)collection - 1; // Assuming pool is just before the first dataItem.
    for (size_t i = 0; i < item_count; ++i) {
        free(collection[i].data);
    }
    freeMemoryPool(memory_pool);
}

