// Global variables for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(log_level_t level, const char *message) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("crypto.log", "a");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_lock(&mutex);
    switch (level) {
        case LOG_ERROR:
            fprintf(log_file, "ERROR: %s\n", message);
            break;
        case LOG_INFO:
            fprintf(log_file, "INFO: %s\n", message);
            break;
    }
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
}

int initialize_data_structures_and_cryptography(
    size_t key_array_size,
    char *error_buffer,
    size_t error_buffer_size,
    int max_records_config,
    log_level_t verbosity
) {
    if (key_array_size == 0 || max_records_config <= 0 || max_records_config > MAX_RECORDS) {
        const char *default_error = "Invalid configuration parameters.";
        strncpy(error_buffer, default_error, error_buffer_size - 1);
        error_buffer[error_buffer_size - 1] = '\0';
        log_message(LOG_ERROR, default_error);
        return EXIT_FAILURE;
    }

    size_t offset_array_size = key_array_size * 2;

    // Dynamic memory allocation
    long *offsets = (long *)malloc(offset_array_size * sizeof(long));
    int *keys = (int *)malloc(key_array_size * sizeof(int));
    record_t *records = (record_t *)malloc(max_records_config * sizeof(record_t));
    unsigned short *status_flags = (unsigned short *)malloc(max_records_config * sizeof(unsigned short));

    // Check for allocation failures
    if (!offsets || !keys || !records || !status_flags) {
        const char *alloc_error = "Memory allocation failed.";
        strncpy(error_buffer, alloc_error, error_buffer_size - 1);
        error_buffer[error_buffer_size - 1] = '\0';

        log_message(LOG_ERROR, alloc_error);

        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) free(records);
        if (status_flags) free(status_flags);

        return EXIT_FAILURE;
    }

    // Initialize arrays
    for (size_t i = 0; i < offset_array_size; ++i) {
        offsets[i] = rand() % 1000;  // Example range, modify as needed
    }

    for (size_t i = 0; i < key_array_size; ++i) {
        keys[i] = rand() % 1000;  // Example range, modify as needed
    }

    for (size_t i = 0; i < max_records_config; ++i) {
        records[i].value = rand() % 1000;  // Example range, modify as needed
        status_flags[i] = rand() % USHRT_MAX;
    }

    if (verbosity == LOG_INFO) {
        log_message(LOG_INFO, "Data structures initialized successfully.");
    }

    return EXIT_SUCCESS;
}
