#include <iostream>
#include <vector>
#include <unordered_map>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>

class ResourceManager {
public:
    struct Resource {
        int id;
        std::chrono::steady_clock::time_point timeout;
        bool available;

        Resource(int _id, int _timeout) 
            : id(_id), timeout(std::chrono::steady_clock::now() + std::chrono::seconds(_timeout)), available(true) {}
    };

private:
    std::unordered_map<int, std::shared_ptr<Resource>> resources;
    std::mutex mtx;
    std::condition_variable cv;
    int maxPoolSize;
    std::atomic<int> currentUsage{0};

public:
    ResourceManager(int initialLimit)
        : maxPoolSize(initialLimit) {
        for (int i = 1; i <= initialLimit; ++i) {
            resources.emplace(i, std::make_shared<Resource>(i, 30)); // Example timeout of 30 seconds
        }
    }

    std::shared_ptr<Resource> allocateResource() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return currentUsage < maxPoolSize; });

        for (auto& pair : resources) {
            if (pair.second->available && 
                std::chrono::steady_clock::now() <= pair.second->timeout) {

                pair.second->available = false;
                ++currentUsage;
                lock.unlock();
                return pair.second;
            }
        }

        // If no resource is available, create a new one if possible
        if (currentUsage < maxPoolSize) {
            int newId = resources.size() + 1;
            auto newResource = std::make_shared<Resource>(newId, 30); // Example timeout of 30 seconds
            resources[newId] = newResource;
            newResource->available = false;
            ++currentUsage;

            lock.unlock();
            return newResource;
        }

        // If no resources are available and maxPoolSize is reached
        return nullptr;
    }

    void returnResource(int resourceId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (resources.find(resourceId) != resources.end()) {
            auto& resource = resources[resourceId];
            if (!resource->available) {
                resource->available = true;
                cv.notify_one();
                --currentUsage;
            }
        }
    }

    void adjustPoolSize(int newSize) {
        std::lock_guard<std::mutex> lock(mtx);
        maxPoolSize = newSize;
        cv.notify_all(); // In case the pool size was increased
    }

    void monitorAndAdjust() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(10)); // Example monitoring interval

            int currentLoad = currentUsage.load();
            int newPoolSize = calculateOptimalPoolSize(currentLoad);

            adjustPoolSize(newPoolSize);
        }
    }

private:
    int calculateOptimalPoolSize(int currentLoad) {
        // Placeholder for a more sophisticated algorithm
        if (currentLoad > maxPoolSize * 0.8) {
            return maxPoolSize + 10; // Example increment
        } else if (currentLoad < maxPoolSize * 0.5 && maxPoolSize > 10) {
            return maxPoolSize - 10; // Example decrement
        }
        return maxPoolSize;
    }
};

int main() {
    ResourceManager rm(50); // Initialize with a pool size of 50

    std::thread monitorThread(&ResourceManager::monitorAndAdjust, &rm);

    // Simulate resource allocation and release in multiple threads
    std::vector<std::thread> threads;
    for (int i = 0; i < 100; ++i) {
        threads.emplace_back([&rm] {
            auto res = rm.allocateResource();
            if (res) {
                std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate work
                rm.returnResource(res->id);
            }
        });
    }

    for (auto& t : threads) {
        t.join();
    }

    monitorThread.detach(); // Continue monitoring in background

    return 0;
}
