// Define structure types
typedef struct {
    // Example fields; actual field definitions depend on specifications
    int valid;
} RX_UE_INFORMATION_TAG;

typedef uint16_t RNTI_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI_T rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool manager definition
typedef struct MemoryPool {
    size_t element_size;
    void* elements;
    size_t total_elements;
    size_t used_elements;
    pthread_mutex_t lock; // For thread safety during allocations
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t max_elements) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->elements = malloc(element_size * max_elements);
    if (!pool->elements) {
        free(pool);
        return NULL;
    }

    pool->total_elements = max_elements;
    pool->used_elements = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_elements >= pool->total_elements) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }

    void* ptr = (char*)pool->elements + (pool->used_elements * pool->element_size);
    pool->used_elements++;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void memory_pool_free(MemoryPool* pool) {
    free(pool->elements);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Function to manage NFAPI_CRC_INDICATION_PDU_T list
typedef struct {
    MemoryPool* mem_pool;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t max_size;
    pthread_rwlock_t lock; // Read-write lock for concurrent access
} NFAPI_CRC_MANAGEMENT;

NFAPI_CRC_MANAGEMENT* nfaapi_crc_management_create(size_t max_size) {
    MemoryPool* mem_pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), max_size);
    if (!mem_pool) return NULL;

    NFAPI_CRC_MANAGEMENT* management = (NFAPI_CRC_MANAGEMENT*)malloc(sizeof(NFAPI_CRC_MANAGEMENT));
    if (!management) {
        memory_pool_free(mem_pool);
        return NULL;
    }

    management->mem_pool = mem_pool;
    management->pdu_list = NULL; // Initially empty
    management->max_size = max_size;
    pthread_rwlock_init(&management->lock, NULL);

    return management;
}

bool nfaapi_crc_management_add(NFAPI_CRC_MANAGEMENT* management, RX_UE_INFORMATION_TAG tag, RNTI_T rnti) {
    pthread_rwlock_wrlock(&management->lock);

    if (management->pdu_list && management->max_size > 0) {
        for (size_t i = 0; i < management->max_size; ++i) {
            if (management->pdu_list[i].rnti == rnti)
                goto unlock_and_return_false; // RNTI must be unique
        }
    }

    void* new_pdu = memory_pool_alloc(management->mem_pool);
    if (!new_pdu) {
        pthread_rwlock_unlock(&management->lock);
        return false; // Allocation failed
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)new_pdu;
    pdu->rx_ue_information_tag = tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (!management->pdu_list) {
        management->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)new_pdu;
    } else {
        size_t current_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * management->max_size;
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(management->pdu_list, current_size + sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_rwlock_unlock(&management->lock);
            return false; // Reallocation failed
        }

        management->pdu_list = new_list;
        management->pdu_list[management->max_size] = *pdu;
    }

unlock_and_return_true:
    pthread_rwlock_unlock(&management->lock);
    return true;

unlock_and_return_false:
    pthread_rwlock_unlock(&management->lock);
    return false;
}

void nfaapi_crc_management_destroy(NFAPI_CRC_MANAGEMENT* management) {
    if (management) {
        free(management->pdu_list);
        memory_pool_free(management->mem_pool);
        pthread_rwlock_destroy(&management->lock);
        free(management);
    }
}
