static void serializeToJson(ConfigManager *manager, json_t **jsonArray);

void initializeNetworkConfigurationManager(ConfigManager **manager) {
    if (!manager || !(*manager = malloc(sizeof(ConfigManager)))) {
        fprintf(stderr, "Failed to allocate memory for ConfigManager\n");
        return;
    }
    memset((*manager)->configs, 0, sizeof(NetworkConfig) * MAX_NODES);
