    if ((*manager)->count < MAX_NODES && validateConfiguration(&dummy)) {
        memcpy(&((*manager)->configs[(*manager)->count++]), &dummy, sizeof(NetworkConfig));
    }
}

static int validateConfiguration(const NetworkConfig *config) {
    if (config->bandwidth > MAX_BANDWIDTH || strlen(config->encryption_key) >= MAX_KEY_LENGTH) {
        return 0;
    }
    return 1;
}

void serializeToJson(ConfigManager *manager, json_t **jsonArray) {
    pthread_mutex_lock(&manager->mutex);

    *jsonArray = json_array();
    for (size_t i = 0; i < manager->count; ++i) {
        json_t *configJson = json_pack("{si:s?s}",
                                       "id", manager->configs[i].id,
                                       "bandwidth", manager->configs[i].bandwidth,
                                       "qos_policy", manager->configs[i].qos_policy,
                                       "encryption_key", manager->configs[i].encryption_key);
        if (configJson) {
            json_array_append_new(*jsonArray, configJson);
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void destroyNetworkConfigurationManager(ConfigManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Example unit test function for demonstration
