#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

// Define constants for the radio channel model
#define NUM_MESSAGES 1000

// Structures to represent various network protocol units
typedef struct {
    uint16_t rx_ue_information_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint32_t rnti;
} RNTI;

typedef struct {
    int crc_flag; // Assume a simple integer for CRC flag, could be expanded.
} CRC_INDICATION_REL8_TAG;

typedef struct {
    float snr_value;
} SNR_INDICATION_REL8_TAG;

typedef struct NFAPI_MESSAGE_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    SNR_INDICATION_REL8_TAG snr_indication_rel8_tag;
} NFAPI_MESSAGE_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next; // Pointer to the next node
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void initialize_messages(NFAPI_MESSAGE_PDU_T messages[], size_t num_messages);
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(uint16_t tag, uint32_t rnti, int crc_flag);
void append_crc_indication(pthread_mutex_t *mutex, pthread_cond_t *cond, NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *node);
void free_crc_list(NFAPI_CRC_INDICATION_PDU_T *head);

// Simulated radio channel SNR calculation
static float calculate_snr() {
    // Simple random noise model for demonstration purposes
    return (float)(rand() % 100) / 10.0 - 5.0; // Random value between -5 and 9.9
}

void initialize_messages(NFAPI_MESSAGE_PDU_T messages[], size_t num_messages) {
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_messages; ++i) {
        messages[i].rx_ue_information_tag.rx_ue_information_tag = rand() % 1024;
        messages[i].rnti.rnti = rand();
        messages[i].crc_indication_rel8_tag.crc_flag = rand() % 2; // Random CRC flag
        messages[i].snr_indication_rel8_tag.snr_value = calculate_snr(); // Calculate SNR
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(uint16_t tag, uint32_t rnti, int crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        perror("Memory allocation failed");
        return NULL;
    }

    node->rx_ue_information_tag.rx_ue_information_tag = tag;
    node->rnti.rnti = rnti;
    node->crc_indication_rel8_tag.crc_flag = crc_flag;
    node->next = NULL;

    return node;
}

void append_crc_indication(pthread_mutex_t *mutex, pthread_cond_t *cond, NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *node) {
    if (!node) return;

    pthread_mutex_lock(mutex);
    if (*head == NULL) {
        *head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_cond_signal(cond);
    pthread_mutex_unlock(mutex);
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *temp;

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Example logging function
static void log_crc_indication(NFAPI_CRC_INDICATION_PDU_T* node) {
    printf("CRC Indication: RX_UE_TAG=%u, RNTI=0x%08X, CRC_FLAG=%d\n",
           node->rx_ue_information_tag.rx_ue_information_tag,
           node->rnti.rnti,
           node->crc_indication_rel8_tag.crc_flag);
}

int main() {
    // Initialize the message array
    NFAPI_MESSAGE_PDU_T messages[NUM_MESSAGES];
    initialize_messages(messages, NUM_MESSAGES);

    // Initialize synchronization primitives for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Create a linked list of CRC indications
    NFAPI_CRC_INDICATION_PDU_T *crc_list_head = NULL;

    // Simulate populating the list with random data (in a real scenario, this would be driven by network events)
    for (int i = 0; i < NUM_MESSAGES; ++i) {
        uint16_t tag = messages[i].rx_ue_information_tag.rx_ue_information_tag;
        uint32_t rnti = messages[i].rnti.rnti;
        int crc_flag = messages[i].crc_indication_rel8_tag.crc_flag;

        NFAPI_CRC_INDICATION_PDU_T *node = create_crc_indication(tag, rnti, crc_flag);
        append_crc_indication(&mutex, &cond, &crc_list_head, node);

        // Optional: Log CRC indication for monitoring
        log_crc_indication(node);
    }

    // Free the linked list memory
    free_crc_list(crc_list_head);

    return 0;
}
