    free(integerArray);
    free(processedStr);
    free(structures);

    return processedStr;
}

void handleMemoryAllocationFailure(void *ptr) {
    if (ptr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
}

int readIntegersFromCSV(const char *filePath, int **array, size_t *size) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Unable to open file");
        return 0;
    }

    size_t capacity = 10;
    *array = malloc(capacity * sizeof(int));
    handleMemoryAllocationFailure(*array);

    int value;
    size_t count = 0;

    while (fscanf(file, "%d,", &value) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            *array = realloc(*array, capacity * sizeof(int));
            handleMemoryAllocationFailure(*array);
        }

        if (value < 0 || value > MAX_INT_RANGE) continue;

        int exists = 0;
        for (size_t i = 0; i < count; i++) {
            if ((*array)[i] == value) {
                exists = 1;
                break;
            }
        }

        if (!exists) {
            (*array)[count++] = value;
        }
    }

    *size = count;

    fclose(file);
    return 1;
