        perror("Encryption failed");
        fclose(file);
        return;
    }

    fwrite(outbuf, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    EVP_CIPHER_CTX_free(ctx);
    free(outbuf);
