#include <openssl/rand.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

#define LOG_BUFFER_SIZE 256
#define KEY_SIZE 32
#define RECORD_COUNT 1000

// Semaphore for concurrency control
sem_t semaphore;

void log_message(const char *message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

void cleanup(void *offset_array, void *key_array, record *records) {
    free(offset_array);
    free(key_array);
    free(records);
    sem_destroy(&semaphore);
}

int generate_random_keys(unsigned char *key, int key_size) {
    if (!RAND_bytes(key, key_size)) {
        return 0;
    }
    return 1;
}

int create_records_and_arrays(long **offset_array, int **key_array, record **records,
                              unsigned long count, unsigned char algorithm, int key_size) {
    sem_init(&semaphore, 0, 1);
    *offset_array = malloc(count * sizeof(long));
    *key_array = malloc(count * sizeof(int));
    *records = malloc(count * sizeof(record));

    if (!*offset_array || !*key_array || !*records) {
        cleanup(*offset_array, *key_array, *records);
        return -1;
    }

    // Seed random number generator for reproducibility
    srand(time(NULL) ^ pthread_self());

    unsigned char key[KEY_SIZE];
    if (!generate_random_keys(key, key_size)) {
        log_message("Error generating cryptographic keys");
        cleanup(*offset_array, *key_array, *records);
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message("Error creating cipher context");
        cleanup(*offset_array, *key_array, *records);
        return -1;
    }

    switch (algorithm) {
        case 1: // AES
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, key + 16)) {
                log_message("Error initializing AES encryption");
                cleanup(*offset_array, *key_array, *records);
                return -1;
            }
            break;
        case 2: // Camellia
            if (!EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, key + 16)) {
                log_message("Error initializing Camellia encryption");
                cleanup(*offset_array, *key_array, *records);
                return -1;
            }
            break;
        default:
            log_message("Unsupported algorithm");
            cleanup(*offset_array, *key_array, *records);
            return -1;
    }

    for (unsigned long i = 0; i < count; ++i) {
        sem_wait(&semaphore);

        (*offset_array)[i] = rand();
        (*key_array)[i] = rand() % 100;

        record new_record;
        new_record.offset = rand();
        new_record.key = rand() % 100;
        new_record.value = (double)rand() / RAND_MAX;

        memcpy(&(*records)[i], &new_record, sizeof(record));

        sem_post(&semaphore);
    }

    EVP_CIPHER_CTX_free(ctx);
    log_message("Records and arrays created successfully");
    return 0;
}

int main() {
    long *offset_array = NULL;
    int *key_array = NULL;
    record *records = NULL;

    if (create_records_and_arrays(&offset_array, &key_array, &records, RECORD_COUNT, 1, KEY_SIZE) != 0) {
        log_message("Failed to create records and arrays");
        return EXIT_FAILURE;
    }

    // Perform data processing here...

    cleanup(offset_array, key_array, records);
    return EXIT_SUCCESS;
}
```

