typedef struct record {
    long *offset_ptr;
    int key;
    struct record *next;
} record_t;

typedef struct hash_table_node {
    record_t *record;
    struct hash_table_node *next;
} hash_table_node_t;

typedef struct {
    hash_table_node_t **buckets;
    size_t size;
    pthread_mutex_t lock;
} hash_table_t;

long resource_offsets[MAX_RESOURCES] = {0};

void init_resources() {
    for (int i = 0; i < MAX_RESOURCES; ++i) {
        resource_offsets[i] = i;
    }
}

unsigned int hash_function(int key, size_t table_size) {
    return key % table_size;
}

hash_table_t* create_hash_table(size_t size) {
    hash_table_t *table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->buckets = calloc(size, sizeof(hash_table_node_t*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = size;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->size; ++i) {
        hash_table_node_t *node = table->buckets[i];
        while (node) {
            hash_table_node_t *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void insert_record(hash_table_t *table, record_t *record) {
    unsigned int index = hash_function(record->key, table->size);

    pthread_mutex_lock(&table->lock);
    hash_table_node_t *new_node = malloc(sizeof(hash_table_node_t));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }
    new_node->record = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
}

void delete_record(hash_table_t *table, int key) {
    unsigned int index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);
    hash_table_node_t *node = table->buckets[index];
    hash_table_node_t *prev = NULL;
    while (node && node->record->key != key) {
        prev = node;
        node = node->next;
    }
    if (node) {
        if (prev) {
            prev->next = node->next;
        } else {
            table->buckets[index] = node->next;
        }
        free(node);
    }
    pthread_mutex_unlock(&table->lock);
}

record_t* find_record(hash_table_t *table, int key) {
    unsigned int index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);
    hash_table_node_t *node = table->buckets[index];
    while (node && node->record->key != key) {
        node = node->next;
    }
    record_t *result = node ? node->record : NULL;
    pthread_mutex_unlock(&table->lock);

    return result;
}

void initialize_and_populate_array(int num_records, NFAPI_MESSAGE_PDU_T_Extended *array) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        array[i].offset = resource_offsets[i % MAX_RESOURCES];
        // Populate other fields as needed
        array[i].snr_indication.SNR = rand() % 100 + 1; // Simulate SNR values
    }
}

int main() {
    int num_keys;
    printf("Enter number of keys: ");
    scanf("%d", &num_keys);

    if (num_keys <= 0) return 1;

    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) return 1;

    printf("Enter %d unique keys (0 to 65535): \n", num_keys);
    for (int i = 0; i < num_keys; ++i) {
        scanf("%d", &keys[i]);
        if (keys[i] < 0 || keys[i] > KEY_MAX) {
            fprintf(stderr, "Invalid key: %d\n", keys[i]);
            free(keys);
            return 1;
        }
    }

    hash_table_t *hash_table = create_hash_table(1024);
    if (!hash_table) {
        free(keys);
        return 1;
    }

    record_t *records[num_keys];
    for (int i = 0; i < num_keys; ++i) {
        int key = keys[i];
        if (find_record(hash_table, key)) {
            fprintf(stderr, "Duplicate key: %d\n", key);
            destroy_hash_table(hash_table);
            free(keys);
            return 1;
        }

        record_t *record = malloc(sizeof(record_t));
        if (!record) {
            for (int j = 0; j < i; ++j) delete_record(hash_table, keys[j]);
            destroy_hash_table(hash_table);
            free(keys);
            return 1;
        }
        record->offset_ptr = &resource_offsets[i % MAX_RESOURCES];
        record->key = key;
        record->next = NULL;

        records[i] = record;
        insert_record(hash_table, record);
    }

    int max_key = keys[0];
    for (int i = 1; i < num_keys; ++i) {
        if (keys[i] > max_key) max_key = keys[i];
    }
    printf("Max key: %d\n", max_key);

    destroy_hash_table(hash_table);
    free(keys);

    return 0;
}
