    printf("Avg Throughput: %.2f Mbps\n", avg_throughput);
    printf("Min Throughput: %.2f Mbps\n", min_throughput);
    printf("Max Throughput: %.2f Mbps\n", max_throughput);

    pthread_rwlock_unlock(&manager->lock);
}

void *network_update_thread(void *arg) {
    NetworkChannelManager *manager = (NetworkChannelManager *)arg;
    while (1) {
        update_metrics(manager);
        sleep(5);  // Simulate periodic updates every 5 seconds
    }
    return NULL;
}

int main() {
    size_t max_channels = MAX_CHANNELS;  // Could be dynamic based on requirements

    NetworkChannelManager manager;
    initialize_network_channel_manager(&manager, max_channels);

    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, network_update_thread, &manager) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    // Simulate running for some time
    sleep(30);  // Main program runs for 30 seconds

    pthread_cancel(update_thread);
    pthread_join(update_thread, NULL);

    cleanup_network_channel_manager(&manager);

    return 0;
}
```

