#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

// Mutex for thread-safe operations on records
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory and initialize arrays
Record* create_and_initialize_records(size_t num_records, const long offsets[], const int keys[], const double values[]) {
    if (num_records == 0 || !offsets || !keys || !values) return NULL;

    // Allocate memory for records
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize each record
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];
    }

    return records;
}

// Logging mechanism with buffered output to minimize I/O overhead
void log_records(const char *filename, const Record *records, size_t num_records) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open file for logging");
        return;
    }

    // Buffer the logs
    static char buffer[1024];
    size_t pos = 0;

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_records; ++i) {
        pos += snprintf(buffer + pos, sizeof(buffer) - pos, "Offset: %ld, Key: %d, Value: %.2f\n",
                        records[i].offset, records[i].key, records[i].value);

        // Write buffer to file when full or at end
        if (pos >= sizeof(buffer)) {
            fwrite(buffer, 1, pos, file);
            pos = 0;
        }
    }

    if (pos > 0) { // Flush remaining buffer content
        fwrite(buffer, 1, pos, file);
    }

    fclose(file);
    pthread_mutex_unlock(&mutex);
}

// Function to clean up allocated memory
void free_records(Record *records) {
    free(records);
}

// Sample usage of the above functions in a multi-threaded context
void* thread_function(void *arg) {
    size_t num_records = *(size_t*)arg;

    // Example initial values (in practice, provide these dynamically)
    long offsets[] = {1L, 2L, 3L}; 
    int keys[] = {100, 200, 300};
    double values[] = {1.0, 2.0, 3.0};

    Record *records = create_and_initialize_records(num_records, offsets, keys, values);
    if (records) {
        log_records("record_log.txt", records, num_records);
        free_records(records);
    }

    return NULL;
}

int main() {
    pthread_t threads[2];
    size_t num_records = 3;

    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &num_records);
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

