#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>
#include <string.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int executeCommand(const char *command) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    } else if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        exit(EXIT_FAILURE); // If execl returns, it must have failed
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : -1;
    }
}

int generateNfaReports(NFAPI_CRC_INDICATION_PDU_T *reports, size_t num_reports, const char *command) {
    if (num_reports > MAX_STRUCTURES) {
        fprintf(stderr, "Error: Number of reports exceeds maximum limit\n");
        return 0;
    }

    // Generate structures
    for (size_t i = 0; i < num_reports; ++i) {
        reports[i].rx_ue_info_tag.RNTI = rand() % UINT32_MAX; // Random RNTI
        reports[i].crc_indication_rel8_tag.CRCFLAG = 0; // Initially unset CRCFLAG
    }

    // Execute command asynchronously and update CRCFLAG
    int result = executeCommand(command);
    if (result == 1) {
        for (size_t i = 0; i < num_reports; ++i) {
            reports[i].crc_indication_rel8_tag.CRCFLAG = 1; // Set CRCFLAG on success
        }
        return 1;
    } else {
        fprintf(stderr, "Command execution failed\n");
        return 0;
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T *reports = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!reports) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    const char *command = "echo 'Test Command'";
    int success = generateNfaReports(reports, 10, command);

    printf("Command execution %s\n", success ? "successful" : "failed");

    free(reports);
    return success ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

### Key Points:
- **Fork and Wait**: The function uses `fork()` to create a child process for executing the command and `waitpid()` to wait for its completion.
- **Random RNTI**: Each structure is populated with a random RNTI using `rand()`.
- **CRCFLAG Handling**: CRCFLAG is set based on the success of the command execution.
- **Error Handling**: Basic error handling is implemented for memory allocation and process creation.
- **Resource Management**: Memory allocated for structures is freed before exiting.']

