    stats->frequency++;
    stats->average = ((stats->average * (stats->frequency - 1)) + new_value) / (double)stats->frequency;
}

// Implementations
LinkedList* create_linked_list(size_t initial_capacity) {
    LinkedList *list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->nodes = calloc(initial_capacity, sizeof(Node *));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
