        if (!fgets(buffer, sizeof(buffer), stdin)) break;

        buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline
        array[i] = strdup(buffer);
    }
}

KeyTable* create_key_table(size_t capacity) {
    KeyTable *table = malloc(sizeof(KeyTable));
    if (!table) return NULL;

    table->keys = calloc(capacity, sizeof(char *));
    if (!table->keys) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

int add_key(KeyTable *table, const char *key) {
    pthread_mutex_lock(&table->lock);
    if (is_key_in_table(table, key)) {
        pthread_mutex_unlock(&table->lock);
        return 0; // Key already exists
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        if (!table->keys[i]) {
            table->keys[i] = strdup(key);
            table->size++;
            pthread_mutex_unlock(&table->lock);
            return 1;
        }
    }

    // Resize key table
    size_t new_capacity = table->capacity * 2;
    char **new_keys = realloc(table->keys, new_capacity * sizeof(char *));
    if (!new_keys) {
        pthread_mutex_unlock(&table->lock);
        return 0; // Allocation failed
    }

    for (size_t i = table->capacity; i < new_capacity; ++i) {
        new_keys[i] = NULL;
    }

    table->keys = new_keys;
    table->capacity = new_capacity;

    pthread_mutex_unlock(&table->lock);
    return add_key(table, key); // Retry adding the key
}

int is_key_in_table(KeyTable *table, const char *key) {
    for (size_t i = 0; i < table->size; ++i) {
        if (strcmp(table->keys[i], key) == 0) return 1;
    }
    return 0;
}

// Main function
