['Below is a C++ implementation of the `NetworkRecordManager` class based on your requirements:

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <random>
#include <chrono>

// Define constants for simulation
const int MAX_CONNECTIONS = 1000;
const double MIN_DOUBLE_VALUE = 0.0;
const double MAX_DOUBLE_VALUE = 1.0;

struct TCP_CONNECTION_RECORD {
    long offset;
    int key;
    double precision_value;
    std::string client_id;
    std::chrono::time_point<std::chrono::system_clock> request_timestamp;
    std::chrono::time_point<std::chrono::system_clock> last_active_timestamp;
    size_t bytes_received;
    size_t bytes_sent;

    TCP_CONNECTION_RECORD(long off, int k, double val, const std::string& cid)
        : offset(off), key(k), precision_value(val), client_id(cid),
          request_timestamp(std::chrono::system_clock::now()),
          last_active_timestamp(std::chrono::system_clock::now()),
          bytes_received(0), bytes_sent(0) {}
};

class NetworkRecordManager {
public:
    NetworkRecordManager(int max_connections);
    ~NetworkRecordManager();

    void addConnectionRecord(long offset, int key, const std::string& client_id);
    void processRecords();
    void reportStatistics() const;

private:
    void workerThread();
    double generateRandomValue(double min, double max) const;

    mutable std::mutex queue_mutex;
    std::condition_variable condition_var;
    std::queue<TCP_CONNECTION_RECORD> record_queue;
    std::vector<std::thread> workers;
    std::atomic<int> active_connections{0};
    int max_connections;

    // Statistics
    std::atomic<size_t> total_bytes_received{0};
    std::atomic<size_t> total_bytes_sent{0};
};

NetworkRecordManager::NetworkRecordManager(int max_conn) : max_connections(max_conn) {
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers.emplace_back(&NetworkRecordManager::workerThread, this);
    }
}

NetworkRecordManager::~NetworkRecordManager() {
    condition_var.notify_all();
    for (auto& worker : workers) {
        if (worker.joinable()) {
            worker.join();
        }
    }
}

void NetworkRecordManager::addConnectionRecord(long offset, int key, const std::string& client_id) {
    double random_value = generateRandomValue(MIN_DOUBLE_VALUE, MAX_DOUBLE_VALUE);

    std::lock_guard<std::mutex> lock(queue_mutex);
    if (active_connections < max_connections) {
        record_queue.emplace(offset, key, random_value, client_id);
        ++active_connections;
        condition_var.notify_one();
    }
}

void NetworkRecordManager::processRecords() {
    while (true) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        condition_var.wait(lock, [this] { return !record_queue.empty(); });

        TCP_CONNECTION_RECORD record = record_queue.front();
        record_queue.pop();
        --active_connections;

        // Simulate network latency and packet loss
        simulateNetworkConditions(record);

        lock.unlock();

        std::lock_guard<std::mutex> stats_lock(stats_mutex);
        total_bytes_received += record.bytes_received;
        total_bytes_sent += record.bytes_sent;
    }
}

void NetworkRecordManager::reportStatistics() const {
    std::lock_guard<std::mutex> lock(queue_mutex);
    size_t avg_bytes_received = total_bytes_received / active_connections;
    size_t min_bytes_received = 0; // Implement logic to find minimum
    size_t max_bytes_received = 0; // Implement logic to find maximum

    std::cout << "Average Bytes Received: " << avg_bytes_received << "\n";
    std::cout << "Min Bytes Received: " << min_bytes_received << "\n";
    std::cout << "Max Bytes Received: " << max_bytes_received << "\n";

    // Repeat for bytes sent
}

double NetworkRecordManager::generateRandomValue(double min, double max) const {
    static std::mt19937 generator(std::random_device{}());
    std::uniform_real_distribution<double> distribution(min, max);
    return distribution(generator);
}

void NetworkRecordManager::workerThread() {
    while (true) {
        processRecords();
    }
}

void NetworkRecordManager::simulateNetworkConditions(TCP_CONNECTION_RECORD& record) {
    // Simulate network latency and packet loss
    std::this_thread::sleep_for(std::chrono::milliseconds(50));

    // Update bytes received/sent to simulate real-world conditions
    record.bytes_received += (std::rand() % 1000);
    record.bytes_sent += (std::rand() % 1000);

    // Update last active timestamp
    record.last_active_timestamp = std::chrono::system_clock::now();
}

int main() {
    NetworkRecordManager manager(MAX_CONNECTIONS);

    // Simulate adding records
    for (int i = 0; i < 100; ++i) {
        manager.addConnectionRecord(i, i * 10, "Client_" + std::to_string(i));
    }

    // Allow some time for processing
    std::this_thread::sleep_for(std::chrono::seconds(5));

    manager.reportStatistics();

    return 0;
}
```

