// Get buffer from pool, resize if necessary
MAC_RX_BUFFER_T* get_buffer_from_pool(MAC_RX_BUFFER_T** pool, size_t current_size) {
    static const size_t growth_factor = 2;
    if (!*pool || current_size >= (*pool)[0]) { // Assuming first element is a reserved header for count
        size_t new_size = (current_size + 1) * growth_factor;
        MAC_RX_BUFFER_T* new_pool = realloc(*pool, sizeof(MAC_RX_BUFFER_T) * new_size);

        if (!new_pool) {
            log_message("Failed to reallocate memory for the buffer pool.");
            return NULL;
        }

        memset(new_pool + current_size, 0, sizeof(MAC_RX_BUFFER_T) * (new_size - current_size));
        (*pool)[0] = new_size; // Update reserved count header
        *pool = new_pool;
    }

    return &((*pool)[++(*(*pool))] );
}

