    if (!buffer) {
        log_message("Failed to acquire buffer from the pool.");
        return;
    }

    // Simulate extracting headers and metadata
    memcpy(&buffer->l1_header.timestamp, packet_data, sizeof(buffer->l1_header));
    memcpy(&buffer->phy_header, (char*)packet_data + sizeof(buffer->l1_header), data_length - sizeof(buffer->l1_header));

    if (validate_packet(&buffer->l1_header, &buffer->phy_header)) {
        process_packet(buffer);
        log_message("Packet processed successfully.");
    } else {
        log_message("Invalid packet encountered.");
    }

    (*current_size)++;
}

