#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct WeatherObservation {
    int timestamp; // e.g., Unix time in seconds
    float temperature;
    float humidity;
    float atmospheric_pressure;
    struct WeatherObservation* next;
} WeatherObservation;

// Function to calculate the average of valid floating-point numbers
float calculate_average(float *numbers, size_t count) {
    if (count == 0) return 0.0f;

    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    return sum / count;
}

// Function to read and validate floating-point numbers from stdin
void read_and_validate_numbers(float *numbers, size_t max_count, float min_val, float max_val, int precision, size_t *count) {
    char buffer[256];
    float number;
    *count = 0;

    while (*count < max_count && fgets(buffer, sizeof(buffer), stdin)) {
        if (sscanf(buffer, "%f", &number) == 1 && 
            number >= min_val && number <= max_val && 
            modf(number, &(float){.5}) < pow(10, -precision)) {

            numbers[(*count)++] = number;
        } else {
            fprintf(stderr, "Invalid input: %s\n", buffer);
        }
    }
}

// Function to create a new WeatherObservation node
WeatherObservation* create_node(int timestamp, float temperature, float humidity, float pressure) {
    WeatherObservation* new_node = (WeatherObservation*)malloc(sizeof(WeatherObservation));
    if (!new_node) {
        perror("Failed to allocate memory for weather observation");
        exit(EXIT_FAILURE);
    }

    new_node->timestamp = timestamp;
    new_node->temperature = temperature;
    new_node->humidity = humidity;
    new_node->atmospheric_pressure = pressure;
    new_node->next = NULL;

    return new_node;
}

// Function to insert a node into the linked list
void insert_observation(WeatherObservation **head, int timestamp, float temperature, float humidity, float pressure) {
    WeatherObservation* new_node = create_node(timestamp, temperature, humidity, pressure);

    if (*head == NULL || (*head)->timestamp > timestamp) {
        new_node->next = *head;
        *head = new_node;
    } else {
        WeatherObservation* current = *head;
        while (current->next != NULL && current->next->timestamp < timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Function to free the linked list
void free_observations(WeatherObservation *head) {
    WeatherObservation* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Function to read weather data from a CSV file and populate the linked list
int read_weather_data_from_csv(const char *filename, WeatherObservation **head) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    int timestamp;
    float temperature, humidity, pressure;
    char line[256];

    while (fgets(line, sizeof(line), file)) {
        // Skip empty lines and comments
        if (line[0] == '\n' || line[0] == '#') continue;

        if (sscanf(line, "%d,%f,%f,%f", &timestamp, &temperature, &humidity, &pressure) != 4) {
            fprintf(stderr, "Malformed data: %s\n", line);
            continue;
        }

        insert_observation(head, timestamp, temperature, humidity, pressure);
    }

    fclose(file);
    return 0;
}

// Function to traverse and print the linked list
void print_observations(WeatherObservation *head) {
    WeatherObservation* current = head;
    while (current != NULL) {
        printf("Timestamp: %d, Temperature: %.2f, Humidity: %.2f, Pressure: %.2f\n",
               current->timestamp,
               current->temperature,
               current->humidity,
               current->atmospheric_pressure);
        current = current->next;
    }
}

int main() {
    float numbers[100];
    size_t valid_count;

    read_and_validate_numbers(numbers, 100, -50.0f, 50.0f, 2, &valid_count);

    if (valid_count > 0) {
        printf("Average: %.2f\n", calculate_average(numbers, valid_count));
    } else {
        fprintf(stderr, "No valid numbers entered.\n");
    }

    WeatherObservation* weather_data = NULL;

    if (read_weather_data_from_csv("weather.csv", &weather_data) == 0) {
        print_observations(weather_data);
        free_observations(weather_data);
    } else {
        fprintf(stderr, "Failed to read weather data.\n");
    }

    return 0;
}
```

