```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    int value;
    Offset *offset_ptr;
} Record;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}

void manage_memory(int n_offsets, int n_records, int seed, int log_level, size_t max_memory_usage) {
    if (log_level > 0) {
        log_message("Starting memory management...\n");
    }

    // Calculate maximum memory usage per structure
    size_t offset_size = sizeof(Offset);
    size_t key_size = sizeof(Key);
    size_t record_size = sizeof(Record);

    Offset *offsets = NULL;
    Key *keys = NULL;
    Record *records = NULL;

    // Allocate and initialize offsets
    if (n_offsets > 0) {
        offsets = (Offset *)aligned_alloc(alignof(long), n_offsets * offset_size);
        if (!offsets) {
            log_message("Failed to allocate memory for offsets.\n");
            goto cleanup;
        }
        for (int i = 0; i < n_offsets; ++i) {
            offsets[i].offset = i;
        }
    }

    // Allocate and initialize keys
    if (n_offsets > 0) {
        keys = (Key *)aligned_alloc(alignof(int), n_offsets * key_size);
        if (!keys) {
            log_message("Failed to allocate memory for keys.\n");
            goto cleanup;
        }
        for (int i = 0; i < n_offsets; ++i) {
            keys[i].key = i;
        }
    }

    // Allocate and initialize records
    if (n_records > 0) {
        records = (Record *)aligned_alloc(alignof(int), n_records * record_size);
        if (!records) {
            log_message("Failed to allocate memory for records.\n");
            goto cleanup;
        }
        srand(seed);
        int min_value = 1, max_value = 100;
        for (int i = 0; i < n_records; ++i) {
            records[i].value = min_value + rand() % (max_value - min_value + 1);
            if (i < n_offsets) {
                records[i].offset_ptr = &offsets[i];
            } else {
                records[i].offset_ptr = NULL;
            }
        }
    }

    // Log memory usage
    size_t total_memory_usage = (offsets ? n_offsets * offset_size : 0) +
                                (keys ? n_offsets * key_size : 0) +
                                (records ? n_records * record_size : 0);
    if (log_level > 1) {
        log_message("Total memory usage: %zu bytes\n", total_memory_usage);
    }

    // Check against max memory usage
    if (total_memory_usage > max_memory_usage) {
        log_message("Memory usage exceeded the limit!\n");
    }

cleanup:
    if (log_level > 0) {
        log_message("Cleaning up...\n");
    }
    free(offsets);
    free(keys);
    free(records);

    if (log_level > 0) {
        log_message("Memory management completed.\n");
    }
}

int main() {
    manage_memory(10, 15, 42, 2, 1024);
    return 0;
}
```

