// Define structure for NFAPI_MESSAGE_PDU_T and other tags
typedef struct {
    unsigned int SNR;
} SNR_INDICATION_REL8_TAG;

typedef struct {
    unsigned int CRC;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
    unsigned int RX_UE_INFORMATION_TAG;
    SNR_INDICATION_REL8_TAG snr_tag;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_MESSAGE_PDU_T;

// Configuration parameters
static size_t initial_size = 10;
static double cooldown_period = 9.0; // seconds
pthread_mutex_t lock;

// Function to simulate SNR calculation
double calculate_snr(double multipath, double shadowing, double interference) {
    return multipath - shadowing + (1 / (interference + 1));
}

// Logger function with levels
void log_message(const char* level, const char* message) {
    FILE *log_file = fopen("operations.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", level, message);
        fclose(log_file);
    }
}

// Function to resize the array
NFAPI_MESSAGE_PDU_T* resize_array(NFAPI_MESSAGE_PDU_T *array, size_t *current_size, size_t new_size) {
    NFAPI_MESSAGE_PDU_T *new_array = realloc(array, new_size * sizeof(NFAPI_MESSAGE_PDU_T));
    if (new_array == NULL) {
        log_message("ERROR", "Failed to resize array");
        exit(EXIT_FAILURE);
    }
    memset(new_array + *current_size, 0, (new_size - *current_size) * sizeof(NFAPI_MESSAGE_PDU_T));
    *current_size = new_size;
    return new_array;
}

// Function to initialize and populate the array
void init_populate_nfa_message_pdu(size_t num_pdus, double multipath, double shadowing, double interference) {
    NFAPI_MESSAGE_PDU_T *array = malloc(initial_size * sizeof(NFAPI_MESSAGE_PDU_T));
    size_t current_size = initial_size;
    time_t last_operation_time = 0;

    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_mutex_lock(&lock);

        // Cooldown period enforcement
        if (difftime(time(NULL), last_operation_time) < cooldown_period) {
            sleep(cooldown_period - difftime(time(NULL), last_operation_time));
        }

        if (i >= current_size) {
            array = resize_array(array, &current_size, current_size * 2);
        }

        // Populate the NFAPI_MESSAGE_PDU_T structure
        array[i].RNTI = i;
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].snr_tag.SNR = calculate_snr(multipath, shadowing, interference);
        array[i].crc_tag.CRC = rand() % 256;

        last_operation_time = time(NULL);

        log_message("INFO", "NFAPI_MESSAGE_PDU_T structure populated");

        pthread_mutex_unlock(&lock);
    }

    // Validation mechanism (simple check)
    for (size_t i = 0; i < num_pdus; ++i) {
        if (array[i].snr_tag.SNR < 0 || array[i].snr_tag.SNR > 100) {
            log_message("ERROR", "Invalid SNR value detected");
        }
    }

    // Cleanup
    free(array);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <num_pdus> <multipath> <shadowing> <interference>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_pdus = strtoul(argv[1], NULL, 10);
    double multipath = atof(argv[2]);
    double shadowing = atof(argv[3]);
    double interference = atof(argv[4]);

    pthread_mutex_init(&lock, NULL);

    init_populate_nfa_message_pdu(num_pdus, multipath, shadowing, interference);

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
