['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 1000
#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_size) {
    if (initial_size == 0 || initial_size > MAX_ELEMENTS) {
        return NULL;
    }

    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = initial_size;
    pthread_mutex_init(&da->mutex, NULL);

    printf("Allocated memory for %zu elements.\n", da->capacity);
    return da;
}

void resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    if (new_capacity > MAX_ELEMENTS) return;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return;

    da->array = new_array;
    da->capacity = new_capacity;

    printf("Resized memory to %zu elements.\n", da->capacity);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_unlock(&da->mutex);

    pthread_mutex_destroy(&da->mutex);
    free(da);

    printf("Freed memory for dynamic array.\n");
}

int populate_array(DynamicArray *da, unsigned int seed, const char *command) {
    if (!da || da->size >= da->capacity) return 0;

    srand(seed);

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork failed");
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp("/bin/sh", "sh", "-c", command, NULL);
        _exit(EXIT_FAILURE); // Only reach this if exec fails
    }

    int status;
    waitpid(pid, &status, 0);

    pthread_mutex_lock(&da->mutex);

    for (size_t i = 0; i < da->capacity && da->size < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &da->array[i];
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            pdu->CRCFLAG = 1;
        } else {
            pdu->CRCFLAG = 0;
        }

        da->size++;
    }

    pthread_mutex_unlock(&da->mutex);

    return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
}

void save_state_to_disk(DynamicArray *da, const char *filename) {
    if (!da || !filename) return;

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), da->size, file);
    fclose(file);

    printf("State saved to %s.\n", filename);
}

void load_state_from_disk(DynamicArray *da, const char *filename) {
    if (!da || !filename) return;

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fsize % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        fprintf(stderr, "Invalid file size\n");
        fclose(file);
        return;
    }

    size_t num_elements = fsize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    resize_dynamic_array(da, num_elements);

    fread(da->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, file);
    da->size = num_elements;

    fclose(file);
    printf("State loaded from %s.\n", filename);
}

int main() {
    DynamicArray *da = create_dynamic_array(INITIAL_SIZE);
    if (!da) return EXIT_FAILURE;

    int success = populate_array(da, 12345, "echo 'Command executed'");
    if (success) {
        printf("Command executed successfully and structures populated.\n");
    } else {
        printf("Command execution failed or array not populated.\n");
    }

    save_state_to_disk(da, "state.dat");

    DynamicArray *da_loaded = create_dynamic_array(0);
    load_state_from_disk(da_loaded, "state.dat");

    free_dynamic_array(da);
    free_dynamic_array(da_loaded);

    return EXIT_SUCCESS;
}
