    const unsigned int m = 4294967296U;

    *seed = (*seed * a + c) % m; // Linear congruential generator
    return min_value + ((*seed / (double)m) * (max_value - min_value + 1));
}

void manage_memory(int n_offsets, int n_records, unsigned int seed, int log_level) {
    Offset *offsets = malloc(n_offsets * sizeof(Offset));
    Key *keys = malloc(n_offsets * sizeof(Key));
    Record *records = malloc(n_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    log_message(log_level, "Offsets and keys allocated.");

    // Global string buffer for key generation
    char global_buffer[256] = "GlobalPrefix_";

    for (int i = 0; i < n_offsets; ++i) {
        offsets[i].offset_value = custom_hash_function(i);
        snprintf(global_buffer + strlen(global_buffer), sizeof(global_buffer) - strlen(global_buffer),
                 "%ld", offsets[i].offset_value);

        keys[i].key_value = modified_hash_algorithm(global_buffer);

        log_message(log_level, "Offset and Key initialized.");
    }

    for (int i = 0; i < n_records; ++i) {
        records[i].value = custom_random(1, 100, &seed); // Example range [1, 100]

        if (i < n_offsets) {
            records[i].offset_ptr = &offsets[i];
        } else {
            records[i].offset_ptr = NULL;
        }

        log_message(log_level, "Record initialized.");
    }

    // Log completion
    log_message(log_level, "Memory management completed.");

    // Free memory after use
    free(offsets);
    free(keys);
    free(records);

    log_message(log_level, "Memory deallocated.");
}

int main() {
    int n_offsets = 10;
    int n_records = 15;
    unsigned int seed = 12345; // Example seed for reproducibility
    int log_level = 1;

    manage_memory(n_offsets, n_records, seed, log_level);

    return 0;
}
```

### Explanation:
- **Offset and Key Initialization**: Each `offset` is initialized using a custom hash function. The key generation involves concatenating the offset with a global buffer and applying another hashing algorithm.
- **Record Management**: Records are filled with random values, and their pointers to offsets are managed carefully to avoid invalid references when `n_records > n_offsets`.
- **Random Number Generation**: A simple linear congruential generator is used for reproducible pseudo-random number generation within specified ranges.
- **Logging**: Basic logging is implemented based on the `log_level`, providing insights into memory operations and structure initializations.
- **Memory Management**: Memory is dynamically allocated, initialized, and freed properly to avoid leaks. The strategy attempts to minimize fragmentation while ensuring efficient access.

This code simulates real-world engineering constraints by considering performance, maintainability, and robustness in handling dynamic sizes and operational conditions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define GROWTH_FACTOR 1.5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    unsigned long seed;
    pthread_mutex_t lock;
} DynamicArray;

void init_array(DynamicArray *dyn_array, unsigned long seed) {
    dyn_array->capacity = INITIAL_CAPACITY;
    dyn_array->count = 0;
    dyn_array->seed = seed;
    dyn_array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(dyn_array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&dyn_array->lock, NULL);
}

static unsigned long xorshift32(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13; 
    x ^= x >> 17; 
    x ^= x << 5;
    *state = x;
    return x;
}

void populate_array(DynamicArray *dyn_array, size_t n_elements) {
    pthread_mutex_lock(&dyn_array->lock);
    if (dyn_array->count + n_elements > dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity;
        while ((new_capacity - dyn_array->count) < n_elements) {
            new_capacity = (size_t)(new_capacity * GROWTH_FACTOR);
            if (new_capacity <= dyn_array->capacity) break; // Handle overflow
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&dyn_array->lock);
            return;
        }
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    for (size_t i = 0; i < n_elements; ++i) {
        size_t index = dyn_array->count + i;
        unsigned long random_value = xorshift32(&dyn_array->seed);

        dyn_array->array[index].RX_UE_INFORMATION_TAG = (int)index;
        dyn_array->array[index].RNTI = (int)(random_value % 10000);
        dyn_array->array[index].CRC_INDICATION_REL8_TAG.CRCFLAG = random_value & 1;

        printf("Allocated: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", 
               dyn_array->array[index].RX_UE_INFORMATION_TAG,
               dyn_array->array[index].RNTI,
               dyn_array->array[index].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    dyn_array->count += n_elements;
    pthread_mutex_unlock(&dyn_array->lock);
}

void serialize_array(const DynamicArray *dyn_array, const char *filename) {
    pthread_mutex_lock(&dyn_array->lock);
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_mutex_unlock(&dyn_array->lock);
        return;
    }

    size_t written = fwrite(dyn_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), dyn_array->count, file);
    if (written != dyn_array->count) {
        fprintf(stderr, "Failed to write all data\n");
    } else {
        printf("Data serialized successfully\n");
    }

    fclose(file);
    pthread_mutex_unlock(&dyn_array->lock);
}

void deserialize_array(DynamicArray *dyn_array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        fprintf(stderr, "Invalid file size\n");
        fclose(file);
        return;
    }

    size_t n_elements = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (n_elements > dyn_array->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, n_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            return;
        }
        dyn_array->array = new_array;
        dyn_array->capacity = n_elements;
    }

    size_t read = fread(dyn_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), n_elements, file);
    if (read != n_elements) {
        fprintf(stderr, "Failed to read all data\n");
    } else {
        printf("Data deserialized successfully\n");
    }

    dyn_array->count = n_elements;
    fclose(file);
}

void free_array(DynamicArray *dyn_array) {
    pthread_mutex_lock(&dyn_array->lock);
    free(dyn_array->array);
    dyn_array->array = NULL;
    dyn_array->capacity = 0;
    dyn_array->count = 0;
    pthread_mutex_unlock(&dyn_array->lock);
    pthread_mutex_destroy(&dyn_array->lock);
}

int main() {
    DynamicArray myArray;
    init_array(&myArray, 42); // Initialize with seed

    populate_array(&myArray, 5000); // Populate array
    serialize_array(&myArray, "array_data.bin"); // Serialize to file

    DynamicArray newArray;
    init_array(&newArray, 42);
    deserialize_array(&newArray, "array_data.bin"); // Deserialize from file

    free_array(&myArray);
    free_array(&newArray);

    return 0;
}
```']

