### JavaScript Function: `optimizeDOMTraversalWithConstraints`

```javascript
function optimizeDOMTraversalWithConstraints(selector, filterCallback) {
    if (!selector || typeof document.querySelector !== 'function') return [];

    const matchedNodes = [];
    const stack = [document.body];

    while (stack.length > 0) {
        const node = stack.pop();

        // Avoid revisiting nodes and push non-matching nodes' children
        if (node.matches(selector)) {
            const isMatched = filterCallback ? filterCallback(node) : true;
            if (isMatched) matchedNodes.push(node);
        }

        for (let child of node.children || []) {
            stack.push(child);
        }
    }

    return matchedNodes;
}
```

