#define MAX_UE_THRESHOLD 10

typedef struct {
    uint16_t rnti;
    int rx_snr; // SNR in dB
    double ber; // Bit Error Rate
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint8_t crc_indication_rel8_tag;
    uint8_t snr_indication_rel8_tag;
    uint8_t ber_indication_tag;
} NFAPI_MESSAGE_PDU_T;

typedef struct {
    int average_snr;
    int min_snr;
    int max_snr;
    double average_ber;
    double min_ber;
    double max_ber;
} SNR_BER_STATS;

NFAPI_MESSAGE_PDU_T* ue_array = NULL;
size_t num_ues = 0;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
SNR_BER_STATS global_stats = {0};

typedef void (*UpdateCallback)(int snr, double ber);

void update_statistics(int snr, double ber) {
    pthread_mutex_lock(&array_lock);

    global_stats.average_snr = ((global_stats.average_snr * num_ues) + snr) / (num_ues + 1);
    global_stats.min_snr = (num_ues == 0 || snr < global_stats.min_snr) ? snr : global_stats.min_snr;
    global_stats.max_snr = (num_ues == 0 || snr > global_stats.max_snr) ? snr : global_stats.max_snr;

    global_stats.average_ber = ((global_stats.average_ber * num_ues) + ber) / (num_ues + 1);
    global_stats.min_ber = (num_ues == 0 || ber < global_stats.min_ber) ? ber : global_stats.min_ber;
    global_stats.max_ber = (num_ues == 0 || ber > global_stats.max_ber) ? ber : global_stats.max_ber;

    pthread_mutex_unlock(&array_lock);
}

void init_and_populate_ue_array(size_t max_ues, UpdateCallback update_callback) {
    if (ue_array != NULL) {
        free(ue_array);
    }

    ue_array = malloc(max_ues * sizeof(NFAPI_MESSAGE_PDU_T));
    if (!ue_array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < max_ues; ++i) {
        pthread_mutex_lock(&array_lock);

        NFAPI_MESSAGE_PDU_T* pdu = &ue_array[i];

        pdu->ue_info.rnti = rand() % 65535;
        pdu->ue_info.rx_snr = (rand() % 50) - 10; // Simulate SNR from -10 to +40 dB
        pdu->ue_info.ber = ((double)rand() / RAND_MAX) * 0.01; // Random BER between 0 and 0.01

        pdu->crc_indication_rel8_tag = rand() % 256;
        pdu->snr_indication_rel8_tag = rand() % 256;
        pdu->ber_indication_tag = rand() % 256;

        update_statistics(pdu->ue_info.rx_snr, pdu->ue_info.ber);

        pthread_mutex_unlock(&array_lock);
    }

    num_ues = max_ues;
}

void free_ue_resources() {
    pthread_mutex_lock(&array_lock);

    if (num_ues > MAX_UE_THRESHOLD) {
        size_t new_size = num_ues / 2;

        NFAPI_MESSAGE_PDU_T* temp_array = realloc(ue_array, new_size * sizeof(NFAPI_MESSAGE_PDU_T));
        if (!temp_array) {
            perror("Reallocation failed");
            exit(EXIT_FAILURE);
        }

        ue_array = temp_array;
        num_ues = new_size;
    } else if (num_ues == 0 && ue_array != NULL) {
        free(ue_array);
        ue_array = NULL;
    }

    pthread_mutex_unlock(&array_lock);
}

void log_performance() {
    pthread_mutex_lock(&array_lock);

    printf("Average SNR: %d dB\n", global_stats.average_snr);
    printf("Min SNR: %d dB\n", global_stats.min_snr);
    printf("Max SNR: %d dB\n", global_stats.max_snr);
    printf("Average BER: %.5f\n", global_stats.average_ber);
    printf("Min BER: %.5f\n", global_stats.min_ber);
    printf("Max BER: %.5f\n", global_stats.max_ber);

    pthread_mutex_unlock(&array_lock);
}

int main() {
    size_t max_ues = 100;

    init_and_populate_ue_array(max_ues, update_statistics);
    log_performance();

    free_ue_resources();
    return 0;
}
```

