MemoryPool* create_pool(size_t element_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->element_size = element_size;
    pool->capacity = 10; // Initial capacity
    pool->count = 0;
    pool->elements = malloc(pool->capacity * sizeof(void *));
    return pool;
}

void* pool_alloc(MemoryPool *pool) {
    if (pool->count == pool->capacity) {
        pool->capacity *= 2;
        pool->elements = realloc(pool->elements, pool->capacity * sizeof(void *));
    }
    void *element = malloc(pool->element_size);
    pool->elements[pool->count++] = element;
    return element;
}

void pool_free(MemoryPool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->elements[i]);
    }
    free(pool->elements);
    free(pool);
}

