    array->pool = create_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return array;
}

void add_element(CRC_Indication_Array *array, NFAPI_CRC_INDICATION_PDU_T *element) {
    memcpy(pool_alloc(array->pool), element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    log_operation("Add", array->pool->count - 1);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(CRC_Indication_Array *array, int index) {
    if (index < 0 || index >= (int)array->pool->count) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
    log_operation("Get", index);
    return (NFAPI_CRC_INDICATION_PDU_T*)array->pool->elements[index];
}

