        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        if (count >= capacity) { // Resize array when full
            capacity *= 2;
            sensors = realloc(sensors, capacity * sizeof(Sensor));
            if (!sensors) {
                perror("Memory allocation failed during resize");
                fclose(file);
                return NULL;
            }
        }

        Sensor sensor;
        char buffer[256];
        int fieldsRead = sscanf(line,
                                "%d,%f,%f,%20[^,],%20[^,],%f,%ld,%50[^,],%100[^\n]",
                                &sensor.id, &sensor.humidity, &sensor.pressure,
                                sensor.sensorType, sensor.name, &sensor.accuracy,
                                &sensor.timestamp, sensor.location.city, sensor.location.country);

        if (fieldsRead == 9) { // Check for correct number of fields
            sensors[count++] = sensor;
        } else {
            printf("Error parsing line: %s", line);
        }
    }

    *sensorCount = count; // Set the actual count of loaded sensors

    fclose(file);
    return sensors;
}

void freeSensors(Sensor *sensors) {
    if (sensors) {
        free(sensors);
    }
}

int main() {
    int sensorCount = 0;
    Sensor *sensors = loadSensorsFromFile("sensors.csv", &sensorCount);

    if (!sensors) {
        fprintf(stderr, "Failed to load sensors.\n");
        return EXIT_FAILURE;
    }

    // Use the loaded sensors
    for (int i = 0; i < sensorCount; ++i) {
        printf("Sensor ID: %d, Name: %s\n", sensors[i].id, sensors[i].name);
    }

    freeSensors(sensors); // Clean up allocated memory

    return EXIT_SUCCESS;
}
```

