#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} RXUEInformation;

typedef struct {
    uint8_t CRCFLAG;
} CRCIndicationRel8Tag;

typedef struct {
    RXUEInformation UEInfo;
    CRCIndicationRel8Tag CRCIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    pthread_mutex_t lock;
} CRCArrayManager;

#define PREDEFINED_CONSTANT 0x55

void log_message(const char *level, const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s - %s\n", level, ctime(&now), message);
}

CRCArrayManager* initialize_crc_array(size_t n) {
    CRCArrayManager* manager = (CRCArrayManager*)malloc(sizeof(CRCArrayManager));
    if (!manager) {
        log_message("ERROR", "Failed to allocate memory for CRCArrayManager");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        log_message("ERROR", "Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        free(manager);
        return NULL;
    }

    manager->size = n;
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < n; ++i) {
        manager->array[i].UEInfo.RX_UE_INFORMATION_TAG = rand() % 1000; // Random valid tag
        manager->array[i].UEInfo.RNTI = (uint16_t)(rand() % 65536);    // Random valid RNTI
        manager->array[i].CRCIndication.CRCFLAG = (i ^ PREDEFINED_CONSTANT) & 0xFF;
    }

    pthread_mutex_unlock(&manager->lock);
    log_message("INFO", "Initialized CRC array successfully");
    return manager;
}

void validate_crc_flags(CRCArrayManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        uint8_t expected_flag = (i ^ PREDEFINED_CONSTANT) & 0xFF;
        if (manager->array[i].CRCIndication.CRCFLAG != expected_flag) {
            log_message("WARNING", "CRC flag mismatch at index");
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_element(CRCArrayManager* manager, size_t index, int RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (index >= manager->size) return;

    pthread_mutex_lock(&manager->lock);

    manager->array[index].UEInfo.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    manager->array[index].UEInfo.RNTI = RNTI;

    pthread_mutex_unlock(&manager->lock);
}

void insert_element(CRCArrayManager* manager, size_t index, int RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (index > manager->size) return;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, (manager->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message("ERROR", "Failed to reallocate memory for element insertion");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    memmove(&new_array[index + 1], &new_array[index], (manager->size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_array[index].UEInfo.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_array[index].UEInfo.RNTI = RNTI;
    new_array[index].CRCIndication.CRCFLAG = (index ^ PREDEFINED_CONSTANT) & 0xFF;

    manager->array = new_array;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    log_message("INFO", "Inserted element successfully");
}

void delete_element(CRCArrayManager* manager, size_t index) {
    if (index >= manager->size) return;

    pthread_mutex_lock(&manager->lock);

    memmove(&manager->array[index], &manager->array[index + 1], (manager->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, (manager->size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array && manager->size > 0) {
        log_message("ERROR", "Failed to reallocate memory for element deletion");
    } else {
        manager->array = new_array;
        --manager->size;
        log_message("INFO", "Deleted element successfully");
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_crc_array(CRCArrayManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
    log_message("INFO", "Freed CRC array and manager resources");
}

int main() {
    size_t n = 10;
    CRCArrayManager* manager = initialize_crc_array(n);

    if (manager) {
        validate_crc_flags(manager);
        update_element(manager, 2, 1234, 5678);
        insert_element(manager, 5, 4321, 8765);
        delete_element(manager, 3);
        free_crc_array(manager);
    }

    return 0;
}
