int ue_count = 0;

void log_message(const char *message) {
    if (logger.logging_level > 0) {
        pthread_mutex_lock(&mutex);
        fprintf(logger.log_file, "%s\n", message);
        fflush(logger.log_file);
        pthread_mutex_unlock(&mutex);
    }
}

double calculate_snr() {
    // Simulate SNR calculation with random noise
    double signal_power = 10.0; // Example signal power in dBm
    double noise_power = (rand() % 100) / 100.0 * 2.0; // Random noise factor between 0 and 2
    return signal_power - 10 * log10(noise_power);
}

void initialize_nfa_array(int num_ues) {
    ue_count = num_ues;
    for (int i = 0; i < ue_count; ++i) {
        nfa_array[i] = (NFAPI_MESSAGE_PDU_T *)malloc(sizeof(NFAPI_MESSAGE_PDU_T));
        if (!nfa_array[i]) {
            log_message("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        // Populate structures
        nfa_array[i]->ue_info.RNTI = i + 1; // Example RNTI assignment
        nfa_array[i]->ue_info.SNR_dB = calculate_snr();
        nfa_array[i]->crc_ind.CRC_INDICATION_REL8_TAG = 0x01; // Example tag value
        nfa_array[i]->snr_ind.SNR_INDICATION_REL8_TAG = 0x02; // Example tag value
        nfa_array[i]->snr_ind.SNR_Value = nfa_array[i]->ue_info.SNR_dB;

        log_message("UE initialized");
    }
}

void cleanup_nfa_array() {
    for (int i = 0; i < ue_count; ++i) {
        free(nfa_array[i]);
        log_message("UE memory freed");
    }
}

int main(int argc, char *argv[]) {
