        strncpy(msgs[i].payload, predefined_string, payload_length);
        msgs[i].payload[payload_length] = '\0';
        msgs[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&lock);
    log_timestamp("Finished initializing messages");

    return msgs;
}

void cleanup_resources(NFAPI_CRC_INDICATION_PDU_T *pdu_list, message *msgs) {
    if (pdu_list) free(pdu_list);
