```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define structures for log entries and network events.
typedef struct {
    time_t timestamp;
    int id;
    char status_message[256];
} LOG_ENTRY_T;

typedef struct {
    int event_type;
    int source_id;
    int status_code;
    long sequence_number;
} NETWORK_EVENT_T;

// Global variables for thread safety
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t network_lock = PTHREAD_MUTEX_INITIALIZER;

// Callback function prototype from the logging library.
void external_logging_callback(const char* message);

// Function to initialize and manage dynamic arrays of logs and events.
int init_network_system(int num_log_entries, int num_network_events) {
    // Seed random number generator
    srand(time(NULL));

    LOG_ENTRY_T *log_entries = NULL;
    NETWORK_EVENT_T *network_events = NULL;

    // Allocate memory for log entries
    log_entries = (LOG_ENTRY_T *)malloc(num_log_entries * sizeof(LOG_ENTRY_T));
    if (!log_entries) {
        external_logging_callback("Memory allocation failed for log entries.");
        return -1;
    }

    // Initialize log entries with unique timestamps and identifiers
    pthread_mutex_lock(&log_lock);
    for (int i = 0; i < num_log_entries; ++i) {
        log_entries[i].timestamp = time(NULL) + rand() % 1000; // Unique timestamp
        log_entries[i].id = rand() % 10000 + 1; // Unique ID

        snprintf(log_entries[i].status_message, sizeof(log_entries[i].status_message), 
                 "Log entry #%d initialized.", i);
    }
    pthread_mutex_unlock(&log_lock);

    // Allocate memory for network events
    network_events = (NETWORK_EVENT_T *)malloc(num_network_events * sizeof(NETWORK_EVENT_T));
    if (!network_events) {
        external_logging_callback("Memory allocation failed for network events.");
        free(log_entries);  // Cleanup allocated resources
        return -1;
    }

    // Initialize network events with unique sequence numbers
    pthread_mutex_lock(&network_lock);
    for (int i = 0; i < num_network_events; ++i) {
        network_events[i].event_type = rand() % 10 + 1;  // Event type range from 1 to 10
        network_events[i].source_id = rand() % 10000 + 1; // Unique source ID

        network_events[i].status_code = rand() % 5 + 1;   // Status code range from 1 to 5
        network_events[i].sequence_number = i + 1;       // Unique sequence number
    }
    pthread_mutex_unlock(&network_lock);

    external_logging_callback("Network system initialized successfully.");

    return 0;
}

void free_resources(LOG_ENTRY_T *log_entries, NETWORK_EVENT_T *network_events) {
    if (log_entries) {
        free(log_entries);
    }
    if (network_events) {
        free(network_events);
    }
}
```

