#define INITIAL_POOL_SIZE 1024

typedef struct {
    int integer;
    float floatValue;
    char* string;
    int booleanFlag; // Using int to represent bool for simplicity
} Data;

typedef struct SessionNode {
    pthread_mutex_t lock;
    struct SessionNode *left, *right;
    double *doublesArray;
    char **charKeysArray;
    Data *dataArray;
    int *intCountersArray;
    struct session *sessionPointers;
    size_t arraySize;
} SessionNode;

typedef struct session {
    // Define session-specific metadata fields
    char sessionId[64];
    pthread_mutex_t lock; // Lock for synchronizing updates to this session's data
} session;

// Custom memory pool structure
typedef struct {
    void *pool;
    size_t block_size;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t initial_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = malloc(block_size * initial_size);
    if (!mp->pool) return NULL;

    mp->block_size = block_size;
    mp->current_size = 0;
    mp->max_size = initial_size;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->current_size >= mp->max_size) {
        // Pool exhausted; you might want to resize or handle this
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    void* block = (char*)mp->pool + (mp->block_size * mp->current_size);
    mp->current_size++;
    pthread_mutex_unlock(&mp->lock);

    return block;
}

void deallocate_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to insert a new session into the binary tree
SessionNode* insert_session(SessionNode* root, session* s);

// Initialize data structures and memory pool
SessionNode* initialize_data_structures() {
    MemoryPool *mp = create_memory_pool(sizeof(session), INITIAL_POOL_SIZE);

    // Allocate initial arrays within the custom memory pool for simplicity
    double *doublesArray = (double*)allocate_from_pool(mp);
    char **charKeysArray = (char**)allocate_from_pool(mp);
    Data *dataArray = (Data*)allocate_from_pool(mp);
    int *intCountersArray = (int*)allocate_from_pool(mp);

    // Initialize the root of the binary tree
    SessionNode *root = malloc(sizeof(SessionNode));
    if (!root) {
        deallocate_memory_pool(mp);
        return NULL;
    }

    pthread_mutex_init(&root->lock, NULL);
    root->left = root->right = NULL;
    root->doublesArray = doublesArray;
    root->charKeysArray = charKeysArray;
    root->dataArray = dataArray;
    root->intCountersArray = intCountersArray;
    root->arraySize = INITIAL_POOL_SIZE;

    return root;
}

// Function to update the data arrays with new measurements
void update_data_arrays(SessionNode *root, double new_double, const char* new_key, Data new_data, int new_counter) {
    pthread_mutex_lock(&root->lock);

    // Ensure room in arrays or handle resizing
    if (root->current_size >= root->arraySize) {
        // Handle resizing logic here
    }

    // Insert data atomically
    size_t index = root->current_size;
    root->doublesArray[index] = new_double;
    root->charKeysArray[index] = strdup(new_key); // Duplicate the string for safe storage
    root->dataArray[index] = new_data; // Direct assignment as Data is a POD type
    root->intCountersArray[index] = new_counter;

    root->current_size++;

    pthread_mutex_unlock(&root->lock);
}

// Thread-safe data ingestion service (simplified)
void* data_ingestion_service(void *arg) {
    SessionNode *root = (SessionNode*)arg;
    while (1) { // Infinite loop for periodic updates
        // Simulate fetching new data
        double new_double = 0.0; // Example value, replace with actual logic
        char *new_key = "key";   // Example key, replace with actual logic
        Data new_data = { .integer = 1, .floatValue = 2.0, .string = strdup("data"), .booleanFlag = 1 };
        int new_counter = 3;     // Example counter

        update_data_arrays(root, new_double, new_key, new_data, new_counter);

        sleep(5); // Sleep for a period before the next ingestion
    }

    return NULL;
}

int main() {
    SessionNode *root = initialize_data_structures();
    if (!root) {
        fprintf(stderr, "Failed to initialize data structures.\n");
        return 1;
    }

    pthread_t ingestion_thread;
    pthread_create(&ingestion_thread, NULL, data_ingestion_service, (void*)root);

    // Simulate running
    sleep(20);

    pthread_cancel(ingestion_thread); // Gracefully terminate the thread

    deallocate_memory_pool(root->mp); // Ensure proper cleanup of resources

    return 0;
}
```

### Key Points:

