    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t num_elements) {
    if (num_elements == 0 || num_elements > 1000000) {
        fprintf(stderr, "Invalid number of elements: %zu\n", num_elements);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_elements; ++i) {
        array[i].RX_UE_INFORMATION_TAG = (uint32_t)(rand() % UINT32_MAX + 1); // Avoid zero
        array[i].RNTI = (uint16_t)(rand() % 65536);
        array[i].CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % (MAX_CRC_VALUE + 1));
    }
    pthread_mutex_unlock(&mutex);

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

// Unit tests
#include <assert.h>

void test_allocation_and_population() {
    size_t num_elements = 1000; // Test with a smaller number for speed
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_crc_pdu_array(num_elements);

    assert(array != NULL);
    assert((size_t)(array - (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == 0);

    for (size_t i = 0; i < num_elements; ++i) {
        assert(array[i].RX_UE_INFORMATION_TAG > 0);
        assert(array[i].RNTI < 65536);
        assert(array[i].CRC_INDICATION_REL8_TAG <= MAX_CRC_VALUE);
    }

    free_crc_pdu_array(array);
}

void test_zero_allocation() {
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_crc_pdu_array(0);
    assert(array == NULL);

    array = allocate_crc_pdu_array(1000001); // Test overflow
    assert(array == NULL);
}

int main() {
    test_allocation_and_population();
    test_zero_allocation();

    printf("All tests passed.\n");
    return 0;
}
```

### Explanation:
- **Memory Management**: Uses `malloc` and `free` for dynamic memory management, with checks to ensure allocation success.
- **Thread Safety**: A mutex is used to protect the critical section where random values are assigned.
- **Random Values**: Ensures CRC values are within valid range using modulo operations.
- **Error Handling**: Checks for invalid input sizes and handles allocation failures gracefully.
- **Unit Tests**: Validates memory allocation, population of structures, and edge cases like zero or overflowed element requests.

