} NFAPI_CRC_INDICATION_MANAGER;

unsigned int hash_rnti(unsigned long rnti) {
    return (rnti % 1024);
}

void log_message(int level, const char *message) {
    if (level == LOG_LEVEL_INFO || level == LOG_LEVEL_DEBUG) {
        printf("%s\n", message);
    }
}

NFAPI_CRC_INDICATION_MANAGER* create_manager() {
    NFAPI_CRC_INDICATION_MANAGER *manager = malloc(sizeof(NFAPI_CRC_INDICATION_MANAGER));
    manager->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);
    memset(manager->hash_table, -1, sizeof(manager->hash_table));
    return manager;
}

void resize_array(NFAPI_CRC_INDICATION_MANAGER *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        manager->array = new_array;
        manager->capacity = new_capacity;
    }
}

void add_pdu(NFAPI_CRC_INDICATION_MANAGER *manager, int RX_UE_INFORMATION_TAG, unsigned long RNTI, int CRC_INDICATION_REL8_TAG, time_t max_age) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        resize_array(manager);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->size];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    pdu->timestamp = time(NULL);

    unsigned int index = hash_rnti(RNTI);
    manager->hash_table[index] = (unsigned long)manager->size;

    log_message(LOG_LEVEL_INFO, "Added new PDU");
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
}

void remove_stale_pdus(NFAPI_CRC_INDICATION_MANAGER *manager, time_t current_time, time_t max_age) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[i];
        if (current_time - pdu->timestamp > max_age) {
            unsigned int index = hash_rnti(pdu->RNTI);
            manager->hash_table[index] = -1;

            log_message(LOG_LEVEL_DEBUG, "Removed stale PDU");

            memmove(&manager->array[i], &manager->array[i + 1], (manager->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            manager->size--;
            i--; // Adjust index after removal
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_manager(NFAPI_CRC_INDICATION_MANAGER *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_MANAGER *manager = create_manager();

    // Simulate adding PDUs
    for (int i = 0; i < 20; ++i) {
        add_pdu(manager, i, rand(), rand(), 60);
    }

    // Remove stale PDUs
    remove_stale_pdus(manager, time(NULL), 30);

    destroy_manager(manager);
    return 0;
}
