void filterMetrics(const DeviceMetricData* data, size_t count,
                   ProcessedMetricSet* processedMetrics) {
    for (size_t i = 0; i < count; ++i) {
        if (isValidMetric(data[i].latency)) {
            processedMetrics->latencies = realloc(processedMetrics->latencies, 
                                                  sizeof(double) * (processedMetrics->numLatencies + 1));
            processedMetrics->latencies[processedMetrics->numLatencies++] = data[i].latency;
        }
        if (isValidMetric(data[i].throughput)) {
            processedMetrics->throughputs = realloc(processedMetrics->throughputs, 
                                                    sizeof(double) * (processedMetrics->numThroughputs + 1));
            processedMetrics->throughputs[processedMetrics->numThroughputs++] = data[i].throughput;
        }
        if (isValidMetric(data[i].errorRate)) {
            processedMetrics->errorRates = realloc(processedMetrics->errorRates, 
                                                   sizeof(double) * (processedMetrics->numErrorRates + 1));
            processedMetrics->errorRates[processedMetrics->numErrorRates++] = data[i].errorRate;
        }
    }
}

int sendMetricsToServer(const ProcessedMetricSet* metrics) {
    // Simulate sending metrics to a server
    return rand() % 2; // Randomly simulate success or failure for demonstration purposes
}

void retrySendingWithDelay(int retries, int delaySeconds) {
    while (retries-- > 0) {
        if (sendMetricsToServer(NULL)) { // Assuming NULL is replaced with actual metrics to send
            return;
        }
        sleep(delaySeconds);
    }
}

int processNetworkMetrics(DeviceMetricData* data, size_t count) {
    ProcessedMetricSet processedMetrics = { .latencies = NULL, .numLatencies = 0,
                                            .throughputs = NULL, .numThroughputs = 0,
                                            .errorRates = NULL, .numErrorRates = 0 };

    filterMetrics(data, count, &processedMetrics);

    int success = sendMetricsToServer(&processedMetrics);
    if (!success) {
        retrySendingWithDelay(MAX_RETRIES, RETRY_DELAY_SECONDS);
    }

    free(processedMetrics.latencies);
    free(processedMetrics.throughputs);
    free(processedMetrics.errorRates);

    return success;
}
