#include <stdio.h>
#include <stdlib.h>

#define OFFSET_CAPACITY 10000

typedef struct MAC_FRAME {
    int key;
    long *offset_ptr;
    // Additional payload or checksum fields can be added here in the future.
} MAC_FRAME;

typedef struct Node {
    MAC_FRAME mac_frame;
    struct Node* next;
} Node;

// Function prototypes
long* initialize_offset_array();
Node* create_linked_list(int num_keys, int* keys);
void free_linked_list(Node* head);
int validate_and_insert_unique_key(int* keys, int key_count, int new_key);

int main() {
    // Simulate user input for unique keys
    int num_keys = 5; // Example number of keys provided by the user
    int keys[5] = {1, 2, 3, 4, 65535};

    // Initialize fixed-size offsets array (zero-initialized)
    long* offsets = initialize_offset_array();
    if (!offsets) {
        fprintf(stderr, "Memory allocation for offsets failed.\n");
        return EXIT_FAILURE;
    }

    // Create linked list of MAC frames
    Node* mac_frame_list = create_linked_list(num_keys, keys);
    if (!mac_frame_list) {
        free(offsets);
        fprintf(stderr, "Memory allocation for MAC frames failed.\n");
        return EXIT_FAILURE;
    }

    // Free allocated resources
    free_linked_list(mac_frame_list);
    free(offsets);

    return 0;
}

long* initialize_offset_array() {
    long* offsets = calloc(OFFSET_CAPACITY, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return NULL;
    }
    return offsets;
}

Node* create_linked_list(int num_keys, int* keys) {
    Node* head = NULL;
    Node* current;

    // Validate and prepare keys
    for (int i = 0; i < num_keys; ++i) {
        if (!validate_and_insert_unique_key(keys, i, keys[i])) {
            free_linked_list(head);
            return NULL;
        }
    }

    for (int i = 0; i < num_keys; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation for node failed.\n");
            free_linked_list(head);
            return NULL;
        }

        long* offset_ptr = &offsets[i % OFFSET_CAPACITY]; // Example of handling offsets
        new_node->mac_frame.key = keys[i];
        new_node->mac_frame.offset_ptr = offset_ptr;

        if (!head) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    // Terminate the list
    if (current) {
        current->next = NULL;
    }

    return head;
}

void free_linked_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int validate_and_insert_unique_key(int* keys, int key_count, int new_key) {
    if (new_key < 0 || new_key > 65535) {
        fprintf(stderr, "Key out of range: %d\n", new_key);
        return 0;
    }

    for (int i = 0; i < key_count; ++i) {
        if (keys[i] == new_key) {
            fprintf(stderr, "Duplicate key found: %d\n", new_key);
            return 0;
        }
    }

    return 1;
}
```

### Explanation:
- **Offset Array**: A zero-initialized array of `long` integers is created using `calloc`, ensuring all elements start at zero.
- **Linked List**: A linked list is used for managing MAC frames, allowing dynamic insertion and traversal. Each node stores a unique key, an offset pointer, and can be extended to include more fields as needed.
- **Memory Management**: Careful handling of memory allocation failures ensures graceful error management without system crashes.
- **Validation**: The keys are validated for uniqueness and range before being added to the linked list.
- **Scalability Considerations**: This design balances dynamic memory usage with efficient access patterns, suitable for varying load scenarios.']

