```csharp
using System;

public class DynamicValueGenerator {
    private Random _random;

    public DynamicValueGenerator(int seed = 0) {
        _random = new Random(seed);
    }

    public double GenerateRandomDouble(double min, double max, bool inclusiveUpper) {
        return inclusiveUpper ? (min + _random.NextDouble() * (max - min)) : (min + _random.NextDouble() * (max - min - 1.0));
    }

    public int GenerateRandomInt(int min, int max, bool inclusiveUpper) {
        if (inclusiveUpper)
            return _random.Next(min, max + 1);
        else
            return _random.Next(min, max);
    }

    public void ShuffleArray(int[] array) {
        for (int i = array.Length - 1; i > 0; i--) {
            int j = _random.Next(i + 1);
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }

    public override string ToString() {
        return $"DynamicValueGenerator with seed {_random.GetHashCode()}";
    }
}
