#define INITIAL_CAPACITY 16

typedef struct {
    int socket_descriptor;
    char local_address[INET6_ADDRSTRLEN];
    char remote_address[INET6_ADDRSTRLEN];
} TCP_CONNECTION_RECORD;

typedef struct {
    TCP_CONNECTION_RECORD *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    double timeout_seconds; // Timeout in seconds for removing inactive connections
} DynamicArray;

// Initialize the dynamic array
int init_dynamic_array(DynamicArray *array, double timeout) {
    if (!array) return -1;
    array->records = (TCP_CONNECTION_RECORD *)malloc(INITIAL_CAPACITY * sizeof(TCP_CONNECTION_RECORD));
    if (!array->records) return -1;
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&array->lock, NULL);
    array->timeout_seconds = timeout;
    return 0;
}

// Resize the dynamic array
static int resize_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    TCP_CONNECTION_RECORD *new_records = (TCP_CONNECTION_RECORD *)realloc(array->records, new_capacity * sizeof(TCP_CONNECTION_RECORD));
    if (!new_records) return -1;
    array->records = new_records;
    array->capacity = new_capacity;
    return 0;
}

// Add a new connection
int add_connection(DynamicArray *array, int socket_descriptor, const char *local_address, const char *remote_address) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity && resize_array(array)) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    TCP_CONNECTION_RECORD new_record = {socket_descriptor, "", ""};
    strncpy(new_record.local_address, local_address, INET6_ADDRSTRLEN - 1);
    strncpy(new_record.remote_address, remote_address, INET6_ADDRSTRLEN - 1);

    array->records[array->count++] = new_record;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Remove inactive connections
int remove_inactive_connections(DynamicArray *array) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count;) {
        // Assume a function `is_connection_active` that checks if the connection is still active
        int active = is_connection_active(array->records[i].socket_descriptor);

        if (!active && difftime(current_time, get_last_activity_time(array->records[i].socket_descriptor)) > array->timeout_seconds) {
            memmove(&array->records[i], &array->records[i + 1],
                    (array->count - i - 1) * sizeof(TCP_CONNECTION_RECORD));
            array->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Update timeout period dynamically
void update_timeout(DynamicArray *array, double new_timeout) {
    if (new_timeout <= 0) return;

    pthread_mutex_lock(&array->lock);
    array->timeout_seconds = new_timeout;
    pthread_mutex_unlock(&array->lock);
}

// Destroy the dynamic array
void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;

    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

// Placeholder functions for external dependencies
int is_connection_active(int socket_descriptor) {
    // Implement actual check here
    return 1; // Assume all connections are active for now
}

time_t get_last_activity_time(int socket_descriptor) {
    // Retrieve the last activity time for this connection
    return time(NULL); // Placeholder: return current time as last activity
}
