#define MAX_CONNECTIONS 1000

typedef struct {
    int socket_descriptor;
    char local_address[INET6_ADDRSTRLEN];
    char remote_address[INET6_ADDRSTRLEN];
} TCP_CONNECTION_RECORD;

typedef struct Node {
    TCP_CONNECTION_RECORD record;
    time_t last_active_time;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int max_size;
    time_t timeout_period;
} ConnectionManager;

ConnectionManager* create_connection_manager(int max_size, time_t timeout) {
    ConnectionManager* manager = malloc(sizeof(ConnectionManager));
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_size = max_size;
    manager->timeout_period = timeout;
    return manager;
}

void destroy_connection_manager(ConnectionManager* manager) {
    Node* current = manager->head;
    while (current != NULL) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_connection(ConnectionManager* manager, TCP_CONNECTION_RECORD record) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);

    if (manager->head == NULL || manager->max_size <= 0) {
        Node* new_node = malloc(sizeof(Node));
        new_node->record = record;
        new_node->last_active_time = now;
        new_node->next = manager->head;
        manager->head = new_node;
        pthread_mutex_unlock(&manager->lock);
        return 1;
    }

    // Check for existing socket descriptor
    Node* current = manager->head;
    while (current != NULL) {
        if (current->record.socket_descriptor == record.socket_descriptor) {
            current->last_active_time = now;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Already exists
        }
        current = current->next;
    }

    // Add new connection
    Node* new_node = malloc(sizeof(Node));
    new_node->record = record;
    new_node->last_active_time = now;
    new_node->next = manager->head;
    manager->head = new_node;

    // Remove inactive connections if necessary
    current = manager->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (now - current->last_active_time > manager->timeout_period) {
            Node* to_delete = current;
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 1;
}

void remove_inactive_connections(ConnectionManager* manager) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (now - current->last_active_time > manager->timeout_period) {
            Node* to_delete = current;
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(to_delete);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_connection_activity(ConnectionManager* manager, int socket_descriptor) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current != NULL) {
        if (current->record.socket_descriptor == socket_descriptor) {
            current->last_active_time = now;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

