#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jansson.h>

#define MAX_RECORDS 10000000

typedef struct {
    char identifier[32];
    double reading;
    time_t timestamp;
} SensorRecord;

int validate_record(const SensorRecord *record) {
    if (strlen(record->identifier) == 0 || record->reading <= 0.0)
        return 0; // Invalid
    return 1; // Valid
}

void serialize_records(SensorRecord **records, size_t count, char ***json_output, size_t *json_size) {
    json_t *root = json_array();

    for (size_t i = 0; i < count; ++i) {
        if (!validate_record(records[i])) continue;

        json_t *obj = json_object();

        json_object_set_new(obj, "identifier", json_string(records[i]->identifier));
        json_object_set_new(obj, "reading", json_real(records[i]->reading));
        json_object_set_new(obj, "timestamp", json_integer((int)records[i]->timestamp));

        json_array_append_new(root, obj);
    }

    char *json_str = json_dumps(root, JSON_COMPACT | JSON_ENSURE_ASCII);
    size_t str_size = strlen(json_str);

    *json_output = malloc(str_size + 1);
    strcpy(*json_output, json_str);
    *json_size = str_size;

    free(json_str);
    json_decref(root);
}

void read_log_file(const char *filename, SensorRecord ***records, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    rewind(file);

    char *data = malloc(fsize + 1);
    fread(data, 1, fsize, file);
    data[fsize] = '\0';

    char *token = strtok(data, "\n");
    *records = malloc(MAX_RECORDS * sizeof(SensorRecord*));
    *count = 0;

    while (token) {
        if (*count >= MAX_RECORDS) break;

        SensorRecord *record = malloc(sizeof(SensorRecord));

        sscanf(token, "%31s %lf %ld", record->identifier, &record->reading, &record->timestamp);
        if (validate_record(record)) {
            (*records)[*count] = record;
            ++(*count);
        } else {
            free(record);
        }

        token = strtok(NULL, "\n");
    }

    fclose(file);
    free(data);
}

void *archive_data(void *args) {
    // Placeholder for database archiving logic
    return NULL;
}

void process_sensor_data(const char *filename) {
    SensorRecord **records;
    size_t count;

    read_log_file(filename, &records, &count);

    char *json_output;
    size_t json_size;

    serialize_records(records, count, &json_output, &json_size);

    // Example of usage with a third-party analytics tool
    printf("%s\n", json_output);

    for (size_t i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(records);
    free(json_output);

    pthread_t archive_thread;
    pthread_create(&archive_thread, NULL, archive_data, NULL);
    pthread_join(archive_thread, NULL);
}
