#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Define USER_SESSION_RECORD structure
typedef struct {
    int user_id;
    time_t start_time;
    time_t last_activity;
    int status; // 0: inactive, 1: active
} USER_SESSION_RECORD;

// Define the dynamic array for session records
typedef struct {
    USER_SESSION_RECORD *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

// Function to initialize the session manager
void initSessionManager(SessionManager *manager, size_t initial_capacity) {
    manager->sessions = (USER_SESSION_RECORD *)malloc(initial_capacity * sizeof(USER_SESSION_RECORD));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to add a new session
void addSession(SessionManager *manager, int user_id) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->sessions = (USER_SESSION_RECORD *)realloc(manager->sessions, new_capacity * sizeof(USER_SESSION_RECORD));
        manager->capacity = new_capacity;
    }

    USER_SESSION_RECORD new_session = {user_id, time(NULL), time(NULL), 1};
    manager->sessions[manager->count++] = new_session;

    pthread_mutex_unlock(&manager->lock);
}

// Function to expire inactive sessions
void expireSessions(SessionManager *manager, time_t inactivity_threshold) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if (now - manager->sessions[i].last_activity > inactivity_threshold && manager->sessions[i].status == 1) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(USER_SESSION_RECORD));
            manager->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to update session activity
void updateSessionActivity(SessionManager *manager, int user_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; i++) {
        if (manager->sessions[i].user_id == user_id && manager->sessions[i].status == 1) {
            manager->sessions[i].last_activity = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to report session usage statistics
void reportSessionUsage(SessionManager *manager, void (*report)(int active_sessions, double average_duration)) {
    pthread_mutex_lock(&manager->lock);

    int active_sessions = 0;
    time_t total_duration = 0;

    for (size_t i = 0; i < manager->count; i++) {
        if (manager->sessions[i].status == 1) {
            active_sessions++;
            total_duration += difftime(time(NULL), manager->sessions[i].start_time);
        }
    }

    double average_duration = active_sessions ? total_duration / (double)active_sessions : 0.0;

    report(active_sessions, average_duration);

    pthread_mutex_unlock(&manager->lock);
}

// Function to clean up resources
void cleanupSessionManager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage of the session manager
void exampleUsage() {
    SessionManager manager;
    initSessionManager(&manager, 10);

    // Add sessions
    addSession(&manager, 1);
    addSession(&manager, 2);

    // Simulate activity update
    sleep(1);
    updateSessionActivity(&manager, 1);

    // Expire inactive sessions
    expireSessions(&manager, 60); // Inactivity threshold of 60 seconds

    // Report usage statistics
    reportSessionUsage(&manager, [](int active_sessions, double average_duration) {
        printf("Active Sessions: %d\n", active_sessions);
        printf("Average Session Duration: %.2f seconds\n", average_duration);
    });

    cleanupSessionManager(&manager);
}

int main() {
    exampleUsage();
    return 0;
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex_t` for thread-safe operations.
- **Dynamic Array Management**: Handles resizing of the session array as needed.
- **Session Expiry**: Checks and removes inactive sessions based on a threshold.
- **Reporting**: Reports active sessions and average duration using a callback function.
- **Resource Cleanup**: Ensures resources are freed properly.

This implementation is designed to be efficient, scalable, and maintainable while handling concurrent access and integrating with an external service for reporting.']

