    if (!array) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    srand(time(NULL)); // Seed for randomness.

    pthread_t threads[4];
    int chunk_size = N / 4;

    for (int i = 0; i < 4; ++i) {
        int start_index = i * chunk_size;
        int end_index = (i == 3) ? N : start_index + chunk_size;

        pthread_create(&threads[i], NULL, ^void*(void* arg) {
            int start = *(int*)arg;

            for (int j = start; j < end_index; ++j) {
                UE_INFORMATION *ue_info_ptr = &array[j].ue_info;
                ue_info_ptr->RX_UE_INFORMATION_TAG = rand() % 1000; // Mock data
                ue_info_ptr->RNTI = rand() % 500; // Mock data

                array[j].crc_tag.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
            }
        }, &start_index);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (!validate_structures(array, N)) {
        log_error("Validation failed: Invalid structures detected.");
        free_nfa_pi_crc_indication_pdu(array, N);
        return NULL;
    }

    // Logging resource usage (mock)
    printf("Successfully allocated %d entries.\n", N);

    return array;
}

void free_nfa_pi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    if (array) {
        free(array);
    }
}

int validate_structures(const NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    for (int i = 0; i < count; ++i) {
        if (array[i].ue_info.RX_UE_INFORMATION_TAG <= 0 || 
