        free(node);
        pthread_mutex_unlock(&queue->lock);
    }
}

int add_record_to_queue(RequestQueue* queue, const Record* record) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new queue node\n");
        return -1;
    }

    memcpy(&newNode->record, record, sizeof(Record));
    newNode->next = NULL;

    pthread_mutex_lock(&queue->lock);
    newNode->next = queue->head;
    queue->head = newNode;
    pthread_mutex_unlock(&queue->lock);

    return 0;
}

void setup_and_run_system(int numRecords) {
    if (numRecords > MAX_RECORDS) {
        fprintf(stderr, "Input exceeds predefined limit\n");
