        pduArray[i].CRCFLAG = (probability < CRC_FLAG_PROBABILITY) ? 1 : 0;
    }

    // Serialize and write data to file
    serialize_and_write_data(pduArray, numRecords);

    RequestQueue queue = { .head = NULL };
    pthread_mutex_init(&queue.lock, NULL);
    pthread_t workerThread;
    if (pthread_create(&workerThread, NULL, process_queue, &queue) != 0) {
        perror("Failed to create worker thread");
        exit(EXIT_FAILURE);
    }

