    double prob_sum = 0.0;
    srand(time(NULL));
    time_t current_time = time(NULL);

    for (int i = 0; i < key_size; ++i) {
        keys[i] = rand() % 100; // Random value within range
        status_flags[i] = rand() % 2; // Random status flag
    }

    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % 10000;
        offset_sum += offsets[i];
        records[i].timestamp = current_time + i; // Current time + index
    }

    if (offset_sum > MAX_OFFSET_SUM) {
        snprintf(error_buffer, BUFFER_SIZE, "Offset sum exceeds maximum limit.");
        free(offsets); free(keys); free(records); free(status_flags); free(timestamps); free(probabilities);
        return NULL;
    }

    for (int i = 0; i < prob_size; ++i) {
        probabilities[i] = ((double)rand() / RAND_MAX) * 100.0; // Random probability between 0 and 100
        prob_sum += probabilities[i];
    }

    if ((prob_sum / prob_size) < 50.0) {
        snprintf(error_buffer, BUFFER_SIZE, "Average probability is less than 50%.");
        free(offsets); free(keys); free(records); free(status_flags); free(timestamps); free(probabilities);
        return NULL;
    }

    // Set records values
    for (int i = 0; i < offset_size; ++i) {
        records[i].value = rand() % 100; // Random value within range
        records[i].status_flag = status_flags[i % key_size];
        records[i].timestamp = timestamps[i];
        records[i].probability = probabilities[i % prob_size];
    }

    // Return pointer to a struct containing all pointers (for demonstration)
    typedef struct {
        long* offsets;
        int* keys;
        record* records;
        short* status_flags;
        uint64_t* timestamps;
        double* probabilities;
    } data_structures;

    data_structures *data = malloc(sizeof(data_structures));
    if (!data) {
        snprintf(error_buffer, BUFFER_SIZE, "Memory allocation failed for data struct.");
        free(offsets); free(keys); free(records); free(status_flags); free(timestamps); free(probabilities);
        return NULL;
    }

    data->offsets = offsets;
    data->keys = keys;
    data->records = records;
    data->status_flags = status_flags;
    data->timestamps = timestamps;
    data->probabilities = probabilities;

    return (void*)data;
}
```

This code defines a function `initialize_data_structures` that performs dynamic memory allocation and initialization of various arrays based on the given constraints. It handles error reporting through a thread-local buffer, ensuring thread safety when multiple threads call this function concurrently. The solution uses standard library functions for memory management and incorporates checks for size validation and resource cleanup in case of errors.']

