#include <iostream>
#include <unordered_map>
#include <vector>
#include <random>
#include <mutex>
#include <memory>
#include <atomic>

class SensorCacheManager {
public:
    struct SensorReading {
        uint64_t timestamp;
        int sensorID;
        double temperature;

        SensorReading(uint64_t ts, int id, double temp) 
            : timestamp(ts), sensorID(id), temperature(temp) {}
    };

private:
    static std::mt19937 rng;
    static std::unordered_map<int, SensorCacheManager*> instances;
    std::mutex mtx;
    std::vector<SensorReading> readings;
    size_t capacity;
    std::atomic<bool> memoryFull;

    // Memory pool simulation
    struct MemoryPool {
        std::unique_ptr<char[]> pool;
        size_t size;

        MemoryPool(size_t sz) : size(sz), pool(std::make_unique<char[]>(sz)) {}

        void* allocate(size_t bytes) {
            if (bytes > size) return nullptr;
            // Simple first-fit allocation
            static size_t offset = 0;
            if (offset + bytes <= size) {
                void* ptr = pool.get() + offset;
                offset += bytes;
                return ptr;
            }
            return nullptr; // Out of memory
        }

        void deallocate(void* ptr, size_t) { /* No-op for simplicity */ }
    };

    MemoryPool memoryPool;

    static uint64_t generateUniqueTimestamp(uint64_t min, uint64_t max) {
        std::uniform_int_distribution<uint64_t> dist(min, max);
        while (true) {
            uint64_t ts = dist(rng);
            // Ensure uniqueness using a simple strategy
            if (!instances.count(ts)) { // This is naive for illustration; use actual storage in real code.
                instances[ts] = nullptr;
                return ts;
            }
        }
    }

public:
    SensorCacheManager(size_t cap) 
        : capacity(cap), memoryFull(false), memoryPool(1024 * 1024) {} // 1 MB pool

    ~SensorCacheManager() {
        readings.clear();
        instances.clear();
    }

    bool addReading(int sensorID, double temperature, uint64_t minTimestamp, uint64_t maxTimestamp) {
        std::lock_guard<std::mutex> lock(mtx);

        if (memoryFull || readings.size() >= capacity) {
            return false;
        }

        uint64_t timestamp = generateUniqueTimestamp(minTimestamp, maxTimestamp);
        SensorReading reading(timestamp, sensorID, temperature);
        readings.push_back(reading);

        // Calculate SNR and other processing
        double snr = calculateSNR();

        std::cout << "Added Reading: SensorID=" << sensorID 
                  << ", Temp=" << temperature 
                  << ", Timestamp=" << timestamp 
                  << ", SNR=" << snr << "\n";

        return true;
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mtx);
        readings.clear();
        instances.clear();
        memoryFull = false;
    }

private:
    double calculateSNR() {
        // Simulate signal-to-noise ratio calculation
        static std::normal_distribution<double> noise(0.0, 1.0); // mean=0, stddev=1
        return 20 * log10((1 + noise(rng)) / (noise(rng)));
    }
};

// Static member initialization
std::mt19937 SensorCacheManager::rng(std::random_device{}());
std::unordered_map<int, SensorCacheManager*> SensorCacheManager::instances;

int main() {
    SensorCacheManager manager(1000);
    for (int i = 0; i < 10; ++i) {
        if (!manager.addReading(i, 25.5 + i, 1633024800, 1640995200)) { // Sample timestamps
            std::cerr << "Failed to add reading\n";
        }
    }

    manager.clear();
    return 0;
}
```

