['```rust
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use rand::Rng;
use signal_processing_lib::advanced_filter; // Assume this is the external library
use log::{info, warn};

struct ChannelData {
    snr: f64,
    metadata: String,
}

impl ChannelData {
    fn new(snr: f64, metadata: &str) -> Self {
        Self { 
            snr, 
            metadata: metadata.to_string(), 
        }
    }

    fn apply_filter(&mut self, noise_factor: f64) {
        let filtered_snr = advanced_filter(self.snr + noise_factor);
        self.snr = filtered_snr;
    }
}

struct MetadataPool {
    pool: Vec<String>,
}

impl MetadataPool {
    fn new(size: usize) -> Self {
        Self { 
            pool: vec![String::new(); size],
        }
    }

    fn acquire(&mut self) -> String {
        if let Some(mut metadata) = self.pool.pop() {
            metadata.clear();
            metadata
        } else {
            String::new()
        }
    }

    fn release(&mut self, metadata: String) {
        self.pool.push(metadata);
    }
}

fn process_and_store_channel_data(
    channels: &mut Vec<ChannelData>,
    metadata_pool: &mut MetadataPool,
    dir_name: &str,
    log_enabled: bool,
) -> Result<(), Box<dyn std::error::Error>> {

    // Configure directory and environment variable
    let env_var = "CHANNEL_DATA_DIR";
    let mut data_dir = match env::var(env_var) {
        Ok(path) => PathBuf::from(path),
        Err(_) => {
            fs::create_dir_all(dir_name)?;
            env::set_var(env_var, dir_name.to_string_lossy().into_owned());
            PathBuf::from(dir_name)
        }
    };

    // Simulate random noise factor
    let mut rng = rand::thread_rng();

    for channel in channels.iter_mut() {
        let noise_factor: f64 = rng.gen_range(-0.1..0.1);

        // Apply advanced filter from the external library
        channel.apply_filter(noise_factor);

        if log_enabled {
            info!("Processed SNR: {:.2} with noise factor: {}", channel.snr, noise_factor);
        }
    }

    Ok(())
}

fn main() {
    env::set_var("RUST_LOG", "info");

    let mut channels = vec![
        ChannelData::new(10.0, "Initial Data 1"),
        ChannelData::new(15.5, "Initial Data 2"),
    ];

    let mut metadata_pool = MetadataPool::new(100);

    if let Err(e) = process_and_store_channel_data(&mut channels, &mut metadata_pool, "data_directory", true) {
        warn!("Error processing channel data: {:?}", e);
    }
}
```

